	function Library:MakeDraggable(Instance, Cutoff)
		Instance.Active = true
		local dragging = false
		local dragStartMouse = Vector2.zero
		local dragStartPos = UDim2.new()
		local placeholder = nil

		Instance.InputBegan:Connect(function(Input)
			if Input.UserInputType == Enum.UserInputType.MouseButton1 then
				local relY = Mouse.Y - Instance.AbsolutePosition.Y
				if relY > (Cutoff or 40) then return end
				if Library.SliderDragging then return end

				dragStartMouse = Vector2.new(Mouse.X, Mouse.Y)
				dragStartPos = Instance.Position
				dragging = true
			end
		end)

		Instance.InputEnded:Connect(function(Input)
			if Input.UserInputType == Enum.UserInputType.MouseButton1 then
				dragging = false
				if placeholder then
					Instance.Position = placeholder.Position
					placeholder:Destroy()
					placeholder = nil
				end
				Instance.Visible = true
			end
		end)

		InputService.InputChanged:Connect(function(Input)
			if dragging and not Library.SliderDragging and Input.UserInputType == Enum.UserInputType.MouseMovement then
				-- Start the drag on the very first mouse movement (no time gate) so it feels instant.
				if not placeholder then
					placeholder = newInstance("Frame")
					placeholder.Name = "DragPlaceholder"
					placeholder.Parent = Instance.Parent
					placeholder.Size = Instance.Size
					placeholder.AnchorPoint = Instance.AnchorPoint
					placeholder.Position = dragStartPos
					placeholder.BorderSizePixel = 0
					placeholder.ZIndex = Instance.ZIndex + 1
					pcall(function() placeholder.BackgroundColor3 = Instance.BackgroundColor3 end)
					placeholder.BackgroundTransparency = 0.6

					-- copy only the cheap style objects so it looks the same (rounded corners, stroke, scale)
					for _, child in pairs(Instance:GetChildren()) do
						if child:IsA("UICorner") or child:IsA("UIStroke") or child:IsA("UIScale") then
							local ok, clone = pcall(function() return child:Clone() end)
							if ok and clone then clone.Parent = placeholder end
						end
					end

					Instance.Visible = false
				end

				local delta = Vector2.new(Mouse.X - dragStartMouse.X, Mouse.Y - dragStartMouse.Y)
				placeholder.Position = UDim2.new(
					dragStartPos.X.Scale, dragStartPos.X.Offset + delta.X,
					dragStartPos.Y.Scale, dragStartPos.Y.Offset + delta.Y
				)
			end
		end)
	end
	function Library:AddToolTip(InfoStr, HoverInstance)
		-- No manual measuring: the frame auto-sizes to the label, and the label auto-sizes to its text (capped at MaxWidth, where it wraps), so the box always fits exactly.
		local Tooltip = Library:Create("Frame", {
			BackgroundColor3 = Library.MainColor,
			BorderColor3 = Library.OutlineColor,
			AutomaticSize = Enum.AutomaticSize.XY,
			Size = UDim2.fromOffset(0, 0),
			ZIndex = 100,
			Parent = Library.ScreenGui,
			Visible = false,
		})
		Library:Create("UIPadding", {
			PaddingLeft = UDim.new(0, 4),
			PaddingRight = UDim.new(0, 4),
			PaddingTop = UDim.new(0, 2),
			PaddingBottom = UDim.new(0, 2),
			Parent = Tooltip,
		})
		-- Single line, no wrap: the label sizes to the full text so the box ends exactly at it.
		local Label = Library:CreateLabel({
			AutomaticSize = Enum.AutomaticSize.XY,
			Size = UDim2.fromOffset(0, 0),
			TextSize = 14,
			Text = InfoStr,
			TextColor3 = Library.FontColor,
			TextWrapped = false,
			TextXAlignment = Enum.TextXAlignment.Left,
			ZIndex = Tooltip.ZIndex + 1,
			Parent = Tooltip,
		})
		Library:AddToRegistry(Tooltip, {
			BackgroundColor3 = "MainColor",
			BorderColor3 = "OutlineColor",
		})
		Library:AddToRegistry(Label, {
			TextColor3 = "FontColor",
		})
		Tooltips[#Tooltips + 1] = Tooltip
		local IsHovering = false
		HoverInstance.MouseEnter:Connect(function()
			if Library:MouseIsOverOpenedFrame() then
				return
			end
			IsHovering = true
			Tooltip.Position = UDim2.fromOffset(Mouse.X + 15, Mouse.Y + 12)
			Tooltip.Visible = true
			while IsHovering do
				RunService.Heartbeat:Wait()
				Tooltip.Position = UDim2.fromOffset(Mouse.X + 15, Mouse.Y + 12)
			end
		end)
		HoverInstance.MouseLeave:Connect(function()
			IsHovering = false
			Tooltip.Visible = false
		end)
	end
	function Library:OnHighlight(HighlightInstance, Instance, Properties, PropertiesDefault)
		HighlightInstance.MouseEnter:Connect(function()
			local Reg = Library.RegistryMap[Instance]
			for Property, ColorIdx in next, Properties do
				Instance[Property] = Library[ColorIdx] or ColorIdx
				if Reg and Reg.Properties[Property] then
					Reg.Properties[Property] = ColorIdx
				end
			end
		end)
		HighlightInstance.MouseLeave:Connect(function()
			local Reg = Library.RegistryMap[Instance]
			for Property, ColorIdx in next, PropertiesDefault do
				Instance[Property] = Library[ColorIdx] or ColorIdx
				if Reg and Reg.Properties[Property] then
					Reg.Properties[Property] = ColorIdx
				end
			end
		end)
	end
	function Library:MouseIsOverOpenedFrame()
		for Frame, _ in next, Library.OpenedFrames do
			local AbsPos, AbsSize = Frame.AbsolutePosition, Frame.AbsoluteSize
			if
				Mouse.X >= AbsPos.X
				and Mouse.X <= AbsPos.X + AbsSize.X
				and Mouse.Y >= AbsPos.Y
				and Mouse.Y <= AbsPos.Y + AbsSize.Y
			then
				return true
			end
		end
	end
	function Library:IsMouseOverFrame(Frame)
		local AbsPos, AbsSize = Frame.AbsolutePosition, Frame.AbsoluteSize
		if
			Mouse.X >= AbsPos.X
			and Mouse.X <= AbsPos.X + AbsSize.X
			and Mouse.Y >= AbsPos.Y
			and Mouse.Y <= AbsPos.Y + AbsSize.Y
		then
			return true
		end
	end
	function Library:UpdateDependencyBoxes()
		for _, Depbox in next, Library.DependencyBoxes do
			Depbox:Update()
		end
	end
	function Library:MapValue(Value, MinA, MaxA, MinB, MaxB)
		return (1 - ((Value - MinA) / (MaxA - MinA))) * MinB + ((Value - MinA) / (MaxA - MinA)) * MaxB
	end
	function Library:GetTextBounds(Text, Font, Size, Resolution)
		local Bounds = TextService:GetTextSize(Text, Size, "RobotoMono", Resolution or Vector2.new(1920, 1080))
		return Bounds.X, Bounds.Y
	end
	function Library:GetDarkerColor(Color)
		local H, S, V = Color3.toHSV(Color)
		return Color3.fromHSV(H, S, V / 1.5)
	end
	Library.AccentColorDark = Library:GetDarkerColor(Library.AccentColor)
	function Library:AddToRegistry(Instance, Properties, IsHud)
		local Idx = #Library.Registry + 1
		local Data = {
			Instance = Instance,
			Properties = Properties,
			Idx = Idx,
		}
		table.insert(Library.Registry, Data)
		Library.RegistryMap[Instance] = Data
		if IsHud then
			table.insert(Library.HudRegistry, Data)
		end
	end
	function Library:RemoveFromRegistry(Instance)
		local Data = Library.RegistryMap[Instance]
		if Data then
			for Idx = #Library.Registry, 1, -1 do
				if Library.Registry[Idx] == Data then
					table.remove(Library.Registry, Idx)
				end
			end
			for Idx = #Library.HudRegistry, 1, -1 do
				if Library.HudRegistry[Idx] == Data then
					table.remove(Library.HudRegistry, Idx)
				end
			end
			Library.RegistryMap[Instance] = nil
		end
	end
	function Library:UpdateColorsUsingRegistry()
		for Idx, Object in next, Library.Registry do
			for Property, ColorIdx in next, Object.Properties do
				if type(ColorIdx) == "string" then
					Object.Instance[Property] = Library[ColorIdx]
				elseif type(ColorIdx) == "function" then
					Object.Instance[Property] = ColorIdx()
				end
			end
		end
		-- After a theme swap repaints the registry, re-apply panel effects that layer on top of the base colours (the accent border tint).
		if Library.UpdatePanelStrokes then
			Library:UpdatePanelStrokes()
		end
	end
	-- Panel accent gradient (the accent -> transparent hairline on every groupbox / tabbox).
	function Library:UpdatePanelAccents()
		local accents = Library.PanelAccents
		if not accents then
			return
		end
		local enabled = false
		if Toggles and Toggles.AccentHairline then
			enabled = Toggles.AccentHairline.Value
		end
		local opacity = 1
		if Options and Options.AccentHairlineOpacity then
			opacity = (tonumber(Options.AccentHairlineOpacity.Value) or 100) / 100
		end
		local thickness = 2
		if Options and Options.AccentHairlineThickness then
			thickness = tonumber(Options.AccentHairlineThickness.Value) or 2
		end
		for _, Frame in next, accents do
			if Frame and Frame.Parent then
				Frame.Visible = enabled
				Frame.BackgroundTransparency = 1 - opacity
				Frame.Size = UDim2.new(1, 0, 0, thickness)
			end
		end
	end
	-- ── UI gradient system ──────────────────────────────────────────────────── One top-lit gradient language shared by every surface.
	Library.UIGradientStrength = 0
	Library.UIGradients = {}
	function Library:SurfaceSequence()
		-- A UIGradient MULTIPLIES the frame's own colour, so the neutral gradient must be WHITE - NOT the base colour, which squares it and darkens the surface.
		local intensity = Library.UIGradientStrength or 0
		if intensity <= 0 then
			return ColorSequence.new(Color3.new(1, 1, 1))
		end
		local dark = math.clamp(1 - intensity, 0, 1)
		return ColorSequence.new({
			ColorSequenceKeypoint.new(0, Color3.new(1, 1, 1)),
			ColorSequenceKeypoint.new(1, Color3.new(dark, dark, dark)),
		})
	end
	-- Track a gradient so the single UI Gradient control can drive it.
	function Library:RegisterUIGradient(Gradient, ColorKey)
		Library.UIGradients = Library.UIGradients or {}
		table.insert(Library.UIGradients, { Gradient = Gradient, Key = ColorKey or "MainColor" })
	end
	-- Apply the UI Gradient toggle + strength across every registered surface.
	function Library:UpdateUIGradients()
		local enabled = true
		if Toggles and Toggles.UIGradient then
			enabled = Toggles.UIGradient.Value
		end
		local strength = 0
		if enabled and Options and Options.GradientStrength then
			strength = ((tonumber(Options.GradientStrength.Value) or 0) / 100) * 0.55
		end
		Library.UIGradientStrength = strength
		local list = Library.UIGradients
		if not list then
			return
		end
		for _, Entry in next, list do
			if Entry.Gradient and Entry.Gradient.Parent then
				Entry.Gradient.Color = Library:SurfaceSequence(Library[Entry.Key])
			end
		end
	end
	-- ── Panel accent border ─────────────────────────────────────────────────── Collected panel outline strokes.
	Library.PanelStrokes = {}
	function Library:RegisterPanelStroke(Stroke)
		Library.PanelStrokes = Library.PanelStrokes or {}
		table.insert(Library.PanelStrokes, Stroke)
		return Stroke
	end
	function Library:PanelStrokeAmount()
		if Toggles and Toggles.AccentBorder and Toggles.AccentBorder.Value and Options and Options.AccentBorderAmount then
			return (tonumber(Options.AccentBorderAmount.Value) or 0) / 100
		end
		return 0
	end
	function Library:UpdatePanelStrokes()
		local color = Library.OutlineColor:Lerp(Library.AccentColor, Library:PanelStrokeAmount())
		local list = Library.PanelStrokes
		if not list then
			return
		end
		for _, Stroke in next, list do
			if Stroke and Stroke.Parent then
				Stroke.Color = color
			end
		end
	end
	function Library:GiveSignal(Signal)
		table.insert(Library.Signals, Signal)
	end
	function Library:Unload()
		for Idx = #Library.Signals, 1, -1 do
			local Connection = table.remove(Library.Signals, Idx)
			Connection:Disconnect()
		end
		if Library.OnUnload then
			Library.OnUnload()
		end
		-- Clear the already-loaded flag so a deliberate reload after an explicit Unload() call is still allowed.
		getgenv().__MiraLoaded = nil
		ScreenGui:Destroy()
	end

	function Library:OnUnload(Callback)
		Library.OnUnload = Callback
	end
	Library:GiveSignal(ScreenGui.DescendantRemoving:Connect(function(Instance)
		if Library.RegistryMap[Instance] then
			Library:RemoveFromRegistry(Instance)
		end
	end))
