				end
				function ContextMenu:Hide()
					self.Container.Visible = false
				end
				function ContextMenu:AddOption(Str, Callback)
					if type(Callback) ~= "function" then
						Callback = function() end
					end
					local Button = Library:CreateLabel({
						Active = false,
						Size = UDim2.new(1, 0, 0, 15),
						TextSize = 13,
						Text = Str,
						ZIndex = 16,
						Parent = self.Inner,
						TextXAlignment = Enum.TextXAlignment.Left,
					})
					Library:OnHighlight(Button, Button, { TextColor3 = "AccentColor" }, { TextColor3 = "FontColor" })
					Button.InputBegan:Connect(function(Input)
						if Input.UserInputType ~= Enum.UserInputType.MouseButton1 then
							return
						end
						Callback()
					end)
				end
				ContextMenu:AddOption("Rainbow toggle", function()
					ColorPicker.Rainbow = not ColorPicker.Rainbow
					ColorPicker:Display()
				end)
				ContextMenu:AddOption("Copy color", function()
					Library.ColorClipboard = ColorPicker.Value
					Library:Notify("Copied color!", 2)
				end)
				ContextMenu:AddOption("Paste color", function()
					if not Library.ColorClipboard then
						return Library:Notify("You have not copied a color!", 2)
					end
					ColorPicker:SetValueRGB(Library.ColorClipboard)
				end)
				ContextMenu:AddOption("Copy HEX", function()
					pcall(setclipboard, ColorPicker.Value:ToHex())
					Library:Notify("Copied hex code to clipboard!", 2)
				end)
				ContextMenu:AddOption("Copy RGB", function()
					pcall(
						setclipboard,
						table.concat({
							math.floor(ColorPicker.Value.R * 255),
							math.floor(ColorPicker.Value.G * 255),
							math.floor(ColorPicker.Value.B * 255),
						}, ", ")
					)
					Library:Notify("Copied RGB values to clipboard!", 2)
				end)
			end
			Library:AddToRegistry(
				PickerFrameInner,
				{ BackgroundColor3 = "BackgroundColor", BorderColor3 = "OutlineColor" }
			)
			Library:AddToRegistry(Highlight, { BackgroundColor3 = "AccentColor" })
			Library:AddToRegistry(
				SatVibMapInner,
				{ BackgroundColor3 = "BackgroundColor", BorderColor3 = "OutlineColor" }
			)
			Library:AddToRegistry(HueBoxInner, { BackgroundColor3 = "MainColor", BorderColor3 = "OutlineColor" })
			Library:AddToRegistry(RgbBoxBase.Frame, { BackgroundColor3 = "MainColor", BorderColor3 = "OutlineColor" })
			Library:AddToRegistry(RgbBox, { TextColor3 = "FontColor" })
			Library:AddToRegistry(HueBox, { TextColor3 = "FontColor" })
			local SequenceTable = {}
			for Hue = 0, 1, 0.1 do
				table.insert(SequenceTable, ColorSequenceKeypoint.new(Hue, Color3.fromHSV(Hue, 1, 1)))
			end
			local HueSelectorGradient = Library:Create("UIGradient", {
				Color = ColorSequence.new(SequenceTable),
				Rotation = 90,
				Parent = HueSelectorInner,
			})
			HueBox.FocusLost:Connect(function(enter)
				if enter then
					local success, result = pcall(Color3.fromHex, HueBox.Text)
					if success and typeof(result) == "Color3" then
						ColorPicker.Hue, ColorPicker.Sat, ColorPicker.Vib = Color3.toHSV(result)
					end
				end
				ColorPicker:Display()
			end)
			RgbBox.FocusLost:Connect(function(enter)
				if enter then
					local r, g, b = RgbBox.Text:match("(%d+),%s*(%d+),%s*(%d+)")
					if r and g and b then
						ColorPicker.Hue, ColorPicker.Sat, ColorPicker.Vib = Color3.toHSV(Color3.fromRGB(r, g, b))
					end
				end
				ColorPicker:Display()
			end)
			function ColorPicker:Display()
				if ColorPicker.Rainbow then
					RainbowColorPickers[ColorPicker] = true
				else
					RainbowColorPickers[ColorPicker] = nil
				end
				ColorPicker.Value = Color3.fromHSV(ColorPicker.Hue, ColorPicker.Sat, ColorPicker.Vib)
				SatVibMap.BackgroundColor3 = Color3.fromHSV(ColorPicker.Hue, 1, 1)
				if ColorPicker.Rainbow then
					ColorPicker.Value = Library.CurrentRainbowColor
				end
				Library:Create(DisplayFrame, {
					BackgroundColor3 = ColorPicker.Value,
					BackgroundTransparency = ColorPicker.Transparency,
					BorderColor3 = Library:GetDarkerColor(ColorPicker.Value),
				})
				if TransparencyBoxInner then
					TransparencyBoxInner.BackgroundColor3 = ColorPicker.Value
					TransparencyCursor.Position = UDim2.new(1 - ColorPicker.Transparency, 0, 0, 0)
				end
				CursorOuter.Position = UDim2.new(ColorPicker.Sat, 0, 1 - ColorPicker.Vib, 0)
				HueCursor.Position = UDim2.new(0, 0, ColorPicker.Hue, 0)
				HueBox.Text = "#" .. ColorPicker.Value:ToHex()
				RgbBox.Text = table.concat({
					math.floor(ColorPicker.Value.R * 255),
					math.floor(ColorPicker.Value.G * 255),
					math.floor(ColorPicker.Value.B * 255),
				}, ", ")
				Library:SafeCallback(
					"ColorPicker_Callback" .. "_" .. (Idx or ""),
					ColorPicker.Callback,
					ColorPicker.Value
				)
				Library:SafeCallback(
					"ColorPicker_Changed" .. "_" .. (Idx or ""),
					ColorPicker.Changed,
					ColorPicker.Value
				)
			end
			function ColorPicker:OnChanged(Func)
				ColorPicker.Changed = Func
				Func(ColorPicker.Value)
			end
			function ColorPicker:Show()
				for Frame, Val in next, Library.OpenedFrames do
					if Frame.Name == "Color" then
						Frame.Visible = false
						Library.OpenedFrames[Frame] = nil
					end
				end
				-- Refresh anchor on open since the signal handler skips work while closed.
				PickerFrameOuter.Position =
					UDim2.fromOffset(DisplayFrame.AbsolutePosition.X, DisplayFrame.AbsolutePosition.Y + 18)
				PickerFrameOuter.Visible = true
				Library.OpenedFrames[PickerFrameOuter] = true
			end
			function ColorPicker:Hide()
				PickerFrameOuter.Visible = false
				Library.OpenedFrames[PickerFrameOuter] = nil
			end
			function ColorPicker:SetValue(HSV, Transparency)
				local Color = Color3.fromHSV(HSV[1], HSV[2], HSV[3])
				ColorPicker.Transparency = Transparency or 0
				ColorPicker:SetHSVFromRGB(Color)
				ColorPicker:Display()
			end
			function ColorPicker:SetValueRGB(Color, Transparency)
				ColorPicker.Transparency = Transparency or 0
				ColorPicker:SetHSVFromRGB(Color)
				ColorPicker:Display()
			end
			local satVibDragging = false
			SatVibMap.InputBegan:Connect(function(Input)
				if Input.UserInputType == Enum.UserInputType.MouseButton1 then
					satVibDragging = true
				end
			end)
			SatVibMap.InputEnded:Connect(function(Input)
				if Input.UserInputType == Enum.UserInputType.MouseButton1 then
					satVibDragging = false
					Library:AttemptSave()
				end
			end)
			InputService.InputChanged:Connect(function(Input)
				if satVibDragging and Input.UserInputType == Enum.UserInputType.MouseMovement then
					local MinX = SatVibMap.AbsolutePosition.X
					local MaxX = MinX + SatVibMap.AbsoluteSize.X
					local MouseX = math.clamp(Mouse.X, MinX, MaxX)
					local MinY = SatVibMap.AbsolutePosition.Y
					local MaxY = MinY + SatVibMap.AbsoluteSize.Y
					local MouseY = math.clamp(Mouse.Y, MinY, MaxY)
					ColorPicker.Sat = (MouseX - MinX) / (MaxX - MinX)
					ColorPicker.Vib = 1 - ((MouseY - MinY) / (MaxY - MinY))
					ColorPicker:Display()
				end
			end)
			local hueDragging = false
			HueSelectorInner.InputBegan:Connect(function(Input)
				if Input.UserInputType == Enum.UserInputType.MouseButton1 then
					hueDragging = true
				end
			end)
			HueSelectorInner.InputEnded:Connect(function(Input)
				if Input.UserInputType == Enum.UserInputType.MouseButton1 then
					hueDragging = false
					Library:AttemptSave()
				end
			end)
			InputService.InputChanged:Connect(function(Input)
				if hueDragging and Input.UserInputType == Enum.UserInputType.MouseMovement then
					local MinY = HueSelectorInner.AbsolutePosition.Y
					local MaxY = MinY + HueSelectorInner.AbsoluteSize.Y
					local MouseY = math.clamp(Mouse.Y, MinY, MaxY)
					ColorPicker.Hue = ((MouseY - MinY) / (MaxY - MinY))
					ColorPicker:Display()
				end
			end)
			DisplayFrame.InputBegan:Connect(function(Input)
				if Input.UserInputType == Enum.UserInputType.MouseButton1 and not Library:MouseIsOverOpenedFrame() then
					if PickerFrameOuter.Visible then
						ColorPicker:Hide()
					else
						ContextMenu:Hide()
						ColorPicker:Show()
					end
				elseif
					Input.UserInputType == Enum.UserInputType.MouseButton2 and not Library:MouseIsOverOpenedFrame()
				then
					ContextMenu:Show()
					ColorPicker:Hide()
				end
			end)
			if TransparencyBoxInner then
				local transpDragging = false
				TransparencyBoxInner.InputBegan:Connect(function(Input)
					if Input.UserInputType == Enum.UserInputType.MouseButton1 then
						transpDragging = true
					end
				end)
				TransparencyBoxInner.InputEnded:Connect(function(Input)
					if Input.UserInputType == Enum.UserInputType.MouseButton1 then
						transpDragging = false
						Library:AttemptSave()
					end
				end)
				InputService.InputChanged:Connect(function(Input)
					if transpDragging and Input.UserInputType == Enum.UserInputType.MouseMovement then
						local MinX = TransparencyBoxInner.AbsolutePosition.X
						local MaxX = MinX + TransparencyBoxInner.AbsoluteSize.X
						local MouseX = math.clamp(Mouse.X, MinX, MaxX)
						ColorPicker.Transparency = 1 - ((MouseX - MinX) / (MaxX - MinX))
						ColorPicker:Display()
					end
				end)
			end
			Library:GiveSignal(InputService.InputBegan:Connect(function(Input)
				if Input.UserInputType == Enum.UserInputType.MouseButton1 then
					local AbsPos, AbsSize = PickerFrameOuter.AbsolutePosition, PickerFrameOuter.AbsoluteSize
					if
						Mouse.X < AbsPos.X
						or Mouse.X > AbsPos.X + AbsSize.X
						or Mouse.Y < (AbsPos.Y - 20 - 1)
						or Mouse.Y > AbsPos.Y + AbsSize.Y
					then
						ColorPicker:Hide()
					end
					if not Library:IsMouseOverFrame(ContextMenu.Container) then
						ContextMenu:Hide()
					end
				end
				if Input.UserInputType == Enum.UserInputType.MouseButton2 and ContextMenu.Container.Visible then
					if
						not Library:IsMouseOverFrame(ContextMenu.Container)
						and not Library:IsMouseOverFrame(DisplayFrame)
					then
						ContextMenu:Hide()
					end
				end
			end))
			ColorPicker:Display()
			ColorPicker.DisplayFrame = DisplayFrame
			if Idx then
				Options[Idx] = ColorPicker
				ColorPickers[Idx] = ColorPicker
			end
			return self
		end
		function Funcs:AddKeyPicker(Idx, Info)
			local ParentObj = self
			local ToggleLabel = self.TextLabel
			local Container = self.Container
			assert(Info.Default, "AddKeyPicker: Missing default value.")
			local KeyPicker = {
				Value = Info.Default,
				Toggled = false,
				Mode = Info.Mode or "Toggle", -- Always, Toggle, Hold
				Type = "KeyPicker",
				Callback = Info.Callback or function(Value) end,
				ChangedCallback = Info.ChangedCallback or function(New) end,
				SyncToggleState = Info.SyncToggleState or false,
			}
			if KeyPicker.SyncToggleState then
				Info.Modes = { "Toggle", "Hold" }
				Info.Mode = "Toggle"
			end
			local PickOuter = Library:Create("Frame", {
				BackgroundColor3 = Library.MainColor,
				BorderSizePixel = 0,
				AnchorPoint = Vector2.new(1, 0.5),
				Position = UDim2.new(1, 0, 0.5, 0),
				Size = UDim2.new(0, 28, 0, 14),
				ZIndex = 6,
				Parent = ToggleLabel,
			})
			Library:Create("UICorner", { CornerRadius = UDim.new(0, 0), Parent = PickOuter })
			Library:AddToRegistry(PickOuter, { BackgroundColor3 = "MainColor" })
			local PickInner = Library:Create("TextLabel", {
				BackgroundTransparency = 1,
				Size = UDim2.new(1, 0, 1, 0),
				TextColor3 = Library.AccentColor,
				TextSize = 11,
				Font = Enum.Font.GothamBold,
				Text = Info.Default,
				ZIndex = 7,
				Parent = PickOuter,
			})
			Library:AddToRegistry(PickInner, { TextColor3 = "AccentColor" })
			local DisplayLabel = PickInner
			local ModeSelectOuter = Library:Create("Frame", {
				BorderColor3 = Color3.new(0, 0, 0),
				Position = UDim2.fromOffset(
					ToggleLabel.AbsolutePosition.X + ToggleLabel.AbsoluteSize.X + 4,
					ToggleLabel.AbsolutePosition.Y + 1
				),
				Size = UDim2.new(0, 60, 0, 60 + 2),
				Visible = false,
				ZIndex = 14,
				Parent = ScreenGui,
			})
			ModeSelectFrames[#ModeSelectFrames + 1] = ModeSelectOuter
			ToggleLabel:GetPropertyChangedSignal("AbsolutePosition"):Connect(function()
				-- Only re-anchor while the mode selector is open, so scrolling doesn't fire this each frame.
				if not ModeSelectOuter.Visible then
					return
				end
				ModeSelectOuter.Position = UDim2.fromOffset(
					ToggleLabel.AbsolutePosition.X + ToggleLabel.AbsoluteSize.X + 4,
					ToggleLabel.AbsolutePosition.Y + 1
				)
			end)
			local ModeSelectInner = Library:Create("Frame", {
				BackgroundColor3 = Library.BackgroundColor,
				BorderColor3 = Library.OutlineColor,
				BorderMode = Enum.BorderMode.Inset,
				Size = UDim2.new(1, 0, 1, 0),
				ZIndex = 15,
				Parent = ModeSelectOuter,
			})
			Library:AddToRegistry(ModeSelectInner, {
				BackgroundColor3 = "BackgroundColor",
				BorderColor3 = "OutlineColor",
			})
			Library:Create("UIListLayout", {
				FillDirection = Enum.FillDirection.Vertical,
				SortOrder = Enum.SortOrder.LayoutOrder,
				Parent = ModeSelectInner,
			})
			local ContainerLabel = Library:CreateLabel({
				TextXAlignment = Enum.TextXAlignment.Left,
				Size = UDim2.new(1, 0, 0, 18),
				TextSize = 13,
				Visible = false,
				ZIndex = 110,
				Parent = Library.KeybindContainer,
			}, true)

			local Modes = Info.Modes or { "Always", "Toggle", "Hold", "Off" }
			local ModeButtons = {}

			function KeyPicker:DoClick()
				if ParentObj.Type == "Toggle" and KeyPicker.SyncToggleState then
					ParentObj:SetValue(not ParentObj.Value)
				end

				Library:SafeCallback("KeyPicker_Callback" .. "_" .. (Idx or ""), KeyPicker.Callback, KeyPicker.Toggled)
				Library:SafeCallback("KeyPicker_Clicked" .. "_" .. (Idx or ""), KeyPicker.Clicked, KeyPicker.Toggled)
			end

			for Idx, Mode in next, Modes do
				local ModeButton = {}

				local Label = Library:CreateLabel({
					Active = false,
					Size = UDim2.new(1, 0, 0, 15),
					TextSize = 13,
					Text = Mode,
					ZIndex = 16,
					Parent = ModeSelectInner,
				})

				function ModeButton:Select()
					for _, Button in next, ModeButtons do
						Button:Deselect()
					end

					if Mode == "Always" then
						KeyPicker.Toggled = true
						KeyPicker:DoClick()
					end

					if Mode == "Off" then
						KeyPicker.Toggled = false
						KeyPicker:DoClick()
					end

					KeyPicker.Mode = Mode

					Label.TextColor3 = Library.AccentColor
					Library.RegistryMap[Label].Properties.TextColor3 = "AccentColor"

					ModeSelectOuter.Visible = false
				end

				function ModeButton:Deselect()
					KeyPicker.Mode = nil

					Label.TextColor3 = Library.FontColor
					Library.RegistryMap[Label].Properties.TextColor3 = "FontColor"
				end

				Label.InputBegan:Connect(function(Input)
					if Input.UserInputType == Enum.UserInputType.MouseButton1 then
						ModeButton:Select()
						Library:AttemptSave()
					end
				end)

				if Mode == KeyPicker.Mode then
					ModeButton:Select()
				end

				ModeButtons[Mode] = ModeButton
			end

			function KeyPicker:Update()
				if Info.NoUI then
					return
				end

				local State = KeyPicker:GetState()

				ContainerLabel.Text = string.format("[%s] %s", KeyPicker.Value, Info.Text)

				-- Only show keybinds that are actually set.
				if KeyPicker.Value == "N/A" or KeyPicker.Value == "None" then
					ContainerLabel.Visible = false
				else
					ContainerLabel.Visible = true
				end

				ContainerLabel.TextColor3 = State and Library.AccentColor or Library.FontColor

				Library.RegistryMap[ContainerLabel].Properties.TextColor3 = State and "AccentColor" or "FontColor"

				local YSize = 0
				local XSize = 0

				for _, Label in next, Library.KeybindContainer:GetChildren() do
					if Label:IsA("TextLabel") and Label.Visible then
						YSize = YSize + 18
						if Label.TextBounds.X > XSize then
							XSize = Label.TextBounds.X
						end
					end
				end

				local Override = Library.KeybindSizeOverride
				local AutoWidth = math.max(XSize + 60, 340)
				local AutoHeight = YSize + 23
				local Width = (Override and Override.Width) or AutoWidth
				local Height = (Override and Override.Height) or AutoHeight

				Library.KeybindFrame.Size = UDim2.new(0, Width, 0, Height)
			end
			function KeyPicker:GetState()
				if KeyPicker.Mode == "Always" then
					return true
				elseif KeyPicker.Mode == "Off" then
					return false
				elseif KeyPicker.Mode == "Hold" then
					if KeyPicker.Value == "None" then
						return false
					end
					local Key = KeyPicker.Value
					if Key == "MB1" or Key == "MB2" then
						return Key == "MB1" and InputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)
							or Key == "MB2" and InputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)
					else
						return InputService:IsKeyDown(Enum.KeyCode[KeyPicker.Value])
					end
				else
					return KeyPicker.Toggled
				end
			end
			function KeyPicker:SetValue(Data)
				local Key, Mode = Data[1], Data[2]
				DisplayLabel.Text = Key
				KeyPicker.Value = Key
				ModeButtons[Mode]:Select()
				KeyPicker:Update()
			end
			function KeyPicker:OnClick(Callback)
				KeyPicker.Clicked = Callback
			end
			function KeyPicker:OnChanged(Callback)
				KeyPicker.Changed = Callback
				Callback(KeyPicker.Value)
			end
			if ParentObj.Addons then
				table.insert(ParentObj.Addons, KeyPicker)
			end
			local Picking = false
			PickOuter.InputBegan:Connect(function(Input)
				if Input.UserInputType == Enum.UserInputType.MouseButton1 and not Library:MouseIsOverOpenedFrame() then
					Picking = true
					DisplayLabel.Text = ""
					local Break
					local Text = ""
					task.spawn(function()
						while not Break do
							if Text == "..." then
								Text = ""
							end
							Text = Text .. "."
							DisplayLabel.Text = Text
							wait(0.4)
						end
					end)
					wait(0.2)
					local Event
					Event = InputService.InputBegan:Connect(function(Input)
						local Key
						if Input.UserInputType == Enum.UserInputType.Keyboard then
							Key = Input.KeyCode.Name
						elseif Input.UserInputType == Enum.UserInputType.MouseButton1 then
							Key = "MB1"
						elseif Input.UserInputType == Enum.UserInputType.MouseButton2 then
							Key = "MB2"
						end
						if Input.KeyCode == Enum.KeyCode.Escape or Input.KeyCode == Enum.KeyCode.Backspace then
							Key = "N/A"
						end
						Break = true
						Picking = false
						DisplayLabel.Text = Key
						KeyPicker.Value = Key
						Library:SafeCallback(
							"KeyPicker_ChangedCallback" .. "_" .. (Idx or ""),
							KeyPicker.ChangedCallback,
							Input.KeyCode or Input.UserInputType
						)
						Library:SafeCallback(
							"KeyPicker_Changed" .. "_" .. (Idx or ""),
							KeyPicker.Changed,
							Input.KeyCode or Input.UserInputType
						)
						Library:AttemptSave()
						Event:Disconnect()
					end)
				elseif
					Input.UserInputType == Enum.UserInputType.MouseButton2 and not Library:MouseIsOverOpenedFrame()
				then
					-- Refresh anchor on open since the signal handler skips work while closed.
					ModeSelectOuter.Position = UDim2.fromOffset(
						ToggleLabel.AbsolutePosition.X + ToggleLabel.AbsoluteSize.X + 4,
						ToggleLabel.AbsolutePosition.Y + 1
					)
					ModeSelectOuter.Visible = true
				end
			end)
			Library:GiveSignal(InputService.InputBegan:Connect(function(Input, ProcessedByGame)
				if ProcessedByGame then
					return
				end
				if not Picking then
					if KeyPicker.Mode == "Toggle" then
						local Key = KeyPicker.Value
						if Key == "MB1" or Key == "MB2" then
							if
								Key == "MB1" and Input.UserInputType == Enum.UserInputType.MouseButton1
								or Key == "MB2" and Input.UserInputType == Enum.UserInputType.MouseButton2
							then
								KeyPicker.Toggled = not KeyPicker.Toggled
								KeyPicker:DoClick()
							end
						elseif Input.UserInputType == Enum.UserInputType.Keyboard then
							if Input.KeyCode.Name == Key then
								KeyPicker.Toggled = not KeyPicker.Toggled
								KeyPicker:DoClick()
							end
						end
					end
					KeyPicker:Update()
				end
				if Input.UserInputType == Enum.UserInputType.MouseButton1 then
					local AbsPos, AbsSize = ModeSelectOuter.AbsolutePosition, ModeSelectOuter.AbsoluteSize
					if
						Mouse.X < AbsPos.X
						or Mouse.X > AbsPos.X + AbsSize.X
						or Mouse.Y < (AbsPos.Y - 20 - 1)
						or Mouse.Y > AbsPos.Y + AbsSize.Y
					then
						ModeSelectOuter.Visible = false
					end
				end
			end))
			Library:GiveSignal(InputService.InputEnded:Connect(function(Input, ProcessedByGame)
				if ProcessedByGame then
					return
				end
				if not Picking then
					KeyPicker:Update()
				end
			end))
			if Info.Mode == "Always" then
				KeyPicker.Toggled = true
				KeyPicker:DoClick()
			end
			if Info.Mode == "Off" then
				KeyPicker.Toggled = false
				KeyPicker:DoClick()
			end
			KeyPicker:Update()
			if Idx then
				Options[Idx] = KeyPicker
			end
			return self
		end
		BaseAddons.__index = Funcs
		BaseAddons.__namecall = function(Table, Key, ...)
			return Funcs[Key](...)
		end
	end
	local function GetVisibleContentHeight(Container)
		local Height = 0
		for _, Element in next, Container:GetChildren() do
			if not Element:IsA("UIListLayout") and Element.Visible then
				Height = Height + Element.Size.Y.Offset
			end
		end
		return math.ceil(Height)
	end
	local function ScheduleLayoutRefresh(Callback)
		task.spawn(function()
			for _ = 1, 4 do
				task.wait()
				if not pcall(Callback) then
					break
				end
			end
		end)
	end
	local BaseGroupbox = {}
	do
		local Funcs = {}
		function Funcs:AddBlank(Size)
			local Groupbox = self
			local Container = Groupbox.Container
			Library:Create("Frame", {
				BackgroundTransparency = 1,
				Size = UDim2.new(1, 0, 0, Size),
				ZIndex = 1,
				Parent = Container,
			})
		end
		function Funcs:AddLabel(Text, DoesWrap)
			local Label = {}
			local Groupbox = self
			local Container = Groupbox.Container
			local TextLabel = Library:CreateLabel({
				Size = UDim2.new(1, -4, 0, 15),
				TextSize = 14,
				Text = Text,
				TextWrapped = DoesWrap or false,
				TextXAlignment = Enum.TextXAlignment.Left,
				ZIndex = 5,
				Parent = Container,
			})
			if DoesWrap then
				local Y = select(
					2,
					Library:GetTextBounds(Text, Library.Font, 14, Vector2.new(TextLabel.AbsoluteSize.X, math.huge))
				)
				TextLabel.Size = UDim2.new(1, -4, 0, Y)
			else
				Library:Create("UIListLayout", {
					Padding = UDim.new(0, 4),
					FillDirection = Enum.FillDirection.Horizontal,
					HorizontalAlignment = Enum.HorizontalAlignment.Right,
					SortOrder = Enum.SortOrder.LayoutOrder,
					Parent = TextLabel,
				})
			end
			Label.TextLabel = TextLabel
			Label.Container = Container
			function Label:SetText(Text)
				TextLabel.Text = Text
				if DoesWrap then
					local Y = select(
						2,
						Library:GetTextBounds(Text, Library.Font, 14, Vector2.new(TextLabel.AbsoluteSize.X, math.huge))
					)
					TextLabel.Size = UDim2.new(1, -4, 0, Y)
				end
				Groupbox:Resize()
			end
			if not DoesWrap then
				setmetatable(Label, BaseAddons)
			end
			Groupbox:AddBlank(5)
			Groupbox:Resize()
			return Label
		end
		function Funcs:AddButton(...)
			local Button = {}
			local function ProcessButtonParams(Class, Obj, ...)
				local Props = select(1, ...)
				if type(Props) == "table" then
					Obj.Text = Props.Text
					Obj.Func = Props.Func
					Obj.DoubleClick = Props.DoubleClick
					Obj.DoubleClickText = Props.DoubleClickText
					Obj.Tooltip = Props.Tooltip
				else
					Obj.Text = select(1, ...)
					Obj.Func = select(2, ...)
				end
				assert(type(Obj.Func) == "function", "AddButton: `Func` callback is missing.")
			end
			ProcessButtonParams("Button", Button, ...)
			local Groupbox = self
			local Container = Groupbox.Container
			local function CreateBaseButton(Button)
				-- Flat button with left accent stripe + subtle gradient + press animation
				local Outer = Library:Create("Frame", {
					BackgroundColor3 = Library.MainColor,
					BorderSizePixel = 0,
					Size = UDim2.new(1, -4, 0, 22),
					ZIndex = 5,
				})
				Library:Create("UICorner", { CornerRadius = UDim.new(0, 0), Parent = Outer })
				local Inner = Library:Create("Frame", {
					BackgroundColor3 = Library.MainColor,
					BorderSizePixel = 0,
					Size = UDim2.new(1, 0, 1, 0),
					ZIndex = 6,
					Parent = Outer,
				})
				Library:Create("UICorner", { CornerRadius = UDim.new(0, 0), Parent = Inner })
				Library:Create("UIGradient", {
					Color = ColorSequence.new({
						ColorSequenceKeypoint.new(0, Color3.new(1, 1, 1)),
						ColorSequenceKeypoint.new(1, Color3.new(0.85, 0.85, 0.85)),
					}),
					Transparency = NumberSequence.new({
						NumberSequenceKeypoint.new(0, 0.88),
						NumberSequenceKeypoint.new(1, 0.98),
					}),
					Rotation = 90,
					Parent = Inner,
				})
				local AccentStripe
				local LabelOffset = 0
				if not Button.IsSubButton then
					AccentStripe = Library:Create("Frame", {
						BackgroundColor3 = Library.AccentColor,
						BorderSizePixel = 0,
						Size = UDim2.new(0, 3, 1, 0),
						ZIndex = 7,
						Parent = Inner,
					})
					Library:AddToRegistry(AccentStripe, { BackgroundColor3 = "AccentColor" })
					LabelOffset = 3
				end
				local FlashOverlay = Library:Create("Frame", {
					BackgroundColor3 = Library.AccentColor,
					BackgroundTransparency = 1,
					BorderSizePixel = 0,
					Size = UDim2.new(1, 0, 1, 0),
					ZIndex = 6,
					Parent = Inner,
				})
				Library:AddToRegistry(FlashOverlay, { BackgroundColor3 = "AccentColor" })
				local Stroke = Library:Create("UIStroke", {
					Color = Library.AccentColor,
					Thickness = 1,
					Transparency = 0.75,
					Parent = Outer,
				})
				Library:AddToRegistry(Stroke, { Color = "AccentColor" })
				local ButtonScale = Library:Create("UIScale", {
					Scale = 1,
					Parent = Outer,
				})
				local Label = Library:CreateLabel({
					Position = UDim2.fromOffset(LabelOffset, 0),
					Size = UDim2.new(1, -LabelOffset, 1, 0),
					TextSize = 13,
					Text = Button.Text,
					ZIndex = 6,
					Parent = Inner,
				})
				Library:AddToRegistry(Outer, {
					BackgroundColor3 = "MainColor",
				})
				Library:AddToRegistry(Inner, {
					BackgroundColor3 = "MainColor",
				})
				if AccentStripe then
					Library:AddToRegistry(AccentStripe, {
						BackgroundColor3 = "AccentColor",
					})
				end
				Library:AddToRegistry(FlashOverlay, {
					BackgroundColor3 = "AccentColor",
				})
				Library:AddToRegistry(Stroke, {
					Color = "AccentColor",
				})
				Library:OnHighlight(Outer, Stroke, { Transparency = 0.15 }, { Transparency = 0.75 })
				Button.FlashOverlay = FlashOverlay
				Button.ButtonScale = ButtonScale
				return Outer, Inner, Label
			end
			local function InitEvents(Button)
				local function WaitForEvent(event, timeout, validator)
					local bindable = Instance.new("BindableEvent")
					local connection = event:Once(function(...)
						if type(validator) == "function" and validator(...) then
							bindable:Fire(true)
						else
							bindable:Fire(false)
						end
					end)
					task.delay(timeout, function()
						connection:disconnect()
						bindable:Fire(false)
					end)
					return bindable.Event:Wait()
				end
				local function ValidateClick(Input)
					if Library:MouseIsOverOpenedFrame() then
						return false
					end
					if Input.UserInputType ~= Enum.UserInputType.MouseButton1 then
						return false
					end
					return true
				end
				local function PlayPressAnimation()
					TweenService:Create(Button.ButtonScale, TweenInfo.new(0.08, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
						Scale = 0.95,
					}):Play()
					TweenService:Create(Button.FlashOverlay, TweenInfo.new(0.06, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
						BackgroundTransparency = 0.75,
					}):Play()
				end
				local function PlayReleaseAnimation()
					TweenService:Create(Button.ButtonScale, TweenInfo.new(0.18, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
						Scale = 1,
					}):Play()
					TweenService:Create(Button.FlashOverlay, TweenInfo.new(0.28, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
						BackgroundTransparency = 1,
					}):Play()
				end
				Button.Outer.InputBegan:Connect(function(Input)
					if not ValidateClick(Input) then
						return
					end
					if Button.Locked then
						return
					end
					PlayPressAnimation()
					task.delay(0.08, PlayReleaseAnimation)
					if Button.DoubleClick then
						Library:RemoveFromRegistry(Button.Label)
						Library:AddToRegistry(Button.Label, { TextColor3 = "AccentColor" })
						Button.Label.TextColor3 = Library.AccentColor
						Button.Label.Text = Button.DoubleClickText or "Are you sure?"
						Button.Locked = true
						local clicked = WaitForEvent(Button.Outer.InputBegan, 2, ValidateClick)
						Library:RemoveFromRegistry(Button.Label)
						Library:AddToRegistry(Button.Label, { TextColor3 = "FontColor" })
						Button.Label.TextColor3 = Library.FontColor
						Button.Label.Text = Button.Text
						task.defer(rawset, Button, "Locked", false)
						if clicked then
							Library:SafeCallback("Button" .. "_" .. Button.Label.Text, Button.Func)
						end
						return
					end
					Library:SafeCallback("Button" .. "_" .. Button.Label.Text, Button.Func)
				end)
			end
			Button.Outer, Button.Inner, Button.Label = CreateBaseButton(Button)
			Button.Outer.Parent = Container
			InitEvents(Button)
			function Button:AddTooltip(tooltip)
				if type(tooltip) == "string" then
					Library:AddToolTip(tooltip, self.Outer)
				end
				return self
			end
			function Button:AddButton(...)
				local SubButton = {}
				ProcessButtonParams("SubButton", SubButton, ...)
				SubButton.IsSubButton = true
				self.Outer.Size = UDim2.new(0.5, -2, 0, 20)
				SubButton.Outer, SubButton.Inner, SubButton.Label = CreateBaseButton(SubButton)
				-- Size/position relative to the parent half instead of reading AbsoluteSize: AbsoluteSize hasn't refreshed yet on the frame we just resized the parent, so the old fromOffset call grabbed a stale/zero width.
				SubButton.Outer.Position = UDim2.new(1, 4, 0, 0)
				SubButton.Outer.Size = UDim2.new(1, -4, 1, 0)
				SubButton.Outer.Parent = self.Outer
				function SubButton:AddTooltip(tooltip)
					if type(tooltip) == "string" then
						Library:AddToolTip(tooltip, self.Outer)
					end
					return SubButton
				end
				if type(SubButton.Tooltip) == "string" then
					SubButton:AddTooltip(SubButton.Tooltip)
				end
				InitEvents(SubButton)
				return SubButton
			end
			if type(Button.Tooltip) == "string" then
				Button:AddTooltip(Button.Tooltip)
			end
			Groupbox:AddBlank(5)
			Groupbox:Resize()
			if self.SearchContext and type(Button.Text) == "string" then
				Library:RegisterSearchable({
					Text = Button.Text,
					TabName = self.SearchContext.TabName,
					SubName = self.SearchContext.SubName,
					GroupName = self.SearchContext.GroupName,
					Side = self.SearchContext.Side,
					ElementType = "Button",
					Row = Button.Outer,
					Show = self.SearchContext.Show,
					Button = Button,
				})
			end
			return Button
		end
		function Funcs:AddDivider()
			local Groupbox = self
			local Container = self.Container
			local Divider = {
				Type = "Divider",
			}
			Groupbox:AddBlank(2)
			local DividerOuter = Library:Create("Frame", {
				BackgroundColor3 = Library.OutlineColor,
				BorderSizePixel = 0,
				BackgroundTransparency = 0.5,
				Size = UDim2.new(1, -8, 0, 1),
				ZIndex = 5,
				Parent = Container,
			})
			local DividerInner = Library:Create("Frame", {
				BackgroundColor3 = Library.OutlineColor,
				BorderSizePixel = 0,
				BackgroundTransparency = 0.5,
				Size = UDim2.new(1, 0, 1, 0),
				ZIndex = 6,
				Parent = DividerOuter,
			})
			Library:AddToRegistry(DividerOuter, {
				BackgroundColor3 = "OutlineColor",
			})
			Library:AddToRegistry(DividerInner, {
				BackgroundColor3 = "MainColor",
				BorderColor3 = "OutlineColor",
			})
			Groupbox:AddBlank(9)
			Groupbox:Resize()
		end
		function Funcs:AddInput(Idx, Info)
			assert(Info.Text, "AddInput: Missing `Text` string.")
			local Textbox = {
				Value = Info.Default or "",
				Numeric = Info.Numeric or false,
				Finished = Info.Finished or false,
				Type = "Input",
				Callback = Info.Callback or function(Value) end,
			}
			local Groupbox = self
			local Container = Groupbox.Container
			local InputLabel = Library:CreateLabel({
				Size = UDim2.new(1, 0, 0, 15),
				TextSize = 14,
				Text = Info.Text,
				TextXAlignment = Enum.TextXAlignment.Left,
				ZIndex = 5,
				Parent = Container,
			})
			Groupbox:AddBlank(1)
			-- Rounded flat input with a soft outline that lifts to accent on hover.
			local TextBoxOuter = Library:Create("Frame", {
				BackgroundColor3 = Library.MainColor,
				BorderSizePixel = 0,
				Size = UDim2.new(1, -4, 0, 22),
				ZIndex = 5,
				Parent = Container,
			})
			Library:Create("UICorner", { CornerRadius = UDim.new(1, 0), Parent = TextBoxOuter })
			local TextBoxStroke = Library:Create("UIStroke", {
				Color = Library.OutlineColor,
				Thickness = 1,
				Transparency = 0.5,
				Parent = TextBoxOuter,
			})
			Library:AddToRegistry(TextBoxStroke, { Color = "OutlineColor" })
			local TextBoxInner = Library:Create("Frame", {
				BackgroundColor3 = Library.MainColor,
				BorderSizePixel = 0,
				Size = UDim2.new(1, 0, 1, 0),
				ZIndex = 6,
				Parent = TextBoxOuter,
			})
			Library:Create("UICorner", { CornerRadius = UDim.new(1, 0), Parent = TextBoxInner })
			Library:AddToRegistry(TextBoxInner, {
				BackgroundColor3 = "MainColor",
			})
			Library:OnHighlight(
				TextBoxOuter,
				TextBoxStroke,
				{ Color = "AccentColor", Transparency = 0 },
				{ Color = "OutlineColor", Transparency = 0.5 }
			)
			if type(Info.Tooltip) == "string" then
				Library:AddToolTip(Info.Tooltip, TextBoxOuter)
			end
			local Container = Library:Create("Frame", {
				BackgroundTransparency = 1,
				ClipsDescendants = true,
				Position = UDim2.new(0, 5, 0, 0),
				Size = UDim2.new(1, -5, 1, 0),
				ZIndex = 7,
				Parent = TextBoxInner,
			})
			local Box = Library:Create("TextBox", {
				BackgroundTransparency = 1,
				Position = UDim2.fromOffset(0, 0),
				Size = UDim2.fromScale(5, 1),
				FontFace = Library.Font,
				PlaceholderColor3 = Color3.fromRGB(190, 190, 190),
				PlaceholderText = Info.Placeholder or "",
				Text = Info.Default or "",
				TextColor3 = Library.FontColor,
				TextSize = 14,
				TextStrokeTransparency = 0,
				TextXAlignment = Enum.TextXAlignment.Left,
				ZIndex = 7,
				Parent = Container,
			})
			Library:ApplyTextStroke(Box)
			local Connection = nil
			function Textbox:SetRawValue(Text)
				if Info.MaxLength and #Text > Info.MaxLength then
					Text = Text:sub(1, Info.MaxLength)
				end
				if Textbox.Numeric then
					if (not tonumber(Text)) and Text:len() > 0 then
						Text = Textbox.Value
					end
				end
				Textbox.Value = Text
				Box.Text = Text
			end
			function Textbox:SetValue(Text)
				if Info.MaxLength and #Text > Info.MaxLength then
					Text = Text:sub(1, Info.MaxLength)
				end
				if Textbox.Numeric then
					if (not tonumber(Text)) and Text:len() > 0 then
						Text = Textbox.Value
					end
				end
				Textbox.Value = Text
				Box.Text = Text
				Library:SafeCallback("Textbox_Callback" .. "_" .. (Idx or ""), Textbox.Callback, Textbox.Value)
				Library:SafeCallback("Textbox_Changed" .. "_" .. (Idx or ""), Textbox.Changed, Textbox.Value)
			end
			if Textbox.Finished then
				Connection = Box.FocusLost:Connect(function(enter)
					if not enter then
						return
					end
					Textbox:SetValue(Box.Text)
					Library:AttemptSave()
				end)
			else
				Connection = Box:GetPropertyChangedSignal("Text"):Connect(function()
					Textbox:SetValue(Box.Text)
					Library:AttemptSave()
				end)
			end
			local function Update()
				local PADDING = 2
				local reveal = Container.AbsoluteSize.X
				if not Box:IsFocused() or Box.TextBounds.X <= reveal - 2 * PADDING then
					Box.Position = UDim2.new(0, PADDING, 0, 0)
				else
					local cursor = Box.CursorPosition
					if cursor ~= -1 then
						local subtext = string.sub(Box.Text, 1, cursor - 1)
						local width = TextService:GetTextSize(
							subtext,
							Box.TextSize,
							Box.Font,
							Vector2.new(math.huge, math.huge)
						).X
						local currentCursorPos = Box.Position.X.Offset + width
						if currentCursorPos < PADDING then
							Box.Position = UDim2.fromOffset(PADDING - width, 0)
						elseif currentCursorPos > reveal - PADDING - 1 then
							Box.Position = UDim2.fromOffset(reveal - width - PADDING - 1, 0)
						end
					end
				end
			end
			task.spawn(Update)
			Box:GetPropertyChangedSignal("Text"):Connect(Update)
			Box:GetPropertyChangedSignal("CursorPosition"):Connect(Update)
			Box.FocusLost:Connect(Update)
			Box.Focused:Connect(Update)
			Box.InputBegan:Connect(function(Input)
				if Input.UserInputType == Enum.UserInputType.MouseButton2 then
					Library:Notify("Text copied to clipboard!", 2.5)
					setclipboard(Box.Text)
				end
			end)
			Library:AddToRegistry(Box, {
				TextColor3 = "FontColor",
			})
			function Textbox:OnChanged(Func)
				Textbox.Changed = Func
				Func(Textbox.Value)
			end
			Groupbox:AddBlank(5)
			Groupbox:Resize()
			if Idx then
				Options[Idx] = Textbox
			end
			if self.SearchContext then
				Library:RegisterSearchable({
					Text = Info.Text,
					TabName = self.SearchContext.TabName,
					SubName = self.SearchContext.SubName,
					Row = TextBoxOuter,
					Show = self.SearchContext.Show,
				})
			end
			return Textbox
		end
		function Funcs:AddToggle(Idx, Info)
			assert(Info.Text, "AddInput: Missing `Text` string.")
			local Toggle = {
				Value = Info.Default or false,
				Type = "Toggle",
				Callback = Info.Callback or function(Value) end,
				Addons = {},
				Risky = Info.Risky,
			}
			local Groupbox = self
			local Container = Groupbox.Container
			-- Sakura checkbox: outer ring always visible as border, inner fills on check
			local ToggleOuter = Library:Create("Frame", {
				BackgroundColor3 = Color3.fromRGB(0, 0, 0),
				BackgroundTransparency = 1,
				BorderSizePixel = 0,
				Size = UDim2.new(1, -4, 0, 20),
				ZIndex = 5,
				Parent = Container,
			})
			Library:Create("UICorner", { CornerRadius = UDim.new(0, 0), Parent = ToggleOuter })
			-- Switch: pill track (accent when on, dark when off) with a sliding round knob.
			local ToggleInner = Library:Create("Frame", {
				BackgroundColor3 = Toggle.Value and Library.AccentColor or Library.MainColor,
				BorderSizePixel = 0,
				AnchorPoint = Vector2.new(0, 0.5),
				Size = UDim2.new(0, 24, 0, 14),
				Position = UDim2.new(0, 1, 0.5, 0),
				ZIndex = 6,
				Parent = ToggleOuter,
			})
			Library:Create("UICorner", { CornerRadius = UDim.new(1, 0), Parent = ToggleInner })
			Library:AddToRegistry(ToggleInner, { BackgroundColor3 = function() return Toggle.Value and Library.AccentColor or Library.MainColor end })
			-- Faint top-lit sheen (multiplies over whatever colour the track is) so the pill isn't a dead-flat block.
			Library:Create("UIGradient", {
				Color = ColorSequence.new({
					ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 255, 255)),
					ColorSequenceKeypoint.new(1, Color3.fromRGB(214, 214, 224)),
				}),
				Rotation = 90,
				Parent = ToggleInner,
			})
			-- Track outline: darkened accent when on; a light, crisp ring when off — matches the outlined-pill look in the reference image.
			local ToggleOffOutline = Color3.fromRGB(150, 150, 162)
			local ToggleBorder = Library:Create("UIStroke", {
				Color = Toggle.Value and Library:GetDarkerColor(Library.AccentColor) or ToggleOffOutline,
				Thickness = 1,
				Transparency = 0.15,
				Parent = ToggleInner,
			})
			Library:AddToRegistry(ToggleBorder, { Color = function() return Toggle.Value and Library:GetDarkerColor(Library.AccentColor) or ToggleOffOutline end })
			-- Round knob that slides between the ends (8 = off/left, 20 = on/right).
			local ToggleKnob = Library:Create("Frame", {
				BackgroundColor3 = Color3.fromRGB(242, 242, 247),
				BorderSizePixel = 0,
				AnchorPoint = Vector2.new(0.5, 0.5),
				Size = UDim2.new(0, 11, 0, 11),
				Position = UDim2.new(0, Toggle.Value and 17 or 7, 0.5, 0),
				ZIndex = 7,
				Parent = ToggleInner,
			})
			Library:Create("UICorner", { CornerRadius = UDim.new(1, 0), Parent = ToggleKnob })
			Library:Create("UIGradient", {
				Color = ColorSequence.new({
					ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 255, 255)),
					ColorSequenceKeypoint.new(1, Color3.fromRGB(210, 212, 222)),
				}),
				Rotation = 90,
				Parent = ToggleKnob,
			})
			Library:Create("UIStroke", {
				Color = Color3.fromRGB(120, 122, 134),
				Thickness = 1,
				Transparency = 0.55,
				Parent = ToggleKnob,
			})
			local ToggleKnobScale = Library:Create("UIScale", {
				Scale = 1,
				Parent = ToggleKnob,
			})
			local ToggleLabel = Library:CreateLabel({
				Size = UDim2.new(1, -32, 1, 0),
				Position = UDim2.new(0, 32, 0, 0),
				TextSize = 14,
				Text = Info.Text,
				TextXAlignment = Enum.TextXAlignment.Left,
				ZIndex = 6,
				Parent = ToggleOuter,
			})
			local ToggleRegion = Library:Create("Frame", {
				BackgroundTransparency = 1,
				Size = UDim2.new(1, 0, 1, 0),
				ZIndex = 8,
				Parent = ToggleOuter,
			})
			local ToggleHovered = false
			ToggleRegion.MouseEnter:Connect(function()
				ToggleHovered = true
				ToggleBorder.Color = Library.AccentColor
				TweenService:Create(ToggleKnobScale, TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { Scale = 1.12 }):Play()
			end)
			ToggleRegion.MouseLeave:Connect(function()
				ToggleHovered = false
				ToggleBorder.Color = Toggle.Value and Library:GetDarkerColor(Library.AccentColor) or ToggleOffOutline
				TweenService:Create(ToggleKnobScale, TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { Scale = 1 }):Play()
			end)
			function Toggle:UpdateColors()
				Toggle:Display()
			end
			if type(Info.Tooltip) == "string" then
				Library:AddToolTip(Info.Tooltip, ToggleRegion)
			end
			function Toggle:Display()
				ToggleInner.BackgroundColor3 = Toggle.Value and Library.AccentColor or Library.MainColor
				ToggleBorder.Color = (ToggleHovered and Library.AccentColor)
					or (Toggle.Value and Library:GetDarkerColor(Library.AccentColor) or ToggleOffOutline)
				TweenService:Create(ToggleKnob, TweenInfo.new(0.18, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
					Position = UDim2.new(0, Toggle.Value and 17 or 7, 0.5, 0),
				}):Play()
			end
			function Toggle:OnChanged(Func)
				Toggle.Changed = Func
				Func(Toggle.Value)
			end
			function Toggle:SetRawValue(Bool)
				Bool = not not Bool
				Toggle.Value = Bool
				Toggle:Display()
				for _, Addon in next, Toggle.Addons do
					if Addon.Type == "KeyPicker" and Addon.SyncToggleState then
						Addon.Toggled = Bool
						Addon:Update()
					end
				end
				Library:UpdateDependencyBoxes()
			end
			function Toggle:SetValue(Bool)
				Bool = not not Bool
				Toggle.Value = Bool
				Toggle:Display()
				for _, Addon in next, Toggle.Addons do
					if Addon.Type == "KeyPicker" and Addon.SyncToggleState then
						Addon.Toggled = Bool
						Addon:Update()
					end
				end
				Library:SafeCallback("Toggle_Callback" .. "_" .. (Idx or ""), Toggle.Callback, Toggle.Value)
				Library:SafeCallback("Toggle_Changed" .. "_" .. (Idx or ""), Toggle.Changed, Toggle.Value)
				Library:UpdateDependencyBoxes()
			end
			ToggleRegion.InputBegan:Connect(function(Input)
				if Input.UserInputType == Enum.UserInputType.MouseButton1 and not Library:MouseIsOverOpenedFrame() then
					TweenService:Create(ToggleKnobScale, TweenInfo.new(0.07, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { Scale = 0.78 }):Play()
					Toggle:SetValue(not Toggle.Value)
					task.delay(0.075, function()
						if ToggleKnobScale.Parent then
							TweenService:Create(ToggleKnobScale, TweenInfo.new(0.2, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Scale = ToggleHovered and 1.16 or 1 }):Play()
						end
					end)
					Library:AttemptSave()
				end
			end)
			if Toggle.Risky then
				Library:RemoveFromRegistry(ToggleLabel)
				ToggleLabel.TextColor3 = Library.RiskColor
				Library:AddToRegistry(ToggleLabel, { TextColor3 = "RiskColor" })
			end
			Toggle:Display()
			Groupbox:AddBlank(Info.BlankSize or 5 + 2)
			Groupbox:Resize()
			Toggle.TextLabel = ToggleLabel
			Toggle.Container = Container
			setmetatable(Toggle, BaseAddons)
			if Idx then
				Toggles[Idx] = Toggle
			end
			Library:UpdateDependencyBoxes()
			if self.SearchContext then
				Library:RegisterSearchable({
					Text = Info.Text,
					TabName = self.SearchContext.TabName,
					SubName = self.SearchContext.SubName,
					GroupName = self.SearchContext.GroupName,
					Side = self.SearchContext.Side,
					ElementType = "Toggle",
					Idx = Idx,
					Row = ToggleOuter,
					Show = self.SearchContext.Show,
					Toggle = Toggle,
				})
			end
			return Toggle
		end
		function Funcs:AddSlider(Idx, Info)
			assert(Info.Default, "AddSlider: Missing default value.")
			assert(Info.Text, "AddSlider: Missing slider text.")
			assert(Info.Min, "AddSlider: Missing minimum value.")
			assert(Info.Max, "AddSlider: Missing maximum value.")
			assert(Info.Rounding, "AddSlider: Missing rounding value.")
			local Slider = {
				Value = Info.Default,
				Min = Info.Min,
				Max = Info.Max,
				Rounding = Info.Rounding,
				MaxSize = 232,
				Type = "Slider",
				Callback = Info.Callback or function(Value) end,
			}
			local Groupbox = self
			local Container = Groupbox.Container
			if not Info.Compact then
				Library:CreateLabel({
					Size = UDim2.new(1, 0, 0, 10),
					TextSize = 14,
					Text = Info.Text,
					TextXAlignment = Enum.TextXAlignment.Left,
					TextYAlignment = Enum.TextYAlignment.Bottom,
					ZIndex = 5,
					Parent = Container,
				})
				Groupbox:AddBlank(3)
			end
			-- Rounded pill slider: soft-outlined track, accent fill, slim rounded handle.
			local SLIDER_PINK = Library.AccentColor -- fill + knob follow the theme accent
			-- Optional type-in box beside the track (great for big-range sliders like fly speed that go up to a few thousand).
			local ShowInput = not Info.NoInput
			local INPUT_W = 52
			-- Horizontal row so the track and the number box sit side by side.
			local SliderRow = Library:Create("Frame", {
				BackgroundTransparency = 1,
				BorderSizePixel = 0,
				Size = UDim2.new(1, -4, 0, 18),
				ZIndex = 5,
				Parent = Container,
			})
			Library:Create("UIListLayout", {
				FillDirection = Enum.FillDirection.Horizontal,
				HorizontalAlignment = Enum.HorizontalAlignment.Left,
				VerticalAlignment = Enum.VerticalAlignment.Center,
				SortOrder = Enum.SortOrder.LayoutOrder,
				Padding = UDim.new(0, 6),
				Parent = SliderRow,
			})
			local SliderOuter = Library:Create("Frame", {
				BackgroundColor3 = Library.BackgroundColor,
				BorderSizePixel = 0,
				Size = ShowInput and UDim2.new(1, -(INPUT_W + 6), 0, 18) or UDim2.new(1, 0, 0, 18),
				LayoutOrder = 1,
				ZIndex = 5,
				Parent = SliderRow,
			})
			Library:Create("UICorner", { CornerRadius = UDim.new(1, 0), Parent = SliderOuter })
			local SliderStroke = Library:Create("UIStroke", {
				Color = Library.OutlineColor,
				Thickness = 1,
				Transparency = 0.45,
				Parent = SliderOuter
			})
			Library:AddToRegistry(SliderStroke, { Color = "OutlineColor" })
			Library:AddToRegistry(SliderOuter, {
				BackgroundColor3 = "BackgroundColor",
			})
			local SliderInner = Library:Create("Frame", {
				BackgroundColor3 = Library.BackgroundColor,
				BorderSizePixel = 0,
				ClipsDescendants = true,
				Size = UDim2.new(1, 0, 1, 0),
				ZIndex = 6,
				Parent = SliderOuter,
			})
			Library:Create("UICorner", { CornerRadius = UDim.new(1, 0), Parent = SliderInner })
			Library:AddToRegistry(SliderInner, {
				BackgroundColor3 = "BackgroundColor",
			})
			local Fill = Library:Create("Frame", {
				BackgroundColor3 = SLIDER_PINK,
				BorderSizePixel = 0,
				Size = UDim2.new(0, 0, 1, 0),
				ZIndex = 7,
				Parent = SliderInner,
			})
			Library:Create("UICorner", { CornerRadius = UDim.new(1, 0), Parent = Fill })
			Library:AddToRegistry(Fill, { BackgroundColor3 = "AccentColor" })
			-- Vertical sheen on the fill so the accent bar has depth instead of reading flat.
			Library:Create("UIGradient", {
				Color = ColorSequence.new({
					ColorSequenceKeypoint.new(0, Color3.new(1, 1, 1)),
					ColorSequenceKeypoint.new(1, Color3.new(0.8, 0.8, 0.8)),
				}),
				Transparency = NumberSequence.new({
					NumberSequenceKeypoint.new(0, 0.82),
					NumberSequenceKeypoint.new(1, 0.94),
				}),
				Rotation = 90,
				Parent = Fill,
			})
			local Knob = Library:Create("Frame", {
				BackgroundColor3 = Color3.fromRGB(255, 255, 255),
				BorderSizePixel = 0,
				AnchorPoint = Vector2.new(0.5, 0.5),
				Position = UDim2.new(0, 0, 0.5, 0),
				Size = UDim2.new(0, 14, 0, 14),
				ZIndex = 8,
				Parent = SliderInner,
			})
			Library:Create("UICorner", { CornerRadius = UDim.new(1, 0), Parent = Knob })
			-- White capsule handle with an accent rim so it reads as a solid raised knob floating on the accent fill instead of a flat sliver.
			local KnobStroke = Library:Create("UIStroke", {
				Color = Library.AccentColor,
				Thickness = 1,
				Transparency = 0.15,
				Parent = Knob,
			})
			Library:Create("UIGradient", {
				Color = ColorSequence.new({
					ColorSequenceKeypoint.new(0, Color3.new(1, 1, 1)),
					ColorSequenceKeypoint.new(1, Color3.new(0.82, 0.82, 0.82)),
				}),
				Transparency = NumberSequence.new({
					NumberSequenceKeypoint.new(0, 0.78),
					NumberSequenceKeypoint.new(1, 0.9),
				}),
				Rotation = 90,
				Parent = Knob,
			})
			Library:AddToRegistry(KnobStroke, { Color = "AccentColor" })
			-- dummy frame so Slider:Display() logic referencing HideBorderRight doesn't error
			local HideBorderRight = Library:Create("Frame", {
				BackgroundTransparency = 1,
				BorderSizePixel = 0,
				Size = UDim2.new(0, 0, 0, 0),
				ZIndex = 1,
				Parent = Fill,
			})
			local DisplayLabel = Library:CreateLabel({
				Size = UDim2.new(1, -14, 1, 0),
				Position = UDim2.new(0, 7, 0, 0),
				TextSize = 12,
				Text = "Infinite",
				TextColor3 = Library.FontColor,
				TextTransparency = 0,
				TextStrokeTransparency = 0.5,
				TextStrokeColor3 = Color3.new(0, 0, 0),
				TextXAlignment = Enum.TextXAlignment.Right,
				ZIndex = 9,
				Parent = SliderInner,
			})
			Library:OnHighlight(SliderOuter, SliderOuter, { BorderColor3 = "AccentColor" }, { BorderColor3 = "Black" })
			if type(Info.Tooltip) == "string" then
				Library:AddToolTip(Info.Tooltip, SliderOuter)
			end
			-- Type-in box beside the track.
			local ValueBox
			if ShowInput then
				local ValueBoxOuter = Library:Create("Frame", {
					BackgroundColor3 = Library.MainColor,
					BorderSizePixel = 0,
					Size = UDim2.new(0, INPUT_W, 0, 18),
					LayoutOrder = 2,
					ZIndex = 5,
					Parent = SliderRow,
				})
				Library:Create("UICorner", { CornerRadius = UDim.new(1, 0), Parent = ValueBoxOuter })
				local ValueBoxStroke = Library:Create("UIStroke", {
					Color = Library.OutlineColor,
					Thickness = 1,
					Transparency = 0.5,
					Parent = ValueBoxOuter,
				})
				Library:AddToRegistry(ValueBoxStroke, { Color = "OutlineColor" })
				local ValueBoxInner = Library:Create("Frame", {
					BackgroundColor3 = Library.MainColor,
					BorderSizePixel = 0,
					Size = UDim2.new(1, 0, 1, 0),
					ZIndex = 6,
					Parent = ValueBoxOuter,
				})
				Library:Create("UICorner", { CornerRadius = UDim.new(1, 0), Parent = ValueBoxInner })
				Library:AddToRegistry(ValueBoxInner, { BackgroundColor3 = "MainColor" })
				Library:OnHighlight(
					ValueBoxOuter,
					ValueBoxStroke,
					{ Color = "AccentColor", Transparency = 0 },
					{ Color = "OutlineColor", Transparency = 0.5 }
				)
				ValueBox = Library:Create("TextBox", {
					BackgroundTransparency = 1,
					Size = UDim2.new(1, -6, 1, 0),
					Position = UDim2.new(0, 3, 0, 0),
					FontFace = Library.Font,
					PlaceholderColor3 = Color3.fromRGB(190, 190, 190),
					PlaceholderText = "",
					Text = tostring(Slider.Value),
					TextColor3 = Library.FontColor,
					TextSize = 12,
					TextStrokeTransparency = 0.5,
					TextStrokeColor3 = Color3.new(0, 0, 0),
					TextXAlignment = Enum.TextXAlignment.Center,
					ClearTextOnFocus = false,
					ClipsDescendants = true,
					ZIndex = 7,
					Parent = ValueBoxInner,
				})
				Library:ApplyTextStroke(ValueBox)
				if type(Info.Tooltip) == "string" then
					Library:AddToolTip(Info.Tooltip, ValueBoxOuter)
				end
				-- Commit only on Enter; a plain click-away restores the real value so a half-typed number never sticks.
				ValueBox.FocusLost:Connect(function(enter)
					if enter then
						Slider:SetValue(ValueBox.Text)
						Library:AttemptSave()
					end
					ValueBox.Text = tostring(Slider.Value)
				end)
			end
			function Slider:UpdateColors()
				Fill.BackgroundColor3 = Library.AccentColor
			end
			function Slider:Display()
				local Suffix = Info.Suffix or ""
				local Percent = 0
				local Fraction = 0
				if Slider.Max ~= Slider.Min then
					Fraction = math.clamp((Slider.Value - Slider.Min) / (Slider.Max - Slider.Min), 0, 1)
					Percent = math.floor(Fraction * 100 + 0.5)
				end
				if Info.Compact then
					DisplayLabel.Text = string.format("%s: %s%s (%d%%)", Info.Text, Slider.Value, Suffix, Percent)
				elseif Info.HideMax then
					DisplayLabel.Text = string.format("%s%s (%d%%)", Slider.Value, Suffix, Percent)
				else
					DisplayLabel.Text = string.format("%s/%s%s (%d%%)", Slider.Value, Slider.Max, Suffix, Percent)
				end
				if SliderInner.AbsoluteSize.X > 0 then
					Slider.MaxSize = SliderInner.AbsoluteSize.X
				end
				-- Scale-based positioning, always geometrically correct relative to the track's real size.
				local knobRadius = 7
				Fill.Size = UDim2.new(Fraction, knobRadius, 1, 0)
				Knob.Position = UDim2.new(Fraction, math.floor(knobRadius - (14 * Fraction)), 0.5, 0)
				HideBorderRight.Visible = not (Fraction == 1 or Fraction == 0)
				-- Mirror the live value into the type-in box, but never while it's focused so a drag can't yank the caret out from under you mid-edit.
				if ValueBox and not ValueBox:IsFocused() then
					ValueBox.Text = tostring(Slider.Value)
				end
			end
			function Slider:OnChanged(Func)
				Slider.Changed = Func
				Func(Slider.Value)
			end
			local function Round(Value)
				if Slider.Rounding == 0 then
					return math.floor(Value)
				end
				return tonumber(string.format("%." .. Slider.Rounding .. "f", Value))
			end
			function Slider:GetValueFromXOffset(X)
				return Round(Library:MapValue(X, 0, Slider.MaxSize, Slider.Min, Slider.Max))
			end
			function Slider:SetRawValue(Value)
				local Num = tonumber(Value)
				if not Num then
					return
				end
				Num = math.clamp(Num, Slider.Min, Slider.Max)
				Num = Round(Num)
				Slider.Value = Num
				Slider:Display()
			end
			function Slider:SetValue(Str)
				local Num = tonumber(Str)
				if not Num then
					return
				end
				Num = math.clamp(Num, Slider.Min, Slider.Max)
				Num = Round(Num)
				Slider.Value = Num
				Slider:Display()
				Library:SafeCallback("Slider_Callback" .. "_" .. (Idx or ""), Slider.Callback, Slider.Value)
				Library:SafeCallback("Slider_Changed" .. "_" .. (Idx or ""), Slider.Changed, Slider.Value)
			end
			local CurrentAmount = 0.01
			local sliderDragging = false
			local sliderMPos = 0
			local sliderGPos = 0
			local sliderDiff = 0
			SliderInner.InputBegan:Connect(function(Input)
				if Input.UserInputType == Enum.UserInputType.MouseButton1 and not Library:MouseIsOverOpenedFrame() then
					sliderMPos = Mouse.X
					sliderGPos = Fill.AbsoluteSize.X
					sliderDiff = sliderMPos - (Fill.AbsolutePosition.X + sliderGPos)
					sliderDragging = true
					Library.SliderDragging = true
				end
				if Input.KeyCode == Enum.KeyCode.Minus then
					CurrentAmount = math.max(CurrentAmount / 10, 0.00001)
				end
				if Input.KeyCode == Enum.KeyCode.Equals and (CurrentAmount * 10) <= Slider.Max then
					CurrentAmount = CurrentAmount * 10
				end
				if Input.KeyCode == Enum.KeyCode.Right then
					Slider:SetValue(Slider.Value + CurrentAmount)
				end
				if Input.KeyCode == Enum.KeyCode.Left then
					Slider:SetValue(Slider.Value - CurrentAmount)
				end
			end)
			SliderInner.InputEnded:Connect(function(Input)
				if Input.UserInputType == Enum.UserInputType.MouseButton1 then
					sliderDragging = false
					Library.SliderDragging = false
					Library:AttemptSave()
				end
			end)
			InputService.InputChanged:Connect(function(Input)
				if sliderDragging and Input.UserInputType == Enum.UserInputType.MouseMovement then
					local nX = math.clamp(sliderGPos + (Mouse.X - sliderMPos) + sliderDiff, 0, Slider.MaxSize)
					local nValue = Slider:GetValueFromXOffset(nX)
					local OldValue = Slider.Value
					Slider.Value = nValue
					Slider:Display()
					if nValue ~= OldValue then
						Library:SafeCallback("Slider_Callback" .. "_" .. (Idx or ""), Slider.Callback, Slider.Value)
						Library:SafeCallback("Slider_Changed" .. "_" .. (Idx or ""), Slider.Changed, Slider.Value)
					end
				end
			end)
			-- SliderInner's AbsoluteSize isn't populated yet the first time Display runs, so the fill bar was computing its width against a hardcoded guess instead of the real rendered width.
			SliderInner:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
				Slider:Display()
			end)
			Slider:Display()
			Groupbox:AddBlank(Info.BlankSize or 6)
			Groupbox:Resize()
			if Idx then
				Options[Idx] = Slider
			end
			if self.SearchContext and Info.Text then
				Library:RegisterSearchable({
					Text = Info.Text,
					TabName = self.SearchContext.TabName,
					SubName = self.SearchContext.SubName,
					GroupName = self.SearchContext.GroupName,
					Side = self.SearchContext.Side,
					ElementType = "Slider",
					Idx = Idx,
					Row = SliderOuter,
					Show = self.SearchContext.Show,
				})
			end
			return Slider
		end
		function Funcs:AddDropdown(Idx, Info)
			if Info.SpecialType == "Player" then
				Info.Values = GetPlayersString()
				Info.AllowNull = true
			elseif Info.SpecialType == "Team" then
				Info.Values = GetTeamsString()
				Info.AllowNull = true
			end
			assert(Info.Values, "AddDropdown: Missing dropdown value list.")
			assert(
				Info.AllowNull or Info.Default,
				"AddDropdown: Missing default value. Pass `AllowNull` as true if this was intentional."
			)
			if not Info.Text then
				Info.Compact = true
			end
			local Dropdown = {
				Values = Info.Values,
				Value = Info.Multi and {},
				SaveValues = Info.SaveValues or false,
				Multi = Info.Multi,
				Type = "Dropdown",
				SpecialType = Info.SpecialType, -- can be either 'Player' or 'Team'
				Callback = Info.Callback or function(Value) end,
			}
			local Groupbox = self
			local Container = Groupbox.Container
			local RelativeOffset = 0
			if not Info.Compact then
				local DropdownLabel = Library:CreateLabel({
					Size = UDim2.new(1, 0, 0, 10),
