			Library:AddToRegistry(Header, { BackgroundColor3 = "MainColor" })
			local HeaderLabel = Library:CreateLabel({
				Position = UDim2.new(0, 7, 0, 0),
				Size = UDim2.new(1, -30, 1, 0),
				Text = Text,
				TextSize = 12,
				Font = Enum.Font.GothamBold,
				TextXAlignment = Enum.TextXAlignment.Left,
				ZIndex = 7,
				Parent = Header,
			})
			Library:AddToRegistry(HeaderLabel, { TextColor3 = "AccentColor" })
			local Arrow = Library:CreateLabel({
				Position = UDim2.new(1, -22, 0, 0),
				Size = UDim2.new(0, 18, 1, 0),
				Text = ">",
				TextSize = 14,
				TextXAlignment = Enum.TextXAlignment.Center,
				Rotation = Section.Expanded and 90 or 0,
				ZIndex = 7,
				Parent = Header,
			})
			Library:AddToRegistry(Arrow, { TextColor3 = "AccentColor" })
			local Holder = Library:Create("Frame", {
				BackgroundTransparency = 1,
				ClipsDescendants = true,
				Size = UDim2.new(1, 0, 0, 0),
				Visible = Section.Expanded,
				Parent = ParentContainer,
			})
			local Content = Library:Create("Frame", {
				BackgroundTransparency = 1,
				Size = UDim2.new(1, -6, 0, 0),
				Position = UDim2.new(0, 6, 0, 0),
				Parent = Holder,
			})
			local Layout = Library:Create("UIListLayout", {
				FillDirection = Enum.FillDirection.Vertical,
				SortOrder = Enum.SortOrder.LayoutOrder,
				Parent = Content,
			})
			function Section:Resize()
				local Height = GetVisibleContentHeight(Content)
				Content.Size = UDim2.new(1, -6, 0, Height)
				Holder.Size = UDim2.new(1, 0, 0, Section.Expanded and Height or 0)
				ParentGroupbox:Resize()
				ScheduleLayoutRefresh(function()
					if Holder.Parent then ParentGroupbox:Resize() end
				end)
			end
			function Section:SetOpen(State)
				Section.Expanded = State
				Holder.Visible = State
				TweenService:Create(Arrow, TweenInfo.new(0.16, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
					Rotation = State and 90 or 0,
				}):Play()
				Section:Resize()
			end
			Layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
				task.defer(function()
					if Holder.Parent then Section:Resize() end
				end)
			end)
			Header.Activated:Connect(function()
				Section:SetOpen(not Section.Expanded)
			end)
			Section.Container = Content
			setmetatable(Section, BaseGroupbox)
			Section:Resize()
			return Section
		end
		function Funcs:AddDependencyBox()
			local Depbox = {
				Dependencies = {},
			}
			local Groupbox = self
			local Container = Groupbox.Container
			local Holder = Library:Create("Frame", {
				BackgroundTransparency = 1,
				Size = UDim2.new(1, 0, 0, 0),
				Visible = false,
				Parent = Container,
			})
			local Frame = Library:Create("Frame", {
				BackgroundTransparency = 1,
				Size = UDim2.new(1, 0, 1, 0),
				Visible = true,
				Parent = Holder,
			})
			local Layout = Library:Create("UIListLayout", {
				FillDirection = Enum.FillDirection.Vertical,
				SortOrder = Enum.SortOrder.LayoutOrder,
				Parent = Frame,
			})
			function Depbox:Resize()
				Holder.Size = UDim2.new(1, 0, 0, GetVisibleContentHeight(Frame))
				Groupbox:Resize()
				ScheduleLayoutRefresh(function()
					if Holder.Parent then Groupbox:Resize() end
				end)
			end
			Layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
				Depbox:Resize()
			end)
			Holder:GetPropertyChangedSignal("Visible"):Connect(function()
				Depbox:Resize()
			end)
			function Depbox:Update()
				for _, Dependency in next, Depbox.Dependencies do
					local Elem = Dependency[1]
					local Value = Dependency[2]
					local satisfied = true
					if Elem.Type == "Toggle" then
						satisfied = Elem.Value == Value
					elseif Elem.Type == "Dropdown" then
						if Elem.Multi then
							-- Multi dropdown: satisfied when the selected set contains Value.
							satisfied = type(Elem.Value) == "table" and Elem.Value[Value] == true
						else
							satisfied = Elem.Value == Value
						end
					end
					if not satisfied then
						Holder.Visible = false
						Depbox:Resize()
						return
					end
				end
				Holder.Visible = true
				Depbox:Resize()
			end
			function Depbox:SetupDependencies(Dependencies)
				for _, Dependency in next, Dependencies do
					assert(type(Dependency) == "table", "SetupDependencies: Dependency is not of type `table`.")
					assert(Dependency[1], "SetupDependencies: Dependency is missing element argument.")
					assert(Dependency[2] ~= nil, "SetupDependencies: Dependency is missing value argument.")
				end
				Depbox.Dependencies = Dependencies
				Depbox:Update()
			end
			Depbox.Container = Frame
				-- Inherit parent search context so dependency-box elements still register (in-game search AND Features/WebBridge).
				Depbox.SearchContext = Groupbox.SearchContext
			setmetatable(Depbox, BaseGroupbox)
			table.insert(Library.DependencyBoxes, Depbox)
			return Depbox
		end
		BaseGroupbox.__index = Funcs
		BaseGroupbox.__namecall = function(Table, Key, ...)
			return Funcs[Key](...)
		end
	end
