	--- Manually override the Keybind List frame's width/height, in pixels.
	function Library:SetKeybindListSize(Width, Height)
		Library.KeybindSizeOverride = Library.KeybindSizeOverride or {}

		if Width ~= nil then
			Library.KeybindSizeOverride.Width = Width
		end

		if Height ~= nil then
			Library.KeybindSizeOverride.Height = Height
		end

		if Library.KeybindFrame then
			local CurrentSize = Library.KeybindFrame.Size
			local NewWidth = Library.KeybindSizeOverride.Width or CurrentSize.X.Offset
			local NewHeight = Library.KeybindSizeOverride.Height or CurrentSize.Y.Offset

			Library.KeybindFrame.Size = UDim2.new(0, NewWidth, 0, NewHeight)
		end
	end
	function Library:SetWatermark(Text)
		local X, Y = Library:GetTextBounds(Text, Library.Font, 14)
		Library.WatermarkText.Text = Text
		Library.Watermark.Size = UDim2.new(0, X + 15, 0, (Y * 1.5) + 3)
	end
	-- ── Mira toast notification ─────────────────────────────────────────────── Design language borrowed from Mira's Box UI: a compact, soft drop-shadowed panel with a live accent status dot, the message in a distinct weight, and the signature accent→transparent hairline that doubles as the countdown.
	function Library:_BuildNotification(Text, Time, AutoDismiss)
		if shared.Mira and shared.Mira.silent then
			return
		end

		local S = (tonumber(Options["NotificationScale"] and Options["NotificationScale"].Value) or 100) / 100
		local function R(n)
			return math.floor(n * S + 0.5)
		end

		-- Message typography (kept distinct from the menu's default Gotham)
		local BodyFont = Font.fromEnum(Enum.Font.GothamMedium)
		local BodySize = math.max(10, R(13))

		-- Metrics (compact single-row layout)
		local PadL, PadR, PadY = R(11), R(12), R(7)
		local DotSize = math.max(4, R(6))
		local DotGap = R(8)
		local Radius = math.max(4, R(7))
		local LineH = math.max(1, R(2))

		local MW, MH = Library:GetTextBounds(Text, BodyFont, BodySize)
		local FullX = PadL + DotSize + DotGap + MW + PadR + R(5)
		local FullY = MH + (PadY * 2)

		-- Holder — a fixed-size layout child so toasts stack in place (no reflow).
		local Holder = Library:Create("Frame", {
			BackgroundTransparency = 1,
			Size = UDim2.new(0, FullX, 0, FullY),
			ZIndex = 100,
			Parent = Library.NotificationArea,
		})

		-- Soft drop shadow (9-slice).
		local ShadowTrans = 0.55
		local Shadow = Library:Create("ImageLabel", {
			BackgroundTransparency = 1,
			Image = "rbxassetid://1316045217",
			ImageColor3 = Color3.new(0, 0, 0),
			ImageTransparency = 1,
			ScaleType = Enum.ScaleType.Slice,
			SliceCenter = Rect.new(10, 10, 118, 118),
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.new(0.5, 0, 0.5, R(5)),
			Size = UDim2.new(1, R(26), 1, R(26)),
			ZIndex = 100,
			Parent = Holder,
		})

		-- Card surface — CanvasGroup enables a clean whole-panel fade.
		local SlideOffset = R(20)
		local ok, Card = pcall(function()
			return Library:Create("CanvasGroup", {
				BackgroundColor3 = Library.MainColor,
				BackgroundTransparency = 0,
				GroupTransparency = 1,
				BorderSizePixel = 0,
				Position = UDim2.new(0, SlideOffset, 0, 0),
				Size = UDim2.new(1, 0, 1, 0),
				ZIndex = 101,
				Parent = Holder,
			})
		end)
		local CanFade = ok and Card ~= nil
		if not CanFade then
			Card = Library:Create("Frame", {
				BackgroundColor3 = Library.MainColor,
				BackgroundTransparency = 0,
				BorderSizePixel = 0,
				Position = UDim2.new(0, SlideOffset, 0, 0),
				Size = UDim2.new(1, 0, 1, 0),
				ZIndex = 101,
				Parent = Holder,
			})
		end
		Library:Create("UICorner", { CornerRadius = UDim.new(0, Radius), Parent = Card })
		Library:AddToRegistry(Card, { BackgroundColor3 = "MainColor" }, true)

		-- Opaque top-lit gradient for depth (theme-reactive, no transparency).
		local function SheenSequence()
			local H, Sat, V = Color3.toHSV(Library.MainColor)
			local Light = Color3.fromHSV(H, Sat, math.min(1, V * 1.4))
			return ColorSequence.new({
				ColorSequenceKeypoint.new(0, Light),
				ColorSequenceKeypoint.new(1, Library.MainColor),
			})
		end
		local Sheen = Library:Create("UIGradient", {
			Color = SheenSequence(),
			Rotation = 90,
			Parent = Card,
		})
		Library:AddToRegistry(Sheen, { Color = SheenSequence })

		-- Hairline border
		local Stroke = Library:Create("UIStroke", {
			ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
			Color = Library.OutlineColor,
			Thickness = 1,
			Transparency = 0.4,
			Parent = Card,
		})
		Library:AddToRegistry(Stroke, { Color = "OutlineColor" }, true)

		-- Padded content region (keeps the bottom hairline free of the padding)
		local Content = Library:Create("Frame", {
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 1, 0),
			ZIndex = 102,
			Parent = Card,
		})
		Library:Create("UIPadding", {
			PaddingLeft = UDim.new(0, PadL),
			PaddingRight = UDim.new(0, PadR),
			PaddingTop = UDim.new(0, PadY),
			PaddingBottom = UDim.new(0, PadY),
			Parent = Content,
		})

		-- Live accent status dot
		local Dot = Library:Create("Frame", {
			AnchorPoint = Vector2.new(0, 0.5),
			BackgroundColor3 = Library.AccentColor,
			BorderSizePixel = 0,
			Position = UDim2.new(0, 0, 0.5, 0),
			Size = UDim2.new(0, DotSize, 0, DotSize),
			ZIndex = 104,
			Parent = Content,
		})
		Library:Create("UICorner", { CornerRadius = UDim.new(1, 0), Parent = Dot })
		Library:AddToRegistry(Dot, { BackgroundColor3 = "AccentColor" }, true)

		-- Message body (single line, vertically centered)
		local Message = Library:Create("TextLabel", {
			BackgroundTransparency = 1,
			FontFace = BodyFont,
			AnchorPoint = Vector2.new(0, 0.5),
			Position = UDim2.new(0, DotSize + DotGap, 0.5, 0),
			Size = UDim2.new(1, -(DotSize + DotGap), 1, 0),
			Text = Text,
			TextColor3 = Library.FontColor,
			TextSize = BodySize,
			TextStrokeTransparency = 1,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextYAlignment = Enum.TextYAlignment.Center,
			ZIndex = 103,
			Parent = Content,
		})
		Library:AddToRegistry(Message, { TextColor3 = "FontColor" }, true)

		-- Signature accent→transparent hairline.
		local Line = Library:Create("Frame", {
			AnchorPoint = Vector2.new(0, 1),
			BackgroundColor3 = Library.AccentColor,
			BorderSizePixel = 0,
			Position = UDim2.new(0, PadL, 1, 0),
			Size = UDim2.new(1, -(PadL + PadR), 0, LineH),
			ZIndex = 104,
			Parent = Card,
		})
		Library:AddToRegistry(Line, { BackgroundColor3 = "AccentColor" }, true)
		Library:Create("UIGradient", {
			Rotation = 0,
			Transparency = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 0),
				NumberSequenceKeypoint.new(0.35, 0.1),
				NumberSequenceKeypoint.new(1, 1),
			}),
			Parent = Line,
		})

		local Duration = Time or 5
		local Fast = AutoDismiss and (Duration - 0.8) <= 0.3 or false
		local SlideTime = Fast and 0.14 or 0.34
		local RestPos = UDim2.new(0, 0, 0, 0)
		local OutPos = UDim2.new(0, SlideOffset, 0, 0)

		-- Entry: slide in + fade in (card) and fade in (shadow)
		local function Ease(t)
			return TweenInfo.new(t, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
		end
		local EntryGoal = { Position = RestPos }
		if CanFade then
			EntryGoal.GroupTransparency = 0
		end
		pcall(function()
			TweenService:Create(Card, Ease(SlideTime), EntryGoal):Play()
		end)
		pcall(function()
			TweenService:Create(Shadow, Ease(SlideTime), { ImageTransparency = ShadowTrans }):Play()
		end)

		local Dismissed = false
		local function TweenOut()
			if Dismissed then
				return
			end
			Dismissed = true
			local ExitGoal = { Position = OutPos }
			if CanFade then
				ExitGoal.GroupTransparency = 1
			end
			pcall(function()
				TweenService:Create(Card, Ease(SlideTime), ExitGoal):Play()
			end)
			pcall(function()
				TweenService:Create(Shadow, Ease(SlideTime), { ImageTransparency = 1 }):Play()
			end)
			task.wait(SlideTime)
			Holder:Destroy()
		end

		-- Hover: warm the border to accent; click or drag-over dismisses
		Card.MouseEnter:Connect(function()
			if Dismissed then
				return
			end
			pcall(function()
				TweenService:Create(Stroke, TweenInfo.new(0.15, Enum.EasingStyle.Quad), { Transparency = 0.05, Color = Library.AccentColor }):Play()
			end)
			if game:GetService("UserInputService"):IsMouseButtonPressed(Enum.UserInputType.MouseButton1) then
				TweenOut()
			end
		end)
		Card.MouseLeave:Connect(function()
			if Dismissed then
				return
			end
			pcall(function()
				TweenService:Create(Stroke, TweenInfo.new(0.2, Enum.EasingStyle.Quad), { Transparency = 0.4, Color = Library.OutlineColor }):Play()
			end)
		end)
		Card.InputBegan:Connect(function(Input)
			if Input.UserInputType == Enum.UserInputType.MouseButton1 then
				TweenOut()
			end
		end)

		if AutoDismiss then
			-- Retract the hairline across the toast's lifetime as a countdown
			task.spawn(function()
				task.wait(SlideTime)
				if not Dismissed then
					pcall(function()
						TweenService:Create(
							Line,
							TweenInfo.new(Duration, Enum.EasingStyle.Linear),
							{ Size = UDim2.new(0, 0, 0, LineH) }
						):Play()
					end)
				end
			end)
			task.spawn(function()
				task.wait(Duration + SlideTime)
				TweenOut()
			end)
		end

		return TweenOut
	end

	function Library:ManuallyManagedNotify(Text)
		return Library:_BuildNotification(Text, nil, false)
	end
	function Library:Notify(Text, Time)
		return Library:_BuildNotification(Text, Time, true)
	end
	function Library:CreateWindow(...)
		local Arguments = { ... }
		local Config = { AnchorPoint = Vector2.zero }
		if type(...) == "table" then
			Config = ...
		else
			Config.Title = Arguments[1]
			Config.AutoShow = Arguments[2] or false
		end
		if type(Config.Title) ~= "string" then
			Config.Title = "No title"
		end
		if type(Config.TabPadding) ~= "number" then
			Config.TabPadding = 0
		end
		if type(Config.MenuFadeTime) ~= "number" then
			Config.MenuFadeTime = 0.2
		end
		if typeof(Config.Position) ~= "UDim2" then
			Config.Position = UDim2.fromOffset(175, 50)
		end
		if typeof(Config.Size) ~= "UDim2" then
			Config.Size = UDim2.fromOffset(550, 600)
		end
		if Config.Center then
			Config.AnchorPoint = Vector2.new(0.5, 0.5)
			Config.Position = UDim2.fromScale(0.5, 0.5)
		end
		local Window = {
			Tabs = {},
		}

		-- Ã¢â€â‚¬Ã¢â€â‚¬ Sakura color constants Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬
		local BG_DARK = Library.BackgroundColor
		local BG_TOPBAR = Library.MainColor
		local BG_TITLEBAR = Library.BackgroundColor
		local BORDER_COL = Library.OutlineColor

		-- Outer shell
		local Outer = Library:Create("Frame", {
			AnchorPoint = Config.AnchorPoint,
			BackgroundColor3 = BG_DARK,
			BorderSizePixel = 0,
			Position = Config.Position,
			Size = Config.Size,
			Visible = false,
			ZIndex = 1,
			Parent = ScreenGui,
		})
		Library:Create("UIScale", {
			Scale = 1,
			Parent = Outer,
		})
		Library:Create("UICorner", { CornerRadius = UDim.new(0, 0), Parent = Outer })
		-- Drop shadow
		local Shadow = Library:Create("Frame", {
			AnchorPoint = Vector2.new(0.5, 0.5),
			BackgroundColor3 = Color3.fromRGB(0, 0, 0),
			BackgroundTransparency = 0.95,
			BorderSizePixel = 0,
			Position = UDim2.new(0.5, 0, 0.5, 4),
			Size = UDim2.new(1, 10, 1, 10),
			ZIndex = 0,
			Parent = Outer,
		})
		Library:Create("UICorner", { CornerRadius = UDim.new(0, 0), Parent = Shadow })
		-- UIStroke for elegant border
		local OuterStroke = Library:Create("UIStroke", {
			Color = Library.OutlineColor,
			Thickness = 1,
			Transparency = 0,
			Parent = Outer,
		})
		Library:AddToRegistry(OuterStroke, { Color = "OutlineColor" })
		Library:MakeDraggable(Outer, 32)
		Library:AddToRegistry(Outer, { BackgroundColor3 = "BackgroundColor" })

		-- Edge Glow Layers
		local GlowLayers = {}
		local GlowConfig = {
			{ BaseExpand = 0.166, BaseTrans = 0.75 },
			{ BaseExpand = 0.388, BaseTrans = 0.85 },
			{ BaseExpand = 0.666, BaseTrans = 0.92 },
			{ BaseExpand = 1.0,   BaseTrans = 0.96 },
		}

		for i, cfg in ipairs(GlowConfig) do
			local GlowLayer = Library:Create("Frame", {
				Name = "GlowLayer" .. i,
				AnchorPoint = Vector2.new(0.5, 0.5),
				BackgroundColor3 = Library.AccentColor,
				BackgroundTransparency = 1,
				BorderSizePixel = 0,
				Position = UDim2.new(0.5, 0, 0.5, 0),
				Size = UDim2.new(1, 0, 1, 0),
				ZIndex = 0,
				Visible = false,
				Parent = Outer,
			})

			Library:Create("UICorner", {
				Name = "UICorner",
				CornerRadius = UDim.new(0, 0),
				Parent = GlowLayer,
			})

			GlowLayers[i] = GlowLayer
		end

		local BreatheStep = 0
		Library:GiveSignal(RunService.RenderStepped:Connect(function(deltaTime)
			local enabled = Toggles and Toggles.EdgeGlow and Toggles.EdgeGlow.Value or false
			if not enabled then
				for _, layer in ipairs(GlowLayers) do
					layer.Visible = false
				end
				return
			end

			local color = Options and Options.EdgeGlowColor and Options.EdgeGlowColor.Value or Library.AccentColor
			local maxSize = Options and Options.EdgeGlowSize and Options.EdgeGlowSize.Value or 60
			local opacity = Options and Options.EdgeGlowOpacity and Options.EdgeGlowOpacity.Value / 100 or 1
			local breathe = Toggles and Toggles.EdgeGlowBreathe and Toggles.EdgeGlowBreathe.Value or false

			local currentSize = maxSize
			local currentOpacity = opacity

			if breathe then
				BreatheStep = BreatheStep + deltaTime * 2
				local breatheMod = 0.8 + (math.sin(BreatheStep) * 0.5 + 0.5) * 0.2
				currentSize = maxSize * breatheMod
				currentOpacity = opacity * breatheMod
			end

			for i, cfg in ipairs(GlowConfig) do
				local layer = GlowLayers[i]
				local corner = layer.UICorner

				layer.Visible = true
				layer.BackgroundColor3 = color

				local targetAlpha = (1 - cfg.BaseTrans) * currentOpacity
				layer.BackgroundTransparency = 1 - targetAlpha

				local expand = math.round(cfg.BaseExpand * currentSize)
				layer.Size = UDim2.new(1, expand * 2, 1, expand * 2)
				corner.CornerRadius = UDim.new(0, expand)
			end
		end))

		-- Main body
		local Inner = Library:Create("Frame", {
			BackgroundColor3 = BG_DARK,
			BorderSizePixel = 0,
			Position = UDim2.new(0, 0, 0, 0),
			Size = UDim2.new(1, 0, 1, 0),
			ZIndex = 2,
			Parent = Outer,
		})
		Library:Create("UICorner", { CornerRadius = UDim.new(0, 0), Parent = Inner })
		Library:AddToRegistry(Inner, { BackgroundColor3 = "BackgroundColor" })
			-- Whole-window background gradient: one continuous gradient across the entire body (not per-panel), so the UI Gradient control never seams.
			local InnerGradient = Library:Create("UIGradient", {
				Color = Library:SurfaceSequence(Library.BackgroundColor),
				Rotation = 90,
				Parent = Inner,
			})
			Library:AddToRegistry(InnerGradient, {
				Color = function()
					return Library:SurfaceSequence(Library.BackgroundColor)
				end,
			})
			Library:RegisterUIGradient(InnerGradient, "BackgroundColor")
			Library:UpdateUIGradients()

		-- â”€â”€ TITLE BAR (drag region, title text) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
		local TitleBar = Library:Create("Frame", {
			BackgroundColor3 = BG_TITLEBAR,
			BackgroundTransparency = 0,
			BorderSizePixel = 0,
			Position = UDim2.new(0, 0, 0, 0),
			Size = UDim2.new(1, 0, 0, 30),
			ZIndex = 3,
			Parent = Inner,
		})
		Library:Create("UICorner", { CornerRadius = UDim.new(0, 0), Parent = TitleBar })
		Library:AddToRegistry(TitleBar, { BackgroundColor3 = "BackgroundColor" })
		-- cover bottom rounded corners
		local TitleBarCorner = Library:Create("Frame", {
			BackgroundColor3 = BG_TITLEBAR,
			BackgroundTransparency = 0,
			BorderSizePixel = 0,
			Position = UDim2.new(0, 0, 1, -12),
			Size = UDim2.new(1, 0, 0, 12),
			ZIndex = 3,
			Parent = TitleBar,
		})
		Library:AddToRegistry(TitleBarCorner, { BackgroundColor3 = "BackgroundColor" })
		local WindowLabel = Library:CreateLabel({
			Position = UDim2.new(0, 14, 0, 0),
			Size = UDim2.new(0.6, 0, 1, 0),
			Text = Config.Title,
			TextSize = 18,
			Font = Enum.Font.GothamBlack,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextColor3 = Library.FontColor,
			TextStrokeColor3 = Color3.fromRGB(18, 12, 25),
			TextStrokeTransparency = 0.35,
			Visible = true,
			ZIndex = 4,
			Parent = TitleBar,
		})
		local TitleGradient = Library:Create("UIGradient", {
			Color = ColorSequence.new({
				ColorSequenceKeypoint.new(0, Library.FontColor),
				ColorSequenceKeypoint.new(1, Library:GetDarkerColor(Library.FontColor)),
			}),
			Rotation = 0,
			Parent = WindowLabel,
		})
		Library:AddToRegistry(TitleGradient, { Color = function() return ColorSequence.new({ ColorSequenceKeypoint.new(0, Library.FontColor), ColorSequenceKeypoint.new(1, Library:GetDarkerColor(Library.FontColor)) }) end })
		Library:CreateLabel({
			Position = UDim2.new(0.5, 0, 0, 0),
