		-- ── SEARCH LOGIC ───────────────────────────────────────────────────
		do
			local MAX_RESULTS = 8
			local ROW_HEIGHT = 24
			local SearchRows = {}

			-- Fuzzy score: lower is better.
			local function FuzzyScore(text, query)
				local lowerText = text:lower()
				local lowerQuery = query:lower()
				if lowerQuery == "" then
					return 0
				end
				-- Exact substring is always best, ranked by position.
				local at = lowerText:find(lowerQuery, 1, true)
				if at then
					return at - 1 + (lowerText == lowerQuery and -1000 or 0)
				end
				-- Subsequence match with gap penalty.
				local ti, score, lastMatch = 1, 0, nil
				for qi = 1, #lowerQuery do
					local ch = lowerQuery:sub(qi, qi)
					local found = lowerText:find(ch, ti, true)
					if not found then
						return nil
					end
					if lastMatch then
						score = score + (found - lastMatch) -- gap since last matched char
					else
						score = score + found -- reward matching early
					end
					lastMatch = found
					ti = found + 1
				end
				return 100 + score -- rank all subsequence hits below substring hits
			end

			-- Flash a feature row so the user can spot it after navigating.
			local function FlashRow(Row)
				if not Row or not Row.Parent then
					return
				end
				local flash = Library:Create("Frame", {
					BackgroundColor3 = Library.AccentColor,
					BackgroundTransparency = 0.5,
					BorderSizePixel = 0,
					Position = UDim2.new(0, -4, 0, -2),
					Size = UDim2.new(1, 8, 1, 4),
					ZIndex = 20,
					Parent = Row,
				})
				Library:Create("UICorner", { CornerRadius = UDim.new(0, 0), Parent = flash })
				task.spawn(function()
					for i = 1, 3 do
						TweenService:Create(flash, TweenInfo.new(0.28), { BackgroundTransparency = 1 }):Play()
						task.wait(0.32)
						if i < 3 and flash.Parent then
							flash.BackgroundTransparency = 0.5
							task.wait(0.12)
						end
					end
					if flash.Parent then
						flash:Destroy()
					end
				end)
			end

			-- Scroll a ScrollingFrame so `Row` is visible near the top.
			local function ScrollTo(Row)
				local scroller = Row.Parent
				while scroller and not scroller:IsA("ScrollingFrame") do
					scroller = scroller.Parent
				end
				if not scroller then
					return
				end
				local ok, y = pcall(function()
					return Row.AbsolutePosition.Y - scroller.AbsolutePosition.Y + scroller.CanvasPosition.Y - 6
				end)
				if ok then
					scroller.CanvasPosition = Vector2.new(0, math.max(0, y))
				end
			end

			local function CloseList()
				SearchList.Visible = false
			end

			local function NavigateTo(Entry)
				if Entry.Show then
					pcall(Entry.Show)
				end
				task.defer(function()
					ScrollTo(Entry.Row)
					FlashRow(Entry.Row)
				end)
			end

			local function ClearRows()
				for _, r in next, SearchRows do
					r:Destroy()
				end
				table.clear(SearchRows)
			end

			-- Build one clickable suggestion row: "Feature · Tab".
			local function MakeRow(Entry, order)
				local Row = Library:Create("Frame", {
					BackgroundColor3 = Library.MainColor,
					BackgroundTransparency = 0.4,
					BorderSizePixel = 0,
					Size = UDim2.new(1, 0, 0, ROW_HEIGHT - 2),
					LayoutOrder = order,
					ZIndex = 22,
					Parent = SearchScroll,
				})
				Library:Create("UICorner", { CornerRadius = UDim.new(0, 0), Parent = Row })
				local Name = Library:CreateLabel({
					BackgroundTransparency = 1,
					Position = UDim2.new(0, 8, 0, 0),
					Size = UDim2.new(0.62, -8, 1, 0),
					Text = Entry.Text,
					TextSize = 12,
					Font = Enum.Font.Gotham,
					TextColor3 = Library.FontColor,
					TextXAlignment = Enum.TextXAlignment.Left,
					TextTruncate = Enum.TextTruncate.AtEnd,
					ZIndex = 23,
					Parent = Row,
				})
				local crumb = Entry.TabName or ""
				if Entry.SubName then
					crumb = crumb .. " \226\128\186 " .. Entry.SubName -- ›
				end
				Library:CreateLabel({
					BackgroundTransparency = 1,
					Position = UDim2.new(0.62, 0, 0, 0),
					Size = UDim2.new(0.38, -8, 1, 0),
					Text = crumb,
					TextSize = 11,
					Font = Enum.Font.Gotham,
					TextColor3 = Library:GetDarkerColor(Library.FontColor),
					TextXAlignment = Enum.TextXAlignment.Right,
					TextTruncate = Enum.TextTruncate.AtEnd,
					ZIndex = 23,
					Parent = Row,
				})
				local Btn = Library:Create("TextButton", {
					BackgroundTransparency = 1,
					Size = UDim2.new(1, 0, 1, 0),
					Text = "",
					ZIndex = 24,
					Parent = Row,
				})
				Btn.MouseEnter:Connect(function()
					Row.BackgroundTransparency = 0
					Name.TextColor3 = Library.AccentColor
				end)
				Btn.MouseLeave:Connect(function()
					Row.BackgroundTransparency = 0.4
					Name.TextColor3 = Library.FontColor
				end)
				Btn.MouseButton1Click:Connect(function()
					NavigateTo(Entry)
					SearchBox.Text = ""
					CloseList()
				end)
				table.insert(SearchRows, Row)
			end

			local function Refresh()
				local query = SearchBox.Text
				ClearRows()
				if query == "" then
					CloseList()
					return
				end
				-- Score & collect matches.
				local matches = {}
				for _, Entry in next, Library.SearchIndex do
					local s = FuzzyScore(Entry.Text, query)
					if s then
						matches[#matches + 1] = { entry = Entry, score = s }
					end
				end
				table.sort(matches, function(a, b)
					if a.score == b.score then
						return a.entry.Text < b.entry.Text
					end
					return a.score < b.score
				end)
				if #matches == 0 then
					CloseList()
					return
				end
				local shown = math.min(#matches, MAX_RESULTS)
				for i = 1, shown do
					MakeRow(matches[i].entry, i)
				end
				SearchList.Size = UDim2.new(0, 220, 0, shown * ROW_HEIGHT + 4)
				SearchList.Visible = true
			end

			SearchBox:GetPropertyChangedSignal("Text"):Connect(Refresh)
			SearchBox.Focused:Connect(function()
				if SearchBox.Text ~= "" then
					Refresh()
				end
			end)
			-- Close the list when clicking elsewhere (but not on the box or list itself).
			Library:GiveSignal(InputService.InputBegan:Connect(function(Input)
				if Input.UserInputType ~= Enum.UserInputType.MouseButton1 then
					return
				end
				if not SearchList.Visible then
					return
				end
				if Library:IsMouseOverFrame(SearchList) or Library:IsMouseOverFrame(SearchOuter) then
					return
				end
				CloseList()
			end))
		end

