						ColorSequenceKeypoint.new(0.3, Library.OutlineColor),
						ColorSequenceKeypoint.new(1, Library.BackgroundColor),
					}),
					Transparency = NumberSequence.new({
						NumberSequenceKeypoint.new(0, 0),
						NumberSequenceKeypoint.new(0.7, 0),
						NumberSequenceKeypoint.new(1, 1),
					}),
					Parent = Sep,
				})
				Library:AddToRegistry(SepGradient, { Color = function() return ColorSequence.new({ ColorSequenceKeypoint.new(0, Library.AccentColor), ColorSequenceKeypoint.new(0.3, Library.OutlineColor), ColorSequenceKeypoint.new(1, Library.BackgroundColor) }) end })
				Library:AddToRegistry(Sep, { BackgroundColor3 = "OutlineColor" })
				local Container = Library:Create("Frame", {
					BackgroundTransparency = 1,
					Position = UDim2.new(0, 10, 0, 30),
					Size = UDim2.new(1, -20, 1, -34),
					ZIndex = 1,
					Parent = BoxInner,
				})
				local GroupboxLayout = Library:Create("UIListLayout", {
					FillDirection = Enum.FillDirection.Vertical,
					SortOrder = Enum.SortOrder.LayoutOrder,
					Parent = Container,
				})
				function Groupbox:Resize()
					if Groupbox.Collapsed then
						Container.Visible = false
						BoxOuter.Size = UDim2.new(1, 0, 0, 24)
