						Groupbox:Resize()
						ScheduleLayoutRefresh(function()
							if BoxOuter.Parent then Groupbox:Resize() end
						end)
					end
					CollapseButton.Activated:Connect(function()
						Groupbox:SetCollapsed(not Groupbox.Collapsed)
					end)
					Groupbox:SetCollapsed(DefaultOpen == false)
					return Groupbox
				end
				GroupboxLayout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
					task.defer(function()
						if BoxOuter.Parent then
							Groupbox:Resize()
						end
					end)
				end)
				Groupbox.Container = Container
				-- Search: remember which tab this groupbox lives on.
				Groupbox.SearchContext = {
					TabName = Name,
					SubName = nil,
					GroupName = Info.Name,
					Side = Info.Side,
					Show = function()
						Tab:ShowTab()
					end,
				}
				setmetatable(Groupbox, BaseGroupbox)
				Groupbox:AddBlank(3)
				Groupbox:Resize()
				Tab.GroupboxCount = Tab.GroupboxCount + 1
				Tab.Groupboxes[Info.Name] = Groupbox
				return Groupbox
			end
			function Tab:AddDynamicGroupbox(Name)
				if (Tab.GroupboxCount + Tab.TabboxCount) % 2 == 0 then
					return Tab:AddLeftGroupbox(Name)
				else
					return Tab:AddRightGroupbox(Name)
				end
			end
			function Tab:AddLeftGroupbox(Name)
				return Tab:AddGroupbox({ Side = 1, Name = Name })
			end
			function Tab:AddRightGroupbox(Name)
				return Tab:AddGroupbox({ Side = 2, Name = Name })
			end
			function Tab:AddTabbox(Info)
				-- Search: capture the outer tab (has :ShowTab) and its name before they get shadowed by the sub-tab's own `Tab`/`Name` locals below.
				local ParentTab = Tab
				local ParentTabName = Name
				local Tabbox = {
					Tabs = {},
				}
				local BoxOuter = Library:Create("Frame", {
					BackgroundColor3 = Library.MainColor,
					BorderSizePixel = 0,
					Size = UDim2.new(1, 0, 0, 0),
					ZIndex = 2,
					Parent = Info.Side == 1 and LeftSide or RightSide,
				})
				Library:Create("UICorner", { CornerRadius = UDim.new(0, 0), Parent = BoxOuter })
				local BoxStroke = Library:Create("UIStroke", {
					Color = Library.OutlineColor,
					Thickness = 1.5,
					Transparency = 0.15,
					Parent = BoxOuter,
				})
				Library:RegisterPanelStroke(BoxStroke)
				Library:AddToRegistry(BoxStroke, { Color = "OutlineColor" })
				Library:AddToRegistry(BoxOuter, {
					BackgroundColor3 = "MainColor",
				})
				local BoxInner = Library:Create("Frame", {
					BackgroundColor3 = Library.MainColor,
					BorderSizePixel = 0,
					Size = UDim2.new(1, 0, 1, 0),
					Position = UDim2.new(0, 0, 0, 0),
					ZIndex = 4,
					Parent = BoxOuter,
				})
				Library:Create("UICorner", { CornerRadius = UDim.new(0, 0), Parent = BoxInner })
				Library:AddToRegistry(BoxInner, {
					BackgroundColor3 = "MainColor",
				})
				-- Accent -> transparent hairline along the bottom edge (same accent gradient language as the notifications).
				local BottomAccent = Library:Create("Frame", {
					AnchorPoint = Vector2.new(0, 1),
					BackgroundColor3 = Library.AccentColor,
					BorderSizePixel = 0,
					Position = UDim2.new(0, 0, 1, 0),
					Size = UDim2.new(1, 0, 0, 2),
					ZIndex = 6,
					Parent = BoxInner,
				})
				Library:AddToRegistry(BottomAccent, { BackgroundColor3 = "AccentColor" })
				Library:Create("UIGradient", {
					Rotation = 0,
					Transparency = NumberSequence.new({
						NumberSequenceKeypoint.new(0, 0),
						NumberSequenceKeypoint.new(0.5, 0.35),
						NumberSequenceKeypoint.new(1, 1),
					}),
					Parent = BottomAccent,
				})
				Library.PanelAccents = Library.PanelAccents or {}
				table.insert(Library.PanelAccents, BottomAccent)
				Library:UpdatePanelAccents()
				-- Panel surface gradient (top-lit fill, like the notifications).
				local PanelSurface = Library:Create("UIGradient", {
					Color = Library:SurfaceSequence(Library.MainColor),
					Rotation = 90,
					Parent = BoxInner,
				})
				Library:AddToRegistry(PanelSurface, {
					Color = function()
						return Library:SurfaceSequence(Library.MainColor)
					end,
				})
				Library:RegisterUIGradient(PanelSurface, "MainColor")
				Library:UpdateUIGradients()
				local Highlight = Library:Create("Frame", {
					BackgroundTransparency = 1,
					BorderSizePixel = 0,
					Size = UDim2.new(0, 0, 0, 0),
					ZIndex = 1,
					Parent = BoxInner,
				})
				local TabboxButtons = Library:Create("Frame", {
					BackgroundTransparency = 1,
					Position = UDim2.new(0, 0, 0, 1),
					Size = UDim2.new(1, 0, 0, 18),
					ZIndex = 5,
					Parent = BoxInner,
				})
				Library:Create("UIListLayout", {
					FillDirection = Enum.FillDirection.Horizontal,
					HorizontalAlignment = Enum.HorizontalAlignment.Left,
					SortOrder = Enum.SortOrder.LayoutOrder,
					Parent = TabboxButtons,
				})
				function Tabbox:AddTab(Name)
					local Tab = {}
					local Button = Library:Create("Frame", {
						BackgroundTransparency = 1,
						BorderSizePixel = 0,
						Size = UDim2.new(0.5, 0, 1, 0),
						ZIndex = 6,
						Parent = TabboxButtons,
					})
					local ButtonLabel = Library:CreateLabel({
						Size = UDim2.new(1, 0, 1, 0),
						TextSize = 13,
						Font = Enum.Font.Gotham,
						Text = Name,
						TextColor3 = Library:GetDarkerColor(Library.FontColor),
						TextXAlignment = Enum.TextXAlignment.Center,
						ZIndex = 7,
						Parent = Button,
					})
					local Underline = Library:Create("Frame", {
						BackgroundColor3 = Library.AccentColor,
						BorderSizePixel = 0,
						AnchorPoint = Vector2.new(0.5, 0),
						Position = UDim2.new(0.5, 0, 1, -1),
						Size = UDim2.new(0.7, 0, 0, 1),
						BackgroundTransparency = 1,
						ZIndex = 8,
						Parent = Button,
					})
					Library:AddToRegistry(Underline, { BackgroundColor3 = "AccentColor" })
					local Block = Library:Create("Frame", {
						BackgroundColor3 = Library.BackgroundColor,
						BorderSizePixel = 0,
						Position = UDim2.new(0, 0, 1, 0),
						Size = UDim2.new(1, 0, 0, 1),
						Visible = false,
						ZIndex = 9,
						Parent = Button,
					})
					Library:AddToRegistry(Block, {
						BackgroundColor3 = "BackgroundColor",
					})
					local Container = Library:Create("Frame", {
						BackgroundTransparency = 1,
						Position = UDim2.new(0, 14, 0, 20),
						Size = UDim2.new(1, -18, 1, -20),
						ZIndex = 1,
						Visible = false,
						Parent = BoxInner,
					})
					local TabContentLayout = Library:Create("UIListLayout", {
						FillDirection = Enum.FillDirection.Vertical,
						SortOrder = Enum.SortOrder.LayoutOrder,
						Parent = Container,
					})
					function Tab:Show()
						for _, Tab in next, Tabbox.Tabs do
							Tab:Hide()
						end
						Container.Visible = true
						Block.Visible = true
						Underline.BackgroundTransparency = 0
						ButtonLabel.TextColor3 = Library.FontColor
						ButtonLabel.Font = Enum.Font.GothamBold
						Tab:Resize()
					end
					function Tab:Hide()
						Container.Visible = false
						Block.Visible = false
						Underline.BackgroundTransparency = 1
						ButtonLabel.TextColor3 = Library:GetDarkerColor(Library.FontColor)
						ButtonLabel.Font = Enum.Font.Gotham
					end
					function Tab:Resize()
						local TabCount = 0
						for _, Tab in next, Tabbox.Tabs do
							TabCount = TabCount + 1
						end
						for _, Button in next, TabboxButtons:GetChildren() do
							if not Button:IsA("UIListLayout") then
								Button.Size = UDim2.new(1 / TabCount, 0, 1, 0)
							end
						end
						if not Container.Visible then
							return
						end
						local Size = GetVisibleContentHeight(Container)
						Container.Size = UDim2.new(1, -18, 0, Size)
						BoxOuter.Size = UDim2.new(1, 0, 0, 20 + Size + 6)
