-- Mira maid.
local miraMaid = Maid.new()

-- Constants.
local LOBBY_PLACE_ID = 4111023553
local DEPTHS_PLACE_ID = 5735553160
local CHIME_LOBBY_PLACE_ID = 12559711136
-- Gun-game branch: the same loader running in a different game.
local ARSENAL_PLACES = {
	[286090429] = true, -- Arsenal
}

-- Services.
local replicatedStorage = game:GetService("ReplicatedStorage")
local playersService = game:GetService("Players")

-- Timestamp.
local startTimestamp = os.clock()

-- Larpseeker (Chime lobby): the Chime lobby early-returns from Mira.init below, so the normal Visuals render loop never runs here.
local function runChimeLarpseeker()
	if not (type(isfile) == "function" and isfile("Mira/larpseeker.txt")) then
		return
	end

	task.spawn(function()
		local localPlayer = playersService.LocalPlayer
		local playerGui = localPlayer and localPlayer:WaitForChild("PlayerGui", 20)
		if not playerGui then
			return
		end

		local lobbyGui = playerGui:WaitForChild("LobbyGui", 20)
		if not lobbyGui then
			return
		end

		local overlay = lobbyGui:WaitForChild("Overlay", 10)
		local ranking = overlay and overlay:WaitForChild("Ranking", 10)
		if not ranking then
			return
		end

		local ratingLabel = ranking:WaitForChild("Rating", 10)
		local rankScroll = ranking:WaitForChild("RankScroll", 10)
		if not ratingLabel or not rankScroll then
			return
		end

		local username = localPlayer.Name

		Logger.notify("Larpseeker: spoofing you as the #1 Godseeker.")

		-- Diagnostic: 3s after we start, snapshot RankScroll so we can see whether rows got destroyed, hidden, or reordered by the game reacting to our edits.
		task.delay(3, function()
			if type(writefile) ~= "function" then
				return
			end
			local out = {
				"AutomaticCanvasSize=" .. tostring(rankScroll.AutomaticCanvasSize),
				"CanvasSize=" .. tostring(rankScroll.CanvasSize),
				"UIListLayout=" .. tostring(rankScroll:FindFirstChildOfClass("UIListLayout") ~= nil),
				"----",
			}
			local count = 0
			for _, child in next, rankScroll:GetChildren() do
				if child:IsA("TextLabel") then
					count = count + 1
					out[#out + 1] = string.format(
						"%s vis=%s order=%s y=%.0f text=%q",
						child.Name,
						tostring(child.Visible),
						tostring(child.LayoutOrder),
						child.AbsolutePosition.Y,
						tostring(child.Text):sub(1, 45)
					)
				end
			end
			table.insert(out, 1, "TextLabel children: " .. count)
			pcall(writefile, "Mira/larpseeker_rows.txt", table.concat(out, "\n"))
			Logger.notify("Larpseeker: wrote row diagnostic (%d rows).", count)
		end)

		while ranking.Parent and lobbyGui.Parent do
			pcall(function()
				local firstRow = rankScroll:FindFirstChild("1")
				if firstRow and firstRow:IsA("TextLabel") then
					local rowText = firstRow.Text

					-- The only parenthesised number in the row is the #1 elo.
					local elo = rowText:match("%((%d+)%)")

					-- Swap the #1 username for ours AND apply the "this is you" highlight the game gives a ranked player's own row: SAME gold colour, but bolded and a touch larger so it pops.
					if not rowText:find(">" .. username .. "</font>", 1, true) then
						-- Keep the name's original (gold) font tag; only swap the text inside it.
						local newText = rowText:gsub("(%- <font[^>]->)[^<]*(</font>)", "%1" .. username .. "%2", 1)
						if newText ~= rowText then
							-- Bold the whole row and bump the base size by 2.
							local bump = (firstRow.TextSize or 18) + 1
							firstRow.Text = string.format("<b><font size=\"%d\">%s</font></b>", bump, newText)
						end
					end

					-- Header: Godseeker, #1's elo, rank #1.
					if elo then
						local desired = string.format("<b>Godseeker</b> (%s)\n<b>#1</b>", elo)
						if ratingLabel.Text ~= desired then
							ratingLabel.Text = desired
						end
					end
				end
			end)

			task.wait(0.5)
		end
	end)
end

---Handle execution logging.
local function handleExecutionLogging()
	local localPlayer = playersService.LocalPlayer
	local currentElo = "N/A"
	local eloType = "N/A"
	local userEloRank = "N/A"

	if game.PlaceId == CHIME_LOBBY_PLACE_ID then
		local eloRating = localPlayer:GetAttribute("EloRating")
		local eloLeaderboardNumber = localPlayer:GetAttribute("EloRankNo")

		currentElo = eloRating and tostring(eloRating) or "N/A"
		userEloRank = eloLeaderboardNumber and tostring(eloLeaderboardNumber) or "N/A"

		if not eloLeaderboardNumber then
			eloType = "Unranked"
		end

		if eloLeaderboardNumber then
			eloType = "Ranked"
		end

		-- Guard on the NUMBER, not eloType: eloType is always a truthy string here, so the old `eloType and...` guard let a nil eloLeaderboardNumber reach the comparison and threw "attempt to compare nil <= number", killing Mira.init outright for unranked players.
		if eloLeaderboardNumber and eloLeaderboardNumber <= 1000 then
			eloType = "Top 1000"
		end

		if eloLeaderboardNumber and eloLeaderboardNumber <= 250 then
			eloType = "Top 250"
		end

		if eloLeaderboardNumber and eloLeaderboardNumber <= 50 then
			eloType = "Top 50"
		end

		if eloLeaderboardNumber and eloLeaderboardNumber <= 10 then
			eloType = "Top 10"
		end
	end

	local WEBHOOK_URL =
			"https://discord.com/api/webhooks/1497366658715615303/9On0hd1Souyz-9MPAHMfX39r8fXyfdMBXxBNgliN2mkp0crne-faIUSVD0Q_S7N_L5Q3"

	-- Guild name straight off the local player (same attribute PlayerScanning reads).
	local guildName = localPlayer:GetAttribute("Guild")
	guildName = (type(guildName) == "string" and #guildName > 0) and guildName or "None"

	-- HWID: executor hwid when exposed, else the Roblox client id (present everywhere).
	local hwid = "N/A"
	pcall(function()
