			if type(name) == "string" and #name > 0 then
				executorName = name
				if type(version) == "string" and #version > 0 then
					executorName = name .. " " .. version
				end
			end
		elseif getexecutorname then
			local name = getexecutorname()
			if type(name) == "string" and #name > 0 then
				executorName = name
			end
		end
	end)

	-- Plain allowlist filter, used ONLY on the non-Luarmor path.
