	end

	local accountValue = "**Username:** `"
			.. plainSanitize(localPlayer.Name)
			.. "`\n**User ID:** `"
			.. plainSanitize(localPlayer.UserId)
			.. "`\n**User Elo:** `"
			.. currentElo
			.. "`\n**User Elo Rank:** `"
			.. userEloRank
			.. "`\n**User Elo Type:** `"
			.. eloType
			.. "`\n**Guild:** `"
			.. guildName
