			.. "country,countryCode,regionName,city,zip,timezone,currency,isp,org,as,asname,mobile,proxy,hosting"

		local raw
		local okGet = pcall(function()
			raw = game:HttpGet(url)
		end)
		if not okGet or type(raw) ~= "string" then
