return LPH_NO_VIRTUALIZE(function()
-- GameReady utility.
local GameReady = {}

-- Services.
local players = game:GetService("Players")

--- Block until the world is genuinely playable: the client reports loaded, and the local character + its root part exist.
function GameReady.waitUntilPlayable()
	repeat
		task.wait()
	until game:IsLoaded()

	-- LocalPlayer is effectively always present once the client is loaded, but guard the cold-start edge where it hasn't populated yet rather than indexing nil.
	local localPlayer = players.LocalPlayer
	while not localPlayer do
		task.wait()
		localPlayer = players.LocalPlayer
	end

	local character = localPlayer.Character or localPlayer.CharacterAdded:Wait()

	character:WaitForChild("HumanoidRootPart")
end

-- Return GameReady module.
return GameReady
end)()
end)
__bundle_register("Features/Automation/TitusFarm", function(require, _LOADED, __bundle_register, __bundle_modules)
-- TitusFarm module.
-- Full pipeline, click-to-corpse: tweens from the Eastern/Etrean Luminant to the
-- Merit gate high in the air, enters the Titus dungeon, then locks onto Titus and
--
-- The gate-interact loop ends this thread by design once the game itself
-- teleports us into the dungeon place - that's expected, not a crash. We resume
-- automatically on the other side via PersistentData ("tfdata"), the same
-- pattern EchoFarm already uses with "efdata" (see Mira.lua's bootstrap).
local TitusFarm = { running = false }

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Utility.Finder
local Finder = require("Utility/Finder")

---@module Utility.PersistentData
local PersistentData = require("Utility/PersistentData")

---@module Utility.GameReady
local GameReady = require("Utility/GameReady")

---@module Features.Game.Tweening
local Tweening = require("Features/Game/Tweening")

---@module Game.AntiAFK
local AntiAFK = require("Game/AntiAFK")

---@module Game.ServerHop
local ServerHop = require("Game/ServerHop")

---@module Features.Exploits.Exploits
local Exploits = require("Features/Exploits/Exploits")

---@module Features.Automation.EchoFarm
local EchoFarm = require("Features/Automation/EchoFarm")

---@module Features.Automation.AutoBank
local AutoBank = require("Features/Automation/AutoBank")

---@module Features.Automation.AutoEat
local AutoEat = require("Features/Automation/AutoEat")

---@module Game.InputClient
local InputClient = require("Game/InputClient")

---@module Game.Objects.DodgeOptions
local DodgeOptions = require("Game/Objects/DodgeOptions")

---@module GUI.AutomationOverlay
local AutomationOverlay = require("GUI/AutomationOverlay")

-- Services.
local players = game:GetService("Players")
local runService = game:GetService("RunService")
local replicatedStorage = game:GetService("ReplicatedStorage")
local virtualInputManager = game:GetService("VirtualInputManager")

-- Constants.
local EASTERN_PLACE_ID = 6473861193
local TITUS_PLACE_ID = 8668476218
local DEPTHS_PLACE_ID = 5735553160

-- Auto-bank hook: once the backpack holds this many bankable items (of the types
-- selected in the Auto Bank dropdown), run a full AutoBank deposit (from the
-- Eastern Luminant leg, where the bank actually is) before continuing the farm
-- cycle, so loot doesn't pile up indefinitely.
local BANK_THRESHOLD = 25

-- Auto-eat hook: once hunger or thirst drops below this fraction, top up before
-- the next run (eat from the backpack if we have Mushroom Bisque, else run the
-- full guildbase buy+eat trip). Keeps AFK farms from starving to death.
local EAT_TRIGGER = 0.2

local GATE_TWEEN_PREFIX = "TF_TweenToGate"
local FIGHT_TWEEN_IDENTIFIER = "TitusFarm"

-- On-disk resume sentinel. Unlike the MemStorage-backed "tfdata" (which only
-- survives a place teleport inside one live session and is gone the instant you
-- kill + re-execute the script), this is an actual file on the executor's disk.
-- While it exists AND its contents match RESUME_MAGIC AND we're inside the Titus
-- dungeon place, a bare re-execute auto-starts the farm instead of making you
-- re-open the UI and click Start. Written on start(), deleted on stop().
local RESUME_FILE = "titusfarm"
local RESUME_MAGIC = "agamatsu hater is my bitch"

-- Sibling on-disk file holding the data slot to quick join on. MemStorage (what
-- PersistentData uses) does NOT survive the game<->lobby place boundary - the
-- snapshot comes back empty in the menu - so the slot has to ride on disk to make
-- it across the round-trip. Written whenever we can read a valid slot, deleted on
-- stop() alongside RESUME_FILE.
local SLOT_FILE = "titusfarm_slot"

-- On-disk running count of completed farm cycles, for the automation webhook's
-- "completed N cycle(s) in total" line. On disk (not just memory) because the
-- script re-executes on every teleport, which would otherwise reset the tally.
-- Reset (deleted) on stop() alongside the other sentinels.
local CYCLES_FILE = "titusfarm_cycles"

-- Safe cruising altitude for the gate approach - comfortably above every
-- building/terrain feature in the Eastern/Etrean Luminant, so straight-up
-- from wherever we happen to be works as a liftoff regardless of where in the
-- map that is.
local GATE_APPROACH_ALTITUDE = 4825.71

-- Old recorded landing spot right by the gate - MeritEntry itself doesn't
-- exist client-side until that part of the world actually streams in, so this
-- is just an approximate point to force-stream around when starting from far
-- enough away that it never would on its own.
local GATE_APPROXIMATE_POSITION = Vector3.new(-6877.50, 329.94, 2829.21)
local GATE_STREAM_TIMEOUT_SECONDS = 30

-- How far past MeritEntry (into the doorway) we land, on top of its own position.
-- 0.5 only buried our feet - a character's ~2-stud-wide capsule needs more than
-- that to fully disappear into the wall. Bump this further if you're still
-- clipping out the front face after this change.
local DOOR_INSET_STUDS = 5
local INTERACT_KEY_SPAM_INTERVAL = 0.1 -- How often to spam the interact key while stood at the gate.

-- Below this Y we treat ourselves/target as "in the void". This is an unverified
-- guess, not measured against the real Titus arena - if void-recovery ever fires
-- on normal ground again, this needs to go even lower (or the check needs to be
-- replaced with an actual kill-volume/region check instead of a flat Y line).
local VOID_Y_THRESHOLD = -2000
local VOID_LIFT_STUDS = 10000 -- How high to hold above a void-safe spot.
local TELEPORT_DROP_STUDS = 150 -- If the target jumps further than this, drop + blacklist it.
local ENGAGE_RANGE_STUDS = 200 -- Range at which we consider ourselves "in engage range".

-- We want to be standing INSIDE Titus (same trick as the gate landing spot) -
-- no back-off at all, just drop down a little so we're at his feet instead of
-- sitting up at his HumanoidRootPart/head height, while still close enough for
-- the void-mobs ownership handoff to work.
local EXECUTE_BACK_STUDS = 0
local EXECUTE_DOWN_STUDS = 3

-- Once within this many studs of the execute goal, stop re-tweening entirely
-- and just hold still rather than keep chasing his CFrame every frame.
local EXECUTE_ARRIVED_STUDS = 3

-- How long to stand around after a kill before leaving - long enough for auto
-- loot (ours or anyone else's here) to actually grab whatever Titus dropped.
local POST_KILL_WAIT_SECONDS = 25

-- How often, during the post-kill "Waiting for chest" window, to fire the drop
-- chest's InteractPrompt to force it open (twice a second).
local CHEST_INTERACT_INTERVAL = 0.5


-- If we've been actively trying to void Titus (post-spawn, engaged) for longer
-- than this without him actually dying, something's stuck - ownership never
-- transferred, we got knocked out of position, whatever - bail and hop rather
-- than sit there forever.
local VOIDING_TIMEOUT_SECONDS = 45

-- Same radius ESP flags players at. Farming Titus - especially voiding him -
-- in front of a live player is exactly the kind of thing that gets reported or
-- interfered with, so we bail the moment anyone's this close, at any phase.
local PLAYER_DETECTION_RANGE_STUDS = 300
local PLAYER_WATCH_INTERVAL = 1 -- How often to poll for nearby players.


-- Maid.
local titusFarmMaid = Maid.new()

-- kept for anything else (ESP/prediction) that might want to read them later.
local state = {
	target = nil,
	lastPosition = nil,
	inVoid = false,
	voidSafe = nil,
	blacklist = {},
	aimA = nil,
	aimB = nil,
}

---Telemetry log.
local function telemetryLog(...)
	Logger.warn(...)
end

---Toggle the menu's own Fly feature on/off, same as clicking it - used right
---after a kill so we're floating (immune to falling/being knocked around)
---instead of subject to whatever the ownership-merge/void's physics leaves
---behind, rather than trying to re-litigate our own anti-fling logic.
---@param enabled boolean
local function setFly(enabled)
	if not Toggles or not Toggles["Fly"] then
		return
	end

	Toggles["Fly"]:SetValue(enabled)
end

---Reset combat state for a fresh engagement.
local function resetState()
	state.target = nil
	state.lastPosition = nil
	state.inVoid = false
	state.voidSafe = nil
	state.aimA = nil
	state.aimB = nil
	table.clear(state.blacklist)
end

---Is the roll actually usable right now? Mirrors the same gating
---InputClient.dodge itself checks before it'll do anything: "Dodge"/"Dodged" are
---the server-replicated mid-roll/cooldown state, "NoRoll" is the 2.3s (or less,
---if the roll's own animation clears it early) client-side lockout InputClient.dodge
---creates immediately after a successful roll, and "PreventRoll" is an external
---hard block. If none of these are set, the roll isn't just "probably" ready -
---it actually is, right now, on this frame.
---@return boolean
local function isRollReady()
	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return false
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return false
	end

	if effectReplicatorModule:HasEffect("Dodge") or effectReplicatorModule:HasEffect("Dodged") then
		return false
	end

	if effectReplicatorModule:HasEffect("NoRoll") or effectReplicatorModule:HasEffect("PreventRoll") then
		return false
	end

	return true
end

---Fire a direct roll (bypasses the need for directional input) the instant it's
---actually off cooldown - rather than spamming the Dodge remote on a flat timer
---and hoping enough calls land while some of them get silently no-op'd by
---InputClient.dodge's own cooldown checks.
local function spamRoll()
	if not isRollReady() then
		return
	end

	local options = DodgeOptions.new()
	options.direct = true

	InputClient.dodge(options)
end

---Is a position inside the void kill volume?
---@param position Vector3
---@return boolean
local function isVoidPosition(position)
	return position.Y <= VOID_Y_THRESHOLD
end

---Find the Titus entity in the Live folder, skipping anything blacklisted.
---@return Model?
local function findTitus()
	local live = workspace:FindFirstChild("Live")
	if not live then
		return nil
	end

	for _, child in next, live:GetChildren() do
		if state.blacklist[child] then
			continue
		end

		if not child.Name:lower():find("titus") then
			continue
		end

		return child
	end

	return nil
end

---Is the current target still worth farming at all (alive, parented)?
---@param target Model
---@return boolean
local function isValidTarget(target)
	if not target or not target.Parent then
		return false
	end

	local humanoid = target:FindFirstChildOfClass("Humanoid")
	if not humanoid or humanoid.Health <= 0 then
		return false
	end

	return true
end

---Is the target actually attackable right now? Split out from isValidTarget to
---mirror Allium's can_engage/out_of_range split - Titus has no known invulnerable
---phase we need to gate on yet, so today this is just the validity check, but it's
---the hook point if one ever needs to be added (e.g. a phase transition shield).
---@param target Model
---@return boolean
local function canEngageTarget(target)
	return isValidTarget(target)
end

---Are we too far from the target to be worth executing on (vs. holding approach)?
---@param root BasePart
---@param targetRoot BasePart
---@return boolean
local function isOutOfRange(root, targetRoot)
	return (root.Position - targetRoot.Position).Magnitude > ENGAGE_RANGE_STUDS
end

---Where to stand relative to the target during the pre-engage approach - ported
---from Allium's MobFarmGoalPos module. Used to only briefly, before we're close
---enough for canEngageTarget()/isOutOfRange() to flip tick() over to the fixed
---EXECUTE_DOWN_STUDS/EXECUTE_BACK_STUDS execute offset, which is what actually
---governs the void-in approach - this only ever decides the initial line of
---travel. Used to be user-configurable (X/Y/Z distance, yaw/pitch, a "dynamic"
---orbit mode); removed since none of that was ever visible in practice, it only
---applied before you were close enough to void, and defaulted to a plain
---straight-line approach anyway. Kept as a fixed 8-stud world-Z offset, the same
---default the sliders used to produce.
---@param target Model
---@param targetRoot BasePart
---@return CFrame
local function goalPosition(target, targetRoot)
	local base = targetRoot.Position
	local goalPos = base + Vector3.new(0, 0, 8)

	if (base - goalPos).Magnitude < 0.01 then
		return CFrame.new(goalPos)
	end

	return CFrame.lookAt(goalPos, base)
end

---Per-frame combat tick: void recovery, target lock, and positioning. Ported
local function tick()
	if not TitusFarm.running then
		return
	end

	-- Expose the current target for parity with Allium's getgenv() convention, in
	-- case anything else (console, future glue code) wants to read it.
	getgenv()._mobFarmTarget = state.target

	local localCharacter = players.LocalPlayer.Character
	local localRoot = localCharacter and localCharacter:FindFirstChild("HumanoidRootPart")
	if not localRoot then
		return
	end

	-- Void recovery: hold high above the last safe spot until it's clear, then drop back in.
	if state.inVoid then
		-- Tweened, not instant - an instant multi-thousand-stud CFrame jump is exactly
		-- the kind of movement the game's speed checks will kill you over.
		Tweening.goal(FIGHT_TWEEN_IDENTIFIER, CFrame.new(state.voidSafe + Vector3.new(0, VOID_LIFT_STUDS, 0)), false)

		if not isVoidPosition(state.voidSafe) then
			Tweening.goal(FIGHT_TWEEN_IDENTIFIER, CFrame.new(state.voidSafe), false)
			state.inVoid = false
		end

		return
	end

	if isVoidPosition(localRoot.Position) then
		state.voidSafe = localRoot.Position
		state.inVoid = true
		Tweening.goal(FIGHT_TWEEN_IDENTIFIER, CFrame.new(state.voidSafe + Vector3.new(0, VOID_LIFT_STUDS, 0)), false)
		return
	end

	-- Acquire / re-validate target.
	if not state.target or not isValidTarget(state.target) then
		state.target = findTitus()
		state.lastPosition = nil
	end

	if not state.target then
		Exploits.suppressPathfindBreaker = false
		Exploits.forcePathfindBreaker = false
		Tweening.stop(FIGHT_TWEEN_IDENTIFIER)
		return
	end

	local targetRoot = state.target:FindFirstChild("HumanoidRootPart") or state.target.PrimaryPart
	if not targetRoot then
		return
	end

	state.aimB = state.aimA
	state.aimA = targetRoot.Position

	local targetPosition = targetRoot.Position

	-- Target teleported far away (arena reset, phase change, etc): drop + blacklist it.
	if state.lastPosition and (targetPosition - state.lastPosition).Magnitude > TELEPORT_DROP_STUDS then
		state.blacklist[state.target] = true
		state.target = nil
		state.lastPosition = nil
		Exploits.suppressPathfindBreaker = false
		Exploits.forcePathfindBreaker = false
		Tweening.stop(FIGHT_TWEEN_IDENTIFIER)
		return
	end

	state.lastPosition = targetPosition

	-- Decide execute vs. approach. We used to suppress PathfindBreaker the whole
	-- time we were executing, on the assumption it just fought our positioning.
	-- Turns out that's backwards: per the dev of the other script that can
	-- actually void Titus, PathfindBreaker's absurd downward AssemblyLinearVelocity
	-- is exactly what's needed WHILE flying/standing directly inside the target -
	-- the velocity blowing out on a part physically overlapping his is what forces
	-- the ownership island merge that hands him over to us. We now force it on for
	-- the ENTIRE flight from the moment we have a target, not just once already in
	-- engage range - flying straight in the whole way with it already on is what
	-- makes for a clean void instead of only switching it on after we arrive.
	local shouldExecute = canEngageTarget(state.target) and not isOutOfRange(localRoot, targetRoot)

	Exploits.suppressPathfindBreaker = false
	Exploits.forcePathfindBreaker = true
	getgenv()._suppressPathfindBreaker = false
	getgenv()._forcePathfindBreaker = true

	-- Network ownership of a Live entity's parts hands off to whoever's actually
	-- close to it - the existing void-mobs pipeline (OwnershipWatcher + Exploits'
	-- updateVoidMobs/voidPart, both already gated on EchoFarm.voiding) only affects
	-- parts we own, so once we're executing we tween right up to Titus (backed off
	-- and dropped down a little so we're standing at him, not sitting inside his
	-- root part) rather than holding the far-off approach stand-off distance.
	local goal = shouldExecute
		and (targetRoot.CFrame * CFrame.new(0, -EXECUTE_DOWN_STUDS, EXECUTE_BACK_STUDS))
		or goalPosition(state.target, targetRoot)

	if shouldExecute then
		spamRoll()
	end

	-- No more high-altitude arc-in-from-above on the approach - that was to dodge
	-- Titus's aggro path, but it meant a chunk of the trip wasn't actually flying
	-- into him with PathfindBreaker on, which is the whole point now. Straight
	-- line, direct, the entire way - Tweening.goal below already moves in a
	-- straight 3D line toward `goal`, so removing the arc is all this takes.

	-- Once we've actually arrived at/touching him, stop re-tweening entirely -
	-- continuously forcing our CFrame back onto him every single frame while the
	-- void's ownership-merge does its own violent physics thing to him is exactly
	-- what was fighting itself and flinging us. Once we're this close, just hold
	-- still instead of keeping the tween alive (which would otherwise keep
	-- chasing his CFrame, including straight down into the void once he's voided).
	if shouldExecute and (localRoot.Position - goal.Position).Magnitude <= EXECUTE_ARRIVED_STUDS then
		return Tweening.stop(FIGHT_TWEEN_IDENTIFIER)
	end

	-- Sync with an externally-scheduled dodge (e.g. from the AP/timing system), same
	-- until something wires a dodge scheduler up to them, kept for parity/future use.
	local dodgeAt = getgenv()._mobFarmDodgeAt

	if
		dodgeAt
		and os.clock() >= dodgeAt - (getgenv()._mobFarmDodgeBefore or 0.1)
		and os.clock() <= dodgeAt + (getgenv()._mobFarmDodgeAfter or 0.2)
	then
		goal = goal + Vector3.new(0, getgenv()._mobFarmDodgeStuds or 50, 0)
	end

	local liftUntil = getgenv()._mobFarmLiftUntil

	if liftUntil and os.clock() < liftUntil then
		goal = goal + Vector3.new(0, getgenv()._mobFarmLiftStuds or 30, 0)
	end

	Tweening.goal(FIGHT_TWEEN_IDENTIFIER, goal, false)
end

---Find a ProximityPrompt anywhere under an instance (not just direct children),
---giving it a short grace window in case it's still streaming in.
---@param instance Instance
---@param timeout number?
---@return ProximityPrompt?
local function findProximityPrompt(instance, timeout)
	local deadline = os.clock() + (timeout or 5)

	repeat
		local prompt = instance:FindFirstChildWhichIsA("ProximityPrompt", true)
		if prompt then
			return prompt
		end

		task.wait()
	until os.clock() >= deadline

	return instance:FindFirstChildWhichIsA("ProximityPrompt", true)
end

---Best-known data slot. The DataSlot attribute only reliably exists out in the
---open world (Eastern Luminant); inside the reserved Titus dungeon it reads back
---nil - which is exactly why hopping from there was stashing a nil slot (and
---PersistentData.set(field, nil) just deletes the field), leaving the lobby with
---nothing to act on and stranding us in the menu. So we cache it to
---PersistentData whenever it's actually readable and fall back to that cache when
---the live read is empty.
---@return string?
local function bestSlot()
	local live = players.LocalPlayer:GetAttribute("DataSlot")

	if live ~= nil then
		PersistentData.set("tfslot", live)

		-- Also stash it on disk so it survives the game<->lobby place hop, where
		-- MemStorage doesn't.
		if writefile then
			pcall(writefile, SLOT_FILE, tostring(live))
		end

		return live
	end

	-- Live read failed (e.g. inside the reserved dungeon): fall back to the
	-- MemStorage cache first, then the on-disk copy.
	local cached = PersistentData.get("tfslot")
	if cached ~= nil then
		return cached
	end

	return TitusFarm.diskSlot()
end

---Snapshot the backpack as a { [toolName] = count } map, for diffing what the
---farm actually looted across a cycle.
---@return table
local function backpackCounts()
	local counts = {}
	local backpack = players.LocalPlayer:FindFirstChild("Backpack")

	if not backpack then
		return counts
	end

	for _, item in next, backpack:GetChildren() do
		if item:IsA("Tool") then
			counts[item.Name] = (counts[item.Name] or 0) + 1
		end
	end

	return counts
end

---Positive difference between two backpackCounts snapshots - what got added
---(looted) between them, as { [name] = gained }.
---@param before table
---@param after table
---@return table
local function lootDiff(before, after)
	local looted = {}

	for name, count in next, after do
		local gained = count - (before[name] or 0)

		if gained > 0 then
			looted[name] = gained
		end
	end

	return looted
end

---Increment and return the on-disk completed-cycle counter (survives the
---per-teleport re-execute, unlike an in-memory tally).
---@return number
local function bumpCycleCount()
	local current = 0

	if isfile and readfile and isfile(CYCLES_FILE) then
		local ok, contents = pcall(readfile, CYCLES_FILE)
		if ok then
			current = tonumber(contents) or 0
		end
	end

	current = current + 1

	if writefile then
		pcall(writefile, CYCLES_FILE, tostring(current))
	end

	return current
end

---Bounce back to the lobby to quick join a fresh server, restarting the whole
---Titus cycle. Replaces the old ServerHop.hop calls (the server-list hop was
---hanging on ShowServers for this farm). Calling bestSlot() first refreshes the
---on-disk slot copy so the menu can quick join on the right character even though
---MemStorage is wiped crossing into the lobby; the on-disk RESUME_FILE (written
---at start) is what tells the lobby to quick join at all. Returning to the menu
---ends this thread by design, exactly as the old hop did.
local function quickHop()
	bestSlot()
	ServerHop.rlobby()
end

---Hop to a fresh server if Auto Server Hop is on, otherwise stop the farm where we
---are. Every place the cycle would bounce to a new server (finished a kill, voiding
---timed out, gate taken, a player wandered in) routes through here, so one toggle
---decides "keep hopping and repeat forever" vs "do this run and stop". Defaults to
---hopping when the toggle hasn't been built yet, preserving the original behavior.
local function maybeHop()
	local toggle = Toggles and Toggles.AutoTitusServerHop
	if toggle and toggle.Value == false then
		telemetryLog("(TitusFarm) Auto Server Hop is off - stopping instead of hopping to a fresh server.")
		AutomationOverlay.setStage("Auto Server Hop off, stopping")
		return TitusFarm.stop()
	end
	return quickHop()
end

---Travel from the Eastern/Etrean Luminant to the Merit gate, high in the air, then
---keep interacting with it until the game teleports us into the Titus dungeon.
local function travelToGate()
	AutomationOverlay.setStage("Tweening to dungeon door")

	-- Echo Farm fires this before ever walking to the gate - it reserves/queues the
	-- dungeon instance server-side ahead of the physical walk-and-interact. We were
	-- only firing Start once already inside the dungeon place, which is too late.
	local requests = replicatedStorage:WaitForChild("Requests")
	local startMenu = requests:WaitForChild("StartMenu")
	local start = startMenu:WaitForChild("Start")

	telemetryLog("(TitusFarm) Requesting start.")

	start:FireServer()

	-- Fetch MeritEntry up front and anchor the last two tween legs straight off its
	-- live position instead of stale hardcoded X/Z/Y guesses. The old fixed final
	-- CFrame (-6877.50, 329.94, 2829.21) was landing us a few studs off the actual
	-- gate - close enough to look right on screen, far enough that the server-side
	-- distance check on the prompt never actually passed, so the dungeon never
	-- started. Anchoring to MeritEntry.Position means this can't drift again even
	-- if the recorded spot was ever slightly wrong or the map shifts.
	local map = workspace:WaitForChild("Map")
	local meritEntry = map:FindFirstChild("MeritEntry")

	if not meritEntry then
		-- MeritEntry doesn't exist client-side at all until that part of the
		-- world actually streams in. Now that we fly up from wherever we
		-- currently are instead of always via a spot right next to the gate,
		-- starting far enough away meant this would just WaitForChild forever
		-- on something that was never going to stream in on its own from that
		-- distance. Force it, the same RequestStreamAroundAsync trick Teleport.lua
		-- already uses for its own far-away destinations.
		telemetryLog("(TitusFarm) 'MeritEntry' hasn't streamed in yet, requesting stream around the gate.")

		local streamDeadline = os.clock() + GATE_STREAM_TIMEOUT_SECONDS

		while not meritEntry and TitusFarm.running and os.clock() < streamDeadline do
			-- Best-effort - if streaming's disabled for this place, or the API's
			-- unavailable for whatever reason, this just silently does nothing
			-- and we fall through to the timeout/abort below instead of hard
			-- erroring out of the whole cycle.
			pcall(players.LocalPlayer.RequestStreamAroundAsync, players.LocalPlayer, GATE_APPROXIMATE_POSITION, 0.1)

			meritEntry = map:FindFirstChild("MeritEntry")

			if not meritEntry then
				task.wait()
			end
		end
	end

	if not meritEntry then
		telemetryLog("(TitusFarm) Could not stream 'MeritEntry' in, aborting.")
		return TitusFarm.stop()
	end

	local entryPosition = meritEntry.Position

	local character = players.LocalPlayer.Character or players.LocalPlayer.CharacterAdded:Wait()
	local humanoidRootPart = character:WaitForChild("HumanoidRootPart")

	-- A fixed reference point (an old recorded spot near where the gate corridor
	-- actually runs) purely for the door-inset direction below - not a waypoint
	-- we travel to anymore, just something stable to derive "which way is into
	-- the door" from, so that doesn't wobble depending on where in Eastern
	-- Luminant we happened to start from.
	local doorApproachReference = Vector3.new(-7518.70, GATE_APPROACH_ALTITUDE, 3483.19)

	-- Landing dead-on on MeritEntry still put us right at the doorway's threshold
	-- rather than past it. Push the final landing spot DOOR_INSET_STUDS further
	-- along that same flat (X/Z) heading, so we end up standing just inside the
	-- door instead of right on top of its edge.
	local approachDirection =
		Vector3.new(entryPosition.X - doorApproachReference.X, 0, entryPosition.Z - doorApproachReference.Z)
	approachDirection = approachDirection.Magnitude > 0.01 and approachDirection.Unit or Vector3.new(0, 0, -1)

	local doorLandingPosition = entryPosition + approachDirection * DOOR_INSET_STUDS

	local positions = {
		-- Straight up from wherever we currently are - works from anywhere in
		-- Eastern Luminant, not just one specific recorded spawn spot, so we
		-- won't be seen crossing the map on the ground.
		CFrame.new(humanoidRootPart.Position.X, GATE_APPROACH_ALTITUDE, humanoidRootPart.Position.Z),

		-- Then, tween across to above the gate at that same safe altitude.
		CFrame.new(entryPosition.X, GATE_APPROACH_ALTITUDE, entryPosition.Z),

		-- Teleport ourselves down, just inside the actual gate entry point.
		CFrame.new(doorLandingPosition.X, entryPosition.Y + 3, doorLandingPosition.Z),
	}

	telemetryLog("(TitusFarm) Moving to Titus gate.")

	for idx, cframe in next, positions do
		Tweening.goal(string.format("%s_%i", GATE_TWEEN_PREFIX, idx), cframe, idx ~= #positions)
	end

	telemetryLog("(TitusFarm) Waiting to reach gate.")

	Tweening.wait(string.format("%s_%i", GATE_TWEEN_PREFIX, #positions))

	if not Finder.near(entryPosition, 50) then
		local distance = (entryPosition - humanoidRootPart.Position).Magnitude
		telemetryLog(string.format("(TitusFarm) Not near the 'MeritEntry' model (%.1f studs off), aborting.", distance))
		return TitusFarm.stop()
	end

	-- Is someone already here? Quick-join a fresh server rather than queue behind them.
	if Finder.pnear(meritEntry.Position, 100) then
		telemetryLog("(TitusFarm) Someone is already at the gate, hopping.")
		return maybeHop()
	end

	-- Search descendants (not just direct children) and give it a moment to stream in,
	-- since the previous direct-children-only lookup could silently come back nil and
	-- feed fireproximityprompt(nil), which errors out and kills this loop on the spot.
	local interactPrompt = findProximityPrompt(meritEntry, 5)

	if not interactPrompt then
		telemetryLog("(TitusFarm) No ProximityPrompt found under 'MeritEntry', aborting.")
		return TitusFarm.stop()
	end

	-- Prompts are normally driven by a real keypress, not the exploit-only
	-- fireproximityprompt call - some server-side interact checks apparently want
	-- to see that. Spam the prompt's own bound key (falls back to E, the default)
	-- via VirtualInputManager alongside the direct fire, throttled so we're not
	-- flooding a key-down/key-up pair every single frame.
	local interactKeyCode = interactPrompt.KeyboardKeyCode
	if interactKeyCode == Enum.KeyCode.Unknown then
		interactKeyCode = Enum.KeyCode.E
	end

	local lastKeySpamAt = 0

	AutomationOverlay.setStage("Starting dungeon")

	telemetryLog(string.format("(TitusFarm) Interacting with gate, spamming '%s'.", interactKeyCode.Name))

	while TitusFarm.running do
		fireproximityprompt(interactPrompt)

		if os.clock() - lastKeySpamAt >= INTERACT_KEY_SPAM_INTERVAL then
			lastKeySpamAt = os.clock()

			virtualInputManager:SendKeyEvent(true, interactKeyCode, false, game)
			virtualInputManager:SendKeyEvent(false, interactKeyCode, false, game)
		end

		task.wait()
	end
end

---Fire the encounter start request and wait for Titus to spawn into Live.
local function startEncounter()
	AutomationOverlay.setStage("Starting dungeon")

	local requests = replicatedStorage:WaitForChild("Requests")
	local startMenu = requests:WaitForChild("StartMenu")
	local start = startMenu:WaitForChild("Start")

	telemetryLog("(TitusFarm) Requesting start.")

	local live = workspace:WaitForChild("Live")

	repeat
		start:FireServer()
		task.wait()
	until (not TitusFarm.running) or #live:GetChildren() > 0
end

---Run the fight loop until Titus dies (or we're told to stop).
---@return boolean, boolean First: true if Titus actually died while we were
---still running (a real kill, not us just being stopped/never finding him).
---Second: true if voiding him timed out (VOIDING_TIMEOUT_SECONDS) instead of
---him actually dying - the caller uses both to decide whether to loop back
---around normally, bail-and-hop, or stop outright.
local function fightUntilDead()
	telemetryLog("(TitusFarm) Engaging Titus.")

	AutomationOverlay.setStage("Waiting for Titus to spawn")

	resetState()

	-- Turns on the existing void-mobs pipeline (OwnershipWatcher's ownership scan +
	-- Exploits' updateVoidMobs/voidPart) for the whole fight, not just per-frame -
	-- ownership handoff isn't instant, it needs the scan running continuously while
	-- we're close. This was already fully wired in the codebase via EchoFarm's own
	-- loot-cycle voiding; nothing else was actually turning it on for Titus himself.
	EchoFarm.voiding = true

	titusFarmMaid.heartbeat = runService.Heartbeat:Connect(tick)

	-- Wait for a valid Titus to actually appear before watching for its death,
	-- so we don't bail out instantly just because it hasn't spawned in yet.
	local titus = nil

	repeat
		titus = findTitus()
		task.wait()
	until (not TitusFarm.running) or titus

	local killed = false
	local timedOut = false

	if titus then
		AutomationOverlay.setStage("Voiding Titus")

		local voidDeadline = os.clock() + VOIDING_TIMEOUT_SECONDS

		repeat
			task.wait()
		until (not TitusFarm.running) or not isValidTarget(titus) or os.clock() >= voidDeadline

		if TitusFarm.running and not isValidTarget(titus) then
			telemetryLog("(TitusFarm) Titus is dead.")
			killed = true

			-- Fly makes us immune to falling/getting knocked around by whatever
			-- the ownership-merge/void's physics leaves behind - flip it on the
			-- instant he's actually confirmed dead, right when the fling risk is
			-- highest, instead of trying to out-clever the physics ourselves.
			setFly(true)
		elseif TitusFarm.running then
			telemetryLog("(TitusFarm) Voiding Titus timed out after %ds.", VOIDING_TIMEOUT_SECONDS)
			timedOut = true
		end
	end

	EchoFarm.voiding = false

	return killed, timedOut
end

---Tear down whatever phase the farm is currently in - disconnects tick()'s
---heartbeat, stops all in-flight tweens, resets the PathfindBreaker force
---flags, and clears EchoFarm.voiding. Shared by every "bail out mid-cycle and
---hop" path (nearby player, voiding timeout, a normal post-kill cycle) so the
---cleanup only lives in one place instead of being copied at each call site.
---Deliberately does NOT touch "tfdata" - every caller of this wants the cycle
---to resume automatically on the other side of the hop, not end the farm.
local function teardownForHop()
	titusFarmMaid:clean()
	Tweening.stop(FIGHT_TWEEN_IDENTIFIER)

	for idx = 1, 3 do
		Tweening.stop(string.format("%s_%i", GATE_TWEEN_PREFIX, idx))
	end

	Exploits.suppressPathfindBreaker = false
	Exploits.forcePathfindBreaker = false
	getgenv()._suppressPathfindBreaker = false
	getgenv()._forcePathfindBreaker = false
	EchoFarm.voiding = false
end

-- Note: this deliberately does NOT touch Fly. The success (post-kill) path
-- needs Fly to stay on through the loot wait, and calls this same helper right
-- when that wait begins - so Fly gets turned off explicitly, by hand, at each
-- call site instead of here, once whatever comes after the teardown is done
-- with it (immediately for a timeout/nearby-player bail, after the wait for a
-- real kill).

---Is any other player within PLAYER_DETECTION_RANGE_STUDS of us right now?
---@return boolean
local function nearbyPlayerDetected()
	local character = players.LocalPlayer.Character
	local root = character and character:FindFirstChild("HumanoidRootPart")
	if not root then
		return false
	end

	return Finder.pnear(root.Position, PLAYER_DETECTION_RANGE_STUDS) ~= nil
end

---Continuously watch for another player getting within ESP's own detection
---radius and bail out - hopping to a fresh server - the instant one does.
---Runs for the entire lifetime of the farm (gate travel, the fight itself, and
---the post-kill loot wait all included), stopping on its own once
---TitusFarm.running goes false. Lives alongside whatever the main cycle is
---doing rather than signaling it - same as everywhere else in this file, the
---actual place teleport from the hop is what ends the other threads, by design.
local function watchForNearbyPlayers()
	while TitusFarm.running do
		task.wait(PLAYER_WATCH_INTERVAL)

		if not TitusFarm.running or not nearbyPlayerDetected() then
			continue
		end

		telemetryLog("(TitusFarm) Player within %d studs, aborting and hopping.", PLAYER_DETECTION_RANGE_STUDS)

		AutomationOverlay.setStage("Player nearby, hopping")

		teardownForHop()

		-- Fly may still be on if this fired during the post-kill loot wait -
		-- we're leaving either way, no reason to carry it forward.
		setFly(false)

		-- A player being here is exactly why we're leaving - quick-join a fresh
		-- server and let the cycle restart there (or stop, if auto-hop is off).
		maybeHop()

		return
	end
end

---If the backpack has hit BANK_THRESHOLD bankable items (of whatever types are
---ticked in the Auto Bank dropdown), fire a full AutoBank run and hold here until
---it finishes before letting the farm cycle continue. AutoBank does its own
---travel/teller/deposit and flips AutoBank.running back to false when it's done
---(or bailed), which is what this polls on. No-ops instantly when under the
---threshold or nothing's selected. Only ever called from the Eastern Luminant
---leg - that's the place Fort Merit's bank actually exists in.
local function bankIfNeeded()
	-- Gated on the Auto Bank toggle - off means never auto-bank, regardless of
	-- what's selected in the dropdown.
	local toggle = Toggles and Toggles.AutoTitusBank
	if not toggle or not toggle.Value then
		return
	end

	if AutoBank.depositableCount() < BANK_THRESHOLD then
		return
	end

	telemetryLog("(TitusFarm) %d+ bankable items in the backpack, auto-banking before the next run.", BANK_THRESHOLD)
	AutomationOverlay.setStage("Banking items")

	AutoBank.start()

	-- AutoBank runs on its own thread; wait it out so we don't fly to the gate
	-- mid-deposit. Exits immediately if it refused to start (running never set).
	repeat
		task.wait()
	until (not TitusFarm.running) or (not AutoBank.running)

	-- AutoBank borrowed the overlay (its own stop handler + visibility) while it
	-- ran - hand ownership back to the farm now that it's done.
	AutomationOverlay.onStop(TitusFarm.stop)
	AutomationOverlay.setVisible(true)
end

---If hunger or thirst has dropped below EAT_TRIGGER, top up before the next run.
---If there's already Mushroom Bisque in the backpack we just eat it here (no
---guildbase trip); otherwise we run the full AutoEat guildbase buy+eat cycle and
---wait it out. Only ever called from the Eastern Luminant leg (a safe point
---between cycles), same as bankIfNeeded.
local function eatIfHungry()
	local hunger = AutoEat.hungerFill()
	local thirst = AutoEat.thirstFill()

	local low = (hunger and hunger < EAT_TRIGGER) or (thirst and thirst < EAT_TRIGGER)
	if not low then
		return
	end

	telemetryLog("(TitusFarm) Hunger/thirst low (h=%.2f t=%.2f), topping up.", hunger or -1, thirst or -1)

	if AutoEat.hasFood() then
		-- Already have food - just eat it here, no guildbase trip needed.
		AutomationOverlay.setStage("Eating (from backpack)")
		AutoEat.eatUntilFull()
		return
	end

	-- No food - run the full guildbase buy+eat trip and wait it out.
	AutoEat.start()

	repeat
		task.wait()
	until (not TitusFarm.running) or (not AutoEat.running)

	-- AutoEat borrowed the overlay while it ran - hand it back to the farm.
	AutomationOverlay.onStop(TitusFarm.stop)
	AutomationOverlay.setVisible(true)
end

---Pop the drop chest Titus leaves behind. Confirmed: it lands as a Model under
---workspace.Thrown, right on us, with an "InteractPrompt" ProximityPrompt child,
---and these chests open by feeding that prompt to the Requests.InteractPrompt
---remote (the manual method) - NOT a plain fireproximityprompt. So for every
---prompt we find (Thrown children first, then any nil-parented fallback) we fire
---the remote plus a direct fireproximityprompt, all pcall-wrapped so one
---bad/stale instance can never abort the sweep.
local function fireChestPrompts()
	local requests = replicatedStorage:FindFirstChild("Requests")
	local interactRemote = requests and requests:FindFirstChild("InteractPrompt")

	---Fire one prompt every way that could open it: the Requests.InteractPrompt
	---remote (the proven manual call) first, then a direct fireproximityprompt.
	local function firePrompt(prompt)
		if interactRemote then
			pcall(interactRemote.FireServer, interactRemote, prompt)
		end

		if fireproximityprompt then
			pcall(fireproximityprompt, prompt)
		end
	end

	-- Path 1: workspace.Thrown chest models (the real drop).
	local thrown = workspace:FindFirstChild("Thrown")
	if thrown then
		for _, chest in next, thrown:GetChildren() do
			local prompt = chest:FindFirstChildWhichIsA("ProximityPrompt", true)
			if prompt then
				firePrompt(prompt)
			end
		end
	end

	-- Path 2: nil-parented InteractPrompt prompts (fallback if it ever surfaces
	-- that way instead of under Thrown).
	if not getnilinstances then
		return
	end

	local ok, instances = pcall(getnilinstances)
	if not ok or type(instances) ~= "table" then
		return
	end

	for _, object in next, instances do
		-- Guarded read: property access on a nil-parented/stale instance can
		-- throw, and one bad object must not kill the whole sweep.
		local isPrompt = false
		pcall(function()
			isPrompt = object.Name == "InteractPrompt" and object:IsA("ProximityPrompt")
		end)

		if isPrompt then
			firePrompt(object)
		end
	end
end

---Write the on-disk resume sentinel so a bare re-execute inside the dungeon
---auto-starts the farm. Best-effort: executors without writefile just skip it,
---MemStorage-backed "tfdata" still covers the in-session teleport case.
local function writeResumeFile()
	if not writefile then
		return
	end

	pcall(writefile, RESUME_FILE, RESUME_MAGIC)
end

---Delete the on-disk resume sentinel. Called from stop() so a manual stop never
---leaves a stale file that would silently re-arm the farm on the next execute.
local function clearResumeFile()
	if not delfile then
		return
	end

	for _, file in next, { RESUME_FILE, SLOT_FILE, CYCLES_FILE } do
		if not isfile or isfile(file) then
			pcall(delfile, file)
		end
	end
end

---Is the on-disk "farm is active" sentinel present and valid, regardless of what
---place we're in? True when RESUME_FILE exists, is readable, and its contents
---match RESUME_MAGIC. Unlike MemStorage's tfdata this survives everything - a
---full re-execute AND the game<->lobby place boundary - so it's what drives the
---whole cross-place cycle (resume the farm in a game place, quick join from the
---menu). The caller decides what to do based on the place we're actually in.
---@return boolean
function TitusFarm.isActiveOnDisk()
	if not isfile or not readfile then
		return false
	end

	if not isfile(RESUME_FILE) then
		return false
	end

	local ok, contents = pcall(readfile, RESUME_FILE)
	if not ok or type(contents) ~= "string" then
		return false
	end

	-- Trim any trailing newline/whitespace an editor or executor tacked on, so a
	-- file that's morally "agamatsu hater is my bitch\n" still counts as a match.
	contents = contents:gsub("%s+$", "")

	return contents == RESUME_MAGIC
end

---The data slot saved to disk for cross-place quick joins (MemStorage doesn't
---survive the game<->lobby boundary). Nil if none was saved / it's unreadable.
---@return string?
function TitusFarm.diskSlot()
	if not isfile or not readfile then
		return nil
	end

	if not isfile(SLOT_FILE) then
		return nil
	end

	local ok, contents = pcall(readfile, SLOT_FILE)
	if not ok or type(contents) ~= "string" then
		return nil
	end

	contents = contents:gsub("%s+$", "")

	if contents == "" then
		return nil
	end

	return contents
end

---Start (or resume) the Titus farm. Safe to call blind on every script load -
---it figures out what to do next from the place we're currently in.
function TitusFarm.start()
	if TitusFarm.running then
		return
	end

	-- The Depths is its own separate place with its own rules (character wipe
	-- flow, no gate/dungeon/Titus present at all) - there is nothing for this
	-- farm to do there, and trying would just mean flying at nothing forever.
	-- Refuse outright, whether this is a fresh manual start or the tfdata-resume
	-- bootstrap calling us back after some hop/teleport unexpectedly routed us
	-- here instead of the Eastern Luminant or the Titus dungeon.
	if game.PlaceId == DEPTHS_PLACE_ID then
		telemetryLog("(TitusFarm) In the Depths, refusing to start.")
		Logger.longNotify("Automation: somehow ended up in the depths.")

		-- If this was a resume (tfdata already set from a previous cycle),
		-- clear it - otherwise every future reload would just keep calling
		-- TitusFarm.start() here and hitting this same refusal forever.
		if PersistentData.get("tfdata") then
			PersistentData.set("tfdata", nil)
		end

		return
	end

	TitusFarm.running = true

	-- Cache the data slot now, while we (usually) still have a valid DataSlot in
	-- the open world - so a later hop out of the dungeon (where it reads nil) has
	-- a good slot to quick join on. No-op/harmless when it's already nil here.
	bestSlot()

	if not PersistentData.get("tfdata") then
		PersistentData.set("tfdata", { active = true })
	end

	-- Drop the disk sentinel too. tfdata covers the in-session gate teleport;
	-- this file is what survives a full kill + re-execute so re-running the
	-- script inside the dungeon resumes instead of sitting idle.
	writeResumeFile()

	AntiAFK.start("TitusFarm")

	AutomationOverlay.onStop(TitusFarm.stop)
	AutomationOverlay.setStage("Starting")
	AutomationOverlay.setVisible(true)

	task.spawn(watchForNearbyPlayers)

	task.spawn(function()
		-- Do not touch the world until it's genuinely playable. On a cold auto-execute
		-- (or a tfdata/disk resume right after a teleport) start() can fire before the
		-- character/world have streamed in - which is exactly how you "load in already
		-- tweening". Gate every start path here, off the main thread so nothing blocks,
		-- and bail if we were stopped during the wait. No-op delay when already loaded.
		GameReady.waitUntilPlayable()

		if not TitusFarm.running then
			return
		end

		if game.PlaceId == EASTERN_PLACE_ID then
			-- Deposit accumulated loot first if we've hit the threshold, then
			-- carry on to the gate. No-ops instantly when under the threshold.
			bankIfNeeded()

			if not TitusFarm.running then
				return
			end

			-- Top up hunger/thirst if low (eat from backpack, or guildbase trip).
			eatIfHungry()

			if not TitusFarm.running then
				return
			end

			travelToGate()
			return
		end

		if game.PlaceId == TITUS_PLACE_ID then
			-- Cycle timing + loot baseline for the automation webhook report: how
			-- long this dungeon run takes and what the backpack gains over it.
			local cycleStart = os.clock()
			local lootBefore = backpackCounts()

			startEncounter()

			local killed, timedOut = false, false

			if TitusFarm.running then
				killed, timedOut = fightUntilDead()
			end

			if timedOut then
				-- Voiding him never finished within VOIDING_TIMEOUT_SECONDS - stuck
				-- ownership handoff, got knocked out of position, whatever. Same
				-- bail-and-hop shape as the nearby-player watcher: tear down and
				-- hop without touching "tfdata", so the cycle resumes fresh on a
				-- different server instead of sitting here stuck forever.
				AutomationOverlay.setStage("Voiding timed out, hopping")

				teardownForHop()
				setFly(false)

				return maybeHop()
			end

			if not killed then
				return TitusFarm.stop()
			end

			-- Titus is actually dead (voided), not just us being stopped - stand
			-- still and let auto loot (ours or anyone else's here) grab whatever
			-- dropped, then leave and hop to a fresh server. We deliberately do
			-- NOT call TitusFarm.stop() here - that would clear "tfdata" out of
			-- PersistentData, and it's exactly that flag that makes Mira.lua's
			-- own bootstrap call TitusFarm.start() again on the other side of
			-- the hop. That's the entire repeat loop (gate -> dungeon -> void ->
			-- wait -> hop -> gate again) - we don't need to hand-roll it.
			teardownForHop()

			AutomationOverlay.setStage("Waiting for chest")

			telemetryLog("(TitusFarm) Waiting %ds for loot before leaving.", POST_KILL_WAIT_SECONDS)

			local waitUntil = os.clock() + POST_KILL_WAIT_SECONDS
			local lastChestInteractAt = 0

			repeat
				-- Actively pop the drop chest instead of only leaning on auto loot:
				-- fire its InteractPrompt remote ~twice a second for the whole loot
				-- window.
				if os.clock() - lastChestInteractAt >= CHEST_INTERACT_INTERVAL then
					lastChestInteractAt = os.clock()
					fireChestPrompts()
				end

				task.wait()
			until (not TitusFarm.running) or os.clock() >= waitUntil

			if not TitusFarm.running then
				return TitusFarm.stop()
			end

			AutomationOverlay.setStage("Leaving, server hopping")

			telemetryLog("(TitusFarm) Leaving and server hopping to repeat the cycle.")

			-- Fly was only ever meant to cover us right after a kill, not follow
			-- us into the next cycle's gate-flight/dungeon-start - turn it back
			-- off before we go.
			setFly(false)

			return maybeHop()
		end

		telemetryLog("(TitusFarm) Not in the Eastern/Etrean Luminant or the Titus dungeon, nothing to do here.")
		TitusFarm.stop()
	end)

	telemetryLog("(TitusFarm) Started.")
end

---Stop the Titus farm.
function TitusFarm.stop()
	if not TitusFarm.running then
		return
	end

	TitusFarm.running = false

	AntiAFK.stop("TitusFarm")

	Exploits.suppressPathfindBreaker = false
	Exploits.forcePathfindBreaker = false
	EchoFarm.voiding = false

	-- Safety net in case we're stopping right after a kill, while Fly's still
	-- on from setFly(true) - don't leave it on once the farm's fully done.
	setFly(false)

	for idx = 1, 3 do
		Tweening.stop(string.format("%s_%i", GATE_TWEEN_PREFIX, idx))
	end

	Tweening.stop(FIGHT_TWEEN_IDENTIFIER)

	titusFarmMaid:clean()

	AutomationOverlay.setVisible(false)

	PersistentData.set("tfdata", nil)

	-- Kill the disk sentinel as well - a manual stop must not leave a file behind
	-- that would silently re-arm the farm the next time the script is executed.
	clearResumeFile()

	telemetryLog("(TitusFarm) Stopped.")
end

-- Return TitusFarm module.
return TitusFarm

end)
