__bundle_register("Features/Automation/AutoEat", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
-- AutoEat module.
local AutoEat = { running = false }

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Utility.Finder
local Finder = require("Utility/Finder")

---@module Features.Game.Tweening
local Tweening = require("Features/Game/Tweening")

---@module Features.Game.Interactions
local Interactions = require("Features/Game/Interactions")

---@module Game.AntiAFK
local AntiAFK = require("Game/AntiAFK")

---@module GUI.AutomationOverlay
local AutomationOverlay = require("GUI/AutomationOverlay")

-- Services.
local players = game:GetService("Players")
local replicatedStorage = game:GetService("ReplicatedStorage")
local virtualInputManager = game:GetService("VirtualInputManager")

-- Constants.
local DEPTHS_PLACE_ID = 5735553160

local TWEEN_PREFIX = "AutoEat_Tween"

-- Same chime spot / tool the guildbase route uses.
local CHIME_POSITION = Vector3.new(-6146.37, 688.39, 2255.43)
local CHIME_LAND_CFRAME =
	CFrame.new(-6146.371, 693.390, 2255.430, 0.019, 0.000, 1.000, 0.000, 1.000, 0.000, -1.000, 0.000, 0.019)
local CHIME_TOOL_NAME = "Chime of Dwelling"

-- Reuse the proven-safe cruising altitude for the Eastern/Etrean region.
local BANK_APPROACH_ALTITUDE = 4825.71
local LANDING_Y_OFFSET = 5

-- Guildbase targets.
local GUILD_CHEF_NAME = "Guild Chef"
local FOOD_ITEM = "Mushroom Bisque"

-- How many to buy per guildbase trip.
local FOOD_BUY_QUANTITY = 20

-- Hunger + thirst both live under PlayerGui.StatsGui.SurvivalStats: the Stomach and Water bars, each with a "Slider" child whose Size.Y.Scale is the fill, 0.. ~1.
local HUNGER_SLIDER_PATH = { "StatsGui", "SurvivalStats", "Stomach", "Slider" }
local THIRST_SLIDER_PATH = { "StatsGui", "SurvivalStats", "Water", "Slider" }

-- Eat until both hunger and thirst are at least this full; safety cap on bites so it can never loop forever.
local FULL_TARGET = 0.85
local MAX_EAT_BITES = 30

-- After the tween drops us at the chime spot, the descent is a fast Y-snap - acting instantly makes the game reset our position.
local CHIME_SETTLE_SECONDS = 2

-- The Tweening module reads a single global "TweenStudsPerSecond" option.
local TWEEN_SPEED = 108

-- Previous global tween speed, captured on start so stop() can put it back.
local previousTweenSpeed = nil

local INTERACT_KEY = Enum.KeyCode.E

local GUILDBASE_ENTER_TIMEOUT_SECONDS = 20
local CHEF_FIND_TIMEOUT_SECONDS = 15
-- Give the door entry a generous window: with fly/tween/noclip off it enters "normally" (walk/interact), which takes a beat plus streaming.
local DOOR_INTERACT_WINDOW_SECONDS = 15
local CHOICE_RESOLVE_TIMEOUT_SECONDS = 4

-- Entering the guild base teleports us a big distance from the chime spot - THAT jump (not chef proximity) is how we know we actually got in.
local ENTERED_JUMP_STUDS = 40

-- Where to stand relative to the Guild Chef, in its LOCAL frame - measured live standing exactly where we want, so it lands there in every guild base regardless of layout.
local CHEF_STAND_OFFSET = CFrame.new(3.47, -0.06, -0.41)

---Telemetry log.
local function telemetryLog(...)
	Logger.warn(...)
end

---Toggle the menu's NoClip on/off, same trick TitusFarm uses for Fly.
---@param enabled boolean
local function setNoClip(enabled)
	if not Toggles or not Toggles["NoClip"] then
		return
	end

	Toggles["NoClip"]:SetValue(enabled)
end

---Toggle the menu's Fly on/off.
---@param enabled boolean
local function setFly(enabled)
	if not Toggles or not Toggles["Fly"] then
		return
	end

	Toggles["Fly"]:SetValue(enabled)
end

---Set the global tween-speed slider.
---@param value number
local function setTweenSpeed(value)
	local slider = Options and Options["TweenStudsPerSecond"]
	if slider and slider.SetValue then
		pcall(function()
			slider:SetValue(value)
		end)
	end
end

---Capture the current tween speed and drop it to TWEEN_SPEED for the trip.
local function applyTweenSpeed()
	local slider = Options and Options["TweenStudsPerSecond"]
	previousTweenSpeed = (slider and slider.Value) or 120
	setTweenSpeed(TWEEN_SPEED)
end

---Restore whatever the tween speed was before the trip.
local function restoreTweenSpeed()
	if previousTweenSpeed then
		setTweenSpeed(previousTweenSpeed)
		previousTweenSpeed = nil
	end
end

---Tap the interact key (E) once via VirtualInputManager.
local function tapInteractKey()
	virtualInputManager:SendKeyEvent(true, INTERACT_KEY, false, game)
	virtualInputManager:SendKeyEvent(false, INTERACT_KEY, false, game)
end

--- Up/across/down tween to a world position - the proven-safe travel shape.
---@param position Vector3
---@param stageText string
---@param finalCFrame CFrame?
---@return boolean True if we ended up near the target.
local function travelTo(position, stageText, finalCFrame)
	AutomationOverlay.setStage(stageText)

	pcall(players.LocalPlayer.RequestStreamAroundAsync, players.LocalPlayer, position, 0.1)

	local character = players.LocalPlayer.Character or players.LocalPlayer.CharacterAdded:Wait()
	local humanoidRootPart = character:WaitForChild("HumanoidRootPart")

	local positions = {
		CFrame.new(humanoidRootPart.Position.X, BANK_APPROACH_ALTITUDE, humanoidRootPart.Position.Z),
		CFrame.new(position.X, BANK_APPROACH_ALTITUDE, position.Z),
		finalCFrame or CFrame.new(position.X, position.Y + LANDING_Y_OFFSET, position.Z),
	}

	for idx, cframe in next, positions do
		Tweening.goal(string.format("%s_%i", TWEEN_PREFIX, idx), cframe, idx ~= #positions)
	end

	Tweening.wait(string.format("%s_%i", TWEEN_PREFIX, #positions))

	return Finder.near(position, 75)
end

--- Tween to a world position (noclip auto-applies while tweening), bounded by a timeout so an unreachable spot can't hang us.
---@param position Vector3
---@param timeout number?
---@param tolerance number?
local function tweenToPosition(position, timeout, tolerance)
	local slot = string.format("%s_move", TWEEN_PREFIX)

	Tweening.goal(slot, CFrame.new(position), false)

	local deadline = os.clock() + (timeout or 10)
	local reach = tolerance or 4

	repeat
		task.wait()
	until (not AutoEat.running) or Finder.near(position, reach) or os.clock() >= deadline

	Tweening.stop(slot)
end

---A world position for an instance (Model pivot, else BasePart position).
---@param instance Instance
---@return Vector3?
local function instancePosition(instance)
	local ok, position = pcall(function()
		return instance:GetPivot().Position
	end)

	if ok and position then
		return position
	end

	if instance:IsA("BasePart") then
		return instance.Position
	end

	return nil
end

---Player HumanoidRootPart position, or nil.
---@return Vector3?
local function rootPosition()
	local character = players.LocalPlayer.Character
	local root = character and character:FindFirstChild("HumanoidRootPart")
	return root and root.Position or nil
end

--- Are we locked at `cframe` - position within tolerance AND facing aligned?
---@param cframe CFrame
---@return boolean
local function isLockedAt(cframe)
	local character = players.LocalPlayer.Character
	local hrp = character and character:FindFirstChild("HumanoidRootPart")
	if not hrp then
		return false
	end

	local posOk = (hrp.Position - cframe.Position).Magnitude <= 4
	local facingOk = hrp.CFrame.LookVector:Dot(cframe.LookVector) >= 0.97

	return posOk and facingOk
end

--- Nearest workspace instance matching `predicate`, with its distance from us.
---@param predicate fun(inst: Instance): boolean
---@return Instance?, number
local function nearestTo(predicate)
	local origin = rootPosition()
	if not origin then
		return nil, math.huge
	end

	local best, bestDist = nil, math.huge

	for _, instance in next, workspace:GetDescendants() do
		if predicate(instance) then
			local pos = instancePosition(instance)
			if pos then
				local dist = (pos - origin).Magnitude
				if dist < bestDist then
					best, bestDist = instance, dist
				end
			end
		end
	end

	return best, bestDist
end

--- The nearest guild ENTRANCE door (ours is right next to us at the chime spot; other guilds' doors are loaded elsewhere in the world).
---@return Instance?
local function findEntranceDoor()
	return (nearestTo(function(instance)
		return instance.Parent == workspace and instance.Name:match("^GuildDoor") ~= nil
	end))
end

---The nearest guild EXIT door (ours, once we're inside our base).
---@return Instance?
local function findExitDoor()
	return (nearestTo(function(instance)
		return instance.Parent == workspace and instance.Name:match("^GuildExitDoor") ~= nil
	end))
end

--- Snapshot of the guild ENTRANCE doors currently in the world, so we can tell which one the chime spawns next.
---@return table<Instance, boolean>
local function guildDoorSnapshot()
	local set = {}

	for _, instance in next, workspace:GetChildren() do
		if instance.Name:match("^GuildDoor") then
			set[instance] = true
		end
	end

	return set
end

--- The guild entrance door that appeared AFTER `before` (the one the chime just spawned - ours), or nil if none yet.
---@param before table<Instance, boolean>
---@return Instance?
local function findNewGuildDoor(before)
	for _, instance in next, workspace:GetChildren() do
		if instance.Name:match("^GuildDoor") and not before[instance] then
			return instance
		end
	end

	return nil
end

--- Enter/exit a door "by interact prompt or by hitting E a few times" until `done()` returns true or the window expires.
---@param door Instance
---@param done fun():boolean
---@param stage string
local function workDoor(door, done, stage)
	AutomationOverlay.setStage(stage)

	local deadline = os.clock() + DOOR_INTERACT_WINDOW_SECONDS
	local lastTapAt = 0

	while AutoEat.running and os.clock() < deadline do
		if done() then
			return
		end

		local prompt = door:FindFirstChildWhichIsA("ProximityPrompt", true)
		if prompt then
			pcall(fireproximityprompt, prompt)
		end

		if os.clock() - lastTapAt >= 0.25 then
			lastTapAt = os.clock()
			tapInteractKey()
		end

		-- Throttled (not every frame) - done() does a full workspace scan.
		task.wait(0.15)
	end
end

--- The NEAREST "Guild Chef" to us, with distance.
---@return Model?, number
local function findGuildChef()
	return nearestTo(function(instance)
		return instance:IsA("Model") and instance.Name == GUILD_CHEF_NAME
	end)
end

--- Find OUR food shop's InteractPrompt - the NEAREST "Mushroom Bisque" shop stall (under a "Shops" folder) to us.
---@return Instance?, Model?
local function findShopPrompt()
	local shop = nearestTo(function(instance)
		return instance.Name == FOOD_ITEM and instance.Parent ~= nil and instance.Parent.Name == "Shops"
	end)

	if not shop then
		return nil, nil
	end

	local prompt = shop:FindFirstChild("InteractPrompt") or shop:FindFirstChildWhichIsA("ProximityPrompt", true)
	return prompt, shop
end

--- Resolve the "Choice" RemoteFunction the buy prompt invokes (quantity).
---@return Instance?
local function resolveChoiceRemote()
	-- 1.
	local requests = replicatedStorage:FindFirstChild("Requests")
	if requests then
		local remote = requests:FindFirstChild("Choice")
		if remote and remote:IsA("RemoteFunction") then
			return remote
		end
	end

	-- 2.
	local playerGui = players.LocalPlayer:FindFirstChild("PlayerGui")
	if playerGui then
		for _, descendant in next, playerGui:GetDescendants() do
			if descendant.Name == "Choice" and descendant:IsA("RemoteFunction") then
				return descendant
			end
		end
	end

	-- 3.
	if getnilinstances then
		local ok, instances = pcall(getnilinstances)
		if ok and instances then
			for _, instance in next, instances do
				if instance.Name == "Choice" and instance:IsA("RemoteFunction") then
					return instance
				end
			end
		end
	end

	return nil
end

--- Buy the food at the Guild Chef: fire the shop's InteractPrompt through the Requests.InteractPrompt remote, then answer the quantity Choice with the buy amount.
---@return boolean
local function buyFood()
	local shopPrompt, shop = findShopPrompt()
	if not shopPrompt then
		telemetryLog("(AutoEat) [buy] no '%s' shop prompt found, aborting buy.", FOOD_ITEM)
		return false
	end

	local root = rootPosition()
	local shopPos = shop and instancePosition(shop)
	telemetryLog(
		"(AutoEat) [buy] shop prompt '%s' (a %s), dist=%.0f",
		shopPrompt.Name,
		shopPrompt.ClassName,
		(root and shopPos) and (shopPos - root).Magnitude or -1
	)

	local requests = replicatedStorage:WaitForChild("Requests")
	local interactRemote = requests:WaitForChild("InteractPrompt")

	AutomationOverlay.setStage("Buying food")

	-- Fire the shop prompt every way that could open the buy dialogue - the Requests.InteractPrompt remote plus a direct fireproximityprompt - a few times, watching for the quantity Choice remote to surface after each.
	for attempt = 1, 6 do
		if not AutoEat.running then
			break
		end

		pcall(function()
			interactRemote:FireServer(shopPrompt)
		end)

		if fireproximityprompt and shopPrompt:IsA("ProximityPrompt") then
			pcall(fireproximityprompt, shopPrompt)
		end

		-- Watch briefly for the Choice remote.
		local deadline = os.clock() + 1
		local choice = nil
		repeat
			choice = resolveChoiceRemote()
			if choice then
				break
			end
			task.wait()
		until (not AutoEat.running) or os.clock() >= deadline

		if choice then
			telemetryLog("(AutoEat) [buy] Choice surfaced on attempt %d, buying %d.", attempt, FOOD_BUY_QUANTITY)
			pcall(function()
				choice:InvokeServer(FOOD_BUY_QUANTITY)
			end)
			return true
		end
	end

	-- Diagnostic: how many "Choice" RemoteFunctions are visible, and where.
	local guiCount, nilCount = 0, 0
	local pg = players.LocalPlayer:FindFirstChild("PlayerGui")
	if pg then
		for _, d in next, pg:GetDescendants() do
			if d.Name == "Choice" and d:IsA("RemoteFunction") then
				guiCount = guiCount + 1
			end
		end
	end
	if getnilinstances then
		local ok, insts = pcall(getnilinstances)
		if ok and insts then
			for _, inst in next, insts do
				local isChoice = false
				pcall(function()
					isChoice = inst.Name == "Choice" and inst:IsA("RemoteFunction")
				end)
				if isChoice then
					nilCount = nilCount + 1
				end
			end
		end
	end

	telemetryLog("(AutoEat) [buy] Choice never surfaced (gui=%d nil=%d).", guiCount, nilCount)
	return false
end

---Stop every leg of the travel tween.
local function stopTweens()
	for idx = 1, 3 do
		Tweening.stop(string.format("%s_%i", TWEEN_PREFIX, idx))
	end
	Tweening.stop(string.format("%s_move", TWEEN_PREFIX))
end

---Run the full anti-hunger trip.
function AutoEat.start()
	if AutoEat.running then
		return
	end

	if game.PlaceId == DEPTHS_PLACE_ID then
		telemetryLog("(AutoEat) In the Depths, refusing to start.")
		return
	end

	AutoEat.running = true

	-- Slow the tween down for the whole trip so the descent doesn't get reset.
	applyTweenSpeed()

	AntiAFK.start("AutoEat")

	AutomationOverlay.onStop(AutoEat.stop)
	AutomationOverlay.setStage("Starting")
	AutomationOverlay.setVisible(true)

	task.spawn(function()
		-- 1.
		if not travelTo(CHIME_POSITION, "Traveling to the Chime spot", CHIME_LAND_CFRAME) then
			telemetryLog("(AutoEat) Couldn't reach the Chime spot, aborting.")
			return AutoEat.stop()
		end

		-- Don't release the tween until we're actually locked at the landing spot AND facing the right way.
		AutomationOverlay.setStage("Locking in position")

		local lockDeadline = os.clock() + 8
		local stableSince = nil

		repeat
			if isLockedAt(CHIME_LAND_CFRAME) then
				stableSince = stableSince or os.clock()
				if os.clock() - stableSince >= 1 then
					break
				end
			else
				stableSince = nil
			end

			task.wait()
		until (not AutoEat.running) or os.clock() >= lockDeadline

		-- Locked in - now release the tween and drop out of noclip/fly.
		stopTweens()
		setNoClip(false)
		setFly(false)

		AutomationOverlay.setStage("Settling")
		task.wait(CHIME_SETTLE_SECONDS)

		if not AutoEat.running then
			return AutoEat.stop()
		end

		local backpack = players.LocalPlayer:FindFirstChild("Backpack")
		local chime = backpack and backpack:FindFirstChild(CHIME_TOOL_NAME)
		if not chime then
			telemetryLog("(AutoEat) No '%s' in the backpack, aborting.", CHIME_TOOL_NAME)
			Logger.longNotify("Automation: no Chime of Dwelling to reach the guild base.")
			return AutoEat.stop()
		end

		-- Snapshot the guild doors already in the world BEFORE using the chime, so we can pick out the new one the chime spawns instead of a neighbouring fixed guild base's door.
		local doorsBefore = guildDoorSnapshot()

		AutomationOverlay.setStage("Using the Chime of Dwelling")
		Interactions.etool(chime)

		local character = players.LocalPlayer.Character
		local equipped = character and character:FindFirstChild(CHIME_TOOL_NAME)
		if equipped then
			pcall(function()
				equipped:Activate()
			end)
		end

		-- 2.
		AutomationOverlay.setStage("Waiting for the guild door")

		local entrance = nil
		local doorDeadline = os.clock() + GUILDBASE_ENTER_TIMEOUT_SECONDS

		repeat
			entrance = findNewGuildDoor(doorsBefore)
			if entrance then
				break
			end
			if equipped and equipped.Parent then
				pcall(function()
					equipped:Activate()
				end)
			end
			task.wait(0.5)
		until (not AutoEat.running) or os.clock() >= doorDeadline

		if not entrance then
			telemetryLog("(AutoEat) Our guild door never spawned, aborting.")
			return AutoEat.stop()
		end

		-- 3.
		telemetryLog("(AutoEat) [gb] door='%s' guild='%s'", entrance.Name, tostring(entrance:GetAttribute("GuildName")))

		local preEnterPos = rootPosition() or Vector3.new()

		local function entered()
			local now = rootPosition()
			return now ~= nil and (now - preEnterPos).Magnitude > ENTERED_JUMP_STUDS
		end

		workDoor(entrance, entered, "Entering guild base")

		if not AutoEat.running then
			setNoClip(false)
			return AutoEat.stop()
		end

		if not entered() then
			setNoClip(false)
			telemetryLog("(AutoEat) Door entry didn't teleport us in, aborting.")
			Logger.longNotify("Automation: couldn't enter the guild base.")
			return AutoEat.stop()
		end

		telemetryLog("(AutoEat) [gb] entered (jumped %.0f studs)", ((rootPosition() or preEnterPos) - preEnterPos).Magnitude)

		-- 4.
		task.wait(2.5)

		AutomationOverlay.setStage("Finding the Guild Chef")

		local chef, chefDist = findGuildChef()

		if not chef then
			local chefDeadline = os.clock() + CHEF_FIND_TIMEOUT_SECONDS
			repeat
				chef, chefDist = findGuildChef()
				if chef then
					break
				end
				task.wait(0.25)
			until (not AutoEat.running) or os.clock() >= chefDeadline
		end

		if not AutoEat.running then
			setNoClip(false)
			return AutoEat.stop()
		end

		if not chef then
			setNoClip(false)
			telemetryLog("(AutoEat) Inside but no Guild Chef found, aborting.")
			Logger.longNotify("Automation: couldn't find the Guild Chef.")
			return AutoEat.stop()
		end

		telemetryLog("(AutoEat) [gb] inside, chef dist=%.0f", chefDist)

		-- Noclip on for the tween to the chef (may be a fair distance across the base).
		setNoClip(true)

		AutomationOverlay.setStage("Tweening to the Guild Chef")

		-- Stand at the chef-local offset (right at the counter), not dead-center on the chef's pivot.
		local okPivot, chefPivot = pcall(function()
			return chef:GetPivot()
		end)
		local standPos = (okPivot and chefPivot and (chefPivot * CHEF_STAND_OFFSET).Position) or instancePosition(chef)

		tweenToPosition(standPos, nil, 1.5)

		local fin = rootPosition() or Vector3.new()
		telemetryLog(
			"(AutoEat) [chef] okPivot=%s target=(%.1f,%.1f,%.1f) final=(%.1f,%.1f,%.1f)",
			tostring(okPivot),
			standPos.X,
			standPos.Y,
			standPos.Z,
			fin.X,
			fin.Y,
			fin.Z
		)

		-- 5.
		if AutoEat.running then
			buyFood()
		end

		if AutoEat.running then
			-- Give the purchase a moment to land in the backpack.
			task.wait(1)
			AutoEat.eatUntilFull()
		end

		setNoClip(false)

		-- 6.
		local exitDoor = findExitDoor()

		if exitDoor then
			local exitPos = instancePosition(exitDoor)
			if exitPos then
				tweenToPosition(exitPos)
			end

			-- Work the door only until we're actually OUT - leaving teleports us a big distance again, same jump signal as entering.
			local preExitPos = rootPosition() or Vector3.new()
			workDoor(exitDoor, function()
				local now = rootPosition()
				return now ~= nil and (now - preExitPos).Magnitude > ENTERED_JUMP_STUDS
			end, "Leaving the guild base")
		end

		AutomationOverlay.setStage("Done")
		AutoEat.stop()
	end)

	telemetryLog("(AutoEat) Started.")
end

---Stop the auto eat run.
function AutoEat.stop()
	if not AutoEat.running then
		return
	end

	AutoEat.running = false

	AntiAFK.stop("AutoEat")

	setNoClip(false)
	restoreTweenSpeed()
	stopTweens()

	AutomationOverlay.setVisible(false)

	telemetryLog("(AutoEat) Stopped.")
end

---Read a SurvivalStats slider fill (0 empty .. ~1 full), or nil if unreadable.
---@param path string[]
---@return number?
local function sliderFill(path)
	local node = players.LocalPlayer:FindFirstChild("PlayerGui")
	if not node then
		return nil
	end

	for _, name in ipairs(path) do
		node = node:FindFirstChild(name)
		if not node then
			return nil
		end
	end

	local ok, scale = pcall(function()
		return node.Size.Y.Scale
	end)

	return ok and scale or nil
end

---Current stomach (hunger) fill, 0 (starving) .. ~1 (full), or nil.
---@return number?
function AutoEat.hungerFill()
	return sliderFill(HUNGER_SLIDER_PATH)
end

---Current water (thirst) fill, 0 (parched) .. ~1 (full), or nil.
---@return number?
function AutoEat.thirstFill()
	return sliderFill(THIRST_SLIDER_PATH)
end

---Is there any Mushroom Bisque in the backpack (or already equipped)?
---@return boolean
function AutoEat.hasFood()
	local character = players.LocalPlayer.Character
	local backpack = players.LocalPlayer:FindFirstChild("Backpack")

	if backpack and backpack:FindFirstChild(FOOD_ITEM) then
		return true
	end

	return character ~= nil and character:FindFirstChild(FOOD_ITEM) ~= nil
end

--- Eat the food until both hunger and thirst are topped up (or it runs out / a safety cap).
function AutoEat.eatUntilFull()
	AutomationOverlay.setStage("Eating")

	for _ = 1, MAX_EAT_BITES do
		local hunger = AutoEat.hungerFill()
		local thirst = AutoEat.thirstFill()

		-- Stop once hunger is readably full and thirst isn't holding us back.
		if hunger and hunger >= FULL_TARGET and (thirst == nil or thirst >= FULL_TARGET) then
			break
		end

		local character = players.LocalPlayer.Character
		local humanoid = character and character:FindFirstChildOfClass("Humanoid")
		local backpack = players.LocalPlayer:FindFirstChild("Backpack")
		local food = (backpack and backpack:FindFirstChild(FOOD_ITEM)) or (character and character:FindFirstChild(FOOD_ITEM))

		if not humanoid or not food then
			break
		end

		-- Equip if still in the backpack, then take a bite (one click).
		if food.Parent == backpack then
			humanoid:EquipTool(food)
		end

		local equipped = character:FindFirstChild(FOOD_ITEM)
		if equipped then
			pcall(function()
				equipped:Activate()
			end)
		end

		task.wait(0.6)
	end
end

-- Return AutoEat module.
return AutoEat
end)()
end)
__bundle_register("Features/Game/Interactions", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Interaction utility.
local Interactions = {}

---@module Utility.Logger
local Logger = require("Utility/Logger")

-- Services.
local players = game:GetService("Players")
local replicatedStorage = game:GetService("ReplicatedStorage")
local virtualInputManager = game:GetService("VirtualInputManager")

-- Constants.
local DEBUGGING_MODE = true

-- FortitudeFarm and TitusFarm both hit the exact same failure this module was missing: fireproximityprompt alone did nothing for their prompts either -- no dialogue/ChoicePrompt ever opened, while a real E press worked fine.
local INTERACT_KEY_SPAM_INTERVAL = 0.1 -- How often to spam the interact key while waiting for dialogue.

---Telemetry log.
local function telemetryLog(...)
	if not DEBUGGING_MODE then
		return
	end

	Logger.warn(...)
end

---Use a tool.
---@param tool Instance
---@param data any Response to interaction to send with the tool use.
function Interactions.utool(tool, data)
	-- Equip tool.
	Interactions.etool(tool)

	-- Keep activating the tool until a 'ChoicePrompt' appears.
	telemetryLog("Activating tool '%s' until ChoicePrompt appears.", tool.Name)

	local playerGui = players.LocalPlayer:WaitForChild("PlayerGui")
	local choicePrompt = nil

	while not choicePrompt do
		-- Activate.
		tool:Activate()

		-- Check for 'ChoicePrompt' in GUI.
		choicePrompt = playerGui:FindFirstChild("ChoicePrompt")

		-- Wait.
		task.wait()
	end

	-- Fire the choice.
	telemetryLog("Firing ChoicePrompt ('%s') with data.", tostring(data))

	local choice = choicePrompt:WaitForChild("Choice")
	choice:FireServer(data)

	-- Wait for it to disappear.
	telemetryLog("Waiting for ChoicePrompt to disappear...")

	repeat
		task.wait()
	until not choicePrompt.Parent

	-- Done.
	telemetryLog("ChoicePrompt has disappeared.")
end

---Equip a tool.
---@param tool Instance
function Interactions.etool(tool)
	local character = players.LocalPlayer.Character
	if not character then
		return
	end

	local humanoid = character:FindFirstChildOfClass("Humanoid")
	if not humanoid then
		return
	end

	repeat
		-- Equip tool.
		humanoid:EquipTool(tool)

		-- Wait.
		task.wait()
	until tool.Parent == players.LocalPlayer.Character
end

---Perform an NPC-style interaction and go through the dialogue.
---@param instance Model
---@param actions table
---@param teleport boolean Should we teleport to the instance?
function Interactions.interact(instance, actions, teleport)
	if not instance or not instance.Parent then
		return
	end

	local interactPrompt = instance:FindFirstChild("InteractPrompt")
	if not interactPrompt or not interactPrompt:IsA("ProximityPrompt") then
		return
	end

	-- Step 1.
	telemetryLog("(%s) Interacting until dialogue appears.", instance.Name)

	local playerGui = players.LocalPlayer:WaitForChild("PlayerGui")
	local dialogueGui = playerGui:WaitForChild("DialogueGui")
	local character = players.LocalPlayer.Character or players.LocalPlayer.CharacterAdded:Wait()

	-- Same key resolution FortitudeFarm/TitusFarm use: the prompt's own bound key, falling back to the default E if it's not set.
	local interactKeyCode = interactPrompt.KeyboardKeyCode
	if interactKeyCode == Enum.KeyCode.Unknown then
		interactKeyCode = Enum.KeyCode.E
	end

	local lastKeySpamAt = 0

	repeat
		-- Teleport.
		if teleport then
			character:PivotTo(instance:GetPivot())
		end

		-- Fire.
		fireproximityprompt(interactPrompt)

		-- Spam the real bound key too, throttled - some server-side interact checks silently ignore the exploit-only fire call on its own.
		if os.clock() - lastKeySpamAt >= INTERACT_KEY_SPAM_INTERVAL then
			lastKeySpamAt = os.clock()

			virtualInputManager:SendKeyEvent(true, interactKeyCode, false, game)
			virtualInputManager:SendKeyEvent(false, interactKeyCode, false, game)
		end

		-- Wait.
		task.wait()
	until dialogueGui.Enabled

	-- Step 2.
	telemetryLog("(%s) Going through dialogue with %i actions.", instance.Name, #actions)

	local requests = replicatedStorage:WaitForChild("Requests")
	local dialogueEvent = requests:WaitForChild("SendDialogue")

	local dialogueCompleted = false

	dialogueEvent.OnClientEvent:Connect(function()
		dialogueCompleted = true
	end)

	for _, action in next, actions do
		dialogueEvent:FireServer(action)

		dialogueCompleted = false

		telemetryLog(
			"(%s) Sent dialogue action '%s' and now waiting for OnClientEvent to fire.",
			instance.Name,
			action.exit and "[EXIT]" or (action.choice or "N/A")
		)

		if action.exit then
			break
		end

		repeat
			task.wait()
		until dialogueCompleted
	end

	telemetryLog("(%s) Completed dialogue.", instance.Name)
end

-- Return Interactions module.
return Interactions
end)
__bundle_register("Features/Automation/AutoBank", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
-- AutoBank module.
local AutoBank = { running = false }

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Utility.Finder
local Finder = require("Utility/Finder")

---@module Features.Game.Tweening
local Tweening = require("Features/Game/Tweening")

---@module Features.Game.Interactions
local Interactions = require("Features/Game/Interactions")

---@module Game.AntiAFK
local AntiAFK = require("Game/AntiAFK")

---@module GUI.AutomationOverlay
local AutomationOverlay = require("GUI/AutomationOverlay")

-- Services.
local players = game:GetService("Players")
local replicatedStorage = game:GetService("ReplicatedStorage")

-- Constants.
local DEPTHS_PLACE_ID = 5735553160

local TWEEN_PREFIX = "AutoBank_Tween"

-- Recorded live: "Fort merit bank position".
local BANK_POSITION = Vector3.new(-7495.27, 45.36, 3191.06)

-- Reuses TitusFarm's own proven-safe cruising altitude for this same Eastern/Etrean Luminant region - comfortably above every building/terrain feature there, so a straight-up liftoff works regardless of where we start.
local BANK_APPROACH_ALTITUDE = 4825.71

-- How far past the recorded bank position (straight up) to land - enough to clear the counter/teller model without landing on top of it.
local LANDING_Y_OFFSET = 5

-- How close the recorded position needs to be to an actual NPC-with-InteractPrompt for us to call it "the teller".
local NPC_SEARCH_RADIUS_STUDS = 40

local NPC_STREAM_TIMEOUT_SECONDS = 15
local BANKGUI_TIMEOUT_SECONDS = 10

local BANK_DIALOGUE_CHOICE = "Can I access my account?"

-- Auto Bank dropdown (built under the Titus Farm section).
local BANK_DROPDOWN_ID = "AutoTitusBankItems"

-- Display name (as shown in the dropdown) -> Finder.tools match string (a Lua pattern; partial by default, case-sensitive).
local BANK_ITEM_MATCHES = {
	["Armorer's Needle"] = "Armorer's Needle",
	["Smith's Alloy"] = "Smith's Alloy",
	["Idol of Yun Shul"] = "Idol of Yun Shul",
	["Moonseyes"] = "Moonseye",
}

-- After firing the initial deposit, a stack of more than 1 of the same item pops a separate "Deposit Items" quantity prompt - one per stack that needs it, not one for the whole batch.
local DEPOSIT_QUANTITY_PROMPT_TIMEOUT_SECONDS = 3
-- Safety cap - how many quantity prompts we'll answer in one deposit run, so a misidentified/looping GUI can't spin this forever.
local DEPOSIT_QUANTITY_PROMPT_MAX_COUNT = 25

---Telemetry log.
local function telemetryLog(...)
	Logger.warn(...)
end

--- Travel from wherever we currently are to the bank, high in the air, then drop down onto it - same up/across/down shape as TitusFarm's gate approach.
---@return boolean True if we actually ended up near the bank.
local function travelToBank()
	AutomationOverlay.setStage("Tweening to bank")

	-- Best-effort - the teller won't exist client-side to search for until this part of the world has actually streamed in, same trick Teleport.lua and TitusFarm both already lean on for far-away destinations.
	pcall(players.LocalPlayer.RequestStreamAroundAsync, players.LocalPlayer, BANK_POSITION, 0.1)

	local character = players.LocalPlayer.Character or players.LocalPlayer.CharacterAdded:Wait()
	local humanoidRootPart = character:WaitForChild("HumanoidRootPart")

	local positions = {
		-- Straight up from wherever we currently are.
		CFrame.new(humanoidRootPart.Position.X, BANK_APPROACH_ALTITUDE, humanoidRootPart.Position.Z),

		-- Across to above the bank at that same safe altitude.
		CFrame.new(BANK_POSITION.X, BANK_APPROACH_ALTITUDE, BANK_POSITION.Z),

		-- Drop down onto the bank.
		CFrame.new(BANK_POSITION.X, BANK_POSITION.Y + LANDING_Y_OFFSET, BANK_POSITION.Z),
	}

	for idx, cframe in next, positions do
		Tweening.goal(string.format("%s_%i", TWEEN_PREFIX, idx), cframe, idx ~= #positions)
	end

	Tweening.wait(string.format("%s_%i", TWEEN_PREFIX, #positions))

	return Finder.near(BANK_POSITION, 75)
end

---Stop every leg of the travel tween, whatever's still active.
local function stopTravelTween()
	for idx = 1, 3 do
		Tweening.stop(string.format("%s_%i", TWEEN_PREFIX, idx))
	end
end

--- Find the bank teller near the recorded position, giving the world a moment to stream in if we just arrived from far away.
---@return Model?
local function findBankTeller()
	AutomationOverlay.setStage("Looking for the teller")

	local deadline = os.clock() + NPC_STREAM_TIMEOUT_SECONDS

	repeat
		local npc = Finder.npc(BANK_POSITION, NPC_SEARCH_RADIUS_STUDS)
		if npc then
			return npc
		end

		pcall(players.LocalPlayer.RequestStreamAroundAsync, players.LocalPlayer, BANK_POSITION, 0.1)

		task.wait()
	until (not AutoBank.running) or os.clock() >= deadline

	return Finder.npc(BANK_POSITION, NPC_SEARCH_RADIUS_STUDS)
end

--- Find every plain string/number that a GuiObject subtree is showing as text - helper for hunting down the quantity prompt without a known instance path.
---@param root Instance
---@return {[1]: TextLabel|TextButton, [2]: string}[]
local function collectGuiTexts(root)
	local found = {}

	for _, descendant in next, root:GetDescendants() do
		if descendant:IsA("TextLabel") or descendant:IsA("TextButton") or descendant:IsA("TextBox") then
			found[#found + 1] = { descendant, descendant.Text }
		end
	end

	return found
end

--- Look for the "Deposit Items" quantity prompt ("Deposit how many?" + a Submit button) anywhere under PlayerGui.
---@param playerGui Instance
---@return GuiObject? promptRoot, TextButton? submitButton
local function findDepositQuantityPrompt(playerGui)
	for _, screenGui in next, playerGui:GetChildren() do
		if not screenGui:IsA("ScreenGui") and not screenGui:IsA("GuiObject") then
			continue
		end

		local texts = collectGuiTexts(screenGui)

		local hasPrompt, submitButton = false, nil

		for _, entry in next, texts do
			local instance, text = entry[1], entry[2]

			if type(text) == "string" and text:match("[Dd]eposit how many") then
				hasPrompt = true
			end

			if instance:IsA("TextButton") and text == "Submit" then
				submitButton = instance
			end
		end

		if hasPrompt and submitButton then
			return screenGui, submitButton
		end
	end

	return nil, nil
end

--- Read the max deposit amount straight off the prompt's own UI so we deposit the whole stack rather than guessing/hardcoding a quantity.
---@param promptRoot GuiObject
---@return number? max
local function readDepositQuantityMax(promptRoot)
	local max = nil

	for _, entry in next, collectGuiTexts(promptRoot) do
		local text = entry[2]
		local number = tonumber(text)

		if number and (not max or number > max) then
			max = number
		end
	end

	return max
end

--- Resolve the "Choice" RemoteFunction the quantity prompt's Submit button invokes.
---@param promptRoot GuiObject
---@return RemoteFunction?
local function resolveDepositQuantityRemote(promptRoot)
	-- 1.
	local requests = replicatedStorage:FindFirstChild("Requests")
	if requests then
		local remote = requests:FindFirstChild("Choice")
		if remote and remote:IsA("RemoteFunction") then
			return remote
		end
	end

	-- 2.
	for _, descendant in next, promptRoot:GetDescendants() do
		if descendant.Name == "Choice" and descendant:IsA("RemoteFunction") then
			return descendant
		end
	end

	-- 3.
	if getnilinstances then
		local ok, instances = pcall(getnilinstances)
		if ok and instances then
			for _, instance in next, instances do
				if instance.Name == "Choice" and instance:IsA("RemoteFunction") then
					return instance
				end
			end
		end
	end

	return nil
end

--- Answer every "Deposit how many?" quantity prompt that pops up after firing the initial deposit choice, always submitting the full amount shown (i.e.
local function answerDepositQuantityPrompts(playerGui)
	for attempt = 1, DEPOSIT_QUANTITY_PROMPT_MAX_COUNT do
		local deadline = os.clock() + DEPOSIT_QUANTITY_PROMPT_TIMEOUT_SECONDS
		local promptRoot, submitButton = nil, nil

		repeat
			promptRoot, submitButton = findDepositQuantityPrompt(playerGui)

			if promptRoot then
				break
			end

			task.wait()
		until os.clock() >= deadline

		if not promptRoot then
			-- Nothing showed up in the window - assume every stack that needed an amount has already been answered.
			return
		end

		local max = readDepositQuantityMax(promptRoot)
		local remote = resolveDepositQuantityRemote(promptRoot)

		if not max or not remote then
			telemetryLog(
				"(AutoBank) Found a deposit quantity prompt but couldn't resolve %s, aborting the prompt loop.",
				(not max and "its max amount") or "its 'Choice' remote"
			)
			Logger.longNotify("Automation: stuck on a deposit amount prompt, deposit finished partially.")
			return
		end

		telemetryLog("(AutoBank) Quantity prompt #%i - submitting the full amount (%i).", attempt, max)

		local ok = pcall(function()
			remote:InvokeServer(max)
		end)

		if not ok then
			-- Fall back to clicking Submit for real, same "exploit call alone isn't trusted" situation Interactions.lua's key-spam fix covers - some server-side checks want to see the actual button activated.
			pcall(function()
				submitButton:Activate()
			end)
		end

		-- Give the prompt a moment to actually close before checking for the next one (or deciding there isn't one).
		local closeDeadline = os.clock() + DEPOSIT_QUANTITY_PROMPT_TIMEOUT_SECONDS
		repeat
			task.wait()
		until (not promptRoot.Parent) or os.clock() >= closeDeadline
	end

	telemetryLog("(AutoBank) Hit the %i-prompt safety cap, stopping.", DEPOSIT_QUANTITY_PROMPT_MAX_COUNT)
end

--- The Finder.tools match strings for whatever item types are currently ticked in the Auto Bank dropdown.
---@return string[]
function AutoBank.selectedMatches()
	local dropdown = Options and Options[BANK_DROPDOWN_ID]

	if not dropdown or type(dropdown.Value) ~= "table" then
		return { BANK_ITEM_MATCHES["Moonseyes"] }
	end

	local matches = {}

	for option, selected in next, dropdown.Value do
		if selected then
			local match = BANK_ITEM_MATCHES[option]
			if match then
				matches[#matches + 1] = match
			end
		end
	end

	return matches
end

--- Every backpack tool matching any currently-selected Auto Bank item type, with duplicates removed (a single tool could match more than one pattern).
---@return Tool[]
function AutoBank.gatherDepositables()
	local seen = {}
	local tools = {}

	for _, match in next, AutoBank.selectedMatches() do
		local ok, matched = pcall(Finder.tools, match, false)

		if ok and type(matched) == "table" then
			for _, tool in next, matched do
				if not seen[tool] then
					seen[tool] = true
					tools[#tools + 1] = tool
				end
			end
		end
	end

	return tools
end

--- How many depositable items are in the backpack right now - what the Titus farm's threshold check counts against.
---@return number
function AutoBank.depositableCount()
	return #AutoBank.gatherDepositables()
end

---Deposit every selected item currently in the backpack.
local function depositRelics()
	AutomationOverlay.setStage("Waiting for bank")

	local playerGui = players.LocalPlayer:WaitForChild("PlayerGui")
	local bankGui = playerGui:WaitForChild("BankGui", BANKGUI_TIMEOUT_SECONDS)

	if not bankGui then
		telemetryLog("(AutoBank) 'BankGui' never appeared, aborting.")
		Logger.longNotify("Automation: bank never opened.")
		return
	end

	local relics = AutoBank.gatherDepositables()

	if #relics <= 0 then
		telemetryLog("(AutoBank) No selected items in the backpack, nothing to deposit.")
		Logger.notify("Nothing selected to bank.")
		return
	end

	AutomationOverlay.setStage(string.format("Depositing %i item(s)", #relics))

	local choice = bankGui:WaitForChild("Choice")
	choice:FireServer("deposit", relics)

	-- Any stack of more than 1 of the same item pops its own "Deposit how many?" prompt - answer all of them before calling this done.
	AutomationOverlay.setStage("Confirming deposit amount(s)")
	answerDepositQuantityPrompts(playerGui)

	telemetryLog("(AutoBank) Deposited %i item(s).", #relics)
	Logger.notify("Banked %i item(s).", #relics)
end

---Start the auto bank run.
function AutoBank.start()
	if AutoBank.running then
		return
	end

	-- The Depths is its own separate place - there's no bank, no Fort Merit, nothing for this to do there.
	if game.PlaceId == DEPTHS_PLACE_ID then
		telemetryLog("(AutoBank) In the Depths, refusing to start.")
		Logger.longNotify("Automation: no bank in the Depths.")
		return
	end

	AutoBank.running = true

	AntiAFK.start("AutoBank")

	AutomationOverlay.onStop(AutoBank.stop)
	AutomationOverlay.setStage("Starting")
	AutomationOverlay.setVisible(true)

	task.spawn(function()
		local arrived = travelToBank()

		if not AutoBank.running then
			return AutoBank.stop()
		end

		if not arrived then
			telemetryLog("(AutoBank) Never got near the bank, aborting.")
			Logger.longNotify("Automation: couldn't reach the bank.")
			return AutoBank.stop()
		end

		local teller = findBankTeller()

		if not AutoBank.running then
			return AutoBank.stop()
		end

		if not teller then
			telemetryLog("(AutoBank) Could not find the bank teller near the recorded position, aborting.")
			Logger.longNotify("Automation: couldn't find the bank teller.")
			return AutoBank.stop()
		end

		AutomationOverlay.setStage("Talking to teller")
		telemetryLog("(AutoBank) Interacting with '%s'.", teller.Name)

		Interactions.interact(teller, { { choice = BANK_DIALOGUE_CHOICE } }, false)

		if not AutoBank.running then
			return AutoBank.stop()
		end

		depositRelics()

		AutomationOverlay.setStage("Done")

		AutoBank.stop()
	end)

	telemetryLog("(AutoBank) Started.")
end

---Stop the auto bank run.
function AutoBank.stop()
	if not AutoBank.running then
		return
	end

	AutoBank.running = false

	AntiAFK.stop("AutoBank")

	stopTravelTween()

	AutomationOverlay.setVisible(false)

	telemetryLog("(AutoBank) Stopped.")
end

-- Return AutoBank module.
return AutoBank
end)()
end)
__bundle_register("Features/Automation/EchoFarm", function(require, _LOADED, __bundle_register, __bundle_modules)
-- EchoFarm module.
---@todo: The first issue is that the farm can be broken when user gets kicked for any reason. It cannot detect that, when it should rejoin the lobby again.
---@todo: The second issue is that we don't have any proper player checks in place.
---@todo: The third issue is that we don't have any proper validity checks. For example, does the user even have a Battleaxe to swap down initially? Do we even have a 'Fort Merit' spawn before trying?
local EchoFarm = { voiding = false }

---@module Utility.PersistentData
local PersistentData = require("Utility/PersistentData")

---@module Game.AntiAFK
local AntiAFK = require("Game/AntiAFK")

---@module Utility.Finder
local Finder = require("Utility/Finder")

---@module Game.Wipe
local Wipe = require("Game/Wipe")

---@module Features.Game.Tweening
local Tweening = require("Features/Game/Tweening")

---@module Game.ServerHop
local ServerHop = require("Game/ServerHop")

---@module Utility.TaskSpawner
local TaskSpawner = require("Utility/TaskSpawner")

---@module Features.Game.Interactions
local Interactions = require("Features/Game/Interactions")

---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Features.Automation.AutoLoot
local AutoLoot = require("Features/Automation/AutoLoot")

---@module Features.Automation.Objects.AutoLootOptions
local AutoLootOptions = require("Features/Automation/Objects/AutoLootOptions")

---@module Utility.GameReady
local GameReady = require("Utility/GameReady")

-- Services.
local players = game:GetService("Players")
local replicatedStorage = game:GetService("ReplicatedStorage")
local httpService = game:GetService("HttpService")

-- Constants.
local EASTERN_PLACE_ID = 6473861193
local TITUS_PLACE_ID = 8668476218
local DEBUGGING_MODE = true

-- On-disk resume data.
local DATA_FILE = "echofarm_data"

-- Automation-webhook bookkeeping, kept on disk because one echo cycle spans several teleports and re-executes - any of which would reset an in-memory tally or clock.
local CYCLES_FILE = "echofarm_cycles"
local CYCLE_START_FILE = "echofarm_cyclestart"

-- The two character-creation picks the server now requires before it will let FinishCreation succeed.
local DEFAULT_BOON = "Steadfast"
local DEFAULT_FLAW = "Glutton"

-- Maid.
local echoFarmMaid = Maid.new()

-- Currently running?
local running = false

---Telemetry log.
local function telemetryLog(...)
	if not DEBUGGING_MODE then
		return
	end

	Logger.warn(...)
end

--- Best-known data slot, falling back to the on-disk copy.
---@return string?
local function bestSlot()
	local live = players.LocalPlayer:GetAttribute("DataSlot")
	if live ~= nil then
		return live
	end

	local data = EchoFarm.diskData()
	return data and data.slot
end

--- Write the current efdata table to disk so the farm survives the game<->lobby hop.
---@param data table?
local function syncDisk(data)
	if not writefile or type(data) ~= "table" then
		return
	end

	local ok, encoded = pcall(httpService.JSONEncode, httpService, data)
	if not ok then
		return
	end

	pcall(writefile, DATA_FILE, encoded)
end

--- Delete the on-disk resume data (and the webhook bookkeeping).
local function clearDisk()
	if not delfile then
		return
	end

	for _, file in next, { DATA_FILE, CYCLES_FILE, CYCLE_START_FILE } do
		if not isfile or isfile(file) then
			pcall(delfile, file)
		end
	end
end

---Read a number out of a disk file, or a default when it's missing/unreadable.
---@param file string
---@param default number
---@return number
local function readNumberFile(file, default)
	if not isfile or not readfile or not isfile(file) then
		return default
	end

	local ok, contents = pcall(readfile, file)
	if not ok or type(contents) ~= "string" then
		return default
	end

	return tonumber(contents) or default
end

---Stamp the start of a new cycle (wall clock) so cend() can report its duration.
local function markCycleStart()
	if not writefile then
		return
	end

	pcall(writefile, CYCLE_START_FILE, tostring(os.time()))
end

---Increment and return the on-disk completed-cycle counter.
---@return number
local function bumpCycleCount()
	local current = readNumberFile(CYCLES_FILE, 0) + 1

	if writefile then
		pcall(writefile, CYCLES_FILE, tostring(current))
	end

	return current
end

--- Snapshot the backpack as a { [toolName] = count } map - what this cycle's character is holding right before it gets wiped, reported as the cycle's "loot".
---@return table
local function backpackSummary()
	local counts = {}
	local backpack = players.LocalPlayer:FindFirstChild("Backpack")

	if not backpack then
		return counts
	end

	for _, item in next, backpack:GetChildren() do
		if item:IsA("Tool") then
			counts[item.Name] = (counts[item.Name] or 0) + 1
		end
	end

	return counts
end

--- The efdata table saved to disk for cross-place resume, or nil if none/unreadable.
---@return table?
function EchoFarm.diskData()
	if not isfile or not readfile then
		return nil
	end

	if not isfile(DATA_FILE) then
		return nil
	end

	local ok, contents = pcall(readfile, DATA_FILE)
	if not ok or type(contents) ~= "string" or contents == "" then
		return nil
	end

	local decoded
	ok, decoded = pcall(httpService.JSONDecode, httpService, contents)
	if not ok or type(decoded) ~= "table" then
		return nil
	end

	return decoded
end

--- Is there a valid on-disk Echo farm to resume, regardless of the place we're in?
---@return boolean
function EchoFarm.isActiveOnDisk()
	local data = EchoFarm.diskData()
	return data ~= nil and data.slot ~= nil
end

---Handle CharacterCreation state.
function EchoFarm.ccreation()
	-- A fresh character = the start of a new cycle.
	markCycleStart()

	local requests = replicatedStorage:WaitForChild("Requests")
	local characterCreator = requests:WaitForChild("CharacterCreator")
	local pickSpawn = characterCreator:WaitForChild("PickSpawn")
	local changeWeapon = characterCreator:WaitForChild("ChangeWeapon")
	-- Bounded waits + FindFirstChild fallback: if either remote ever got renamed or isn't present yet, a plain WaitForChild would yield forever and silently stall the whole farm here.
	local pickBoon = characterCreator:WaitForChild("PickBoon", 10) or characterCreator:FindFirstChild("PickBoon")
	local pickFlaw = characterCreator:WaitForChild("PickFlaw", 10) or characterCreator:FindFirstChild("PickFlaw")
	local finishCreation = characterCreator:WaitForChild("FinishCreation")
	local toggleMetaModifier = requests:WaitForChild("ToggleMetaModifier")

	if not pickBoon or not pickFlaw then
		return error("CharacterCreator is missing PickBoon/PickFlaw - did the remote paths change?")
	end

	-- Which boon/flaw to pick, from efdata (defaulting to Steadfast/Glutton).
	local data = PersistentData.get("efdata") or {}
	local boon = data.boon or DEFAULT_BOON
	local flaw = data.flaw or DEFAULT_FLAW

	local success = pickSpawn:InvokeServer("Merit")
	if not success then
		return error("Does the user not have the 'Fort Merit' spawn?")
	end

	success = changeWeapon:InvokeServer("Battleaxe")
	if not success then
		return error("Does the user not have the 'Battleaxe' weapon?")
	end

	-- Pick the flaw BEFORE the boon.
	local flawResult = pickFlaw:InvokeServer(flaw)
	local boonResult = pickBoon:InvokeServer(boon)

	telemetryLog(
		"(EchoFarm) PickFlaw('%s') -> %s | PickBoon('%s') -> %s",
		tostring(flaw),
		tostring(flawResult),
		tostring(boon),
		tostring(boonResult)
	)

	toggleMetaModifier:FireServer("All")

	local playerGui = players.LocalPlayer:WaitForChild("PlayerGui")

	-- Re-assert window: if creation still hasn't finished a couple seconds in, the first pick may have landed too early (before the creator was ready).
	local reassertAt = os.clock() + 2

	repeat
		-- Answer any confirmation prompt the creator throws up (some picks pop one before they finalize).
		local choicePrompt = playerGui:FindFirstChild("ChoicePrompt")
		local choice = choicePrompt and choicePrompt:FindFirstChild("Choice")

		if choice then
			choice:FireServer(true)
		end

		if os.clock() >= reassertAt then
			reassertAt = os.clock() + 2

			pickFlaw:InvokeServer(flaw)
			pickBoon:InvokeServer(boon)

			telemetryLog("(EchoFarm) FinishCreation still pending, re-asserted flaw/boon.")
		end

		task.wait()
	until finishCreation:InvokeServer()
end

---Go to the Titus fight.
---@param tdata table Fake data.
function EchoFarm.titus(tdata)
	-- Request start.
	local requests = replicatedStorage:WaitForChild("Requests")
	local startMenu = requests:WaitForChild("StartMenu")
	local start = startMenu:WaitForChild("Start")

	telemetryLog("(EchoFarm) Requesting start.")

	start:FireServer()

	local data = tdata or PersistentData.get("efdata")
	if not data then
		return error("No EchoFarm data found in PersistentData.")
	end

	local positions = {
		-- From spawn, we need to be up in the jar, so we won't be seen.
		CFrame.new(-7518.70, 4825.71, 3483.19),

		-- Then, tween above the gate.
		CFrame.new(-6877.09, 4825.71, 2829.91),

		-- Teleport ourselves down.
		CFrame.new(-6877.50, 329.94, 2829.21),
	}

	-- Humanoid root part.
	local character = players.LocalPlayer.Character or players.LocalPlayer.CharacterAdded:Wait()
	local humanoidRootPart = character:WaitForChild("HumanoidRootPart")

	-- First position.
	local firstPosition = positions[1].Position

	firstPosition = Vector3.new(firstPosition.X, humanoidRootPart.Position.Y, firstPosition.Z)

	-- If we're not near the filltered first position, skip that position.
	if not Finder.near(firstPosition, 100) then
		table.remove(positions, 1)
	end

	-- Move towards each position.
	telemetryLog("(EchoFarm) Moving to Titus gate.")

	for idx, cframe in next, positions do
		Tweening.goal(string.format("EF_TweenToGate_%i", idx), cframe, idx ~= #positions)
	end

	-- We wait until we've reached the last position.
	telemetryLog("(EchoFarm) Waiting to reach gate.")

	Tweening.wait(string.format("EF_TweenToGate_%i", #positions))

	-- Is anyone near here?
	telemetryLog("(EchoFarm) Checking if anyone is near the gate.")

	local map = workspace:WaitForChild("Map")
	local meritEntry = map:WaitForChild("MeritEntry")
	local interactPrompt = meritEntry:FindFirstChildWhichIsA("ProximityPrompt")

	-- Are we not near the gate at all?
	if not Finder.near(meritEntry.Position, 50) then
		return error("We are not near the 'MeritEntry' model.")
	end

	-- Is someone already here?
	telemetryLog("(EchoFarm) Checking if anyone is near the gate.")

	if Finder.pnear(meritEntry.Position, 100) then
		return ServerHop.hop(data.slot, true)
	end

	-- Keep trying to interact with the prompt and teleport us there.
	telemetryLog("(EchoFarm) Interacting with gate.")

	while task.wait() do
		fireproximityprompt(interactPrompt)
	end
end

---Wait for a chest to spawn on us.
---@param tdata table Fake data.
---@return Instance
function EchoFarm.wfc(tdata)
	local data = tdata or PersistentData.get("efdata")
	if not data then
		return error("No EchoFarm data found in PersistentData.")
	end

	local character = players.LocalPlayer.Character or players.LocalPlayer.CharacterAdded:Wait()
	local humanoidRootPart = character and character:FindFirstChild("HumanoidRootPart")
	local startTimestamp = os.clock()
	local voidingTicks = 0

	while task.wait() do
		if os.clock() - startTimestamp >= 60 then
			return ServerHop.hop(data.slot, false)
		end

		EchoFarm.voiding = voidingTicks % 10 == 0
		voidingTicks = voidingTicks + 1

		local chest = Finder.chest(humanoidRootPart.Position, 300)
		if not chest then
			continue
		end

		return chest
	end

	return nil
end

---Wait for ChoicePrompt by interacting with a chest.
---@param chest Instance
---@return Instance?
function EchoFarm.wcp(chest)
	local playerGui = players.LocalPlayer:WaitForChild("PlayerGui")
	local interactPrompt = chest:WaitForChild("InteractPrompt")

	while task.wait() do
		fireproximityprompt(interactPrompt)

		local prompt = playerGui:FindFirstChild("ChoicePrompt")
		if not prompt then
			continue
		end

		return prompt
	end

	return nil
end

---Kill titus.
---@param tdata table Fake data.
function EchoFarm.ktitus(tdata)
	-- Request start.
	local requests = replicatedStorage:WaitForChild("Requests")
	local startMenu = requests:WaitForChild("StartMenu")
	local start = startMenu:WaitForChild("Start")

	telemetryLog("(EchoFarm) Requesting start.")

	repeat
		-- Fire server.
		start:FireServer()

		-- Wait.
		task.wait()
	until #workspace:WaitForChild("Live"):GetChildren() > 0

	local data = tdata or PersistentData.get("efdata")
	if not data then
		return error("No EchoFarm data found in PersistentData.")
	end

	-- Enable voiding.
	telemetryLog("(EchoFarm) Enabling voiding.")

	EchoFarm.voiding = true
	AutoLoot.ignore = true

	-- Is anyone with us?
	telemetryLog("(EchoFarm) Checking if anyone is in the dungeon with us.")

	if #players:GetPlayers() > 1 then
		return ServerHop.hop(data.slot, false)
	end

	-- Wait for chest to spawn near us.
	telemetryLog("(EchoFarm) Waiting for chest to spawn on us.")

	local chest = EchoFarm.wfc(tdata)
	if not chest then
		return error("No chest found on us.")
	end

	-- Keep interacting until we get a choice prompt.
	telemetryLog("(EchoFarm) Interacting with chest.")

	local choicePrompt = EchoFarm.wcp(chest)
	if not choicePrompt then
		return error("No ChoicePrompt found after interacting with chest.")
	end

	-- Process chest.
	telemetryLog("(EchoFarm) Processing chest.")

	AutoLoot.process(choicePrompt, AutoLootOptions.new(0, 0, {}, true))

	-- Wait until we're finished.
	telemetryLog("(EchoFarm) Waiting until auto loot is finished.")

	local backpack = players.LocalPlayer.Backpack
	local items = #backpack:GetChildren()

	repeat
		task.wait()
	until not AutoLoot.active()

	-- Wait until we have more items in our backpack.
	telemetryLog("(EchoFarm) Waiting until we have more items in our backpack.")

	repeat
		task.wait()
	until #backpack:GetChildren() > items

	-- Check if we have an enchant stone.
	telemetryLog("(EchoFarm) Checking for enchant stone.")

	local stone = nil
	local timestamp = os.clock()

	repeat
		-- Look for stone.
		stone = Finder.tool("Enchant Stone", false)

		-- Has it been over a second?
		if os.clock() - timestamp >= 1.0 then
			return ServerHop.hop(data.slot, false)
		end

		-- Wait.
		task.wait()
	until stone

	-- Mark a kill.
	telemetryLog("(EchoFarm) Marking Titus kill.")

	if not tdata then
		PersistentData.stf("efdata", "tkill", true)
		syncDisk(PersistentData.get("efdata"))
	end

	-- Teleport to exit.
	telemetryLog("(EchoFarm) Teleporting to dungeon exit.")

	local detainmentCore = workspace:WaitForChild("DetainmentCore")
	local dungeonExit = detainmentCore:WaitForChild("DungeonExit")

	while task.wait() do
		players.LocalPlayer.Character:PivotTo(CFrame.new(dungeonExit.Position))
	end
end

---End the cycle and wipe the character.
---@param tdata table Fake data.
function EchoFarm.cend(tdata)
	-- Log.
	telemetryLog("(EchoFarm) Invoking cycle end.")

	-- Invoke wipe and clear Titus kill marker.
	local data = tdata or PersistentData.get("efdata")
	if not data then
		return error("No EchoFarm data found in PersistentData.")
	end

	if not tdata then
		PersistentData.stf("efdata", "tkill", false)
		syncDisk(PersistentData.get("efdata"))

	end

	Wipe.invoke(data.slot, { "Battleaxe" })
end

---Titus killed.
---@param tdata table Fake data.
function EchoFarm.tkilled(tdata)
	-- Request start.
	local requests = replicatedStorage:WaitForChild("Requests")
	local startMenu = requests:WaitForChild("StartMenu")
	local start = startMenu:WaitForChild("Start")

	telemetryLog("(EchoFarm) Requesting start.")

	start:FireServer()

	local data = tdata or PersistentData.get("efdata")
	if not data then
		return error("No EchoFarm data found in PersistentData.")
	end

	-- Tween up in the air.
	telemetryLog("(EchoFarm) Tweening up in the air after killing Titus.")

	Tweening.goal("EchoFarm_TitusKilledAirTween", CFrame.new(-6877.50, 4825.94, 2829.21), false)
	Tweening.wait("EchoFarm_TitusKilledAirTween")

	-- Enchant Battleaxe.
	telemetryLog("(EchoFarm) Enchanting Battleaxe.")

	local weapon = Finder.weweapon("Battleaxe")
	if not weapon then
		return Logger.longNotify("You do not have a valid Battleaxe to enchant.")
	end

	Interactions.etool(weapon)

	weapon:Activate()

	local stone = Finder.tool("Enchant Stone", false)
	if not stone then
		return Logger.longNotify("You do not have an Enchant Stone to use.")
	end

	Interactions.utool(stone, true)

	-- Wait until it is fully enchanted.
	local equipped = Finder.tool("Weapon", true)

	repeat
		task.wait()
	until equipped:GetAttribute("RichStats"):match("Enchant")

	-- Use idol if we have it.
	telemetryLog("(EchoFarm) Using Idol if we have one.")

	local idol = Finder.tool("Idol", false)
	if idol then
		Interactions.utool(idol, "Give me relief from my Flaws.")
	end

	-- Invoke end.
	EchoFarm.cend(tdata)
end

---Start the EchoFarm module.
function EchoFarm.start()
	local localPlayer = players.LocalPlayer
	if not localPlayer then
		return
	end

	local data = PersistentData.get("efdata")
	if not data then
		return error("No EchoFarm data found in PersistentData.")
	end

	if not data.slot then
		return error("No data slot found for EchoFarm.")
	end

	if running then
		return
	end

	running = true

	PersistentData.set("efdata", data)

	-- Mirror efdata to disk so a server hop can quick join back in and re-arm the farm on the far side.
	syncDisk(data)

	AntiAFK.start("EchoFarm")

	-- Everything below acts on the world and reads the game's "GameLoaded" attribute, so none of it can run until the world is actually playable - on a cold auto-execute start fires before the character/world have streamed in.
	echoFarmMaid:mark(TaskSpawner.spawn("EchoFarm_Boot", function()
		GameReady.waitUntilPlayable()

		if not running then
			return
		end

		if localPlayer:GetAttribute("GameLoaded") == "CharacterCreation" then
			data.wiped = true
		end

		if not data.wiped then
			return Wipe.invoke(data.slot, { "Battleaxe" })
		end

		if localPlayer:GetAttribute("GameLoaded") == "CharacterCreation" then
			return echoFarmMaid:mark(TaskSpawner.spawn("EchoFarm_CCreation", EchoFarm.ccreation))
		end

		if game.PlaceId == EASTERN_PLACE_ID and not data.tkill then
			return echoFarmMaid:mark(TaskSpawner.spawn("EchoFarm_Titus", EchoFarm.titus))
		end

		if game.PlaceId == TITUS_PLACE_ID then
			return echoFarmMaid:mark(TaskSpawner.spawn("EchoFarm_Dungeon_KillTitusFSM", EchoFarm.ktitus))
		end

		if game.PlaceId == EASTERN_PLACE_ID and data.tkill then
			return echoFarmMaid:mark(TaskSpawner.spawn("EchoFarm_Eastern_KilledTitusFSM", EchoFarm.tkilled))
		end
	end))
end

---Invoke the EchoFarm module.
function EchoFarm.invoke()
	local data = {
		-- Have we killed Titus?
		tkill = false,

		-- Have we done atleast one wipe to do initial setup?
		wiped = false,

		-- What is the current slot that we are farming on?
		slot = bestSlot(),

		-- Which boon/flaw to pick during character creation.
		boon = DEFAULT_BOON,
		flaw = DEFAULT_FLAW,
	}

	PersistentData.set("efdata", data)

	-- Seed the disk copy up front too, so even a hop that happens before start() gets a chance to sync still has something to resume from.
	syncDisk(data)

	EchoFarm.start()
end

---Stop the EchoFarm module.
function EchoFarm.stop()
	if not running then
		return
	end

	running = false

	-- Stop AntiAFK.
	AntiAFK.stop("EchoFarm")

	-- Clear persistent data.
	PersistentData.set("efdata", nil)

	-- Kill the disk copy too - a manual stop must not leave a file behind that would silently re-arm the farm the next time the script is executed.
	clearDisk()

	-- Stop all tasks.
	echoFarmMaid:clean()

	-- Cancel all tweens related to EchoFarm.
	for _, data in next, Tweening.queue do
		if not data.identifier:match("EF") then
			continue
		end

		Tweening.cancel(data.identifier)
	end
end

-- Return EchoFarm module.
return EchoFarm
end)
__bundle_register("Features/Automation/Objects/AutoLootOptions", function(require, _LOADED, __bundle_register, __bundle_modules)
---@class AutoLootOptions
---@field smin number Minimum stars to loot.
---@field smax number Maximum stars to loot.
---@field wanted string[] List of wanted item names.
---@field lall boolean Whether to loot everything.
local AutoLootOptions = {}

---Create new AutoLootOptions object.
---@param smin number Minimum stars to loot.
---@param smax number Maximum stars to loot.
---@param wanted string[] List of wanted item names.
---@param lall boolean Whether to loot everything.
---@return AutoLootOptions
function AutoLootOptions.new(smin, smax, wanted, lall)
	local self = setmetatable({}, AutoLootOptions)
	self.smin = smin
	self.smax = smax
	self.wanted = wanted
	self.lall = lall
	return self
end

-- Return AutoLootOptions module.
return AutoLootOptions


end)
__bundle_register("Features/Automation/AutoLoot", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Utility.JSON
local JSON = require("Utility/JSON")

---@module Utility.Table
local Table = require("Utility/Table")

---@module Utility.Signal
local Signal = require("Utility/Signal")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@module Features.Automation.Objects.AutoLootOptions
local AutoLootOptions = require("Features/Automation/Objects/AutoLootOptions")

-- AutoLoot module.
local AutoLoot = { ignore = false }

-- Timestamp.
local lastTimestamp = os.clock()

-- Maid.
local autoLootMaid = Maid.new()

-- The choice remote that will be used.
local choiceRemote = nil

-- The current prompt being processed.
local currentPrompt = nil

-- The current choice being looted.
local currentChoice = nil

-- The queue of items to be looted from the remote.
local lootQueue = {}

-- Are we currently in loot all mode?
local lootAll = false

-- Services.
local players = game:GetService("Players")
local runService = game:GetService("RunService")

--- Wait for the current choice to be deleted.
---@param options ScrollingFrame
---@param remote RemoteEvent
local function waitForChoiceDeletion(options, remote)
	local choiceObject = options:FindFirstChild(currentChoice)

	remote:FireServer(currentChoice)

	if choiceObject and choiceObject.Parent then
		return
	end

	if lootQueue[1] ~= currentChoice then
		error("We assumed that the current choice was the first in the queue, was the queue modified?")
	end

	table.remove(lootQueue, 1)

	currentChoice = nil
end

---Reset the AutoLoot module.
local function resetAutoLoot()
	choiceRemote = nil
	lootQueue = {}
	currentChoice = nil
	currentPrompt = nil
	lootAll = false
end

---On player GUI descendant added.
---@param descendant Instance
local function onPlayerGuiDescendantAdded(descendant)
	if descendant.Name ~= "ChoicePrompt" then
		return
	end

	if AutoLoot.ignore then
		return
	end

	if not Configuration.expectToggleValue("AutoLoot") then
		return
	end

	-- Wait for all the instances to replicate.
	descendant:WaitForChild("ChoiceFrame"):WaitForChild("Options")

	-- Start processing the prompt.
	AutoLoot.process(
		descendant,
		AutoLootOptions.new(
			Configuration.expectOptionValue("AutoLootStarsMin") or 0,
			Configuration.expectOptionValue("AutoLootStarsMax") or 0,
			Configuration.expectOptionValues("ItemNameList") or {},
			Configuration.expectToggleValue("AutoLootAll") or false
		)
	)
end

---Wait for the current prompt to be deleted.
---@param prompt ScreenGui
---@param remote RemoteEvent
---@param param string
local function waitForPromptDeletion(prompt, remote, param)
	repeat
		-- Close prompt.
		remote:FireServer(param)

		-- Wait.
		task.wait()
	until not prompt.Parent

	resetAutoLoot()
end

---Is the auto loot active?
---@return boolean
function AutoLoot.active()
	return choiceRemote ~= nil and currentPrompt ~= nil and #lootQueue > 0
end

---Update the AutoLoot module.
function AutoLoot.update()
	if os.clock() - lastTimestamp <= 0.15 then
		return
	end

	lastTimestamp = os.clock()

	if not AutoLoot.ignore and not Configuration.expectToggleValue("AutoLoot") then
		return resetAutoLoot()
	end

	if not choiceRemote or not choiceRemote.Parent then
		return resetAutoLoot()
	end

	if not currentPrompt or not currentPrompt.Parent then
		return resetAutoLoot()
	end

	local choiceFrame = currentPrompt:FindFirstChild("ChoiceFrame")
	local options = choiceFrame and choiceFrame:FindFirstChild("Options")
	if not options then
		return resetAutoLoot()
	end

	if lootAll then
		return waitForPromptDeletion(currentPrompt, choiceRemote, "LOOT_ALL")
	end

	if currentChoice then
		return waitForChoiceDeletion(options, choiceRemote)
	end

	local itemToLoot = lootQueue[1]
	if not itemToLoot then
		return waitForPromptDeletion(currentPrompt, choiceRemote, "EXIT")
	end

	currentChoice = itemToLoot

	choiceRemote:FireServer(itemToLoot)
end

--- Process a choice prompt and add the items with filtering to the loot queue.
---@param prompt ScreenGui The choice prompt to process.
---@param options AutoLootOptions The options to use.
function AutoLoot.process(prompt, options)
	local remote = prompt:FindFirstChild("Choice")
	if not remote or not remote:IsA("RemoteEvent") then
		return
	end

	local jsonLootData = prompt:GetAttribute("LootData")
	if typeof(jsonLootData) ~= "string" then
		return
	end

	local lootData = JSON.decode(jsonLootData)
	if typeof(lootData) ~= "table" then
		return
	end

	-- Reset the AutoLoot module.
	resetAutoLoot()

	-- Set the new data for processing.
	currentPrompt = prompt
	choiceRemote = remote
	lootAll = options.lall

	-- Process the loot data.
	for _, item in next, lootData do
		local rich = item.rich:gsub("%$%S*", "")
		local text = item.text

		if not text then
			continue
		end

		local matched = text:match("[*]")
		local stars = matched and #matched or 0

		if stars < options.smin or stars > options.smax then
			continue
		end

		local wanted, _ = Table.find(options.wanted, function(value, _)
			return rich:match(value)
		end)

		if not wanted then
			continue
		end

		lootQueue[#lootQueue + 1] = text
	end
end

---Initialize the AutoLoot module.
function AutoLoot.init()
	local localPlayer = players.LocalPlayer
	local playerGui = localPlayer:WaitForChild("PlayerGui")

	local preRender = Signal.new(runService.PreRender)
	local playerGuiDescendantAdded = Signal.new(playerGui.DescendantAdded)

	autoLootMaid:mark(playerGuiDescendantAdded:connect("AutoLoot_PlayerGuiDescendantAdded", onPlayerGuiDescendantAdded))
	autoLootMaid:mark(preRender:connect("AutoLoot_PreRender", AutoLoot.update))
end

---Detach the AutoLoot module.
function AutoLoot.detach()
	autoLootMaid:clean()
end

-- Return the AutoLoot module.
return AutoLoot

end)()
end)
