-- Serializer module.
local Serializer = {}

---Does a specified table match the layout of an array.
---@param tbl table
---@return boolean
local function isAnArray(tbl)
	local expected = 1

	for k in next, tbl do
		if k ~= expected then
			return false
		end

		expected = expected + 1
	end

	return true
end

---Serialize number to a float.
---@param value number
---@return string
local function serializeFloat(value)
	local serializedFloat = string.unpack("f", string.pack("f", value))
	if serializedFloat == value then
		return string.pack(">Bf", 0xca, value)
	end

	return string.pack(">Bd", 0xcb, value)
end

---Serialize number to a signed int.
---@param value number
---@return string
local function serializeSignedInt(value)
	if value < 128 then
		return string.pack("B", value)
	elseif value <= 0xff then
		return string.pack("BB", 0xcc, value)
	elseif value <= 0xffff then
		return string.pack(">BI2", 0xcd, value)
	elseif value <= 0xffffffff then
		return string.pack(">BI4", 0xce, value)
	end

	return string.pack(">BI8", 0xcf, value)
end

---Serialize number to a unsigned int.
---@param value number
---@return string
local function serializeUnsignedInt(value)
	if value >= -32 then
		return string.pack("B", 0xe0 + (value + 32))
	elseif value >= -128 then
		return string.pack("Bb", 0xd0, value)
	elseif value >= -32768 then
		return string.pack(">Bi2", 0xd1, value)
	elseif value >= -2147483648 then
		return string.pack(">Bi4", 0xd2, value)
	end

	return string.pack(">Bi8", 0xd3, value)
end

---Serialize string to a UTF8 string.
---@param value string
---@return string
local function serializeUtf8(value)
	local len = #value

	if len < 32 then
		return string.pack("B", 0xa0 + len) .. value
	elseif len < 256 then
		return string.pack(">Bs1", 0xd9, value)
	elseif len < 65536 then
		return string.pack(">Bs2", 0xda, value)
	end

	return string.pack(">Bs4", 0xdb, value)
end

---Serialize string to a string of bytes.
---@param value string
---@return string
local function serializeStringBytes(value)
	local len = #value

	if len < 256 then
		return string.pack(">Bs1", 0xc4, value)
	elseif len < 65536 then
		return string.pack(">Bs2", 0xc5, value)
	end

	return string.pack(">Bs4", 0xc6, value)
end

---Serialize table to a array.
---@param value table
---@return string
local function serializeArray(value)
	local elements = {}

	for i, v in pairs(value) do
		if type(v) ~= "function" and type(v) ~= "thread" and type(v) ~= "userdata" then
			elements[i] = Serializer.marshal(v)
		end
	end

	local result = table.concat(elements)
	local length = #elements

	if length < 16 then
		return string.pack(">B", 0x90 + length) .. result
	elseif length < 65536 then
		return string.pack(">BI2", 0xdc, length) .. result
	end

	return string.pack(">BI4", 0xdd, length) .. result
end

---Serialize table to a map.
---@param value table
---@return string
local function serializeMap(value)
	local elements = {}

	for k, v in pairs(value) do
		if type(v) ~= "function" and type(v) ~= "thread" and type(v) ~= "userdata" then
			elements[#elements + 1] = Serializer.marshal(k)
			elements[#elements + 1] = Serializer.marshal(v)
		end
	end

	local length = math.floor(#elements / 2)
	if length < 16 then
		return string.pack(">B", 0x80 + length) .. table.concat(elements)
	elseif length < 65536 then
		return string.pack(">BI2", 0xde, length) .. table.concat(elements)
	end

	return string.pack(">BI4", 0xdf, length) .. table.concat(elements)
end

---Serialize nil to a binary string.
---@return string
local function serializeNil()
	return string.pack("B", 0xc0)
end

---serialize table to a binary string
---@param value table
---@return string
local function serializeTable(value)
	return isAnArray(value) and serializeArray(value) or serializeMap(value)
end

---serialize boolean to a binary string
---@param value boolean
---@return string
local function serializeBoolean(value)
	return string.pack("B", value and 0xc3 or 0xc2)
end

---serialize int to a binary string
---@param value number
---@return string
local function serializeInt(value)
	return value >= 0 and serializeSignedInt(value) or serializeUnsignedInt(value)
end

---serialize number to a binary string
---@param value number
---@return string
local function serializeNumber(value)
	return value % 1 == 0 and serializeInt(value) or serializeFloat(value)
end

---serialize string to a binary string
---@param value number
---@return string
local function serializeString(value)
	return utf8.len(value) and serializeUtf8(value) or serializeStringBytes(value)
end

-- Types mapping to functions that serialize it.
local typeToSerializeMap = {
	["nil"] = serializeNil,
	["boolean"] = serializeBoolean,
	["number"] = serializeNumber,
	["string"] = serializeString,
	["table"] = serializeTable,
}

---Marshal a value into a binary string.
---@param value any
---@return string
function Serializer.marshal(value)
	return typeToSerializeMap[type(value)](value)
end

-- Return Serializer module.
return Serializer


end)
__bundle_register("Game/Wipe", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Wipe module.
local Wipe = {}

-- Constants.
local LOBBY_PLACE_ID = 4111023553
local FRAGMENTS_OF_SELF_POS = Vector3.new(2910.00, 1133.03, 1474.00)

---@module Features.Game.Interactions
local Interactions = require("Features/Game/Interactions")

---@module Utility.PersistentData
local PersistentData = require("Utility/PersistentData")

---@module Utility.Finder
local Finder = require("Utility/Finder")

---@module Game.ServerHop
local ServerHop = require("Game/ServerHop")

---@module Utility.Logger
local Logger = require("Utility/Logger")

-- Debugging mode.
local DEBUGGING_MODE = true

-- Services.
local players = game:GetService("Players")
local replicatedStorage = game:GetService("ReplicatedStorage")

---Telemetry log.
local function telemetryLog(...)
	if not DEBUGGING_MODE then
		return
	end

	Logger.warn(...)
end

---Wait until we're in the fragments of self area.
function Wipe.pwait()
	local wdata = PersistentData.get("wdata")
	if not wdata then
		return error("No wipe data set in PersistentData.")
	end

	local startTimestamp = os.clock()

	while task.wait() do
		if os.clock() - startTimestamp >= 30 then
			return ServerHop.hop(wdata.slot, true)
		end

		if Finder.near(FRAGMENTS_OF_SELF_POS, 200) then
			break
		end
	end
end

---Process all items we need to pass down.
function Wipe.pitems()
	local wdata = PersistentData.get("wdata")
	if not wdata then
		return error("No wipe data set in PersistentData.")
	end

	local npcs = workspace:WaitForChild("NPCs")
	local hippocampusPool = npcs:WaitForChild("Hippocampal Pool")

	for _, name in next, wdata.weapons do
		local weapon = Finder.weweapon(name)
		if not weapon then
			continue
		end

		Interactions.etool(weapon)

		Interactions.interact(hippocampusPool, {
			{ choice = "[Inspect]" },
			{ choice = "[Pass down item]" },
			{ exit = true },
		}, true)
	end
end

---Start the process for wiping a slot in the depths.
function Wipe.depths()
	-- Request start.
	local requests = replicatedStorage:WaitForChild("Requests")
	local startMenu = requests:WaitForChild("StartMenu")
	local start = startMenu:WaitForChild("Start")

	telemetryLog("(Depths) Requesting start.")

	start:FireServer()

	-- Wait until our character is in the fragments of self area.
	Wipe.pwait()

	-- Look for people in the Fragments of Self area.
	telemetryLog("(Depths) Looking for anyone in the Fragments of Self area.")

	local wdata = PersistentData.get("wdata")
	if not wdata then
		return error("No wipe data set in PersistentData.")
	end

	if Finder.pnear(FRAGMENTS_OF_SELF_POS, 500) then
		return ServerHop.hop(wdata.slot, true)
	end

	-- Process items.
	Wipe.pitems()

	-- Interact with Self NPC.
	local npcs = workspace:WaitForChild("NPCs")
	local selfNpc = npcs:WaitForChild("Self")

	telemetryLog("(Depths) Teleporting and interacting with Self NPC.")

	repeat
		-- Interact.
		Interactions.interact(selfNpc, {
			{ choice = "[The End]" },
		}, true)

		-- Wait.
		task.wait()
	until not players.LocalPlayer.Character

	telemetryLog("(Depths) Wiped slot. Removing marker.")

	-- Add or remove markers.
	PersistentData.set("wdata", nil)

	if PersistentData.get("efdata") then
		PersistentData.stf("efdata", "wiped", true)
	end
end

---Start the process for wiping a slot in the lobby.
function Wipe.lobby()
	telemetryLog("(Lobby) (Step 1) Wiping slot in lobby.")

	-- Keep attempting to wipe the slot until successful.
	local requests = replicatedStorage:WaitForChild("Requests")
	local wipeSlot = requests:WaitForChild("WipeSlot")

	local wdata = PersistentData.get("wdata")
	if not wdata then
		return error("No wipe data set in PersistentData.")
	end

	repeat
		task.wait()
	until wipeSlot:InvokeServer(wdata.slot)

	telemetryLog("(Lobby) (Step 2) Wiped slot. Server hopping.")

	-- Server hop.
	ServerHop.hop(wdata.slot, false)
end

---Invoke a wipe for a specific slot.
---@param slot string The data slot to wipe.
---@param weapons string[]? Optional items to keep. Does not handle any validation.
function Wipe.invoke(slot, weapons)
	-- Mark slot.
	PersistentData.set("wdata", {
		slot = slot,
		weapons = weapons or {},
	})

	telemetryLog("(Invoke) (Step 1) Marked slot %s in data.", slot)

	-- If we're in the lobby, continue there.
	if game.PlaceId == LOBBY_PLACE_ID then
		return Wipe.lobby()
	end

	-- Otherwise, return to the lobby first.
	return ServerHop.rlobby()
end

-- Return Wipe module.
return Wipe


end)
__bundle_register("Features/Exploits/Exploits", function(require, _LOADED, __bundle_register, __bundle_modules)
---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Utility.InstanceWrapper
local InstanceWrapper = require("Utility/InstanceWrapper")

-- Void maid.
local voidMaid = Maid.new()

-- How fast (studs/sec) a voided part is driven straight DOWN.
local VOID_FALL_SPEED = 10000

-- Depth (negative Y) we keep the part phasing straight through EVERYTHING before we let it collide again.
local VOID_KILL_Y_THRESHOLD = -10000

--- Strip everything that could pull a part back toward the arena: unanchor it and destroy every position/orientation holder, while keeping our own downward BodyVelocity and the structural welds intact.
---@param part BasePart
local function stripArenaHolders(part)
	part.Anchored = false
	for _, child in ipairs(part:GetChildren()) do
		-- Every force mover (BodyVelocity / BodyPosition / BodyGyro / ...) plus the align constraints.
		if child:IsA("BodyMover")
			or child:IsA("AlignPosition")
			or child:IsA("AlignOrientation")
		then
			child:Destroy()
		end
	end
end

---Void part.
---@param model Model
---@param part Part
local function voidPart(model, part)
	-- No BodyVelocity / force mover anymore.

	---@note: Remove part controllers.
	local velocityController = part:FindFirstChild("ControlVel")
		or part:FindFirstChild("SafetyBV")
		or part:FindFirstChild("SwimBV")
		or part:FindFirstChild("Holder")

	if velocityController and velocityController:IsA("BodyMover") then
		velocityController:Destroy()
	end

	-- Free the root part of any arena tether (the full model gets the same treatment in updateVoidMobs; this covers the root explicitly).
	stripArenaHolders(part)

	-- Drive it down with velocity and let real physics carry it through the intervening space, instead of hard-snapping part.Position to directly every frame like this used to.
	part.AssemblyLinearVelocity = Vector3.new(0, -VOID_FALL_SPEED, 0)
	part.AssemblyAngularVelocity = Vector3.new(0, 0, 0)

	-- CanCollide off is needed to phase through solid terrain on the way down, but left off forever it also means the part can never physically touch anything below either -- including a touch-based kill volume, if that's what's actually down there.
	if part.Position.Y > VOID_KILL_Y_THRESHOLD then
		part.CanCollide = false
	else
		part.CanCollide = true
	end

	-- Stop part from sleeping.
	sethiddenproperty(part, "NetworkIsSleeping", false)
end

return (function()
	-- Exploits related stuff is handled here.
	local Exploits = {
		forceVoid = false,
		ownershipTimestamp = 0,
		ownershipItem = nil,
		currentRootPart = nil,

		-- Set by TitusFarm (or anything else doing precise positioning on a target) while it's actively executing.
		suppressPathfindBreaker = false,

		-- Set by TitusFarm while flying directly into a target it wants to void.
		forcePathfindBreaker = false,
	}

	---@module Utility.Signal
	local Signal = require("Utility/Signal")

	---@module Utility.Configuration
	local Configuration = require("Utility/Configuration")

	---@module Utility.OriginalStore
	local OriginalStore = require("Utility/OriginalStore")

	---@module Features.Game.OwnershipWatcher
	local OwnershipWatcher = require("Features/Game/OwnershipWatcher")

	---@module Utility.Logger
	local Logger = require("Utility/Logger")

	---@module Features.Automation.EchoFarm
	local EchoFarm = require("Features/Automation/EchoFarm")

	-- Services.
	local runService = game:GetService("RunService")
	local players = game:GetService("Players")
	local physicsService = game:GetService("PhysicsService")
	local replicatedStorage = game:GetService("ReplicatedStorage")

	-- Collision group name using our unique table.
	local collisionGroupName = tostring(Exploits)

	-- Maids.
	local exploitsMaid = Maid.new()
	local pathfindBreakerMaid = Maid.new()

	-- Original stores.
	local allowSleep = voidMaid:mark(OriginalStore.new())

	-- Signals.
	local heartbeat = Signal.new(runService.Heartbeat)
	local preRender = Signal.new(runService.PreRender)

	-- Last velocity before breaker modification.
	local lastVelocity = nil

	-- Last Vector
	local lastVector = 1

	-- Parts we've committed to voiding.
	local voidingParts = {}

	---Clean up void mobs.
	local function cleanVoidMobs()
		voidMaid:clean()
		allowSleep:restore()
		table.clear(voidingParts)
	end

	---Update void mobs.
	local function updateVoidMobs()
		local localPlayer = players.LocalPlayer
		local peerId = OwnershipWatcher.clientPeerId

		-- Set simulation radius.
		if setsimulationradius then
			setsimulationradius(math.huge, math.huge)
		else
			sethiddenproperty(localPlayer, "MaxSimulationRadius", 9e9)
			sethiddenproperty(localPlayer, "SimulationRadius", 9e9)
		end

		-- Set allow sleep.
		allowSleep:set(settings().Physics, "AllowSleep", false)

		---@type BasePart
		for part, data in next, OwnershipWatcher.parts do
			local model = data.model
			if not model then
				continue
			end

			-- Commit any mob we currently own to being voided, then keep voiding it from then on - even if ownership reads false on a later frame - so a distance-based ownership reassign can't make us stop pushing partway down.
			if data.owned then
				voidingParts[part] = true
			end

			if not voidingParts[part] then
				continue
			end

			---@todo: Filtering out parts (CheckPartConnections, missing checks, etc)
			local localCharacter = localPlayer and localPlayer.Character
			if not localCharacter then
				continue
			end

			if model == localCharacter then
				continue
			end

			if model.Parent ~= workspace.Live then
				continue
			end

			-- Force network ownership to STICK.
			if peerId ~= nil and sethiddenproperty then
				pcall(sethiddenproperty, part, "NetworkOwnerV3", peerId)
			end

			-- Bosses fight the fall with their Humanoid: the state machine keeps re-grounding/standing the character back up, which is the "up" half of the up-down-up-down bounce.
			local humanoid = model:FindFirstChildOfClass("Humanoid")
			if humanoid then
				pcall(function()
					humanoid.PlatformStand = true
					humanoid.AutoRotate = false
					humanoid.WalkSpeed = 0
					humanoid:ChangeState(Enum.HumanoidStateType.Physics)
				end)
			end

			-- Same reasoning as voidPart's own CanCollide handling: only phase the rest of the model through terrain while it's still above real terrain depth, not forever, so it can still physically register against whatever's actually below once it's deep enough.
			local stillNearTerrain = part.Position.Y > VOID_KILL_Y_THRESHOLD

			for _, instance in pairs(model:GetChildren()) do
				if instance:IsA("BasePart") then
					instance.CanCollide = not stillNearTerrain
					-- The arena tether can live on ANY welded part, not just the HumanoidRootPart.
					stripArenaHolders(instance)
				end

				local bone = instance:FindFirstChild("Bone")
				if not bone or not bone:IsA("BasePart") then
					continue
				end

				bone.CanCollide = not stillNearTerrain
				stripArenaHolders(bone)
			end

			voidPart(model, part)
		end
	end

	---Get knocked ownership item.
	local function getKnockedOwnershipItem()
		local localPlayer = players.LocalPlayer
		if not localPlayer then
			return
		end

		local backpack = localPlayer:FindFirstChild("Backpack")
		if not backpack then
			return
		end

		local selected = nil

		for _, item in pairs(backpack:GetChildren()) do
			if item.Name:match("Talent") then
				continue
			end

			if not item:IsA("Tool") then
				continue
			end

			if not item:FindFirstChildOfClass("BasePart") then
				continue
			end

			selected = item
		end

		if not selected then
			selected = localPlayer.Character and localPlayer.Character:FindFirstChild("Weapon")
			selected = selected or backpack:FindFirstChild("Weapon")
		end

		return selected
	end

	---Update move while knocked.
	local function updateMoveWhileKnocked()
		local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
		local effectReplicatorModule = require(effectReplicator)

		if not effectReplicatorModule:FindEffect("Knocked") then
			return
		end

		local localPlayer = players.LocalPlayer
		if not localPlayer then
			return
		end

		local character = localPlayer.Character
		if not character then
			return
		end

		local rootPart = character:FindFirstChild("HumanoidRootPart")
		if not rootPart then
			return
		end

		local humanoid = character:FindFirstChild("Humanoid")
		if not humanoid then
			return
		end

		local backpack = localPlayer:FindFirstChild("Backpack")
		if not backpack then
			return
		end

		local ownershipItem = Exploits.ownershipItem or getKnockedOwnershipItem()
		if not ownershipItem then
			return
		end

		if not Exploits.ownershipItem or not Exploits.ownershipItem:IsDescendantOf(game) then
			Exploits.ownershipItem = ownershipItem
		end

		if tick() - Exploits.ownershipTimestamp <= 0.15 then
			return
		end

		local leftHand = character:FindFirstChild("LeftHand")
		local rightHand = character:FindFirstChild("RightHand")
		local hasHandWeapon = false

		if leftHand and leftHand:FindFirstChild("HandWeapon") then
			hasHandWeapon = true
		end

		if rightHand and rightHand:FindFirstChild("HandWeapon") then
			hasHandWeapon = true
		end

		local characterHandler = character:FindFirstChild("CharacterHandler")
		local requests = characterHandler and characterHandler:FindFirstChild("Requests")
		local equipWeapon = requests and requests:FindFirstChild("EquipWeapon")

		if ownershipItem.Name == "Weapon" and hasHandWeapon then
			return equipWeapon and equipWeapon:FireServer(false)
		end

		if ownershipItem.Name == "Weapon" and not hasHandWeapon then
			return equipWeapon and equipWeapon:FireServer(true)
		end

		if ownershipItem.Parent == character then
			return humanoid:UnequipTools()
		end

		if ownershipItem.Parent == backpack then
			humanoid:EquipTool(ownershipItem)
		end

		Exploits.ownershipTimestamp = tick()
	end

	---Update pathfind breaker heartbeat.
	local function updatePathfindBreakerHeartbeat()
		local character = players.LocalPlayer.Character
		if not character then
			return
		end

		local humanoidRootPart = character:FindFirstChild("HumanoidRootPart")
		if not humanoidRootPart then
			return
		end

		lastVelocity = humanoidRootPart.AssemblyLinearVelocity

		if Configuration.expectToggleValue("AggressiveMode") then
			humanoidRootPart.AssemblyLinearVelocity = Vector3.new(0, -1e5, 0)
		else
			humanoidRootPart.AssemblyLinearVelocity = Vector3.new(0, -9e9, 0)
		end

		if not Configuration.expectToggleValue("PathfindBreakerHighlight") then
			return pathfindBreakerMaid:clean()
		end

		local highlight = InstanceWrapper.create(pathfindBreakerMaid, "PathfindBreakerHighlight", "Highlight")
		highlight.FillColor = Configuration.expectOptionValue("PathfindBreakerHighlightColor")
		highlight.OutlineColor = Configuration.expectOptionValue("PathfindBreakerHighlightOutlineColor")

		if humanoidRootPart.Parent then
			highlight.Parent = humanoidRootPart.Parent
		end
	end

	---Update exploits.
	local function updateExploits()
		local localPlayer = players.LocalPlayer
		if not localPlayer then
			return
		end

		if EchoFarm.voiding or Configuration.expectToggleValue("VoidMobs") then
			updateVoidMobs()
		else
			cleanVoidMobs()
		end

		if Configuration.expectToggleValue("MoveWhileKnocked") then
			updateMoveWhileKnocked()
		end

		if
			(Configuration.expectToggleValue("PathfindBreaker") or Exploits.forcePathfindBreaker)
			and not Exploits.suppressPathfindBreaker
		then
			updatePathfindBreakerHeartbeat()
		else
			lastVelocity = nil
			pathfindBreakerMaid:clean()
		end
	end

	---Update pathfind breaker.
	local function updatePathfindBreakerRender()
		if not lastVelocity then
			return
		end

		local character = players.LocalPlayer and players.LocalPlayer.Character
		if not character then
			return
		end

		local humanoidRootPart = character:FindFirstChild("HumanoidRootPart")
		if not humanoidRootPart then
			return
		end

		humanoidRootPart.AssemblyLinearVelocity = lastVelocity
	end

	---Initalize exploits.
	function Exploits.init()
		exploitsMaid:add(heartbeat:connect("Exploits_Heartbeat", updateExploits))
		exploitsMaid:add(preRender:connect("Exploits_PreRender", updatePathfindBreakerRender))

		---@note: Wrapped in a PCall to prevent errors.
		pcall(function()
			physicsService:RegisterCollisionGroup(collisionGroupName)
			physicsService:CollisionGroupSetCollidable(collisionGroupName, collisionGroupName, false)
			physicsService:CollisionGroupSetCollidable(collisionGroupName, "Default", false)
			physicsService:CollisionGroupSetCollidable(collisionGroupName, "Player", false)
			physicsService:CollisionGroupSetCollidable(collisionGroupName, "WalkThrough", false)
		end)

		-- Log.
		Logger.warn("Exploits initialized.")
	end

	---Detach voidMobs.
	function Exploits.detach()
		-- Clean.
		exploitsMaid:clean()
		voidMaid:clean()
		pathfindBreakerMaid:clean()

		-- Log.
		Logger.warn("Exploits detached.")
	end

	-- Return Exploits module.
	return Exploits
end)()
end)
__bundle_register("Features/Game/OwnershipWatcher", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Ownership data.
local clientPart = Instance.new("Part", workspace)
local clientSuccess, clientPeerId = pcall(function()
	return gethiddenproperty(clientPart, "NetworkOwnerV3")
end)

clientPart:Destroy()

---Check for network ownership.
---@param part BasePart
---@return boolean
local function hasNetworkOwnership(part)
	local exploitFallback = isnetworkowner or function(...)
		return false
	end

	return exploitFallback(part)
end

return LPH_NO_VIRTUALIZE(function()
	-- Ownership watcher module.
	local OwnershipWatcher = { modelsToScan = {}, parts = {} }

	-- Our own network-owner peer id, read from a part we parented ourselves (so it is owned by us).
	OwnershipWatcher.clientPeerId = clientSuccess and clientPeerId or nil

	-- Services
	local runService = game:GetService("RunService")

	---@module Utility.Maid
	local Maid = require("Utility/Maid")

	---@module Utility.Configuration
	local Configuration = require("Utility/Configuration")

	---@module Utility.Signal
	local Signal = require("Utility/Signal")

	---@module Utility.InstanceWrapper
	local InstanceWrapper = require("Utility/InstanceWrapper")

	---@module Utility.Logger
	local Logger = require("Utility/Logger")

	---@module Features.Automation.EchoFarm
	local EchoFarm = require("Features/Automation/EchoFarm")

	-- Signals.
	local renderStepped = Signal.new(runService.RenderStepped)

	-- Maids.
	local ownershipMaid = Maid.new()

	--- Clean up parts.
	local function cleanParts()
		for _, maid in next, OwnershipWatcher.modelsToScan do
			maid:clean()
		end
	end

	---Add live characters to ownership watcher.
	---@param character Model
	local function onLiveAdded(character)
		if not character:IsA("Model") then
			return
		end

		if OwnershipWatcher.modelsToScan[character] then
			return
		end

		OwnershipWatcher.modelsToScan[character] = Maid.new()
	end

	---Remove live characters from ownership watcher.
	---@param character Model
	local function onLiveRemoved(character)
		if not OwnershipWatcher.modelsToScan[character] then
			return
		end

		OwnershipWatcher.modelsToScan[character]:clean()
		OwnershipWatcher.modelsToScan[character] = nil
	end

	---Update ownership.
	local function updateOwnership()
		---@optimization: Stop updating when we don't need it.
		if
			not Configuration.expectToggleValue("ShowOwnership")
			and not Configuration.expectToggleValue("VoidMobs")
			and not EchoFarm.voiding
		then
			return cleanParts()
		end

		-- Create an update table.
		local updateTable = {}

		-- Add models.
		for model, maid in next, OwnershipWatcher.modelsToScan do
			local humanoidRootPart = model:FindFirstChild("HumanoidRootPart")
			if not humanoidRootPart then
				continue
			end

			-- Check if owner.
			local isNetworkOwner = hasNetworkOwnership(humanoidRootPart)

			-- Visualization.
			local netVisual = InstanceWrapper.create(maid, "NetworkVisual", "Part", model)
			netVisual.Size = Vector3.new(10, 10, 10)
			netVisual.Transparency = Configuration.expectToggleValue("ShowOwnership") and 0.8 or 1.0
			netVisual.Color = isNetworkOwner and Color3.fromRGB(0, 255, 0) or Color3.fromRGB(255, 0, 0)
			netVisual.CFrame = humanoidRootPart.CFrame
			netVisual.Anchored = true
			netVisual.CanCollide = false

			-- Part data.
			local data = OwnershipWatcher.parts[humanoidRootPart]
				or {
					owned = isNetworkOwner,
					model = model,
				}

			-- Update part data.
			data.owned = isNetworkOwner
			data.model = model

			-- Set in global part list.
			OwnershipWatcher.parts[humanoidRootPart] = data

			-- Set in map.
			updateTable[humanoidRootPart] = data
		end

		-- Override global part list with the new update table.
		---@note: This will get rid of any parts that were not updated (e.g no longer existing root part or not in model list) upon cycle.
		---@todo: Fix me - this is a bit of a hack.
		OwnershipWatcher.parts = updateTable
	end

	---Get table of watched parts along with a mapping to extra data.
	---@return table<BasePart, table>
	function OwnershipWatcher.get()
		return OwnershipWatcher.parts
	end

	---Iniitalize OwnershipWatcher module.
	function OwnershipWatcher.init()
		local live = workspace:WaitForChild("Live")
		local liveChildAdded = Signal.new(live.ChildAdded)
		local liveChildRemoved = Signal.new(live.ChildRemoved)

		ownershipMaid:add(liveChildAdded:connect("OwnershipWatcher_OnLiveChildAdded", onLiveAdded))
		ownershipMaid:add(liveChildRemoved:connect("OwnershipWatcher_OnLiveChildRemoved", onLiveRemoved))
		ownershipMaid:add(renderStepped:connect("OwnershipWatcher_RenderStepped", updateOwnership))

		for _, entity in next, live:GetChildren() do
			onLiveAdded(entity)
		end

		Logger.warn("OwnershipWatcher initialized.")
	end

	---Detach OwnershipWatcher module.
	function OwnershipWatcher.detach()
		-- Clean up ownership maids.
		ownershipMaid:clean()

		-- Clean up parts.
		cleanParts()

		-- Log.
		Logger.warn("OwnershipWatcher detached.")
	end

	-- Return OwnershipWatcher module.
	return OwnershipWatcher
end)()
end)
__bundle_register("Utility/InstanceWrapper", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Instance wrapper module - used for continously updating functions that require instances.
local InstanceWrapper = {}

-- Services.
local collectionService = game:GetService("CollectionService")

---@module Utility.Signal
local Signal = require("Utility/Signal")

---Cache an instance, clean the instance up through a maid, and automatically uncache on deletion.
---@param instanceMaid Maid
---@param identifier any
---@param inst Instance
---@return Instance
InstanceWrapper.mark = LPH_NO_VIRTUALIZE(function(instanceMaid, identifier, inst)
	local maidInstance = instanceMaid[identifier]
	if maidInstance then
		return maidInstance
	end

	local onAncestorChange = Signal.new(inst.AncestryChanged)

	if inst:IsA("BodyVelocity") then
		collectionService:AddTag(inst, "AllowedBM")
	end

	instanceMaid[identifier] = inst
	instanceMaid:add(onAncestorChange:connect("Instance_OnAncestorChange", function(_)
		if inst:IsDescendantOf(game) then
			return
		end

		instanceMaid:removeTask(identifier)
	end))

	return inst
end)

---Create & cache an instance, clean the instance up through a maid, and automatically uncache on deletion.
---@param instanceMaid Maid
---@param identifier any
---@param type string
---@param parent Instance?
---@return Instance
InstanceWrapper.create = LPH_NO_VIRTUALIZE(function(instanceMaid, identifier, type, parent)
	local maidInstance = instanceMaid[identifier]
	if maidInstance then
		return maidInstance
	end

	local newInstance = Instance.new(type, parent)
	local onAncestorChange = Signal.new(newInstance.AncestryChanged)

	if newInstance:IsA("BodyVelocity") then
		collectionService:AddTag(newInstance, "AllowedBM")
	end

	instanceMaid[identifier] = newInstance
	instanceMaid:add(onAncestorChange:connect("Instance_OnAncestorChange", function(_)
		if newInstance:IsDescendantOf(game) then
			return
		end

		instanceMaid:removeTask(identifier)
	end))

	return newInstance
end)

-- Return InstanceWrapper module
return InstanceWrapper


end)
__bundle_register("Utility/OriginalStore", function(require, _LOADED, __bundle_register, __bundle_modules)
---@class OriginalStore
---@param data any
---@param index any
---@param value any
---@field stored boolean
local OriginalStore = {}
OriginalStore.__index = OriginalStore

---Get stored data value.
---@return any
OriginalStore.get = LPH_NO_VIRTUALIZE(function(self)
	if not self.stored then
		return nil
	end

	return self.value
end)

---Set something, run a callback, and then restore.
---@param data table|Instance
---@param index any
---@param value any
---@param callback fun(): any
OriginalStore.run = LPH_NO_VIRTUALIZE(function(self, data, index, value, callback)
	self:set(data, index, value)

	callback()

	self:restore()
end)

---Mark data value.
---@param data table|Instance
---@param index any
OriginalStore.mark = LPH_NO_VIRTUALIZE(function(self, data, index)
	if self.stored and self.data ~= data then
		self:restore()
	end

	if not self.stored then
		self.data = data
		self.index = index
		self.value = data[index]
		self.stored = true
	end
end)

---Set data value.
---@param data table|Instance
---@param index any
---@param value any
OriginalStore.set = LPH_NO_VIRTUALIZE(function(self, data, index, value)
	self:mark(data, index)

	data[index] = value
end)

---Restore data value.
OriginalStore.restore = LPH_NO_VIRTUALIZE(function(self)
	if not self.stored then
		return
	end

	pcall(function()
		self.data[self.index] = self.value
	end)

	self.stored = false
end)

---Detach OriginalStore object.
OriginalStore.detach = LPH_NO_VIRTUALIZE(function(self)
	self:restore()
	self.data = nil
	self.index = nil
	self.value = nil
	self.stored = false
end)

---Create new OriginalStore object.
---@return OriginalStore
OriginalStore.new = LPH_NO_VIRTUALIZE(function()
	local self = setmetatable({}, OriginalStore)
	self.data = nil
	self.index = nil
	self.value = nil
	self.stored = false
	return self
end)

-- Return OriginalStore module.
return OriginalStore


end)
__bundle_register("Game/UpdateNotifier", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Terms-of-Service gate (was the version-update popup).
local UpdateNotifier = {}

---@module GUI.Library
local Library = require("GUI/Library")

---@module Utility.Logger
local Logger = require("Utility/Logger")

-- Services.
local tweenService = game:GetService("TweenService")
local coreGui = game:GetService("CoreGui")

-- Marker file written to the executor workspace once the user agrees.
local TOS_FILE = "Mira/miraTosAgreed.txt"

-- The agreement body.
local TOS_BODY = table.concat({
	'<b>By clicking "Agree" and using this script, you acknowledge and agree to the following:</b>',
	"",
	"• You understand that sharing, distributing, leaking, or attempting to crack this script is strictly prohibited.",
	"• Attempting to bypass the script's security in any way is strictly prohibited.",
	"• Any attempt to reverse engineer, crack, or gain unauthorized access to the script will result in immediate action being taken.",
	"• Violations of these terms will result in a permanent ban and blacklist from the script.",
	"",
	"<b>Actions we may take include, but are not limited to:</b>",
	"",
	"• Removal and permanent ban from our Discord community.",
	"• Blacklisting of your license/key from future access.",
	"• Blacklisting associated identifiers, including your IP address and Roblox account, where applicable.",
	"• Blocking access associated with accounts or identifiers used to abuse or violate these terms.",
	"",
	"By continuing, you confirm that you have read, understood, and agreed to these terms.",
}, "\n")

---Show the ToS gate if it hasn't been agreed to yet.
---@param version string? Unused; kept for the old call signature.
function UpdateNotifier.check(version)
	-- Already agreed on this executor -> never show again.
	if isfile and isfile(TOS_FILE) then
		return
	end

	-- Silent mode: no popups at all.
	if shared.Mira and shared.Mira.silent then
		return
	end

	UpdateNotifier.show()
end

---Build and show the ToS popup.
function UpdateNotifier.show()
	-- ScreenGui.
	local screenGui = Instance.new("ScreenGui")
	screenGui.Name = "MiraTosPopup"
	screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
	screenGui.DisplayOrder = 999
	screenGui.IgnoreGuiInset = true

	pcall(function()
		screenGui.Parent = coreGui
	end)

	if not screenGui.Parent then
		pcall(function()
			screenGui.Parent = game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui")
		end)
	end

	-- Overlay is a TextButton so it swallows clicks: the menu behind can't be used until the user makes a choice (proper modal gate).
	local overlay = Instance.new("TextButton")
	overlay.Name = "Overlay"
	overlay.Size = UDim2.new(1, 0, 1, 0)
	overlay.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
	overlay.BackgroundTransparency = 1
	overlay.BorderSizePixel = 0
	overlay.AutoButtonColor = false
	overlay.Text = ""
	overlay.Active = true
	overlay.Modal = true
	overlay.ZIndex = 90
	overlay.Parent = screenGui

	-- Outer frame.
	local outer = Instance.new("Frame")
	outer.Name = "Outer"
	outer.AnchorPoint = Vector2.new(0.5, 0.5)
	outer.Position = UDim2.new(0.5, 0, 0.5, 0)
	outer.Size = UDim2.new(0, 440, 0, 420)
	outer.BackgroundTransparency = 1
	outer.BorderSizePixel = 0
	outer.ZIndex = 100
	outer.Parent = screenGui

	-- Inner frame.
	local inner = Instance.new("Frame")
	inner.Name = "Inner"
	inner.Size = UDim2.new(1, 0, 1, 0)
	inner.BackgroundColor3 = Library.MainColor
	inner.BorderMode = Enum.BorderMode.Inset
	inner.BorderColor3 = Library.OutlineColor
	inner.BorderSizePixel = 1
	inner.ZIndex = 101
	inner.BackgroundTransparency = 1
	inner.Parent = outer

	Library:AddToRegistry(inner, {
		BackgroundColor3 = "MainColor",
		BorderColor3 = "OutlineColor",
	})

	-- Accent bar.
	local accentBar = Instance.new("Frame")
	accentBar.Name = "AccentBar"
	accentBar.Size = UDim2.new(1, 0, 0, 2)
	accentBar.Position = UDim2.new(0, 0, 0, 0)
	accentBar.BackgroundColor3 = Library.AccentColor
	accentBar.BorderSizePixel = 0
	accentBar.ZIndex = 102
	accentBar.BackgroundTransparency = 1
	accentBar.Parent = inner

	Library:AddToRegistry(accentBar, {
		BackgroundColor3 = "AccentColor",
	})

	-- Title.
	local title = Instance.new("TextLabel")
	title.Name = "Title"
	title.Text = "Terms of Service"
	title.Position = UDim2.new(0, 0, 0, 8)
	title.Size = UDim2.new(1, 0, 0, 22)
	title.BackgroundTransparency = 1
	title.TextColor3 = Library.AccentColor
	title.FontFace = Library.Font
	title.TextSize = 22
	title.TextXAlignment = Enum.TextXAlignment.Center
	title.ZIndex = 102
	title.TextTransparency = 1
	title.Parent = inner

	Library:AddToRegistry(title, {
		TextColor3 = "AccentColor",
	})

	-- Separator.
	local separator = Instance.new("Frame")
	separator.Name = "Separator"
	separator.Size = UDim2.new(1, -16, 0, 1)
	separator.Position = UDim2.new(0, 8, 0, 34)
	separator.BackgroundColor3 = Library.OutlineColor
	separator.BorderSizePixel = 0
	separator.ZIndex = 102
	separator.BackgroundTransparency = 1
	separator.Parent = inner

	Library:AddToRegistry(separator, {
		BackgroundColor3 = "OutlineColor",
	})

	-- Body scrolling frame.
	local bodyFrame = Instance.new("ScrollingFrame")
	bodyFrame.Name = "Body"
	bodyFrame.Position = UDim2.new(0, 8, 0, 40)
	bodyFrame.Size = UDim2.new(1, -16, 1, -82)
	bodyFrame.BackgroundColor3 = Library.BackgroundColor
	bodyFrame.BorderColor3 = Library.OutlineColor
	bodyFrame.BorderMode = Enum.BorderMode.Inset
	bodyFrame.BorderSizePixel = 1
	bodyFrame.ScrollBarThickness = 4
	bodyFrame.ScrollBarImageColor3 = Library.AccentColor
	bodyFrame.CanvasSize = UDim2.new(0, 0, 0, 0)
	bodyFrame.AutomaticCanvasSize = Enum.AutomaticSize.Y
	bodyFrame.ZIndex = 102
	bodyFrame.ScrollingDirection = Enum.ScrollingDirection.Y
	bodyFrame.BackgroundTransparency = 1
	bodyFrame.Parent = inner

	Library:AddToRegistry(bodyFrame, {
		BackgroundColor3 = "BackgroundColor",
		BorderColor3 = "OutlineColor",
		ScrollBarImageColor3 = "AccentColor",
	})

	-- Body text.
	local bodyText = Instance.new("TextLabel")
	bodyText.Name = "BodyText"
	bodyText.Text = TOS_BODY
	bodyText.Size = UDim2.new(1, -12, 0, 0)
	bodyText.Position = UDim2.new(0, 6, 0, 4)
	bodyText.AutomaticSize = Enum.AutomaticSize.Y
	bodyText.BackgroundTransparency = 1
	bodyText.TextColor3 = Library.FontColor
	bodyText.FontFace = Library.Font
	bodyText.TextSize = 15
	bodyText.TextXAlignment = Enum.TextXAlignment.Left
	bodyText.TextYAlignment = Enum.TextYAlignment.Top
	bodyText.TextWrapped = true
	bodyText.ZIndex = 103
	bodyText.RichText = true
	bodyText.TextTransparency = 1
	bodyText.Parent = bodyFrame

	Library:AddToRegistry(bodyText, {
		TextColor3 = "FontColor",
	})

	-- Shared button factory (Decline / Agree sit side by side).
	local function makeButton(name, text, xPos, textColorKey)
		local btn = Instance.new("TextButton")
		btn.Name = name
		btn.Position = xPos
		btn.Size = UDim2.new(0.5, -12, 0, 30)
		btn.BackgroundColor3 = Library.MainColor
		btn.BorderColor3 = Library.OutlineColor
		btn.BorderMode = Enum.BorderMode.Inset
		btn.BorderSizePixel = 1
		btn.Text = text
		btn.TextColor3 = Library[textColorKey]
		btn.FontFace = Font.new("rbxasset://fonts/families/SourceSansPro.json")
		btn.TextSize = 16
		btn.ZIndex = 102
		btn.AutoButtonColor = false
		btn.BackgroundTransparency = 1
		btn.TextTransparency = 1
		btn.Parent = inner

		Library:AddToRegistry(btn, {
			BackgroundColor3 = "MainColor",
			BorderColor3 = "OutlineColor",
			TextColor3 = textColorKey,
		})

		return btn
	end

	local agreeBtn = makeButton("Agree", "Agree", UDim2.new(0, 8, 1, -38), "FontColor")
	local declineBtn = makeButton("Decline", "Decline", UDim2.new(0.5, 4, 1, -38), "RiskColor")

	-- Hover: Decline warms to risk red, Agree warms to accent.
	declineBtn.MouseEnter:Connect(function()
		declineBtn.BackgroundColor3 = Library.RiskColor
	end)
	declineBtn.MouseLeave:Connect(function()
		declineBtn.BackgroundColor3 = Library.MainColor
	end)
	agreeBtn.MouseEnter:Connect(function()
		agreeBtn.BackgroundColor3 = Library.AccentColor
	end)
	agreeBtn.MouseLeave:Connect(function()
		agreeBtn.BackgroundColor3 = Library.MainColor
	end)

	---Fade in.
	local function fadeIn()
		tweenService:Create(overlay, TweenInfo.new(0.3, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
			BackgroundTransparency = 0.4,
		}):Play()

		outer.Size = UDim2.new(0, 420, 0, 400)
		tweenService:Create(outer, TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
			Size = UDim2.new(0, 440, 0, 420),
		}):Play()

		tweenService:Create(inner, TweenInfo.new(0.3), { BackgroundTransparency = 0.02 }):Play()
		tweenService:Create(accentBar, TweenInfo.new(0.3), { BackgroundTransparency = 0.02 }):Play()
		tweenService:Create(separator, TweenInfo.new(0.3), { BackgroundTransparency = 0.02 }):Play()
		tweenService:Create(bodyFrame, TweenInfo.new(0.3), { BackgroundTransparency = 0.02 }):Play()
		tweenService:Create(title, TweenInfo.new(0.3), { TextTransparency = 0.02 }):Play()
		tweenService:Create(bodyText, TweenInfo.new(0.3), { TextTransparency = 0.02 }):Play()
		tweenService:Create(declineBtn, TweenInfo.new(0.3), { BackgroundTransparency = 0.02, TextTransparency = 0.02 }):Play()
		tweenService:Create(agreeBtn, TweenInfo.new(0.3), { BackgroundTransparency = 0.02, TextTransparency = 0.02 }):Play()
	end

	---Fade out then destroy. `after` runs once the fade completes.
	local function fadeOut(after)
		tweenService:Create(overlay, TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {
			BackgroundTransparency = 1,
		}):Play()

		tweenService:Create(inner, TweenInfo.new(0.2), { BackgroundTransparency = 1 }):Play()
		tweenService:Create(accentBar, TweenInfo.new(0.2), { BackgroundTransparency = 1 }):Play()
		tweenService:Create(separator, TweenInfo.new(0.2), { BackgroundTransparency = 1 }):Play()
		tweenService:Create(bodyFrame, TweenInfo.new(0.2), { BackgroundTransparency = 1, ScrollBarImageTransparency = 1 }):Play()
		tweenService:Create(title, TweenInfo.new(0.2), { TextTransparency = 1 }):Play()
		tweenService:Create(bodyText, TweenInfo.new(0.2), { TextTransparency = 1 }):Play()
		tweenService:Create(declineBtn, TweenInfo.new(0.2), { BackgroundTransparency = 1, TextTransparency = 1 }):Play()
		tweenService:Create(agreeBtn, TweenInfo.new(0.2), { BackgroundTransparency = 1, TextTransparency = 1 }):Play()

		task.wait(0.25)
		screenGui:Destroy()
		if after then
			after()
		end
	end

	-- Guard so a double-click can't fire both handlers.
	local decided = false

	-- Agree: write the marker file so the gate never shows again, then continue.
	agreeBtn.MouseButton1Click:Connect(function()
		if decided then
			return
		end
		decided = true
		if writefile then
			-- Make sure the "Mira" folder exists before writing into it.
			if type(makefolder) == "function" and not (type(isfolder) == "function" and isfolder("Mira")) then
				pcall(makefolder, "Mira")
			end
			pcall(writefile, TOS_FILE, "agreed")
		end
		fadeOut()
	end)

	-- Decline: tear the whole script down.
	declineBtn.MouseButton1Click:Connect(function()
		if decided then
			return
		end
		decided = true
		fadeOut(function()
			pcall(function()
				Library:Unload()
			end)
		end)
	end)

	fadeIn()
end

-- Return UpdateNotifier module.
return UpdateNotifier
end)
__bundle_register("Game/Timings/ModuleManager", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
-- Internal modules if they exist, provided by to by preprocessor.
local INTERNAL_MODULES = {
    ["BloodOrb"] = function()
        ---@type PartTiming
        local PartTiming = getfenv().PartTiming

        ---@type Action
        local Action = getfenv().Action

        ---@type ProjectileTracker
        ---@diagnostic disable-next-line: unused-local
        local ProjectileTracker = getfenv().ProjectileTracker

        ---@module Features.Combat.Defense
        local Defense = getfenv().Defense

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	local distance = self:distance(self.entity)

        	local tracker = ProjectileTracker.new(function(candidate)
        		return candidate.Name == "BloodBall_" .. self.entity.Name
        	end)

        	if distance <= 10 then
        		local action = Action.new()
        		action._type = "Parry"
        		action._when = 400
        		action.name = "Blood Orb Close Timing"
        		action.ihbc = true
        		return self:action(timing, action)
        	end

        	if distance <= 20 then
        		local action = Action.new()
        		action._type = "Parry"
        		action._when = 500
        		action.name = "Blood Orb Mid Timing"
        		action.ihbc = true
        		return self:action(timing, action)
        	end

        	if distance <= 30 then
        		local action = Action.new()
        		action._type = "Parry"
        		action._when = 600
        		action.name = "Blood Orb Mid Timing"
        		action.ihbc = true
        		return self:action(timing, action)
        	end

        	local action = Action.new()
        	action._when = 0
        	action._type = "Start Block"
        	action.name = "Blood Orb Part"

        	local actionTwo = Action.new()
        	actionTwo._when = 500
        	actionTwo._type = "End Block"
        	actionTwo.name = "Blood Orb End"
        	actionTwo.ihbc = true

        	local pt = PartTiming.new()
        	pt.uhc = true
        	pt.duih = true
        	pt.fhb = true
        	pt.name = "BloodOrbProjectile"
        	pt.hitbox = Vector3.new(20, 35, 15)
        	pt.actions:push(action)
        	pt.actions:push(actionTwo)
        	pt.cbm = true

        	Defense.cdpo(tracker:wait(), pt)
        end
    end,
    ["ArrowModel"] = function()
        ---@type PartTiming
        local PartTiming = getfenv().PartTiming

        ---@type Action
        local Action = getfenv().Action

        ---@type ProjectileTracker
        ---@diagnostic disable-next-line: unused-local
        local ProjectileTracker = getfenv().ProjectileTracker

        ---@module Features.Combat.Defense
        local Defense = getfenv().Defense

        ---@module Game.Latency
        local Latency = getfenv().Latency

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	local thrown = workspace:FindFirstChild("Thrown")
        	if not thrown then
        		return
        	end

        	local tracker = ProjectileTracker.new(function(candidate)
        		return candidate.Name == "ArrowModel_" .. self.entity.Name
        	end)

        	task.wait(0.05 - Latency.rtt())

        	if self:distance(self.entity) <= 25 then
        		local action = Action.new()
        		action._type = "Parry"
        		action._when = 0
        		action.name = "Arrow Close Timing"
        		action.ihbc = true
        		return self:action(timing, action)
        	end

        	local action = Action.new()
        	action._when = 0
        	action._type = "Parry"
        	action.name = "Arrow Part"

        	local pt = PartTiming.new()
        	pt.uhc = true
        	pt.duih = true
        	pt.name = "ArrowProjectile"
        	pt.hitbox = Vector3.new(50, 50, 100)
        	pt.actions:push(action)
        	pt.cbm = true

        	Defense.cdpo(tracker:wait(), pt)
        end
    end,
    ["AstralWind"] = function()
        ---@type Action
        local Action = getfenv().Action

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	timing.tag = "Spell"
        	timing.uif = true
        	timing.pfh = true
        	timing.pfht = 0.25
        	timing.phd = true
        	timing.phds = 1.0

        	local hrp = self.entity:FindFirstChild("HumanoidRootPart")
        	local speed = hrp and math.clamp(hrp.Velocity.Magnitude, 0, 25) or 0

        	local action = Action.new()
        	action._when = 300
        	action._type = "Parry"
        	action.hitbox = Vector3.new(40, 20, 40) + Vector3.new(0, 0, speed)
        	action.name = "Astral Wind Parry"
        	return self:action(timing, action)
        end
    end,
    ["AirForce"] = function()
        ---@class Action
        local Action = getfenv().Action

        ---@module Modules.Globals.Mantra
        local Mantra = getfenv().Mantra

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	local data = Mantra.data(self.entity, "Mantra:BlastWind{{Air Force}}")
        	local range = data.perfect * 8 + data.crystal * 6
        	local size = data.stratus * 1.5 + data.cloud * 1

        	local action = Action.new()
        	action._when = 0
        	action._type = "Parry"
        	action.hitbox = Vector3.new(20 + size, 20 + size, 50 + range)
        	action.name = "Dynamic Air Force Timing"

        	timing.ffh = true

        	self:action(timing, action)
        end
    end,
    ["ParasolTendrils"] = function()
        ---@type PartTiming
        local PartTiming = getfenv().PartTiming

        ---@module Features.Combat.Defense
        local Defense = getfenv().Defense

        ---@type Action
        local Action = getfenv().Action

        ---@module Utility.TaskSpawner
        local TaskSpawner = getfenv().TaskSpawner

        ---@module Game.Latency
        local Latency = getfenv().Latency

        -- Services.
        local players = game:GetService("Players")

        ---Check if the ParaHook is aiming at the local player.
        ---@param hook BasePart
        ---@return boolean
        local function isAimingAtPlayer(hook)
        	local character = players.LocalPlayer and players.LocalPlayer.Character
        	if not character then return false end
        	local rootPart = character:FindFirstChild("HumanoidRootPart")
        	if not rootPart then return false end

        	local toPlayer = (rootPart.Position - hook.Position).Unit
        	return hook.CFrame.UpVector:Dot(toPlayer) < -0.75
        end

        ---Module function.
        ---@param self SoundDefender
        ---@param timing SoundTiming
        return function(self, timing)
        	local part = self.part
        	if not part then return end
        	if not part.Name:match("ParaHook") then return end

        	-- Poll aiming continuously for 1000ms.
        	local isAiming = false
        	local startTime = os.clock()
        	while (os.clock() - startTime) < 1 do
        		if not part.Parent then return end
        		if isAimingAtPlayer(part) then
        			isAiming = true
        			break
        		end
        		task.wait()
        	end
        	if not isAiming then return end

        	-- Close range: delayed parry via spawned task (survives sound destruction).
        	local elapsed = os.clock() - startTime
        	if self:distance(part) <= 100 then
        		TaskSpawner.spawn("ParasolTendrilClose", function()
        			task.wait(math.max(0, 1.35 - Latency.rtt() - elapsed))
        			local action = Action.new()
        			action._when = 0
        			action._type = "Parry"
        			action.ihbc = true
        			action.name = "Parasol Tendril Close Parry"
        			self:action(timing, action)
        		end)
        		return
        	end

        	-- Far range: track the hook with duih.
        	local action = Action.new()
        	action._when = 0
        	action._type = "Parry"
        	action.ihbc = true
        	action.name = "Parasol Tendril Parry"

        	local pt = PartTiming.new()
        	pt.uhc = true
        	pt.duih = true
        	pt.fhb = false
        	pt.name = "Parasol Tendril"
        	pt.hitbox = Vector3.new(25, 200, 25)
        	pt.actions:push(action)
        	pt.cbm = true

        	Defense.cdpo(part, pt)
        end
    end,
