        		timing.iae = true
        		timing.rpue = true
        		timing.duih = false
        		timing.imdd = 0
        		timing.imxd = 1000
        		timing._rsd = 800
        		timing._rpd = 150
        		return self:srpue(self.entity, timing, info)

        	-- Blinding move
        	else
        		local action = Action.new()
        		action._when = 1400
        		action._type = "Parry"
        		action.hitbox = Vector3.new(800, 800, 800)
        		action.name = "Ethiron Blind Timing"
        		self:action(timing, action)
        	end
        end
    end,
