    ["FlameGrab"] = function()
        ---@type Action
        local Action = getfenv().Action

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	timing.duih = false
        	timing.fhb = false

        	local action = Action.new()
        	action._when = 0
        	action._type = "Parry"
        	action.hitbox = Vector3.new(20, 20, 25)
        	action.name = string.format("(1) (%.2f) Dynamic Flame Grab Timing", self.track.Speed)
        	self:action(timing, action)

        	repeat
                task.wait()
        	until self.track.TimePosition >= 0.25 or not self.track.IsPlaying

        	if not self.track.IsPlaying then
        		return
        	end

        	timing.duih = true
        	timing.hitbox = Vector3.new(20, 20, 20)
        	timing.fhb = true

        	local actionTwo = Action.new()
        	actionTwo._when = 0
        	actionTwo._type = "Parry"
        	actionTwo.name = string.format("(2) (%.2f) Dynamic Flame Grab Timing", self.track.Speed)
        	self:action(timing, actionTwo)
        end
    end,
    ["FlameRepulsion"] = function()
        ---@class Action
        local Action = getfenv().Action

        ---@module Modules.Globals.Mantra
        local Mantra = getfenv().Mantra

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	local data = Mantra.data(self.entity, "Mantra:RepulsionFire{{Flame Repulsion}}")
        	local range = data.stratus * 14 + data.cloud * 10

        	local action = Action.new()
        	action._when = 100
        	action._type = "Parry"
        	action.hitbox = Vector3.new(32 + range, 32 + range, 32 + range)
        	action.name = "Dynamic Flame Repulsion Timing"

        	timing.hitbox = action.hitbox

        	self:action(timing, action)
        end
    end,
    ["FlameRepulsionSpring"] = function()
        ---@type PartTiming
        local PartTiming = getfenv().PartTiming

        ---@type Action
        local Action = getfenv().Action

        ---@module Modules.Globals.Mantra
        local Mantra = getfenv().Mantra

        ---@type ProjectileTracker
        ---@diagnostic disable-next-line: unused-local
        local ProjectileTracker = getfenv().ProjectileTracker

        ---@module Features.Combat.Defense
        local Defense = getfenv().Defense

        ---@module Game.Latency
        local Latency = getfenv().Latency

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	local data = Mantra.data(self.entity, "Mantra:RepulsionFire{{Flame Repulsion}}")
        	local range = data.stratus * 2 + data.cloud * 2
        	local thrown = workspace:FindFirstChild("Thrown")
        	if not thrown then
        		return
        	end

        	local tracker = ProjectileTracker.new(function(candidate)
        		return candidate.Name:match("FlameRepulsionRanged")
        	end)

        	task.wait(0.9 - Latency.rtt())

        	if self:distance(self.entity) <= 25 then
        		local action = Action.new()
        		action._type = "Parry"
        		action._when = 0
        		action.name = "Flame Repulsion Ranged Close Timing"
        		action.ihbc = true
        		return self:action(timing, action)
        	end

        	local action = Action.new()
        	action._when = 0
        	action._type = "Start Block"
        	action.name = "Flame Repulsion Ranged Part"

        	local actionTwo = Action.new()
        	actionTwo._when = 300
        	actionTwo._type = "End Block"

        	local pt = PartTiming.new()
        	pt.uhc = true
        	pt.duih = true
        	pt.fhb = false
        	pt.name = "FlameRepulsionRangedProjectile"
        	pt.hitbox = Vector3.new(40 + range, 40 + range, 40 + range)
        	pt.actions:push(action)
        	pt.cbm = true

        	Defense.cdpo(tracker:wait(), pt)
        end
    end,
