    ["LightningSlash"] = function()
        ---@type Action
        local Action = getfenv().Action

        -- Slash counter.
        local sc = 0

        -- Last slash time
        local lst = 0.0

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	if os.clock() - lst >= 3.0 then
        		sc = 0
        	end

        	lst = os.clock()
        	sc = sc + 1

        	local action = Action.new()

        	if sc == 1 then
        		return
        	end

        	if sc == 2 then
        		action._when = 900
        	end

        	if sc == 3 then
        		action._when = 200
        	end

        	if sc == 4 then
        		action._when = 200
        	end

        	action._type = "Parry"
        	action.ihbc = true
        	action.name = string.format("(%i) Lightning Slash Ferryman Timing", sc)
        	return self:action(timing, action)
        end
    end,
    ["LightningStream"] = function()
        ---@type PartTiming
        local PartTiming = getfenv().PartTiming

        ---@type Action
        local Action = getfenv().Action

        ---@module Modules.Globals.Mantra
        local Mantra = getfenv().Mantra

        ---@type ProjectileTracker
        ---@diagnostic disable-next-line: unused-local
        local ProjectileTracker = getfenv().ProjectileTracker

        ---@module Features.Combat.Defense
        local Defense = getfenv().Defense

        ---@module Game.Latency
        local Latency = getfenv().Latency

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	local data = Mantra.data(self.entity, "Mantra:StreamLightning{{Lightning Stream}}")
        	local range = data.perfect * 26 + data.crystal * 24
        	local thrown = workspace:FindFirstChild("Thrown")
        	if not thrown then
        		return
        	end

        	local tracker = ProjectileTracker.new(function(candidate)
        		return candidate.Name == "STREAMPART"
        	end)

        	task.wait(0.3 - Latency.rtt())

            if self:distance(self.entity) <= 8 then
                local action = Action.new()
                action._type = "Parry"
                action._when = 250
                action.name = "Lightning Stream Close Timing"
                action.ihbc = true
                return self:action(timing, action)
            end

        	if self:distance(self.entity) <= 16 then
                local action = Action.new()
                action._type = "Parry"
                action._when = 400 
                action.name = "Lightning Stream Close Timing"
                action.ihbc = true
                return self:action(timing, action)
            end

            if self:distance(self.entity) <= 24 then
                local action = Action.new()
                action._type = "Parry"
                action._when = 500 
                action.name = "Lightning Stream Mid Timing"
                action.ihbc = true
                return self:action(timing, action)
            end

        	if self:distance(self.entity) <= 30 then
                local action = Action.new()
                action._type = "Parry"
                action._when = 600 
                action.name = "Lightning Stream Mid Timing"
                action.ihbc = true
                return self:action(timing, action)
            end

        	local action = Action.new()
        	action._when = 0
        	action._type = "Start Block"
        	action.name = "Lightning Stream Part"

        	local actionTwo = Action.new()
        	actionTwo._when = 500
        	actionTwo._type = "End Block"
        	actionTwo.name = "Lightning Stream End"
        	actionTwo.ihbc = true

        	local pt = PartTiming.new()
        	pt.uhc = true
        	pt.duih = true
        	pt.fhb = false
        	pt.name = "LightningStreamProjectile"
        	pt.hitbox = Vector3.new(55 + range, 55 + range, 55 + range)
        	pt.actions:push(action)
        	pt.actions:push(actionTwo)
        	pt.cbm = true

        	Defense.cdpo(tracker:wait(), pt)
        end
    end,
    ["LightningStrike"] = function()
        ---@type Action
        local Action = getfenv().Action

        ---@module Modules.Globals.Finder
        local Finder = getfenv().Finder

        ---Module function.
        ---@param self PartDefender
        ---@param timing PartTiming
        return function(self, timing)
        	local part = self.part
        	if not part then return end

        	-- Ignore if stormblade is active (LightningSword in Thrown near player).
        	local thrown = workspace:FindFirstChild("Thrown")
        	if thrown then
        		for _, child in next, thrown:GetChildren() do
        			if child.Name == "LightningSword" and self:distance(child) <= 50 then
        				return
        			end
        		end
        	end

        	-- Parasol present: delayed parry with ignore hitbox check.
        	if Finder.entity("parasol") then
        		local action = Action.new()
        		action._when = 600
        		action._type = "Parry"
        		action.ihbc = true
        		action.name = "Lightning Strike (Parasol)"
        		return self:action(timing, action)
        	end
        end
    end,
    ["LionfishBeam"] = function()
        ---@type Action
        local Action = getfenv().Action

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	local charging = false

        	timing.imb = true

        	while task.wait() do
        		local _, _, z = self.entity:GetPivot():ToOrientation()

        		-- ok, so the first part of the beam is the charge. we must detect the peak in which he starts fully charging his beam.
        		if not charging and z <= -1.7 then
        			charging = true
        		end

        		-- if there is no charge, continue.
        		if not charging then
        			continue
        		end

        		-- after that, we must detect the release. his release is at around -0.9 so if we're below that, we can continue.
        		if z <= -0.9 then
        			continue
        		end

        		local root = self.entity:FindFirstChild("HumanoidRootPart")
        		if not root then
        			continue
        		end

        		local corrupted = root:FindFirstChild("Fog")
        		local glacial = self.entity.Name:match("ice")

        		local action = Action.new()
        		action._when = 150
        		action._type = "Forced Full Dodge"
        		action.hitbox = Vector3.new(50, 100, 130)
        		action.name = "Lionfish Beam Dodge"

        		if glacial then
        			action.name = "Glacial Lionfish Beam Dodge"
        			action._when = 150
        		elseif corrupted then
        			action.name = "Corrupted Lionfish Beam Dodge"
        			action._when = 150
        		end

        		return self:action(timing, action)
        	end
        end
    end,
    ["LittleBell"] = function()
        ---@module Utility.TaskSpawner
        local TaskSpawner = getfenv().TaskSpawner

        ---@module Game.QueuedBlocking
        local QueuedBlocking = getfenv().QueuedBlocking

        ---@class Action
        local Action = getfenv().Action

        ---@module Utility.Finder
        local Finder = getfenv().Finder

        -- Services.
        local players = game:GetService("Players")

        -- State.
        local blockUntil = 0
        local parryBellUntil = 0
        local running = false

        ---Check if animation is a parry bell animation.
        ---@param animationId string
        ---@return boolean
        local function isParryBellAnimation(animationId)
        	return animationId == "rbxassetid://76760612897349"
        		or animationId == "rbxassetid://95485609909879"
        		or animationId == "rbxassetid://124372082770931"
        end

        ---Start block loop.
        local function startBlockLoop()
        	if running then
        		return
        	end

        	running = true

        	TaskSpawner.spawn("LittleBell_BlockLoop", function()
        		while os.clock() < blockUntil do
        			task.wait()
        		end

        		QueuedBlocking.stop("LittleBell")
        		running = false
        	end)
        end

        ---Invoke block.
        local function invokeBlock()
        	QueuedBlocking.invoke(QueuedBlocking.BLOCK_TYPE_NORMAL, "LittleBell", nil)
        	startBlockLoop()
        end

        ---Start hold block window.
        local function startHoldBlockWindow()
        	blockUntil = math.max(blockUntil, os.clock() + 5.5)
        	invokeBlock()
        end

        ---Parry bell animation.
        local function parryBellAnimation(self, timing)
        	parryBellUntil = math.max(parryBellUntil, os.clock() + 1.5)
        	timing.forced = true

        	local action = Action.new()
        	action._when = 720
        	action._type = "Parry"
        	action.hitbox = Vector3.new(25, 20, 25)
        	action.ihbc = true
        	action.name = "Knell Bell Parry Timing"
        	return self:action(timing, action)
        end

        ---Module function.
        ---@param self AnimatorDefender|PartDefender
        ---@param timing AnimationTiming|PartTiming
        return function(self, timing)
        	if self.__type == "Animation" then
        		local isParryAnimation = isParryBellAnimation(timing._id)

        		if timing._id ~= "rbxassetid://140154405052975" and not isParryAnimation then
        			return
        		end

        		if not Finder.entity("knell") then
        			return
        		end

        		timing.forced = true

        		if isParryAnimation then
        			return parryBellAnimation(self, timing)
        		end

        		return startHoldBlockWindow()
        	end

        	if os.clock() < parryBellUntil then
        		return
        	end

        	if os.clock() >= blockUntil then
        		return
        	end

        	local character = players.LocalPlayer and players.LocalPlayer.Character
        	if character and self.part:IsDescendantOf(character) then
        		return
        	end

        	local thrown = workspace:FindFirstChild("Thrown")
        	if not thrown or not self.part:IsDescendantOf(thrown) then
        		return
        	end

        	if self:distance(self.part) > 15 then
        		return
        	end

        	if not Finder.entity("knell") then
        		return
        	end

        	invokeBlock()
        end
    end,
