    ["MastersFlourish"] = function()
        ---@type Action
        local Action = getfenv().Action

        ---@module Game.InputClient
        local InputClient = getfenv().InputClient

        ---@module Game.Latency
        local Latency = getfenv().Latency

        -- Services.
        local replicatedStorage = game:GetService("ReplicatedStorage")

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
        	if not effectReplicator then return end
        	local effectReplicatorModule = require(effectReplicator)

        	-- First hit.
        	local action = Action.new()
        	action._when = 350
        	action._type = "Parry"
        	action.hitbox = Vector3.new(25, 15, 25)
        	action.name = "Masters Flourish (1)"
        	self:action(timing, action)

        	-- Wait for first action to fire, then check if we dodged.
        	task.wait((0.35 - Latency.rtt()) + 0.05)

        	if effectReplicatorModule:FindEffect("DodgeFrame") then
        		-- Dodged instead of parried, dodge again for second hit.
        		local dodge = Action.new()
        		dodge._when = 100
        		dodge._type = "Dodge"
        		dodge.ihbc = true
        		dodge.name = "Masters Flourish Dodge Chain"
        		return self:action(timing, dodge)
        	end

        	-- Second hit.
        	local actionTwo = Action.new()
        	actionTwo._when = 800 - 350 - 50
        	actionTwo._type = "Parry"
        	actionTwo.hitbox = Vector3.new(20, 18, 20)
        	actionTwo.name = "Masters Flourish (2)"
        	return self:action(timing, actionTwo)
        end
    end,
    ["MetalArmament"] = function()
        ---@type Action
        local Action = getfenv().Action

        ---Module function.
        ---@param self PartDefender
        ---@param timing PartTiming
        return function(self, timing)
        	local part = self.part
        	local localChar = game.Players.LocalPlayer.Character

        	if localChar and part:IsDescendantOf(localChar) then
        		self:notify(timing, "Skipped - local player")
        		return
        	end

        	local parent = part.Parent
        	if not parent then
        		self:notify(timing, "Skipped - no parent")
        		return
        	end

        	local handle = parent:FindFirstChild("Handle")
        	if not handle then
        		self:notify(timing, "Skipped - no handle found")
        		return
        	end

        	local hrp = localChar and localChar:FindFirstChild("HumanoidRootPart")
        	local enemyHrp = parent.Parent and parent.Parent:FindFirstChild("HumanoidRootPart")

        	self.part = handle

        	local action = Action.new()

        	if part.Name == "MetalSword" then
        		if hrp and enemyHrp then
        			local dist = (hrp.Position - enemyHrp.Position).Magnitude
        			if dist > 50 then
        				return
        			end
        		end
        		self:notify(timing, "Metal Armament detected")
        		action._when = 400
        		action._type = "Parry"
        		action.hitbox = Vector3.new(31, 31, 31)
        		action.name = "MetalArmament"
        	elseif part.Name == "BladePart" then
        		if hrp and enemyHrp then
        			local dist = (hrp.Position - enemyHrp.Position).Magnitude
        			if dist > 118 then
        				return
        			end
        		end
        		self:notify(timing, "Grand Warden Axe detected")
        		action._when = 800
        		action._type = "Parry"
        		action.hitbox = Vector3.new(32, 18, 32)
        		action.name = "GrandWardenAxe"
        	else
        		return
        	end

        	return self:action(timing, action)
        end
    end,
    ["MetalBall"] = function()
        ---@type Action
        local Action = getfenv().Action

        ---@module Game.Latency
        local Latency = getfenv().Latency

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	timing.ieae = true
        	timing.iae = true

        	task.wait(0.5 - Latency.rtt())

        	-- Wait for SpikeBall (partial match, can have number suffix).
        	local spikeBall = nil
        	local isBlocking = false

        	while task.wait() do
        		if not spikeBall then
        			for _, child in next, self.entity:GetChildren() do
        				if child.Name:match("^SpikeBall") then
        					spikeBall = child
        					break
        				end
        			end
        			if not spikeBall then
        				continue
        			end
        		end

        		if not spikeBall.Parent then
        			local endAction = Action.new()
        			endAction._when = 0
        			endAction._type = "End Block"
        			endAction.ihbc = true
        			endAction.name = "Metal Ball End"
        			return self:action(timing, endAction)
        		end

        		if isBlocking then
        			continue
        		end

        		if self:distance(self.entity) >= 30 then
        			continue
        		end

        		local action = Action.new()
        		action._when = 0
        		action.ihbc = true
        		action._type = "Start Block"
        		action.name = "Metal Ball Block"
        		self:action(timing, action)

        		isBlocking = true
        	end
        end
    end,
