        	actionTwo._when = 1400
        	actionTwo._type = "End Block"
        	actionTwo.ihbc = true
        	actionTwo.name = string.format("(%.2f) Dynamic Pressure Blast Timing", distance)
        	return self:action(timing, actionTwo)
        end
    end,
