    ["RisingShadow"] = function()
        ---@type PartTiming
        local PartTiming = getfenv().PartTiming

        ---@type Action
        local Action = getfenv().Action

        ---@module Modules.Globals.Mantra
        local Mantra = getfenv().Mantra

        ---@type ProjectileTracker
        local ProjectileTracker = getfenv().ProjectileTracker

        ---@module Features.Combat.Defense
        local Defense = getfenv().Defense

        ---@module Utility.TaskSpawner
        local TaskSpawner = getfenv().TaskSpawner

        ---@module Game.Latency
        local Latency = getfenv().Latency

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
            timing.forced = true

            TaskSpawner.spawn("Module_RisingShadow", function()
                local data = Mantra.data(self.entity, "Mantra:RisingSlashShadow{{Rising Shadow}}")
                local range = data.rush * 3 + data.drift * 2

                local thrown = workspace:FindFirstChild("Thrown")
                if not thrown then
                    return
                end

                local tracker = ProjectileTracker.new(function(candidate)
                    return candidate.Name == "TRACKER" 
                end)

                task.wait(math.max(0, 0.5 - Latency.rtt()))

                if self:distance(self.entity) <= 10 then
                    local action = Action.new()
                    action._type = "Parry" 
                    action._when = 75
                    action.name = "Rising Shadow Close Timing"
                    action.ihbc = true
                    action.fhb = true
                    return self:action(timing, action)
                end

                local hrp = self.entity:FindFirstChild("HumanoidRootPart")
                local playerVelocity = hrp and hrp.AssemblyLinearVelocity.Magnitude or 0
                local velocityFactor = 1 - math.min(playerVelocity / 50, 0.5)

                local action = Action.new()
                action._when = 380 * velocityFactor
                action._type = "Parry" 
                action.name = "Rising Shadow Part"

                local pt = PartTiming.new()
                pt.uhc = true
                pt.duih = true
                pt.fhb = true 
                pt.name = "RisingShadowProjectile"

                pt.hitbox = Vector3.new(22 + range, 22 + range, 22 + range)
                pt.actions:push(action)
                pt.cbm = true

                Defense.cdpo(tracker:wait(), pt)
            end)
        end
    end,
    ["RisingThunder"] = function()
        ---@type Action
        local Action = getfenv().Action

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	timing.duih = true
        	timing.hitbox = Vector3.new(15, 20, 18)
        	timing.mat = 1300
        	timing.iae = true
        	timing.ieae = true

        	local distance = self:distance(self.entity)


            if self:distance(self.entity) <= 10 then
                    local action = Action.new()
                    action._type = "Parry" 
                    action._when = 250
                    action.name = "Rising Thunder Close Timing"
                    action.ihbc = true
                    action.fhb = true
                    return self:action(timing, action)
            end

        	if self:distance(self.entity) <= 18 then
                    local action = Action.new()
                    action._type = "Parry" 
                    action._when = 600
                    action.name = "Rising Thunder Close Timing"
                    action.ihbc = true
                    action.fhb = true
                    return self:action(timing, action)
            end


        	local action = Action.new()
        	action._when = 400
        	action._type = "Start Block"
        	action.name = string.format("(1) Rising Thunder Start", distance)
        	self:action(timing, action)

        	local secondAction = Action.new()
        	secondAction._when = 1250
        	secondAction._type = "End Block"
        	secondAction.name = "(2) Rising Thunder End"
        	self:action(timing, secondAction)

        	local entity = self.entity

        	local function onFolderCreated(folder)
        		self:notify(timing, "(3) Rising Thunder Strike")

        		task.spawn(function()
        			task.wait(750 / 1000)
        			self:notify(timing, "Folder Detected, Executing Parry")
        			self:parry(timing, nil)
        		end)
        	end

        	local folderConn
        	folderConn = entity.DescendantAdded:Connect(function(d)
        		if not d:IsA("Folder") then return end
        		if not d.Name:match("RisingLightning") then return end
        		onFolderCreated(d)
        	end)

        	self.tmaid:mark(folderConn)
        end
    end,
