    ["WindBlade"] = function()
        ---@type PartTiming
        local PartTiming = getfenv().PartTiming

        ---@type Action
        local Action = getfenv().Action

        ---@module Utility.Finder
        local Finder = getfenv().Finder

        ---@type ProjectileTracker
        ---@diagnostic disable-next-line: unused-local
        local ProjectileTracker = getfenv().ProjectileTracker

        ---@module Features.Combat.Defense
        local Defense = getfenv().Defense

        ---@module Game.Latency
        local Latency = getfenv().Latency

        ---Module function.
        ---@param self AnimatorDefender|PartDefender
        ---@param timing AnimationTiming|PartTiming
        return function(self, timing)
        	if self.__type == "Part" then
        		local duke = Finder.entity("theduke")
        		local root = duke and duke:FindFirstChild("HumanoidRootPart")

        		if root and (self.part.Position - root.Position).Magnitude <= 10 then
        			return
        		end

        		local action = Action.new()
        		action._when = timing.name == "WindSlashProjectile" and 150 or 0
        		action._type = "Parry"
        		action.hitbox = Vector3.zero
        		action.ihbc = false
        		action.name = timing.name == "WindSlashProjectile" and "Wind Slash Projectile Timing" or "Wind Blade Timing"
        		return self:action(timing, action)
        	end

        	local thrown = workspace:FindFirstChild("Thrown")
        	if not thrown then
        		return
        	end

        	local tracker = ProjectileTracker.new(function(candidate)
        		return candidate.Name == "WindSlashProjectile"
        	end)

        	task.wait(0.5 - Latency.rtt())

        	if self:distance(self.entity) <= 20 then
        		local action = Action.new()
        		action._type = "Parry"
        		action._when = 0
        		action.name = "Arc Beam Close Timing"
        		action.ihbc = true
        		return self:action(timing, action)
        	end

        	local action = Action.new()
        	action._when = 0
        	action._type = "Parry"
        	action.name = "Wind Slash Part"

        	local pt = PartTiming.new()
        	pt.uhc = true
        	pt.duih = true
        	pt.fhb = true
        	pt.name = "WindSlashProjectile"
        	pt.hitbox = Vector3.new(10, 10, 10)
        	pt.actions:push(action)
        	pt.cbm = true

        	Defense.cdpo(tracker:wait(), pt)
        end
    end,
    ["WindCarve"] = function()
        ---@type Action
        local Action = getfenv().Action

        ---@module Modules.Globals.Mantra
        local Mantra = getfenv().Mantra

        ---@type Signal
        local Signal = getfenv().Signal

        ---@type HitboxOptions
        local HitboxOptions = getfenv().HitboxOptions

        ---@module Game.Latency
        local Latency = getfenv().Latency

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	local data = Mantra.data(self.entity, "Mantra:CarveWind{{Wind Carve}}")
        	local range = data.stratus * 1.4 + data.cloud * 0.9

        	timing.ffh = true
        	timing.pfh = true
        	timing.fhb = true
        	timing.rpue = false
        	timing.duih = true
        	timing.hitbox = Vector3.new(20 + range, 20 + range, 13.5 + range)

        	local root = self.entity:FindFirstChild("HumanoidRootPart")
        	if not root then
        		return
        	end

        	-- Set up End Block listener before waiting.
        	local onDescendantAdded = Signal.new(self.entity.DescendantAdded)

        	self.tmaid:add(onDescendantAdded:connect("WindCarve_StopCarve", function(child)
        		if child.Name == "StopCarve" then
        			local actionTwo = Action.new()
        			actionTwo._when = 0
        			actionTwo._type = "End Block"
        			actionTwo.ihbc = true
        			actionTwo.name = "Wind Carve End"
        			self:action(timing, actionTwo)
        		end
        	end))

        	-- Wait initial delay.
        	task.wait(0.5 - Latency.rtt())

        	-- Wait until in hitbox.
        	local hoptions = HitboxOptions.new(root, timing)
        	hoptions.spredict = false
        	hoptions.entity = self.entity
        	hoptions:ucache()

        	while task.wait() do
        		if self:hc(hoptions, nil) then
        			break
        		end
        	end

        	-- Start block.
        	local action = Action.new()
        	action._when = 0
        	action._type = "Start Block"
        	action.ihbc = true
        	action.name = "Wind Carve Start"
        	self:action(timing, action)
        end
    end,
    ["WindForge"] = function()
        ---@class Action
        local Action = getfenv().Action

        ---@module Modules.Globals.TetherBoxTracker
        local TetherBoxTracker = getfenv().TetherBoxTracker

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	TetherBoxTracker.watch(self, timing, 10)

        	local action = Action.new()
        	action._when = 1750
        	action._type = "Parry"
        	action.hitbox = Vector3.new(118, 115, 118)
        	action.name = "Wind Forge Timing"
        	return self:action(timing, action)
        end
    end,
    ["WindGun"] = function()
        ---@type Action
        local Action = getfenv().Action

        ---Module function.
        ---@param self AnimatorDefender
        ---@param timing AnimationTiming
        return function(self, timing)
        	timing.ffh = true

        	local distance = self:distance(self.entity)
        	local player = game:GetService("Players"):GetPlayerFromCharacter(self.entity)
        	local backpack = player and player:FindFirstChild("Backpack")

        	local hasBlastSpark = false

        	if backpack then
        		for _, item in next, backpack:GetChildren() do
        			if item.Name:find("GunWind") then
        				local richStats = item:GetAttribute("RichStats")
        				if richStats and richStats:find("Blast Spark") then
        					hasBlastSpark = true
        				end
        				break
        			end
        		end
        	end

        	if hasBlastSpark then
        		local action = Action.new()
        		action._when = 500
        		action._type = "Parry"
        		action.hitbox = Vector3.new(30, 20, 40)
        		action.name = string.format("(%.2f) Wind Gun (Blast Spark)", distance)

        		return self:action(timing, action)
        	else
        		local action = Action.new()
        		action._when = 400

        		if distance >= 20 then
        			action._when = 500
        		end

        		action._type = "Parry"
        		action.hitbox = Vector3.new(30, 20, 40)
        		action.name = string.format("(%.2f) Dynamic Wind Gun Timing", distance)

        		return self:action(timing, action)
        	end
        end
    end,
