    ["TetherBoxTracker"] = function()
        ---@class Action
        local Action = getfenv().Action

        ---@module Utility.TaskSpawner
        local TaskSpawner = getfenv().TaskSpawner

        -- Services.
        local players = game:GetService("Players")
        local runService = game:GetService("RunService")

        -- Tether box tracker.
        local TetherBoxTracker = {}

        -- State.
        local activeBoxes = {}
        local lastParry = 0

        ---Get local root part.
        ---@return BasePart?
        local function localRoot()
        	local character = players.LocalPlayer and players.LocalPlayer.Character
        	return character and character:FindFirstChild("HumanoidRootPart")
        end

        ---Get tether box.
        ---@param instance Instance
        ---@return Instance?
        function TetherBoxTracker.box(instance)
        	if not instance then
        		return
        	end

        	if instance.Name == "Tether Box" then
        		return instance
        	end

        	return instance:FindFirstAncestor("Tether Box")
        end

        ---Get fallback part.
        ---@param box Instance
        ---@param fallback Instance?
        ---@return BasePart?
        local function fallbackPart(box, fallback)
        	if fallback and fallback:IsA("BasePart") then
        		return fallback
        	end

        	if box:IsA("BasePart") then
        		return box
        	end

        	return box:FindFirstChildWhichIsA("BasePart", true)
        end

        ---Get box position.
        ---@param box Instance
        ---@param fallback BasePart?
        ---@return Vector3?
        local function boxPosition(box, fallback)
        	if box:IsA("Model") then
        		return box:GetPivot().Position
        	end

        	if box:IsA("BasePart") then
        		return box.Position
        	end

        	local position = Vector3.zero
        	local count = 0

        	for _, descendant in next, box:GetDescendants() do
        		if not descendant:IsA("BasePart") then
        			continue
        		end

        		position = position + descendant.Position
        		count = count + 1
        	end

        	if count <= 0 then
        		return fallback and fallback.Position or nil
        	end

        	return position / count
        end

        ---Check hitbox range.
        ---@param position Vector3
        ---@param movement Vector3
        ---@param rootPosition Vector3
        ---@return boolean
        local function inHitboxRange(position, movement, rootPosition)
        	local cframe = CFrame.lookAt(position, position + movement.Unit)
        	local offset = cframe:PointToObjectSpace(rootPosition)

        	return math.abs(offset.X) <= 25 / 2
        		and math.abs(offset.Y) <= 10 / 2
        		and math.abs(offset.Z) <= 10 / 2
        end

        ---Queue parry.
        ---@param self Defender
        ---@param timing Timing
        local function queueParry(self, timing)
        	timing.forced = true

        	local action = Action.new()
        	action._when = 50
        	action._type = "Parry"
        	action.hitbox = Vector3.zero
        	action.ihbc = true
        	action.name = "Tether Box Timing"
        	return self:action(timing, action)
        end

        ---Track box movement.
        ---@param self Defender
        ---@param timing Timing
        ---@param box Instance
        ---@param fallback Instance?
        function TetherBoxTracker.track(self, timing, box, fallback)
        	if not box then
        		return
        	end

        	local info = activeBoxes[box] or {}
        	if info.tracking then
        		return
        	end

        	local root = localRoot()
        	if not root then
        		return
        	end

        	local part = fallbackPart(box, fallback)
        	local position = boxPosition(box, part)
        	if not position then
        		return
        	end

        	info.position = position
        	info.distance = (position - root.Position).Magnitude
        	info.updated = os.clock()
        	info.tracking = true
        	activeBoxes[box] = info

        	local started = os.clock()

        	while box.Parent and os.clock() - started <= 10 do
        		local delta = runService.Heartbeat:Wait() or 1 / 60
        		root = localRoot()

        		if not root then
        			continue
        		end

        		part = fallbackPart(box, fallback)
        		position = boxPosition(box, part)

        		if not position then
        			continue
        		end

        		local now = os.clock()
        		local movement = position - info.position
        		local distance = (position - root.Position).Magnitude
        		local moveDistance = movement.Magnitude
        		local toRoot = root.Position - position

        		info.position = position
        		info.updated = now

        		if moveDistance < 0.02 or toRoot.Magnitude <= 0 then
        			info.distance = distance
        			continue
        		end

        		local closingSpeed = (info.distance - distance) / math.max(delta, 1 / 60)
        		local movingTowardRoot = movement.Unit:Dot(toRoot.Unit) >= 0.6

        		info.distance = distance

        		if not movingTowardRoot or closingSpeed < 3 then
        			continue
        		end

        		if not inHitboxRange(position, movement, root.Position) then
        			continue
        		end

        		if now - lastParry < 0.6 then
        			continue
        		end

        		lastParry = now
        		activeBoxes[box] = nil
        		return queueParry(self, timing)
        	end

        	activeBoxes[box] = nil
        end

        ---Track candidate instance.
        ---@param self Defender
        ---@param timing Timing
        ---@param candidate Instance
        function TetherBoxTracker.candidate(self, timing, candidate)
        	local box = TetherBoxTracker.box(candidate)
        	if not box then
        		return
        	end

        	TaskSpawner.spawn("TetherBoxTracker_Track", TetherBoxTracker.track, self, timing, box, candidate)
        end

        ---Watch for tether boxes.
        ---@param self Defender
        ---@param timing Timing
        ---@param duration number
        function TetherBoxTracker.watch(self, timing, duration)
        	local expires = os.clock() + duration

        	TaskSpawner.spawn("TetherBoxTracker_Watch", function()
        		local connection = workspace.DescendantAdded:Connect(function(descendant)
        			if os.clock() > expires then
        				return
        			end

        			TetherBoxTracker.candidate(self, timing, descendant)
        		end)

        		for _, descendant in next, workspace:GetDescendants() do
        			TetherBoxTracker.candidate(self, timing, descendant)
        		end

        		while os.clock() <= expires do
        			task.wait(0.1)
        		end

        		connection:Disconnect()
        	end)
        end

        ---Detach function.
        function TetherBoxTracker.detach()
        	activeBoxes = {}
        	lastParry = 0
        end

        -- Return tether box tracker.
        return TetherBoxTracker
    end,
    ["Waiter"] = function()
        ---Waiter module.
        local Waiter = {}

        ---@module Game.Latency
        local Latency = getfenv().Latency

        ---Find a track.
        ---@param aid string Animation ID to look for.
        ---@param animator Animator The animator to search in.
        ---@return AnimationTrack?
        function Waiter.ftrack(aid, animator)
        	for _, track in next, animator:GetPlayingAnimationTracks() do
        		local animation = track.Animation
        		if not animation then
        			continue
        		end

        		if animation.AnimationId ~= aid then
        			continue
        		end

        		return track
        	end
        end

        ---Stepped wait.
        ---@param defender Defender
        ---@param time number The time to wait in seconds.
        ---@param callback function The callback to run.
        function Waiter.stw(defender, time, callback)
        	local lastTimestamp = os.clock()
        	local initialPing = Latency.rtt()

        	while (os.clock() - lastTimestamp) <= (time - initialPing) do
        		-- Wait.
        		task.wait()

        		-- Step.
        		callback()
        	end
        end

        ---Fetch a track.
        ---@param aid string Animation ID to look for.
        ---@param animator Animator The animator to search in.
        ---@return AnimationTrack?
        function Waiter.fet(aid, animator)
        	while task.wait() do
        		local track = Waiter.ftrack(aid, animator)
        		if not track then
        			continue
        		end

        		return track
        	end
        end

        -- Return Waiter module.
        return Waiter
    end,
    ["Weapon"] = function()
        ---@module Game.Timings.Action
        local Action = getfenv().Action

        -- Weapon module.
        local Weapon = {}

        ---Get equipped weapon data.
        ---@param entity Model
        function Weapon.data(entity)
        	local hw = nil

        	if entity:GetAttribute("MOB_rich_name") then
        		local lh = entity:FindFirstChild("LeftHand")
        		local rh = entity:FindFirstChild("RightHand")
        		if not lh and not rh then
        			return
        		end

        		hw = (lh and lh:FindFirstChild("HandWeapon")) or (rh and rh:FindFirstChild("HandWeapon"))
        		if not hw then
        			return
        		end
        	else
        		local thrown = workspace:FindFirstChild("Thrown")
        		if not thrown then
        			return
        		end

        		local attach = thrown:FindFirstChild("Attach_" .. entity.Name)
        		if not attach then
        			return
        		end

        		hw = attach:FindFirstChild("HandWeapon")
        		if not hw then
        			return
        		end
        	end

        	local hwstats = hw:FindFirstChild("Stats")
        	if not hwstats then
        		return
        	end

        	local ssv = hwstats:FindFirstChild("SwingSpeed")
        	if not ssv then
        		return
        	end

        	local lv = hwstats:FindFirstChild("Length")
        	if not lv then
        		return
        	end

        	local type = hw:FindFirstChild("Type")
        	if not type then
        		return
        	end

        	local nemesis = false

        	for _, inst in next, hw:GetChildren() do
        		if not inst:IsA("ParticleEmitter") then
        			continue
        		end

        		if inst.Texture ~= "rbxassetid://11889781532" then
        			continue
        		end

        		nemesis = true
        		break
        	end

        	return {
        		hw = hw,
        		ss = ssv.Value,
        		oss = ssv:GetAttribute("OldValue") or ssv.Value,
        		length = lv.Value,
        		type = type.Value or "N/A",
        		nemesis = nemesis,
        	}
        end

        -- Return Weapon module.
        return Weapon
    end
}

-- Module manager.
---@note: All globals get executed first but never ran. This gets set in the global environment of every future module after.
local ModuleManager = { modules = {}, globals = {} }

---@module Utility.Filesystem
local Filesystem = require("Utility/Filesystem")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Game.Timings.Action
local Action = require("Game/Timings/Action")

---@module Game.InputClient
local InputClient = require("Game/InputClient")

---@module Features.Combat.Objects.Task
local Task = require("Features/Combat/Objects/Task")

---@module Game.Timings.Timing
local Timing = require("Game/Timings/Timing")

---@module Features.Combat.StateListener
local StateListener = require("Features/Combat/StateListener")

---@module Utility.TaskSpawner
local TaskSpawner = require("Utility/TaskSpawner")

---@module Utility.Finder
local Finder = require("Utility/Finder")

---@module Features.Combat.Targeting
local Targeting = require("Features/Combat/Targeting")

---@module Game.Timings.PartTiming
local PartTiming = require("Game/Timings/PartTiming")

---@module Features.Combat.Objects.HitboxOptions
local HitboxOptions = require("Features/Combat/Objects/HitboxOptions")

---@module Features.Combat.Objects.RepeatInfo
local RepeatInfo = require("Features/Combat/Objects/RepeatInfo")

---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Utility.Signal
local Signal = require("Utility/Signal")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@module Game.QueuedBlocking
local QueuedBlocking = require("Game/QueuedBlocking")

-- Module filesystem.
local fs = Filesystem.new("Mira/Mira-Rewrite-Modules")
local gfs = Filesystem.new(fs:append("Globals"))

-- Detach table.
local tdetach = {}

---Execute module function.
---@param lf function
---@param id string
---@param file string?
---@param global boolean
function ModuleManager.execute(lf, id, file, global)
	---@module Features.Combat.Defense
	---@note: For some reason, it broke lol. Returned nil.
	-- Has to do with loadingPlaceholder issue.
	local Defense = require("Features/Combat/Defense")

	---@module Game.Latency
	local Latency = require("Game/Latency")

	-- Set function environment to allow for internal modules.
	getfenv(lf).Timing = Timing
	getfenv(lf).PartTiming = PartTiming
	getfenv(lf).Defense = Defense
	getfenv(lf).Action = Action
	getfenv(lf).Task = Task
	getfenv(lf).Maid = Maid
	getfenv(lf).Signal = Signal
	getfenv(lf).InputClient = InputClient
	getfenv(lf).TaskSpawner = TaskSpawner
	getfenv(lf).Targeting = Targeting
	getfenv(lf).Finder = Finder
	getfenv(lf).Logger = Logger
	getfenv(lf).HitboxOptions = HitboxOptions
	getfenv(lf).RepeatInfo = RepeatInfo
	getfenv(lf).StateListener = StateListener
	getfenv(lf).Latency = Latency
	getfenv(lf).Configuration = Configuration
	getfenv(lf).QueuedBlocking = QueuedBlocking

	-- Load globals if we should.
	for name, entry in next, (not global) and ModuleManager.globals or {} do
		getfenv(lf)[name] = entry
	end

	-- Run executable function to initialize it.
	local success, result = pcall(lf)
	if not success then
		return Logger.warn("Module '%s' failed to load due to error '%s' while executing.", file or id, result)
	end

	if global and typeof(result) ~= "table" then
		return Logger.warn("Global module '%s' is invalid because it does not return a table.", file or id)
	end

	-- Output table.
	local output = global and ModuleManager.globals or ModuleManager.modules

	-- Get the result as a function.
	output[id] = result

	-- If this is a global, the result is a table, and it has a detach function, store it for later.
	if typeof(result) == "table" and typeof(result.detach) == "function" then
		tdetach[#tdetach + 1] = result.detach
	end
end

---Load file modules from filesystem.
---@param tfs Filesystem The filesystem to load from.
---@param global boolean Whether we're loading global modules or not.
function ModuleManager.load(tfs, global)
	for _, file in next, tfs:list(false) do
		-- Check if it is .lua.
		if string.sub(file, #file - 3, #file) ~= ".lua" then
			continue
		end

		-- Get string to load.
		local ls = tfs:read(file)

		-- Get function that we can execute.
		local lf, lr = loadstring(ls)
		if not lf then
			Logger.warn("Module file '%s' failed to load due to error '%s' while loading.", file, lr)
			continue
		end

		ModuleManager.execute(lf, string.sub(file, 1, #file - 4), file, global)
	end
end

---List loaded modules.
---@return string[]
function ModuleManager.loaded()
	local out = {}

	for file, _ in next, ModuleManager.modules do
		table.insert(out, file)
	end

	return out
end

---Detach functions.
function ModuleManager.detach()
	for _, detach in next, tdetach do
		detach()
	end

	-- Clear detach table.
	tdetach = {}
end

---Refresh ModuleManager.
function ModuleManager.refresh()
	-- Detach all modules.
	ModuleManager.detach()

	-- Reset current list.
	ModuleManager.modules = {}
	ModuleManager.globals = {}

	for id, lf in next, INTERNAL_GLOBALS do
		ModuleManager.execute(lf, id, nil, true)
	end

	for id, lf in next, INTERNAL_MODULES do
		ModuleManager.execute(lf, id, nil, false)
	end

	-- Load all globals in our filesystem.


	-- Load all modules in our filesystem.

end

-- Return ModuleManager module.
return ModuleManager
end)()
end)
