---Get the backstab mantra tool from backpack.
---@return Tool|nil
local function getBackstabMantraTool()
	local backpack = localPlayer and localPlayer:FindFirstChild("Backpack")
	if not backpack then
		return nil
	end

	local selectedMantras = Configuration.expectOptionValue("BackstabMovestackMantras")
	if type(selectedMantras) ~= "table" then
		return nil
	end

	local candidates = table.clone(selectedMantras)
	local hasCandidates = false
	for _, selected in next, candidates do
		if selected then
			hasCandidates = true
			break
		end
	end

	if not hasCandidates then
		return nil
	end

	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	local effectReplicatorModule = effectReplicator and require(effectReplicator)

	if effectReplicatorModule and effectReplicatorModule.GetEffects then
		for _, effect in pairs(effectReplicatorModule:GetEffects()) do
			if type(effect) ~= "table" then
				continue
			end

			local class = effect.Class or (effect.index and effect.index.Class)
			local value = effect.Value or (effect.index and effect.index.Value)

			if class == "ToolLockCD" and value then
				local tool = backpack:FindFirstChild(tostring(value))
				if tool and tool:GetAttribute("DefaultName") then
					candidates[tool:GetAttribute("DefaultName")] = nil
				end
			end
		end
	end

	local decidedMantra = next(candidates)
	if not decidedMantra then
		return nil
	end

	for _, tool in pairs(backpack:GetChildren()) do
		if tool:IsA("Tool") then
			local defaultName = tool:GetAttribute("DefaultName")
			if defaultName and defaultName == decidedMantra then
				return tool
			end
		end
	end

	return nil
end

---Try to activate backstab movestack.
---@return boolean
local function tryActivateBackstabMovestack()
	if not Configuration.expectToggleValue("BackstabMovestack") then
		return false
	end

	local tool = getBackstabMantraTool()
	if not tool then
		return false
	end

	local localPlayer = game:GetService("Players").LocalPlayer
	local character = localPlayer and localPlayer.Character
	local characterHandler = character and character:FindFirstChild("CharacterHandler")
	local requests = characterHandler and characterHandler:FindFirstChild("Requests")
	local activateMantra = requests and requests:FindFirstChild("ActivateMantra")

	if activateMantra then
		activateMantra:FireServer(tool)
		if Configuration.expectToggleValue("ShowDebugInformation") then
			Logger.notify("[Movestack] FIRED mantra: %s", tostring(tool:GetAttribute("DefaultName")))
		end
		return true
	end

	return false
end

---Check if backstab action is locked.
---@return boolean
local function isBackstabActionLocked()
	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	local effectReplicatorModule = effectReplicator and require(effectReplicator)
	if not effectReplicatorModule then
		return false
	end

	return effectReplicatorModule:HasAny("Action", "MobileAction", "UsingAbility", "LightAttack")
end

---Get backstab movestack delay.
---@return number
local function getBackstabMovestackDelay()
	local delay = Configuration.expectOptionValue("BackstabMovestackDelay") or 0.05
	return math.max(delay, 0.0)
end

---Schedule backstab movestack activation.
---@param label string
local function scheduleBackstabMovestackActivation(label)
	TaskSpawner.delay(label, function()
		return getBackstabMovestackDelay()
	end, function()
		backstabMovestackReady = false
		tryActivateBackstabMovestack()
	end)
end

---Check if animation track is the backstab trigger.
---@param track AnimationTrack
---@return boolean
local function isBackstabTriggerAnimationTrack(track)
	if not track or not track.Animation then
		return false
	end

	local aid = tostring(track.Animation.AnimationId)
	if aid == BACKSTAB_TRIGGER_ANIMATION_ID then
		return true
	end

	local numericId = aid:match("%d+")
	return numericId == BACKSTAB_TRIGGER_ANIMATION_NUMERIC_ID
end

---On local backstab animation played.
---@param track AnimationTrack
local onBackstabLocalAnimationPlayed = (function(track)
	if not Configuration.expectToggleValue("BackstabMovestack") then
		return
	end

	if not isBackstabTriggerAnimationTrack(track) then
		return
	end

	if os.clock() - backstabAnimationTriggerTimestamp <= 0.15 then
		return
	end

	backstabMovestackReady = true
	backstabAnimationTriggerTimestamp = os.clock()

	if Configuration.expectToggleValue("ShowDebugInformation") then
		local dbgTool = getBackstabMantraTool()
		local dbgChar = localPlayer and localPlayer.Character
		local dbgReq = dbgChar and dbgChar:FindFirstChild("CharacterHandler")
		dbgReq = dbgReq and dbgReq:FindFirstChild("Requests")
		local dbgRemote = dbgReq and dbgReq:FindFirstChild("ActivateMantra")
		Logger.notify("[Movestack] trigger | tool=%s remote=%s actionLocked=%s",
			dbgTool and tostring(dbgTool:GetAttribute("DefaultName")) or "NIL",
			dbgRemote and "ok" or "NIL",
			tostring(isBackstabActionLocked()))
	end

	if not isBackstabActionLocked() and tryActivateBackstabMovestack() then
		backstabMovestackReady = false
		return
	end

	TaskSpawner.spawn("Defense_BackstabMovestackImmediateRetry", function()
		local startedAt = os.clock()

		while os.clock() - startedAt <= 0.35 do
			if not backstabMovestackReady then
				return
			end

			if not Configuration.expectToggleValue("BackstabMovestack") then
				return
			end

			if not isBackstabActionLocked() and tryActivateBackstabMovestack() then
				backstabMovestackReady = false
				return
			end

			runService.RenderStepped:Wait()
		end

		scheduleBackstabMovestackActivation("Defense_BackstabMovestackFromAnimation")
	end)
end)

---Bind backstab animation listener to character.
---@param character Model
local function bindBackstabAnimationListener(character)
	if not character then
		return
	end

	local animator = character:FindFirstChildWhichIsA("Animator", true)
	if not animator then
		return
	end

	local animationPlayed = Signal.new(animator.AnimationPlayed)
	defenseMaid["Defense_BackstabAnimationPlayed"] =
		animationPlayed:connect("Defense_BackstabAnimationPlayed", onBackstabLocalAnimationPlayed)
end

---On backstab character added.
---@param character Model
local function onBackstabCharacterAdded(character)
	if not character then
		return
	end

	bindBackstabAnimationListener(character)

	local descendantAdded = Signal.new(character.DescendantAdded)
	defenseMaid["Defense_BackstabCharacterDescendantAdded"] = descendantAdded:connect(
		"Defense_BackstabCharacterDescendantAdded",
		function(descendant)
			if not descendant:IsA("Animator") then
				return
			end

			bindBackstabAnimationListener(character)
		end
	)
end

-- Attack effects whose end-lag we strip the instant they apply.
local FAST_SWING_EFFECTS = {
	OffhandAttack = true,
	HeavyAttack = true,
	MediumAttack = true,
	LightAttack = true,
	UsingSpell = true,
}

---Strips weapon end-lag by removing the attack effect as it's added when FastSwing is on.
---@param effect table
local function onFastSwingEffectAdded(effect)
	if not Configuration.expectToggleValue("FastSwing") then
		return
	end
	if not FAST_SWING_EFFECTS[effect.Class] then
		return
	end
	task.defer(function()
		pcall(function()
			effect:Remove(true)
		end)
	end)
end

---Removes any status effect the moment it's added when NoStatusEffects is on.
---@param effect table
local function onNoStatusEffectsEffectAdded(effect)
	if not Configuration.expectToggleValue("NoStatusEffects") then
		return
	end
	task.defer(function()
		pcall(function()
			effect:Remove(true)
		end)
	end)
end

---On backstab effect added.
---@param effect table
local function onBackstabEffectAdded(effect)
	if not Configuration.expectToggleValue("BackstabMovestack") then
		return
	end

	if effect.Class == "backstabDebounce" then
		backstabMovestackReady = true
		task.delay(3, function()
			backstabMovestackReady = false
		end)
	end
end

---On backstab effect removed.
---@param effect table
local function onBackstabEffectRemoved(effect)
	if not Configuration.expectToggleValue("BackstabMovestack") then
		return
	end

	if os.clock() - backstabAnimationTriggerTimestamp <= 1.0 then
		return
	end

	if effect.Class ~= "Action" or not backstabMovestackReady then
		return
	end

	scheduleBackstabMovestackActivation("Defense_BackstabMovestack")
end

---Update auto air counter.
local updateAutoAirCounter = (function()
	if not Configuration.expectToggleValue("AutoAirCounter") then
		return
	end

	-- Rate limit to ~10 checks per second.
	if os.clock() - lastAutoAirCounterUpdate < 0.1 then
		return
	end
	lastAutoAirCounterUpdate = os.clock()

	local localPlayer = players.LocalPlayer
	local character = localPlayer and localPlayer.Character
	if not character then
		return
	end

	local characterHandler = character:FindFirstChild("CharacterHandler")
	local requests = characterHandler and characterHandler:FindFirstChild("Requests")
	local antiAir = requests and requests:FindFirstChild("AntiAir")
	if not antiAir then
		return
	end

	local rootPart = character:FindFirstChild("HumanoidRootPart")
	if not rootPart then
		return
	end

	-- Check if we are in the air (unless on-ground mode is enabled).
	if not Configuration.expectToggleValue("AutoAirCounterOnGround") then
		local isGrounded = false
		local controllerManager = character:FindFirstChild("ControllerManager")
		if controllerManager then
			local groundSensor = controllerManager:FindFirstChild("GroundSensor")
			if groundSensor and groundSensor.SensedPart then
				isGrounded = true
			end
		end

		if not isGrounded then
			local humanoid = character:FindFirstChildWhichIsA("Humanoid")
			if humanoid and humanoid.FloorMaterial ~= Enum.Material.Air then
				isGrounded = true
			end
		end

		if not isGrounded then
			local raycastParams = RaycastParams.new()
			raycastParams.FilterType = Enum.RaycastFilterType.Exclude
			raycastParams.FilterDescendantsInstances = { workspace:FindFirstChild("Live"), workspace:FindFirstChild("NPCs"), workspace:FindFirstChild("Thrown") }
			local hit = workspace:Raycast(rootPart.Position, Vector3.new(0, -4, 0), raycastParams)
			if hit and hit.Instance then
				isGrounded = true
			end
		end

		if isGrounded then
			return -- We're on the ground, skip.
		end
	end

	local live = workspace:FindFirstChild("Live")
	if not live then
		return
	end

	local range = Configuration.expectOptionValue("AutoAirCounterRange") or 60
	local allyCheck = Configuration.expectToggleValue("AutoAirCounterAllyCheck")

	for _, entity in next, live:GetChildren() do
		if entity == character then
			continue
		end

		-- Skip hidden/invalid entities.
		if entity.Name:sub(1, 1) == "." then
			continue
		end

		local entityRoot = entity:FindFirstChild("HumanoidRootPart")
		if not entityRoot then
			continue
		end

		local distance = (entityRoot.Position - rootPart.Position).Magnitude
		if distance > range then
			continue
		end

		-- Ally check: skip players in our party/guild.
		if allyCheck then
			local entityPlayer = players:GetPlayerFromCharacter(entity)
			if entityPlayer then
				local pvpAttribute = entity:GetAttribute("PVPEnabled")
				if pvpAttribute == false or PlayerScanning.isAlly(entityPlayer) then
					continue
				end
			end
		end

		antiAir:FireServer(entity)
	end
end)

---Add animator defender.
---@param animator Animator
local addAnimatorDefender = (function(animator)
	-- An Animator with no Model ancestor (detached / preview / leftover) has no entity to defend.
	if not animator:FindFirstAncestorWhichIsA("Model") then
		return
	end

	local animationDefender = AnimatorDefender.new(animator, mobAnimations)
	defenderObjects[animator] = animationDefender
	defenderAnimationObjects[animator] = animationDefender
end)

---Add sound defender.
---@param sound Sound
local addSoundDefender = (function(sound)
	---@note: If there's nothing to base the sound position off of, then I'm just gonna skip it bruh.
	local part = sound:FindFirstAncestorWhichIsA("BasePart")
	if not part then
		return
	end

	-- Add sound defender.
	defenderObjects[sound] = SoundDefender.new(sound, part)
end)

---On game descendant added.
---@param descendant Instance
local onGameDescendantAdded = (function(descendant)
	if descendant:IsA("Animator") then
		return addAnimatorDefender(descendant)
	end

	if descendant:IsA("Sound") then
		return addSoundDefender(descendant)
	end

	if descendant:IsA("BasePart") then
		return Defense.cdpo(descendant)
	end
end)

---On game descendant removed.
---@param descendant Instance
local onGameDescendantRemoved = (function(descendant)
	local object = defenderObjects[descendant]
	if not object then
		return
	end

	if object.rpbdata then
		deletedPlaybackData[descendant] = object.rpbdata
	end

	if defenderPartObjects[descendant] then
		defenderPartObjects[descendant] = nil
	end

	if defenderAnimationObjects[descendant] then
		defenderAnimationObjects[descendant] = nil
	end

	object:detach()
	-- Remove the detached defender from the live map.
	defenderObjects[descendant] = nil
end)

---On client effect event.
---@param name string?
---@param data table?
local onClientEffectEvent = (function(name, data)
	if not name then
		return
	end

	if not data or typeof(data) ~= "table" then
		data = {}
	end

	-- Park it in the weak-valued table so it's reclaimed the instant its scheduled work is done, instead of leaking into defenderObjects for the rest of the session.
	effectDefenders[data] = EffectDefender.new(name, data)
end)

---Update history.
local updateHistory = (function()
	if os.clock() - lastHistoryUpdate <= 0.1 then
		return
	end

	lastHistoryUpdate = os.clock()

	local character = players.LocalPlayer.Character
	if not character then
		return
	end

	local humanoidRootPart = character:FindFirstChild("HumanoidRootPart")
	if not humanoidRootPart then
		return
	end

	EntityHistory.add(players.LocalPlayer, humanoidRootPart.CFrame, humanoidRootPart.AssemblyLinearVelocity, tick())

	for _, player in next, players:GetPlayers() do
		if player == players.LocalPlayer then
			continue
		end

		local pcharacter = player.Character
		if not pcharacter then
			continue
		end

		local proot = pcharacter:FindFirstChild("HumanoidRootPart")
		if not proot then
			continue
		end

		EntityHistory.add(pcharacter, proot.CFrame, proot.AssemblyLinearVelocity, tick())
	end
end)

-- Auto Golden Tongue only ever says ONE of these single characters, nothing else.
local GOLDEN_TONGUE_MESSAGES = { "a", "s", "d", "w", "f" }
local goldenTongueRandom = Random.new()

---Update golden tongue.
local updateGoldenTongue = (function()
	-- Fire once every 60 seconds (Golden Tongue's real cooldown).
	if os.clock() - lastGoldenTongueUpdate <= 60.0 then
		return
	end

	lastGoldenTongueUpdate = os.clock()

	if not Configuration.expectToggleValue("AutoGoldenTongue") then
		return
	end

	-- No talent-presence or GoldCool cooldown gating -- this fires purely on the 40s clock so it reliably sends.
	if Configuration.expectToggleValue("CheckIfInCombat") then
		local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
		local effectReplicatorModule = effectReplicator and require(effectReplicator)
		if not effectReplicatorModule or not effectReplicatorModule:FindEffect("Combat") then
			return
		end
	end

	-- Send through TextChatService.
	local textChannels = textChatService:FindFirstChild("TextChannels")
	if not textChannels then
		return
	end

	local channel = textChannels:FindFirstChild("RBXGeneral")
	if not channel then
		for _, child in next, textChannels:GetChildren() do
			if child:IsA("TextChannel") and child.Name ~= "RBXSystem" then
				channel = child
				break
			end
		end
	end

	channel = channel or textChannels:FindFirstChild("RBXSystem")
	if not channel then
		return
	end

	-- Say exactly one of a/s/d/w/f and nothing else.
	local message = GOLDEN_TONGUE_MESSAGES[goldenTongueRandom:NextInteger(1, #GOLDEN_TONGUE_MESSAGES)]

	defenseMaid:mark(TaskSpawner.spawn("Defender_GoldenTongueSendAsync", channel.SendAsync, channel, message))
end)

---Update auto ardour.
local updateAutoArdour = (function()
	if os.clock() - lastAutoArdourUpdate <= 1.0 then
		return
	end
	lastAutoArdourUpdate = os.clock()

	if not Configuration.expectToggleValue("AutoArdour") then
		return
	end

	local localPlayer = players.LocalPlayer
	if not localPlayer then
		return
	end

	local backpack = localPlayer:FindFirstChild("Backpack")
	if not backpack or not backpack:FindFirstChild("Talent:Murmur: Ardour") then
		return
	end

	local character = localPlayer.Character
	if not character then
		return
	end

	local success, hasWeapon = pcall(function()
		return workspace.Live[localPlayer.Name].RightHand.HandWeapon ~= nil
	end)

	if not success or not hasWeapon then
		return
	end

	local hasArdour = pcall(function()
		return workspace.Live[localPlayer.Name].RightHand.HandWeapon.ArdourHum
	end)

	if hasArdour then
		return
	end

	local characterHandler = character:FindFirstChild("CharacterHandler")
	local requests = characterHandler and characterHandler:FindFirstChild("Requests")
	local ardourRemote = requests and requests:FindFirstChild("Ardour")

	if ardourRemote then
		pcall(function()
			ardourRemote:FireServer()
		end)
	end
end)

---Toggle visualizations.
Defense.visualizations = (function()
	local transparency = Configuration.expectToggleValue("EnableVisualizations") and 0.2 or 1.0

	for _, collection in next, visualizedDefenderSets do
		for _, object in next, collection do
			for _, hitbox in next, object.hmaid._tasks do
				if typeof(hitbox) ~= "Instance" then
					continue
				end

				hitbox.Transparency = transparency
			end
		end
	end
end)

---Update visualization.
local updateVisualizations = (function()
	if not Configuration.expectToggleValue("EnableVisualizations") then
		return
	end

	if os.clock() - lastVisualizationUpdate <= 5.0 then
		return
	end

	lastVisualizationUpdate = os.clock()

	for _, collection in next, visualizedDefenderSets do
		for _, object in next, collection do
			for idx, hitbox in next, object.hmaid._tasks do
				if typeof(hitbox) ~= "Instance" then
					continue
				end

				---@note: We call :Debris so we don't have to clean it up ourselves. We just unregister it from the maid.
				if hitbox.Parent then
					continue
				end

				object.hmaid._tasks[idx] = nil
			end
		end
	end
end)

---Batch RenderStepped defense work into one callback.
local updateDefenseRenderStepped = (function()
	updateVisualizations()
	updateHistory()
	updateGoldenTongue()
	updateAutoArdour()
end)

---Handle spell string & position.
---@param position number
---@param str string
local hssp = (function(position, str)
	if
		lastAutoWispUpdate
		and os.clock() - lastAutoWispUpdate <= (Configuration.expectOptionValue("AutoWispDelay") or 0)
	then
		return Logger.warn(
			"(%.2f - %.2f = %.2f vs. %.2f) Auto Wisp is on cooldown.",
			os.clock(),
			lastAutoWispUpdate,
			os.clock() - lastAutoWispUpdate,
			Configuration.expectOptionValue("AutoWispDelay") or 0
		)
	end

	if lastAutoWispShift and os.clock() - lastAutoWispShift <= 0.15 then
		return Logger.warn(
			"(%.2f - %.2f = %.2f vs. %.2f) Auto Wisp shift is on forced cooldown.",
			os.clock(),
			lastAutoWispShift,
			os.clock() - lastAutoWispShift,
			0.15
		)
	end

	if autoWispLocked then
		return Logger.warn("Auto Wisp is locked.")
	end

	if position <= 0 or position > #str then
		return Logger.warn("Invalid position (%i vs. %i) for Auto Wisp.", position, #str)
	end

	local character = str:sub(position, position)
	if character ~= "Z" and character ~= "X" and character ~= "C" and character ~= "V" then
		return Logger.warn("Invalid character (%s) for Auto Wisp.", tostring(character))
	end

	local localPlayer = players.LocalPlayer
	local localPlayerCharacter = localPlayer.Character
	if not localPlayerCharacter then
		return
	end

	local mantras = replicatedStorage:FindFirstChild("Requests")
	mantras = mantras and mantras:FindFirstChild("Mantras")
	local spellInput = mantras and mantras:FindFirstChild("RitualSpellInput")
	if not spellInput then
		return
	end

	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return
	end

	if not effectReplicatorModule:HasEffect("RitualCastingSpell") then
		return Logger.warn("RitualCastingSpell effect not found.")
	end

	if effectReplicatorModule:HasEffect("Knocked") then
		return Logger.warn("Knocked effect found.")
	end

	Logger.warn("Sending event for character (%s) with position (%i) and string (%s).", character, position, str)

	autoWispLocked = true
	lastAutoWispUpdate = os.clock()

	spellInput:FireServer(WISP_INPUT_MAP[character] or character)
end)

-- Auto assassination state.
local assassinationBusy = false
local assassinationAutoCrouched = false
local assassinationCrouchAt = 0
local assassinationCooldowns = setmetatable({}, { __mode = "k" })

-- Assassination tuning (looser than Rain's since we don't force shift-lock: behind arc + camera aim + range).
local ASSASSINATION_BACK_OFFSET = 1.5
local ASSASSINATION_MAX_RANGE = 18
local ASSASSINATION_BEHIND_DOT = 0.55
local ASSASSINATION_FACING_DOT = 0.45
local ASSASSINATION_TARGET_COOLDOWN = 1.5


---Resolve the EffectReplicator module, or nil.
local function getEffectReplicator()
	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	return effectReplicator and require(effectReplicator) or nil
end

---Resolve the KeyBinds module (only if it exposes ForceActionDown), or nil.
local function getKeybinds()
	local keybindsModule = replicatedStorage:FindFirstChild("KeyBinds")
	local Keybinds = keybindsModule and require(keybindsModule) or nil
	if not Keybinds or not Keybinds.ForceActionDown then
		return nil
	end
	return Keybinds
end

---Are we currently crouched?
local function isCrouching()
	local effectReplicatorModule = getEffectReplicator()
	return effectReplicatorModule ~= nil and effectReplicatorModule:FindEffect("ClientCrouch") ~= nil
end

---Toggle crouch to the requested state (crouch is a toggle, so only tap when it actually differs).
---@param wantCrouch boolean
local function setCrouch(wantCrouch)
	if isCrouching() == wantCrouch then
		return
	end
	local Keybinds = getKeybinds()
	if not Keybinds then
		return
	end
	Keybinds.ForceActionDown("Crouch")
	Keybinds.ForceActionUp("Crouch")
end

---Is this target inside the assassination arc: behind them, in range, with us and the camera facing them?
---@param localRoot BasePart
---@param targetRoot BasePart
---@return boolean
local function isValidAssassinationTarget(localRoot, targetRoot)
	local back = -targetRoot.CFrame.LookVector
	local distance = (localRoot.Position - (targetRoot.Position + back * ASSASSINATION_BACK_OFFSET)).Magnitude
	if distance > ASSASSINATION_MAX_RANGE or distance < 0.01 then
		return false
	end

	local targetToLocal = localRoot.Position - targetRoot.Position
	if targetToLocal.Magnitude < 0.01 then
		return false
	end
	-- We must be inside the target's back arc.
	if back:Dot(targetToLocal.Unit) < ASSASSINATION_BEHIND_DOT then
		return false
	end

	local localToTarget = targetRoot.Position - localRoot.Position
	if localToTarget.Magnitude < 0.01 then
		return false
	end

	-- Camera has to be roughly looking at the target (character facing is skipped: when crouched the root often doesn't match camera aim).
	local camera = workspace.CurrentCamera
	if camera and camera.CFrame.LookVector:Dot(localToTarget.Unit) < ASSASSINATION_FACING_DOT then
		return false
	end

	return true
end

-- Workspace folders that hold assassinatable characters: players/mobs live under Live, NPCs under NPCs.
local ASSASSINATION_TARGET_FOLDERS = { "Live", "NPCs" }

---Pick the closest valid target across the character folders, or nil -- returning nil is what stops it swinging at nothing.
---@param localCharacter Model
---@param localRoot BasePart
---@return BasePart|nil, string|nil
local function findAssassinationTarget(localCharacter, localRoot)
	local now = os.clock()
	local best = nil
	local bestName = nil
	local bestDistance = math.huge

	for _, folderName in ipairs(ASSASSINATION_TARGET_FOLDERS) do
		local folder = workspace:FindFirstChild(folderName)
		if not folder then
			continue
		end

		for _, entity in next, folder:GetChildren() do
			if entity == localCharacter or not entity:IsA("Model") then
				continue
			end

			local cooldown = assassinationCooldowns[entity]
			if cooldown and now < cooldown then
				continue
			end

			local humanoid = entity:FindFirstChildWhichIsA("Humanoid")
			local targetRoot = entity:FindFirstChild("HumanoidRootPart")
			if humanoid and targetRoot and humanoid.Health > 0 and isValidAssassinationTarget(localRoot, targetRoot) then
				local distance = (localRoot.Position - targetRoot.Position).Magnitude
				if distance < bestDistance then
					best = targetRoot
					bestName = entity
					bestDistance = distance
				end
			end
		end
	end

	return best, bestName
end

--- Auto assassination: only strikes when a real target sits in the back arc, auto-crouching for it -- so holding the bind while just standing never swings.
local function updateAutoAssassination()
	if not Configuration.expectToggleValue("AutoAssassination") then
		if assassinationDebugPart then
			assassinationDebugPart:Destroy()
			assassinationDebugPart = nil
		end
		if assassinationAutoCrouched then
			setCrouch(false)
			assassinationAutoCrouched = false
		end
		return
	end
	local character = localPlayer.Character
	local root = character and character:FindFirstChild("HumanoidRootPart")
	if Configuration.expectToggleValue("AutoAssassinationDebug") and root then
		if not assassinationDebugPart then
			local part = Instance.new("Part")
			part.Name = "MiraAssassinationHitbox"
			part.Anchored = true
			part.CanCollide = false
			part.CanQuery = false
			part.CanTouch = false
			part.Transparency = 0.65
			part.Color = Color3.fromRGB(255, 45, 45)
			part.Material = Enum.Material.ForceField
			part.Size = Vector3.new(6, 6, 9)
			part.Parent = workspace
			assassinationDebugPart = part
		end
		assassinationDebugPart.CFrame = root.CFrame * CFrame.new(0, -1.5, -5.5)
	elseif assassinationDebugPart then
		assassinationDebugPart:Destroy()
		assassinationDebugPart = nil
	end

	local keybind = Options and Options.AutoAssassinationKeybind
	local held = keybind ~= nil and keybind:GetState()

	-- Bind released (or no character): drop any crouch we applied and stop.
	if not held or not root then
		if assassinationAutoCrouched then
			setCrouch(false)
			assassinationAutoCrouched = false
		end
		return
	end

	-- Hold the bind = stay crouched (sneaking). If we're not crouched yet, tap crouch and wait for it to register before striking.
	if not isCrouching() then
		if not assassinationAutoCrouched or (os.clock() - assassinationCrouchAt) > 0.4 then
			local Keybinds = getKeybinds()
			if Keybinds then
				Keybinds.ForceActionDown("Crouch")
				Keybinds.ForceActionUp("Crouch")
			end
			assassinationAutoCrouched = true
			assassinationCrouchAt = os.clock()
		end
		return
	end

	-- A strike is already resolving; let it finish.
	if assassinationBusy then
		return
	end

	-- Crouched and ready. No valid target -> stay crouched, just don't swing.
	local target, targetEntity = findAssassinationTarget(character, root)
	if not target then
		return
	end

	-- Fire the assassination off the tick; we're already crouched so it lands as a stealth kill, not a normal M1.
	assassinationBusy = true
	assassinationCooldowns[targetEntity] = os.clock() + ASSASSINATION_TARGET_COOLDOWN
	TaskSpawner.spawn("Defense_AutoAssassinationStrike", function()
		pcall(function()
			InputClient.left(CFrame.new(target.Position), true)
		end)
		assassinationBusy = false
	end)
end

---Is the attacker close enough that its timing is actually a threat right now?
---@param object Defender
---@param timing Timing
---@return boolean
local function isThreatImminent(object, timing)
	local entity = object.entity
	if not entity then
		return true
	end

	if not entity:FindFirstChild("HumanoidRootPart") then
		return true
	end

	local distance = object:distance(entity)
	if not distance then
		return true
	end

	return distance <= (timing.imxd or math.huge)
end

--- Rebuild the cached Block Input state.
Defense.updateBlockInputState = (function()
	if
		not Configuration.expectToggleValue("EnableAutoDefense")
		or not Configuration.expectToggleValue("BlockInput")
	then
		blockInputActive = {}
		return
	end

	local allowedTargets = Configuration.expectOptionValue("BlockInputAllowedTargets") or {
		PVE = true,
		PVP = true,
	}

	local punishTime = (Configuration.expectOptionValue("BlockInputPunishmentTime") or 0) / 1000
	local halfPing = Latency.rdelay()

	local active = {}

	for object in next, Defender.armed do
		-- NOTE: deliberately NOT gated on object:blocking -- that gate only opens inside each task's own punishable window, which capped the Punishment Time slider.
		local timing = object.timing
		if timing and timing.ibi then
			continue
		end

		local ownerModel = object.entity or object.owner
		if not ownerModel and object.part then
			ownerModel = object.part:FindFirstAncestorWhichIsA("Model")
		end

		local isPvp = ownerModel and players:GetPlayerFromCharacter(ownerModel) ~= nil
		if isPvp and not allowedTargets.PVP then
			continue
		end

		if not isPvp and not allowedTargets.PVE then
			continue
		end

		if timing and not isThreatImminent(object, timing) then
			continue
		end

		for _, tsk in next, object.tasks do
			-- Skip finished tasks.
			if coroutine.status(tsk.thread) == "dead" then
				continue
			end

			local when = tsk:when()

			-- One global punishment lead: block M1 / Mantra / Critical together from `punishTime` (+ ping) before the hit through the task's after-window.
			if os.clock() >= when - punishTime - halfPing and os.clock() <= when + tsk.after then
				active.M1s = true
				active.Criticals = true
				active.Mantras = true
			end
		end
	end

	blockInputActive = active
end)

---@note: Cheap read only (booleans + option table) so it is safe to call from input hooks.
---@param moveType string
---@return boolean
Defense.shouldBlockInput = (function(moveType)
	local blockedMoves = Configuration.expectOptionValue("BlockedSafeInputUserMoves") or {}
	return blockedMoves[moveType] == true and blockInputActive[moveType] == true
end)

---Update defenders.
local updateDefenders = (function()
	Defense.updateBlockInputState()

	if Configuration.expectToggleValue("M1Hold") and leftClickState and not Defense.shouldBlockInput("M1s") then
		InputClient.left(players.LocalPlayer:GetMouse().Hit, true)
	end

	updateAutoAssassination()

	if Configuration.expectToggleValue("AutoWisp") and cwp and cws then
		hssp(cwp, cws)
	end

	-- Animation defenders always tick, even with Auto Defense off.
	for _, object in next, defenderAnimationObjects do
		object:update()
	end

	if not Configuration.expectToggleValue("EnableAutoDefense") then
		return
	end

	for _, object in next, defenderPartObjects do
		object:update()
	end
end)

-- Slide cast mantras. 
local lastMantraSlideActivatedAt = 0.0
local lastMantraActivatedTool = nil
local lastMantraActivatedAt = 0.0

--- Is a mantra allowed by a multi-dropdown option list?
---@param mantra Tool
---@param optionKey string
---@return boolean
local function isMantraAllowed(mantra, optionKey)
	local selectedMantras = Configuration.expectOptionValue(optionKey)
	if type(selectedMantras) ~= "table" then
		return true
	end

	local isEmpty = true
	for _, v in pairs(selectedMantras) do
		if v then
			isEmpty = false
			break
		end
	end

	if isEmpty then
		return false
	end

	local defaultName = mantra and mantra.GetAttribute and mantra:GetAttribute("DefaultName")
	if not defaultName then
		return false
	end

	return selectedMantras[defaultName] == true
end

---Attempt to roll cast a just-activated mantra.
---@param mantra Tool
local function attemptRollCast(mantra)
	if not isMantraAllowed(mantra, "RollCastMantrasList") then
		return
	end

	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	local effectReplicatorModule = effectReplicator and require(effectReplicator)
	if not effectReplicatorModule then
		return
	end

	if effectReplicatorModule:HasAny(
		"AirCombo",
		"NoSlide",
		"Action",
		"MobileAction",
		"UsingAbility",
		"LightAttack",
		"Blocking",
		"Parried",
		"ClientSlide2",
		"ClientSwim"
	) then
		return
	end

	local keybindsModule = replicatedStorage:FindFirstChild("KeyBinds")
	if not keybindsModule then
		return
	end

	local Keybinds = require(keybindsModule)
	if not Keybinds or not Keybinds.ForceActionDown then
		return
	end

	Keybinds.ForceActionDown("Dodge")
	Keybinds.ForceActionUp("Dodge")

	task.delay(0.09, function()
		local clientFeint = effectReplicatorModule:CreateEffect("ClientFeint")
		if clientFeint then
			clientFeint:Debris(0.1)
		end
	end)
end

---Attempt to slide cast a just-activated mantra.
---@param mantra Tool
local function attemptSlideCast(mantra)
	if not isMantraAllowed(mantra, "SlideCastMantrasList") then
		return
	end

	local localPlayer = players.LocalPlayer
	local character = localPlayer and localPlayer.Character
	if not character then
		return
	end

	local ether = character:FindFirstChild("Ether")
	local spellCost = mantra and mantra:GetAttribute("SpellCost")
	if not ether or not spellCost or ether.Value <= spellCost then
		return
	end

	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	local effectReplicatorModule = effectReplicator and require(effectReplicator)
	if not effectReplicatorModule then
		return
	end

	if effectReplicatorModule:HasAny(
		"AirCombo",
		"NoSlide",
		"Action",
		"MobileAction",
		"UsingAbility",
		"LightAttack",
		"Blocking",
		"Parried",
		"ClientSlide2",
		"ClientSwim"
	) then
		return
	end

	local humanoid = character:FindFirstChildWhichIsA("Humanoid")
	if not humanoid then
		return
	end

	local moveDirection = humanoid.MoveDirection
	if moveDirection.Magnitude <= 0.1 then
		return
	end

	local rootPart = character:FindFirstChild("HumanoidRootPart")
	if not rootPart then
		return
	end

	local hitPart = workspace:FindPartOnRayWithIgnoreList(
		Ray.new(rootPart.Position, Vector3.new(0, -10, 0)),
		{ workspace:FindFirstChild("Live"), workspace:FindFirstChild("NPCs"), workspace:FindFirstChild("Thrown") }
	)

	if not hitPart then
		return
	end

	if not effectReplicatorModule:FindEffect("Sprinting") then
		return
	end

	local keybindsModule = replicatedStorage:FindFirstChild("KeyBinds")
	if not keybindsModule then
		return
	end

	local Keybinds = require(keybindsModule)
	if not Keybinds or not Keybinds.ForceActionDown then
		return
	end

	-- Slide cooldown: minimum time since the last actual slide cast.
	local slideCooldown = Configuration.expectOptionValue("ActionSlideCooldown") or 0
	if slideCooldown > 0 and (os.clock() - lastMantraSlideActivatedAt) < slideCooldown then
		return
	end

	-- Slide chance: percent chance an otherwise-eligible slide actually fires.
	local slideChance = Configuration.expectOptionValue("ActionSlideChance") or 100
	if slideChance <= 0 or math.random(1, 100) > slideChance then
		return
	end

	if not effectReplicatorModule:FindEffect("CastingSpell") then
		local castingSpell = effectReplicatorModule:CreateEffect("CastingSpell")
		if castingSpell then
			castingSpell:Debris(0.05)
		end
	end

	lastMantraSlideActivatedAt = os.clock()

	Keybinds.ForceActionDown("Crouch")
	Keybinds.ForceActionUp("Crouch")
end

---Poll for newly-activated mantras and route them to slide cast.
local function updateMantraRequests()
	local mantra = StateListener.lMantraActivated
	if not mantra then
		return
	end

	-- Compare the hook-set timestamp to detect genuinely new activations.
	local activatedAt = StateListener.lMantraActivatedAt
	if activatedAt == lastMantraActivatedAt then
		return
	end

	lastMantraActivatedTool = mantra
	lastMantraActivatedAt = activatedAt

	if Configuration.expectToggleValue("RollCastMantras") then
		attemptRollCast(mantra)
	end

	if Configuration.expectToggleValue("SlideCastMantras") then
		attemptSlideCast(mantra)
	end
end

---Batch PostSimulation defense work into one callback.
local updateDefensePostSimulation = (function()
	updateDefenders()
	updateAutoAirCounter()
	updateMantraRequests()
end)
---Create a defender part object.
---@param part BasePart
---@param timing PartTiming?
---@return PartDefender?
Defense.cdpo = (function(part, timing)
	-- This came from a module and we specified it in the parameters, meaning this is custom.
	if timing and (timing.cbm or timing.umoa) then
		timing["imxd"] = (timing["imxd"])
		timing["imdd"] = (timing["imdd"])
		timing["hitbox"] = Vector3.new(
			(timing["hitbox"].X),
			(timing["hitbox"].Y),
			(timing["hitbox"].Z)
		)
	end

	local partDefender = PartDefender.new(part, timing)
	if not partDefender then
		return nil
	end

	defenderObjects[part] = partDefender
	defenderPartObjects[part] = partDefender

	return partDefender
end)

---Return the defender animation object for an entity.
---@param entity Instance
---@return AnimatorDefender?
Defense.dao = (function(entity)
	for _, object in next, defenderAnimationObjects do
		if object.entity ~= entity then
			continue
		end

		return object
	end
end)

---Get playback data of first defender with Animation ID.
---@param aid string
---@return PlaybackData?
Defense.agpd = (function(aid)
	---@note: Grabbing from 'rpbdata' means that we know that the data has been fully recorded.
	for _, object in next, defenderAnimationObjects do
		local pbdata = object.rpbdata[aid]
		if not pbdata then
			continue
		end

		return pbdata
	end

	---@note: Fallback to deleted playback data if that doesn't exist.
	for _, rpbdata in next, deletedPlaybackData do
		local pbdata = rpbdata[aid]
		if not pbdata then
			continue
		end

		return pbdata
	end
end)

---On spell event.
---@param name string
---@param data any?
local onSpellEvent = (function(name, data)
	-- Close.
	if name == "close" then
		cws = nil
		cwp = nil
		lastAutoWispUpdate = nil
		lastAutoWispShift = nil
		autoWispLocked = false
	end

	-- Set the current position & string.
	if name == "start" then
		cws = data
		cwp = 1
		lastAutoWispUpdate = os.clock()
		lastAutoWispShift = nil
		autoWispLocked = false
	end

	-- Shift our position if we were successful.
	if cws and cwp and name == "shift" then
		cwp = cwp + 1
		lastAutoWispShift = os.clock()
		autoWispLocked = false
	end
end)

---Feint flourish.
function Defense.fflourish()
	if not Configuration.expectToggleValue("FeintFlourish") then
		return
	end

	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return Logger.warn("EffectReplicator not found for FeintFlourish.")
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return Logger.warn("EffectReplicator module not found for FeintFlourish.")
	end

	if not effectReplicatorModule:FindEffect("MidAttack") then
		return Logger.warn("Not MidAttack effect for FeintFlourish.")
	end

	local mantra = Finder.ncdm()
	if not mantra then
		return Logger.warn("No mantra found for FeintFlourish.")
	end

	if effectReplicatorModule:FindEffect("FeintCool") then
		return Logger.warn("No avaliable feint for FeintFlourish.")
	end

	local lastAnimationTiming = StateListener.lAnimTiming
	if not lastAnimationTiming then
		return Logger.warn("No last animation timing found for FeintFlourish.")
	end

	if not lastAnimationTiming.smod:match("Flourish") then
		return Logger.warn("Last animation is not a flourish for FeintFlourish.")
	end

	-- Activate mantra.
	Logger.warn("(%s) FeintFlourish activated mantra.", mantra.Name)

	InputClient.amantra(mantra)

	-- Wait.
	task.wait(0.1)

	-- Feint mantra.
	Logger.warn("(%s) FeintFlourish feinted mantra.", mantra.Name)

	InputClient.feint()
end

---Initialize defense.
function Defense.init()
	-- Cache mob animations.
	local assetFolder = replicatedStorage:WaitForChild("Assets")
	local animationFolder = assetFolder:WaitForChild("Anims")
	local mobsAnimationFolder = animationFolder:WaitForChild("Mobs")

	for _, animation in next, mobsAnimationFolder:QueryDescendants("Animation") do
		if animation.Name == "RunningAttack" then
			continue
		end

		mobAnimations[animation.AnimationId] = animation
	end

	-- Requests.
	local requests = replicatedStorage:WaitForChild("Requests")
	local clientEffect = requests:WaitForChild("ClientEffect")
	local clientEffectLarge = requests:WaitForChild("ClientEffectLarge")
	local clientEffectDirect = requests:WaitForChild("ClientEffectDirect")
	local spell = requests:WaitForChild("Mantras"):WaitForChild("RitualSpellInput")

	-- Signals.
	local gameDescendantAdded = Signal.new(game.DescendantAdded)
	local gameDescendantRemoved = Signal.new(game.DescendantRemoving)
	local inputBegan = Signal.new(userInputService.InputBegan)
	local inputEnded = Signal.new(userInputService.InputEnded)
	local renderStepped = Signal.new(runService.RenderStepped)
	local postSimulation = Signal.new(runService.PostSimulation)
	local clientEffectEvent = Signal.new(clientEffect.OnClientEvent)
	local clientEffectLargeEvent = Signal.new(clientEffectLarge.OnClientEvent)
	local cientEffectDirect = Signal.new(clientEffectDirect.Event)
	local spellEvent = Signal.new(spell.OnClientEvent)

	-- EffectReplicator signals for backstab movestack.
	local localPlayer = players.LocalPlayer
	local characterAdded = Signal.new(localPlayer.CharacterAdded)
	local effectReplicator = replicatedStorage:WaitForChild("EffectReplicator")
	local effectReplicatorModule = require(effectReplicator)
	local effectAddedSignal = Signal.new(effectReplicatorModule.EffectAdded)
	local effectRemovedSignal = Signal.new(effectReplicatorModule.EffectRemoved)

	---@note: Need this to detect UI presses / game processed inputs.
	defenseMaid:mark(inputBegan:connect("Defense_OnInputBegan", function(input, gameProcessed)
		if gameProcessed then
			return
		end

		if input.UserInputType == Enum.UserInputType.MouseButton2 then
			TaskSpawner.delay("StateListener_FeintFlourish", function()
				return 0.07
			end, Defense.fflourish)
		end

		if input.UserInputType ~= Enum.UserInputType.MouseButton1 then
			return
		end

		-- Easy Mantra Feint / Easy Roll Cancel.
		do
			local character = localPlayer.Character
			local root = character and character:FindFirstChild("HumanoidRootPart")
			-- Debounce + feint-cooldown gate: a rapid second M1 must fall through to a normal attack, never re-feint (which would feint the M1 we just threw).
			if root and (os.clock() - lastEasyFeint) > 0.3 and StateListener.cfeint() then
				if
					Configuration.expectToggleValue("EasyMantraFeint")
					and (effectReplicatorModule:HasEffect("UsingSpell") or effectReplicatorModule:HasEffect("CastingSpell"))
				then
					lastEasyFeint = os.clock()
					task.spawn(function()
						-- Same feint path the autoparry uses (InputClient.feint fires the real FeintClick/FeintRelease remotes).
						InputClient.feint()
						task.wait()
						InputClient.left(root.CFrame, true)
					end)
				elseif
					Configuration.expectToggleValue("EasyRollCancel")
					and (effectReplicatorModule:HasEffect("Dodge") or effectReplicatorModule:HasEffect("ClientDodge"))
				then
					lastEasyFeint = os.clock()
					task.spawn(function()
						-- Same feint path the autoparry uses; InputClient.feint cancels an active dodge (creates ClientFeint over ClientDodge), then throw the M1.
						InputClient.feint()
						task.wait()
						InputClient.left(root.CFrame, true)
					end)
				end
			end
		end

		leftClickState = true
	end))

	defenseMaid:mark(inputEnded:connect("Defense_OnInputEnded", function(input, _)
		if input.UserInputType ~= Enum.UserInputType.MouseButton1 then
			return
		end

		leftClickState = false
	end))

	defenseMaid:mark(gameDescendantAdded:connect("Defense_OnDescendantAdded", onGameDescendantAdded))
	defenseMaid:mark(gameDescendantRemoved:connect("Defense_OnDescendantRemoved", onGameDescendantRemoved))
	defenseMaid:mark(renderStepped:connect("Defense_UpdateRenderStepped", updateDefenseRenderStepped))
	defenseMaid:mark(postSimulation:connect("Defense_UpdatePostSimulation", updateDefensePostSimulation))
	defenseMaid:mark(clientEffectEvent:connect("Defense_ClientEffectEvent", onClientEffectEvent))
	defenseMaid:mark(clientEffectLargeEvent:connect("Defense_ClientEffectEventLarge", onClientEffectEvent))
	defenseMaid:mark(cientEffectDirect:connect("Defense_ClientEffectEventDirect", onClientEffectEvent))
	defenseMaid:mark(spellEvent:connect("Defense_SpellEvent", onSpellEvent))
	defenseMaid:mark(characterAdded:connect("Defense_BackstabCharacterAdded", onBackstabCharacterAdded))
	defenseMaid:mark(effectAddedSignal:connect("Defense_BackstabEffectAdded", onBackstabEffectAdded))
	defenseMaid:mark(effectAddedSignal:connect("Defense_FastSwingEffectAdded", onFastSwingEffectAdded))
	defenseMaid:mark(effectAddedSignal:connect("Defense_NoStatusEffectsEffectAdded", onNoStatusEffectsEffectAdded))
	defenseMaid:mark(effectRemovedSignal:connect("Defense_BackstabEffectRemoved", onBackstabEffectRemoved))

	onBackstabCharacterAdded(localPlayer.Character)

	local workspace = game:GetService("Workspace")

	local function scanRoot(root)
		if not root then
			return
		end

		for _, descendant in next, root:GetDescendants() do
			onGameDescendantAdded(descendant)
		end
	end

	-- Combat-critical folders first so defenders are ready immediately.
	scanRoot(workspace:FindFirstChild("Live"))
	scanRoot(workspace:FindFirstChild("NPCs"))
	scanRoot(workspace:FindFirstChild("Thrown"))

	-- Defer the full-world scan so init doesn't freeze a frame.
	task.spawn(function()
		local count = 0
		for _, descendant in next, game:GetDescendants() do
			if defenderObjects[descendant] then
				continue
			end

			onGameDescendantAdded(descendant)
			count = count + 1

			if count % 500 == 0 then
				task.wait()
			end
		end
	end)

	-- Log.
	Logger.warn("Defense initialized.")
end

---Detach defense.
function Defense.detach()
	for _, object in next, defenderObjects do
		object:detach()
	end

	-- Effect defenders live in their own weak table; detach any still in flight so their pending parry tasks are cancelled instead of firing ghost inputs after unload.
	for _, object in next, effectDefenders do
		object:detach()
	end

	table.clear(defenderObjects)
	table.clear(defenderPartObjects)
	table.clear(defenderAnimationObjects)
	table.clear(effectDefenders)
	table.clear(deletedPlaybackData)
	if assassinationDebugPart then
		assassinationDebugPart:Destroy()
		assassinationDebugPart = nil
	end

	-- Leave the character standing: undo any crouch the assassination applied before unloading.
	if assassinationAutoCrouched then
		setCrouch(false)
		assassinationAutoCrouched = false
	end
	assassinationBusy = false

	defenseMaid:clean()

	Logger.warn("Defense detached.")
end

-- Return Defense module.
return Defense
end)
__bundle_register("Features/Combat/Objects/Defender", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

-- One shared RNG for all failure/dash/feint rolls.
local rngShared = Random.new()

---@module Game.InputClient
local InputClient = require("Game/InputClient")

---@module Features.Combat.Objects.Task
local Task = require("Features/Combat/Objects/Task")

---@module Game.QueuedBlocking
local QueuedBlocking = require("Game/QueuedBlocking")

---@module Game.KeyHandling
local KeyHandling = require("Game/KeyHandling")

---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Game.Timings.ModuleManager
local ModuleManager = require("Game/Timings/ModuleManager")

---@module Utility.TaskSpawner
local TaskSpawner = require("Utility/TaskSpawner")

---@module Features.Combat.Targeting
local Targeting = require("Features/Combat/Targeting")

---@module Features.Combat.Objects.ValidationOptions
local ValidationOptions = require("Features/Combat/Objects/ValidationOptions")

---@module Features.Combat.EntityHistory
local EntityHistory = require("Features/Combat/EntityHistory")

---@module Features.Combat.Objects.HitboxOptions
local HitboxOptions = require("Features/Combat/Objects/HitboxOptions")

---@module Utility.OriginalStore
local OriginalStore = require("Utility/OriginalStore")

---@module Features.Combat.StateListener
local StateListener = require("Features/Combat/StateListener")

---@module Utility.Finder
local Finder = require("Utility/Finder")

---@module Game.Latency
local Latency = require("Game/Latency")

---@module GUI.Library
local Library = require("GUI/Library")

---@class Defender
---@field tasks Task[]
---@field tmaid Maid Cleaned up every clean cycle.
---@field rhook table<string, function> Hooked functions that we can restore on clean-up.
---@field markers table<string, boolean> Blocking markers for unknown length timings. If the entry exists and is true, then we're blocking.
---@field maid Maid
---@field hmaid Maid Maid for hitbox visualizations.
---@field uids number Unique ID counter for hitbox visualizations.
---@field afeinted boolean Whether if we have auto-feinted this defense cycle.
---@field ifeinted boolean Whether if we have initial auto-feinted this defense cycle.
local Defender = {}
Defender.__index = Defender
Defender.__type = "Defender"

-- Services.
local replicatedStorage = game:GetService("ReplicatedStorage")
local userInputService = game:GetService("UserInputService")
local players = game:GetService("Players")
local textChatService = game:GetService("TextChatService")
local debrisService = game:GetService("Debris")
local virtualInputManager = game:GetService("VirtualInputManager")

-- Constants.
local MAX_VISUALIZATION_TIME = 5.0
local MAX_REPEAT_WAIT = 10.0
local PREDICTION_LENIENCY_MULTI = 10.0

-- Unbidden's Critical cooldown (8s, 6s after a successful counter).
local UNBIDDEN_COOLDOWN = 8.0
local lastUnbiddenFire = 0

-- Counter windups.
local COUNTER_LEAD_DEFAULT = {
	Prediction = 0.200,
	Unbidden = 0.200,
	IllusoryCounter = 0.200,
	Punishment = 0.300,
	Equalizer = 0.500,
}

local COUNTER_LEAD_OPTION = {
	Prediction = "PredictionLeadTime",
	Unbidden = "UnbiddenLeadTime",
	IllusoryCounter = "IllusoryCounterLeadTime",
	Punishment = "PunishmentLeadTime",
	Equalizer = "EqualizerLeadTime",
}

--- Configured lead time for a counter, in seconds.
---@param counter string
---@return number
local function counterLead(counter)
	local value = Configuration.expectOptionValue(COUNTER_LEAD_OPTION[counter])
	if type(value) ~= "number" then
		value = COUNTER_LEAD_DEFAULT[counter]
	end
	return math.max(0, value)
end

---@module Game.Objects.DodgeOptions
local DodgeOptions = require("Game/Objects/DodgeOptions")

---Log a miss to the UI library with distance check.
---@param type string
---@param key string
---@param name string?
---@param distance number
---@param parent string? If provided, will be shown in the log.
---@return boolean
function Defender:miss(type, key, name, distance, parent)
	if not Configuration.expectToggleValue("ShowLoggerWindow") then
		return false
	end

	local minDistance = Configuration.expectOptionValue("MinimumLoggerDistance") or 0
	local maxDistance = Configuration.expectOptionValue("MaximumLoggerDistance") or 0

	-- Anything closer than the minimum is filtered.
	if distance < minDistance then
		return false
	end

	if maxDistance > 0 and distance > maxDistance then
		return false
	end

	Library:AddMissEntry(type, key, name, distance, parent)

	return true
end

-- Weak set of defenders that currently have at least one armed task.
Defender.armed = setmetatable({}, { __mode = "k" })

---Fetch distance.
---@param from Model? | BasePart?
---@return number?
Defender.distance = (function(_, from)
	if not from then
		return
	end

	local entRootPart = from

	if from:IsA("Model") then
		entRootPart = from:FindFirstChild("HumanoidRootPart")
	end

	if not entRootPart then
		return
	end

	local localCharacter = players.LocalPlayer.Character
	if not localCharacter then
		return
	end

	local localRootPart = localCharacter:FindFirstChild("HumanoidRootPart")
	if not localRootPart then
		return
	end

	return (entRootPart.Position - localRootPart.Position).Magnitude
end)

---Is the attacker behind the local player?
---@param self Defender
---@return boolean
Defender.behind = (function(self)
	local entity = self.entity
	if not entity then
		return false
	end

	local entityRoot = entity:FindFirstChild("HumanoidRootPart")
	if not entityRoot then
		return false
	end

	local localCharacter = players.LocalPlayer.Character
	local localRootPart = localCharacter and localCharacter:FindFirstChild("HumanoidRootPart")
	if not localRootPart then
		return false
	end

	return (entityRoot.Position - localRootPart.Position):Dot(localRootPart.CFrame.LookVector) < 0
end)

---Find target - hookable function.
---@param self Defender
---@param entity Model
---@return Target?
Defender.target = (function(self, entity)
	return Targeting.find(entity)
end)

---Get extrapolated seconds.
---@param self Defender
---@param timing AnimationTiming
---@return number
Defender.fsecs = (function(self, timing)
	local player = players:GetPlayerFromCharacter(self.entity)
	local sd = (player and player:GetAttribute("AveragePing") or 50.0) / 2000
	return (timing.pfht or 0.15) + (sd + Latency.rdelay())
end)

---Start repeat until parry end.
---@param self Defender
---@param ref Model|Part
---@param timing Timing
---@param info RepeatInfo
Defender.srpue = (function(self, ref, timing, info)
	if timing.umoa or timing.cbm then
		timing["_rpd"] = (timing["_rpd"])
		timing["_rsd"] = (timing["_rsd"])
		timing["imdd"] = (timing["imdd"])
		timing["imxd"] = (timing["imxd"])
	end

	local cache = {
		["name"] = timing.name,
		["imdd"] = (timing.imdd),
		["imxd"] = (timing.imxd),
		["rsd"] = timing:rsd(),
		["rpd"] = timing:rpd(),
	}

	local target = self:target(ref)
	local part = target and target.root or CFrame.new()

	if ref:IsA("Part") then
		part = ref
	end

	local options = HitboxOptions.new(part, timing)
	options.spredict = not timing.duih
	options.ptime = self:fsecs(timing)
	options.entity = ref:IsA("Model") and target or nil
	options.hmid = info.hmid
	options:ucache()

	-- Start RPUE.
	self:mark(Task.new(string.format("RPUE_%s_%i", timing.name, 0), function()
		return cache["rsd"] - info.irdelay - Latency.sdelay()
	end, timing.punishable, timing.after, self.rpue, self, ref, timing, info, cache, options))

	-- Notify.
	if not LRM_UserNote or LRM_UserNote == "tester" then
		self:notify(
			timing,
			"Added RPUE '%s' (%.2fs, then every %.2fs) with ping '%.2f' (changing) subtracted.",
			cache["name"],
			cache["rsd"],
			cache["rpd"],
			Latency.rtt()
		)
	else
		self:notify(
			timing,
			"Added RPUE '%s' ([redacted], then every [redacted]) with ping '%.2f' (changing) subtracted.",
			cache["name"],
			Latency.rtt()
		)
	end
end)

---Repeat until parry end.
---@param self Defender
---@param ref Model|Part
---@param timing Timing
---@param info RepeatInfo
---@param cache table Cache table for RPUE to prevent unnecessary recalculations.
---@param options HitboxOptions
Defender.rpue = (function(self, ref, timing, info, cache, options)
	local distance = self:distance(ref)
	if not distance then
		return Logger.warn("Stopping RPUE '%s' because the distance is not valid.", cache.name)
	end

	if not self:rc(info) then
		return Logger.warn("Stopping RPUE '%s' because the repeat condition is not valid.", cache.name)
	end

	local target = ref:IsA("Model") and self:target(ref) or true
	local success = false
	local reasons = {}

	options.part = ref:IsA("Part") and ref or (target and target.root)
	options.cframe = not options.part and CFrame.new()

	if timing.duih and target then
		success = self:hc(options, info)
		reasons[#reasons + 1] = string.format("hitbox (%s)", tostring(options:hitbox()))
	end

	local within = (distance >= cache.imdd and distance <= cache.imxd)

	if timing then
		success = within
	end

	if not within then
		reasons[#reasons + 1] = string.format("distance range (%.2f < %.2f > %.2f)", cache.imdd, distance, cache.imxd)
	end

	info.index = info.index + 1

	self:mark(Task.new(string.format("RPUE_%s_%i", timing.name, info.index), function()
		return cache.rpd - info.irdelay - Latency.sdelay()
	end, timing.punishable, timing.after, self.rpue, self, ref, timing, info, cache, options))

	if not target then
		return Logger.warn("Skipping RPUE '%s' because the target is not valid.", cache.name)
	end

	if not success then
		return Logger.warn("Skipping RPUE '%s' (%s)", cache.name, #reasons > 1 and table.concat(reasons, ", ") or "N/A")
	end

	self:notify(timing, "Action type 'RPUE Parry' is being executed.")

	self:parry(timing, nil)
end)

--- Check if we're in a valid state to proceed with action handling.
---@param self Defender
---@param options ValidationOptions
---@return boolean
Defender.valid = (function(self, options)
	local integer = rngShared:NextNumber(1.0, 100.0)
	local rate = Configuration.expectOptionValue("FailureRate") or 0.0
	local timing = options.timing

	local function internalNotifyFunction(...)
		if not options.notify then
			return
		end

		return self:notify(...)
	end

	local overrideData = Library:GetOverrideData(timing.name)

	-- On the Timing Override List => fully ignore this move (never parry/dash).
	if overrideData then
		return internalNotifyFunction(timing, "Timing '%s' is on the override list - not defending.", timing.name)
	end

	if Configuration.expectToggleValue("AllowFailure") and integer <= rate then
		return internalNotifyFunction(timing, "(%i <= %i) Intentionally did not run.", integer, rate)
	end

	local selectedFilters = Configuration.expectOptionValue("AutoDefenseFilters") or {}

	if selectedFilters["Disable While Holding Block"] and StateListener.hblock() then
		return internalNotifyFunction(timing, "User is pressing down on a key binded to Block.")
	end

	local chatInputBarConfiguration = textChatService:FindFirstChildOfClass("ChatInputBarConfiguration")

	if
		selectedFilters["Disable When Textbox Focused"]
		and (userInputService:GetFocusedTextBox() or chatInputBarConfiguration.IsFocused)
	then
		return internalNotifyFunction(timing, "User is typing in a text box.")
	end

	if selectedFilters["Disable While Using Sightless Beam"] and StateListener.csb() then
		return internalNotifyFunction(timing, "User is using the 'Sightless Beam' move.")
	end

	if selectedFilters["Disable When Window Not Active"] and not iswindowactive() then
		return internalNotifyFunction(timing, "Window is not active.")
	end

	if selectedFilters["Disable During Chime Countdown"] and StateListener.ccd() then
		return internalNotifyFunction(timing, "Chime countdown is active.")
	end

	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return internalNotifyFunction(timing, "No effect replicator found.")
	end

	if selectedFilters["Disable While In Payback"] then
		local effectReplicatorModule = require(effectReplicator)
		if effectReplicatorModule then
			for _, effect in next, effectReplicatorModule.Effects do
				if
					effect.Class == "ToolLockCD"
					and effect.index
					and effect.index.Value
					and tostring(effect.index.Value):find("Payback")
				then
					return internalNotifyFunction(timing, "Payback is on cooldown (recently used).")
				end
			end
		end
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return internalNotifyFunction(timing, "No effect replicator module found.")
	end

	local actionType = options.action and options.action._type or "N/A"
	local isCrouchOrSlide = actionType == "Start Crouch"
		or actionType == "End Crouch"
		or actionType == "Start Slide"
		or actionType == "End Slide"

	if
		not Configuration.expectToggleValue("BlatantRoll")
		or (actionType ~= ("Dodge") and actionType ~= ("Forced Full Dodge"))
	then
		if not self.afeinted and not options.sstun and not isCrouchOrSlide and StateListener.astun() then
			return internalNotifyFunction(timing, "User is in action stun.")
		end

		if effectReplicatorModule:FindEffect("Knocked") then
			return internalNotifyFunction(timing, "User is knocked.")
		end
	end

	if actionType == ("Parry") then
		local isPlayer = self.entity and players:GetPlayerFromCharacter(self.entity)
		if effectReplicatorModule:FindEffect("AutoParry") and isPlayer and Configuration.expectToggleValue("UseAutoParryFrames") then
			return internalNotifyFunction(timing, "User has auto parry frames.")
		end
	end

	if timing.tag == "M1" and selectedFilters["Filter Out M1s"] then
		return internalNotifyFunction(timing, "Attacker is using a 'M1' attack.")
	end

	if timing.tag == "Mantra" and selectedFilters["Filter Out Mantras"] then
		return internalNotifyFunction(timing, "Attacker is using a 'Mantra' attack.")
	end

	-- We swung and connected first on THIS attacker: our hit cancels their swing, so their M1/Mantra animation is a ghost the auto defense should ignore.
	if
		timing.tag == "M1"
		and selectedFilters["Disable If Enemy Hit In M1"]
		and self.hitByUsRecently
		and self:hitByUsRecently()
	then
		return internalNotifyFunction(timing, "Enemy 'M1' cancelled by our hit.")
	end

	if
		timing.tag == "Mantra"
		and selectedFilters["Disable If Enemy Hit In Mantra"]
		and self.hitByUsRecently
		and self:hitByUsRecently()
	then
		return internalNotifyFunction(timing, "Enemy 'Mantra' cancelled by our hit.")
	end

	if timing.tag == "Critical" and selectedFilters["Filter Out Criticals"] then
		return internalNotifyFunction(timing, "Attacker is using a 'Critical' attack.")
	end

	if timing.tag == "Undefined" and selectedFilters["Filter Out Undefined"] then
		return internalNotifyFunction(timing, "Attacker is using an 'Undefined' attack.")
	end

	if timing.rsc and StateListener.recentlyCast(timing.rsaid, timing.rsaw) then
		return internalNotifyFunction(timing, "User recently played the same animation themselves (%s).", timing.rsaid)
	end

	return true
end)

---Check if any parts that are in our filter were hit.
---@note: Solara fallback.
local function checkParts(parts, filter)
	for _, part in next, parts do
		for _, fpart in next, filter do
			if part ~= fpart and not part:IsDescendantOf(fpart) then
				continue
			end

			return true
		end
	end

	return false
end

---Get a unique ID for hitboxes.
---@param spaces number Determines how many spaces that one UID can occupy.
---@return number
function Defender:uid(spaces)
	-- Increment.
	self.uids = self.uids + spaces

	-- Return.
	return self.uids
end

---Visualize a position and size.
---@param self Defender
---@param identifier number? If the identifier is nil, then we will auto-generate one for each visualization.
---@param cframe CFrame
---@param size Vector3
---@param color Color3
---@param shape Enum.PartType
Defender.visualize = (function(self, identifier, cframe, size, color, shape)
	local id = identifier or self:uid(10)
	local vpart = self.hmaid[id] or Instance.new("Part")

	pcall(function()
		vpart.Parent = workspace
	end)

	if vpart.Parent then
		vpart.Anchored = true
		vpart.CanCollide = false
		vpart.CanQuery = false
		vpart.CanTouch = false
		vpart.Material = Enum.Material.ForceField
		vpart.CastShadow = false
		vpart.Size = size
		vpart.CFrame = cframe
		vpart.Color = color
		vpart.Shape = shape
		vpart.Transparency = Configuration.expectToggleValue("EnableVisualizations") and 0.2 or 1.0
	end

	if self.hmaid[id] then
		return
	end

	self.hmaid[id] = vpart

	debrisService:AddItem(vpart, MAX_VISUALIZATION_TIME)
end)

--- Run hitbox check.
---@param self Defender
---@param cframe CFrame
---@param fd boolean
---@param soffset number
---@param size Vector3
---@param filter Instance[]
---@param shape Enum.PartType
---@return boolean?, CFrame?
Defender.hitbox = (function(self, cframe, fd, soffset, size, filter, shape)
	local shouldManualFilter = getexecutorname
		and (getexecutorname():match("Solara") or getexecutorname():match("Xeno"))

	local overlapParams = OverlapParams.new()
	overlapParams.FilterDescendantsInstances = shouldManualFilter and {} or filter
	overlapParams.FilterType = shouldManualFilter and Enum.RaycastFilterType.Exclude or Enum.RaycastFilterType.Include

	local character = players.LocalPlayer.Character
	if not character then
		return nil, nil
	end

	local root = character:FindFirstChild("HumanoidRootPart")
	if not root then
		return nil, nil
	end

	-- Used CFrame.
	local usedCFrame = cframe

	if fd then
		usedCFrame = usedCFrame * CFrame.new(0, 0, -(size.Z / 2))
	end

	if soffset and soffset ~= 0 then
		usedCFrame = usedCFrame * CFrame.new(0, 0, soffset)
	end

	-- Create simulation part.
	local simulationPart = Instance.new("Part")
	simulationPart.Size = size
	simulationPart.Material = Enum.Material.ForceField
	simulationPart.Shape = shape
	simulationPart.CFrame = usedCFrame

	if shape == Enum.PartType.Cylinder then
		simulationPart.CFrame = usedCFrame * CFrame.Angles(0, 0, math.rad(90))
	end

	-- Parts in bounds.
	local parts = workspace:GetPartsInPart(simulationPart, overlapParams)

	-- Return result.
	return shouldManualFilter and checkParts(parts, filter) or #parts > 0, usedCFrame
end)

--- Whether an entity this far out is worth processing at all.
---@param from Model? | BasePart?
---@param distance number
---@return boolean
Defender.processable = (function(_, from, distance)
	if not from then
		return true
	end

	local character = players.LocalPlayer and players.LocalPlayer.Character
	if character and (from == character or from.Parent == character) then
		return true
	end

	-- `from` can be the character model itself or a part inside it, so check both.
	local player = players:GetPlayerFromCharacter(from)
		or (from.Parent and players:GetPlayerFromCharacter(from.Parent))

	local limit = Configuration.expectOptionValue(player and "DontProcessPlayersOver" or "DontProcessMobsOver")
	if type(limit) ~= "number" or limit <= 0 then
		return true
	end

	return distance <= limit
end)

---Check initial state.
---@param self Defender
---@param from Model? | BasePart?
---@param pair TimingContainerPair
---@param name string
---@param key string
---@return Timing?
Defender.initial = (function(self, from, pair, name, key)
	-- Find timing.
	local timing = pair:index(key)

	-- Fetch distance.
	local distance = self:distance(from)
	if not distance then
		return nil
	end

	-- Distance ceiling.
	if not self:processable(from, distance) then
		return nil
	end

	-- Check for distance; if we have a timing.
	if timing then
		local md = (timing.imdd)

		if md <= 0.01 then
			md = 0.0
		end

		if distance < md or distance > (timing.imxd) then
			return nil
		end
	end

	-- Check for no timing.
	---@note: Ignore return value.
	if not timing then
		self:miss(self.__type, key, name, distance, from and tostring(from.Parent) or nil)
		return false
	end

	-- Return timing.
	return timing
end)

---Logger notify.
---@param self Defender
---@param timing Timing
---@param str string
Defender.notify = (function(self, timing, str, ...)
	if not Configuration.expectToggleValue("EnableNotifications") then
		return
	end

	Logger.qnotify("[%s] (%s) %s", timing.name, self.__type, string.format(str, ...))
end)

---Repeat conditional.
---@param self Defender
---@param info RepeatInfo
---@return boolean
Defender.rc = (function(self, info)
	if os.clock() - info.start >= MAX_REPEAT_WAIT then
		return false
	end

	return true
end)

---Handle delay until in hitbox.
---@param self Defender
---@param options HitboxOptions
---@param info RepeatInfo
---@return boolean
Defender.duih = (function(self, options, info)
	local clone = options:clone()
	clone.hmid = info.hmid
	clone:ucache()

	while task.wait() do
		if not self:rc(info) then
			return false
		end

		if not self:hc(clone, nil) then
			continue
		end

		return true
	end
end)

---Handle hitbox check options.
---@param self Defender
---@param options HitboxOptions
---@param info RepeatInfo? Pass this in if you want to use the delay until in hitbox.
---@return boolean
Defender.hc = (function(self, options, info)
	local action = options.action
	local timing = options.timing

	-- Inner visualization function.
	local function innerVisualize(...)
		if not options.visualize then
			return
		end

		return self:visualize(...)
	end

	-- Run basic validation.
	local character = players.LocalPlayer.Character
	if not character then
		return false
	end

	local root = character:FindFirstChild("HumanoidRootPart")
	if not root then
		return false
	end

	if action and action.ihbc then
		return true
	end

	-- If we have info, then we want to delay until in hitbox.
	if info then
		return self:duih(options, info)
	end

	-- Fetch the data that we need.
	local hitbox = options:hitbox()
	local eposition = options.spredict and options:extrapolate() or nil
	local position = options:pos()
	local pt = timing.htype or Enum.PartType.Block

	-- Run hitbox check.
	local result, usedCFrame = self:hitbox(position, timing.fhb, timing.hso, hitbox, options.filter, pt)

	if usedCFrame then
		innerVisualize(options.hmid, usedCFrame, hitbox, options:ghcolor(result), pt)
		innerVisualize(options.hmid and options.hmid + 1 or nil, root.CFrame, root.Size, options:ghcolor(result), pt)
	end

	if not options.spredict or result then
		return result
	end

	-- Run prediction check.
	local closest = EntityHistory.pclosest(players.LocalPlayer, tick() - (Latency.rtt() * PREDICTION_LENIENCY_MULTI))
	if not closest then
		return false
	end

	local store = OriginalStore.new()

	-- Run check.
	store:run(root, "CFrame", closest, function()
		result, usedCFrame = self:hitbox(eposition, timing.fhb, timing.hso, hitbox, options.filter, pt)
	end)

	-- Visualize predicted hitbox.
	if usedCFrame then
		innerVisualize(options.hmid and options.hmid + 1 or nil, usedCFrame, hitbox, options:gphcolor(result), pt)
		innerVisualize(options.hmid and options.hmid + 1 or nil, closest, root.Size, options:gphcolor(result), pt)
	end

	-- Return result.
	return result
end)

---Handle action.
---@param self Defender
---@param timing Timing
---@param action Action
---@param started number
Defender.handle = (function(self, timing, action, started)
	local actionType = (action._type)

	if actionType == "End Block" then
		QueuedBlocking.stop("Defender_StartBlock")
	end

	-- Delayed-feint catch.
	if self.__type == "Animation" and self.track and actionType ~= "End Block" and self:stopped(self.track, timing) then
		-- Diagnostic detail: the bare message can't distinguish a real feint from a track that simply ENDED before its scheduled action.
		local playing, timePosition, length, speed = "?", -1, -1, -1
		pcall(function()
			playing = tostring(self.track.IsPlaying)
			timePosition = self.track.TimePosition
			length = self.track.Length
			speed = self.track.Speed
		end)

		return self:notify(
			timing,
			"Reaction aborted: attack stopped (feint) before input fired. (playing=%s tpos=%.3f len=%.3f speed=%.2f when=%.3f gate=%.3f sinceSched=%.3f iae=%s ieae=%s)",
			playing,
			timePosition,
			length,
			speed,
			action:when(),
			self.gateDelay or 0,
			started and (os.clock() - started) or -1,
			tostring(timing.iae),
			tostring(timing.ieae)
		)
	end

	-- Handle auto feint.
	if
		Configuration.expectToggleValue("AutoFeint")
		and not timing.duih
		and action._when > 0
		and self.__type == "Animation"
		and actionType ~= "End Block"
	then
		self:afeint(timing, action, started, false)
	end

	if actionType ~= "End Block" then
		local validationOptions = ValidationOptions.new(action, timing)
		local defensiveAction = actionType == "Parry"
			or actionType == "Dodge"
			or actionType == "Forced Full Dodge"
			or actionType == "Start Block"
		local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
		local effectReplicatorModule = effectReplicator and require(effectReplicator)
		local forceDefensiveFeint = Configuration.expectToggleValue("AutoFeint")
			and not self.afeinted
			and defensiveAction
			and effectReplicatorModule
			and effectReplicatorModule:HasEffect("LightAttack")
			and StateListener.cfeint()

		-- An M1 that is about to be feinted should not make the otherwise valid defensive action fail its transient action-stun check.
		validationOptions.sstun = forceDefensiveFeint or false

		if not self:valid(validationOptions) then
			return
		end

		if forceDefensiveFeint then
			self.afeinted = true
			InputClient.feint()
			self:notify(timing, "Auto Feint cancelled the active M1 for auto defense.")
		end
	end

	local redactedMap = {
		["Start Slide"] = "1",
		["End Slide"] = "2",
		["Teleport Up"] = "3",
		["Forced Full Dodge"] = "4",
		["Jump"] = "5",
		["Start Block"] = "6",
		["End Block"] = "7",
		["Parry"] = "8",
		["Dodge"] = "9",
		["Start Crouch"] = "10",
		["End Crouch"] = "11",
	}

	if LRM_UserNote then
		self:notify(timing, "Action type '%s' is being executed.", redactedMap[actionType] or actionType)
	else
		self:notify(timing, "Action type '%s' is being executed.", actionType)
	end

	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return
	end

	if actionType == "Start Block" then
		return QueuedBlocking.invoke(QueuedBlocking.BLOCK_TYPE_NORMAL, "Defender_StartBlock", 20.0)
	end

	local options = DodgeOptions.new()
	options.rollCancel = Configuration.expectToggleValue("RollCancel") and actionType ~= "Forced Full Dodge"
	options.rollCancelDelay = Configuration.expectOptionValue("RollCancelDelay") or 0.0
	options.direct = Configuration.expectToggleValue("BlatantRoll")

	local inIFrame = effectReplicatorModule:FindEffect("Immortal")
		or effectReplicatorModule:FindEffect("Dodge")
		or effectReplicatorModule:FindEffect("Ghost")

	if
		(actionType == "Dodge" or actionType == "Forced Full Dodge") and Configuration.expectToggleValue("ParryOnly")
	then
		actionType = "Parry"
		self:notify(timing, "Action 'Dodge' changed to 'Parry'")
	end

	if actionType == "Dodge" then
		if Configuration.expectToggleValue("UseIFrames") and inIFrame then
			return
		end

		return InputClient.dodge(options)
	end

	if actionType == "Forced Full Dodge" then
		return InputClient.dodge(options)
	end

	if actionType == "End Block" then
		return
	end

	if actionType == "Start Slide" then
		return InputClient.slide()
	end

	if actionType == "End Slide" then
		return InputClient.unslide()
	end

	if actionType == "Start Crouch" then
		return InputClient.crouch()
	end

	if actionType == "End Crouch" then
		return InputClient.uncrouch()
	end

	if actionType == "Jump" then
		local humanController = InputClient.getHumanController()
		if not humanController then
			return
		end

		if effectReplicatorModule:HasAny("Swimming", "Jumped", "NoJump", "Landed") then
			return
		end

		if not humanController:Jump() then
			return
		end

		return InputClient.ejump()
	end

	if actionType == "Teleport Up" then
		local character = players.LocalPlayer.Character
		if not character then
			return
		end

		local humanoidRootPart = character:FindFirstChild("HumanoidRootPart")
		if not humanoidRootPart then
			return
		end

		if Finder.pnear(humanoidRootPart.Position, 500) then
			return self:notify(timing, "Action 'Teleport Up' blocked because there are players nearby.")
		end

		humanoidRootPart.CFrame = CFrame.new(humanoidRootPart.Position + Vector3.new(0, 75, 0))
	end

	self:parry(timing, action)
end)

---Simulate input based on action type.
---@param self Defender
---@param timing Timing
---@param action Action
Defender.SimulateInput = (function(self, timing, action)
	if not Configuration.expectToggleValue("EnableSimulation") then
		return
	end

	if not action or not action._type then
		return
	end

	local actionType = action._type
	local function simulateRightClick(hold)
		if type(mouse2press) == "function" and type(mouse2release) == "function" then
			mouse2press()
			task.delay(hold, function()
				mouse2release()
			end)
			return
		end

		keypress(0x02)
		task.delay(hold, function()
			keyrelease(0x02)
		end)
	end

	-- Human-like hold time: a small random duration so presses are never perfectly consistent (like a real keyboard).
	local function holdTime()
		return Random.new():NextNumber(0.1, 0.15)
	end

	-- Press a raw OS virtual key then release it after the hold.
	local function simulateKeyTap(virtualKey)
		keypress(virtualKey)
		task.delay(holdTime(), function()
			keyrelease(virtualKey)
		end)
	end

	local selectedFilters = Configuration.expectOptionValue("AutoDefenseFilters") or {}

	if selectedFilters["Disable While Holding Block"] and StateListener.hblock() then
		return
	end

	local chatInputBarConfiguration = textChatService:FindFirstChildOfClass("ChatInputBarConfiguration")
	if
		selectedFilters["Disable When Textbox Focused"]
		and (userInputService:GetFocusedTextBox() or (chatInputBarConfiguration and chatInputBarConfiguration.IsFocused))
	then
		return
	end

	if selectedFilters["Disable While Using Sightless Beam"] and StateListener.csb() then
		return
	end

	if selectedFilters["Disable When Window Not Active"] and type(iswindowactive) == "function" and not iswindowactive() then
		return
	end

	if selectedFilters["Disable During Chime Countdown"] and StateListener.ccd() then
		return
	end

	if selectedFilters["Disable While In Payback"] then
		local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
		local effectReplicatorModule = effectReplicator and require(effectReplicator)
		if effectReplicatorModule then
			for _, effect in next, effectReplicatorModule.Effects do
				if
					effect.Class == "ToolLockCD"
					and effect.index
					and effect.index.Value
					and tostring(effect.index.Value):find("Payback")
				then
					return
				end
			end
		end
	end

	if timing and timing.tag == "M1" and selectedFilters["Filter Out M1s"] then
		return
	end

	if timing and timing.tag == "Mantra" and selectedFilters["Filter Out Mantras"] then
		return
	end

	-- Our hit cancelled THIS attacker's swing -> ignore its ghost M1/Mantra animation (per entity; a second attacker we did not hit is unaffected).
	if
		timing
		and timing.tag == "M1"
		and selectedFilters["Disable If Enemy Hit In M1"]
		and self.hitByUsRecently
		and self:hitByUsRecently()
	then
		return
	end

	if
		timing
		and timing.tag == "Mantra"
		and selectedFilters["Disable If Enemy Hit In Mantra"]
		and self.hitByUsRecently
		and self:hitByUsRecently()
	then
		return
	end

	if timing and timing.tag == "Critical" and selectedFilters["Filter Out Criticals"] then
		return
	end

	if timing and timing.tag == "Undefined" and selectedFilters["Filter Out Undefined"] then
		return
	end

	if actionType == "Parry" then
		-- F key (parry).
		simulateKeyTap(0x46)

	elseif actionType == "Dodge" or actionType == "Forced Full Dodge" then
		-- Q key (roll).
		simulateKeyTap(0x51)

		if Configuration.expectToggleValue("RollCancel") then
			task.delay(0.01, function()
				simulateRightClick(holdTime())
			end)
		end

	elseif actionType == "Vent" then
		-- G key (vent).
		simulateKeyTap(0x47)

	elseif actionType == "Feint" then
		simulateRightClick(holdTime())
	end
end)

---Handle parry.
---@param self Defender
---@param timing Timing
---@param action Action
Defender.parry = (function(self, timing, action)
	-- Options.
	local options = DodgeOptions.new()
	options.rollCancel = Configuration.expectToggleValue("RollCancel")
	options.rollCancelDelay = Configuration.expectOptionValue("RollCancelDelay") or 0.0
	options.direct = Configuration.expectToggleValue("BlatantRoll")

	-- Rate.
	local rate = (Configuration.expectOptionValue("DashInsteadOfParryRate") or 0.0)
	local overrideData = Library:GetOverrideData(timing.name)
	if overrideData then
		rate = overrideData.dipr
	end

	-- Effect Replicator.
	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	local effectReplicatorModule = effectReplicator and require(effectReplicator)

	-- IFrame checks
	local inIFrame = effectReplicatorModule:FindEffect("Immortal")
		or effectReplicatorModule:FindEffect("DodgeFrame")
		or effectReplicatorModule:FindEffect("ParryFrame")
		or effectReplicatorModule:FindEffect("Ghost")

	-- Dash instead of parry.
	local dashReplacement = rngShared:NextNumber(1.0, 100.0) <= rate

	if action and (action._type) ~= "Parry" then
		dashReplacement = false
	end

	if not Configuration.expectToggleValue("AllowFailure") and not overrideData then
		dashReplacement = false
	end

	if timing.umoa or timing.actions:count() ~= 1 then
		dashReplacement = false
	end

	if Configuration.expectToggleValue("ParryOnly") then
		dashReplacement = false
	end

	local function internalNotify(...)
		if timing.rpue and timing.srpn then
			return
		end

		return self:notify(...)
	end

	if Configuration.expectToggleValue("UseIFrames") and inIFrame then
		return internalNotify(timing, "Action 'Parry' blocked because there are already existing IFrames.")
	end

	if
		Configuration.expectToggleValue("RollIfBehind")
		and StateListener.cdodge()
		and not timing.ndfb
		and self:behind()
	then
		self:SimulateInput(timing, { _type = "Dodge" })
		InputClient.dodge(options)

		return internalNotify(timing, "Action type 'Parry' rolled because attack is behind.")
	end

	-- Parry if possible.
	if StateListener.cparry() then
		-- Handle deflecting.
		if timing.nfdb or not StateListener.cdodge() or not dashReplacement then
			self:SimulateInput(timing, { _type = "Parry" })
			return QueuedBlocking.invoke(QueuedBlocking.BLOCK_TYPE_DEFLECT, "Defender_Deflect", nil)
		end

		-- Notify.
		internalNotify(timing, "Action type 'Parry' replaced to 'Dodge' type.")

		-- Dash replacement.
		self:SimulateInput(timing, { _type = "Dodge" })
		return InputClient.dodge(options)
	end

	-- What fallbacks can we run?
	local canBlock = Configuration.expectToggleValue("DeflectBlockFallback")
		and not timing.nbfb
		and StateListener.cblock()

	local canVent = StateListener.cvent()
		and Configuration.expectToggleValue("VentFallback")
		and not timing.nvfb
		and not timing.rpue
		and self.__type ~= "Part"

	local canDodge = StateListener.cdodge()
		and Configuration.expectToggleValue("RollOnParryCooldown")
		and not timing.ndfb

	if canDodge then
		-- Dodge.
		self:SimulateInput(timing, { _type = "Dodge" })
		InputClient.dodge(options)

		-- Notify.
		return internalNotify(timing, "Action type 'Parry' fallback to 'Dodge' type.")
	end

	-- Prefer Block Fallback (pbfb).
	if canBlock and timing.pbfb then
		self:SimulateInput(timing, { _type = "Start Block" })
		QueuedBlocking.invoke(QueuedBlocking.BLOCK_TYPE_NORMAL, "Defender_BlockFallback", timing.bfht)

		return internalNotify(timing, "Action type 'Parry' fallback to 'Block' type (preferred).")
	end

	if canVent then
		-- Vent.
		self:SimulateInput(timing, { _type = "Vent" })
		InputClient.vent()

		-- Notify.
		return internalNotify(timing, "Action type 'Parry' fallback to 'Vent' type.")
	end

	if canBlock then
		-- Block.
		self:SimulateInput(timing, { _type = "Start Block" })
		QueuedBlocking.invoke(QueuedBlocking.BLOCK_TYPE_NORMAL, "Defender_BlockFallback", timing.bfht)

		-- Notify.
		return internalNotify(timing, "Action type 'Parry' fallback to 'Block' type.")
	end

	-- Cannot fallback.
	return internalNotify(timing, "Action 'Parry' blocked because no fallbacks are available.")
end)

---Check if we have input blocking tasks.
---@param self Defender
---@return boolean
Defender.blocking = (function(self)
	for _, marker in next, self.markers do
		if not marker then
			continue
		end

		return true
	end

	for _, task in next, self.tasks do
		if not task:blocking() then
			continue
		end

		return true
	end
end)

---Mark task.
---@param task Task
function Defender:mark(task)
	self.tasks[#self.tasks + 1] = task
	Defender.armed[self] = true
end

---Clean up hooks.
function Defender:clhook()
	for key, old in next, self.rhook do
		if not self[key] then
			continue
		end

		self[key] = old
	end

	self.rhook = {}
end

---Clean up all tasks.
---@param self Defender
Defender.clean = (function(self)
	-- Clean-up tasks.
	for idx, task in next, self.tasks do
		if task.forced then
			continue
		end

		if
			task.identifier == "Start Crouch"
			or task.identifier == "End Crouch"
			or task.identifier == "Start Slide"
			or task.identifier == "End Slide"
		then
			continue
		end

		-- Cancel task.
		task:cancel()

		-- Clear in table.
		self.tasks[idx] = nil

		-- If we are cancelling a stop block or start block, then we want to end the block.
		if task.identifier ~= "End Block" and task.identifier ~= "Start Block" then
			continue
		end

		QueuedBlocking.stop("Defender_StartBlock")
	end

	-- Clean-up hooks.
	self:clhook()

	-- Clear temporary maid.
	self.tmaid:clean()

	-- Clear markers.
	self.markers = {}

	-- Clean up hitboxes.
	self.hmaid:clean()

	-- Reset auto feint.
	self.afeinted = false

	-- Drop out of the armed set once every non-forced task is gone.
	if next(self.tasks) == nil then
		Defender.armed[self] = nil
	end
end)

---Process module.
---@param self Defender
---@param timing Timing
---@varargs any
Defender.module = (function(self, timing, ...)
	-- Get loaded function.
	local lf = ModuleManager.modules[(timing.smod)]
	if not lf then
		return self:notify(timing, "No module '%s' found.", (timing.smod))
	end

	-- Create identifier.
	local identifier = string.format("Defender_RunModule_%s", (timing.smod))

	-- Notify.
	if not timing.smn then
		self:notify(timing, "Running module '%s' on timing.", (timing.smod))
	end

	-- Run module.
	self.tmaid:mark(TaskSpawner.spawn(identifier, lf, self, timing, ...))
end)

---Activate Prediction mantra instead of parrying.
---@param self Defender
---@param timing Timing
---@param action Action
Defender.prediction = (function(self, timing, action)
	-- Too fast to counter: the attack's parry timing doesn't leave room for the windup.
	if action:when() <= counterLead("Prediction") then
		return
	end

	-- Players always.
	if not players:GetPlayerFromCharacter(self.entity)
		and Configuration.expectToggleValue("PredictionCounterNPCs") == false
	then
		return
	end

	-- Windup delay.
	task.wait(0.1)

	local options = ValidationOptions.new(action, timing)
	options.skipFailureRate = true
	options.visualize = false
	if not self:valid(options) then
		return
	end

	-- Feint check.
	if self.__type == "Animation" and self.track and self:stopped(self.track, timing) then
		return
	end

	local localPlayer = players.LocalPlayer
	local character = localPlayer and localPlayer.Character
	local backpack = localPlayer and localPlayer:FindFirstChild("Backpack")
	local predictionMantra = backpack and backpack:FindFirstChild("Mantra:PredictionIntelligence{{Prediction}}")

	if not character then
		return
	end

	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	local effectReplicatorModule = effectReplicator and require(effectReplicator)

	if not effectReplicatorModule then
		return
	end

	-- IFrame check.
	local inIFrame = effectReplicatorModule:FindEffect("Immortal")
		or effectReplicatorModule:FindEffect("DodgeFrame")
		or effectReplicatorModule:FindEffect("ParryFrame")
		or effectReplicatorModule:FindEffect("Ghost")

	local isPlayer = self.entity and players:GetPlayerFromCharacter(self.entity)
	if Configuration.expectToggleValue("UseIFrames") and inIFrame and isPlayer then
		return
	end

	-- Hitbox check.
	if self.entity and self.__type == "Animation" then
		local root = self.entity:FindFirstChild("HumanoidRootPart")
		if not root then
			return
		end

		local hoptions = HitboxOptions.new(root, timing)
		hoptions.spredict = not timing.duih and not timing.dp
		hoptions.ptime = self:fsecs(timing)
		hoptions.action = action
		hoptions.entity = self.entity
		hoptions.visualize = false
		hoptions:ucache()

		if not self:hc(hoptions, nil) and not self:fpc(timing, hoptions) then
			return
		end
	end

	if not predictionMantra then
		return
	end

	local onCooldown = false
	for _, effect in next, effectReplicatorModule.Effects do
		if
			effect.Class == "ToolLockCD"
			and effect.index
			and effect.index.Value
			and tostring(effect.index.Value):find("PredictionIntelligence")
		then
			onCooldown = true
			break
		end
	end

	if onCooldown then
		return
	end

	local activateMantra = character:FindFirstChild("CharacterHandler")
		and character.CharacterHandler:FindFirstChild("Requests")
		and character.CharacterHandler.Requests:FindFirstChild("ActivateMantra")

	if not activateMantra then
		return
	end

	activateMantra:FireServer(predictionMantra)
	self:notify(timing, "Action 'Parry' replaced with 'Prediction' mantra.")
end)

---Activate Punishment mantra instead of parrying.
---@param self Defender
---@param timing Timing
---@param action Action
Defender.punishment = (function(self, timing, action)
	-- Too fast to counter: the attack's parry timing doesn't leave room for the windup.
	if action:when() <= counterLead("Punishment") then
		return
	end

	-- Players always.
	if not players:GetPlayerFromCharacter(self.entity)
		and Configuration.expectToggleValue("PunishmentCounterNPCs") == false
	then
		return
	end

	-- Windup delay.
	task.wait(0.1)

	local options = ValidationOptions.new(action, timing)
	options.skipFailureRate = true
	options.visualize = false
	if not self:valid(options) then
		return
	end

	-- Feint check.
	if self.__type == "Animation" and self.track and self:stopped(self.track, timing) then
		return
	end

	local localPlayer = players.LocalPlayer
	local character = localPlayer and localPlayer.Character
	local backpack = localPlayer and localPlayer:FindFirstChild("Backpack")
	local punishmentMantra = backpack and backpack:FindFirstChild("Mantra:RevengeWeaponHeavy{{Punishment}}")

	if not character then
		return
	end

	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	local effectReplicatorModule = effectReplicator and require(effectReplicator)

	if not effectReplicatorModule then
		return
	end

	-- Defer to Prediction.
	if Configuration.expectToggleValue("UsePrediction") then
		local predictionMantra = backpack and backpack:FindFirstChild("Mantra:PredictionIntelligence{{Prediction}}")
		if predictionMantra then
			local predictionOnCooldown = false
			for _, effect in next, effectReplicatorModule.Effects do
				if
					effect.Class == "ToolLockCD"
					and effect.index
					and effect.index.Value
					and tostring(effect.index.Value):find("PredictionIntelligence")
				then
					predictionOnCooldown = true
					break
				end
			end

			if not predictionOnCooldown then
				return
			end
		end
	end

	-- Skip if already absorbing.
	if effectReplicatorModule:FindEffect("AbsorbCharge") then
		return
	end

	-- IFrame check.
	local inIFrame = effectReplicatorModule:FindEffect("Immortal")
		or effectReplicatorModule:FindEffect("DodgeFrame")
		or effectReplicatorModule:FindEffect("ParryFrame")
		or effectReplicatorModule:FindEffect("Ghost")

	local isPlayer = self.entity and players:GetPlayerFromCharacter(self.entity)
	if Configuration.expectToggleValue("UseIFrames") and inIFrame and isPlayer then
		return
	end

	-- Hitbox check.
	if self.entity and self.__type == "Animation" then
		local root = self.entity:FindFirstChild("HumanoidRootPart")
		if not root then
			return
		end

		local hoptions = HitboxOptions.new(root, timing)
		hoptions.spredict = not timing.duih and not timing.dp
		hoptions.ptime = self:fsecs(timing)
		hoptions.action = action
		hoptions.entity = self.entity
		hoptions.visualize = false
		hoptions:ucache()

		if not self:hc(hoptions, nil) and not self:fpc(timing, hoptions) then
			return
		end
	end

	if not punishmentMantra then
		return
	end

	local onCooldown = false
	for _, effect in next, effectReplicatorModule.Effects do
		if
			effect.Class == "ToolLockCD"
			and effect.index
			and effect.index.Value
			and tostring(effect.index.Value):find("RevengeWeaponHeavy")
		then
			onCooldown = true
			break
		end
	end

	if onCooldown then
		return
	end

	local activateMantra = character:FindFirstChild("CharacterHandler")
		and character.CharacterHandler:FindFirstChild("Requests")
		and character.CharacterHandler.Requests:FindFirstChild("ActivateMantra")

	if not activateMantra then
		return
	end

	activateMantra:FireServer(punishmentMantra)
	self:notify(timing, "Action 'Parry' replaced with 'Punishment' mantra.")
end)

---Activate Equalizer mantra instead of parrying.
---@param self Defender
---@param timing Timing
---@param action Action
Defender.Equalizer = (function(self, timing, action)
	-- Too fast to counter: the attack's parry timing doesn't leave room for the windup.
	if action:when() <= counterLead("Equalizer") then
		return
	end

	-- Players always.
	if not players:GetPlayerFromCharacter(self.entity)
		and Configuration.expectToggleValue("EqualizerCounterNPCs") == false
	then
		return
	end

	-- Validate but skip failure rate (Equalizer should always work).
	local options = ValidationOptions.new(action, timing)
	options.skipFailureRate = true
	options.visualize = false
	if not self:valid(options) then
		return
	end

	-- Check if animation stopped (feint detection).
	if self.__type == "Animation" and self.track and self:stopped(self.track, timing) then
		return
	end

	local localPlayer = players.LocalPlayer
	local character = localPlayer and localPlayer.Character
	local backpack = localPlayer and localPlayer:FindFirstChild("Backpack")
	local equalizerMantra = backpack and backpack:FindFirstChild("Mantra:AntiairContractor{{Equalizer}}")

	if not character then
		return
	end

	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	local effectReplicatorModule = effectReplicator and require(effectReplicator)

	if not effectReplicatorModule then
		return
	end

	-- Defer to Prediction if it is enabled, available, and off cooldown.
	if Configuration.expectToggleValue("UsePrediction") then
		local predictionMantra = backpack and backpack:FindFirstChild("Mantra:PredictionIntelligence{{Prediction}}")
		if predictionMantra then
			local predictionOnCooldown = false
			for _, effect in next, effectReplicatorModule.Effects do
				if
					effect.Class == "ToolLockCD"
					and effect.index
					and effect.index.Value
					and tostring(effect.index.Value):find("PredictionIntelligence")
				then
					predictionOnCooldown = true
					break
				end
			end

			if not predictionOnCooldown then
				return
			end
		end
	end

	-- Skip if already absorbing damage from a previous counter.
	if effectReplicatorModule:FindEffect("AbsorbCharge") then
		return
	end

	-- Skip if already in IFrames (only for players).
	local inIFrame = effectReplicatorModule:FindEffect("Immortal")
		or effectReplicatorModule:FindEffect("DodgeFrame")
		or effectReplicatorModule:FindEffect("ParryFrame")
		or effectReplicatorModule:FindEffect("Ghost")

	local isPlayer = self.entity and players:GetPlayerFromCharacter(self.entity)
	if Configuration.expectToggleValue("UseIFrames") and inIFrame and isPlayer then
		return
	end

	-- Hitbox check for AnimatorDefender.
	if self.entity and self.__type == "Animation" then
		local root = self.entity:FindFirstChild("HumanoidRootPart")
		if not root then
			return
		end

		local hoptions = HitboxOptions.new(root, timing)
		hoptions.spredict = not timing.duih and not timing.dp
		hoptions.ptime = self:fsecs(timing)
		hoptions.action = action
		hoptions.entity = self.entity
		hoptions.visualize = false
		hoptions:ucache()

		if not self:hc(hoptions, nil) and not self:fpc(timing, hoptions) then
			return
		end
	end

	if not equalizerMantra then
		return
	end

	-- Check if Equalizer is on cooldown.
	local onCooldown = false
	for _, effect in next, effectReplicatorModule.Effects do
		if
			effect.Class == "ToolLockCD"
			and effect.index
			and effect.index.Value
			and tostring(effect.index.Value):find("AntiairContractor")
		then
			onCooldown = true
			break
		end
	end

	if onCooldown then
		return
	end

	local activateMantra = character:FindFirstChild("CharacterHandler")
		and character.CharacterHandler:FindFirstChild("Requests")
		and character.CharacterHandler.Requests:FindFirstChild("ActivateMantra")

	if not activateMantra then
		return
	end

	activateMantra:FireServer(equalizerMantra)
	self:notify(timing, "Action 'Parry' replaced with 'Equalizer' mantra.")
end)

---Activate Unbidden instead of parrying.
---@param self Defender
---@param timing Timing
---@param action Action
Defender.unbidden = (function(self, timing, action)
	-- Too fast to counter: the attack's parry timing doesn't leave room for the windup.
	if action:when() <= counterLead("Unbidden") then
		return
	end

	-- Unbidden is an enchant on the weapon itself, not a mantra you need a player target to justify -- works the same against NPCs as it does against players, so there's no "only use against players" restriction here.

	-- Self-tracked fallback cooldown -- see UNBIDDEN_COOLDOWN's comment.
	if os.clock() - lastUnbiddenFire < UNBIDDEN_COOLDOWN then
		return
	end

	-- Hardcoded 100ms delay for Unbidden timing.
	task.wait(0.1)

	-- Validate positioning and timing.
	local options = ValidationOptions.new(action, timing)
	options.skipFailureRate = true
	options.visualize = false
	if not self:valid(options) then
		return
	end

	-- Check if animation stopped (feint detection).
	if self.__type == "Animation" and self.track and self:stopped(self.track, timing) then
		return
	end

	local localPlayer = players.LocalPlayer
	local character = localPlayer and localPlayer.Character
	if not character then
		return
	end

	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	local effectReplicatorModule = effectReplicator and require(effectReplicator)

	-- IFrame check to prevent wasting the Critical.
	if effectReplicatorModule then
		local inIFrame = effectReplicatorModule:FindEffect("Immortal")
			or effectReplicatorModule:FindEffect("DodgeFrame")
			or effectReplicatorModule:FindEffect("ParryFrame")
			or effectReplicatorModule:FindEffect("Ghost")

		if Configuration.expectToggleValue("UseIFrames") and inIFrame then
			return
		end

		-- Check if the weapon's Critical specifically is on cooldown.
		for _, effect in next, effectReplicatorModule.Effects do
			if
				effect.Class == "ToolLockCD"
				and effect.index
				and effect.index.Value
				and tostring(effect.index.Value):find("Critical")
			then
				return
			end
		end
	end

	-- Hitbox check.
	if self.entity and self.__type == "Animation" then
		local root = self.entity:FindFirstChild("HumanoidRootPart")
		if root then
			local hoptions = HitboxOptions.new(root, timing)
			hoptions.spredict = not timing.duih and not timing.dp
			hoptions.ptime = self:fsecs(timing)
			hoptions.action = action
			hoptions.entity = self.entity
			hoptions.visualize = false
			hoptions:ucache()

			if not self:hc(hoptions, nil) and not self:fpc(timing, hoptions) then
				return
			end
		end
	end

	local criticalRemote = KeyHandling.getRemote("CriticalClick")

	if criticalRemote then
		criticalRemote:FireServer()
		lastUnbiddenFire = os.clock()
		self:notify(timing, "Action 'Parry' replaced with 'Unbidden'.")
	end
end)

