	return self
end

-- Return RepeatInfo module.
return RepeatInfo

end)()

end)
__bundle_register("Features/Combat/Objects/SoundDefender", function(require, _LOADED, __bundle_register, __bundle_modules)
---@module Features.Combat.Objects.Defender
local Defender = require("Features/Combat/Objects/Defender")

---@module Game.Timings.SaveManager
local SaveManager = require("Game/Timings/SaveManager")

---@module Utility.Signal
local Signal = require("Utility/Signal")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@module Features.Combat.Objects.RepeatInfo
local RepeatInfo = require("Features/Combat/Objects/RepeatInfo")

---@module Features.Combat.Objects.HitboxOptions
local HitboxOptions = require("Features/Combat/Objects/HitboxOptions")

---@module Game.Latency
local Latency = require("Game/Latency")

---@class SoundDefender: Defender
---@field owner Model? The owner of the part.
---@field sound Sound The sound that we're defending.
---@field part BasePart A part that we can base the position off of.
local SoundDefender = setmetatable({}, { __index = Defender })
SoundDefender.__index = SoundDefender
SoundDefender.__type = "Sound"

-- Services.
local players = game:GetService("Players")

---Check if we're in a valid state to proceed with the action.
---@param self SoundDefender
---@param options ValidationOptions
---@return boolean
SoundDefender.valid = function(self, options)
	if not Defender.valid(self, options) then
		return false
	end

	local function internalNotifyFunction(timing, message)
		if not options.notify then
			return
		end

		return self:notify(timing, message)
	end

	local timing = options.timing
	local action = options.action

	if self.owner and not self:target(self.owner) then
		if not timing.alp or not players.LocalPlayer.Character or self.owner ~= players.LocalPlayer.Character then
			return internalNotifyFunction(timing, "Not a viable target.")
		end
	end

	local character = players.LocalPlayer.Character
	if not character then
		return internalNotifyFunction(timing, "No character found.")
	end

	local hoptions = HitboxOptions.new(self.part, timing)
	hoptions.spredict = false
	hoptions.action = action
	hoptions:ucache()

	if not self:hc(hoptions, timing.duih and RepeatInfo.new(timing, Latency.rdelay(), self:uid(10)) or nil) then
		return internalNotifyFunction(timing, "Not in hitbox.")
	end

	return true
end

---Repeat conditional.
---@param self SoundDefender
---@param _ RepeatInfo
---@return boolean
SoundDefender.rc = function(self, _)
	if not self.sound.IsPlaying then
		return false
	end

	return true
end

---Process sound playing.
---@param self SoundDefender
SoundDefender.process = function(self)
	---@type SoundTiming?
	local timing = self:initial(
		self.owner or self.part,
		SaveManager.ss,
		self.owner and self.owner.Name or self.part.Name,
		tostring(self.sound.SoundId)
	)

	if not timing then
		return
	end

	if not Configuration.expectToggleValue("EnableAutoDefense") then
		return
	end

	if not timing.alp and (players.LocalPlayer.Character and self.owner == players.LocalPlayer.Character) then
		return
	end

	---@note: Clean up previous tasks that are still waiting or suspended because they're in a different track.
	self:clean()

	-- Use module if we need to.
	if timing.umoa then
		return self:module(timing)
	end

	---@note: Start processing the timing. Add the actions if we're not RPUE.
	if not timing.rpue then
		return self:actions(timing)
	end

	-- Start RPUE.
	local info = RepeatInfo.new(timing, Latency.rdelay(), self:uid(10))
	self:srpue(self.entity, timing, info)
end

---Create new SoundDefender object.
---@param sound Sound
---@param part BasePart
---@return SoundDefender
function SoundDefender.new(sound, part)
	local self = setmetatable(Defender.new(), SoundDefender)
	local soundPlayed = Signal.new(sound.Played)

	self.sound = sound
	self.part = part
	self.owner = sound:FindFirstAncestorWhichIsA("Model")
	self.maid:mark(soundPlayed:connect(
		"SoundDefender_OnSoundPlayed",
		function()
			self:process()
		end
	))

	if sound.Playing then
		self:process()
	end

	return self
end

-- Return SoundDefender module.
return SoundDefender


end)
__bundle_register("Features/Combat/Objects/PartDefender", function(require, _LOADED, __bundle_register, __bundle_modules)
---@module Features.Combat.Objects.Defender
local Defender = require("Features/Combat/Objects/Defender")

---@module Game.Timings.SaveManager
local SaveManager = require("Game/Timings/SaveManager")

---@module Features.Combat.Objects.RepeatInfo
local RepeatInfo = require("Features/Combat/Objects/RepeatInfo")

---@module Features.Combat.Objects.HitboxOptions
local HitboxOptions = require("Features/Combat/Objects/HitboxOptions")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@module Game.Latency
local Latency = require("Game/Latency")


---@class PartDefender: Defender
---@field part BasePart
---@field timing PartTiming
---@field touched boolean Determines whether if we touched the timing in the past.
---@field vuid string Visualizer UID.
local PartDefender = setmetatable({}, { __index = Defender })
PartDefender.__index = PartDefender
PartDefender.__type = "Part"

-- Services.
local players = game:GetService("Players")

---Get CFrame.
---@param self PartDefender
---@return CFrame
PartDefender.cframe = function(self)
	return self.timing.uhc and self.part.CFrame or CFrame.new(self.part.Position)
end

---Check if we're in a valid state to proceed with the action.
---@param self PartDefender
---@param options ValidationOptions
---@return boolean
PartDefender.valid = function(self, options)
	if not Defender.valid(self, options) then
		return false
	end

	local function internalNotifyFunction(timing, message)
		if not options.notify then
			return
		end

		return self:notify(timing, message)
	end

	local timing = options.timing
	local action = options.action

	local character = players.LocalPlayer.Character
	if not character then
		return internalNotifyFunction(timing, "No character found.")
	end

	local hoptions = HitboxOptions.new(self.part, timing)
	hoptions.spredict = false
	hoptions.action = action
	hoptions:ucache()

	if not timing.duih or timing.umoa then
		if not self:hc(hoptions, timing.duih and RepeatInfo.new(timing, Latency.rdelay(), self.vuid) or nil) then
			return internalNotifyFunction(timing, "Not in hitbox.")
		end
	end

	return true
end

---Update PartDefender object.
---@param self PartDefender
PartDefender.update = function(self)
	-- Skip if we're not handling delay until in hitbox or we want to use modules.
	if not self.timing.duih or self.timing.umoa then
		return
	end

	-- Deny updates if we already have actions in the queue.
	if #self.tasks > 0 then
		return
	end

	local localPlayer = players.LocalPlayer
	if not localPlayer then
		return
	end

	local character = localPlayer.Character
	if not character then
		return
	end

	local hb = self.timing.hitbox

	hb = Vector3.new((hb.X), (hb.Y), (hb.Z))

	-- Get current hitbox state.
	---@note: If we're using PartDefender, why perserve rotation? It's likely wrong or gonna mess us up.
	local touching, cframe = self:hitbox(
		self:cframe(),
		self.timing.fhb,
		self.timing.hso,
		hb,
		{ character },
		self.timing.htype or Enum.PartType.Block
	)

	if cframe then
		self:visualize(
			self.vuid,
			cframe,
			hb,
			touching and Color3.fromHex("#DDF527") or Color3.fromHex("#2765F5"),
			self.timing.htype or Enum.PartType.Block
		)
	end

	-- Deny updates if we're not touching the part.
	if not touching then
		return
	end

	-- Deny updates if the we were touching the part last and we are touching it now.
	if self.touched and touching then
		return
	end

	-- Ok, set the new state.
	self.touched = touching

	-- Clean all previous tasks.
	self:clean()

	---@note: Start processing the timing. Add the actions if we're not RPUE.
	if not self.timing.rpue then
		return self:actions(self.timing)
	end

	-- Start RPUE.
	local info = RepeatInfo.new(self.timing, Latency.rdelay(), self:uid(10))
	self:srpue(self.entity, self.timing, info)
end

---Create new PartDefender object.
---@param part BasePart
---@param timing PartTiming?
---@return PartDefender?
function PartDefender.new(part, timing)
	if not Configuration.expectToggleValue("EnableAutoDefense") then
		return nil
	end

	local okey = nil

	-- Hotfix for now; too lazy to do it the animation way.
	if part.Name:match("VengefulSlash") then
		okey = "VengefulSlashes"
	end

	local self = setmetatable(Defender.new(), PartDefender)
	self.part = part
	self.timing = timing or self:initial(part, SaveManager.ps, nil, okey or part.Name)
	self.touched = false
	self.vuid = self:uid(10)

	-- Handle no timing.
	if not self.timing then
		return nil
	end

	-- Handle module.
	if self.timing.umoa then
		self:module(self.timing)
	end

	-- Handle no hitbox delay.
	if self.timing.umoa or self.timing.duih then
		return self
	end

	local info = RepeatInfo.new(self.timing, Latency.rdelay(), self:uid(10))

	if self.timing.rpue then
		self:srpue(self.entity, self.timing, info)
	else
		self:actions(self.timing)
	end

	-- Return self.
	return self
end

-- Return PartDefender module.
return PartDefender

end)
__bundle_register("Features/Combat/Objects/AnimatorDefender", function(require, _LOADED, __bundle_register, __bundle_modules)
---@module Features.Combat.Objects.Defender
local Defender = require("Features/Combat/Objects/Defender")

---@module Utility.Signal
local Signal = require("Utility/Signal")

---@module Game.Timings.SaveManager
local SaveManager = require("Game/Timings/SaveManager")

---@module Utility.Logger
local Logger = require("Utility/Logger")
-- Throttled anti-breaker warn: caps anti-breaker console output to 6 lines/sec
-- so an Aggressive-3 flood cannot bury the log. (Was drowning out everything.)
-- Anti-AP-Breaker + swing-trace logging fully removed: emitting rejection
-- reasons to the console let people reverse-engineer the checks, so both loggers
-- are no-ops and every call site passes no descriptive arguments.
local function ptrace() end
-- apbWarn(reason) surfaces WHY a track was dropped when "Reject Reason Notifications"
-- is on. The notifier is assigned below, once Configuration/Library are required; a
-- bare apbWarn() with no reason stays silent, as before.
local apbNotifyReject
local function apbWarn(reason)
	if reason and apbNotifyReject then
		apbNotifyReject(reason)
	end
end




-- A mutated URL still names the REAL asset in its `id=` param -- canonicalize back to
-- rbxassetid://<n> so timing-store lookups recognise a mutated attack instead of
-- treating it as an unknown animation and never defending it. Clean ids pass through
-- unchanged. (This is separate from the Mutated ID *rejection* check, which reads the
-- raw id; recognition must happen regardless of whether that check is on.)
local function canonicalAid(animationId)
	local text = tostring(animationId or "")
	local real = text:match("[?&]id=(%d+)")
	if real then
		return "rbxassetid://" .. real
	end
	return text
end

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

-- One shared RNG for the reaction-rate / speed-changer rolls, reused instead of
-- allocating a fresh Random.new() on every roll during combat.
local rngShared = Random.new()

---@module Game.Timings.PlaybackData
local PlaybackData = require("Game/Timings/PlaybackData")

---@module Game.InputClient
local InputClient = require("Game/InputClient")

---@module Features.Combat.Objects.RepeatInfo
local RepeatInfo = require("Features/Combat/Objects/RepeatInfo")

---@module Game.QueuedBlocking
local QueuedBlocking = require("Game/QueuedBlocking")

---@module Features.Combat.Objects.HitboxOptions
local HitboxOptions = require("Features/Combat/Objects/HitboxOptions")

---@module Utility.OriginalStore
local OriginalStore = require("Utility/OriginalStore")

---@module Features.Combat.EntityHistory
local EntityHistory = require("Features/Combat/EntityHistory")

---@module Features.Combat.StateListener
local StateListener = require("Features/Combat/StateListener")

---@module Game.Latency
local Latency = require("Game/Latency")

---@module Game.Objects.DodgeOptions
local DodgeOptions = require("Game/Objects/DodgeOptions")

---@module GUI.Library
local Library = require("GUI/Library")

-- Reject-reason notifier (see apbWarn near the top). Unthrottled: every rejection
-- reports, so nothing is hidden while diagnosing.
apbNotifyReject = function(reason)
	if not Configuration.expectToggleValue("AntiAPBreakerRejectReasonNotify") then
		return
	end
	pcall(function() Library:Notify("AP reject: " .. tostring(reason), 3) end)
end

---@class AnimatorDefender: Defender
---@field animator Animator
---@field offset number?
---@field entity Model
---@field keyframes Action[]
---@field timing AnimationTiming?
---@field pbdata table<AnimationTrack, PlaybackData> Playback data to be recorded.
---@field rpbdata table<string, PlaybackData> Recorded playback data. Optimization so we don't have to constantly reiterate over recorded data.
---@field manimations table<number, Animation>
---@field track AnimationTrack? Don't be confused. This is the **valid && last** animation track played.
---@field maid Maid This maid is cleaned up after every new animation track. Safe to use for on-animation-track setup.
---@field sct table<AnimationTrack, boolean> Tracks that need to have their speed/weight/fade changed.
---@field tsc table<AnimationTrack, number> Tracks that are saving their last speed.
---@field multiplier table<AnimationTrack, number> Chosen speed multiplier per track.
---@field wmultiplier table<AnimationTrack, number> Chosen target weight per track (presence => already applied).
---@field fdc table<AnimationTrack, boolean> Tracks whose fade time has already been applied (fade-only mode).
---@field pdc table<AnimationTrack, boolean> Tracks whose priority has already been applied.
local AnimatorDefender = setmetatable({}, { __index = Defender })
AnimatorDefender.__index = AnimatorDefender
AnimatorDefender.__type = "Animation"

-- Services.
local players = game:GetService("Players")
local replicatedStorage = game:GetService("ReplicatedStorage")

-- Constants.
local MAX_REPEAT_TIME = 5.0
local HISTORY_STEPS = 5.0
local PREDICT_FACING_DELTA = 3

-- Fake feint (offensive): on our own real attacks, STOP the swing track just before its
-- own hit frame. That flips track.IsPlaying to false, which is the one ungated signal the
-- enemy autoparry's stopped() reads as a feint ("Animation stopped playing") - so it
-- cancels its parry. We never send FeintClick/FeintRelease, and the hit was already fired
-- via the LeftClick remote (server-authoritative, animation-independent), so it still lands.
local FAKE_FEINT_MARGIN = 0.05 -- (crit/mantra) stop this many seconds before the move's hit frame
local FAKE_FEINT_FALLBACK = 0.12 -- (crit/mantra) stop delay when the move exposes no action timing
local FAKE_FEINT_M1_DELAY = 0.05 -- (M1 / fast swings) early stop: the hit fired on the click and the
                                 -- swing is short, so cut it early, before a fast M1 parry can commit

---Is animation stopped? Made into a function for de-duplication.
---@param self AnimatorDefender
---@param track AnimationTrack
---@param timing AnimationTiming
---@param notify boolean? Whether to notify or not.
---@return boolean
AnimatorDefender.stopped = LPH_NO_VIRTUALIZE(function(self, track, timing, notify)
	local function internalNotifyFunction(...)
		if not notify then
			return
		end

		return self:notify(...)
	end

	-- Ghost respect: a track we deliberately kept armed after an early kill (Aggressive 3)
	-- must never have its own stop read as a feint while its ghost window is open.
	if self._ghostTrack == track and os.clock() < (self._ghostUntil or 0) then
		return false
	end

	local overrideData = Library:GetOverrideData(timing.name)
	local rate = (Configuration.expectOptionValue("IgnoreAnimationEndRate") or 0.0)

	if overrideData then
		rate = overrideData.iaer
	end

	-- The previous build gated this "ignore animation end" path behind `not stoppedShort`,
	-- which blocked it whenever a track was cut short -- i.e. EXACTLY what an Aggressive-3
	-- cancel/replay produces. That made Ignore Animation End Rate useless vs A3. Removed so
	-- the humanizer ignores early cancels too and the parry commits through them
	-- react-to-feints behavior). Tradeoff: at high rate you also commit through REAL feints.
	if
		(Configuration.expectToggleValue("AllowFailure") or overrideData)
		and not timing.rpue
		and rngShared:NextNumber(1.0, 100.0) <= rate
		and StateListener.cdodge()
	then
		return false, internalNotifyFunction(timing, "Intentionally ignoring animation end to simulate human error.")
	end

	-- Ghost eligibility is normally decided by the async pollers (mid-play kill checker /
	-- track.Ended handler), which can race a parry that fires between their ticks. Decide
	-- it inline here too so a track that died early never slips through that gap as a feint.
	if not track.IsPlaying and self:_apbGhostOnEarlyKill(track) then
		return false
	end

	-- React to Feints: when the enemy feints (their track stops early), roll this rate; on
	-- success DON'T cancel the scheduled defense - ghost the track so the defense holds and
	-- the parry commits through the feint instead of aborting. The ghost respect at the top
	-- of this function keeps that decision consistent across later calls (no re-roll flicker).
	-- Requires Allow Failure (parry-through); overridable per-timing via frr.
	if not track.IsPlaying
		and (Configuration.expectToggleValue("AllowFailure") or overrideData)
		and not timing.rpue
	then
		local frr = Configuration.expectOptionValue("FeintReactionRate") or 0.0
		if overrideData and overrideData.frr then
			frr = overrideData.frr
		end
		if frr > 0 and rngShared:NextNumber(1.0, 100.0) <= frr then
			local speed = math.abs(track.Speed)
			self._ghostTrack = track
			self._ghostStartedAt = os.clock()
			self._ghostUntil = os.clock() + math.min(track.Length / (speed >= 0.5 and speed or 1), 5)
			return false, internalNotifyFunction(timing, "React to Feints: enemy feinted, holding the defense.")
		end
	end

	if not timing.iae and not track.IsPlaying then
		return true, internalNotifyFunction(timing, "Animation stopped playing.")
	end

	if timing.iae and not timing.ieae and not track.IsPlaying and track.TimePosition < track.Length then
		return true, internalNotifyFunction(timing, "Animation stopped playing early.")
	end
end)

---Repeat conditional. Extra parameter 'track' added on.
---@param self AnimatorDefender
---@param info RepeatInfo
---@return boolean
AnimatorDefender.rc = LPH_NO_VIRTUALIZE(function(self, info)
	---@note: There are cases where we might not have a track. If it's not handled properly, it will throw an error.
	-- Perhaps, the animation can end and we're handling a different repeat conditional.
	if not info.track then
		return apbWarn()
	end

	if self:stopped(info.track, info.timing) then
		return false
	end

	if info.timing.iae and os.clock() - info.start >= ((info.timing.mat / 1000) or MAX_REPEAT_TIME) then
		return self:notify(info.timing, "Max animation timeout exceeded.")
	end

	return true
end)

---Run predict facing hitbox check.
---@param self AnimatorDefender
---@param options HitboxOptions
---@return boolean
AnimatorDefender.pfh = LPH_NO_VIRTUALIZE(function(self, options)
	local root = self.entity:FindFirstChild("HumanoidRootPart")
	if not root then
		return false
	end

	local localRoot = players.LocalPlayer.Character and players.LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
	if not localRoot then
		return false
	end

	if not options.timing.ffh then
		local yrate = EntityHistory.yrate(self.entity)
		if not yrate then
			return false
		end

		if math.abs(yrate) < PREDICT_FACING_DELTA then
			return
		end
	end

	local clone = options:clone()
	clone.hcolor = Color3.new(0, 1, 1)
	clone.mcolor = Color3.new(1, 1, 0)
	clone:ucache()

	local result = false
	local store = OriginalStore.new()

	store:run(root, "CFrame", CFrame.lookAt(root.Position, localRoot.Position), function()
		result = self:hc(clone, nil)
	end)

	return result
end)

---Run past hitbox check.
---@param timing Timing
---@param options HitboxOptions
---@return boolean
AnimatorDefender.phd = LPH_NO_VIRTUALIZE(function(self, timing, options)
	for _, cframe in next, EntityHistory.pstepped(self.entity, HISTORY_STEPS, timing.phds) or {} do
		local clone = options:clone()
		clone.cframe = cframe
		clone.hcolor = Color3.new(0.839215, 0.976470, 0.537254)
		clone.mcolor = Color3.new(0.564705, 0, 1)
		clone:ucache()

		if not self:hc(clone, nil) then
			continue
		end

		return true
	end
end)

---Run our facing extrapolation / interpolation.
AnimatorDefender.fpc = LPH_NO_VIRTUALIZE(function(self, timing, options)
	if timing.duih then
		return false
	end

	if (timing.ffh or timing.pfh) and self:pfh(options) then
		return true
	end

	if timing.phd and self:phd(timing, options) then
		return true
	end
end)

---Check if we're in a valid state to proceed with the action.
---@param self AnimatorDefender
---@param options ValidationOptions
---@return boolean
AnimatorDefender.valid = LPH_NO_VIRTUALIZE(function(self, options)
	if not Defender.valid(self, options) then
		return false
	end

	local timing = options.timing
	local action = options.action

	local function internalNotifyFunction(...)
		if not options.notify then
			return
		end

		return self:notify(...)
	end

	if not self.track then
		return internalNotifyFunction(timing, "No current track.")
	end

	if not self.entity then
		return internalNotifyFunction(timing, "No entity found.")
	end

	local target = self:target(self.entity)
	if not target then
		return internalNotifyFunction(timing, "Not a viable target.")
	end

	local root = self.entity:FindFirstChild("HumanoidRootPart")
	if not root then
		return internalNotifyFunction(timing, "No humanoid root part found.")
	end

	local character = players.LocalPlayer.Character
	if not character then
		return internalNotifyFunction(timing, "No character found.")
	end

	local targetInstance = self.entity:FindFirstChild("Target")

	if
		targetInstance
		and targetInstance.Value ~= character
		and Configuration.expectToggleValue("CheckTargetingValue")
	then
		return internalNotifyFunction(timing, "Not being targeted.")
	end

	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return internalNotifyFunction(timing, "No effect replicator found.")
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return internalNotifyFunction(timing, "No effect replicator module found.")
	end

	if
		not timing.imb
		and root:FindFirstChild("MegalodauntBroken")
		and not players:GetPlayerFromCharacter(self.entity)
	then
		return internalNotifyFunction(timing, "Entity is block broken.")
	end

	if self:stopped(self.track, timing, options.notify) then
		return false
	end

	local hoptions = HitboxOptions.new(root, timing)
	hoptions.spredict = not timing.duih and not timing.dp
	hoptions.ptime = self:fsecs(timing)
	hoptions.action = action
	hoptions.entity = self.entity
	hoptions.visualize = options.visualize
	hoptions:ucache()

	local info = RepeatInfo.new(timing, Latency.rdelay(), self:uid(10))
	info.track = self.track

	local hc = self:hc(hoptions, timing.duih and info or nil)
	if hc then
		return true
	end

	local pc = self:fpc(timing, hoptions)
	if pc then
		return true
	end

	return self:notify(timing, "Not in hitbox.")
end)

-- How long after our hit lands the enemy's swing is treated as cancelled. A hit's
-- stagger/interrupt resolves within a few frames; keep the window tight so a later,
-- genuine swing from the same entity is not wrongly skipped.
local HIT_CANCEL_WINDOW = 0.40

---Resolve (and cache) this entity's Humanoid.
---@param self AnimatorDefender
---@return Humanoid?
local resolveHumanoid = LPH_NO_VIRTUALIZE(function(self)
	local humanoid = self._hbuHumanoid
	if humanoid and humanoid.Parent then
		return humanoid
	end

	humanoid = self.entity and self.entity:FindFirstChildWhichIsA("Humanoid")
	self._hbuHumanoid = humanoid
	return humanoid
end)

---Per-frame: stamp the moment WE land a hit on THIS specific entity. A health drop
---alone is not enough (chip/DoT/another player), so it is gated on StateListener.chit()
---- our own "just dealt damage" flag - which together mean our attack connected here.
---@param self AnimatorDefender
AnimatorDefender.trackHitByUs = LPH_NO_VIRTUALIZE(function(self)
	-- Never against ourselves.
	if players.LocalPlayer.Character and self.entity == players.LocalPlayer.Character then
		return
	end

	local humanoid = resolveHumanoid(self)
	if not humanoid then
		self._hbuLastHealth = nil
		return
	end

	local health = humanoid.Health
	local previous = self._hbuLastHealth
	self._hbuLastHealth = health

	-- Dropped since last frame AND we were dealing damage this window => our hit.
	if previous and health < previous - 0.01 and StateListener.chit() then
		self._hbuHitAt = os.clock()
	end
end)

---Did our hit land on THIS entity within the swing-cancel window?
---@param self AnimatorDefender
---@return boolean
AnimatorDefender.hitByUsRecently = LPH_NO_VIRTUALIZE(function(self)
	return (os.clock() - (self._hbuHitAt or 0)) <= HIT_CANCEL_WINDOW
end)

---Update keyframe handling.
---@param self AnimatorDefender
AnimatorDefender.update = LPH_NO_VIRTUALIZE(function(self)
	-- Keep per-entity "we hit them" state fresh every frame -- but only while Auto
	-- Defense is on. This state is read ONLY by the "Disable If Enemy Hit In M1/Mantra"
	-- filters inside the defense-validation path (Defender.lua), which never runs with
	-- Auto Defense off. With it off, the per-frame Humanoid.Health read for every entity
	-- in the server can never be consulted, so skip it and clear the baseline so the
	-- first frame after re-enabling re-anchors cleanly instead of seeing a stale delta.
	if Configuration.expectToggleValue("EnableAutoDefense") then
		self:trackHitByUs()
	else
		self._hbuLastHealth = nil
	end

	for track, data in next, self.pbdata do
		-- Don't process tracks.
		if not Configuration.expectToggleValue("ShowAnimationVisualizer") then
			self.pbdata[track] = nil
			continue
		end

		-- Check if the track is playing.
		if not track.IsPlaying then
			-- Remove out of 'pbdata' and put it in to the recorded table.
			self.pbdata[track] = nil
			self.rpbdata[tostring(track.Animation.AnimationId)] = data

			-- Continue to next playback data.
			continue
		end

		-- Start tracking the animation's speed.
		data:astrack(track.Speed)
	end

	-- Animation speed changer. Kept byte-for-byte identical to the known-good version - the
	-- weight/fade/priority changers live in their own separate pass below so they can never
	-- alter this path.
	if Configuration.expectToggleValue("AnimationSpeedChanger") then
		local min = Configuration.expectOptionValue("AnimationSpeedMinimum") or 1.0
		local max = Configuration.expectOptionValue("AnimationSpeedMaximum") or 1.3
		local rng = rngShared

		for track, _ in next, self.sct do
			if not track.IsPlaying then
				self.sct[track] = nil
				self.tsc[track] = nil
				self.multiplier[track] = nil
				self.wmultiplier[track] = nil
				self.fdc[track] = nil
				self.pdc[track] = nil
				continue
			end

			if self.tsc[track] == tostring(track.Speed) then
				continue
			end

			local mode = rng:NextInteger(1, 2)
			local generated = nil

			if not self.multiplier[track] and not Configuration.expectToggleValue("SwitchBetweenSpeeds") then
				generated = rng:NextNumber(min, max)
			end

			if not self.multiplier[track] and Configuration.expectToggleValue("SwitchBetweenSpeeds") then
				generated = mode == 1 and min or max
			end

			if not self.multiplier[track] and generated then
				self.multiplier[track] = generated
			end

			local multiplier = self.multiplier[track]
			if not multiplier then
				continue
			end

			if multiplier == 1.0 then
				continue
			end

			local adjusted = track.Speed * multiplier

			track:AdjustSpeed(adjusted)

			self.tsc[track] = tostring(track.Speed)
		end
	end
end)

-- How long an entity must be clean before the APB flag is lifted. The flag is
-- INFORMATIONAL now (notify/UI only) - it never gates dropping. Verdicts are
-- made per-track by the judge in process(), because breakers interleave fake
-- tracks with the ONE real swing; an entity-wide drop throws the real swing
-- out with the garbage (that was the "doesn't parry at all vs breakers" bug).
local APB_FLAG_RESET_WINDOW = 10.0

-- Hardening against resource-exhaustion ("nuker") attacks: these caps bound
-- how much concurrent async work the AP-break pipeline will ever do,
-- independent of whether any individual fake animation looks convincing.
-- A flood attack doesn't need to fool the detection logic below - it only
-- needs enough raw volume of known-animation events to overwhelm the
-- pipeline with spawned coroutines, table growth, and notifications. These
-- limits exist purely to bound worst-case resource usage, not to detect
-- anything - they're a circuit breaker, separate from the actual detection.
local MAX_CONCURRENT_APB_TASKS_PER_ENTITY = 24 -- BUFF: 8 -> 24, validate far more concurrently
local GLOBAL_APB_RATE_LIMIT = 150 -- BUFF: 40 -> 150, don't let heavy floods slip past the circuit breaker
local GLOBAL_APB_RATE_WINDOW = 0.1 -- seconds
local globalApbTimestamps = {}

---Global circuit breaker: returns true if the AP-break pipeline is already
---processing more known-animation events than any legitimate combat scenario
---would produce, regardless of source. An attacker doesn't need to fool the
---per-entity frequency-flagging logic - they just need enough raw volume
---(potentially spread across many different animation IDs, or even multiple
---entities) to overwhelm the pipeline. This caps the total processed rate
---no matter where it's coming from.
---@return boolean
local function globalApbRateLimited()
	local now = os.clock()
	local cutoff = now - GLOBAL_APB_RATE_WINDOW
	local timestamps = globalApbTimestamps
	local writeIdx = 0
	for i = 1, #timestamps do
		if timestamps[i] > cutoff then
			writeIdx = writeIdx + 1
			timestamps[writeIdx] = timestamps[i]
		end
	end
	for i = #timestamps, writeIdx + 1, -1 do
		timestamps[i] = nil
	end
	timestamps[writeIdx + 1] = now
	return (writeIdx + 1) > GLOBAL_APB_RATE_LIMIT
end


-- How long to wait for a frozen windup (speed ~0) to come alive before giving up.
-- Was 0.50s, which silently dropped any charge held longer than half a second:
-- no hitbox, no notification. Charged attacks are held well past that.
local WINDUP_POLL_WINDOW = 3.0
-- [Masked Track] how long the judge LIVE-polls a track's priority, waiting for it
-- to rise to the top before calling it a covered decoy. The breaker boosts its real
-- swing to Action4 a frame or two after AnimationPlayed (later under lag); the poll
-- breaks the instant the boost lands, so a real swing waits only the few frames it
-- takes to uncover -- only genuine decoys sit out the full window.
local MASKED_WATCH_WINDOW = 0.2
-- Fade-time ("Time") check thresholds. Instead of pattern-matching one magic
-- fade value, the judge measures the ACTUAL weight ramp across its two samples
-- and projects how long the fade would take to reach the weight target. A real
-- fade is ~0.1s; a fade-time breaker stretches it to hundreds of ms, or - with
-- an absurd fade like the AP Breaker's 9999999s - effectively forever. Only
-- tracks still well under their weight target are considered, so a real swing
-- that has already ramped is never touched.
local FADE_TIME_RATIO_SUSPECT = 0.7 -- only suspect tracks under this weight ratio (raised 0.6->0.7: catch baits that ramp a little higher before stalling)
local FADE_TIME_RAMP_RATE = 0.05    -- weight/sec at or below this = no ramp (frozen fade)
-- The projected-fade ceiling itself is the user-facing "Time < Xms" slider
-- (cfg.timeMax); anything projecting a longer fade than that is bait.


-- ============================================================================
-- Anti-AP Breaker configuration
-- ----------------------------------------------------------------------------
-- Everything the old BASE/AGGRESSIVE/EXTREME tier system hard-coded is now
-- user-driven:
--   * "AntiAPBreakerChecks" -> multi dropdown, decides WHICH checks run.
--                              (empty selection == every check on.)
--   * the sliders below      -> each check's threshold.
-- readApbConfig() snapshots all of it once per track so the async judge reads a
-- stable set of values instead of re-querying config mid-verdict.
-- ============================================================================
-- Every check exposed in the UI is toggled on its own (the old "Aggressive" bundle
-- was unpacked). Threshold checks read their slider values in readApbConfig(); the
-- rest are pure on/off. This table is the fallback selection when the option was
-- never registered, so protection is never silently off on a fresh profile.
local APB_CHECK_DEFAULTS = {
	["Weight Target"]    = true,
	["Weight Ramp"]      = true,
	["Speed"]            = true,
	["Time"]             = true,
	["Animation Stop"]   = true,
	["Post-Check Ramp"]  = true,
	["Churn"]            = true,
	["Ghost Track"]      = true,
	-- Masked Track (accept a known attack only while it's the highest-priority track
	-- playing) is the flood filter now, so it ships ON.
	["Masked Track"]     = true,
}

local function apbNum(name, fallback)
	local value = Configuration.expectOptionValue(name)
	return (type(value) == "number") and value or fallback
end

local function readApbConfig()
	local checks = Configuration.expectOptionValue("AntiAPBreakerChecks")
	-- Missing option (never registered) -> all checks on, so protection is never
	-- silently off. An explicitly EMPTY set means the user turned every check off.
	if type(checks) ~= "table" then
		checks = APB_CHECK_DEFAULTS
	end
	return {
		checks       = checks,
		parryThrough = Configuration.expectToggleValue("AllowFailure") == true,
		-- Weight Target check — user sliders.
		wtMin        = apbNum("ApbWeightTargetMin", 0.35),
		wtMax        = apbNum("ApbWeightTargetMax", 5.0),
		-- Speed check — user sliders.
		speedMin     = apbNum("ApbSpeedMin", 0.35),
		speedMax     = apbNum("ApbSpeedMax", 3.0),
		-- Time check user slider (max implied fade time in ms, stored as seconds).
		timeMax      = apbNum("ApbTimeMax", 250) / 1000,
		-- Animation Stop: only a track killed within this many seconds of its start counts
		-- as a stop+replay bait (humans feint 100ms+ in, so a sub-0.05s death is a script
		-- kill, not a feint). A later kill is left to the ghost / feint logic instead.
		animStopTime = apbNum("ApbAnimationStopTime", 0.05),
		-- Masked Track: a higher-priority track only counts as a real COVER (able to mask
		-- our swing) if it reads like a genuine animation. A fake boosted up just to keep
		-- us looking masked is ignored, so the real swing under it can uncover. Ignore a
		-- cover playing slower than maskSpeedMin, rendering under maskWeightMin weight, or
		-- fading in slower than maskFadeMax (implied fade, ms -> seconds).
		maskSpeedMin  = apbNum("ApbMaskIgnoreSpeed", 0.1),
		maskWeightMin = apbNum("ApbMaskIgnoreWeight", 0.25),
		maskFadeMax   = apbNum("ApbMaskIgnoreFade", 1000) / 1000,
		-- Aggressive 2 user sliders. Concurrency = how many distinct known attacks have
		-- to be in flight at once before the sieve engages (a real player can only
		-- swing one). Jitter = how close to the flood's emission grid an arrival has
		-- to land before it's called machine-timed, in seconds.
		a2Concurrency = apbNum("ApbA2Concurrency", 3),
		a2Jitter      = apbNum("ApbA2Jitter", 20) / 1000,
		-- Weight Ramp sliders (uncollapsed from the old "Aggressive" bundle).
		wtSuspicious = apbNum("ApbWeightSuspiciousBelow", 0.9),
		rampFast     = apbNum("ApbRampFastPass", 0.25),
		rampFloor    = apbNum("ApbRampFloor", 0.30),
		-- Post-Check Ramp slider.
		flatWeight   = apbNum("ApbFlatWeightFloor", 0.15),
		-- Frequency Spike slider.
		freqPerSec   = apbNum("ApbFreqSpikePerSec", 8),
		-- Judge sample delays.
		sample1      = apbNum("ApbSample1Delay", 0.03),
		sample2      = apbNum("ApbSample2Delay", 0.06),
	}
end

local function apbEnabled(cfg, name)
	-- Every check is toggled on its own now (the old "Aggressive" bundle was unpacked
	-- back into individual entries in the Checks dropdown).
	return cfg.checks[name] == true
end

---Record one piece of AP-break evidence (a rejected fake track, a churn
---restart, a frequency spike). Purely informational: flags the entity and
---notifies the user. NEVER gates dropping - fake/real verdicts are made
---per-track by the judge in process().
---
---(Replaces the old learned "AP break profile". That profile taught itself
---min/max speed+weight envelopes from rejected samples - but breakers like
---rain jitter their fakes at speed 0.90-1.10x, the SAME band real attacks
---play in, so the learned envelope grew to swallow every legitimate swing
---and the defender silently dropped all of them. Self-poisoning by design;
---removed outright.)
---@param self AnimatorDefender
function AnimatorDefender:_apbEvidenceEvent()
	local now = os.clock()
	local ev = self._apbEvidence
	local writeIdx = 0
	for i = 1, #ev do
		if now - ev[i] <= 1.0 then
			writeIdx = writeIdx + 1
			ev[writeIdx] = ev[i]
		end
	end
	for i = #ev, writeIdx + 1, -1 do
		ev[i] = nil
	end
	ev[writeIdx + 1] = now

	-- Detection level: how many AP-break evidence events must land inside the ~1s
	-- window before we flag/notify. Raised from 3 to 6 to stop false firing on normal
	-- combat (a couple of coincidental hits no longer trips it).
	if writeIdx + 1 >= 6 then
		if not self._apbFlagged then
			self._apbFlagged = true
			apbWarn()
		end
		self._apbFlaggedAt = now

		if Configuration.expectToggleValue("AntiAPBreakerNotify") then
			if not self._apbNotifiedAt or (now - self._apbNotifiedAt) > 10 then
				self._apbNotifiedAt = now
				Library:Notify(string.format("%s is attempting to AP break you.", self.entity.Name), 10)
			end
		end
	elseif self._apbFlagged and now - self._apbFlaggedAt > APB_FLAG_RESET_WINDOW then
		self._apbFlagged = false
		apbWarn()
	end
end

---Passive AP-break detection (churn + frequency spike) for a known animation id.
---Pure bookkeeping + evidence/notify - never rejects or drops anything - so it's safe
---to run even when the full Anti-AP Breaker pipeline (validation/dropping) is switched
---off. This is what lets "AP Break Notifications" work independently of the main
---"Anti-AP Breaker" toggle.
---@param self AnimatorDefender
---@param aid string
function AnimatorDefender:_apbTrackKnownAnimation(aid, cfg)
	local now = os.clock()

	-- Reuse / restart-churn bookkeeping. THE critical change: rapid reuse
	-- of the same animation id is NEVER hard-rejected anymore. Stop+replay
	-- breakers (allium passive: Stop(0), replay ~0.13s later; rain: restart
	-- churn several times a second) deliberately replay the SAME swing -
	-- and one of those replays IS the real attack. The old "reused too
	-- soon" reject was throwing away exactly the instance that carried the
	-- hit, which is why nothing got parried while a breaker ran.
	--
	-- Instead: remember the FIRST play of each swing. When impossibly-fast
	-- reuse marks the swing as churned, later validation re-anchors its
	-- action timing to that original play time - the server-side hit
	-- follows the ORIGINAL swing start, no matter how many times the
	-- breaker restarts the visual (and restarts reset TimePosition to 0,
	-- so TimePosition alone can't recover the true elapsed time).
	local firstPlay = self._apbFirstPlay[aid]
	local lastMoveTime = self._apbLastMoveTime[aid]
	self._apbLastMoveTime[aid] = now
	local reuseGap = lastMoveTime and (now - lastMoveTime) or math.huge

	if firstPlay and now - firstPlay.t <= 2.0 and reuseGap <= 0.8 then
		-- Same swing again within one swing's span: a replay/restart of an
		-- attack already in flight. Keep the original anchor.
		if reuseGap < 0.35 then
			-- No real weapon re-fires the identical swing this fast: churn.
			-- Always keep the timing anchor; only raise evidence if Churn is on.
			firstPlay.churn = true
			if not cfg or apbEnabled(cfg, "Churn") then
				self:_apbEvidenceEvent()
			end
		end
	else
		-- Fresh swing (or the old one is stale): new anchor.
		self._apbFirstPlay[aid] = { t = now, churn = false }
	end

	-- Frequency-based detection.
	local timestamps = self._apbAnimTimestamps
	timestamps[#timestamps + 1] = now

	-- Clean old timestamps (keep last 2 seconds).
	local cutoff = now - 2
	local timestampCount = #timestamps
	local firstValidIdx = 0
	for i = 1, timestampCount do
		if timestamps[i] > cutoff then
			firstValidIdx = i
			break
		end
	end

	if firstValidIdx > 1 then
		local newTimestamps = {}
		local writeIdx = 0
		for i = firstValidIdx, timestampCount do
			writeIdx = writeIdx + 1
			newTimestamps[writeIdx] = timestamps[i]
		end
		self._apbAnimTimestamps = newTimestamps
		timestamps = newTimestamps
	elseif firstValidIdx == 0 and timestampCount > 0 then
		timestamps = {}
		self._apbAnimTimestamps = timestamps
	end

	-- Count animations in the last 1 second. Timestamps are chronologically
	-- sorted (append-only), so entries within the last 1 second are always
	-- a contiguous suffix - scan backward and stop at the first one that's
	-- too old instead of scanning the full (up to 2 second) list every time.
	local recentCount = 0
	for i = #timestamps, 1, -1 do
		if now - timestamps[i] <= 1 then
			recentCount = recentCount + 1
		else
			break
		end
	end

	-- Frequency spike: 5+ known attacks in a second is flood-tier volume no
	-- real combat pacing produces. Feed it to the evidence tracker, which
	-- handles flagging + the user notification (with its own cooldown).
	-- Evidence is informational only - it never drops anything, so
	-- parry-through / AllowFailure semantics are unaffected.
	-- Always on: it is notify-only (never rejects anything), so there is no reason to
	-- let it be switched off -- hence no entry in the Checks dropdown either. Only the
	-- per-second threshold stays user-facing.
	local freqThreshold = (cfg and cfg.freqPerSec) or 8
	if recentCount >= freqThreshold then
		self:_apbEvidenceEvent()
	end

	-- Hand the per-second rate back so the Spam Guard can actively drop floods
	-- (this bookkeeping otherwise only feeds notify-level evidence).
	return recentCount
end

-- ============================================================================
-- A2 COUNTER — direct counter to Experimental AP Breaker "Aggressive 2".
--
-- Aggressive 2 plays decoys out of a pooled track list at a fixed rate:
--
--     chosenTrack.Priority = Enum.AnimationPriority.Action
--     chosenTrack:Play(0.1, 1, 1)          -- fade 0.1, weight 1, speed 1
--
-- Weight target 1.0, speed 1.0, Action priority, a 0.1s fade. Every per-track
-- metric the rest of this file measures reads EXACTLY like a real swing, which
-- is why Weight Target / Speed / Weight Ramp can't separate them and Spam Guard
-- ends up drop-everything. It also cycles a pool of up to 200 ids, so per-id
-- rate limiting is useless too — an individual id repeats maybe once every
-- twenty seconds.
--
-- What it CANNOT hide is structural:
--
--  1. MASK TWIN. Its applyMasks() replays every real track as a second copy one
--     priority tier above the flood, mirroring TimePosition frame for frame, so
--     his own swings still render over his decoys. Decoys are excluded from
--     masking (trackPoolSet). So a known attack id that arrives TWICE inside one
--     swing at two different priorities is his real attack — announced by his
--     own masking code. This is a positive ID on the real swing, not a guess
--     about the fakes.
--
--  2. FADE SIGNATURE. Those mask copies are played with `mask:Play(0, ...)` —
--     fade 0, so weight is already at target on the first read. Decoys are
--     mid-ramp through their 0.1s fade. Turning Mask Visual off removes both
--     signals but leaves his own screen buried under the flood, which is the
--     point: the counter forces a choice between hidden and effective.
--
--  3. EMISSION GRID. The flood comes off a fixed accumulator (interval =
--     1 / intensity) inside RenderStepped, so its arrivals form a periodic
--     train. A human swing lands off that grid. Phase is measured against the
--     last known DECOY rather than the last arrival, so one real swing slipping
--     through doesn't shift the reference and drag the next decoy off-grid
--     with it.
--
-- Verdicts are "real" / "decoy" / "dupe" / "clear". Nothing here drops anything
-- outside a detected flood, and an inconclusive read inside one returns "clear"
-- (process it) — a marginal parry attempt beats a silently dropped real attack.
-- ============================================================================
local A2_TWIN_WINDOW    = 0.20 -- mask copy lands within a frame or two of its source
local A2_REAL_HOLD      = 1.50 -- how long a beaconed id stays trusted for that swing
local A2_ARRIVAL_MEMORY = 2.00
local A2_DEDUPE         = 0.30 -- source + mask copy are one swing, defend it once
local A2_INSTANT_RATIO  = 0.85 -- fade-0 mask copy is already at target weight

---Aggressive 2 flood sieve. Runs before any counting so decoys can never inflate
---the rate that Spam Guard drops real swings on.
---@param self AnimatorDefender
---@param track AnimationTrack
---@param aid string
---@param cfg table
---@return string "real" | "decoy" | "dupe" | "clear"
function AnimatorDefender:_a2Verdict(track, aid, cfg)
	local now = os.clock()

	-- One swing, one defense. The mask twin carries the same id and the same
	-- TimePosition as its source, so whichever copy landed first already owns it.
	local accepted = self._a2Accepted[aid]
	if accepted and (now - accepted) <= A2_DEDUPE then
		return "dupe"
	end

	-- Roll the arrival window and count how many distinct known attacks this
	-- entity has in flight. A real player has one, plus its mask copy.
	local kept, seen, distinct = {}, {}, 0
	for _, arrival in ipairs(self._a2Arrivals) do
		if now - arrival.t <= A2_ARRIVAL_MEMORY then
			kept[#kept + 1] = arrival
			if now - arrival.t <= 1.0 and not seen[arrival.aid] then
				seen[arrival.aid] = true
				distinct = distinct + 1
			end
		end
	end
	if not seen[aid] then
		distinct = distinct + 1
	end

	local previousArrival = kept[#kept]
	kept[#kept + 1] = { t = now, aid = aid }
	self._a2Arrivals = kept

	-- [1] Mask twin — same id, two priorities, inside one swing.
	local previous = self._a2IdLast[aid]
	self._a2IdLast[aid] = { t = now, priority = track.Priority }
	if previous and (now - previous.t) <= A2_TWIN_WINDOW and previous.priority ~= track.Priority then
		self._a2Real[aid] = now + A2_REAL_HOLD
		self._a2Accepted[aid] = now
		return "real"
	end

	-- Still inside a swing already identified as real.
	local trusted = self._a2Real[aid]
	if trusted and now < trusted then
		self._a2Accepted[aid] = now
		return "real"
	end

	-- Not a flood: leave the normal pipeline alone entirely.
	if distinct < cfg.a2Concurrency then
		self._a2Accepted[aid] = now
		return "clear"
	end

	-- [2] Fade signature — at target weight on the first read means fade 0.
	local weightTarget = track.WeightTarget
	if weightTarget > 0 and (track.WeightCurrent / weightTarget) >= A2_INSTANT_RATIO then
		self._a2Real[aid] = now + A2_REAL_HOLD
		self._a2Accepted[aid] = now
		return "real"
	end

	-- [3] Emission grid. Estimate the flood's period from recent gaps, then test
	-- this arrival's phase against the last confirmed decoy.
	local gaps = {}
	for index = #kept - 1, math.max(2, #kept - 9), -1 do
		local gap = kept[index].t - kept[index - 1].t
		if gap > 0 then
			gaps[#gaps + 1] = gap
		end
	end

	if #gaps >= 4 then
		table.sort(gaps)
		local period = gaps[math.ceil(#gaps / 2)]
		if period > 0.005 then
			local reference = self._a2LastDecoy
			if not reference or (now - reference) > 1.0 then
				reference = previousArrival and previousArrival.t or nil
			end

			if reference then
				local elapsed = (now - reference) / period
				local offGrid = math.abs(elapsed - math.floor(elapsed + 0.5)) * period
				if offGrid <= cfg.a2Jitter then
					self._a2LastDecoy = now
					return "decoy"
				end

				self._a2Real[aid] = now + A2_REAL_HOLD
				self._a2Accepted[aid] = now
				return "real"
			end
		end
	end

	-- Inconclusive inside a flood: process it. Dropping here would recreate the
	-- exact failure this check exists to fix.
	self._a2Accepted[aid] = now
	return "clear"
end

---True only once the track is gone from its Humanoid's live playing set. track.IsPlaying
---can stay true for a track that was already stop+replay killed server-side, so kill
---detection needs to check the actual animator, not the property.
---@param self AnimatorDefender
---@param track AnimationTrack
---@return boolean
function AnimatorDefender:isFullyDead(track)
	local humanoid = self.entity:FindFirstChild("Humanoid")
	if not humanoid then
		return not track.IsPlaying
	end

	local ok, playing = pcall(function() return humanoid:GetPlayingAnimationTracks() end)
	if not ok or type(playing) ~= "table" then
		return not track.IsPlaying
	end

	return table.find(playing, track) == nil
end

---Convert an attack track that was killed mid-flight with no feint (Aggressive 3) into a
---"ghost": keep the defense armed for a window based on the track's remaining length, so
---the incoming hit still gets parried even though the visual animation was cut. Returns
---true when the track is (or has just been) ghosted.
---@param self AnimatorDefender
---@param track AnimationTrack
---@return boolean converted
function AnimatorDefender:_apbGhostOnEarlyKill(track)
	if self._ghostTrack == track and os.clock() < (self._ghostUntil or 0) then
		return true
	end

	if not Configuration.expectToggleValue("AntiAPBreakerEnabled") then
		return false
	end

	if not players:GetPlayerFromCharacter(self.entity) then
		return false
	end

	-- Killed within the first 0.2s (before a human could realistically feint) OR killed
	-- after already ramping to (near) full weight. A swing that completed its weight ramp
	-- has passed its hit frame -- the hit is server-side and lands no matter when the
	-- animation is then cut -- so a later Stop() is a stop+replay bait, not a feint. Only a
	-- PARTIAL-weight kill past 0.2s reads as a genuine feint (cancelled before the hit).
	-- Peak weight is tracked by the pollers in processValidated across the swing's life.
	if track.TimePosition > 0.2 and (self._trackPeakWeight or 0) < apbNum("ApbGhostKillMinWeight", 0.8) then
		return false
	end

	local speed = math.abs(track.Speed)
	self._ghostTrack = track
	self._ghostStartedAt = os.clock()
	self._ghostUntil = os.clock() + math.min(track.Length / (speed >= 0.5 and speed or 1), 5)

	Logger.warn(
		"(%s) %s's attack track was killed mid-flight with no feint (Aggressive 3) -- ghost processing.",
		track.Animation.AnimationId,
		self.entity.Name
	)

	return true
end

---Virtualized processing checks.
---@param track AnimationTrack
---@return boolean
function AnimatorDefender:pvalidate(track)
	if not Configuration.expectToggleValue("AntiAPBreakerEnabled") then
		return true
	end

	local cfg = readApbConfig()

	if track.Priority == Enum.AnimationPriority.Core then
		return false
	end

	local isComingFromPlayer = players:GetPlayerFromCharacter(self.entity)

	-- Only run AP breaking checks on known animations in the timing database.
	local isKnownAnimation = isComingFromPlayer and SaveManager.as:index(canonicalAid(track.Animation.AnimationId)) ~= nil

	-- Charged windup handling. Structural, not a user check: WT < 1.0 at speed 0
	-- is impossible for a real animation, and a real charged windup must be polled
	-- until it releases before we can judge it.
	if isKnownAnimation and math.abs(track.Speed) < 0.05 then
		-- WT >= 1.0: legit windup (charged attack), poll until speed changes.
		if track.WeightTarget >= 1.0 then
			if self._apbActiveTasks >= MAX_CONCURRENT_APB_TASKS_PER_ENTITY then
				return false
			end
			local myTrack = track
			local myAid = tostring(track.Animation.AnimationId)
			self._apbActiveTasks = self._apbActiveTasks + 1
			task.spawn(function()
				local start = os.clock()
				while os.clock() - start < WINDUP_POLL_WINDOW do
					task.wait(0.02)
					-- A STOPPED track is not a released windup: Speed reverts to a nonzero
					-- default once a track stops, so a speed-only check mistakes a dead
					-- track for a resumed one and schedules a defense on a corpse.
					if self:isFullyDead(myTrack) then
						self._apbActiveTasks = self._apbActiveTasks - 1
						return
					end

					if math.abs(myTrack.Speed) >= 0.05 then
						self._apbActiveTasks = self._apbActiveTasks - 1
						if not self:pvalidate(myTrack) then return end
						self:processValidated(myTrack, myAid, os.clock() - start)
						return
					end
				end
				self._apbActiveTasks = self._apbActiveTasks - 1
			end)
			return false
		end

		-- WT < 1.0 at speed 0: no legit animation does this, reject.
		return false
	end

	-- [CHECK: Speed] playback-speed ceiling.
	if apbEnabled(cfg, "Speed") and isKnownAnimation and math.abs(track.Speed) > cfg.speedMax then
		apbWarn("speed ceiling")
		return false
	end

	-- A MONSTER animation (anything in the Mobs asset folder) playing on a PLAYER rig is
	-- never legit -- it's a breaker feeding us a mob move (e.g. sharko_kick_v2) so the
	-- autoparry schedules a defense on a mob's timing that no player hit will ever match.
	-- Canonicalize first: the breaker mutates the URL (?attack=..&slot=..&id=<real>) so the
	-- raw AnimationId never equals the clean rbxassetid the map is keyed by -- that mutation
	-- is exactly what let this slip past while still resolving to a known attack. Matching on
	-- the canonical id closes it without touching the (clean) legit-attack path.
	if isComingFromPlayer and self.manimations[canonicalAid(track.Animation.AnimationId)] ~= nil then
		apbWarn("mob animation")
		return false
	end

	return true
end

---Animation speed / weight / fade changer registration.
---@param self AnimatorDefender
---@param track AnimationTrack
AnimatorDefender.asc = LPH_NO_VIRTUALIZE(function(self, track)
	if not Configuration.expectToggleValue("AnimationSpeedChanger") then
		return
	end

	if
		Configuration.expectToggleValue("LimitToAPAnimations")
		and not SaveManager.as:index(canonicalAid(track.Animation.AnimationId))
	then
		return
	end

	self.sct[track] = true
end)

---Process animation track.
---@param self AnimatorDefender
---@param track AnimationTrack
AnimatorDefender.process = function(self, track)
	local isLocalPlayer = players.LocalPlayer.Character and self.entity == players.LocalPlayer.Character

	if isLocalPlayer then
		self:asc(track)

		-- Log local player animations to builder logger.
		local aid = canonicalAid(track.Animation.AnimationId)
		self:initial(self.entity, SaveManager.as, self.entity.Name, aid)

		-- Fake feint on our own real attacks. Only for known offensive moves (M1 / Critical
		-- / Mantra) so idle/run/utility animations are never touched. Stop the swing track
		-- just before its own hit frame: that flips IsPlaying to false, which the enemy
		-- autoparry reads as a feint (stopped()) and cancels its parry. The hit was already
		-- sent by the attack remote and is server-authoritative, so it still lands.
		if Configuration.expectToggleValue("FakeFeint") then
			local timing = SaveManager.as:index(aid)
			local isKnownAttack = timing
				and (timing.tag == "M1" or timing.tag == "Critical" or timing.tag == "Mantra")

			-- Only fake-feint animations registered in the auto defense timing database. The old
			-- "broad catch" also grabbed any Action-tier / attack-effect swing even when it wasn't
			-- in the DB - that's what was still stopping unregistered animations, so it's dropped.
			local isAttack = isKnownAttack

			if isAttack then
				-- PLAY-THEN-CUT fake feint. Let the swing play out to ~70% of its length so it
				-- looks like a real, near-complete attack to EVERYONE (you and other players) -
				-- important because a hit with no matching animation is a clip/ban risk - then
				-- Stop(0) it near the end. The stop still flips IsPlaying=false late in the swing,
				-- which the enemy autoparry reads as a feint and drops its parry, while the hit
				-- (already fired server-side via the attack remote) lands. No frame-0 pinning, so
				-- no jitter: the animation genuinely plays, it just ends early.
				local FAKE_FEINT_PLAY_FRACTION = 0.70 -- how much of the swing to let play before cutting
				local FAKE_FEINT_MIN_STOP = 0.05     -- floor so ultra-short swings still play a real beat

				local pinnedTrack = track
				task.spawn(function()
					-- Resolve the swing length. track.Length can read 0 for a frame or two while the
					-- animation loads, so wait briefly for it to populate.
					local length = pinnedTrack.Length
					local waited = 0
					while (not length or length <= 0) and waited < 0.2 do
						waited = waited + task.wait()
						length = pinnedTrack.Length
					end

					-- How long to let it play. Fraction of the real length, with a small floor.
					local playFor
					if length and length > 0 then
						playFor = math.max(FAKE_FEINT_MIN_STOP, length * FAKE_FEINT_PLAY_FRACTION)
					else
						playFor = 0.25 -- unknown length: sane default that still shows most of a swing
					end

					task.wait(playFor)
					if pinnedTrack.IsPlaying then
						-- Stop with a short fade (not 0) so the attack track blends OUT smoothly
						-- back into locomotion instead of hard-snapping and freezing on the last
						-- pose (the "statue"). The fade still drops IsPlaying, so the enemy still
						-- reads the feint. Then poke the humanoid's Animate script so it re-asserts
						-- the idle/run animation immediately rather than waiting for the next state
						-- change.
						pinnedTrack:Stop(0.12)

						local character = players.LocalPlayer.Character
						local humanoid = character and character:FindFirstChildWhichIsA("Humanoid")
						local animateScript = character and character:FindFirstChild("Animate")
						if humanoid then
							-- Toggling Animate off/on forces the game's locomotion animator to
							-- rebuild and replay the correct movement/idle track, clearing any
							-- stuck pose left over from the interrupted attack.
							if animateScript then
								animateScript.Disabled = true
								task.defer(function()
									animateScript.Disabled = false
								end)
							end
							-- Re-fire the current movement state so idle/run visibly resumes.
							pcall(function()
								humanoid:ChangeState(Enum.HumanoidStateType.Running)
							end)
						end
					end
				end)
			end
		end

		return
	end

	-- Distance gate: skip all the AP-break tracking/detection machinery for
	-- entities far beyond any possible attack range. Every animator in the
	-- server gets a defender with no distance filtering, so without this,
	-- players thousands of studs away (who could never actually hit you)
	-- still trigger the full frequency-tracking + multiple task.delay checks
	-- on every single animation they play - real, measurable overhead in a
	-- populated server. 200 studs is generous enough to never cut off an
	-- actual threat (real attack ranges here are single/low-double digits).
	do
		local localCharacter = players.LocalPlayer.Character
		local localRoot = localCharacter and localCharacter:FindFirstChild("HumanoidRootPart")
		local entityRoot = self.entity:FindFirstChild("HumanoidRootPart")
		if localRoot and entityRoot then
			if (localRoot.Position - entityRoot.Position).Magnitude > 200 then
				return
			end
		end
	end

	-- Unconditional 0-weight filter. A track fading to WeightTarget 0 is never a real,
	-- committed swing -- it's the anti-AP-breaker bait (0-weight characteristic). This runs
	-- BEFORE and INDEPENDENT of AntiAPBreakerEnabled, so auto parry always drops 0-weight
	-- tracks even with the whole anti-breaker system switched off. No other check.
	if track.WeightTarget <= 0.050 then
		return
	end

	-- AP break protection: background detection + blocking gate.
	local rawAid = tostring(track.Animation.AnimationId)
	local aid = canonicalAid(rawAid)
	local isPlayer = players:GetPlayerFromCharacter(self.entity)
	local isKnownAnimation = isPlayer and SaveManager.as:index(aid) ~= nil

	if Configuration.expectToggleValue("AntiAPBreakerEnabled") then
		-- Which checks run + their thresholds come straight from the UI now (the
		-- "Checks" dropdown + the sliders under it). No fixed tiers anymore - each
		-- check is toggled on its own. Snapshotted once so the async judge below
		-- reads a stable set of values.
		local cfg = readApbConfig()
		local apbParryThrough = cfg.parryThrough

		-- [CHECK: Ghost Track] a genuinely-playing track is ALWAYS present in its
		-- animator's own playing set. Some breakers fake the AnimationPlayed event
		-- (firesignal) or drive a detached animator, producing a track that reports
		-- IsPlaying=true yet never appears in GetPlayingAnimationTracks() - impossible
		-- for a real animation. Only that direction is flagged (listed-but-stopped is a
		-- normal fade-out). Player tracks only; the list read is skipped when off.
		if apbEnabled(cfg, "Ghost Track") and isPlayer and track.IsPlaying then
			local animator = self.animator
			local listed = true
			if animator then
				local ok, playing = pcall(function() return animator:GetPlayingAnimationTracks() end)
				if ok and type(playing) == "table" then
					listed = table.find(playing, track) ~= nil
				end
			end
			if not listed then
				apbWarn("ghost track")
				self:_apbEvidenceEvent()
				return
			end
		end

		-- [CHECK: Weight Target] a weight target outside [min, max] is a definitive
		-- spoof - hard reject on both ends. Inside the band is merely SUSPICIOUS and
		-- flows to the judge, which demands a real weight ramp before validating.
		-- Fires even in parry-through: out-of-band weight is a spoof, not a feint.
		if apbEnabled(cfg, "Weight Target") and isKnownAnimation
			and (track.WeightTarget < cfg.wtMin or track.WeightTarget > cfg.wtMax) then
			apbWarn("weight target")
			return
		end

		if isKnownAnimation then
			-- NOTE: the global rate limiter and the Aggressive 2 flood sieve were removed
			-- from this path. With mutated ids now recognised, both were dropping the real
			-- swing along with the flood. Masked Track (accept only the highest-priority
			-- track playing) does the flood filtering now -- decoys sit at Action, the real
			-- swing gets boosted to Action4, so only it survives.
			-- Passive bookkeeping only (churn anchor + frequency-spike evidence).
			-- Spam Guard was removed: its counter was entity-wide and id-agnostic, so a
			-- flood's decoys and the real swing landed in the same bucket and it dropped
			-- the genuine attack upstream of the judge that would have cleared it.
			self:_apbTrackKnownAnimation(aid, cfg)

			-- Store isKnown alongside the evaluation entry so the update() loop
			-- can guard clean() calls without re-querying SaveManager each frame.
			self._evaluationData[track] = { t = tick(), isKnown = true }

			-- (The old standalone background-WeightCurrent counter and FadeTime
			-- inference task are gone: both are folded into the judge below as
			-- ramp checks on each track's own verdict, so slow-fade detection no
			-- longer feeds an entity-wide counter that punished later real swings.)

			-- Exempt legit windups: speed 0 + WT >= 1.0 (charged attacks).
			if math.abs(track.Speed) < 0.05 and track.WeightTarget >= 1.0 then
				if self._apbActiveTasks >= MAX_CONCURRENT_APB_TASKS_PER_ENTITY then
					return
				end
				local myTrack = track
				local myAid = aid
				self._apbActiveTasks = self._apbActiveTasks + 1
				task.spawn(function()
					local start = os.clock()
					while os.clock() - start < WINDUP_POLL_WINDOW do
						task.wait(0.02)
						-- A STOPPED track is not a released windup: Speed reverts to a nonzero
						-- default once a track stops, so a speed-only check mistakes a dead
						-- track for a resumed one and schedules a defense on a corpse (which
						-- handle() then rejects as "attack stopped (feint)").
						if self:isFullyDead(myTrack) then
							self._apbActiveTasks = self._apbActiveTasks - 1
							return
						end

						if math.abs(myTrack.Speed) >= 0.05 then
							self._apbActiveTasks = self._apbActiveTasks - 1
							if not self:pvalidate(myTrack) then return end
							self:processValidated(myTrack, myAid, os.clock() - start)
							return
						end
					end
					self._apbActiveTasks = self._apbActiveTasks - 1
					-- Timeout is NOT a silent drop: without this the attack simply vanished
					-- (no defense scheduled, nothing logged), which reads as "it stopped
					-- parrying that move" with no way to tell why.
				end)
				return
			end

			-- ═══════════════ THE JUDGE (per-track verdict) ═══════════════
			-- Every known player attack gets its own async micro-judge. No
			-- entity-wide dropping, no learned profiles, no blocking waits in
			-- the event path. Rejecting a fake NEVER blocks the next track -
			-- which matters because breakers interleave garbage with the one
			-- real swing (often a stop+replay of an id we just saw).
			--
			-- Two-point sample:
			--   ~0.03s  fast-pass. A clean real attack is alive, at sane speed,
			--           already ramping weight -> validate NOW. Added latency on
			--           legit swings is ~2 frames, and it's compensated anyway.
			--   ~0.09s  second read for inconclusive tracks (slow fades, low
			--           weight, weird speed). Ramp floors scale with tier.
			--
			-- Latency compensation: validation passes the judge's real measured
			-- elapsed time (via TimePosition) - plus the churn anchor when the
			-- swing was restart-churned - so scheduled actions stay anchored to
			-- the TRUE swing start. The old code judged with fixed guesses and
			-- no TimePosition awareness, which is why parries against allium's
			-- mid-swing replays fired at the wrong moment.
			if self._apbActiveTasks >= MAX_CONCURRENT_APB_TASKS_PER_ENTITY then
				return
			end

			local myTrack = track
			local myAid = aid
			-- Alive but under-weighted target: passed the hard WT gate above, but
			-- must PROVE a real weight ramp before validating. Only meaningful when
			-- the Weight Ramp check is enabled.
			local wtSuspicious = apbEnabled(cfg, "Weight Ramp") and myTrack.WeightTarget < cfg.wtSuspicious

			self._apbActiveTasks = self._apbActiveTasks + 1
			task.spawn(function()
				local function accept()
					self._apbActiveTasks = self._apbActiveTasks - 1
					if not self:pvalidate(myTrack) then
						return
					end
					-- Elapsed swing time from the track itself. Covers replays
					-- that resume mid-swing (allium aggressive preserves
					-- TimePosition across its stop/replay churn).
					local elapsed = myTrack.TimePosition / math.max(math.abs(myTrack.Speed), 0.5)
					-- Churn anchor: restarts reset TimePosition to 0, but the
					-- server-side hit follows the ORIGINAL swing start. Re-anchor.
					local anchor = self._apbFirstPlay[myAid]
					if anchor and anchor.churn and (os.clock() - anchor.t) <= 2.0 then
						elapsed = math.max(elapsed, os.clock() - anchor.t)
					end
					self:processValidated(myTrack, myAid, math.min(elapsed, 1.5))
				end

				local function reject(reason)
					self._apbActiveTasks = self._apbActiveTasks - 1
					self:_apbEvidenceEvent()
					apbWarn(reason)
				end

				-- SAMPLE 1.
				task.wait(cfg.sample1)

				local speed = math.abs(myTrack.Speed)
				local wt = myTrack.WeightTarget
				local wc = myTrack.WeightCurrent

				-- Dead this early is a script kill (stop+replay bait), never a
				-- human feint - humans feint 100ms+ into a swing, and by then
				-- this track is already validated and the stopped()/iae logic
				-- owns the decision. Unambiguous, so it fires even in
				-- parry-through: the REPLAY that follows is what gets parried.
				if apbEnabled(cfg, "Animation Stop") and self:isFullyDead(myTrack) and myTrack.TimePosition < myTrack.Length and myTrack.TimePosition < cfg.animStopTime then
					return reject("animation stop")
				end

				-- [CHECK: Masked Track] LIVE watch, not a single snapshot. The breaker boosts
				-- its real swing to Action4 on a RenderStepped pass a frame or two AFTER
				-- AnimationPlayed (later still under lag), so ANY one read can miss the boost
				-- and drop a genuine top swing. Instead poll every frame until the track is the
				-- highest-priority track playing (boost landed) or the watch window elapses.
				-- Breaks the instant it uncovers, so a real swing adds only the few frames it
				-- takes to rise; a covered decoy never uncovers and is rejected at the deadline.
				if apbEnabled(cfg, "Masked Track") then
					local humanoid = self.entity:FindFirstChild("Humanoid")
					if humanoid then
						local deadline = os.clock() + MASKED_WATCH_WINDOW
						local uncovered = false
						-- Per-scan weight history for the OTHER tracks, so we can measure a
						-- cover's fade rate across frames (a genuine cover ramps in fast; a
						-- stretched/huge-fade fake barely moves).
						local coverHistory = {}
						while not self:isFullyDead(myTrack) do
							local ok, playing = pcall(function() return humanoid:GetPlayingAnimationTracks() end)
							if ok and type(playing) == "table" then
								local nowClock = os.clock()
								local highest = myTrack.Priority.Value
								for _, other in ipairs(playing) do
									if other ~= myTrack and other.Priority.Value > highest then
										-- Only a track that reads like a REAL cover can mask us. A fake
										-- boosted up just to keep the real swing looking masked (frozen
										-- speed, barely rendered, or a stretched/huge fade) doesn't count,
										-- so the swing beneath it can uncover.
										local ospeed = math.abs(other.Speed)
										local owc = other.WeightCurrent
										local owt = other.WeightTarget
										local ignore = ospeed < cfg.maskSpeedMin or owc < cfg.maskWeightMin
										-- High implied fade: weight far under target and ramping too
										-- slowly to ever reach it. Needs two samples, so it engages a
										-- frame after this cover first appears.
										if not ignore and owt > 0 and owc < owt and (owc / owt) < FADE_TIME_RATIO_SUSPECT then
											local prev = coverHistory[other]
											if prev and nowClock > prev.t then
												local rate = (owc - prev.wc) / (nowClock - prev.t)
												local impliedFade = (rate > FADE_TIME_RAMP_RATE) and ((owt - owc) / rate) or math.huge
												if impliedFade > cfg.maskFadeMax then
													ignore = true
												end
											end
										end
										coverHistory[other] = { t = nowClock, wc = owc }
										if not ignore then
											highest = other.Priority.Value
										end
									end
								end
								if myTrack.Priority.Value >= highest then
									uncovered = true
									break
								end
							end
							if os.clock() >= deadline then break end
							task.wait()
						end
						-- Still covered after the watch (and still alive) = masked decoy.
						if not uncovered and not self:isFullyDead(myTrack) then
							return reject("masked track")
						end
						-- Uncovered: the watch advanced time and the weight ramped further, so
						-- refresh the sampled values to keep the fast-pass below accurate.
						if uncovered then
							speed = math.abs(myTrack.Speed)
							wt = myTrack.WeightTarget
							wc = myTrack.WeightCurrent
						end
					end
				end

				local ratio = wt > 0 and (wc / wt) or 1
				local speedSane = speed >= cfg.speedMin and speed <= cfg.speedMax
				local fastPassRatio = cfg.rampFast
				-- Charged-attack windup that froze AFTER play started (the play-time
				-- exemption above only catches tracks frozen from frame 0). Never
				-- treat a windup freeze as an invalid-speed fake.
				-- WT >= 1.0 (not > 1.0): a windup sitting at EXACTLY 1.0 is the common
				-- case, and the strict > was rejecting it as "invalid speed segment".
				local isWindup = speed < 0.05 and wt >= 1.0

				-- Fast-pass: a clean attack only has to satisfy the checks that are ON.
				local weightOk = (not apbEnabled(cfg, "Weight Ramp")) or (not wtSuspicious and ratio >= fastPassRatio)
				local speedOk = (not apbEnabled(cfg, "Speed")) or speedSane
				if weightOk and speedOk then
					return accept()
				end

				-- Invalid-speed segment (allium aggressive replays at ~0.25x and
				-- corrects later - a later corrected segment will pass instead).
				if apbEnabled(cfg, "Speed") and not apbParryThrough and not speedSane and not isWindup then
					return reject("speed")
				end

				-- SAMPLE 2: inconclusive - give the fade one more read.
				-- Keep the first-sample weight so the Time check can see whether the
				-- weight actually ramped between the two reads.
				local wcSample1 = wc
				task.wait(cfg.sample2)

				speed = math.abs(myTrack.Speed)
				wt = myTrack.WeightTarget
				wc = myTrack.WeightCurrent
				ratio = wt > 0 and (wc / wt) or 1
				isWindup = speed < 0.05 and wt >= 1.0

				if apbEnabled(cfg, "Animation Stop") and self:isFullyDead(myTrack) and myTrack.TimePosition < myTrack.Length and myTrack.TimePosition < cfg.animStopTime then
					return reject("animation stop")
				end

				-- [CHECK: Time] fade-time bait. A fade-time breaker plays the real swing
				-- with a long Play() fade so its weight ramps in far slower than any real
				-- animation (a real fade is ~0.1s). Rather than match one magic fade value,
				-- measure the ACTUAL weight ramp across the two samples and project how long
				-- the fade would take to reach the weight target. If the weight is still
				-- well under target AND that projected fade is abnormally long - or the
				-- weight is frozen and never ramps at all - it's a stretched or huge fade
				-- time. Gated on NOT parry-through, exactly like Weight Ramp / Speed below -- a
				-- fade-time BREAKER hides its real swing here by playing the genuine hit with a
				-- huge fade, so it reads identical to a bait; the hit lands on the move's normal
				-- timing regardless of the visual fade, so parry-through must attempt it, not drop
				-- it. True zero-TARGET ghosts are still caught by the Weight Target gate above.
				if
					not apbParryThrough
					and apbEnabled(cfg, "Time")
					and not isWindup
					and myTrack.IsPlaying
					and speed >= 0.05
					and ratio < FADE_TIME_RATIO_SUSPECT
					and (wt - wc) > 0
				then
					local rate = (wc - wcSample1) / math.max(cfg.sample2, 0.001)
					local impliedFade = (rate > FADE_TIME_RAMP_RATE) and ((wt - wc) / rate) or math.huge
					if impliedFade > cfg.timeMax then
						return reject("time")
					end
				end

				if not apbParryThrough then
					-- [CHECK: Weight Ramp] slow-fade bait: a real fade is well past the
					-- floor by now; a FadeTime=0.5 bait sits under it.
					local rampFloor = cfg.rampFloor
					if apbEnabled(cfg, "Weight Ramp") and ratio < rampFloor and not isWindup then
						return reject("weight ramp")
					end

					-- [CHECK: Speed]
					if apbEnabled(cfg, "Speed") and (speed < cfg.speedMin or speed > cfg.speedMax) and not isWindup then
						return reject("speed")
					end

					-- [CHECK: Weight Ramp] suspicious weight target that never grew weight.
					if apbEnabled(cfg, "Weight Ramp") and wtSuspicious and wc < 0.5 then
						return reject("weight ramp")
					end
				end

				-- BASE tier / parry-through: alive and still progressing is
				-- enough. Better a parry attempt on a marginal track than a
				-- silently dropped real attack.
				return accept()
			end)
			return
		end
	end

	if not Configuration.expectToggleValue("AntiAPBreakerEnabled") and isKnownAnimation and Configuration.expectToggleValue("AntiAPBreakerNotify") then
		-- AP Break Notifications work independently of Anti-AP Breaker itself: run
		-- the same passive churn/frequency detection purely for evidence/notify -
		-- zero interference, never rejects or drops anything.
		if not globalApbRateLimited() then
			self:_apbTrackKnownAnimation(aid)
		end
	end

	if not self:pvalidate(track) then
		return
	end

	-- Process instantly (NPCs and unknown animations only - every known player
	-- attack is owned by the per-track judge above and never reaches this path).
	self:processValidated(track, aid)
end

---Process validated animation track.
---@param self AnimatorDefender
---@param track AnimationTrack
---@param aid string
---@param gateDelay number? Extra delay from ramp gate to compensate in timing.
AnimatorDefender.processValidated = function(self, track, aid, gateDelay)
	---@type AnimationTiming?
	local timing = self:initial(self.entity, SaveManager.as, self.entity.Name, aid)

	---@note: Record playback data for visualizer/builder regardless of existing timing.
	if Configuration.expectToggleValue("ShowAnimationVisualizer") then
		self.pbdata[track] = PlaybackData.new(self.entity)
	end

	if not timing then
		return
	end

	if not Configuration.expectToggleValue("EnableAutoDefense") then
		return
	end

	local humanoidRootPart = self.entity:FindFirstChild("HumanoidRootPart")
	if not humanoidRootPart then
		return
	end

	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return
	end

	if timing.tag == "Critical" then
		timing.nbfb = true
		timing.ha = true
	end

	---@note: Clean up previous tasks that are still waiting or suspended because they're in a different track.
	self:clean()

	-- Set current data.
	self.timing = timing
	self.track = track
	self.offset = Latency.rdelay() + (gateDelay or 0)

	-- How long the anti-AP-breaker pipeline burned BEFORE this defense got scheduled
	-- (judge samples, windup polling). Task countdowns start at scheduling time while
	-- action:when() is measured from the SWING's start, so Defender.action subtracts
	-- this. Without it every parry fires late by exactly the gate's cost whenever
	-- Anti-AP Breaker is on - which is why it felt fine with the toggle off.
	self.gateDelay = math.max(0, gateDelay or 0)

	-- Timestamp exactly when THIS track's playback genuinely stops (Stop() call or
	-- natural end), off the track's real .Stopped event - not off whatever moment
	-- some later poll/check happens to look. AnimatorDefender.stopped() and the
	-- post-check ramp guard below both require a stop to be genuinely stale before
	-- trusting it as a real feint, so a stop timed to land right at a check doesn't
	-- get to veto an already-committed defense just because it's fresh.
	self._trackStoppedAt = nil
	local stoppedSignal = Signal.new(track.Stopped)
	self.tmaid:add(stoppedSignal:connect("AnimatorDefender_TrackStopped", function()
		self._trackStoppedAt = os.clock()
	end))

	self._trackSeq = self._trackSeq + 1
	local mySeq = self._trackSeq

	-- Peak WeightCurrent this swing reaches while alive, sampled by the pollers below.
	-- _apbGhostOnEarlyKill uses it to tell a stop+replay bait (ramped to full weight, hit
	-- landed, then cut) from a genuine feint (cut before the weight completed).
	self._trackPeakWeight = 0

	-- Post-check protection [AGGRESSIVE tier]: aborts the scheduled defense if the anim gets
	-- killed / de-weighted after passing. Skipped in parry-through mode so Ignore Animation
	-- End can still commit the parry through A3 cancels.
	if Configuration.expectToggleValue("AntiAPBreakerEnabled")
		and apbEnabled(readApbConfig(), "Post-Check Ramp")
		and not Configuration.expectToggleValue("AllowFailure") then
		local isPlayer = players:GetPlayerFromCharacter(self.entity)
		if isPlayer then
			-- Ramp check: reject flat/de-weighted animations that passed the 0.02s gate.
			task.spawn(function()
				task.wait(0.08)

				if self._trackSeq ~= mySeq then
					return
				end

				local isPlaying = track.IsPlaying
				local weightCurrent = track.WeightCurrent
				local timePosition = track.TimePosition
				local killed = not isPlaying and timePosition < track.Length
				-- 0.15, not 0.50: at 80ms a legit slower fade (0.2s) is only ~40%
				-- weighted - the old 0.50 floor was cleaning real attacks and
				-- contributed to "recognizes the timing but never parries".
				local flatWeight = isPlaying and weightCurrent < apbNum("ApbFlatWeightFloor", 0.15)

				-- Fixed-offset check (always runs at ~0.08s from swing start, regardless
				-- of this weapon's actual windup/hit timing). A track killed by a post-hit
				-- bait cut - which by definition can only happen once a hit has already
				-- resolved - reads identically to a real cancel here otherwise. Require the
				-- stop to be genuinely stale before letting it nuke the whole defense.
				-- A ghost-processed track (killed early, defense deliberately kept armed)
				-- must survive this guard.
				if (killed and self._ghostTrack ~= track) or flatWeight then
					apbWarn()
					self:clean()
				end
			end)

			-- Secondary check: full validation at 0.25s.
			task.spawn(function()
				task.wait(0.25)

				if self._trackSeq ~= mySeq then
					return
				end

				local isPlaying = track.IsPlaying
				local weightCurrent = track.WeightCurrent
				local timePosition = track.TimePosition
				local length = track.Length
				local killed = not isPlaying and timePosition < length
				local deweighted = isPlaying and weightCurrent < apbNum("ApbFlatWeightFloor", 0.15)

				-- Same staleness guard as the 0.08s pass above.
				-- Same ghost respect as the 0.08s pass above.
				if (killed and self._ghostTrack ~= track) or deweighted then
					apbWarn()
					self:clean()
				end
			end)
		end
	end

	-- Track-ended ghost handler: when a defended attack track ends (an Aggressive-3 kill
	-- or a normal finish), mark it a ghost and keep the defense armed for its window, so a
	-- mid-flight kill with no feint still parries the incoming hit.
	if Configuration.expectToggleValue("AntiAPBreakerEnabled") and players:GetPlayerFromCharacter(self.entity) then
		track.Ended:Once(function()
			if self._trackSeq ~= mySeq then
				return
			end

			local speed = math.abs(track.Speed)
			self._ghostTrack = track
			self._ghostStartedAt = os.clock()
			self._ghostUntil = os.clock() + math.min(track.Length / (speed >= 0.5 and speed or 1), 5)

			Logger.warn(
				"(%s) %s's attack track ended (Aggressive 3 kill or normal finish) -- keeping defense armed.",
				track.Animation.AnimationId,
				self.entity.Name
			)
		end)
	end

	-- Mid-play kill checker: at ~0.08s and ~0.25s, if the track was killed mid-play, ghost
	-- it (a very early kill == Aggressive 3, keep the defense) or clean it (a real cancel).
	if Configuration.expectToggleValue("AntiAPBreakerEnabled") and players:GetPlayerFromCharacter(self.entity) then
		task.spawn(function()
			task.wait(0.08)

			for _, wait in next, { 0, 0.17 } do
				if wait > 0 then
					task.wait(wait)
				end

				if self._trackSeq ~= mySeq then
					return
				end

				if track.IsPlaying then
					self._trackPeakWeight = math.max(self._trackPeakWeight or 0, track.WeightCurrent)
				elseif track.TimePosition < track.Length then
					if self:_apbGhostOnEarlyKill(track) then
						return
					end

					Logger.warn(
						"(%s) Animation from %s killed mid-play. (WC=%.4f, TimePos=%.3f, Length=%.3f)",
						track.Animation.AnimationId,
						self.entity.Name,
						track.WeightCurrent,
						track.TimePosition,
						track.Length
					)
					self:clean()
					return
				end
			end
		end)
	end

	-- Use module over actions.
	if timing.umoa then
		return self:module(timing)
	end

	---@note: Start processing the timing. Add the actions if we're not RPUE.
	if not timing.rpue then
		return self:actions(timing)
	end

	-- Start RPUE.
	local info = RepeatInfo.new(timing, Latency.rdelay(), self:uid(10))
	info.track = track
	self:srpue(self.entity, timing, info)
end

---Clean up the defender.
AnimatorDefender.clean = LPH_NO_VIRTUALIZE(function(self)
	-- Empty data.
	self.keyframes = {}

	-- Clean through base method.
	Defender.clean(self)
end)

---Create new AnimatorDefender object.
---@param animator Animator
---@param manimations table<number, Animation>
---@return AnimatorDefender
AnimatorDefender.new = LPH_NO_VIRTUALIZE(function(animator, manimations)
	local entity = animator:FindFirstAncestorWhichIsA("Model")
	if not entity then
		return error(string.format("AnimatorDefender.new(%s) - no entity.", animator:GetFullName()))
	end

	local self = setmetatable(Defender.new(), AnimatorDefender)
	local animationPlayed = Signal.new(animator.AnimationPlayed)

	self.animator = animator
	self.manimations = manimations
	self.entity = entity

	self.track = nil
	self.timing = nil
	self.offset = nil

	self.keyframes = {}
	self.pbdata = {}
	self.rpbdata = {}
	self.sct = {}
	self.tsc = {}
	self.multiplier = {}
	self.wmultiplier = {}
	self.fdc = {}
	self.pdc = {}

	-- Evaluation-data AP break state.
	self._evaluationData = {}

	-- AP break protection state. Flag is informational (notify/UI) only.
	self._apbFlagged = false
	self._apbFlaggedAt = 0
	self._apbAnimTimestamps = {}

	-- Aggressive 2 state (see the block above pvalidate). Arrivals feed flood width
	-- and the emission-grid period; _a2IdLast catches the mask twin; _a2Real marks
	-- ids identified as genuine swings; _a2Accepted collapses the source + mask
	-- pair into one defense; _a2LastDecoy is the phase reference for the grid test.
	self._a2Arrivals = {}
	self._a2IdLast = {}
	self._a2Real = {}
	self._a2Accepted = {}
	self._a2LastDecoy = nil

	-- Evidence timestamps (rejected fakes, churn restarts, frequency spikes)
	-- within the last second. Feeds flagging + the user notification - never
	-- gates dropping.
	self._apbEvidence = {}


	-- Tracks the last time each specific animation ID was played by this
	-- entity. Rapid reuse is no longer auto-rejected (stop+replay breakers
	-- make the REPLAY the real attack) - it feeds churn detection instead.
	self._apbLastMoveTime = {}

	-- Per-animation-id first-play anchors: { t = clock of first play, churn =
	-- whether impossibly-fast reuse marked this swing as restart-churned }.
	-- When churned, validation re-anchors action timing to the original play,
	-- since the server-side hit follows the original swing start no matter
	-- how many times the breaker restarts the visual.
	self._apbFirstPlay = {}

	-- Caps how many of this entity's async AP-break checks (windup polling,
	-- FadeTime inference, background weight check, judge gate) can be alive
	-- at once. Bounds worst-case resource usage against a flood attack that
	-- doesn't try to fool detection, just tries to spawn enough concurrent
	-- work to overwhelm the client.
	self._apbActiveTasks = 0

	-- Monotonic sequence counter. Starts at 0; incremented each time self.track
	-- is assigned in processValidated. Deferred tasks capture this value at spawn time
	-- and compare it at execution time - if it has changed, a newer track has taken
	-- over and the callback should not clean() the current state.
	self._trackSeq = 0

	-- Aggressive-3 ghost: when an attack track is killed mid-flight with no feint, the
	-- defense is kept armed against that track until _ghostUntil (see _apbGhostOnEarlyKill
	-- + the track.Ended / mid-play handlers in processValidated).
	self._ghostTrack = nil
	self._ghostStartedAt = 0
	self._ghostUntil = 0

	-- Per-entity "we hit them" tracking. update() reads this entity's Humanoid.Health
	-- every frame; a drop that coincides with our own DamagedAnother effect
	-- (StateListener.chit) means WE landed the hit on THIS entity, so their in-progress
	-- swing is cancelled. Only this entity's defender is stamped, so a second attacker
	-- we did NOT hit still gets parried normally.
	self._hbuHumanoid = nil
	self._hbuLastHealth = nil
	self._hbuHitAt = 0

	self.maid:mark(animationPlayed:connect(
		"AnimatorDefender_OnAnimationPlayed",
		function(track)
			self:process(track)
		end
	))

	return self
end)

-- Return AnimatorDefender module.
return AnimatorDefender


end)
__bundle_register("Game/Timings/PlaybackData", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
---@class PlaybackData
---@field base number Timestamp of when the object was created.
---@field ash table<number, number> Animation speed history. The key is the timestamp delta and the value is the speed at that point.
---@field entity Model Entity to playback.
local PlaybackData = {}
PlaybackData.__index = PlaybackData

---Get last exceeded speed difference from a timestamp delta.
---@param from number
---@return number?, number?
function PlaybackData:last(from)
	local latestExceededSpeed = nil
	local latestExceededDelta = nil

	for delta, speed in next, self.ash do
		if from <= delta then
			continue
		end

		if latestExceededDelta and delta <= latestExceededDelta then
			continue
		end

		latestExceededSpeed = speed
		latestExceededDelta = delta
	end

	return latestExceededSpeed, latestExceededDelta
end

---Track animation speed.
---@param speed number
function PlaybackData:astrack(speed)
	local delta = os.clock() - self.base

	if self:last(delta) == speed then
		return
	end

	self.ash[delta] = speed
end

---Create new PlaybackData object.
---@param entity Model
---@return PlaybackData
function PlaybackData.new(entity)
	local self = setmetatable({}, PlaybackData)
	self.base = os.clock()
	self.entity = entity

	---@note: Timestamp delta is how many seconds need to pass before being able to reach this speed.
	self.ash = {}

	return self
end

-- Return PlaybackData module.
return PlaybackData

end)()

end)
__bundle_register("Utility/ControlModule", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
	-- This module is used for getting the proper input fly values - 1:1 with Aztup.
	local ControlModule = {
		forwardValue = 0,
		backwardValue = 0,
		leftValue = 0,
		rightValue = 0,
	}

	---@module Utility.Profiler
	local Profiler = require("Utility/Profiler")

	---@module Utility.Logger
	local Logger = require("Utility/Logger")

	---@module Utility.Maid
	local Maid = require("Utility/Maid")

	-- Maids.
	local controlMaid = Maid.new()

	-- Services.
	local ContextActionService = game:GetService("ContextActionService")

	---Bind action safely with maid, error, and profiler handling.
	---@param actionName string
	---@param callback function
	---@param createTouchButton boolean
	local function bindActionWrapper(actionName, callback, createTouchButton, ...)
		---Log bind action errors.
		---@param error string
		local function onBindActionWrapperError(error)
			Logger.trace("onBindActionWrapperError - (%s) - %s", actionName, error)
		end

		local actionWrapperCallback = callback
			and Profiler.wrap(string.format("ControlModule_BindActionWrapper_%s", actionName), function(...)
				local success, result = xpcall(callback, onBindActionWrapperError, ...)

				if not success then
					return nil
				end

				return result
			end)

		---@note: This is a hot-fix and should be handled properly in the future.
		controlMaid:add(function()
			ContextActionService:UnbindAction(actionName)
		end)

		ContextActionService:BindAction(actionName, actionWrapperCallback, createTouchButton, ...)
	end

	---Initialize control module.
	function ControlModule.init()
		bindActionWrapper("ControlModule_ForwardValue", function(_, inputState, _)
			ControlModule.forwardValue = (inputState == Enum.UserInputState.Begin) and -1 or 0
			return Enum.ContextActionResult.Pass
		end, false, Enum.KeyCode.W)

		bindActionWrapper("ControlModule_LeftValue", function(_, inputState, _)
			ControlModule.leftValue = (inputState == Enum.UserInputState.Begin) and -1 or 0
			return Enum.ContextActionResult.Pass
		end, false, Enum.KeyCode.A)

		bindActionWrapper("ControlModule_BackwardValue", function(_, inputState, _)
			ControlModule.backwardValue = (inputState == Enum.UserInputState.Begin) and 1 or 0
			return Enum.ContextActionResult.Pass
		end, false, Enum.KeyCode.S)

		bindActionWrapper("ControlModule_RightValue", function(_, inputState, _)
			ControlModule.rightValue = (inputState == Enum.UserInputState.Begin) and 1 or 0
			return Enum.ContextActionResult.Pass
		end, false, Enum.KeyCode.D)

		Logger.warn("ControlModule initialized.")
	end

	---Detach control module.
	function ControlModule.detach()
		controlMaid:clean()
		Logger.warn("ControlModule detached.")
	end

	---Get move vector.
	---@return Vector3
	function ControlModule.getMoveVector()
		return Vector3.new(
			ControlModule.leftValue + ControlModule.rightValue,
			0,
			ControlModule.forwardValue + ControlModule.backwardValue
		)
	end

	-- Return control module.
	return ControlModule
end)()


end)
