__bundle_register("Features/Arsenal/Visuals", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
-- Arsenal visuals feature: Player ESP (box / name / distance), the visual removals (No Fog / Blur / Blind / Shadows) and Field of View.
local Visuals = {}

-- Services.
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local Workspace = game:GetService("Workspace")
local Lighting = game:GetService("Lighting")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

local localPlayer = Players.LocalPlayer

-- Runtime state.
local renderConn = nil
local playerRemovingConn = nil
local espObjects = {} -- [player] = { box, name, dist }
local hasDrawing = (type(Drawing) == "table") and (type(Drawing.new) == "function")

-- ── config readers ─────────────────────────────────────────────────────────
local function optNum(key, default)
	local value = Configuration.expectOptionValue(key)
	return (type(value) == "number") and value or default
end
local function tog(key)
	return Configuration.expectToggleValue(key) == true
end
local function optColor(key, default)
	local value = Configuration.expectOptionValue(key)
	return (typeof(value) == "Color3") and value or default
end

-- ── ESP drawing pool ───────────────────────────────────────────────────────
local function makeEsp()
	local box = Drawing.new("Square")
	box.Thickness = 1
	box.Filled = false
	box.Transparency = 1
	box.Visible = false

	local name = Drawing.new("Text")
	name.Size = 13
	name.Center = true
	name.Outline = true
	name.Visible = false

	local dist = Drawing.new("Text")
	dist.Size = 12
	dist.Center = true
	dist.Outline = true
	dist.Visible = false

	local weapon = Drawing.new("Text")
	weapon.Size = 12
	weapon.Center = true
	weapon.Outline = true
	weapon.Visible = false

	local tracer = Drawing.new("Line")
	tracer.Thickness = 1
	tracer.Transparency = 1
	tracer.Visible = false

	return { box = box, name = name, dist = dist, weapon = weapon, tracer = tracer }
end

-- Best-effort "what are they holding": an equipped Tool, else a common weapon attribute on the character/player, else "None".
local function getWeaponName(character, player)
	local tool = character:FindFirstChildWhichIsA("Tool")
	if tool then
		return tool.Name
	end
	for _, key in ipairs({ "Weapon", "EquippedWeapon", "CurrentWeapon", "Gun", "Loadout" }) do
		local value = character:GetAttribute(key)
		if value == nil then
			value = player:GetAttribute(key)
		end
		if value ~= nil and tostring(value) ~= "" then
			return tostring(value)
		end
	end
	return "None"
end

local function getEsp(player)
	local obj = espObjects[player]
	if not obj then
		obj = makeEsp()
		espObjects[player] = obj
	end
	return obj
end

local function hideEsp(obj)
	obj.box.Visible = false
	obj.name.Visible = false
	obj.dist.Visible = false
	obj.weapon.Visible = false
	obj.tracer.Visible = false
end

local function removeEsp(player)
	local obj = espObjects[player]
	if obj then
		pcall(function()
			obj.box:Remove()
			obj.name:Remove()
			obj.dist:Remove()
			obj.weapon:Remove()
			obj.tracer:Remove()
		end)
		espObjects[player] = nil
	end
end

-- Project a STABLE box for the character to a 2D screen rectangle.
local BOX_HALF_HEIGHT = 3.0 -- studs above/below the root (covers an R15 rig)
local function projectBox(character, camera)
	local root = character:FindFirstChild("HumanoidRootPart")
	if not root then
		return nil
	end

	local cframe = root.CFrame
	local top = camera:WorldToViewportPoint((cframe * CFrame.new(0, BOX_HALF_HEIGHT, 0)).Position)
	local bottom = camera:WorldToViewportPoint((cframe * CFrame.new(0, -BOX_HALF_HEIGHT, 0)).Position)
	if top.Z <= 0 or bottom.Z <= 0 then
		return nil
	end

	local height = math.abs(top.Y - bottom.Y)
	local width = height * 0.55
	local centerX = (top.X + bottom.X) * 0.5
	local yTop = math.min(top.Y, bottom.Y)

	return centerX - width * 0.5, yTop, width, height
end

local function updateESP()
	if not hasDrawing then
		return
	end

	local enabled = tog("ESPEnabled")
	local camera = Workspace.CurrentCamera

	if not enabled or not camera then
		for _, obj in next, espObjects do
			hideEsp(obj)
		end
		return
	end

	local showBox = tog("ESPBox")
	local showName = tog("ESPName")
	local showDist = tog("ESPDistance")
	local teamCheck = tog("ESPTeamCheck")
	local maxDist = optNum("ESPMaxDistance", 1000)
	local color = optColor("ESPColor", Color3.fromRGB(255, 60, 60))
	local showWeapon = tog("ESPWeapon")
	local showTracer = tog("ESPTracer")
	local viewport = camera.ViewportSize
	local tracerOrigin = Vector2.new(viewport.X * 0.5, viewport.Y)

	local mine = localPlayer.Character
	local myRoot = mine and mine:FindFirstChild("HumanoidRootPart")

	for _, player in ipairs(Players:GetPlayers()) do
		if player == localPlayer then
			continue
		end

		local obj = getEsp(player)
		local character = player.Character
		local humanoid = character and character:FindFirstChildWhichIsA("Humanoid")
		local root = character and character:FindFirstChild("HumanoidRootPart")

		if not character or not root or (humanoid and humanoid.Health <= 0) then
			hideEsp(obj)
			continue
		end

		if teamCheck and localPlayer.Team and player.Team == localPlayer.Team then
			hideEsp(obj)
			continue
		end

		local distance = myRoot and (root.Position - myRoot.Position).Magnitude or 0
		if myRoot and distance > maxDist then
			hideEsp(obj)
			continue
		end

		local x, y, w, h = projectBox(character, camera)
		if not x then
			hideEsp(obj)
			continue
		end

		if showBox then
			obj.box.Position = Vector2.new(x, y)
			obj.box.Size = Vector2.new(w, h)
			obj.box.Color = color
			obj.box.Visible = true
		else
			obj.box.Visible = false
		end

		if showName then
			obj.name.Text = player.Name
			obj.name.Color = color
			obj.name.Position = Vector2.new(x + w * 0.5, y - 16)
			obj.name.Visible = true
		else
			obj.name.Visible = false
		end

		if showDist then
			obj.dist.Text = string.format("[%dm]", math.floor(distance))
			obj.dist.Color = color
			obj.dist.Position = Vector2.new(x + w * 0.5, y + h + 2)
			obj.dist.Visible = true
		else
			obj.dist.Visible = false
		end

		if showWeapon then
			obj.weapon.Text = getWeaponName(character, player)
			obj.weapon.Color = color
			obj.weapon.Position = Vector2.new(x + w * 0.5, y + h + 16)
			obj.weapon.Visible = true
		else
			obj.weapon.Visible = false
		end

		if showTracer then
			obj.tracer.Color = color
			obj.tracer.From = tracerOrigin
			obj.tracer.To = Vector2.new(x + w * 0.5, y + h)
			obj.tracer.Visible = true
		else
			obj.tracer.Visible = false
		end
	end
end

-- ── lighting removals + FOV ──────────────────────────────────────────────── Lighting removals don't need per-frame reassertion -- the effects change rarely, so a 5 Hz throttle is imperceptible and skips a full Lighting:GetDescendants allocation every single render step.
local lastWorldUpdate = 0
local WORLD_INTERVAL = 0.2
local function updateWorld()
	-- Field of View (per-frame).
	if tog("ModifyFieldOfView") then
		local camera = Workspace.CurrentCamera
		if camera then
			camera.FieldOfView = optNum("FieldOfView", 90)
		end
	end

	local now = os.clock()
	if now - lastWorldUpdate < WORLD_INTERVAL then
		return
	end
	lastWorldUpdate = now

	-- No Fog.
	if tog("NoFog") then
		Lighting.FogStart = 9e9
		Lighting.FogEnd = 9e9
		for _, effect in ipairs(Lighting:GetChildren()) do
			if effect:IsA("Atmosphere") then
				effect.Density = 0
			end
		end
	end

	-- No Blur + No Blind share ONE descendants pass instead of allocating two.
	local noBlur = tog("NoBlur")
	local noBlind = tog("NoBlind")
	if noBlur or noBlind then
		for _, effect in ipairs(Lighting:GetDescendants()) do
			if noBlur and effect:IsA("BlurEffect") and effect.Enabled then
				effect.Enabled = false
			elseif noBlind and effect:IsA("ColorCorrectionEffect") and effect.Brightness > 0 then
				effect.Brightness = 0
			end
		end
	end

	-- No Shadows.
	if tog("NoShadows") then
		Lighting.GlobalShadows = false
	end
end

local function onRender()
	updateESP()
	updateWorld()
end

-- ── lifecycle ──────────────────────────────────────────────────────────────
function Visuals.init()
	renderConn = RunService.RenderStepped:Connect(onRender)
	playerRemovingConn = Players.PlayerRemoving:Connect(removeEsp)
end

function Visuals.detach()
	if renderConn then
		renderConn:Disconnect()
		renderConn = nil
	end
	if playerRemovingConn then
		playerRemovingConn:Disconnect()
		playerRemovingConn = nil
	end
	for player in next, espObjects do
		removeEsp(player)
	end
end

return Visuals
end)()
end)
__bundle_register("Features/Arsenal/Movement", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
-- Arsenal movement feature: WalkSpeed, Fly, Noclip and Infinite Jump.
local Movement = {}

-- Services.
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")
local Workspace = game:GetService("Workspace")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

local localPlayer = Players.LocalPlayer

-- Runtime state.
local heartbeatConn = nil
local renderConn = nil
local inputConn = nil
local flyVelocity = nil
local flyGyro = nil
local flying = false

-- Reused constant so updateFly doesn't allocate a fresh up-vector every render step.
local UP = Vector3.new(0, 1, 0)

-- Noclip caches the current character's BaseParts so the heartbeat loop never calls character:GetDescendants() (a full-array allocation ~60x/second).
local noclipChar = nil
local noclipParts = setmetatable({}, { __mode = "k" })
local noclipAddedConn = nil
local noclipRemovingConn = nil

local function releaseNoclipConns()
	if noclipAddedConn then
		noclipAddedConn:Disconnect()
		noclipAddedConn = nil
	end
	if noclipRemovingConn then
		noclipRemovingConn:Disconnect()
		noclipRemovingConn = nil
	end
end

local function bindNoclipCache(character)
	noclipChar = character
	noclipParts = setmetatable({}, { __mode = "k" })
	releaseNoclipConns()
	if not character then
		return
	end

	for _, part in ipairs(character:GetDescendants()) do
		if part:IsA("BasePart") then
			noclipParts[part] = true
		end
	end

	noclipAddedConn = character.DescendantAdded:Connect(function(descendant)
		if descendant:IsA("BasePart") then
			noclipParts[descendant] = true
		end
	end)
	noclipRemovingConn = character.DescendantRemoving:Connect(function(descendant)
		noclipParts[descendant] = nil
	end)
end

-- ── config readers ─────────────────────────────────────────────────────────
local function optNum(key, default)
	local value = Configuration.expectOptionValue(key)
	return (type(value) == "number") and value or default
end
local function tog(key)
	return Configuration.expectToggleValue(key) == true
end

-- ── character helpers ──────────────────────────────────────────────────────
local function getCharacter()
	return localPlayer.Character
end
local function getHumanoid(character)
	return character and character:FindFirstChildWhichIsA("Humanoid")
end
local function getRoot(character)
	return character and character:FindFirstChild("HumanoidRootPart")
end

-- ── fly ────────────────────────────────────────────────────────────────────
local function stopFly()
	flying = false
	if flyVelocity then
		flyVelocity:Destroy()
		flyVelocity = nil
	end
	if flyGyro then
		flyGyro:Destroy()
		flyGyro = nil
	end
	local humanoid = getHumanoid(getCharacter())
	if humanoid then
		humanoid.PlatformStand = false
	end
end

local function startFly(root, humanoid)
	if flyVelocity and flyVelocity.Parent then
		return
	end
	flying = true
	humanoid.PlatformStand = true

	flyVelocity = Instance.new("BodyVelocity")
	flyVelocity.MaxForce = Vector3.new(1, 1, 1) * 9e9
	flyVelocity.Velocity = Vector3.zero
	flyVelocity.P = 5000
	flyVelocity.Parent = root

	flyGyro = Instance.new("BodyGyro")
	flyGyro.MaxTorque = Vector3.new(1, 1, 1) * 9e9
	flyGyro.P = 9000
	flyGyro.CFrame = root.CFrame
	flyGyro.Parent = root
end

local function updateFly()
	if not tog("Fly") then
		if flying then
			stopFly()
		end
		return
	end

	local character = getCharacter()
	local root = getRoot(character)
	local humanoid = getHumanoid(character)
	if not root or not humanoid then
		if flying then
			stopFly()
		end
		return
	end

	startFly(root, humanoid)

	local camera = Workspace.CurrentCamera
	if not camera then
		return
	end

	-- Point the character where the camera looks and move on WASD + Space/Shift.
	flyGyro.CFrame = camera.CFrame

	local speed = optNum("FlySpeed", 50)
	local move = Vector3.zero

	if not UserInputService:GetFocusedTextBox() then
		local look = camera.CFrame.LookVector
		local right = camera.CFrame.RightVector
		if UserInputService:IsKeyDown(Enum.KeyCode.W) then
			move = move + look
		end
		if UserInputService:IsKeyDown(Enum.KeyCode.S) then
			move = move - look
		end
		if UserInputService:IsKeyDown(Enum.KeyCode.D) then
			move = move + right
		end
		if UserInputService:IsKeyDown(Enum.KeyCode.A) then
			move = move - right
		end
		if UserInputService:IsKeyDown(Enum.KeyCode.Space) then
			move = move + UP
		end
		if UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) then
			move = move - UP
		end
	end

	if move.Magnitude > 0 then
		flyVelocity.Velocity = move.Unit * speed
	else
		flyVelocity.Velocity = Vector3.zero
	end
end

-- ── walkspeed / noclip (heartbeat) ─────────────────────────────────────────
local function onHeartbeat()
	local character = getCharacter()
	if not character then
		return
	end

	-- WalkSpeed.
	if tog("WalkSpeedEnabled") then
		local humanoid = getHumanoid(character)
		if humanoid then
			local target = optNum("WalkSpeed", 16)
			if humanoid.WalkSpeed ~= target then
				humanoid.WalkSpeed = target
			end
		end
	end

	-- Noclip: keep every part non-colliding while enabled.
	if tog("Noclip") then
		if character ~= noclipChar then
			bindNoclipCache(character)
		end
		for part in next, noclipParts do
			if part.CanCollide then
				part.CanCollide = false
			end
		end
	end
end

-- ── infinite jump ──────────────────────────────────────────────────────────
local function onInputBegan(input, gameProcessed)
	if gameProcessed then
		return
	end
	if not tog("InfiniteJump") then
		return
	end
	if input.KeyCode ~= Enum.KeyCode.Space then
		return
	end
	local humanoid = getHumanoid(getCharacter())
	if humanoid then
		humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
	end
end

-- ── lifecycle ──────────────────────────────────────────────────────────────
function Movement.init()
	heartbeatConn = RunService.Heartbeat:Connect(onHeartbeat)
	renderConn = RunService.RenderStepped:Connect(updateFly)
	inputConn = UserInputService.InputBegan:Connect(onInputBegan)
end

function Movement.detach()
	stopFly()
	if heartbeatConn then
		heartbeatConn:Disconnect()
		heartbeatConn = nil
	end
	if renderConn then
		renderConn:Disconnect()
		renderConn = nil
	end
	if inputConn then
		inputConn:Disconnect()
		inputConn = nil
	end
	releaseNoclipConns()
	noclipChar = nil
	noclipParts = setmetatable({}, { __mode = "k" })
end

return Movement
end)()
end)
__bundle_register("Features/Arsenal/Aimbot", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
-- Arsenal aimbot feature.
local Aimbot = {}

-- Services.
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local Workspace = game:GetService("Workspace")
local UserInputService = game:GetService("UserInputService")
local GuiService = game:GetService("GuiService")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

local localPlayer = Players.LocalPlayer

-- Runtime state.
local boundRender = false
local fovGui = nil
local fovCircle = nil
local fovStroke = nil
local rainbowHue = 0
local currentTargetPlayer = nil
local triggerOnTargetSince = nil
local triggerLastShot = 0
local triggerFiring = false

-- ── config readers ─────────────────────────────────────────────────────────
local function optNum(key, default)
	local value = Configuration.expectOptionValue(key)
	return (type(value) == "number") and value or default
end

local function optStr(key, default)
	local value = Configuration.expectOptionValue(key)
	return (type(value) == "string") and value or default
end

local function tog(key)
	return Configuration.expectToggleValue(key) == true
end

-- ── aim part resolution ──────────────────────────────────────────────────── Friendly UI names -> candidate rig part names.
local PART_CANDIDATES = {
	Head = { "Head" },
	Torso = { "HumanoidRootPart", "UpperTorso", "Torso", "LowerTorso" },
	Legs = { "LeftUpperLeg", "RightUpperLeg", "LeftLeg", "RightLeg", "LeftLowerLeg", "RightLowerLeg" },
}

local function resolvePart(character, name)
	local candidates = PART_CANDIDATES[name]
	if not candidates then
		return nil
	end
	for _, partName in ipairs(candidates) do
		local part = character:FindFirstChild(partName)
		if part and part:IsA("BasePart") then
			return part
		end
	end
	return nil
end

-- Highest-priority part that actually exists on this rig (primary, then secondary).
local function pickAimPart(character)
	local primary = optStr("AimbotPrimaryPart", "Head")
	local part = resolvePart(character, primary)
	if part then
		return part
	end

	local secondary = optStr("AimbotSecondaryPart", "Torso")
	if secondary and secondary ~= "None" then
		return resolvePart(character, secondary)
	end
	return nil
end

-- ── wall / visible check ─────────────────────────────────────────────────── Raycast from the camera to the part; clear if nothing blocks it.
local function isVisible(targetCharacter, part)
	local camera = Workspace.CurrentCamera
	if not camera then
		return true
	end

	local origin = camera.CFrame.Position
	local direction = part.Position - origin

	local params = RaycastParams.new()
	params.FilterType = Enum.RaycastFilterType.Exclude
	local mine = localPlayer.Character
	params.FilterDescendantsInstances = mine and { mine, camera } or { camera }

	local result = Workspace:Raycast(origin, direction, params)
	if not result then
		return true
	end
	return result.Instance:IsDescendantOf(targetCharacter)
end

-- ── target acquisition ───────────────────────────────────────────────────── Screen distance of a player's aim part from the crosshair + whether it passes every gate.
local function evaluate(player)
	if player == localPlayer then
		return math.huge, false
	end
	local camera = Workspace.CurrentCamera
	if not camera then
		return math.huge, false
	end

	local character = player.Character
	if not character then
		return math.huge, false
	end

	-- Never lock onto teammates.
	if tog("AimbotTeamCheck") and localPlayer.Team and player.Team == localPlayer.Team then
		return math.huge, false
	end

	local humanoid = character:FindFirstChildWhichIsA("Humanoid")
	if humanoid and humanoid.Health <= 0 then
		return math.huge, false
	end

	local part = pickAimPart(character)
	if not part then
		return math.huge, false
	end

	local mine = localPlayer.Character
	local myRoot = mine and mine:FindFirstChild("HumanoidRootPart")
	if myRoot and (part.Position - myRoot.Position).Magnitude > optNum("AimbotMaxDistance", 500) then
		return math.huge, false
	end

	local screenPos, onScreen = camera:WorldToViewportPoint(part.Position)
	if not onScreen then
		return math.huge, false
	end

	local viewport = camera.ViewportSize
	local center = Vector2.new(viewport.X * 0.5, viewport.Y * 0.5)
	local dist2d = (Vector2.new(screenPos.X, screenPos.Y) - center).Magnitude
	if dist2d > optNum("AimbotFOV", 120) then
		return math.huge, false
	end

	if tog("AimbotWallCheck") and not isVisible(character, part) then
		return math.huge, false
	end

	return dist2d, true
end

-- Keep the lock as long as the target is alive and in range.
local function shouldKeepTarget(player)
	if not player or not player.Parent or player == localPlayer then
		return false
	end
	local character = player.Character
	if not character then
		return false
	end
	if tog("AimbotTeamCheck") and localPlayer.Team and player.Team == localPlayer.Team then
		return false
	end
	local humanoid = character:FindFirstChildWhichIsA("Humanoid")
	if humanoid and humanoid.Health <= 0 then
		return false
	end
	local part = pickAimPart(character)
	if not part then
		return false
	end
	local mine = localPlayer.Character
	local myRoot = mine and mine:FindFirstChild("HumanoidRootPart")
	if myRoot and (part.Position - myRoot.Position).Magnitude > optNum("AimbotMaxDistance", 500) then
		return false
	end
	return true
end

-- Can we put the aim on this part right now (on-screen + line of sight)?
local function canAimAt(character, part)
	local camera = Workspace.CurrentCamera
	if not camera then
		return false
	end
	local _, onScreen = camera:WorldToViewportPoint(part.Position)
	if not onScreen then
		return false
	end
	if tog("AimbotWallCheck") and not isVisible(character, part) then
		return false
	end
	return true
end

-- Player closest to the crosshair that passes every gate.
local function acquireTargetPlayer()
	local best, bestScore = nil, math.huge
	for _, player in ipairs(Players:GetPlayers()) do
		local score, ok = evaluate(player)
		if ok and score < bestScore then
			best, bestScore = player, score
		end
	end
	return best
end

-- ── activation ───────────────────────────────────────────────────────────── Master toggle on AND the hold key currently down.
local function isActive()
	if not tog("Aimbot") then
		return false
	end
	local picker = Options and Options.AimbotKeybind
	if picker and picker.GetState then
		return picker:GetState() == true
	end
	return false
end

-- ── triggerbot ─────────────────────────────────────────────────────────────
local function getPlayerFromInstance(instance)
	local node = instance
	while node do
		local player = Players:GetPlayerFromCharacter(node)
		if player then
			return player
		end
		node = node.Parent
	end
	return nil
end

-- One clean press + release per call.
local TRIGGER_HOLD = 0.02 -- seconds the button is held per click
local function fireClick()
	if triggerFiring then
		return
	end
	triggerFiring = true
	task.spawn(function()
		pcall(function()
			if type(mouse1press) == "function" and type(mouse1release) == "function" then
				mouse1press()
				task.wait(TRIGGER_HOLD)
				mouse1release()
			elseif type(mouse1click) == "function" then
				mouse1click()
			else
				local vim = game:GetService("VirtualInputManager")
				vim:SendMouseButtonEvent(0, 0, 0, true, game, false)
				task.wait(TRIGGER_HOLD)
				vim:SendMouseButtonEvent(0, 0, 0, false, game, false)
			end
		end)
		triggerFiring = false
	end)
end

-- Resolve who the crosshair is on right now: the aimbot's locked target if it's actively holding one, else a straight camera-forward raycast so the triggerbot still works standalone.
local function resolveTriggerTarget()
	if isActive() and currentTargetPlayer and currentTargetPlayer.Parent then
		return currentTargetPlayer
	end
	local camera = Workspace.CurrentCamera
	if not camera then
		return nil
	end
	local params = RaycastParams.new()
	params.FilterType = Enum.RaycastFilterType.Exclude
	local mine = localPlayer.Character
	params.FilterDescendantsInstances = mine and { mine, camera } or { camera }
	local result = Workspace:Raycast(camera.CFrame.Position, camera.CFrame.LookVector * 5000, params)
	return result and getPlayerFromInstance(result.Instance) or nil
end

-- Fire when the crosshair (camera forward) is over an alive enemy.
local function updateTrigger()
	if not tog("Triggerbot") then
		triggerOnTargetSince = nil
		return
	end

	local picker = Options and Options.TriggerbotKeybind
	if picker and picker.GetState and picker.Value ~= "None" and not picker:GetState() then
		triggerOnTargetSince = nil
		return -- a key is bound but not held
	end

	local player = resolveTriggerTarget()

	-- Validate it's an alive enemy.
	local valid = player ~= nil and player ~= localPlayer
	if valid and tog("AimbotTeamCheck") and localPlayer.Team and player.Team == localPlayer.Team then
		valid = false
	end
	if valid then
		local humanoid = player.Character and player.Character:FindFirstChildWhichIsA("Humanoid")
		if humanoid and humanoid.Health <= 0 then
			valid = false
		end
	end

	if not valid then
		triggerOnTargetSince = nil -- crosshair left the target; reset the reaction timer
		return
	end

	local now = os.clock()
	if not triggerOnTargetSince then
		triggerOnTargetSince = now
	end

	-- Reaction delay before the first shot.
	if now - triggerOnTargetSince < (optNum("TriggerbotDelay", 0) / 1000) then
		return
	end

	-- Refire throttle so we don't spam a click every frame (auto weapons still spray).
	if now - triggerLastShot < 0.06 then
		return
	end
	triggerLastShot = now
	fireClick()
end

-- ── FOV circle ─────────────────────────────────────────────────────────────
local function updateCircle()
	if not fovCircle then
		return
	end

	local show = tog("Aimbot") and tog("AimbotShowCircle")
	fovCircle.Visible = show
	if not show then
		return
	end

	local fov = optNum("AimbotFOV", 120)
	fovCircle.Size = UDim2.fromOffset(fov * 2, fov * 2)

	if tog("AimbotRainbow") then
		rainbowHue = (rainbowHue + 0.004) % 1
		fovStroke.Color = Color3.fromHSV(rainbowHue, 1, 1)
	else
		local color = Configuration.expectOptionValue("AimbotCircleColor")
		if typeof(color) == "Color3" then
			fovStroke.Color = color
		end
	end
end

-- ── per-frame ──────────────────────────────────────────────────────────────
local function updateAim()
	if not isActive() then
		currentTargetPlayer = nil
		return
	end

	-- Sticky lock: only re-acquire when the target is truly gone (dead / removed / out of range).
	if not shouldKeepTarget(currentTargetPlayer) then
		currentTargetPlayer = acquireTargetPlayer()
	end
	if not currentTargetPlayer then
		return
	end

	local character = currentTargetPlayer.Character
	local part = character and pickAimPart(character)
	if not part then
		return
	end

	if not canAimAt(character, part) then
		return -- keep the lock; just don't move the aim this frame
	end

	local camera = Workspace.CurrentCamera
	if not camera then
		return
	end

	local smoothness = optNum("AimbotSmoothness", 5)
	local alpha = (smoothness <= 0) and 1 or math.clamp(1 / (smoothness + 1), 0.02, 1)
	local method = optStr("AimbotMethod", "Camera")

	if method == "Mouse" and type(mousemoverel) == "function" then
		-- Move the real mouse toward the target's screen position.
		local screenPoint = camera:WorldToViewportPoint(part.Position)
		if screenPoint.Z <= 0 then
			return -- behind the camera
		end
		-- WorldToViewportPoint is viewport-space (below the top bar); GetMouseLocation is screen-space (includes the inset) -- add the inset so they line up.
		local inset = GuiService:GetGuiInset()
		local targetPos = Vector2.new(screenPoint.X + inset.X, screenPoint.Y + inset.Y)
		local delta = targetPos - UserInputService:GetMouseLocation()
		mousemoverel(delta.X * alpha, delta.Y * alpha)
	else
		-- Camera: rotate the view to look right at the part.
		local currentCF = camera.CFrame
		camera.CFrame = currentCF:Lerp(CFrame.new(currentCF.Position, part.Position), alpha)
	end
end

-- Order matters: aim first (moves the camera / sets the locked target), THEN run the triggerbot so it fires against the freshly-aimed camera and current lock.
local function onRender()
	updateCircle()
	updateAim()
	updateTrigger()
end

-- ── lifecycle ──────────────────────────────────────────────────────────────
function Aimbot.init()
	-- FOV circle GUI.
	fovGui = Instance.new("ScreenGui")
	fovGui.Name = "ScreenGui"
	fovGui.IgnoreGuiInset = true
	fovGui.DisplayOrder = 998
	fovGui.ResetOnSpawn = false

	local parent = game:GetService("CoreGui")
	pcall(function()
		if gethui then
			parent = gethui()
		end
	end)
	fovGui.Parent = parent

	fovCircle = Instance.new("Frame")
	fovCircle.Name = "FOV"
	fovCircle.AnchorPoint = Vector2.new(0.5, 0.5)
	fovCircle.Position = UDim2.new(0.5, 0, 0.5, 0)
	fovCircle.Size = UDim2.fromOffset(240, 240)
	fovCircle.BackgroundTransparency = 1
	fovCircle.BorderSizePixel = 0
	fovCircle.Visible = false
	fovCircle.Parent = fovGui

	local corner = Instance.new("UICorner")
	corner.CornerRadius = UDim.new(1, 0)
	corner.Parent = fovCircle

	fovStroke = Instance.new("UIStroke")
	fovStroke.Thickness = 1.5
	fovStroke.Color = Color3.fromRGB(255, 255, 255)
	fovStroke.Parent = fovCircle

	-- Bind at the very end of the render step so a Camera-method write is the LAST one before the frame renders - otherwise Arsenal' camera controller overwrites it some frames and the view snaps away.
	RunService:BindToRenderStep("MiraAimbot", Enum.RenderPriority.Last.Value + 1, onRender)
	boundRender = true
end

function Aimbot.detach()
	if boundRender then
		pcall(function()
			RunService:UnbindFromRenderStep("MiraAimbot")
		end)
		boundRender = false
	end
	if fovGui then
		fovGui:Destroy()
		fovGui = nil
	end
	fovCircle, fovStroke = nil, nil
end

return Aimbot
end)()
end)
__bundle_register("Features/Automation/FortitudeFarm", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
-- Fortitude farming.
local FortitudeFarm = {}

---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Utility.Signal
local Signal = require("Utility/Signal")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@module Game.AntiAFK
local AntiAFK = require("Game/AntiAFK")

-- Services.
local players = game:GetService("Players")
local runService = game:GetService("RunService")
local virtualInputManager = game:GetService("VirtualInputManager")

-- Signals.
local renderStepped = Signal.new(runService.RenderStepped)

-- Maids.
local fortitudeFarmMaid = Maid.new()

-- Timestamp (throttle -- no need to check every single frame).
local fortitudeFarmTimestamp = os.clock()

-- These notifications used to fire every single 0.1s tick while stuck in either state, which is 10 notifications a second.
local NOTIFY_MAX = 2
local nearbyNotifyCount = 0
local rangeNotifyCount = 0

-- Confirmed live: firing the ProximityPrompt with fireproximityprompt() alone did nothing at all - no ChoicePrompt dialogue ever opened, nothing.

---Find Brutus.
---@return Model?
local function findBrutus()
	-- He actually lives under Workspace.NPCs, not Workspace.Live - confirmed live in-game, this used to look in the wrong folder entirely and would never find him no matter how close you stood.
	local npcs = workspace:FindFirstChild("NPCs")
	if npcs then
		local brutus = npcs:FindFirstChild("Brutus")
		if brutus then
			return brutus
		end
	end

	-- Fallback in case that folder ever gets reorganized again - recursive scan for anything named Brutus anywhere in the workspace.
	for _, descendant in next, workspace:GetDescendants() do
		if descendant:IsA("Model") and descendant.Name:lower():find("brutus") then
			return descendant
		end
	end

	return nil
end

---Update fortitude farm.
local function updateFortitudeFarm()
	if os.clock() - fortitudeFarmTimestamp < 0.1 then
		return
	end

	fortitudeFarmTimestamp = os.clock()

	AntiAFK.stop("FortitudeFarm")

	local fortitudeFarm = Toggles["AutoFortitude"]
	if not fortitudeFarm or not fortitudeFarm.Value then
		-- Fresh notification budget next time this gets turned back on.
		nearbyNotifyCount = 0
		rangeNotifyCount = 0
		return
	end

	AntiAFK.start("FortitudeFarm")

	local localPlayer = players.LocalPlayer
	local localPlayerCharacter = localPlayer.Character
	local humanoidRootPart = localPlayerCharacter and localPlayerCharacter:FindFirstChild("HumanoidRootPart")
	if not humanoidRootPart then
		return
	end

	local brutus = findBrutus()
	local interactPrompt = brutus and brutus:FindFirstChild("InteractPrompt")
	local brutusRoot = brutus and (brutus:FindFirstChild("HumanoidRootPart") or brutus.PrimaryPart)

	if not interactPrompt or not interactPrompt:IsA("ProximityPrompt") or not brutusRoot then
		rangeNotifyCount = 0

		if nearbyNotifyCount < NOTIFY_MAX then
			nearbyNotifyCount = nearbyNotifyCount + 1
			Logger.longNotify("Auto Fortitude Farm: Brutus isn't nearby, go to Brutus.")
		end

		return
	end

	if (humanoidRootPart.Position - brutusRoot.Position).Magnitude > interactPrompt.MaxActivationDistance then
		nearbyNotifyCount = 0

		if rangeNotifyCount < NOTIFY_MAX then
			rangeNotifyCount = rangeNotifyCount + 1
			Logger.longNotify("Auto Fortitude Farm: not within range of Brutus, move closer.")
		end

		return
	end

	nearbyNotifyCount = 0
	rangeNotifyCount = 0

	local interactKeyCode = interactPrompt.KeyboardKeyCode
	if interactKeyCode == Enum.KeyCode.Unknown then
		interactKeyCode = Enum.KeyCode.E
	end

	fireproximityprompt(interactPrompt)
	virtualInputManager:SendKeyEvent(true, interactKeyCode, false, game)
	virtualInputManager:SendKeyEvent(false, interactKeyCode, false, game)
end

---Fortitude farming.
function FortitudeFarm.init()
	-- Attach.
	fortitudeFarmMaid:add(renderStepped:connect("FortitudeFarm_OnPreRender", updateFortitudeFarm))

	-- Log.
	Logger.warn("Fortitude Farm initialized.")
end

---Detach the fortitude farm.
function FortitudeFarm.detach()
	-- Clean.
	fortitudeFarmMaid:clean()
	AntiAFK.stop("FortitudeFarm")

	-- Log.
	Logger.warn("Fortitude Farm detached.")
end

-- Return FortitudeFarm module
return FortitudeFarm
end)()
end)
__bundle_register("Features/Automation/FishFarm", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
-- Fish farming.
local FishFarm = {}

---@module Game.AntiAFK
local AntiAFK = require("Game/AntiAFK")

---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Utility.Signal
local Signal = require("Utility/Signal")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

-- Services.
local players = game:GetService("Players")
local runService = game:GetService("RunService")

-- Signals.
local renderStepped = Signal.new(runService.RenderStepped)

-- Maids.
local fishFarmMaid = Maid.new()

-- Timestamp.
local fishFarmTimestamp = os.clock()

-- State.
local wasActivated = false

---Update fish farm.
local function updateFishFarm()
	if os.clock() - fishFarmTimestamp < 0.1 then
		return
	end

	fishFarmTimestamp = os.clock()

	AntiAFK.stop("FishFarm")

	if not Configuration.expectToggleValue("AutoFish") then
		return
	end

	AntiAFK.start("FishFarm")

	local localPlayer = players.LocalPlayer
	local localPlayerCharacter = localPlayer.Character
	if not localPlayerCharacter then
		return
	end

	local humanoid = localPlayerCharacter:FindFirstChild("Humanoid")
	if not humanoid then
		return
	end

	local backpack = localPlayer:FindFirstChild("Backpack")
	if not backpack then
		return
	end

	local characterRod = localPlayerCharacter:FindFirstChild("Fishing Rod")
	local backpackRod = backpack:FindFirstChild("Fishing Rod")

	if not characterRod then
		return backpackRod and humanoid:EquipTool(backpackRod)
	end

	local handle = characterRod:FindFirstChild("Handle")
	local rod = handle and handle:FindFirstChild("Rod")
	local bobby = rod and rod:FindFirstChild("bobby")
	if not bobby then
		return
	end

	local addBait = characterRod:FindFirstChild("AddBait")
	if not addBait then
		return
	end

	---@todo: add fish meat lol
	local baitTable = {
		"Plumfruit",
		"Pomar",
		"Gobletto",
		"Squid",
		"Dentifilo",
		"Seaweed Bundle",
		"Urchin",
		"Browncap",
		"Chum",
		"Calabash",
		"Pufferfish",
		"Redd",
	}

	for _, baitName in next, baitTable do
		local bait = backpack:FindFirstChild(baitName)
		if not bait then
			continue
		end

		if bobby:FindFirstChild("bait") then
			break
		end

		return addBait:FireServer(bait)
	end

	local hook = bobby:FindFirstChild("hook")
	if not hook then
		return
	end

	if hook.Transparency ~= 1.0 then
		wasActivated = not wasActivated
		return wasActivated and characterRod:Deactivate() or characterRod:Activate()
	end

	local inputUpdate = characterRod:FindFirstChild("InputUpdate")
	if not inputUpdate then
		return
	end

	local playerGui = localPlayer:FindFirstChild("PlayerGui")
	if not playerGui then
		return
	end

	local fishingGui = playerGui:FindFirstChild("FishingGui")
	if not fishingGui or not fishingGui.Enabled then
		return
	end

	local mainFrame = fishingGui:FindFirstChild("MainFrame")
	if not mainFrame then
		return
	end

	local holdA = mainFrame:FindFirstChild("HoldA")
	local holdS = mainFrame:FindFirstChild("HoldS")
	local holdD = mainFrame:FindFirstChild("HoldD")
	if not holdA or not holdS or not holdD then
		return
	end

	inputUpdate:FireServer({
		a = holdA.Visible,
		s = holdS.Visible,
		d = holdD.Visible,
	})
end

---Fish farming.
function FishFarm.init()
	-- Attach the fish farm.
	fishFarmMaid:add(renderStepped:connect("FishFarm_RenderStepped", updateFishFarm))

	-- Log.
	Logger.warn("Fish Farm initialized.")
end

---Detach the fish farm.
function FishFarm.detach()
	-- Clean the maid.
	fishFarmMaid:clean()

	-- Log.
	Logger.warn("Fish Farm detached.")
end

-- Return FishFarm module.
return FishFarm

end)()

end)
