	iconThree.Name = "Icon"
	iconThree.ScaleType = Enum.ScaleType.Crop
	iconThree.BorderColor3 = Color3.new()
	iconThree.BackgroundColor3 = Library.FontColor
	iconThree.Image = "rbxassetid://10734961809"
	iconThree.BackgroundTransparency = 1
	iconThree.Position = UDim2.new(0.5, -8, 0.5, -8)
	iconThree.SizeConstraint = Enum.SizeConstraint.RelativeXX
	iconThree.BorderSizePixel = 0
	iconThree.Size = UDim2.new(0, 16, 0, 16)
	iconThree.Parent = frameForwards

	local animationTextbox = Instance.new("TextBox")
	animationTextbox.Name = "AnimationTextbox"
	animationTextbox.CursorPosition = -1
	animationTextbox.TextColor3 = Library.FontColor
	animationTextbox.Text = "rbxassetid://0"
	animationTextbox.BackgroundColor3 = Library.MainColor
	animationTextbox.Position = UDim2.new(0.323, -78, 0.835, -24)
	animationTextbox.BorderColor3 = Color3.new()
	animationTextbox.FontFace = Font.new("rbxasset://fonts/families/RobotoMono.json")
	animationTextbox.TextSize = 15  -- Better readability
	animationTextbox.Size = UDim2.new(0, 246, 0, 15)
	animationTextbox.Parent = inner

	-- Current data for playback loop.
	local currentPlaybackData = nil
	local currentTrack = nil
	local isPaused = false
	local timeElapsed = 0.0

	---Map slider value.
	---@param value number
	---@param min number
	---@param max number
	---@param minSize number
	---@param maxSize number
	local function mapSliderValue(value, min, max, minSize, maxSize)
		return (1 - ((value - min) / (max - min))) * minSize + ((value - min) / (max - min)) * maxSize
	end

	---On Animation ID focus lost.
	---@param enter boolean
	---@param _ InputObject
	local function onIdFocusLost(enter, _)
		if not enter then
			return
		end

		-- Empty out previous data.
		currentTrack = nil
		currentPlaybackData = nil

		---@type PlaybackData
		local playbackData = Defense.agpd(animationTextbox.Text)
		if not playbackData then
			return AnimationVisualizer.message("No Playback Data Found")
		end

		-- Remove all previously loaded models.
		for _, descendant in next, viewportFrame:GetDescendants() do
			if descendant.ClassName ~= "Model" then
				continue
			end

			descendant:Destroy()
		end

		-- Load the model & center it.
		local entity = playbackData.entity:Clone()
		entity.Parent = worldModel
		entity:PivotTo(CFrame.new(0, 0, 0))

		-- Fetch the primary part.
		if not entity.PrimaryPart then
			return AnimationVisualizer.message("No Primary Part Found")
		end

		-- Setup camera.
		local _, bbs = entity:GetBoundingBox()
		camera.CFrame =
			CFrame.lookAt(entity.PrimaryPart.Position - Vector3.new(0, 0, bbs.Magnitude), entity.PrimaryPart.Position)

		-- Fetch animator.
		local animator = entity:FindFirstChildWhichIsA("Animator", true)
		if not animator then
			return AnimationVisualizer.message("No Animator Found")
		end

		-- Stop previous animations.
		for _, track in next, animator:GetPlayingAnimationTracks() do
			track:Stop()
		end

		-- Create animation.
		local animation = Instance.new("Animation")
		animation.AnimationId = animationTextbox.Text

		-- Store current data for playback.
		currentPlaybackData = playbackData
		currentTrack = animator:LoadAnimation(animation)

		-- Play animation and keep it at zero speed.
		currentTrack:Play(0.0, 100, 0.0)
		currentTrack.Priority = Enum.AnimationPriority.Action
		currentTrack.Looped = true
		visualizerMaid:mark(currentTrack.DidLoop:Connect(function()
			timeElapsed = 0.0
		end))

		-- Reset time elapsed.
		timeElapsed = 0.0

		-- Show frames.
		viewportFrame.Visible = true
		noViewportFrame.Visible = false
	end

	---Get time elapsed from time position.
	---@param timePosition number
	---@param animationLength number
	---@return number?
	local function getTimeElapsedFromTp(timePosition, animationLength)
		if not currentPlaybackData then
			return nil
		end

		if timePosition <= 0 then
			return 0.0
		end

		-- Numerical integration to find elapsed time.
		local currentPos = 0
		local elapsed = 0
		local dt = 0.01
		local iterations = 0

		while currentPos < timePosition do
			local speed = currentPlaybackData:last(elapsed) or 1
			local stepSize = speed * dt

			iterations = iterations + 1

			---@note: We can calculate how many iterations this should likely take based on the length (e.g 4 seconds) of the animation.
			--- Since we have a delta time of 0.01s, that means we can multiply the length by 100 to get our iteration amount.
			if iterations >= math.max(((animationLength * 100) * 10), 1000) then
				break
			end

			-- If adding the full step would exceed the target position, calculate partial step and break.
			if currentPos + stepSize > timePosition then
				local remainingTime = (timePosition - currentPos) / speed
				elapsed = elapsed + remainingTime
				break
			end

			currentPos = currentPos + stepSize
			elapsed = elapsed + dt
		end

		-- Return the elapsed time.
		return elapsed
	end

	---On playback loop.
	---@param delta number
	local function onPlaybackLoop(delta)
		if not screenGui.Enabled then
			return
		end

		iconTwo.Image = isPaused and "rbxassetid://10734923549" or "rbxassetid://10734919336"

		-- Run slider calculations.
		local mhs = sliderOuter.AbsoluteSize.X
		local hs = currentTrack and mapSliderValue(currentTrack.TimePosition, 0.0, currentTrack.Length, 0, mhs) or 0.0

		-- Update slider text.
		sliderText.Text = (currentTrack and currentPlaybackData)
				and string.format(
					"%.3f/%.3f (%ims)",
					currentTrack.TimePosition,
					currentTrack.Length,
					math.round((getTimeElapsedFromTp(currentTrack.TimePosition, currentTrack.Length) or 0.0) * 1000)
				)
			or "0.000 / ??? (???ms)"

		-- Update size.
		sliderFill.Visible = not (hs == 0)
		sliderFill.Size = UDim2.new(0, math.max(math.ceil(hs), 1), 1, 0)
		hideBorderRight.Visible = not (hs == mhs or hs == 0)

		-- Update speed amount.
		speedText.Text = currentTrack and string.format("Speed (%.2f)", currentTrack.Speed) or "Speed (???)"

		if currentTrack and isPaused then
			speedText.Text = string.format(
				"Speed (%.2f)",
				currentPlaybackData:last(getTimeElapsedFromTp(currentTrack.TimePosition, currentTrack.Length) or 0.0)
					or 0.0
			)
		end

		if not currentTrack or not currentPlaybackData then
			return
		end

		if isPaused then
			return currentTrack:AdjustSpeed(0.0)
		end

		timeElapsed = timeElapsed + delta

		currentTrack:AdjustSpeed(currentPlaybackData:last(timeElapsed) or 0.0)
	end

	---Toggle play stop function.
	local function togglePlayStop()
		if not currentTrack then
			return
		end

		if not currentTrack.IsPlaying then
			return
		end

		isPaused = not isPaused
	end

	---Go backwards one frame.
	local function onFrameBackwards()
		if not currentTrack then
			return
		end

		currentTrack.TimePosition = math.max(currentTrack.TimePosition - 0.01, 0)
	end

	---Go forwards one frame.
	local function onFrameForwards()
		if not currentTrack then
			return
		end

		currentTrack.TimePosition = math.min(currentTrack.TimePosition + 0.01, currentTrack.Length)
	end

	---On slider input began.
	---@param input InputObject
	---@param gameProcessed boolean
	local function onSliderInputBegan(input, gameProcessed)
		if gameProcessed then
			return
		end

		if input.UserInputType ~= Enum.UserInputType.MouseButton1 then
			return
		end

		while screenGui.Enabled and userInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) do
			if not currentTrack then
				return
			end

			-- Pause track.
			isPaused = true

			-- Calculate new time position.
			local mouse = players.LocalPlayer:GetMouse()
			local sliderOuterSize = sliderOuter.AbsoluteSize.X
			local mouseX = math.clamp(mouse.X - sliderOuter.AbsolutePosition.X, 0, sliderOuterSize)
			local newTimePosition = mapSliderValue(mouseX, 0, sliderOuterSize, 0, currentTrack.Length)

			-- Update time position.
			currentTrack.TimePosition = newTimePosition

			-- Wait.
			runService.PreRender:Wait()
		end

		timeElapsed = getTimeElapsedFromTp(currentTrack.TimePosition, currentTrack.Length) or 0.0
	end

	---Outer input began.
	---@param input InputObject
	---@param gameProcessed boolean
	local function outerFrameInputBegan(input, gameProcessed)
		if gameProcessed then
			return
		end

		if input.KeyCode == Enum.KeyCode.Space then
			return togglePlayStop()
		end

		if input.KeyCode == Enum.KeyCode.Right then
			return onFrameForwards()
		end

		if input.KeyCode == Enum.KeyCode.Left then
			return onFrameBackwards()
		end
	end

	---Set the visibility of the AnimationVisualizer.
	---@param state boolean
	function AnimationVisualizer.visible(state)
		screenGui.Enabled = state
	end

	---Show a message.
	---@param message string
	function AnimationVisualizer.message(message)
		viewportFrame.Visible = false
		noViewportFrame.Visible = true
		textLabel.Text = message
	end

	---Initialize AnimationVisualizer module.
	function AnimationVisualizer.init()
		-- Initialize GUI.
		screenGui.Name = "AnimationVisualizer"
		screenGui.Enabled = false
		screenGui.DisplayOrder = 1

		-- Make draggable.
		Library:MakeDraggable(outer)

		-- Setup colors.
		Library:AddToRegistry(color, {
			BackgroundColor3 = "AccentColor",
		}, true)

		Library:AddToRegistry(animationVisualizer, {
			TextColor3 = "AccentColor",
		}, true)

		Library:AddToRegistry(hideBorderRight, {
			BackgroundColor3 = "AccentColor",
		}, true)

		Library:AddToRegistry(sliderFill, {
			BackgroundColor3 = "AccentColor",
		}, true)

		Library:AddToRegistry(inner, {
			BackgroundColor3 = "MainColor",
			BorderColor3 = "OutlineColor",
		}, true)

		Library:AddToRegistry(playStop, {
			BackgroundColor3 = "MainColor",
			BorderColor3 = "Black",
		}, true)

		Library:AddToRegistry(animationTextbox, {
			BackgroundColor3 = "MainColor",
			BorderColor3 = "Black",
			TextColor3 = "FontColor",
		}, true)

		Library:AddToRegistry(icon, {
			ImageColor3 = "FontColor",
		}, true)

		Library:AddToRegistry(iconTwo, {
			ImageColor3 = "FontColor",
		}, true)

		Library:AddToRegistry(iconThree, {
			ImageColor3 = "FontColor",
		}, true)

		Library:AddToRegistry(textLabel, {
			TextColor3 = "FontColor",
		}, true)

		Library:AddToRegistry(speedText, {
			TextColor3 = "FontColor",
		}, true)

		Library:AddToRegistry(noViewportFrame, {
			BackgroundColor3 = "MainColor",
			BorderColor3 = "Black",
		}, true)

		Library:AddToRegistry(frameBackwards, {
			BackgroundColor3 = "MainColor",
			BorderColor3 = "Black",
		}, true)

		Library:AddToRegistry(frameForwards, {
			BackgroundColor3 = "MainColor",
			BorderColor3 = "Black",
		}, true)

		Library:AddToRegistry(viewportFrame, {
			BackgroundColor3 = "MainColor",
			BorderColor3 = "Black",
		}, true)

		Library:AddToRegistry(sliderOuter, {
			BorderColor3 = "Black",
		}, true)

		Library:AddToRegistry(sliderInner, {
			BackgroundColor3 = "MainColor",
			BorderColor3 = "Black",
		}, true)

		Library:AddToRegistry(sliderFill, {
			BackgroundColor3 = "AccentColor",
			BorderColor3 = "AccentColorDark",
		}, true)

		Library:AddToRegistry(hideBorderRight, {
			BackgroundColor3 = "AccentColor",
		}, true)

		Library:AddToRegistry(sliderText, {
			TextColor3 = "FontColor",
		}, true)

		-- Setup camera.
		viewportFrame.CurrentCamera = camera

		-- Setup intro scene.
		AnimationVisualizer.message("Waiting For Animation ID")

		-- Setup signals.
		local idFocusLost = Signal.new(animationTextbox.FocusLost)
		local preRender = Signal.new(runService.PreRender)
		local playStopClicked = Signal.new(playStop.MouseButton1Click)
		local outerInputBegan = Signal.new(outer.InputBegan)
		local frameBackwardsClick = Signal.new(frameBackwards.MouseButton1Click)
		local frameForwardsClick = Signal.new(frameForwards.MouseButton1Click)
		local sliderInputBegan = Signal.new(sliderOuter.InputBegan)

		visualizerMaid:add(sliderInputBegan:connect("AnimationVisualizer_SliderInputBegan", onSliderInputBegan))
		visualizerMaid:add(frameForwardsClick:connect("AnimationVisualizer_FrameForwardsClick", onFrameForwards))
		visualizerMaid:add(frameBackwardsClick:connect("AnimationVisualizer_FrameBackwardsClick", onFrameBackwards))
		visualizerMaid:add(outerInputBegan:connect("AnimationVisualizer_OuterInputBegan", outerFrameInputBegan))
		visualizerMaid:add(playStopClicked:connect("AnimationVisualizer_PlayStopClicked", togglePlayStop))
		visualizerMaid:add(preRender:connect("AnimationVisualizer_PlaybackLoop", onPlaybackLoop))
		visualizerMaid:add(idFocusLost:connect("AnimationVisualizer_IdFocusLost", onIdFocusLost))

		-- Add outer frame to library.
		Library.AnimationVisualizerFrame = outer
	end

	---Detach AnimationVisualizer module.
	function AnimationVisualizer.detach()
		visualizerMaid:clean()
	end

	-- Return AnimationVisualizer module.
	return AnimationVisualizer
end)()
end)
__bundle_register("Features/Combat/SilentAim", function(require, _LOADED, __bundle_register, __bundle_modules)
local SilentAim = {}
---@module Utility.Configuration
local Configuration = require("Utility/Configuration")
---@module Utility.Maid
local Maid = require("Utility/Maid")
---@module Utility.Signal
local Signal = require("Utility/Signal")
---@module Utility.Logger
local Logger = require("Utility/Logger")
local replicatedStorage = game:GetService("ReplicatedStorage")
local players = game:GetService("Players")
local runService = game:GetService("RunService")
local guiService = game:GetService("GuiService")
local stats = game:GetService("Stats")
local silentMaid = Maid.new()
local localPlayer = players.LocalPlayer
local fovCircle = nil
local currentTarget = nil
local lastTargetScan = 0
local getCameraToMouse = nil
local updateMouse = nil
local hookInstalled = false

local hasDrawing = (type(Drawing) == "table") and (type(Drawing.new) == "function")

---@return number
local function getPing()
	local ok, ping = pcall(function()
		return stats.Network.ServerStatsItem["Data Ping"]:GetValue()
	end)
	if ok and type(ping) == "number" then
		return ping / 1000
	end
	return 0
end

---@param value any
---@return any
local function sanitize(value)
	if typeof(value) == "Vector3" then
		return Vector3.new(
			value.X == value.X and value.X or 0,
			value.Y == value.Y and value.Y or 0,
			value.Z == value.Z and value.Z or 0
		)
	end
	if typeof(value) == "number" then
		return value == value and value or 0
	end
	return value
end

---@param character Model
---@param isMob boolean
---@return boolean
local function isAllowedTarget(character, isMob)
	if isMob then
		return Configuration.expectToggleValue("SilentAimTargetMobs") ~= false
	end
	local targetPlayer = players:GetPlayerFromCharacter(character)
	if targetPlayer and targetPlayer ~= localPlayer then
		if not Configuration.expectToggleValue("SilentAimTargetGuildmates") then
			local myGuild = localPlayer:GetAttribute("Guild")
			local theirGuild = targetPlayer:GetAttribute("Guild")
			if myGuild and theirGuild and #tostring(myGuild) > 0 and myGuild == theirGuild then
				return false
			end
		end
	end
	return Configuration.expectToggleValue("SilentAimTargetPlayers") ~= false
end

---@return Model?
local function getTarget()
	local live = workspace:FindFirstChild("Live")
	if not live then
		return nil
	end
	local camera = workspace.CurrentCamera
	if not camera then
		return nil
	end
	local mouse = localPlayer:GetMouse()
	local originX = mouse.X
	local originY = mouse.Y + guiService:GetGuiInset().Y
	local fov = Configuration.expectOptionValue("SilentAimFOV") or 120
	local closestTarget = nil
	local closestDistance = fov
	for _, character in next, live:GetChildren() do
		local isMob = character.Name:sub(1, 1) == "."
		if character == localPlayer.Character then
			continue
		end
		if not character.PrimaryPart then
			continue
		end
		if not isAllowedTarget(character, isMob) then
			continue
		end
		local extent = Vector3.new(4, 5, 6)
		local base = character.PrimaryPart.CFrame - extent / 2
		local low = base.Position
		local high = (base + extent).Position
		local corners = {
			Vector3.new(low.X, low.Y, low.Z),
			Vector3.new(low.X, high.Y, low.Z),
			Vector3.new(high.X, high.Y, low.Z),
			Vector3.new(high.X, low.Y, low.Z),
			Vector3.new(high.X, high.Y, high.Z),
			Vector3.new(low.X, high.Y, high.Z),
			Vector3.new(low.X, low.Y, high.Z),
			Vector3.new(high.X, low.Y, high.Z),
		}
		for _, corner in next, corners do
			local screen, onScreen = camera:WorldToViewportPoint(corner)
			if onScreen then
				local delta = math.sqrt((screen.X - originX) ^ 2 + (screen.Y - originY) ^ 2)
				if delta < closestDistance then
					closestDistance = delta
					closestTarget = character
					break
				end
			end
		end
	end
	return closestTarget
end

---@param target Model
---@return CFrame
local function aimCFrameFor(target)
	local camera = workspace.CurrentCamera
	local primary = target and target.PrimaryPart
	if not camera or not primary then
		return CFrame.identity
	end
	local predictionPercent = Configuration.expectOptionValue("SilentAimPrediction") or 0
	local lead = primary.Velocity * getPing() * (predictionPercent / 100)
	local aimAt = sanitize(primary.Position + lead)
	return CFrame.lookAt(camera.CFrame.Position, aimAt)
end

---@return CFrame
local function realAimCFrame()
	local camera = workspace.CurrentCamera
	local mouse = localPlayer:GetMouse()
	if not camera then
		return CFrame.identity
	end
	return CFrame.lookAt(camera.CFrame.Position, sanitize(mouse.Hit.Position))
end

local function installHook()
	if hookInstalled or not getCameraToMouse then
		return
	end

	getCameraToMouse.OnClientInvoke = function()
		local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
		local effectReplicatorModule = effectReplicator and require(effectReplicator)
		local cameraLock = effectReplicatorModule and effectReplicatorModule:HasEffect("CameraLock") or false
		if Configuration.expectToggleValue("SilentAim") and currentTarget and currentTarget.PrimaryPart then
			return aimCFrameFor(currentTarget), cameraLock
		end
		return realAimCFrame(), cameraLock
	end
	hookInstalled = true
end

local function onRenderStepped()
	if not Configuration.expectToggleValue("SilentAim") then
		if fovCircle then
			fovCircle.Visible = false
		end
		currentTarget = nil
		return
	end
	local mouse = localPlayer:GetMouse()
	local position = Vector2.new(mouse.X, mouse.Y + guiService:GetGuiInset().Y)
	if hasDrawing then
		if not fovCircle then
			fovCircle = Drawing.new("Circle")
			fovCircle.Thickness = 1
			fovCircle.NumSides = 100
			fovCircle.Filled = false
			fovCircle.Transparency = 1
		end
		local show = Configuration.expectToggleValue("SilentAimShowFOV") ~= false
		fovCircle.Visible = show
		fovCircle.Radius = Configuration.expectOptionValue("SilentAimFOV") or 120
		fovCircle.Position = position
		fovCircle.Color = Color3.fromRGB(255, 255, 255)
	end
	if os.clock() - lastTargetScan > 0.1 then
		lastTargetScan = os.clock()
		currentTarget = getTarget()
	end
	if updateMouse and currentTarget and currentTarget.PrimaryPart then
		local predictionPercent = Configuration.expectOptionValue("SilentAimPrediction") or 0
		local lead = currentTarget.PrimaryPart.Velocity * getPing() * (predictionPercent / 100)
		local aimAt = sanitize(currentTarget.PrimaryPart.Position + lead)

		local ok, buf = pcall(function()
			local b = buffer.create(24)
			buffer.writef64(b, 0, aimAt.X)
			buffer.writef64(b, 8, aimAt.Y)
			buffer.writef64(b, 16, aimAt.Z)
			return b
		end)
		if ok then
			pcall(function()
				updateMouse:FireServer(buf)
			end)
		end
	end
end

function SilentAim.init()
	local requests = replicatedStorage:FindFirstChild("Requests")
	if not requests then
		return Logger.warn("Silent Aim: Requests folder not found.")
	end
	getCameraToMouse = requests:FindFirstChild("GetCameraToMouse")
	updateMouse = requests:FindFirstChild("UpdateMouse")
	if not getCameraToMouse then
		return Logger.warn("Silent Aim: GetCameraToMouse remote not found.")
	end
	installHook()
	local characterAdded = Signal.new(localPlayer.CharacterAdded)
	silentMaid:mark(characterAdded:connect("SilentAim_CharacterAdded", function()
		hookInstalled = false
		task.delay(1, installHook)
	end))
	local renderStepped = Signal.new(runService.RenderStepped)
	silentMaid:mark(renderStepped:connect("SilentAim_RenderStepped", onRenderStepped))
	Logger.warn("Silent Aim initialized.")
end

function SilentAim.detach()
	silentMaid:clean()
	currentTarget = nil
	if fovCircle then
		pcall(function()
			fovCircle:Remove()
		end)
		fovCircle = nil
	end
	if getCameraToMouse then
		pcall(function()
			getCameraToMouse.OnClientInvoke = function()
				return realAimCFrame(), false
			end
		end)
	end
	hookInstalled = false
end
return SilentAim

end)
__bundle_register("Features/Combat/AnimationInspector", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Animation Inspector -- a live window listing every animation a selected player is CURRENTLY playing.

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local MarketplaceService = game:GetService("MarketplaceService")

---@module Utility.CoreGuiManager
local CoreGuiManager = require("Utility/CoreGuiManager")
---@module GUI.Library
local Library = require("GUI/Library")
---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

local AnimationInspector = {}

-- Theme (pulled from the Mira Library so the window matches the menu).
local ACCENT  = Library.AccentColor     or Color3.fromRGB(243, 168, 214)
local MAIN    = Library.MainColor       or Color3.fromRGB(40, 32, 50)
local BG      = Library.BackgroundColor or Color3.fromRGB(28, 22, 36)
local FG      = Library.FontColor       or Color3.fromRGB(245, 238, 250)
local OUTLINE = Library.OutlineColor    or Color3.fromRGB(110, 86, 132)
local RISK    = Library.RiskColor       or Color3.fromRGB(255, 96, 128)
local MUTED   = Color3.fromRGB(168, 156, 182)

local MAX_ROWS = 100         -- hard cap so an AP-break flood can't spawn thousands
local UPDATE_INTERVAL = 0.06 -- ~16 Hz live-prop refresh
local LOG_FILE = "mira_animlog.txt"
local LOG_FLUSH_INTERVAL = 1.0

-- State
local running = false
local targetPlayer = nil
local targetName = nil

local screenGui, mainFrame, titleLabel, subLabel, listFrame, emptyLabel

local rows = {}          -- track -> { frame, nameLabel, propLabel, assetId, stoppedConn }
local rowCount = 0

local animatorConn = nil
local charAddedConn = nil
local charRemovingConn = nil
local updateConn = nil
local updateAccum = 0

-- Namecall-hook capture (fade time isn't exposed on AnimationTrack any other way).
local playArgs = setmetatable({}, { __mode = "k" })
local hookActive = false
local oldNamecall = nil

-- Asset-name resolution.
local nameCache = {}     -- assetId -> name | false
local namePending = {}
local nameQueue = {}
local resolverRunning = false

-- File logging (name / id / priority and any changes to them).
local logBuffer = {}
local logFlushAccum = 0
local logSessionStart = 0

-- Small helpers
local function mk(class, props, parent)
	local inst = Instance.new(class)
	for key, value in pairs(props) do
		inst[key] = value
	end
	if parent then
		inst.Parent = parent
	end
	return inst
end

local function fmtNum(value, digits)
	if type(value) ~= "number" then
		return "?"
	end
	return string.format("%." .. (digits or 2) .. "f", value)
end

local function safeGet(fn, fallback)
	local ok, value = pcall(fn)
	if ok and value ~= nil then
		return value
	end
	return fallback
end

-- The real asset behind an AnimationId.
local function assetIdOf(animationId)
	local text = tostring(animationId or "")
	local viaQuery = text:match("[?&]id=(%d+)")
	if viaQuery then
		return tonumber(viaQuery)
	end
	return tonumber(text:match("(%d+)"))
end

-- Query junk (a `?` AND an `&`) beyond a plain asset reference = id-spoof tell.
local function isMutatedId(animationId)
	local text = tostring(animationId or "")
	return text:find("?", 1, true) ~= nil and text:find("&", 1, true) ~= nil
end

local function lookupName(assetId)
	local ok, info = pcall(function()
		return MarketplaceService:GetProductInfo(assetId, Enum.InfoType.Asset)
	end)
	local resolved = (ok and info and info.Name) or false
	nameCache[assetId] = resolved
	namePending[assetId] = nil
	return resolved
end

local function queueName(assetId)
	if not assetId or nameCache[assetId] ~= nil or namePending[assetId] then
		return
	end
	namePending[assetId] = true
	nameQueue[#nameQueue + 1] = assetId
end

-- One background worker chews through lookups (GetProductInfo yields + rate-limits).
local function startResolver()
	if resolverRunning then
		return
	end
	resolverRunning = true
	task.spawn(function()
		while running do
			local assetId = table.remove(nameQueue, 1)
			if assetId then
				lookupName(assetId)
				task.wait(0.3)
			else
				task.wait(0.25)
			end
		end
		resolverRunning = false
	end)
end

-- GUI parenting (exploit-safe: gethui -> CoreGui -> PlayerGui)
local function guiParent()
	local ok, hui = pcall(function()
		return gethui and gethui()
	end)
	if ok and hui then
		return hui
	end
	local ok2, cg = pcall(function()
		return game:GetService("CoreGui")
	end)
	if ok2 and cg then
		return cg
	end
	local lp = Players.LocalPlayer
	return lp and lp:FindFirstChildOfClass("PlayerGui")
end

-- Window
local function buildWindow()
	if screenGui then
		return
	end

	screenGui = Instance.new("ScreenGui")
	screenGui.Name = "MiraAnimInspect"
	screenGui.ResetOnSpawn = false
	screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
	screenGui.DisplayOrder = 9999
	CoreGuiManager.imark(screenGui)

	local ProtectGui = protectgui or (syn and syn.protect_gui) or function() end
	pcall(ProtectGui, screenGui)
	screenGui.Parent = guiParent()

	mainFrame = mk("Frame", {
		Name = "Window",
		Size = UDim2.fromOffset(360, 420),
		Position = UDim2.fromOffset(120, 120),
		BackgroundColor3 = BG,
		BorderSizePixel = 0,
	}, screenGui)
	mk("UICorner", { CornerRadius = UDim.new(0, 6) }, mainFrame)
	mk("UIStroke", { Color = OUTLINE, Thickness = 1, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, mainFrame)

	-- Title bar.
	local titleBar = mk("Frame", {
		Name = "TitleBar",
		Size = UDim2.new(1, 0, 0, 34),
		BackgroundColor3 = MAIN,
		BorderSizePixel = 0,
	}, mainFrame)
	mk("UICorner", { CornerRadius = UDim.new(0, 6) }, titleBar)
	-- Square off the bottom corners of the title bar.
	mk("Frame", {
		Size = UDim2.new(1, 0, 0, 8),
		Position = UDim2.new(0, 0, 1, -8),
		BackgroundColor3 = MAIN,
		BorderSizePixel = 0,
	}, titleBar)

	local accentBar = mk("Frame", {
		Size = UDim2.new(0, 3, 1, -8),
		Position = UDim2.fromOffset(8, 4),
		BackgroundColor3 = ACCENT,
		BorderSizePixel = 0,
	}, titleBar)
	mk("UICorner", { CornerRadius = UDim.new(1, 0) }, accentBar)

	titleLabel = mk("TextLabel", {
		Name = "Title",
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(18, 3),
		Size = UDim2.new(1, -54, 0, 16),
		Font = Enum.Font.GothamBold,
		Text = "Animation Inspector",
		TextColor3 = FG,
		TextSize = 13,
		TextXAlignment = Enum.TextXAlignment.Left,
	}, titleBar)

	subLabel = mk("TextLabel", {
		Name = "Sub",
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(18, 18),
		Size = UDim2.new(1, -54, 0, 13),
		Font = Enum.Font.Gotham,
		Text = "no target",
		TextColor3 = MUTED,
		TextSize = 11,
		TextXAlignment = Enum.TextXAlignment.Left,
	}, titleBar)

	local closeBtn = mk("TextButton", {
		Name = "Close",
		BackgroundColor3 = MAIN,
		Position = UDim2.new(1, -28, 0, 6),
		Size = UDim2.fromOffset(22, 22),
		Font = Enum.Font.GothamBold,
		Text = "X",
		TextColor3 = RISK,
		TextSize = 13,
		AutoButtonColor = true,
	}, titleBar)
	mk("UICorner", { CornerRadius = UDim.new(0, 4) }, closeBtn)
	closeBtn.MouseButton1Click:Connect(function()
		-- Flip the menu toggle off; its OnChanged calls stop().
		local ok = pcall(function()
			local toggles = getgenv and getgenv().Toggles
			if toggles and toggles.AnimationInspector then
				toggles.AnimationInspector:SetValue(false)
				return true
			end
			return false
		end)
		if not ok then
			AnimationInspector.stop()
		end
	end)

	-- Scrolling list of live rows.
	listFrame = mk("ScrollingFrame", {
		Name = "List",
		Position = UDim2.fromOffset(6, 40),
		Size = UDim2.new(1, -12, 1, -46),
		BackgroundColor3 = MAIN,
		BorderSizePixel = 0,
		ScrollBarThickness = 4,
		ScrollBarImageColor3 = ACCENT,
		CanvasSize = UDim2.new(0, 0, 0, 0),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollingDirection = Enum.ScrollingDirection.Y,
	}, mainFrame)
	mk("UICorner", { CornerRadius = UDim.new(0, 4) }, listFrame)
	mk("UIListLayout", {
		FillDirection = Enum.FillDirection.Vertical,
		SortOrder = Enum.SortOrder.LayoutOrder,
		Padding = UDim.new(0, 3),
	}, listFrame)
	mk("UIPadding", {
		PaddingTop = UDim.new(0, 4),
		PaddingBottom = UDim.new(0, 4),
		PaddingLeft = UDim.new(0, 4),
		PaddingRight = UDim.new(0, 4),
	}, listFrame)

	emptyLabel = mk("TextLabel", {
		Name = "Empty",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 40),
		Font = Enum.Font.Gotham,
		Text = "no animations playing",
		TextColor3 = MUTED,
		TextSize = 12,
	}, listFrame)

	pcall(function()
		Library:MakeDraggable(mainFrame, 34)
	end)
end

-- Rows
local function updateEmptyState()
	if emptyLabel then
		emptyLabel.Visible = rowCount == 0
	end
	if subLabel then
		local who = targetName or "no target"
		subLabel.Text = string.format("%s  ·  %d playing", who, rowCount)
	end
end

-- File logging -- name / id / priority, and any change to them, appended to a txt in the executor's workspace folder for later reading.
local function loggingEnabled()
	return Configuration.expectToggleValue("AnimInspectLogToFile") == true
end

local function writeLog(text)
	pcall(function()
		if appendfile then
			appendfile(LOG_FILE, text)
		elseif writefile and readfile and isfile then
			local existing = isfile(LOG_FILE) and readfile(LOG_FILE) or ""
			if #existing < 5 * 1024 * 1024 then
				writefile(LOG_FILE, existing .. text)
			end
		end
	end)
end

local function flushLog()
	if #logBuffer == 0 then
		return
	end
	local text = table.concat(logBuffer, "\n") .. "\n"
	logBuffer = {}
	writeLog(text)
end

local function logLine(text)
	if not loggingEnabled() then
		return
	end
	logBuffer[#logBuffer + 1] = string.format("[%8.2f] %s", os.clock() - logSessionStart, text)
	if #logBuffer >= 400 then
		flushLog()
	end
end

local function updateRow(row)
	local track = row.track
	local anim = safeGet(function() return track.Animation end)
	local animationId = anim and tostring(anim.AnimationId) or nil
	local mutated = isMutatedId(animationId)

	local assetId = row.assetId
	local resolved = assetId and nameCache[assetId] or nil
	local displayName = resolved or (anim and anim.Name ~= "" and anim.Name) or "?"
	if displayName == "Animation" and assetId then
		displayName = "id:" .. tostring(assetId)
	end

	local priorityName = tostring(safeGet(function() return track.Priority.Name end, "?"))

	row.nameLabel.Text = string.format("%s   ·   %s", displayName, priorityName)
	row.nameLabel.TextColor3 = mutated and RISK or FG

	local args = playArgs[track]
	local fade = args and fmtNum(args.fade) or "?"

	row.propLabel.Text = string.format(
		"spd %s · wt %s/%s · len %s · t %s · fade %s%s",
		fmtNum(safeGet(function() return track.Speed end)),
		fmtNum(safeGet(function() return track.WeightCurrent end)),
		fmtNum(safeGet(function() return track.WeightTarget end)),
		fmtNum(safeGet(function() return track.Length end)),
		fmtNum(safeGet(function() return track.TimePosition end)),
		fade,
		mutated and "  · MUTATED" or ""
	)

	row.idLabel.Text = "id " .. (animationId or "?")
	row.idLabel.TextColor3 = mutated and RISK or ACCENT

	-- File log: one line on first sight, then any change to name / id / priority.
	local idStr = animationId or "?"
	if row.loggedId == nil then
		row.loggedName = displayName
		row.loggedId = idStr
		row.loggedPriority = priorityName
		logLine(string.format('[+] name="%s" id=%s priority=%s', displayName, idStr, priorityName))
	else
		if idStr ~= row.loggedId then
			logLine(string.format("[~] id=%s  id: %s -> %s", row.loggedId, row.loggedId, idStr))
			row.loggedId = idStr
		end
		if displayName ~= row.loggedName then
			logLine(string.format('[~] id=%s  name: "%s" -> "%s"', row.loggedId, row.loggedName, displayName))
			row.loggedName = displayName
		end
		if priorityName ~= row.loggedPriority then
			logLine(string.format("[~] id=%s  priority: %s -> %s", row.loggedId, row.loggedPriority, priorityName))
			row.loggedPriority = priorityName
		end
	end
end

local function removeRow(track)
	local row = rows[track]
	if not row then
		return
	end
	if row.loggedId then
		logLine(string.format("[-] id=%s  (stopped)", row.loggedId))
	end
	rows[track] = nil
	rowCount = rowCount - 1
	if row.stoppedConn then
		pcall(function() row.stoppedConn:Disconnect() end)
	end
	if row.frame then
		row.frame:Destroy()
	end
	updateEmptyState()
end

local function addRow(track)
	if rows[track] or rowCount >= MAX_ROWS or not listFrame then
		return
	end

	local frame = mk("Frame", {
		Name = "Row",
		Size = UDim2.new(1, 0, 0, 54),
		BackgroundColor3 = BG,
		BorderSizePixel = 0,
	}, listFrame)
	mk("UICorner", { CornerRadius = UDim.new(0, 4) }, frame)
	mk("UIStroke", { Color = OUTLINE, Thickness = 1, Transparency = 0.4 }, frame)

	local nameLabel = mk("TextLabel", {
		Name = "Name",
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(8, 4),
		Size = UDim2.new(1, -12, 0, 15),
		Font = Enum.Font.GothamSemibold,
		Text = "...",
		TextColor3 = FG,
		TextSize = 12,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
	}, frame)

	local propLabel = mk("TextLabel", {
		Name = "Props",
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(8, 20),
		Size = UDim2.new(1, -12, 0, 14),
		Font = Enum.Font.Code,
		Text = "",
		TextColor3 = MUTED,
		TextSize = 11,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
	}, frame)

	local idLabel = mk("TextLabel", {
		Name = "Id",
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(8, 35),
		Size = UDim2.new(1, -12, 0, 13),
		Font = Enum.Font.Code,
		Text = "",
		TextColor3 = ACCENT,
		TextSize = 11,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
	}, frame)

	local anim = safeGet(function() return track.Animation end)
	local assetId = anim and assetIdOf(anim.AnimationId) or nil
	queueName(assetId)

	local row = { frame = frame, nameLabel = nameLabel, propLabel = propLabel, idLabel = idLabel, assetId = assetId, track = track }
	rows[track] = row
	rowCount = rowCount + 1

	-- DELETE the row the instant the animation ends.
	row.stoppedConn = track.Stopped:Connect(function()
		removeRow(track)
	end)

	updateRow(row)
	updateEmptyState()
end

local function clearRows()
	for track in pairs(rows) do
		removeRow(track)
	end
	rowCount = 0
	rows = {}
	updateEmptyState()
end

-- Live refresh loop: repaints visible rows and prunes tracks that stopped without firing .Stopped.
local function startUpdateLoop()
	if updateConn then
		return
	end
	updateConn = RunService.RenderStepped:Connect(function(dt)
		if not running then
			return
		end
		updateAccum = updateAccum + dt
		if updateAccum < UPDATE_INTERVAL then
			return
		end
		updateAccum = 0

		local dead = nil
		for track, row in pairs(rows) do
			if not safeGet(function() return track.IsPlaying end, false) then
				dead = dead or {}
				dead[#dead + 1] = track
			else
				updateRow(row)
			end
		end
		if dead then
			for _, track in ipairs(dead) do
				removeRow(track)
			end
		end

		logFlushAccum = logFlushAccum + UPDATE_INTERVAL
		if logFlushAccum >= LOG_FLUSH_INTERVAL then
			logFlushAccum = 0
			flushLog()
		end
	end)
end

-- Namecall hook -- capture the caller's Play(fade, weight, speed) args.
local function installHook()
	if hookActive then
		return
	end
	if not (hookmetamethod and getnamecallmethod and checkcaller) then
		return -- fade time simply stays "?" without exploit hook support
	end
	local ok = pcall(function()
		oldNamecall = hookmetamethod(game, "__namecall", function(self, ...)
			-- NOTE: deliberately NOT skipping checkcaller() calls.
			if not hookActive then
				return oldNamecall(self, ...)
			end
			if getnamecallmethod() == "Play" then
				local okClass, isTrack = pcall(game.IsA, self, "AnimationTrack")
				if okClass and isTrack then
					local a, b, c = ...
					playArgs[self] = {
						fade = type(a) == "number" and a or 0.1,
						weight = type(b) == "number" and b or 1,
						speed = type(c) == "number" and c or 1,
					}
				end
			end
			return oldNamecall(self, ...)
		end)
	end)
	hookActive = ok
end

local function removeHook()
	if not hookActive then
		return
	end
	hookActive = false
	if oldNamecall and hookmetamethod then
		pcall(function()
			hookmetamethod(game, "__namecall", oldNamecall)
		end)
		oldNamecall = nil
	end
end

-- Target binding
local function bindAnimator(animator, character)
	if animatorConn then
		pcall(function() animatorConn:Disconnect() end)
		animatorConn = nil
	end
	if not animator then
		return
	end

	animatorConn = animator.AnimationPlayed:Connect(function(track)
		if running then
			addRow(track)
		end
	end)

	-- Seed with whatever is already playing.
	for _, track in ipairs(safeGet(function() return animator:GetPlayingAnimationTracks() end, {})) do
		addRow(track)
	end
end

local function hookCharacter(character)
	clearRows()
	if not character then
		return
	end
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
	if animator then
		bindAnimator(animator, character)
		return
	end
	-- Character just spawned; its Animator may not exist yet.
	task.spawn(function()
		local hum = character:WaitForChild("Humanoid", 5)
		local anim = hum and hum:WaitForChild("Animator", 5)
		if anim and running and targetPlayer and targetPlayer.Character == character then
			bindAnimator(anim, character)
		end
	end)
end

local function bindPlayer(player)
	if charAddedConn then
		pcall(function() charAddedConn:Disconnect() end)
		charAddedConn = nil
	end
	if charRemovingConn then
		pcall(function() charRemovingConn:Disconnect() end)
		charRemovingConn = nil
	end

	targetPlayer = player
	targetName = player and player.Name or nil

	if titleLabel then
		titleLabel.Text = player and ("Animation Inspector — " .. player.Name) or "Animation Inspector"
	end
	updateEmptyState()

	if not player then
		clearRows()
		return
	end

	charAddedConn = player.CharacterAdded:Connect(function(character)
		if running and targetPlayer == player then
			hookCharacter(character)
		end
	end)
	charRemovingConn = player.CharacterRemoving:Connect(function()
		if running and targetPlayer == player then
			clearRows()
		end
	end)

	hookCharacter(player.Character)
end

local function resolveByName(name)
	if not name or name == "" then
		return nil
	end
	for _, p in ipairs(Players:GetPlayers()) do
		if p.Name == name then
			return p
		end
	end
	local lower = string.lower(name)
	for _, p in ipairs(Players:GetPlayers()) do
		if string.lower(p.Name) == lower or string.lower(p.DisplayName) == lower then
			return p
		end
	end
	return nil
end

-- Public API
function AnimationInspector.startByName(name)
	local player = resolveByName(name)
	if not player then
		pcall(function()
			Library:Notify("Animation Inspector: pick a player first.", 4)
		end)
		pcall(function()
			local toggles = getgenv and getgenv().Toggles
			if toggles and toggles.AnimationInspector then
				toggles.AnimationInspector:SetValue(false)
			end
		end)
		return
	end

	running = true
	if loggingEnabled() then
		logBuffer = {}
		logFlushAccum = 0
		logSessionStart = os.clock()
		pcall(function()
			if writefile then
				writefile(LOG_FILE, string.format(
					"=== Animation Inspector log | target=%s | %s ===\n",
					player.Name, os.date("%Y-%m-%d %H:%M:%S")
				))
			end
		end)
	end
	buildWindow()
	if screenGui then
		screenGui.Enabled = true
	end
	installHook()
	startResolver()
	startUpdateLoop()
	bindPlayer(player)
end

function AnimationInspector.setTargetByName(name)
	if not running then
		return
	end
	local player = resolveByName(name)
	if player then
		bindPlayer(player)
	end
end

function AnimationInspector.stop()
	if not running then
		return
	end
	running = false

	if updateConn then
		pcall(function() updateConn:Disconnect() end)
		updateConn = nil
	end
	if animatorConn then
		pcall(function() animatorConn:Disconnect() end)
		animatorConn = nil
	end
	if charAddedConn then
		pcall(function() charAddedConn:Disconnect() end)
		charAddedConn = nil
	end
	if charRemovingConn then
		pcall(function() charRemovingConn:Disconnect() end)
		charRemovingConn = nil
	end

	clearRows()
	removeHook()
	flushLog()

	if screenGui then
		screenGui:Destroy()
		screenGui = nil
		mainFrame, titleLabel, subLabel, listFrame, emptyLabel = nil, nil, nil, nil, nil
	end

	targetPlayer = nil
	targetName = nil
end

-- Full teardown (script detach): tear everything down for good.
function AnimationInspector.detach()
	AnimationInspector.stop()
end

return AnimationInspector
end)
__bundle_register("Features/Exploits/AnimationFlooder", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Animation Flooder: plays the decoy attack-animation flood on a selected player's character.

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")
---@module GUI.Library
local Library = require("GUI/Library")

local AnimationFlooder = {}

-- Fallback pool if the timing store isn't populated yet (same ids the AP breaker uses).
local FALLBACK_IDS = {
	"rbxassetid://9726608174",
	"rbxassetid://111647546998749",
	"rbxassetid://5064195992",
	"rbxassetid://6607519294",
	"rbxassetid://7600160919",
}
local MOVE_TYPES = { M1 = true, Mantra = true, Critical = true }
local FLOOD_PRIORITY = Enum.AnimationPriority.Action
local MAX_POOL = 200

-- State.
local running = false
local targetPlayer = nil
local targetName = nil
local currentAnimator = nil
local trackPool = {}
local accumulator = 0
local poolCursor = 0
local renderConn = nil
local charAddedConn = nil
local charRemovingConn = nil

-- Helpers
local function getIntensity()
	local value = Configuration.expectOptionValue("AnimationFlooderIntensity")
	if type(value) ~= "number" then
		return 8
	end
	return value
end

-- Attack animation ids straight out of the timing store; fall back to the hard list.
local function collectAttackIds()
	local ids, seen = {}, {}
	pcall(function()
		local TimingStore = require("Game/Timings/SaveManager")
		local list = TimingStore.as:list()
		for _, entry in ipairs(list) do
			if MOVE_TYPES[entry.tag] then
				local id = entry:id()
				if type(id) == "string" and id:match("%d") and not seen[id] then
					seen[id] = true
					ids[#ids + 1] = id
				end
			end
		end
	end)
	if #ids == 0 then
		ids = FALLBACK_IDS
	end
	return ids
end

local function destroyPool()
	for _, track in ipairs(trackPool) do
		pcall(function() track:Stop(0); track:Destroy() end)
	end
	trackPool = {}
	poolCursor = 0
end

-- Load our decoy pool onto the TARGET's animator.
local function loadPool(animator, idList)
	destroyPool()
	if type(idList) ~= "table" or #idList == 0 then
		return
	end

	local targetSize = math.min(MAX_POOL, math.max(#idList, 20))
	local cursor, attempts, maxAttempts = 0, 0, targetSize + #idList + 8
	while #trackPool < targetSize and attempts < maxAttempts do
		attempts = attempts + 1
		cursor = cursor % #idList + 1
		local id = idList[cursor]
		if not string.find(id, "://", 1, true) then
			id = "rbxassetid://" .. id
		end
		local animation = Instance.new("Animation")
		animation.AnimationId = id
		local ok, track = pcall(function() return animator:LoadAnimation(animation) end)
		if ok and track then
			track.Looped = false
			pcall(function() track.Priority = FLOOD_PRIORITY end)
			trackPool[#trackPool + 1] = track
		end
	end
end

-- Target binding
local function bindCharacter(character)
	currentAnimator = nil
	destroyPool()
	if not character then
		return
	end
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
	if animator then
		currentAnimator = animator
		loadPool(animator, collectAttackIds())
		return
	end
	-- Character just spawned; wait for its Animator.
	task.spawn(function()
		local hum = character:WaitForChild("Humanoid", 5)
		local anim = hum and hum:WaitForChild("Animator", 5)
		if anim and running and targetPlayer and targetPlayer.Character == character then
			currentAnimator = anim
			loadPool(anim, collectAttackIds())
		end
	end)
end

local function bindPlayer(player)
	if charAddedConn then
		pcall(function() charAddedConn:Disconnect() end)
		charAddedConn = nil
	end
	if charRemovingConn then
		pcall(function() charRemovingConn:Disconnect() end)
		charRemovingConn = nil
	end

	targetPlayer = player
	targetName = player and player.Name or nil

	if not player then
		currentAnimator = nil
		destroyPool()
		return
	end

	charAddedConn = player.CharacterAdded:Connect(function(character)
		if running and targetPlayer == player then
			bindCharacter(character)
		end
	end)
	charRemovingConn = player.CharacterRemoving:Connect(function()
		if running and targetPlayer == player then
			currentAnimator = nil
			destroyPool()
		end
	end)

	bindCharacter(player.Character)
end

local function resolveByName(name)
	if not name or name == "" then
		return nil
	end
	for _, p in ipairs(Players:GetPlayers()) do
		if p.Name == name then
			return p
		end
	end
	local lower = string.lower(name)
	for _, p in ipairs(Players:GetPlayers()) do
		if string.lower(p.Name) == lower or string.lower(p.DisplayName) == lower then
			return p
		end
	end
	return nil
end

-- Flood loop
local function startLoop()
	if renderConn then
		return
	end
	renderConn = RunService.RenderStepped:Connect(function(deltaTime)
		if not running then
			return
		end
		local animator = currentAnimator
		if not animator or #trackPool == 0 then
			return
		end

		local interval = 1 / math.max(1, getIntensity())
		accumulator = math.min(accumulator + deltaTime, interval * 2)

		local burstsThisFrame = 0
		while accumulator >= interval and burstsThisFrame < 50 do
			accumulator = accumulator - interval
			burstsThisFrame = burstsThisFrame + 1

			-- Prefer an idle track; if all are mid-play, hard-restart the next one so a fresh AnimationPlayed still fires.
			local chosen = nil
			for _ = 1, #trackPool do
				poolCursor = poolCursor % #trackPool + 1
				local candidate = trackPool[poolCursor]
				if candidate and not candidate.IsPlaying then
					chosen = candidate
					break
				end
			end
			local recycled = false
			if not chosen then
				poolCursor = poolCursor % #trackPool + 1
				chosen = trackPool[poolCursor]
				recycled = chosen ~= nil
			end
			if chosen then
				pcall(function()
					if recycled then
						chosen:Stop(0)
					end
					chosen.Priority = FLOOD_PRIORITY
					chosen:Play(0.1, 1, 1)
				end)
			end
		end
	end)
end

-- Public API
function AnimationFlooder.startByName(name)
	local player = resolveByName(name)
	if not player then
		pcall(function() Library:Notify("Animation Flooder: pick a target player first.", 4) end)
		pcall(function()
			local toggles = getgenv and getgenv().Toggles
			if toggles and toggles.AnimationFlooder then
				toggles.AnimationFlooder:SetValue(false)
			end
		end)
		return
	end
	running = true
	startLoop()
	bindPlayer(player)
end

function AnimationFlooder.setTargetByName(name)
	if not running then
		return
	end
	local player = resolveByName(name)
	if player then
		bindPlayer(player)
	end
end

function AnimationFlooder.stop()
	if not running then
		return
	end
	running = false
	if renderConn then
		pcall(function() renderConn:Disconnect() end)
		renderConn = nil
	end
	if charAddedConn then
		pcall(function() charAddedConn:Disconnect() end)
		charAddedConn = nil
	end
	if charRemovingConn then
		pcall(function() charRemovingConn:Disconnect() end)
		charRemovingConn = nil
	end
	destroyPool()
	currentAnimator = nil
	targetPlayer = nil
	targetName = nil
	accumulator = 0
end

function AnimationFlooder.detach()
	AnimationFlooder.stop()
end

return AnimationFlooder
end)
__bundle_register("Features/Game/Spoofing", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
	---@module Utility.Maid
	local Maid = require("Utility/Maid")

	---@module Utility.Signal
	local Signal = require("Utility/Signal")

	---@module Utility.Configuration
	local Configuration = require("Utility/Configuration")

	---@module Utility.Logger
	local Logger = require("Utility/Logger")

