		if talentDismiss then
			table.insert(roll2Dismissals, talentDismiss)
		end
	end
end)

-- Reveal AP Break Animations (ported from apc) Standalone detector, independent of the anti-AP breaker.
local REVEAL_FULL_WEIGHT = 1

-- [track] = original WeightTarget, captured on first touch so the forced weight is handed back byte-for-byte once we stop touching the track.
local revealedTracks = setmetatable({}, { __mode = "k" })

---Snapshot a track's weight once, before we override it.
---@param track AnimationTrack
local function captureTrack(track)
	if revealedTracks[track] == nil then
		revealedTracks[track] = track.WeightTarget
	end
end

---Hand a track's weight back to what it was before we touched it.
---@param track AnimationTrack
---@param savedWeight number
local function restoreRevealedTrack(track, savedWeight)
	pcall(function()
		track:AdjustWeight(savedWeight, 0)
	end)
end

---Restore every track we've currently got altered and forget them.
local function restoreAllRevealed()
	for track, savedWeight in next, revealedTracks do
		restoreRevealedTrack(track, savedWeight)
	end

	revealedTracks = setmetatable({}, { __mode = "k" })
end

-- Weight to force on a non-attack track (nil = leave alone): Action2/3/4 -> 0 to hide mask copies.
---@param track AnimationTrack
---@return number?
local function revealWeightFor(track)
	local priority = track.Priority

	if priority == Enum.AnimationPriority.Action2
		or priority == Enum.AnimationPriority.Action3
		or priority == Enum.AnimationPriority.Action4 then
		return 0
	end

	if priority == Enum.AnimationPriority.Core or priority == Enum.AnimationPriority.Idle then
		return REVEAL_FULL_WEIGHT
	end

	if track.WeightCurrent <= 0.01 then
		return REVEAL_FULL_WEIGHT
	end

	local threshold = tonumber(Configuration.expectOptionValue("RevealWeightThreshold")) or 0.5

	if track.WeightCurrent < threshold then
		return REVEAL_FULL_WEIGHT
	end

	return nil
end

---Update reveal animations.
local updateRevealAnimations = (function()
	-- Tracks we re-pinned THIS frame.
	local touched = {}

	local localPlayer = players.LocalPlayer
	if not localPlayer then
		return
	end

	for _, player in next, players:GetPlayers() do
		if player == localPlayer then
			continue
		end

		local character = player.Character
		local humanoid = character and character:FindFirstChildOfClass("Humanoid")
		local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
		if not animator then
			continue
		end

		local ok, tracks = pcall(function()
			return animator:GetPlayingAnimationTracks()
		end)
		if not ok or type(tracks) ~= "table" then
			continue
		end

		for _, track in next, tracks do
			-- Never touch a registered attack: leaving those untouched is exactly what keeps reveal from ever interfering with the auto-defense.
			local animation = track.Animation
			if animation and TimingStore.as:index(tostring(animation.AnimationId)) ~= nil then
				continue
			end

			local weight = revealWeightFor(track)
			if weight ~= nil then
				captureTrack(track)
				touched[track] = true
				pcall(function()
					track:AdjustWeight(weight, 0)
				end)
			end
		end
	end

	-- Restore + forget anything we held but didn't re-pin this frame.
	for track, savedWeight in next, revealedTracks do
		if not touched[track] then
			restoreRevealedTrack(track, savedWeight)
			revealedTracks[track] = nil
		end
	end
end)

