}

-- Get game name dynamically.
local gameName = "Unknown"
pcall(function()
	local marketplaceService = game:GetService("MarketplaceService")
	local productInfo = marketplaceService:GetProductInfo(game.PlaceId)
	gameName = productInfo.Name or "Unknown"
end)

local MENU_TITLE = "Mira"

--- Initialize the trimmed Arsenal menu.
---@param window table
function Menu.initArsenal(window)
	-- Combat: Aimbot.
	local combat = window:AddTab("Combat")
	do
		local aimbot = combat:AddLeftGroupbox("Aimbot")

		local aimbotToggle = aimbot:AddToggle("Aimbot", {
			Text = "Enabled",
			Default = false,
			Tooltip = "Master switch. Hold the aim key below to actually lock on.",
		})
		aimbotToggle:AddKeyPicker("AimbotKeybind", {
			-- "None" (not "N/A") is the unbound sentinel Hold-mode GetState checks; "N/A" would hit Enum.KeyCode["N/A"] and crash the moment it builds.
			Default = "None",
			Mode = "Hold",
			Text = "Aim Key",
			Tooltip = "Hold to aim, release to stop.",
		})

		aimbot:AddDropdown("AimbotMethod", {
			Text = "Aim Method",
			Values = { "Camera", "Mouse" },
			Default = "Camera",
			Tooltip = "Camera = rotates the view (reliable in first-person). Mouse = moves the cursor (for free-cursor aim).",
		})

		aimbot:AddDropdown("AimbotPrimaryPart", {
			Text = "Primary Aim Part",
			Values = { "Head", "Torso", "Legs" },
			Default = "Head",
			Tooltip = "Preferred part to aim at.",
		})
		aimbot:AddDropdown("AimbotSecondaryPart", {
			Text = "Secondary Aim Part",
			Values = { "None", "Head", "Torso", "Legs" },
			Default = "Torso",
			Tooltip = "Fallback when the primary part isn't on the target's rig.",
		})

		aimbot:AddSlider("AimbotSmoothness", {
			Text = "Smoothness",
			Default = 5,
			Min = 0,
			Max = 20,
			Rounding = 1,
			Tooltip = "0 = instant snap. Higher = slower and more legit.",
		})
		aimbot:AddSlider("AimbotMaxDistance", {
			Text = "Max Distance",
			Default = 500,
			Min = 10,
			Max = 1000,
			Rounding = 0,
			Suffix = " studs",
		})
		aimbot:AddToggle("AimbotWallCheck", {
			Text = "Wall Check",
			Default = true,
			Tooltip = "Only target players you have line of sight to.",
		})
		aimbot:AddToggle("AimbotTeamCheck", {
			Text = "Team Check",
			Default = true,
			Tooltip = "Never lock onto players on your own team.",
		})

		local fov = combat:AddRightGroupbox("Aimbot FOV")
		fov:AddToggle("AimbotShowCircle", {
			Text = "Show FOV Circle",
			Default = true,
		})
		fov:AddSlider("AimbotFOV", {
			Text = "FOV",
			Default = 120,
			Min = 1,
			Max = 2000,
			Rounding = 0,
		})
		fov:AddLabel("Circle Color"):AddColorPicker("AimbotCircleColor", {
			Default = Color3.fromRGB(255, 255, 255),
		})
		fov:AddToggle("AimbotRainbow", {
			Text = "Rainbow Circle",
			Default = false,
		})

		local trigger = combat:AddRightGroupbox("Triggerbot")
		local triggerToggle = trigger:AddToggle("Triggerbot", {
			Text = "Enabled",
			Default = false,
		})
		triggerToggle:AddKeyPicker("TriggerbotKeybind", {
			Default = "None",
			Mode = "Hold",
			Text = "Trigger Key",
			Tooltip = "Optional. Hold to fire; leave unbound to fire whenever your crosshair is on an enemy.",
		})
		trigger:AddSlider("TriggerbotDelay", {
			Text = "Reaction Delay",
			Default = 0,
			Min = 0,
			Max = 500,
			Rounding = 0,
			Suffix = "ms",
			Tooltip = "How long your crosshair must sit on an enemy before it fires. 0 = instant.",
		})
	end

	-- Game: Movement (WalkSpeed / Fly / Noclip / Infinite Jump).
	local gameTab = window:AddTab("Game")
	do
		local move = gameTab:AddLeftGroupbox("Movement")

		local walkToggle = move:AddToggle("WalkSpeedEnabled", {
			Text = "WalkSpeed",
			Default = false,
		})
		local walkDep = move:AddDependencyBox()
		walkDep:AddSlider("WalkSpeed", {
			Text = "WalkSpeed",
			Default = 16,
			Min = 16,
			Max = 500,
			Rounding = 0,
		})
		walkDep:SetupDependencies({ { walkToggle, true } })

		local flyToggle = move:AddToggle("Fly", {
			Text = "Fly",
			Default = false,
			Tooltip = "WASD to move, Space up, Shift down.",
		})
		local flyDep = move:AddDependencyBox()
		flyDep:AddSlider("FlySpeed", {
			Text = "Fly Speed",
			Default = 50,
			Min = 10,
			Max = 500,
			Rounding = 0,
		})
		flyDep:SetupDependencies({ { flyToggle, true } })

		move:AddToggle("Noclip", {
			Text = "Noclip",
			Default = false,
		})
		move:AddToggle("InfiniteJump", {
			Text = "Infinite Jump",
			Default = false,
		})
	end

	-- Visuals: Player ESP + visual removals + Field of View.
	local visuals = window:AddTab("Visuals")
	do
		local esp = visuals:AddLeftGroupbox("Player ESP")
		esp:AddToggle("ESPEnabled", { Text = "Enabled", Default = false })
		esp:AddToggle("ESPBox", { Text = "Box", Default = true })
		esp:AddToggle("ESPName", { Text = "Name", Default = true })
		esp:AddToggle("ESPDistance", { Text = "Distance", Default = true })
		esp:AddToggle("ESPWeapon", {
			Text = "Weapon",
			Default = false,
			Tooltip = "Shows the equipped weapon (or None).",
		})
		esp:AddToggle("ESPTracer", { Text = "Tracer", Default = false })
		esp:AddToggle("ESPTeamCheck", {
			Text = "Team Check",
			Default = true,
			Tooltip = "Ignore players on your own team.",
		})
		esp:AddSlider("ESPMaxDistance", {
			Text = "Max Distance",
			Default = 1000,
			Min = 10,
			Max = 2000,
			Rounding = 0,
			Suffix = " studs",
		})
		esp:AddLabel("ESP Color"):AddColorPicker("ESPColor", {
			Default = Color3.fromRGB(255, 60, 60),
		})

		local world = visuals:AddRightGroupbox("World Visuals")
		world:AddToggle("NoFog", { Text = "No Fog", Default = false })
		world:AddToggle("NoBlur", { Text = "No Blur", Default = false })
		world:AddToggle("NoBlind", { Text = "No Blind", Default = false })
		world:AddToggle("NoShadows", { Text = "No Shadows", Default = false })

		local fovToggle = world:AddToggle("ModifyFieldOfView", {
			Text = "Modify Field Of View",
			Default = false,
		})
		local fovDep = world:AddDependencyBox()
		fovDep:AddSlider("FieldOfView", {
			Text = "Field Of View",
			Default = 90,
			Min = 1,
			Max = 120,
			Rounding = 0,
		})
		fovDep:SetupDependencies({ { fovToggle, true } })
	end

	-- Settings tab — identical to Deepwoken.
	MiraTab.init(window)

	-- Admin panel — only appears for whitelisted UserIds.
	AdminTab.init(window)
end

---Initialize menu.
function Menu.init()
	-- Create window.
	local window = Library:CreateWindow({
		Title = MENU_TITLE,
		Center = true,
		AutoShow = not shared.Mira.silent,
		TabPadding = 12,  -- Improved spacing
		MenuFadeTime = 0.0,
	})

	-- Everything Mira writes lives under one "Mira" folder.
	local configFolder = ARSENAL_PLACES[game.PlaceId] and "Mira/Arsenal-Config" or "Mira/deepwoken-config"

	-- Configure ThemeManager.
	ThemeManager:SetLibrary(Library)
	ThemeManager:SetFolder("Mira/themes")

	-- Configure SaveManager.
	SaveManager:SetLibrary(Library)
	SaveManager:IgnoreThemeSettings()
	SaveManager:SetFolder(configFolder)
	SaveManager:SetIgnoreIndexes({
		"Fly",
		"NoClip",
		"Speedhack",
		"InfiniteJump",
		"TweenToObjective",
		"TweenToBack",
	})

	-- Initialize all tabs.
	if ARSENAL_PLACES[game.PlaceId] then
		Menu.initArsenal(window)
	else
		CombatTab.init(window)

		GameTab.init(window)
		VisualsTab.init(window)
		AutomationTab.init(window)
		ExploitTab.init(window)
		MiraTab.init(window)
		AdminTab.init(window)
	end


	-- Load default theme after settings are built.
	ThemeManager:LoadDefault()

	-- Last update.
	local lastUpdate = os.clock()

	-- Update watermark.
	menuMaid:add(renderStepped:connect(
		"Menu_WatermarkUpdate",
		LPH_NO_VIRTUALIZE(function()
			if os.clock() - lastUpdate <= 0.5 then
				return
			end

			lastUpdate = os.clock()

			-- Get stats.
			local networkStats = stats:FindFirstChild("Network")
			local workspaceStats = stats:FindFirstChild("Workspace")
			local performanceStats = stats:FindFirstChild("PerformanceStats")
			local serverStats = networkStats and networkStats:FindFirstChild("ServerStatsItem") or nil

			-- Get data.
			local pingData = serverStats and serverStats:FindFirstChild("Data Ping") or nil
			local heartbeatData = workspaceStats and workspaceStats:FindFirstChild("Heartbeat") or nil
			local cpuData = performanceStats and performanceStats:FindFirstChild("CPU") or nil
			local gpuData = performanceStats and performanceStats:FindFirstChild("GPU") or nil

			-- Set values.
			local ping = pingData and pingData:GetValue() or 0.0
			local fps = heartbeatData and heartbeatData:GetValue() or 0.0
			local cpu = cpuData and cpuData:GetValue() or 0.0
			local gpu = gpuData and gpuData:GetValue() or 0.0

			-- String.
			local str = string.format("%s | %.2fms | %.1f/s | %.1fms | %.1fms", MENU_TITLE, ping, fps, cpu, gpu)

			-- Character/mouse data is only needed for the debug readout, so compute it (and the deprecated :GetMouse() call) only when that's actually shown.
			if Configuration.expectToggleValue("ShowDebugInformation") then
				local character = players.LocalPlayer and players.LocalPlayer.Character
				local humanoidRootPart = character and character:FindFirstChild("HumanoidRootPart")
				local position = humanoidRootPart and humanoidRootPart.Position
				local positionFormat = position
						and string.format("(%.2f, %.2f, %.2f)", position.X, position.Y, position.Z)
					or "N/A"
				local mouse = players.LocalPlayer and players.LocalPlayer:GetMouse()

				str = str .. string.format(" | %s", positionFormat)
				str = str .. string.format(" | %s", mouse and mouse.Target and mouse.Target:GetFullName() or "N/A")
			end

			-- Set watermark.
			Library:SetWatermark(str)
		end)
	))

	local inputBegan = Signal.new(userInputService.InputBegan)

	inputBegan:connect("Menu_InputBegan", function(input, gameProcessed)
		if gameProcessed then
			return
		end

		if not Configuration.expectToggleValue("ShowDebugInformation") then
			return
		end

		if input.KeyCode == Enum.KeyCode.F8 then
			local mouse = players.LocalPlayer and players.LocalPlayer:GetMouse()
			local target = mouse and mouse.Target
			if not target then
				return
			end

			target.Name = tostring(math.random(100000, 1000000))

			return Logger.mnnotify("The target has been renamed to '%s' as a marker.", target.Name)
		end

		if input.KeyCode == Enum.KeyCode.Equals and Library.Recording then
			local Character = players.LocalPlayer and players.LocalPlayer.Character
			local HumanoidRootPart = Character and Character:FindFirstChild("HumanoidRootPart")
			local Position = HumanoidRootPart and HumanoidRootPart.Position
			local PositionFormat = Position
					and string.format("CFrame.new(%.2f, %.2f, %.2f)", Position.X, Position.Y, Position.Z)
				or "N/A"

			Library.PositionList[#Library.PositionList + 1] = PositionFormat
		end
	end)

	-- Configure Library.
	Library.ToggleKeybind = Options.MenuKeybind

	-- Load auto-load config.
	SaveManager.OnLoadComplete = function()
		pcall(function() ThemeManager:ThemeUpdate() end)
	end

	SaveManager:LoadAutoloadConfig()

	-- Final colour sweep.
	pcall(function() ThemeManager:ThemeUpdate() end)
	task.spawn(function()
		for _ = 1, 3 do
			task.wait(0.15)
			pcall(function() ThemeManager:ThemeUpdate() end)
		end
	end)

	-- Log menu initialization.
	Logger.warn("Menu initialized.")
end

---Detach menu.
function Menu.detach()
	menuMaid:clean()


	Library:Unload()

	Logger.warn("Menu detached.")
end

-- Return Menu module.
return Menu
end)






__bundle_register("Menu/AdminTab", function(require, _LOADED, __bundle_register, __bundle_modules)
-- AdminTab module -- developer-only admin control panel.
local AdminTab = {}

---@module GUI.Library
local Library = require("GUI/Library")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Features.Admin
local Admin = require("Features/Admin")

---@module Features.Game.Monitoring
local Monitoring = require("Features/Game/Monitoring")

---@module Features.Exploits.AnimationFlooder
local AnimationFlooder = require("Features/Exploits/AnimationFlooder")

---@module Features.Combat.AnimationInspector
local AnimationInspector = require("Features/Combat/AnimationInspector")

local Players = game:GetService("Players")

-- Teleport destinations the ;tp command accepts (see Features/Game/Teleport.lua).
local TP_DESTINATIONS = {
	"EasternLuminant",
	"EtreanLuminant",
	"Depths",
	"Voidheart",
	"TrialOfOne",
	"GuildDoor",
}

---Resolve a live Player from a username (the roster dropdown stores names).
---@param name string
---@return Player?
local function playerFromName(name)
	if type(name) ~= "string" or name == "" then
		return nil
	end

	for _, plr in next, Players:GetPlayers() do
		if plr.Name == name then
			return plr
		end
	end

	return nil
end

---The username the panel is currently pointed at, or nil.
---@return string?
local function selectedName()
	local option = Options and Options["AdminTarget"]
	return option and option.Value or nil
end


---@param name string
---@return string
local function targetToken(name)
	local localPlayer = Players.LocalPlayer
	if localPlayer and name == localPlayer.Name then
		return "me"
	end
	return name
end

---Fire a command at whoever's selected, with a friendly notify either way.
---@param cmd string
---@param extra string?
local function runCommand(cmd, extra)
	local name = selectedName()
	if not name then
		return Logger.notify("Admin panel: pick a player first.")
	end

	if Admin.sendCommand(cmd, targetToken(name), extra) then
		Logger.notify("Admin panel: sent '%s' to %s.", cmd, name)
	else
		Logger.notify("Admin panel: failed to send '%s' (no chat channel).", cmd)
	end
end

---Point the spectate camera at the selected player. 
local function spectateSelected()
	local name = selectedName()
	if not name then
		return Logger.notify("Admin panel: pick a player to spectate.")
	end

	local player = playerFromName(name)
	if not player then
		return Logger.notify("Admin panel: '%s' is no longer in the server.", name)
	end

	if player == Players.LocalPlayer then
		Monitoring.subject = nil
		return Logger.notify("Admin panel: that's you -- camera reset.")
	end

	local character = player.Character
	local humanoidRootPart = character and character:FindFirstChild("HumanoidRootPart")
	if not humanoidRootPart then
		return Logger.notify("Admin panel: '%s' isn't loaded in yet.", name)
	end

	Monitoring.subject = humanoidRootPart
	Logger.notify("Admin panel: spectating %s.", name)
end

---Release the spectate camera.
local function stopSpectating()
	Monitoring.subject = nil
	Logger.notify("Admin panel: stopped spectating.")
end

--- Initialize the Admin tab.
---@param window table
function AdminTab.init(window)
	local localPlayer = Players.LocalPlayer
	if not localPlayer then
		return
	end

	-- Whitelist gate: the whole tab only exists for developers.
	if not Admin.isDeveloper(localPlayer.UserId) then
		return
	end

	local tab = window:AddTab("Admin")

	-- ---- Players / spectate ----
	local roster = tab:AddLeftGroupbox("Players")

	
	roster:AddDropdown("AdminTarget", {
		Text = "Target Player",
		SpecialType = "Player",
		AllowNull = true,
		Tooltip = "Every player in the server, yourself included. Drives the admin commands.",
	})

	roster:AddButton({
		Text = "Spectate Selected",
		Func = spectateSelected,
		Tooltip = "Lock your camera onto the selected player.",
	})
	roster:AddButton({
		Text = "Stop Spectating",
		Func = stopSpectating,
	})

	roster:AddButton({
		Text = "Bring To Me",
		Func = function()
			runCommand("bring")
		end,
		Tooltip = "Pull the selected player to your position.",
	})

	-- ---- Commands ----
	local cmds = tab:AddRightGroupbox("Commands")

	cmds:AddButton({
		Text = "Freeze",
		Func = function()
			runCommand("freeze")
		end,
		Tooltip = "Anchor the target in place.",
	})
	cmds:AddButton({
		Text = "Unfreeze",
		Func = function()
			runCommand("unfreeze")
		end,
	})
	cmds:AddButton({
		Text = "Kill",
		DoubleClick = true,
		Tooltip = "Double-click. Sends max fall damage to the target.",
		Func = function()
			runCommand("kill")
		end,
	})
	cmds:AddButton({
		Text = "Kick",
		DoubleClick = true,
		Tooltip = "Double-click. Kicks the target, naming you as the admin.",
		Func = function()
			runCommand("kick")
		end,
	})
	cmds:AddButton({
		Text = "Fake Ban",
		DoubleClick = true,
		Tooltip = "Double-click. Kicks the target with a fake moderation-ban notice.",
		Func = function()
			runCommand("fakeban")
		end,
	})
	cmds:AddButton({
		Text = "Unload Their Mira",
		DoubleClick = true,
		Tooltip = "Double-click. Force-unloads Mira on the target's client.",
		Func = function()
			runCommand("unload")
		end,
	})
	cmds:AddButton({
		Text = "Fake Agamatsu",
		Func = function()
			runCommand("fakeagamatsu")
		end,
		Tooltip = "Fires a counterfeit 'Agamatsu is staff' alert on the target.",
	})

	-- ---- Teleport ----
	local tp = tab:AddRightGroupbox("Teleport")

	tp:AddDropdown("AdminTpDestination", {
		Text = "Destination",
		Values = TP_DESTINATIONS,
		Default = TP_DESTINATIONS[1],
		Tooltip = "Where ;tp sends the selected player.",
	})
	tp:AddButton({
		Text = "Teleport Selected",
		Func = function()
			local option = Options and Options["AdminTpDestination"]
			runCommand("tp", option and option.Value or nil)
		end,
	})

	--Animation flooder/forgeban
	local flood = tab:AddLeftGroupbox("Forge Ban")

	-- Everyone except yourself (flooding your own character is pointless), sorted.
	local function flooderNames()
		local names = {}
		for _, p in ipairs(Players:GetPlayers()) do
			if p ~= Players.LocalPlayer then
				names[#names + 1] = p.Name
			end
		end
		table.sort(names)
		return names
	end

	local flooderInitial = flooderNames()

	local flooderDropdown = flood:AddDropdown("AnimationFlooderTarget", {
		Text = "Target Player",
		Values = flooderInitial,
		Default = flooderInitial[1] or "",
		Multi = false,
		AllowNull = true,
		Tooltip = "Which player to flood animations on.",
		Callback = function(name)
			AnimationFlooder.setTargetByName(name)
		end,
	})

	flood:AddButton({
		Text = "Refresh Player List",
		Func = function()
			pcall(function() flooderDropdown:SetValues(flooderNames()) end)
		end,
	})

	flood:AddSlider("AnimationFlooderIntensity", {
		Text = "Intensity",
		Default = 8,
		Min = 1,
		Max = 50,
		Rounding = 0,
		Tooltip = "Flood animations played per second on the target.",
	})

	local floodToggle = flood:AddToggle("AnimationFlooder", {
		Text = "Flood Player Animations",
		Default = false,
		Tooltip = "Plays every decoy attack animation on the selected player's character.",
	})
	floodToggle:OnChanged(function(state)
		if state then
			AnimationFlooder.startByName(flooderDropdown.Value)
		else
			AnimationFlooder.stop()
		end
	end)
	floodToggle:AddKeyPicker("AnimationFlooderKeybind", { Default = "N/A", SyncToggleState = true, Text = "Flood Player Animations" })

	Players.PlayerAdded:Connect(function()
		pcall(function() flooderDropdown:SetValues(flooderNames()) end)
	end)
	Players.PlayerRemoving:Connect(function()
		pcall(function() flooderDropdown:SetValues(flooderNames()) end)
	end)

	-- ---- Animation Logger 
	local logger = tab:AddLeftGroupbox("Animation Logger")

	logger:AddDivider()

	-- Yourself included, and listed FIRST so it's the default pick -- inspecting your own animations is how you see what your breaker is actually emitting.
	local function inspectNames()
		local names = {}
		local lp = Players.LocalPlayer
		for _, p in ipairs(Players:GetPlayers()) do
			if p ~= lp then
				names[#names + 1] = p.Name
			end
		end
		table.sort(names)
		if lp then
			table.insert(names, 1, lp.Name)
		end
		return names
	end

	local inspectInitial = inspectNames()

	local inspectDropdown = logger:AddDropdown("AnimInspectTarget", {
		Text = "Inspect Player",
		Values = inspectInitial,
		Default = inspectInitial[1] or "",
		Multi = false,
		AllowNull = true,
		Tooltip = "Which player's live animations to show in the inspector window. You're listed first, so leave it as-is to watch your own.",
		Callback = function(name)
			AnimationInspector.setTargetByName(name)
		end,
	})

	logger:AddButton({
		Text = "Refresh Player List",
		Func = function()
			pcall(function() inspectDropdown:SetValues(inspectNames()) end)
		end,
	})

	logger:AddToggle("AnimInspectLogToFile", {
		Text = "Log to File",
		Default = false,
		Tooltip = "While the inspector runs, write the target's animation name/id/priority (and any change to them) to mira_animlog.txt in your executor's workspace folder.",
	})

	local inspectToggle = logger:AddToggle("AnimationInspector", {
		Text = "Animation Inspector",
		Default = false,
		Tooltip = "Opens a live window listing every animation the selected player is currently playing. Rows appear as animations start and are DELETED the moment each one ends.",
	})
	inspectToggle:OnChanged(function(state)
		if state then
			AnimationInspector.startByName(inspectDropdown.Value)
		else
			AnimationInspector.stop()
		end
	end)

	-- Keep the dropdown in sync as players join / leave.
	Players.PlayerAdded:Connect(function()
		pcall(function() inspectDropdown:SetValues(inspectNames()) end)
	end)
	Players.PlayerRemoving:Connect(function()
		pcall(function() inspectDropdown:SetValues(inspectNames()) end)
	end)
end

-- Return AdminTab module.
return AdminTab
end)
__bundle_register("Menu/MiraTab", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
-- MiraTab module.
local MiraTab = {}

---@module GUI.ThemeManager
local ThemeManager = require("GUI/ThemeManager")

---@module GUI.SaveManager
local SaveManager = require("GUI/SaveManager")

---@module GUI.Library
local Library = require("GUI/Library")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---Initialize Cheat Settings section.
---@param groupbox table
-- Marker files live under the shared "Mira" folder like everything else.
local SILENT_MARKER = "Mira/smarker.txt"
local SCANNING_MARKER = "Mira/dpscanning.txt"
local NORPC_MARKER = "Mira/norpc.txt"

-- Make sure the "Mira" folder exists before writing a marker into it.
local function ensureMiraFolder()
	if type(makefolder) == "function" and not (type(isfolder) == "function" and isfolder("Mira")) then
		pcall(makefolder, "Mira")
	end
end

function MiraTab.initCheatSettingsSection(groupbox)
	groupbox:AddButton("Toggle Silent Mode", function()
		if not isfile or not delfile or not writefile then
			return
		end

		shared.Mira.silent = not shared.Mira.silent

		if not shared.Mira.silent then
			Logger.notify("Silent mode was disabled.")
		end

		if isfile(SILENT_MARKER) then
			delfile(SILENT_MARKER)
		else
			ensureMiraFolder()
			writefile(
				SILENT_MARKER,
				"Hello, if you're reading this, that means you have Mira-Rewrite (Deepwoken) silent mode turned on. Deleting this file will turn it off."
			)
		end
	end)

	groupbox:AddButton("Toggle Player Scanning", function()
		if not isfile or not delfile or not writefile then
			return
		end

		shared.Mira.dpscanning = not shared.Mira.dpscanning

		if shared.Mira.dpscanning then
			Logger.notify("Player scanning was disabled.")
		else
			Logger.notify("Player scanning was enabled.")
		end

		if isfile(SCANNING_MARKER) then
			delfile(SCANNING_MARKER)
		else
			ensureMiraFolder()
			writefile(
				SCANNING_MARKER,
				"Hello, if you're reading this, that means you have Mira-Rewrite (Deepwoken) player scanning turned off. Deleting this file will turn it on."
			)
		end
	end)

	groupbox:AddButton("Toggle Bloxstrap RPC", function()
		if not isfile or not delfile or not writefile then
			return
		end

		shared.Mira.norpc = not shared.Mira.norpc

		if not shared.Mira.norpc then
			Logger.notify("Bloxstrap RPC was enabled.")
		else
			Logger.notify("Bloxstrap RPC was disabled.")
		end

		if isfile(NORPC_MARKER) then
			delfile(NORPC_MARKER)
		else
			ensureMiraFolder()
			writefile(
				NORPC_MARKER,
				"Hello, if you're reading this, that means you have Mira-Rewrite (Deepwoken) Bloxstrap RPC turned off. Deleting this file will turn it on."
			)
		end
	end)

	groupbox:AddButton("Unload Cheat", function()
		shared.Mira.detach()
	end)
end

---Initialize UI Settings section.
---@param groupbox table
function MiraTab.initUISettingsSection(groupbox)
	groupbox:AddSlider("NotificationScale", {
		Text = "Notification Scale",
		Min = 50,
		Max = 300,
		Default = 100,
		Rounding = 0,
		Suffix = "%",
	})

	groupbox:AddSlider("QuickNotificationSpeed", {
		Text = "Quick Notification Speed",
		Min = 0.1,
		Max = 2.0,
		Default = 0.5,
		Rounding = 2,
		Suffix = "s",
	})

	local menuBindLabel = groupbox:AddLabel("Menu Bind")

	menuBindLabel:AddKeyPicker("MenuKeybind", { Default = "LeftAlt", NoUI = true, Text = "Menu Keybind" })

	groupbox:AddToggle("KeybindListToggle", {
		Text = "Keybind List",
		Default = false,
		Callback = function(Value)
			pcall(function()
				if Library and Library.KeybindFrame then
					Library.KeybindFrame.Visible = (Value == true)
				end
			end)
		end,
	})

	groupbox:AddToggle("WatermarkToggle", {
		Text = "Watermark",
		Default = false,
		Callback = function(Value)
			pcall(function()
				if Library and Library.Watermark then
					Library.Watermark.Visible = (Value == true)
				end
			end)
		end,
	})


end

---Initialize tab.
function MiraTab.init(window)
	-- Create tab.
	local tab = window:AddTab("Settings") -- dont change the name, it's more confusing if its named that way

	-- Initialize sections.
	MiraTab.initCheatSettingsSection(tab:AddLeftGroupbox("Cheat Settings"))
	MiraTab.initUISettingsSection(tab:AddRightGroupbox("UI Settings"))

	-- Configure SaveManager & ThemeManager.
	ThemeManager:ApplyToTab(tab)
	SaveManager:BuildConfigSection(tab)
end

-- Return MiraTab module.
return MiraTab
end)()

end)
__bundle_register("GUI/SaveManager", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
	local httpService = game:GetService("HttpService")

	---Export UDim2 to a serializable table.
	---@param udim2 UDim2
	---@return table
	local function uDIm2Export(udim2)
		return {
			xScale = udim2.X.Scale,
			xOffset = udim2.X.Offset,
			yScale = udim2.Y.Scale,
			yOffset = udim2.Y.Offset,
		}
	end

	---Import UDim2 from a serializable table.
	---@param serialized table
	---@return UDim2
	local function uDim2Import(serialized)
		return UDim2.new(serialized.xScale, serialized.xOffset, serialized.yScale, serialized.yOffset)
	end

	local SaveManager = {}
	do
		SaveManager.Folder = "Mira/deepwoken-config"
		SaveManager.Ignore = {}
		SaveManager.LoadBatchSize = 99999
		SaveManager.OnLoadComplete = nil
		SaveManager.Parser = {
			Toggle = {
				Save = function(idx, object)
					return { type = "Toggle", idx = idx, value = object.Value }
				end,
				Load = function(idx, data)
					if Toggles[idx] then
						Toggles[idx]:SetValue(data.value)
					end
				end,
			},
			Slider = {
				Save = function(idx, object)
					return { type = "Slider", idx = idx, value = tostring(object.Value) }
				end,
				Load = function(idx, data)
					if Options[idx] then
						Options[idx]:SetValue(data.value)
					end
				end,
			},
			Dropdown = {
				Save = function(idx, object)
					return {
						type = "Dropdown",
						idx = idx,
						value = object.Value,
						values = object.SaveValues and object.Values or nil,
						mutli = object.Multi,
					}
				end,
				Load = function(idx, data)
					if Options[idx] then
						Options[idx]:SetValue(data.value)

						if not data.values then
							return
						end

						Options[idx]:SetValues(data.values)
					end
				end,
			},
			ColorPicker = {
				Save = function(idx, object)
					return {
						type = "ColorPicker",
						idx = idx,
						hue = object.Hue,
						sat = object.Sat,
						vib = object.Vib,
						transparency = object.Transparency,
						rainbow = object.Rainbow,
					}
				end,
				Load = function(idx, data)
					if Options[idx] then
						Options[idx].Rainbow = data.rainbow
						Options[idx]:SetValue({ data.hue, data.sat, data.vib }, data.transparency)
						Options[idx]:Display()
					end
				end,
			},
			KeyPicker = {
				Save = function(idx, object)
					return { type = "KeyPicker", idx = idx, mode = object.Mode, key = object.Value }
				end,
				Load = function(idx, data)
					if Options[idx] then
						Options[idx]:SetValue({ data.key, data.mode })
					end
				end,
			},

			Input = {
				Save = function(idx, object)
					return { type = "Input", idx = idx, text = object.Value }
				end,
				Load = function(idx, data)
					if Options[idx] and type(data.text) == "string" then
						Options[idx]:SetValue(data.text)
					end
				end,
			},
		}

		function SaveManager:SetIgnoreIndexes(list)
			for _, key in next, list do
				self.Ignore[key] = true
			end
		end

		function SaveManager:SetFolder(folder)
			self.Folder = folder
			self:BuildFolderTree()
		end

		function SaveManager:Save(name)
			if not name then
				return false, "no config file is selected"
			end

			local fullPath = self.Folder .. "/" .. name .. ".json"

			local data = {
				objects = {},
				infoLoggerBlacklistHistory = self.Library.InfoLoggerData.KeyBlacklistHistory,
				infoLoggerBlacklist = self.Library.InfoLoggerData.KeyBlacklistList,
				infoLoggerCycle = self.Library.InfoLoggerData.InfoLoggerCycle,
				overrideData = self.Library.OverrideData,
			}

			-- Only save positions for frames that actually exist.
			if self.Library.KeybindFrame then
				data.keybindFramePosition = uDIm2Export(self.Library.KeybindFrame.Position)
			end
			if self.Library.Watermark then
				data.watermarkFramePosition = uDIm2Export(self.Library.Watermark.Position)
			end
			if self.Library.InfoLoggerFrame then
				data.infoLoggerFramePosition = uDIm2Export(self.Library.InfoLoggerFrame.Position)
			end
			if self.Library.AnimationVisualizerFrame then
				data.animationVisualizerFramePosition = uDIm2Export(self.Library.AnimationVisualizerFrame.Position)
			end

			for idx, toggle in next, Toggles do
				if self.Ignore[idx] then
					continue
				end

				table.insert(data.objects, self.Parser[toggle.Type].Save(idx, toggle))
			end

			for idx, option in next, Options do
				if not self.Parser[option.Type] then
					continue
				end
				if self.Ignore[idx] then
					continue
				end

				table.insert(data.objects, self.Parser[option.Type].Save(idx, option))
			end

			local success, encoded = pcall(httpService.JSONEncode, httpService, data)
			if not success then
				return false, "failed to encode data"
			end

			writefile(fullPath, encoded)
			return true
		end

		function SaveManager:Load(name)
			if not name then
				return false, "no config file is selected"
			end

			local file = self.Folder .. "/" .. name .. ".json"
			if not isfile(file) then
				return false, "invalid file"
			end

			local success, decoded = pcall(httpService.JSONDecode, httpService, readfile(file))
			if not success then
				return false, "decode error"
			end

			if decoded.keybindFramePosition and self.Library.KeybindFrame then
				self.Library.KeybindFrame.Position = uDim2Import(decoded.keybindFramePosition)
			end

			if decoded.watermarkFramePosition and self.Library.Watermark then
				self.Library.Watermark.Position = uDim2Import(decoded.watermarkFramePosition)
			end

			if decoded.infoLoggerFramePosition and self.Library.InfoLoggerFrame then
				self.Library.InfoLoggerFrame.Position = uDim2Import(decoded.infoLoggerFramePosition)
			end

			if decoded.infoLoggerBlacklistHistory and self.Library.InfoLoggerData then
				self.Library.InfoLoggerData.KeyBlacklistHistory = decoded.infoLoggerBlacklistHistory
			end

			if decoded.animationVisualizerFramePosition and self.Library.AnimationVisualizerFrame then
				self.Library.AnimationVisualizerFrame.Position = uDim2Import(decoded.animationVisualizerFramePosition)
			end

			local timingList = Options["TimingOverrideList"]

			if decoded.overrideData and timingList then
				self.Library.OverrideData = decoded.overrideData

				local values = {}

				for rname, _ in next, decoded.overrideData do
					values[#values + 1] = rname
				end

				timingList:SetValues(values)
			end

			-- Apply elements in small batches instead of spawning every one on the same frame.
			local pending = {}
			for _, option in next, decoded.objects do
				if self.Parser[option.type] then
					pending[#pending + 1] = option
				end
			end

			task.spawn(function()
				for index, option in ipairs(pending) do
					task.spawn(function()
						self.Parser[option.type].Load(option.idx, option)
					end)

					if index % self.LoadBatchSize == 0 then
						task.wait()
					end
				end

				-- Everything has been dispatched.
				if type(self.OnLoadComplete) == "function" then
					pcall(self.OnLoadComplete)
				end
			end)

			if decoded.infoLoggerBlacklist then
				self.Library.InfoLoggerData.KeyBlacklistList = decoded.infoLoggerBlacklist
				self.Library:RefreshInfoLogger()
				if Options and Options.BlacklistedKeys then
					Options.BlacklistedKeys:SetValues(self.Library:KeyBlacklists())
				end
			end

			if decoded.infoLoggerCycle then
				self.Library.InfoLoggerData.InfoLoggerCycle = decoded.infoLoggerCycle
				self.Library:RefreshInfoLogger()
				if Options and Options.BlacklistedKeys then
					Options.BlacklistedKeys:SetValues(self.Library:KeyBlacklists())
				end
			end

			return true
		end

		function SaveManager:IgnoreThemeSettings()
			self:SetIgnoreIndexes({
				"BackgroundColor",
				"MainColor",
				"AccentColor",
				"OutlineColor",
				"FontColor", -- themes
				"ThemeManager_ThemeList",
				"ThemeManager_CustomThemeList",
				"ThemeManager_CustomThemeName", -- themes
			})
		end

		function SaveManager:BuildFolderTree()
			-- Create each path segment in turn so a nested folder (e.g.
			local built = nil
			for segment in string.gmatch(self.Folder, "[^/\\]+") do
				built = built and (built .. "/" .. segment) or segment
				if not isfolder(built) then
					makefolder(built)
				end
			end
		end

		function SaveManager:RefreshConfigList()
			local list = listfiles(self.Folder)

			local out = {}
			for i = 1, #list do
				local file = list[i]
				if file:sub(-5) == ".json" then
					-- i hate this but it has to be done ...

					local pos = file:find(".json", 1, true)
					local start = pos

					local char = file:sub(pos, pos)
					while char ~= "/" and char ~= "\\" and char ~= "" do
						pos = pos - 1
						char = file:sub(pos, pos)
					end

					if char == "/" or char == "\\" then
						table.insert(out, file:sub(pos + 1, start - 1))
					end
				end
			end

			return out
		end

		function SaveManager:SetLibrary(library)
			self.Library = library
		end

		function SaveManager:LoadAutoloadConfig()
			if isfile(self.Folder .. "/autoload.txt") then
				local name = readfile(self.Folder .. "/autoload.txt")

				local success, err = self:Load(name)
				if not success then
					return self.Library:Notify("Failed to load autoload config: " .. err)
				end

				self.Library:Notify(string.format("Auto loaded config %q", name))
			end
		end

		function SaveManager:BuildConfigSection(tab)
			assert(self.Library, "Must set SaveManager.Library")

			local section = tab:AddRightGroupbox("Config Manager")

			section:AddInput("SaveManager_ConfigName", { Text = "Config name" })
			section:AddDropdown(
				"SaveManager_ConfigList",
				{ Text = "Config list", Values = self:RefreshConfigList(), AllowNull = true }
			)

			section:AddDivider()

			section
				:AddButton("Create config", function()
					local name = Options.SaveManager_ConfigName.Value

					if name:gsub(" ", "") == "" then
						return self.Library:Notify("Invalid config name (empty)", 2)
					end

					local success, err = self:Save(name)
					if not success then
						return self.Library:Notify("Failed to save config: " .. err)
					end

					self.Library:Notify(string.format("Created config %q", name))

					Options.SaveManager_ConfigList:SetValues(self:RefreshConfigList())
					Options.SaveManager_ConfigList:SetValue(nil)
				end)
				:AddButton("Load config", function()
					local name = Options.SaveManager_ConfigList.Value

					local success, err = self:Load(name)
					if not success then
						return self.Library:Notify("Failed to load config: " .. err)
					end

					self.Library:Notify(string.format("Loaded config %q", name))
				end)

			section:AddButton("Overwrite config", function()
				local name = Options.SaveManager_ConfigList.Value

				local success, err = self:Save(name)
				if not success then
					return self.Library:Notify("Failed to overwrite config: " .. err)
				end

				self.Library:Notify(string.format("Overwrote config %q", name))
			end)

			section:AddButton("Refresh list", function()
				Options.SaveManager_ConfigList:SetValues(self:RefreshConfigList())
				Options.SaveManager_ConfigList:SetValue(nil)
			end)

			section:AddButton("Set as autoload", function()
				local name = Options.SaveManager_ConfigList.Value

				-- Guard: with nothing selected this used to writefile(path, nil) and concat a nil into the label, throwing instead of warning.
				if type(name) ~= "string" or name:gsub(" ", "") == "" then
					return self.Library:Notify("No config selected to set as autoload", 2)
				end

				writefile(self.Folder .. "/autoload.txt", name)
				SaveManager.AutoloadLabel:SetText("Current autoload config: " .. name)
				self.Library:Notify(string.format("Set %q to auto load", name))
			end)

			section:AddButton("Clear autoload", function()
				local path = self.Folder .. "/autoload.txt"

				if not isfile(path) then
					return self.Library:Notify("No autoload config is set", 2)
				end

				delfile(path)
				SaveManager.AutoloadLabel:SetText("Current autoload config: none")
				self.Library:Notify("Cleared autoload config")
			end)

			SaveManager.AutoloadLabel = section:AddLabel("Current autoload config: none", true)

			if isfile(self.Folder .. "/autoload.txt") then
				local name = readfile(self.Folder .. "/autoload.txt")
				SaveManager.AutoloadLabel:SetText("Current autoload config: " .. name)
			end

			SaveManager:SetIgnoreIndexes({ "SaveManager_ConfigList", "SaveManager_ConfigName" })
		end

		SaveManager:BuildFolderTree()
	end

	return SaveManager
end)()

end)
