			MainColor = Color3.fromRGB(32, 42, 54),
			BackgroundColor = Color3.fromRGB(22, 30, 40),
			AccentColor = Color3.fromRGB(150, 210, 235),
			OutlineColor = Color3.fromRGB(110, 150, 175),
		},
		Crimson = {
			FontColor = Color3.fromRGB(255, 180, 190),
			MainColor = Color3.fromRGB(34, 22, 24),
			BackgroundColor = Color3.fromRGB(24, 15, 17),
			AccentColor = Color3.fromRGB(220, 40, 60),
			OutlineColor = Color3.fromRGB(150, 40, 55),
		},
		Knight = {
			FontColor = Color3.fromRGB(215, 222, 235),
			MainColor = Color3.fromRGB(38, 40, 46),
			BackgroundColor = Color3.fromRGB(26, 28, 33),
			AccentColor = Color3.fromRGB(150, 170, 200),
			OutlineColor = Color3.fromRGB(100, 115, 140),
		},
		Dracula = {
			FontColor = Color3.fromRGB(248, 248, 242),
			MainColor = Color3.fromRGB(40, 42, 54),
			BackgroundColor = Color3.fromRGB(33, 34, 44),
			AccentColor = Color3.fromRGB(189, 147, 249),
			OutlineColor = Color3.fromRGB(98, 114, 164),
		},
		["Rose Pine"] = {
			FontColor = Color3.fromRGB(224, 222, 244),
			MainColor = Color3.fromRGB(38, 35, 58),
			BackgroundColor = Color3.fromRGB(25, 23, 36),
			AccentColor = Color3.fromRGB(196, 167, 231),
			OutlineColor = Color3.fromRGB(82, 79, 103),
		},
		Nord = {
			FontColor = Color3.fromRGB(236, 239, 244),
			MainColor = Color3.fromRGB(46, 52, 64),
			BackgroundColor = Color3.fromRGB(36, 41, 51),
			AccentColor = Color3.fromRGB(136, 192, 208),
			OutlineColor = Color3.fromRGB(76, 86, 106),
		},
		Catppuccin = {
			FontColor = Color3.fromRGB(205, 214, 244),
			MainColor = Color3.fromRGB(30, 30, 46),
			BackgroundColor = Color3.fromRGB(24, 24, 37),
			AccentColor = Color3.fromRGB(203, 166, 247),
			OutlineColor = Color3.fromRGB(88, 91, 112),
		},
		Sunset = {
			FontColor = Color3.fromRGB(255, 205, 190),
			MainColor = Color3.fromRGB(44, 30, 40),
			BackgroundColor = Color3.fromRGB(32, 22, 30),
			AccentColor = Color3.fromRGB(255, 130, 110),
			OutlineColor = Color3.fromRGB(200, 100, 110),
		},
	}
	ThemeManager.CurrentTheme = "Default"
	ThemeManager.ThemeFolder = "themes"

	function ThemeManager:ApplyTheme(theme)
			local customThemeData = self:GetCustomTheme(theme)
			local data = customThemeData or self.BuiltInThemes[theme]

			if not data then
				return
			end

			-- Handle both old JSON format (data[2]) and new Color3 format
			local themeTable = customThemeData or (data[2] or data)
			
			if not themeTable then
				return
			end

			for idx, themeData in next, themeTable do
				if type(themeData) == "string" then
					self.Library[idx] = Color3.fromHex(themeData)

					if Options[idx] then
						Options[idx]:SetValueRGB(Color3.fromHex(themeData))
					end
				elseif typeof(themeData) == "Color3" then
					-- Handle Color3 values directly from new themes
					self.Library[idx] = themeData
					
					if Options[idx] then
						local h, s, v = themeData:ToHSV()
						Options[idx]:SetValue({ h, s, v }, 0)
					end
				else
					self.Library[idx] = Color3.fromHSV(themeData.hue, themeData.sat, themeData.vib)

					if Options[idx] then
						Options[idx].Rainbow = themeData.rainbow
						Options[idx]:SetValue({ themeData.hue, themeData.sat, themeData.vib }, themeData.transparency)
						Options[idx]:Display()
					end
				end
			end

			self.CurrentTheme = theme
			self:ThemeUpdate()
		end

		function ThemeManager:ThemeUpdate()
			-- This allows us to force apply themes without loading the themes tab :)
			local options = { "FontColor", "MainColor", "AccentColor", "BackgroundColor", "OutlineColor" }
			for i, field in next, options do
				if Options and Options[field] then
					self.Library[field] = Options[field].Value
				end
			end

			self.Library.AccentColorDark = self.Library:GetDarkerColor(self.Library.AccentColor)
			self.Library:UpdateColorsUsingRegistry()
		end

		function ThemeManager:CleanThemeName(name)
			return name and name:gsub("%.json$", "") or name
		end

		function ThemeManager:RefreshThemeList()
			local out = {}

			for name in next, self.BuiltInThemes do
				table.insert(out, name)
			end

			table.sort(out)

			for _, name in next, self:ReloadCustomThemes() do
				table.insert(out, name)
			end

			return out
		end

		function ThemeManager:LoadDefault()
			local theme = "Default"
			local content = isfile(self.Folder .. "/default.txt") and readfile(self.Folder .. "/default.txt")

			local isCustom = false
			if content then
				content = self:CleanThemeName(content)
				if self.BuiltInThemes[content] then
					theme = content
				elseif self:GetCustomTheme(content) then
					theme = content
					isCustom = true
				end
			elseif self.BuiltInThemes[self.DefaultTheme] then
				theme = self.DefaultTheme
			end

			if theme then
				self:ApplyTheme(theme)
				if Options.ThemeManager_ThemeList then
					Options.ThemeManager_ThemeList:SetValue(theme)
				end
			end
		end

		function ThemeManager:SaveDefault(theme)
			if not theme or theme:gsub(" ", "") == "" then
				return self.Library:Notify("Invalid theme name", 3)
			end

			writefile(self.Folder .. "/default.txt", self:CleanThemeName(theme))
		end

		function ThemeManager:CreateThemeManager(groupbox)
			local themeList = groupbox:AddDropdown("ThemeManager_ThemeList", {
				Text = "Theme",
				Values = self:RefreshThemeList(),
				AllowNull = false,
				Default = self.CurrentTheme or "Default",
			})

			themeList:OnChanged(function(value)
				if value and value ~= "" then
					self:ApplyTheme(value)
				end
			end)

			groupbox:AddInput("ThemeManager_CustomThemeName", {
				Text = "Custom theme name",
				Placeholder = "My theme name",
			})

			groupbox:AddButton("Save custom theme", function()
				local name = Options.ThemeManager_CustomThemeName.Value
				if not name or name:gsub("%s", "") == "" then
					return self.Library:Notify("Enter a valid theme name.", 3)
				end

				self:SaveCustomTheme(name)
				themeList:SetValues(self:RefreshThemeList())
				themeList:SetValue(self:CleanThemeName(name))
				themeList:Display()
			end)

			groupbox:AddButton("Save as default", function()
				local name = Options.ThemeManager_ThemeList.Value
				if not name or name:gsub("%s", "") == "" then
					return self.Library:Notify("Select a theme first.", 3)
				end

				self:SaveDefault(name)
				self.Library:Notify("Saved default theme: " .. name)
			end)

			groupbox:AddButton("Reload themes", function()
				themeList:SetValues(self:RefreshThemeList())
				themeList:Display()
			end)

			groupbox:AddDivider()
			groupbox:AddLabel("Surface colour"):AddColorPicker("BackgroundColor", { Default = self.Library.BackgroundColor })
			groupbox:AddLabel("Panel colour"):AddColorPicker("MainColor", { Default = self.Library.MainColor })
			groupbox:AddLabel("Accent colour"):AddColorPicker("AccentColor", { Default = self.Library.AccentColor })
			groupbox:AddLabel("Outline colour"):AddColorPicker("OutlineColor", { Default = self.Library.OutlineColor })
			groupbox:AddLabel("Text colour"):AddColorPicker("FontColor", { Default = self.Library.FontColor })

			local function UpdateTheme()
				self:ThemeUpdate()
			end

			Options.BackgroundColor:OnChanged(UpdateTheme)
			Options.MainColor:OnChanged(UpdateTheme)
			Options.AccentColor:OnChanged(UpdateTheme)
			Options.OutlineColor:OnChanged(UpdateTheme)
			Options.FontColor:OnChanged(UpdateTheme)

			-- UI font selector: changes the whole interface's font live.
			local uiFonts = {
				"GothamMedium", "Gotham", "GothamBold", "SourceSans", "SourceSansBold",
				"Roboto", "RobotoMono", "Code", "Arial", "Legacy",
			}

			groupbox:AddDivider()
			groupbox:AddDropdown("UIFont", {
				Text = "UI Font",
				Values = uiFonts,
				Default = table.find(uiFonts, "GothamMedium") or 1,
				Tooltip = "Changes the font used across the entire interface.",
			})

			Options.UIFont:OnChanged(function()
				local enumFont = Enum.Font[Options.UIFont.Value]
				if not enumFont then
					return
				end

				local oldFont = self.Library.Font
				local newFont = Font.fromEnum(enumFont)
				self.Library.Font = newFont

				-- Re-apply to every existing label that used the old library font (leaves intentionally-custom fonts, e.g.
				local gui = self.Library.ScreenGui
				if gui then
					for _, inst in next, gui:GetDescendants() do
						if
							(inst:IsA("TextLabel") or inst:IsA("TextButton") or inst:IsA("TextBox"))
							and inst.FontFace == oldFont
						then
							inst.FontFace = newFont
						end
					end
				end
			end)

			-- UI Effects now live in their own tabbed subsection editor (built below).
			self:BuildUIEffects(groupbox)
		end

		-- Tabbed "UI Effects" editor.
		function ThemeManager:BuildUIEffects(groupbox)
			local Library = self.Library
			local tab = self.Tab

			local gradientHost, hairlineHost, borderHost, glowHost
			if tab then
				-- Left column so it sits directly under the UI Font control in the Theme Manager groupbox, not over in the Config Manager column.
				local fx = tab:AddLeftTabbox("UI Effects")
				gradientHost = fx:AddTab("Gradient")
				hairlineHost = fx:AddTab("Hairline")
				borderHost = fx:AddTab("Border")
				glowHost = fx:AddTab("Edge Glow")
			else
				groupbox:AddDivider()
				groupbox:AddLabel("UI Effects")
				gradientHost, hairlineHost, borderHost, glowHost = groupbox, groupbox, groupbox, groupbox
			end

			-- ── Gradient ────────────────────────────────────────────────────── Top-lit fill across the WHOLE UI, matching the notifications.
			local uiGradientToggle = gradientHost:AddToggle("UIGradient", {
				Text = "UI Gradient",
				Default = false,
				Tooltip = "Top-lit gradient across the whole UI - window background and panels - matching the notifications.",
			})
			uiGradientToggle:OnChanged(function()
				Library:UpdateUIGradients()
			end)

			gradientHost:AddSlider("GradientStrength", {
				Text = "Gradient Strength",
				Min = 0,
				Max = 100,
				Default = 25,
				Rounding = 0,
				Suffix = "%",
			})
			Options.GradientStrength:OnChanged(function()
				Library:UpdateUIGradients()
			end)

			-- ── Hairline ────────────────────────────────────────────────────── Accent -> transparent line along each panel's bottom edge.
			local accentHairlineToggle = hairlineHost:AddToggle("AccentHairline", {
				Text = "Accent Hairline",
				Default = false,
				Tooltip = "Accent -> transparent gradient line along the bottom edge of every panel.",
			})
			accentHairlineToggle:OnChanged(function()
				Library:UpdatePanelAccents()
			end)

			hairlineHost:AddSlider("AccentHairlineOpacity", {
				Text = "Hairline Opacity",
				Min = 0,
				Max = 100,
				Default = 100,
				Rounding = 0,
				Suffix = "%",
			})
			Options.AccentHairlineOpacity:OnChanged(function()
				Library:UpdatePanelAccents()
			end)

			hairlineHost:AddSlider("AccentHairlineThickness", {
				Text = "Hairline Thickness",
				Min = 1,
				Max = 5,
				Default = 2,
				Rounding = 0,
				Suffix = "px",
			})
			Options.AccentHairlineThickness:OnChanged(function()
				Library:UpdatePanelAccents()
			end)

			-- ── Border ──────────────────────────────────────────────────────── Blends every panel outline from the normal colour toward accent.
			local accentBorderToggle = borderHost:AddToggle("AccentBorder", {
				Text = "Accent Border",
				Default = false,
				Tooltip = "Blend every panel's outline toward the accent colour.",
			})
			accentBorderToggle:OnChanged(function()
				Library:UpdatePanelStrokes()
			end)

			borderHost:AddSlider("AccentBorderAmount", {
				Text = "Border Accent",
				Min = 0,
				Max = 100,
				Default = 50,
				Rounding = 0,
				Suffix = "%",
			})
			Options.AccentBorderAmount:OnChanged(function()
				Library:UpdatePanelStrokes()
			end)

			-- ── Edge Glow ───────────────────────────────────────────────────── (Moved here from the Visuals tab so all UI-look controls live together.)
			local edgeGlowToggle = glowHost:AddToggle("EdgeGlow", {
				Text = "Edge Glow",
				Default = true,
			})

			edgeGlowToggle:AddColorPicker("EdgeGlowColor", {
				Default = Color3.fromRGB(195, 154, 236),
			})

			local egDepBox = glowHost:AddDependencyBox()

			egDepBox:AddToggle("EdgeGlowBreathe", {
				Text = "Breathe",
				Default = false,
			})

			egDepBox:AddSlider("EdgeGlowSize", {
				Text = "Glow Size",
				Min = 0,
				Max = 60,
				Default = 10,
				Rounding = 0,
				Suffix = "px",
			})

			egDepBox:AddSlider("EdgeGlowOpacity", {
				Text = "Glow Opacity",
				Min = 0,
				Max = 100,
				Default = 100,
				Rounding = 0,
				Suffix = "%",
			})

			egDepBox:SetupDependencies({
				{ Toggles.EdgeGlow, true },
			})
		end

		function ThemeManager:GetCustomTheme(file)
			local checkedName = self:CleanThemeName(file)
			local path = self.Folder .. "/" .. checkedName .. ".json"
			if not isfile(path) then
				return nil
			end

			local data = readfile(path)
			local success, decoded = pcall(httpService.JSONDecode, httpService, data)

			if not success then
				return nil
			end

			return decoded
		end

		function ThemeManager:SaveCustomTheme(file)
			if file:gsub(" ", "") == "" then
				return self.Library:Notify("Invalid file name for theme (empty)", 3)
			end

			local theme = {}
			local fields = { "FontColor", "MainColor", "AccentColor", "BackgroundColor", "OutlineColor" }

			for _, field in next, fields do
				local option = Options[field]

				theme[field] = {
					type = "ColorPicker",
					hue = option.Hue,
					sat = option.Sat,
					vib = option.Vib,
					transparency = option.Transparency,
					rainbow = option.Rainbow,
				}
			end

			writefile(self.Folder .. "/" .. file .. ".json", httpService:JSONEncode(theme))
		end

		function ThemeManager:ReloadCustomThemes()
			local list = listfiles(self.Folder)

			local out = {}
			for i = 1, #list do
				local file = list[i]
				if file:sub(-5) == ".json" then
					local pos = file:find(".json", 1, true)
					local char = file:sub(pos, pos)

					while char ~= "/" and char ~= "\\" and char ~= "" do
						pos = pos - 1
						char = file:sub(pos, pos)
					end

					if char == "/" or char == "\\" then
						table.insert(out, self:CleanThemeName(file:sub(pos + 1)))
					end
				end
			end

			return out
		end

		function ThemeManager:SetLibrary(lib)
			self.Library = lib
		end

		function ThemeManager:BuildFolderTree()
			-- Build parent-first so a nested folder like "Mira/themes" is created even on executors whose makefolder won't make missing parents.
			local built = nil
			for segment in string.gmatch(self.Folder, "[^/\\]+") do
				built = built and (built .. "/" .. segment) or segment
				if not isfolder(built) then
					makefolder(built)
				end
			end
		end

		function ThemeManager:SetFolder(folder)
			self.Folder = folder
			self:BuildFolderTree()
		end

		function ThemeManager:CreateGroupBox(tab)
			assert(self.Library, "Must set ThemeManager.Library first!")
			return tab:AddLeftGroupbox("Theme Manager")
		end

		function ThemeManager:ApplyToTab(tab)
			assert(self.Library, "Must set ThemeManager.Library first!")
			-- Stash the host tab so the UI Effects subsection editor can hang a tabbox off it (tabboxes are a Tab-level element, not a groupbox one).
			self.Tab = tab
			local groupbox = self:CreateGroupBox(tab)
			self:CreateThemeManager(groupbox)
		end

		function ThemeManager:ApplyToGroupbox(groupbox)
			assert(self.Library, "Must set ThemeManager.Library first!")
			self:CreateThemeManager(groupbox)
		end

		ThemeManager:BuildFolderTree()
	end

	return ThemeManager
end)()
end)
__bundle_register("Menu/ExploitTab", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
-- ExploitTab module.
local ExploitTab = {}

---@module Features.Game.Teleport
local Teleport = require("Features/Game/Teleport")

---Initialize Mob Exploits section.
---@param groupbox table
function ExploitTab.initMobExploitsSection(groupbox)
	local voidMobsToggle = groupbox:AddToggle("VoidMobs", {
		Text = "Void Mobs",
		Tooltip = "Teleport nearby mobs and send them to the void.",
		Default = false,
	})

	voidMobsToggle:AddKeyPicker("VoidMobsKeyBind", { Default = "N/A", SyncToggleState = true, Text = "Void Mobs" })
end

---Initialize Local Character Exploits section.
---@param groupbox table
function ExploitTab.initLocalCharacterExploitsSection(groupbox)
	local moveWhileKnockedToggle = groupbox:AddToggle("MoveWhileKnocked", {
		Text = "Move While Knocked",
		Tooltip = "Move your character while in a knocked down state.",
		Default = false,
	})

	moveWhileKnockedToggle:AddKeyPicker(
		"MoveWhileKnockedKeyBind",
		{ Default = "N/A", SyncToggleState = true, Text = "Move While Knocked", HideIfUnbound = true }
	)

	local pathfindBreakerToggle = groupbox:AddToggle("PathfindBreaker", {
		Text = "Pathfind Breaker",
		Tooltip = "Visibly break the pathfinding for humanoid mobs by attempting to spoof your vertical velocity.",
		Default = false,
	})

	pathfindBreakerToggle:AddKeyPicker(
		"PathfindBreakerKeyBind",
		{ Default = "N/A", SyncToggleState = true, Text = "Pathfind Breaker", HideIfUnbound = true }
	)

	local pbDepBox = groupbox:AddDependencyBox()

	pbDepBox:AddToggle("AggressiveMode", {
		Text = "Aggressive Mode",
		Tooltip = "Enable this to make the pathfinding breaker more aggressive by luring mobs towards you.",
		Default = false,
	})

	local pbHighlightToggle = pbDepBox:AddToggle("PathfindBreakerHighlight", {
		Text = "Show Highlight",
		Tooltip = "Because this feature can be very visible, you can enable a visual highlight to see if it is on.",
		Default = false,
	})

	pbHighlightToggle:AddColorPicker("PathfindBreakerHighlightColor", {
		Default = Color3.fromRGB(255, 105, 180),
		Text = "Highlight Color",
	})

	pbHighlightToggle:AddColorPicker("PathfindBreakerHighlightOutlineColor", {
		Default = Color3.fromRGB(255, 182, 193),
		Text = "Outline Color",
	})

	pbDepBox:SetupDependencies({
		{ pathfindBreakerToggle, true },
	})
end

---Add teleport button with disclaimer.
---@param groupbox table
---@param text string
---@param dest string
local function addTeleportButton(groupbox, text, dest)
	groupbox:AddButton({
		Text = text,
		Tooltip = "All teleports can bug out and cause death. They also may be very visible to other players.",
		DoubleClick = true,
		DoubleClickText = "Use at your own risk?",
		Func = function()
			Teleport.start(dest)
		end,
	})
end

---Initialize Teleports section.
---@param groupbox table
function ExploitTab.initTeleportsSection(groupbox)
	if game.PlaceId == 6032399813 then
		addTeleportButton(groupbox, "Teleport to Eastern Luminant", "EasternLuminant")
		addTeleportButton(groupbox, "Teleport to Trial Of One", "TrialOfOne")
	end

	if game.PlaceId == 6473861193 then
		addTeleportButton(groupbox, "Teleport to Etrean Luminant", "EtreanLuminant")
	end

	addTeleportButton(groupbox, "Teleport to Depths", "Depths")
	addTeleportButton(groupbox, "Teleport to Voidheart", "Voidheart")

	groupbox:AddButton("Stop Teleporting", Teleport.stop)
	groupbox:AddDivider()
	groupbox:AddInput("GuildDoorName", {
		Text = "Guild Door Name",
		Placeholder = "Exact or partial name of door.",
	})

	groupbox:AddButton({
		Text = "Teleport To Guild Door",
		Func = function()
			local guildDoorName = Options["GuildDoorName"]
			local name = guildDoorName and guildDoorName.Value or ""
			if name == "" then
				return Logger.notify("Please enter a guild door name.")
			end
			Teleport.start("GuildDoor")
		end,
	})
end

---Initialize tab.
---@param window table
function ExploitTab.init(window)
	-- Create tab.
	local tab = window:AddTab("Exploit")

	-- Fetch realm information.
	local replicatedStorage = game:GetService("ReplicatedStorage")
	local info = replicatedStorage:WaitForChild("Info")
	local realmInfo = info:WaitForChild("RealmInfo")
	local realmInfoModule = require(realmInfo)
	local currentWorld = realmInfoModule.CurrentWorld or "N/A"

	-- Initialize sections.
	local mobGroup = tab:AddLeftGroupbox("Mob Exploits")
	ExploitTab.initMobExploitsSection(mobGroup)

	local characterGroup = tab:AddLeftGroupbox("Character")
	ExploitTab.initLocalCharacterExploitsSection(characterGroup)

	-- Hair Id Stealer 
	local teleportGroup = tab:AddRightGroupbox("Teleports")
	ExploitTab.initTeleportsSection(teleportGroup)
end

-- Return ExploitTab module.
return ExploitTab
end)()

end)
__bundle_register("Menu/VisualsTab", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@module Features.Visuals.Visuals
local Visuals = require("Features/Visuals/Visuals")

---@module Utility.JSON
local JSON = require("Utility/JSON")

---@module Features.Visuals.Objects.BuilderData
local BuilderData = require("Features/Visuals/Objects/BuilderData")

-- Visuals tab.
local VisualsTab = {}

---Initialize ESP Customization section.
---@param groupbox table
function VisualsTab.initESPCustomization(groupbox)
	groupbox:AddSlider("FontSize", {
		Text = "ESP Font Size",
		Default = 14,
		Min = 4,
		Max = 24,
		Rounding = 0,
	})

	groupbox:AddSlider("ESPSplitLineLength", {
		Text = "ESP Split Line Length",
		Tooltip = "The total length of a ESP label line before it splits into a new line.",
		Default = 30,
		Min = 10,
		Max = 100,
		Rounding = 0,
	})

	local fonts = {}

	for _, font in next, Enum.Font:GetEnumItems() do
