---Add Filtered ESP section.
---@param identifier string
---@param depbox table
---@return string, table
function VisualsTab.addFilterESP(identifier, depbox)
	depbox:AddDivider()

	local filterObjectsToggle = depbox:AddToggle(Configuration.identify(identifier, "FilterObjects"), {
		Text = "Filter Objects",
		Default = false,
	})

	local foDepBox = depbox:AddDependencyBox()

	local filterLabelList = foDepBox:AddDropdown(Configuration.identify(identifier, "FilterLabelList"), {
		Text = "Filter Label List",
		Default = {},
		SaveValues = true,
		Multi = true,
		Values = {},
	})

	local filterLabel = foDepBox:AddInput(Configuration.identify(identifier, "FilterLabel"), {
		Text = "Filter Label",
		Placeholder = "Partial or exact object label.",
	})

	foDepBox:AddDropdown(Configuration.identify(identifier, "FilterLabelListType"), {
		Text = "Filter List Type",
		Default = 1,
		Values = { "Hide Labels Out Of List", "Hide Labels In List" },
	})

	foDepBox:AddButton("Add Name To Filter", function()
		local filterLabelValue = filterLabel.Value

		if #filterLabelValue <= 0 then
			return Logger.notify("Please enter a valid filter name.")
		end

		local filterLabelListValues = filterLabelList.Values

		if not table.find(filterLabelListValues, filterLabelValue) then
			table.insert(filterLabelListValues, filterLabelValue)
		end

		filterLabelList:SetValues(filterLabelListValues)
		filterLabelList:SetValue({})
		filterLabelList:Display()
	end)

	foDepBox:AddButton("Remove Selected Names", function()
		local filterLabelListValues = filterLabelList.Values
		local selectedFilterNames = filterLabelList.Value

		for selectedFilterName, _ in next, selectedFilterNames do
			local selectedIndex = table.find(filterLabelListValues, selectedFilterName)
			if not selectedIndex then
				return Logger.notify("The selected filter name %s does not exist in the list", selectedFilterName)
			end

			table.remove(filterLabelListValues, selectedIndex)
		end

		filterLabelList:SetValues(filterLabelListValues)
		filterLabelList:SetValue({})
		filterLabelList:Display()
	end)

	foDepBox:SetupDependencies({
		{ filterObjectsToggle, true },
	})

	return identifier, depbox
end

---Initialize ESP categories tab.
---@param tab table
--- Build one ESP category inside a shared container (a tabbox sub-tab).
---@param container table The sub-tab to add into.
---@param identifier string ESP config identifier (unchanged, so saved configs carry over).
---@param title string Display name shown on the Enable toggle.
---@param decorate function|nil Optional extra builder, called with (id, depbox).
function VisualsTab.buildESPCategory(container, identifier, title, decorate)
	container:AddDivider()

	local id, depbox = VisualsTab.initBaseESPSection(identifier, container, title)

	if decorate then
		decorate(id, depbox)
	end
end

--- Initialize ESP categories as collapsible subsections.
---@param tab table
function VisualsTab.initESPCategoriesTab(tab)
	local espTabbox = tab:AddLeftTabbox("ESP Categories")

	-- PLAYERS
	local players = espTabbox:AddTab("Players")
	VisualsTab.buildESPCategory(players, "Player", "Player ESP", function(id, depbox)
		VisualsTab.addPlayerESP(VisualsTab.addEntityESP(id, depbox))
	end)

	-- MOBS
	local mobs = espTabbox:AddTab("Mobs")
	VisualsTab.buildESPCategory(mobs, "Mob", "Mob ESP", function(id, depbox)
		VisualsTab.addFilterESP(VisualsTab.addEntityESP(id, depbox))
	end)
	VisualsTab.buildESPCategory(mobs, "NPC", "NPC ESP")

	-- OBJECTS (items, drops, pickups)
	local objects = espTabbox:AddTab("Objects")
	VisualsTab.buildESPCategory(objects, "Chest", "Chest ESP", function(id, depbox)
		VisualsTab.addChestESP(id, depbox)
	end)
	VisualsTab.buildESPCategory(objects, "BagDrop", "Bag ESP")
	VisualsTab.buildESPCategory(objects, "Ingredient", "Ingredient ESP", function(id, depbox)
		VisualsTab.addFilterESP(id, depbox)
	end)
	VisualsTab.buildESPCategory(objects, "BoneSpear", "Bone Spear ESP")
	VisualsTab.buildESPCategory(objects, "ArmorBrick", "Armor Brick ESP")
	VisualsTab.buildESPCategory(objects, "HealBrick", "Heal Brick ESP")
	VisualsTab.buildESPCategory(objects, "BellMeteor", "Bell Meteor ESP")
	VisualsTab.buildESPCategory(objects, "BellKey", "Bell Key ESP")
	VisualsTab.buildESPCategory(objects, "OwlFeathers", "Owl Feathers ESP")
	VisualsTab.buildESPCategory(objects, "WindrunnerOrb", "Windrunner Orb ESP")
	VisualsTab.buildESPCategory(objects, "ExplosiveBarrel", "Explosive Barrel ESP")
	VisualsTab.buildESPCategory(objects, "Artifact", "Artifact ESP")
	VisualsTab.buildESPCategory(objects, "BRWeapon", "BR Weapon ESP")
	VisualsTab.buildESPCategory(objects, "VOIWeaponESP", "VOI Weapon ESP")
	VisualsTab.buildESPCategory(objects, "MinistryCacheIndicator", "Ministry Cache ESP")

	-- LOCATIONS (world structures, obelisks, areas)
	local locations = espTabbox:AddTab("Locations")
	VisualsTab.buildESPCategory(locations, "AreaMarker", "Area Marker ESP", function(id, depbox)
		VisualsTab.addFilterESP(id, depbox)
	end)
	VisualsTab.buildESPCategory(locations, "Obelisk", "Obelisk ESP", function(id, depbox)
		VisualsTab.addObeliskESP(id, depbox)
	end)
	VisualsTab.buildESPCategory(locations, "RareObelisk", "Rare Obelisk ESP")
	VisualsTab.buildESPCategory(locations, "MantraObelisk", "Mantra Obelisk ESP")
	VisualsTab.buildESPCategory(locations, "BoneAltar", "Bone Altar ESP", function(id, depbox)
		VisualsTab.addBoneAltarESP(id, depbox)
	end)
	VisualsTab.buildESPCategory(locations, "Whirlpool", "Whirlpool ESP")
	VisualsTab.buildESPCategory(locations, "ShopESP", "Shop ESP")
	VisualsTab.buildESPCategory(locations, "JobBoard", "Job Board ESP")
	VisualsTab.buildESPCategory(locations, "GuildDoor", "Guild Door ESP")
	VisualsTab.buildESPCategory(locations, "GuildBanner", "Guild Banner ESP")
	VisualsTab.buildESPCategory(locations, "VOIBoundaryESP", "VOI Boundary ESP")
end

---Initialize tab.
---@param window table
function VisualsTab.init(window)
	-- Create tab.
	local tab = window:AddTab("Visuals")

	-- General settings.
	VisualsTab.initESPCustomization(tab:AddLeftGroupbox("ESP Customization"))
	VisualsTab.initESPOptimizations(tab:AddRightGroupbox("ESP Optimizations"))
	VisualsTab.initWorldVisualsSection(tab:AddLeftGroupbox("World Visuals"))

	-- Leaderboard cosmetics (custom addition) — above the ESP categories.
	VisualsTab.initLeaderboardSection(tab:AddLeftGroupbox("Leaderboard"))

	-- ESP categories.
	VisualsTab.initESPCategoriesTab(tab)

	-- Assistance and cleanup.
	VisualsTab.initVisualAssistanceSection(tab:AddRightGroupbox("Visual Assistance"))

	-- Combat reveals.
	VisualsTab.initCombatRevealsSection(tab:AddRightGroupbox("Combat Reveals"))

	-- Morph loader (custom addition).
	VisualsTab.initMorphLoaderSection(tab:AddLeftGroupbox("Morphs"))

	-- Streamproof external ESP (custom addition).
	VisualsTab.initExternalESPSection(tab:AddRightGroupbox("Streamproof ESP"))
end

--- Initialize the Leaderboard cosmetics section.
---@param groupbox table
function VisualsTab.initLeaderboardSection(groupbox)
	local larpseekerToggle = groupbox:AddToggle("Larpseeker", {
		Text = "Larpseeker",
		Tooltip = "makes ur leaderboard colour the godseeker colour for larping",
		Default = false,
	})

	-- The Chime lobby early-returns before the menu ever loads, so it can't read this toggle directly.
	larpseekerToggle:OnChanged(function(value)
		task.spawn(function()
			if type(makefolder) == "function"
				and not (type(isfolder) == "function" and isfolder("Mira")) then
				pcall(makefolder, "Mira")
			end

			if value then
				if type(writefile) == "function" then
					pcall(writefile, "Mira/larpseeker.txt", "1")
				end
			elseif type(delfile) == "function" and type(isfile) == "function" and isfile("Mira/larpseeker.txt") then
				pcall(delfile, "Mira/larpseeker.txt")
			end
		end)
	end)
end

--- Initialize the streamproof external ESP section.
---@param groupbox table
function VisualsTab.initExternalESPSection(groupbox)
	---@module Features.Visuals.ExternalESP
	local ExternalESP = require("Features/Visuals/ExternalESP")

	local espToggle = groupbox:AddToggle("ExternalESP", {
		Text = "Streamproof ESP",
		Tooltip = "uses python to draw esp this requires setup",
		Default = false,
	})

	espToggle:OnChanged(function(value)
		if not value then
			ExternalESP.disable()
			return
		end

		-- Text box, so Value is a STRING -- coerce, and fall back if it's blank/garbage.
		local port = tonumber(Options.ExternalESPPort and Options.ExternalESPPort.Value) or 7813
		local ok = ExternalESP.enable(port)
		if not ok then
			-- enable() already notified why (no websocket / overlay not running).
			espToggle:SetValue(false)
		end
	end)

	-- Auto-connect on load: if the toggle was saved ON in the config, connect to a running overlay automatically instead of making the user flip it each session.
	task.spawn(function()
		-- Give the config autoload a moment to restore toggle values first.
		task.wait(3)

		if not (Toggles.ExternalESP and Toggles.ExternalESP.Value) then
			return
		end

		if ExternalESP.isConnected() then
			return
		end

		-- Text box, so Value is a STRING -- coerce, and fall back if it's blank/garbage.
		local port = tonumber(Options.ExternalESPPort and Options.ExternalESPPort.Value) or 7813
		ExternalESP.enable(port)
	end)
end

--- Morph loader Models live under the executor workspace at mira_morphs/Races and mira_morphs/Ornaments.
---@param groupbox table
function VisualsTab.initMorphLoaderSection(groupbox)
	local Players = game:GetService("Players")
	local lp = Players.LocalPlayer

	-- Executor file API resolution (Synapse Z / generic).
	local readCustomAsset = getcustomasset or getsynasset or (syn and syn.get_custom_asset)
	local listFiles = listfiles

	local FOLDERS = {
		Races = "Mira/mira_morphs/Races",
		Ornaments = "Mira/mira_morphs/Ornaments",
	}

	-- Create the morph folders on first execution, the same way the config / theme folders get made.
	do
		local function ensureFolder(path)
			if type(makefolder) ~= "function" then
				return
			end
			if type(isfolder) == "function" and isfolder(path) then
				return
			end
			pcall(makefolder, path)
		end
		ensureFolder("Mira")
		ensureFolder("Mira/mira_morphs")
		ensureFolder(FOLDERS.Races)
		ensureFolder(FOLDERS.Ornaments)
	end

	local HOLDER_NAME = "MiraMorph_Applied"
	local BACKUP_NAME = "MiraMorph_Backup"
	-- Per-morph baked forward nudge (studs, along facing).
	local MORPH_FORWARD = {
	}
	-- Morphs that ship a HideBody flag but look better worn OVER the body.
	local MORPH_NOHIDE = {
	}
	-- For hide-body morphs with gaps, keep these character limbs visible to plug the holes. morphName -> { limbName = true }.
	local MORPH_KEEP_VISIBLE = {
	}

	local currentCategory = "Races"
	local currentFile = nil
	local lastApplied = nil -- { category = , file = }
	local hideBodyEnabled = true
	local reapplyEnabled = false
	local hideToggle -- forward declared; assigned in UI section below
	local RunService = game:GetService("RunService")
	local hideConn = nil
	local hiddenList = {}

	local function listMorphs(dir)
		if type(listFiles) ~= "function" then return {} end
		local ok, res = pcall(listFiles, dir)
		if not ok or type(res) ~= "table" then return {} end
		local out = {}
		for _, p in ipairs(res) do
			local path = tostring(p):gsub("\\", "/")
			if path:sub(-5):lower() == ".rbxm" then
				local name = path:match("([^/]+)%.rbxm$")
				if name then table.insert(out, name) end
			end
		end
		table.sort(out)
		return out
	end

	local function getChar()
		local c = lp.Character
		if not c then return nil end
		if not c:FindFirstChild("HumanoidRootPart") then
			c:WaitForChild("HumanoidRootPart", 5)
		end
		return c
	end

	-- Stop enforcing invisibility and restore everything we hid.
	local function stopHide()
		if hideConn then hideConn:Disconnect(); hideConn = nil end
		for _, p in ipairs(hiddenList) do
			if p and p.Parent then
				pcall(function()
					if p:IsA("BasePart") then
						p.LocalTransparencyModifier = 0
					end
					if p:GetAttribute("MiraMorphHidden") ~= nil then
						p.Transparency = p:GetAttribute("MiraMorphHidden")
						p:SetAttribute("MiraMorphHidden", nil)
					end
				end)
			end
		end
		hiddenList = {}
	end

	-- Keep the given parts/decals invisible every frame (Deepwoken re-shows them otherwise).
	local function startHide(parts)
		stopHide()
		hiddenList = parts
		hideConn = RunService.RenderStepped:Connect(function()
			for _, p in ipairs(hiddenList) do
				if p and p.Parent then
					if p:IsA("BasePart") then
						p.LocalTransparencyModifier = 1
					else
						p.Transparency = 1
					end
				end
			end
		end)
	end

	local function clearMorphs()
		stopHide()
		local c = lp.Character
		if not c then return end
		-- Remove morph clothing clones we added.
		for _, p in ipairs(c:GetChildren()) do
			if p:GetAttribute("MiraMorphClothing") then p:Destroy() end
		end
		-- Restore any original clothing we backed up.
		local backup = c:FindFirstChild(BACKUP_NAME)
		if backup then
			for _, p in ipairs(backup:GetChildren()) do p.Parent = c end
			backup:Destroy()
		end
		local h = c:FindFirstChild(HOLDER_NAME)
		if h then h:Destroy() end
		-- Restore / remove any face decals we changed.
		for _, p in ipairs(c:GetDescendants()) do
			if p:GetAttribute("MiraMorphFaceClone") then
				p:Destroy()
			elseif p:GetAttribute("MiraMorphFace") ~= nil then
				pcall(function() p.Texture = p:GetAttribute("MiraMorphFace") end)
				p:SetAttribute("MiraMorphFace", nil)
			end
		end
		-- Safety sweep for any leftover hidden decals from a prior run.
		for _, p in ipairs(c:GetDescendants()) do
			if p:GetAttribute("MiraMorphHidden") ~= nil then
				pcall(function() p.Transparency = p:GetAttribute("MiraMorphHidden") end)
				p:SetAttribute("MiraMorphHidden", nil)
			end
		end
		-- Restore any real body limbs we recolored to a morph's skin tone.
		for _, p in ipairs(c:GetDescendants()) do
			if p:GetAttribute("MiraMorphSkin") ~= nil then
				pcall(function() p.Color = p:GetAttribute("MiraMorphSkin") end)
				p:SetAttribute("MiraMorphSkin", nil)
			end
		end
	end

	-- Character limb parts (R15 first, R6 fallback) we can bind morph pieces to.
	local LIMB_NAMES = {
		"Head", "UpperTorso", "LowerTorso",
		"LeftUpperArm", "LeftLowerArm", "LeftHand",
		"RightUpperArm", "RightLowerArm", "RightHand",
		"LeftUpperLeg", "LeftLowerLeg", "LeftFoot",
		"RightUpperLeg", "RightLowerLeg", "RightFoot",
		"Torso", "Left Arm", "Right Arm", "Left Leg", "Right Leg",
	}
	-- Names a morph tends to use for its torso/root anchor.
	local ANCHOR_NAMES = {
		"HumanoidRootPart", "UpperTorso", "Torso", "LowerTorso",
		"tt", "t", "lt", "Chestplate", "Body", "Root", "Middle",
	}

	local function collectLimbs(char)
		local limbs = {}
		for _, name in ipairs(LIMB_NAMES) do
			local p = char:FindFirstChild(name)
			if p and p:IsA("BasePart") then limbs[#limbs + 1] = p end
		end
		return limbs
	end

	local function findCharAnchor(char)
		return char:FindFirstChild("UpperTorso")
			or char:FindFirstChild("Torso")
			or char:FindFirstChild("LowerTorso")
			or char:FindFirstChild("HumanoidRootPart")
	end

	local function findMorphAnchor(model)
		for _, an in ipairs(ANCHOR_NAMES) do
			local p = model:FindFirstChild(an, true)
			if p and p:IsA("BasePart") then return p end
		end
		return model.PrimaryPart or model:FindFirstChildWhichIsA("BasePart", true)
	end

	local function nearestLimb(limbs, pos)
		local best, bestDist
		for _, l in ipairs(limbs) do
			local d = (l.Position - pos).Magnitude
			if not bestDist or d < bestDist then bestDist, best = d, l end
		end
		return best
	end

	-- Map a keyword in a morph part's name to a character limb, so morphs that bind by naming convention land on the intended limb instead of relying on raw nearest-position guessing.
	local LIMB_HINTS = {
		{ "uppertorso", { "UpperTorso" } },
		{ "lowertorso", { "LowerTorso" } },
		{ "torso", { "UpperTorso", "Torso", "LowerTorso" } },
		{ "chest", { "UpperTorso", "Torso" } },
		{ "head", { "Head" } }, { "face", { "Head" } }, { "hair", { "Head" } },
		{ "hat", { "Head" } }, { "horn", { "Head" } }, { "mask", { "Head" } }, { "helm", { "Head" } },
		-- Head/hair overlay meshes (ippo's "Shading") are head pieces; without a hint they'd fall to the torso and render on the chest.
		{ "shading", { "Head" } }, { "shade", { "Head" } },
		{ "lefthand", { "LeftHand", "Left Arm" } }, { "righthand", { "RightHand", "Right Arm" } },
		{ "leftlowerarm", { "LeftLowerArm", "Left Arm" } }, { "rightlowerarm", { "RightLowerArm", "Right Arm" } },
		{ "leftupperarm", { "LeftUpperArm", "Left Arm" } }, { "rightupperarm", { "RightUpperArm", "Right Arm" } },
		{ "leftarm", { "LeftUpperArm", "Left Arm" } }, { "rightarm", { "RightUpperArm", "Right Arm" } },
		{ "leftfoot", { "LeftFoot", "Left Leg" } }, { "rightfoot", { "RightFoot", "Right Leg" } },
		{ "leftlowerleg", { "LeftLowerLeg", "Left Leg" } }, { "rightlowerleg", { "RightLowerLeg", "Right Leg" } },
		{ "leftupperleg", { "LeftUpperLeg", "Left Leg" } }, { "rightupperleg", { "RightUpperLeg", "Right Leg" } },
		{ "leftleg", { "LeftUpperLeg", "Left Leg" } }, { "rightleg", { "RightUpperLeg", "Right Leg" } },
		{ "arm", { "UpperTorso", "Torso" } }, -- generic "arms equipment" binds to the torso anchor
	}
	local function limbFromName(char, name)
		local n = tostring(name):lower():gsub("[^%w]", "")
		for _, pair in ipairs(LIMB_HINTS) do
			if n:find(pair[1], 1, true) then
				for _, cand in ipairs(pair[2]) do
					local limb = char:FindFirstChild(cand)
					if limb and limb:IsA("BasePart") then
						return limb
					end
				end
			end
		end
		return nil
	end

	-- The attachment a morph part welds by.
	local function bindingAttachment(part)
		local a = part:FindFirstChild("Offset") or part:FindFirstChild("JointOffset")
			or part:FindFirstChild("Attach")
		if a and a:IsA("Attachment") then
			return a
		end
		return nil
	end

	-- Per-morph, per-part vertical lift (studs) for pieces a morph anchors too low.
	local MORPH_PART_LIFT = {
		FifthGear = { ArmsEquipment_Torso = 1.3 },
	}
	local function partLift(morphName, partName)
		local base = tostring(morphName):gsub("%s*%(%d+%)%s*$", "")
		local t = MORPH_PART_LIFT[base]
		return (t and t[partName]) or 0
	end

	-- Per-morph skin tone.
	local MORPH_SKIN = {
		FifthGear = Color3.fromRGB(226, 178, 132), -- Gear 5 golden tan
	}
	-- Real body limbs to recolor (R6 + R15 names; whichever the character actually has).
	local SKIN_LIMBS = {
		"Torso", "Left Arm", "Right Arm", "Left Leg", "Right Leg",
		"UpperTorso", "LowerTorso",
		"LeftUpperArm", "LeftLowerArm", "LeftHand",
		"RightUpperArm", "RightLowerArm", "RightHand",
		"LeftUpperLeg", "LeftLowerLeg", "LeftFoot",
		"RightUpperLeg", "RightLowerLeg", "RightFoot",
	}

	-- Full R15 limb names.
	local R15_LIMB_SET = {
		Head = true, UpperTorso = true, LowerTorso = true,
		LeftUpperArm = true, LeftLowerArm = true, LeftHand = true,
		RightUpperArm = true, RightLowerArm = true, RightHand = true,
		LeftUpperLeg = true, LeftLowerLeg = true, LeftFoot = true,
		RightUpperLeg = true, RightLowerLeg = true, RightFoot = true,
	}

	-- ---- Per-morph overrides (keyed by base file name, trailing " (n)" copy-suffix ignored) ----
	local function morphBase(name) return tostring(name):gsub("%s*%(%d+%)%s*$", "") end
	-- Morphs whose "head" is a stiff extension of the body: weld the head region to the TORSO, not the neck, so it can't swing away from the body when a weapon draw / emote animation tilts the head.
	local MORPH_RIGID_HEAD = { TungTung = true }
	-- Redundant / overlapping pieces to drop outright.
	local MORPH_HIDE_PARTS = {
		Mudskipper = { MudskipperHatA = true },
	}
	-- Force a named morph part onto a named character limb, overriding the name-guessing.
	local MORPH_PART_LIMB = {}
	-- Corrective vertical lift (studs) for DRIVEN sub-parts that sit too low -- their joint offset drops them onto the chest.
	local MORPH_SUBPART_LIFT = { ippo = { MeshPart = 1.5 } }

	local function applyModel(model, hideBody, morphName)
		local char = getChar()
		if not char then return false, "no character" end
		if not char:FindFirstChild("HumanoidRootPart") then return false, "no HumanoidRootPart" end

		local limbs = collectLimbs(char)
		if #limbs == 0 then return false, "no limbs on character" end

		local extraHide = {} -- specific parts (e.g. real hair) to hide even when not hiding the whole body
		local morphHasHair = false -- set true if the morph supplies its own hair

		local base = morphBase(morphName)

		-- NOTE: do NOT strip the morph's LocalScripts -- on these Deepwoken race morphs they apply the skin/hair/eye colouring from RaceData at runtime; removing them renders the morph flat black.

		-- Drop pieces this morph is known to double up on (prevents z-fighting overlaps).
		local hideParts = MORPH_HIDE_PARTS[base]
		if hideParts then
			for _, p in ipairs(model:GetDescendants()) do
				if p:IsA("BasePart") and hideParts[p.Name] then
					pcall(function() p:Destroy() end)
				end
			end
		end

		-- Per-morph forced part->limb map, consulted before name guessing.
		local partLimbMap = MORPH_PART_LIMB[base]
		local function overrideLimb(partName)
			local nm = partLimbMap and partLimbMap[partName]
			if nm then
				local l = char:FindFirstChild(nm)
				if l and l:IsA("BasePart") then return l end
			end
			return nil
		end
		local rigidHead = MORPH_RIGID_HEAD[base]
		-- Records which character limb each morph part was bound to, so sub-parts of an assembly can inherit their parent's limb instead of falling to a nearest-position guess that can strand them on the chest.
		local partToLimb = {}

		-- Snapshot the real body NOW (before adding morph parts) so we can hide it wholesale, skipping any joint-filler limbs this morph wants kept visible.
		local keepVisible = MORPH_KEEP_VISIBLE[morphName] or {}
		local originalBits = {}
		for _, p in ipairs(char:GetDescendants()) do
			local isPart = p:IsA("BasePart") and p.Name ~= "HumanoidRootPart"
			local isDecal = p:IsA("Decal") or p:IsA("Texture")
			if isPart or isDecal then
				local ownerName = isPart and p.Name or (p.Parent and p.Parent.Name)
				if not (ownerName and keepVisible[ownerName]) then
					if isDecal and p:GetAttribute("MiraMorphHidden") == nil then
						p:SetAttribute("MiraMorphHidden", p.Transparency)
					end
					originalBits[#originalBits + 1] = p
				end
			end
		end

		local cAnchor = findCharAnchor(char)
		local mAnchor = findMorphAnchor(model)
		if not cAnchor or not mAnchor then return false, "could not find torso anchor" end

		-- Does this morph actually replace the body?
		local morphWantsHide = model:FindFirstChild("HideBody", true) ~= nil
		-- Only trust the anchor if it's a genuine torso part; otherwise recenter afterward.
		local TRUE_TORSO = {
			HumanoidRootPart = true, UpperTorso = true, Torso = true,
			LowerTorso = true, tt = true, t = true, lt = true,
		}
		local trustedAnchor = TRUE_TORSO[mAnchor.Name] == true

		-- Transform that maps morph-space onto the character.
		local T = cAnchor.CFrame * mAnchor.CFrame:Inverse()

		-- Parts already driven by the morph's own joints — don't re-weld those.
		local driven = {}
		for _, j in ipairs(model:GetDescendants()) do
			if j:IsA("Weld") or j:IsA("Motor6D") or j:IsA("WeldConstraint")
				or j:IsA("Snap") or j:IsA("ManualWeld") then
				if j.Part1 then driven[j.Part1] = true end
			end
		end

		-- Rigidly slide the whole morph onto the character (keeps internal layout + joints).
		for _, p in ipairs(model:GetDescendants()) do
			if p:IsA("BasePart") then
				p.CFrame = T * p.CFrame
			end
		end

		-- If we anchored off a non-torso part (e.g.
		if not trustedAnchor then
			local sum, cnt = Vector3.zero, 0
			for _, p in ipairs(model:GetDescendants()) do
				if p:IsA("BasePart") then sum = sum + p.Position; cnt = cnt + 1 end
			end
			if cnt > 0 then
				local center = sum / cnt
				local delta = Vector3.new(cAnchor.Position.X - center.X, 0, cAnchor.Position.Z - center.Z)
				for _, p in ipairs(model:GetDescendants()) do
					if p:IsA("BasePart") then p.CFrame = p.CFrame + delta end
				end
			end
		end

		-- Forward/back nudge along the character's facing: per-morph baked default.
		local fwdAmount = MORPH_FORWARD[morphName] or 0
		if fwdAmount ~= 0 then
			local fwd = cAnchor.CFrame.LookVector * fwdAmount
			for _, p in ipairs(model:GetDescendants()) do
				if p:IsA("BasePart") then p.CFrame = p.CFrame + fwd end
			end
		end

		-- Full-body R15 rig morphs (e.g.
		local rigParts = {}
		for _, p in ipairs(model:GetDescendants()) do
			if p:IsA("BasePart") and R15_LIMB_SET[p.Name] and char:FindFirstChild(p.Name) then
				rigParts[#rigParts + 1] = p
			end
		end
		if #rigParts >= 6 then
			-- Cut the morph's internal limb welds so each limb is free to follow its own bone.
			for _, w in ipairs(model:GetDescendants()) do
				if (w:IsA("Weld") or w:IsA("Motor6D") or w:IsA("ManualWeld")
					or w:IsA("Snap") or w:IsA("WeldConstraint"))
					and w.Part1 and R15_LIMB_SET[w.Part1.Name] then
					w:Destroy()
				end
			end
			for _, p in ipairs(rigParts) do
				local targetName = p.Name
				local keepPos = false
				-- Rigid-head morphs: pin the head to the torso and KEEP its current offset above the body, so the log head rides the torso as one piece instead of pivoting on the neck when the character animates.
				if rigidHead and p.Name == "Head" then
					if char:FindFirstChild("UpperTorso") then targetName = "UpperTorso"
					elseif char:FindFirstChild("Torso") then targetName = "Torso" end
					keepPos = true
				end
				local real = char:FindFirstChild(targetName)
				if real and real:IsA("BasePart") then
					-- A standard R15 skinned part's CFrame IS its bone frame, so aligning it to the real limb's CFrame fits it exactly; the weld then locks it there.
					if not keepPos then p.CFrame = real.CFrame end
					p.Anchored = false; p.CanCollide = false; p.Massless = true
					local w = Instance.new("Weld")
					w.Name = "MiraMorphWeld"
					w.Part0 = real
					w.Part1 = p
					w.C0 = real.CFrame:Inverse() * p.CFrame
					w.C1 = CFrame.new()
					w.Parent = p
					driven[p] = true
				end
			end
			-- Hide the leftover bone-anchor Parts (la/t/h/...): they only carried the welds we just replaced and would otherwise render as stray blocks around the body.
			for _, p in ipairs(model:GetDescendants()) do
				if p.ClassName == "Part" and not driven[p] then
					pcall(function()
						p.Transparency = 1; p.CanCollide = false; p.Massless = true
					end)
				end
			end
		end

		-- Cosmetic/clothing morphs: place Offset-attachment pieces on the right limb and swap the face decal.
		if not morphWantsHide then
			local headPart = char:FindFirstChild("Head")
			local torsoPart = char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso")
			for _, p in ipairs(model:GetDescendants()) do
				if p:IsA("BasePart") and not driven[p] then
					local off = bindingAttachment(p)
					if off then
						local n = p.Name:lower()
						local isHair = n:find("hair") ~= nil
						-- Prefer the limb named in the part itself (e.g.
						local limb = overrideLimb(p.Name) or limbFromName(char, p.Name)
						if not limb then
							if isHair or n:find("head") or n:find("face")
								or n:find("hat") or n:find("horn") or n:find("mask") then
								limb = headPart
							else
								limb = torsoPart
							end
						end
						if limb then
							-- The Offset attachment marks where the piece meets the limb; align that attachment onto the limb so it sits right.
							p.CFrame = limb.CFrame * off.CFrame:Inverse()
							-- Per-morph vertical correction for pieces that anchor too low.
							local lift = partLift(morphName, p.Name)
							if lift ~= 0 then
								p.CFrame = p.CFrame + Vector3.new(0, lift, 0)
							end
							p.Anchored = false; p.CanCollide = false; p.Massless = true
							local w = Instance.new("Weld")
							w.Name = "MiraMorphWeld"
							w.Part0 = limb
							w.Part1 = p
							w.C0 = limb.CFrame:Inverse() * p.CFrame
							w.C1 = CFrame.new()
							w.Parent = p
							driven[p] = true
							partToLimb[p] = limb
							if isHair then morphHasHair = true end
						end
					end
				end
			end

			-- Face: Deepwoken renders the face as a Decal sitting on the FaceMount mesh -- NOT the block Head, and NOT the mesh's TextureID.
			local faces = model:FindFirstChild("Faces", true)
			local head = char:FindFirstChild("Head")
			if faces and head then
				local srcFace = faces:FindFirstChild("Base") or faces:FindFirstChildWhichIsA("Decal")
				if srcFace and srcFace:IsA("Decal") then
					local faceTex = srcFace.Texture
					-- The face decal lives under the head (usually on FaceMount).
					local faceDecal
					for _, d in ipairs(head:GetDescendants()) do
						if d:IsA("Decal") then
							if d.Name:lower() == "face" then
								faceDecal = d
								break
							elseif not faceDecal then
								faceDecal = d
							end
						end
					end
					if faceDecal then
						if faceDecal:GetAttribute("MiraMorphFace") == nil then
							faceDecal:SetAttribute("MiraMorphFace", faceDecal.Texture)
						end
						faceDecal.Texture = faceTex
						-- Deepwoken layers separate overlay decals for the eyes/brows on top of the base face; the morph face already includes its own eyes, so hide every OTHER face decal/texture on the head so the real eyes don't show through.
						for _, d in ipairs(head:GetDescendants()) do
							if d ~= faceDecal
								and (d:IsA("Decal") or d:IsA("Texture"))
								and not d:GetAttribute("MiraMorphFaceClone")
							then
								if d:GetAttribute("MiraMorphHidden") == nil then
									d:SetAttribute("MiraMorphHidden", d.Transparency)
								end
								d.Transparency = 1
							end
						end
					else
						-- No existing face decal: mount a fresh one on FaceMount's front (a Decal keeps alpha, so it blends instead of boxing solid).
						local mount = head:FindFirstChild("FaceMount") or head
						local nd = srcFace:Clone()
						nd.Name = "MiraMorphFace"
						nd.Face = Enum.NormalId.Front
						nd:SetAttribute("MiraMorphFaceClone", true)
						nd.Parent = mount
					end
				end
			end
		end

		-- Bind each free (non-driven) part to a limb so it sits right and articulates.
		local bound = 0
		for _, p in ipairs(model:GetDescendants()) do
			if p:IsA("BasePart") and not driven[p] then
				local limb = overrideLimb(p.Name) or limbFromName(char, p.Name)
				if not limb then
					-- Inherit the limb an ancestor part was bound to: a strand parented under a hair clump belongs on the head with it, not wherever nearest-position lands.
					local anc = p.Parent
					while anc and anc ~= model do
						if partToLimb[anc] then limb = partToLimb[anc]; break end
						anc = anc.Parent
					end
				end
				limb = limb or nearestLimb(limbs, p.Position)
				if limb then
					p.Anchored = false
					p.CanCollide = false
					p.Massless = true
					local w = Instance.new("Weld")
					w.Name = "MiraMorphWeld"
					w.Part0 = limb
					w.Part1 = p
					w.C0 = limb.CFrame:Inverse() * p.CFrame
					w.C1 = CFrame.new()
					w.Parent = p
					partToLimb[p] = limb
					bound = bound + 1
				end
			end
		end

		-- Safety net: if every part looked driven, at least pin the anchor to the torso.
		if bound == 0 then
			mAnchor.Anchored = false
			local w = Instance.new("Weld")
			w.Name = "MiraMorphWeld"
			w.Part0 = cAnchor
			w.Part1 = mAnchor
			w.C0 = cAnchor.CFrame:Inverse() * mAnchor.CFrame
			w.Parent = mAnchor
		end

		-- Nothing anchored / colliding.
		for _, p in ipairs(model:GetDescendants()) do
			if p:IsA("BasePart") then
				p.Anchored = false
				p.CanCollide = false
			end
		end

		-- Accessories self-weld under the Humanoid.
		for _, acc in ipairs(model:GetDescendants()) do
			if acc:IsA("Accessory") then acc.Parent = char end
		end

		-- Turn effects on (they usually ship disabled).
		for _, fx in ipairs(model:GetDescendants()) do
			if fx:IsA("ParticleEmitter") or fx:IsA("Trail") or fx:IsA("Beam")
				or fx:IsA("PointLight") or fx:IsA("SpotLight") or fx:IsA("SurfaceLight") then
				pcall(function() fx.Enabled = true end)
			end
		end

		-- Apply clothing morphs (Shirt / Pants / graphic) straight onto the character.
		local backup = char:FindFirstChild(BACKUP_NAME)
		for _, cl in ipairs(model:GetDescendants()) do
			if cl:IsA("Shirt") or cl:IsA("Pants") or cl:IsA("ShirtGraphic") then
				if not backup then
					backup = Instance.new("Folder")
					backup.Name = BACKUP_NAME
					backup.Parent = char
				end
				local existing = char:FindFirstChildOfClass(cl.ClassName)
				if existing then existing.Parent = backup end
				local clone = cl:Clone()
				clone:SetAttribute("MiraMorphClothing", true)
				clone.Parent = char
				-- The carrier part (e.g.
				local carrier = cl.Parent
				if carrier and carrier:IsA("BasePart") then
					carrier.Transparency = 1
					carrier.CanCollide = false
				end
			end
		end

		-- Hide the player's real hair whenever the morph replaces the body or brings its own hair.
		if morphWantsHide or morphHasHair then
			for _, acc in ipairs(char:GetChildren()) do
				if acc:IsA("Accessory") then
					local handle = acc:FindFirstChild("Handle")
					local isHairAcc = false
					local ok, at = pcall(function() return acc.AccessoryType end)
					if ok and at == Enum.AccessoryType.Hair then isHairAcc = true end
					if handle and handle:FindFirstChild("HairAttachment") then isHairAcc = true end
					if isHairAcc and handle then extraHide[#extraHide + 1] = handle end
				end
			end
		end

		-- Wear-over morph that brings its OWN head: the real Deepwoken head keeps rendering straight through the morph one -- the "two heads" bug.
		if hideBody and not morphWantsHide then
			local morphReplacesHead = false
			for _, p in ipairs(model:GetDescendants()) do
				-- Exact "Head" only: a piece merely CONTAINING "head" is an accessory, not a head replacement -- hiding the real head for those would leave the character headless.
				if p:IsA("BasePart") and p.Name:lower() == "head" then
					morphReplacesHead = true
					break
				end
			end
			if morphReplacesHead then
				local realHead = char:FindFirstChild("Head")
				if realHead then
					extraHide[#extraHide + 1] = realHead
					for _, d in ipairs(realHead:GetChildren()) do
						if d:IsA("Decal") or d:IsA("Texture") then
							extraHide[#extraHide + 1] = d
						end
					end
				end
			end
		end

		-- Hide the real body ONLY for morphs that truly replace it (e.g.
		if hideBody and morphWantsHide and not MORPH_NOHIDE[morphName] then
			startHide(originalBits)
		elseif #extraHide > 0 then
			startHide(extraHide)
		else
			stopHide()
		end

		-- Skin tone: recolor the real body limbs to the morph's skin so exposed arms/legs/hands match instead of showing the player's own pale skin.
		local skin = MORPH_SKIN[(tostring(morphName):gsub("%s*%(%d+%)%s*$", ""))]
		if skin then
			for _, name in ipairs(SKIN_LIMBS) do
				local part = char:FindFirstChild(name)
				if part and part:IsA("BasePart") then
					if part:GetAttribute("MiraMorphSkin") == nil then
						part:SetAttribute("MiraMorphSkin", part.Color)
					end
					part.Color = skin
				end
			end

			-- The FACE mesh isn't in SKIN_LIMBS: recolor it to skin so the face isn't left white, and clear its Deepwoken face TextureID so the old eyes/skin stop bleeding through the morph face's transparent parts.
			local skinHead = char:FindFirstChild("Head")
			local faceMount = skinHead and skinHead:FindFirstChild("FaceMount")
			if faceMount and faceMount:IsA("MeshPart") then
				if faceMount:GetAttribute("MiraMorphSkin") == nil then
					faceMount:SetAttribute("MiraMorphSkin", faceMount.Color)
				end
				faceMount.Color = skin
				if faceMount:GetAttribute("MiraMorphFaceTex") == nil then
					faceMount:SetAttribute("MiraMorphFaceTex", faceMount.TextureID)
				end
				faceMount.TextureID = ""
			end
		end

		-- Corrective lift for driven sub-parts that hang too low.
		local subLift = MORPH_SUBPART_LIFT[base]
		if subLift then
			for _, j in ipairs(model:GetDescendants()) do
				if (j:IsA("Motor6D") or j:IsA("Weld")) and j.Part1 and subLift[j.Part1.Name] then
					j.C0 = CFrame.new(0, subLift[j.Part1.Name], 0) * j.C0
				end
			end
		end

		local holder = char:FindFirstChild(HOLDER_NAME)
		if not holder then
			holder = Instance.new("Folder")
			holder.Name = HOLDER_NAME
			holder.Parent = char
		end
		model.Parent = holder
		return true
	end

	local function loadMorph(category, fileName)
		if not fileName or fileName == "" then
			return Logger.notify("Pick a morph from the dropdown first.")
		end
		if type(readCustomAsset) ~= "function" then
			return Logger.notify("Executor has no getcustomasset — can't load local models.")
		end
		local path = (FOLDERS[category] or FOLDERS.Races) .. "/" .. fileName .. ".rbxm"
		local ok, asset = pcall(readCustomAsset, path)
		if not ok or not asset then
			return Logger.notify("getcustomasset failed: " .. path)
		end
		local ok2, objs = pcall(function() return game:GetObjects(asset) end)
		if not ok2 or type(objs) ~= "table" or not objs[1] then
			return Logger.notify("Failed to deserialize: " .. tostring(objs))
		end
		local model = objs[1]
		if not model:IsA("Model") then
			local m = Instance.new("Model")
			model.Parent = m
			model = m
		end


		-- Force the morph's meshes/textures to download BEFORE we place anything.
		pcall(function()
			local cp = game:GetService("ContentProvider")
			local assets = { model }
			for _, d in ipairs(model:GetDescendants()) do
				if d:IsA("MeshPart") or d:IsA("SpecialMesh") or d:IsA("Decal") or d:IsA("Texture") then
					assets[#assets + 1] = d
				end
			end
			cp:PreloadAsync(assets)
		end)

		clearMorphs() -- replace any previously applied morph
		local okA, err = applyModel(model, hideBodyEnabled, fileName)
		if okA then
			lastApplied = { category = category, file = fileName }

		else
			if model then model:Destroy() end
			Logger.notify("Apply error: " .. tostring(err))
		end
	end

	-- ===== UI =====
	local catDropdown = groupbox:AddDropdown("MiraMorph_Category", {
		Text = "Category",
		Values = { "Races", "Ornaments" },
		AllowNull = false,
		Default = "Races",
	})

	local morphDropdown = groupbox:AddDropdown("MiraMorph_File", {
		Text = "Morph",
		Values = listMorphs(FOLDERS[currentCategory]),
		AllowNull = true,
		Default = nil,
	})

	catDropdown:OnChanged(function(v)
		currentCategory = v
		morphDropdown:SetValues(listMorphs(FOLDERS[v]))
		morphDropdown:Display()
	end)

	morphDropdown:OnChanged(function(v)
		currentFile = v
	end)

	groupbox:AddButton("Load Morph", function()
		loadMorph(currentCategory, currentFile)
	end)

	groupbox:AddButton("Clear Morph", function()
		clearMorphs()
		lastApplied = nil
		Logger.notify("Cleared applied morphs.")
	end)

	groupbox:AddButton("Refresh List", function()
		morphDropdown:SetValues(listMorphs(FOLDERS[currentCategory]))
		morphDropdown:Display()
	end)

	hideToggle = groupbox:AddToggle("MiraMorph_HideBody", {
		Text = "Hide real body (for HideBody morphs)",
		Default = true,
	})
	hideToggle:OnChanged(function(v)
		hideBodyEnabled = v
	end)

	local reapplyToggle = groupbox:AddToggle("MiraMorph_Reapply", {
		Text = "Reapply on respawn",
		Default = false,
	})
	reapplyToggle:OnChanged(function(v)
		reapplyEnabled = v
	end)

	lp.CharacterAdded:Connect(function()
		if reapplyEnabled and lastApplied then
			task.wait(1.5)
			loadMorph(lastApplied.category, lastApplied.file)
		end
	end)
end

---Initialize Combat Reveals section.
---@param groupbox table
function VisualsTab.initCombatRevealsSection(groupbox)
	groupbox:AddToggle("RevealAnimations", {
		Text = "Reveal AP Break Animations",
		Tooltip = "is that ur ap breaker lollll",
		Default = false,
	})

	local revealDepBox = groupbox:AddDependencyBox()

	revealDepBox:AddSlider("RevealWeightThreshold", {
		Text = "Weight Threshold",
		Tooltip = "Any non-attack track rendering under this weight gets dragged to full so hidden decoys show. Higher = reveal more aggressively.",
		Default = 0.5,
		Min = 0,
		Max = 1,
		Suffix = "",
		Rounding = 2,
	})

	revealDepBox:SetupDependencies({
		{ Toggles.RevealAnimations, true },
	})
end

-- Return VisualsTab module.
return VisualsTab
end)()
end)
__bundle_register("Features/Visuals/ExternalESP", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

--[[
	ExternalESP — streamproof ESP bridge.

	Internal executors (Volt, Synapse Z) render every drawing through Roblox's own
	pipeline, so anything they draw shows up in screenshots and recordings. There is
	no way for the executor to hide its own GUI from capture.

	The workaround: stop letting Roblox draw the ESP and hand the drawing to a
	SEPARATE window we own — a transparent, click-through overlay produced by an
	external Python process (see mira_esp.py). That window is excluded from capture
	at the OS level (SetWindowDisplayAffinity / WDA_EXCLUDEFROMCAPTURE), so it is
	streamproof for free.

	The split:
	  - This module (the "brain") computes everything Roblox already knows — screen
	    positions, health, names, distance — and serializes it into draw commands.
	  - Python (the "pen") receives those commands and paints. It never reads or
	    writes memory; it can't, and it doesn't need to.

	Detection is by file presence: the user drops mira_esp.py into the executor's
	"Mira" folder (same folder the config/theme/morph data lives in) and runs it.
	If the file is there, the UI unlocks the toggle. If not, the toggle bounces off
	with an install hint.

	Transport is a localhost WebSocket. mira_esp.py runs the server; we connect as a
	client and push one JSON frame per tick.
--]]

local ExternalESP = {}

-- Services.
local players = game:GetService("Players")
local runService = game:GetService("RunService")
local guiService = game:GetService("GuiService")
local workspaceService = workspace

-- The file the user is expected to drop into the executor "Mira" folder.
local SCRIPT_NAME = "Mira/mira_esp.py"

-- Executor file API resolution (matches the pattern used by the morph loader).
local fileExists = isfile
local makeFolder = makefolder
local folderExists = isfolder

-- WebSocket API resolution across executors: Volt: global WebSocket.connect(url) Synapse Z: syn.websocket.connect(url) (older builds expose WebSocket too)
local websocketConnect = (WebSocket and WebSocket.connect)
	or (syn and syn.websocket and syn.websocket.connect)

-- Connection state.
local socket = nil
local connected = false
local renderConnection = nil
local lastSend = 0.0

-- Diagnostics for the "why isn't it drawing" case.
local dbgPumpTicks = 0     -- times pump fired at all
local dbgFramesSent = 0    -- times a payload was actually handed to the socket
local dbgLastItems = 0     -- item count of the last frame built
local dbgSendOk = "n/a"    -- did the last send call succeed
local dbgSendErr = ""      -- last send error, if any

-- Default draw port.
local DEFAULT_PORT = 7813

-- Box color fallback if the Player ESP color option isn't set.
local FALLBACK_COLOR = Color3.new(1, 1, 1)

--- Make sure the base "Mira" folder exists so a fresh install has somewhere to drop the script.
local ensureBaseFolder = (function()
	if type(makeFolder) ~= "function" then
		return
	end

	if type(folderExists) == "function" and folderExists("Mira") then
		return
	end

	pcall(makeFolder, "Mira")
end)

--- Is the Python overlay file present in the Mira folder?
---@return boolean
ExternalESP.installed = (function()
	if type(listfiles) ~= "function" then
		return false
	end

	local ok, list = pcall(listfiles, "Mira")
	if not ok or type(list) ~= "table" then
		return false
	end

	for _, entry in next, list do
		-- Entries can come back as "Mira/mira_esp.py" or "Mira\\mira_esp.py".
		local path = tostring(entry):gsub("\\", "/"):lower()
		if path:sub(-#"mira_esp.py") == "mira_esp.py" then
			return true
		end
	end

	return false
end)

---Convert a Color3 into a "rrggbb" hex string for the wire.
---@param color Color3
---@return string
local hexOf = (function(color)
	color = color or FALLBACK_COLOR
	return string.format(
		"%02x%02x%02x",
		math.floor(color.R * 255 + 0.5),
		math.floor(color.G * 255 + 0.5),
		math.floor(color.B * 255 + 0.5)
	)
end)

--- Project a character's 3D bounds to a stable 2D screen rectangle.
---@param camera Camera
---@param cframe CFrame
---@param size Vector3
---@return table|nil  { x, y, w, h }
local projectBox = (function(camera, cframe, size)
	local center = cframe.Position
	local centerScreen = camera:WorldToViewportPoint(center)

	-- Behind the camera → genuinely not visible.
	if centerScreen.Z <= 0 then
		return nil
	end

	local halfHeight = size.Y * 0.5
	local halfWidth = math.max(size.X, size.Z) * 0.5

	-- Vertical extent: world up/down around the center.
	local topScreen = camera:WorldToViewportPoint(center + Vector3.new(0, halfHeight, 0))
	local bottomScreen = camera:WorldToViewportPoint(center - Vector3.new(0, halfHeight, 0))

	-- Horizontal extent: use the camera's screen-facing right vector so the width stays stable regardless of the entity's own facing.
	local rightVector = camera.CFrame.RightVector
	local rightScreen = camera:WorldToViewportPoint(center + rightVector * halfWidth)
	local leftScreen = camera:WorldToViewportPoint(center - rightVector * halfWidth)

	local top = math.min(topScreen.Y, bottomScreen.Y)
	local bottom = math.max(topScreen.Y, bottomScreen.Y)
	local left = math.min(leftScreen.X, rightScreen.X)
	local right = math.max(leftScreen.X, rightScreen.X)

	return {
		x = math.floor(left),
		y = math.floor(top),
		w = math.floor(right - left),
		h = math.floor(bottom - top),
	}
end)

-- Lazily-resolved reference to the Visuals module so we can read its live ESP object pool.
local Visuals = nil
local resolveVisuals = (function()
	if Visuals then
		return Visuals
	end
	local ok, mod = pcall(require, "Features/Visuals/Visuals")
	if ok and type(mod) == "table" then
		Visuals = mod
	end
	return Visuals
end)

--- Resolve a world CFrame + size to draw a box around, for any ESP object kind.
---@param object table
---@return CFrame|nil, Vector3|nil
local objectBounds = (function(object)
	local model = object.entity
	if model and typeof(model) == "Instance" and model:IsA("Model") then
		local ok, cframe, size = pcall(function()
			local c, s = model:GetBoundingBox()
			return c, s
		end)
		if ok and cframe then
			return cframe, size
		end
	end

	local instance = object.instance
	if instance and typeof(instance) == "Instance" and instance:IsA("BasePart") then
		return instance.CFrame, instance.Size
	end

	local adornee = object.billboard and object.billboard.Adornee
	if adornee and typeof(adornee) == "Instance" then
		if adornee:IsA("BasePart") then
			return adornee.CFrame, adornee.Size
		elseif adornee:IsA("Model") then
			local ok, cframe, size = pcall(function()
				local c, s = adornee:GetBoundingBox()
				return c, s
			end)
			if ok and cframe then
				return cframe, size
			end
		end
	end

	return nil, nil
end)

--- Build one draw frame by mirroring the LIVE ESP object pool.
---@return table|nil
local buildFrame = (function()
	local camera = workspaceService.CurrentCamera
	if not camera then
		return nil
	end

	local viewport = camera.ViewportSize
	local items = {}

	-- The Python overlay now tracks Roblox's client area exactly, which is the same space WorldToViewportPoint returns — so the coordinates map 1:1 with no inset correction.
	local offX = Configuration.expectOptionValue("ExternalESPOffsetX") or 0
	local offY = Configuration.expectOptionValue("ExternalESPOffsetY") or 0

	local vis = resolveVisuals()
	local groups = vis and vis.groups

	if groups then
		for _, group in next, groups do
			-- group:data() returns the pooled ESP objects for this category.
			local ok, objects = pcall(function()
				return group:data()
			end)
			if ok and type(objects) == "table" then
				for _, object in next, objects do
					-- One bad object must never kill the whole frame.
					pcall(function()
						-- FilteredESP is a thin wrapper: the real ESP object — with the billboard, bounds, _show flag and label — lives in.object.
						local obj = object
						if obj.__type == "FilteredESP" and obj.object then
							obj = obj.object
						end

						-- Logical visibility (object's visible()); billboard is hidden while overlay active.
						if not obj._show then
							return
						end

						local cframe, size = objectBounds(obj)
						if not cframe then
							return
						end

						local box = projectBox(camera, cframe, size)
						if not box then
							return
						end

						-- Keep degenerate boxes visible instead of dropping them.
						if box.w < 4 then box.w = 4 end
						if box.h < 4 then box.h = 4 end

						-- Align to the overlay: strip the GUI inset + apply user nudge.
						box.x = box.x + offX
						box.y = box.y + offY

						-- Only cull boxes that are WAY off screen (generous margin), so on-screen and edge boxes never blink out mid-camera-move.
						local margin = 200
						if box.x + box.w < -margin or box.x > viewport.X + margin
							or box.y + box.h < -margin or box.y > viewport.Y + margin then
							return
						end

						local color = Configuration.idOptionValue(obj.identifier, "Color") or FALLBACK_COLOR
						local hex = hexOf(color)

						items[#items + 1] = {
							k = "box",
							x = box.x, y = box.y, w = box.w, h = box.h, c = hex,
						}

						-- Label (name / object type) above the box.
						local label = obj.label
						if type(label) == "string" and #label > 0 then
							items[#items + 1] = {
								k = "text",
								x = box.x + math.floor(box.w * 0.5),
								y = box.y - 14,
								a = "center",
								s = label,
								c = hex,
							}
						end

						-- Health bar for anything with a Humanoid (players/mobs/NPCs).
						local model = obj.entity
						local humanoid = model and typeof(model) == "Instance"
							and model:FindFirstChildOfClass("Humanoid")
						if humanoid and humanoid.MaxHealth > 0 then
							items[#items + 1] = {
								k = "bar",
								x = box.x - 5,
								y = box.y,
								w = 3,
								h = box.h,
								p = math.clamp(humanoid.Health / humanoid.MaxHealth, 0, 1),
							}
						end
					end)
				end
			end
		end
	end

	return {
		t = "frame",
		w = math.floor(viewport.X),
		h = math.floor(viewport.Y),
		items = items,
	}
end)

--- Push the current frame down the socket.
local pump = (function()
	if not connected or not socket then
		return
	end

	-- Reuse the existing ESP refresh-rate option as our send cap.
	local hz = Configuration.expectOptionValue("ESPRefreshRate")
	local interval = hz and hz > 0 and (1 / math.clamp(hz, 15, 144)) or (1 / 60)

	local now = os.clock()
	if now - lastSend < interval then
		return
	end
	lastSend = now
	dbgPumpTicks = dbgPumpTicks + 1

	local frame = buildFrame()
	if not frame then
		return
	end
	dbgLastItems = frame.items and #frame.items or 0

	local ok, payload = pcall(function()
		return game:GetService("HttpService"):JSONEncode(frame)
	end)
	if not ok then
		dbgSendOk = "encode-failed"
		dbgSendErr = tostring(payload)
		return
	end

	-- Send method casing differs across executors (:Send vs :send).
	local sent, err = pcall(function()
		socket:Send(payload)
	end)
	if not sent then
		sent, err = pcall(function()
			socket:send(payload)
		end)
	end

	if sent then
		dbgFramesSent = dbgFramesSent + 1
		dbgSendOk = "ok"
	else
		dbgSendOk = "send-failed"
		dbgSendErr = tostring(err)
	end
end)

---Open the socket and start streaming.
---@return boolean success
ExternalESP.enable = (function(port)
	if connected then
		return true
	end

	if type(websocketConnect) ~= "function" then
		Logger.notify("This executor has no WebSocket support — external ESP can't connect.")
		return false
	end

	port = port or DEFAULT_PORT
	local url = string.format("ws://127.0.0.1:%d", port)

	local ok, result = pcall(websocketConnect, url)
	if not ok or not result then
		Logger.notify("Couldn't reach the overlay on %s. Is mira_esp.py running?", url)
		return false
	end

	socket = result
	connected = true
	-- Flag consumed by EntityESP/InstanceESP:visible() to hide the in-world billboards so only the streamproof overlay draws.
	shared.MiraExternalActive = true

	-- Drop our state if Python closes (window shut, script killed).
	if socket.OnClose then
		socket.OnClose:Connect(function()
			connected = false
			socket = nil
			shared.MiraExternalActive = false
		end)
	end

	renderConnection = runService.RenderStepped:Connect(pump)
	Logger.notify("External streamproof ESP connected on %s.", url)
	return true
end)

---Close the socket and stop streaming.
ExternalESP.disable = (function()
	if renderConnection then
		renderConnection:Disconnect()
		renderConnection = nil
	end

	if socket then
		pcall(function()
			socket:Close()
		end)
	end

	socket = nil
	connected = false
	-- Re-show the in-world billboards next update cycle.
	shared.MiraExternalActive = false
end)

---Current connection state.
---@return boolean
ExternalESP.isConnected = (function()
	return connected
end)

--- Diagnostic: walk the pool exactly like buildFrame and report where it drops to zero, so we can see whether the problem is the require, the pool, visibility, bounds, or projection.
---@return string
ExternalESP.debugStream = (function()
	local camera = workspaceService.CurrentCamera
	local vis = resolveVisuals()
	local groups = vis and vis.groups

	if not vis then
		return "Visuals module did NOT resolve (require failed)."
	end
	if not groups then
		return "Visuals resolved, but Visuals.groups is nil (pool not exposed)."
	end

	local nGroups, nObjects, nEnabled, nBounds, nProjected = 0, 0, 0, 0, 0
	local perGroup = {}
	for identifier, group in next, groups do
		nGroups = nGroups + 1
		local gObjects, gEnabled = 0, 0
		local ok, objects = pcall(function()
			return group:data()
		end)
		if ok and type(objects) == "table" then
			for _, object in next, objects do
				nObjects = nObjects + 1
				gObjects = gObjects + 1
				-- Unwrap FilteredESP (see buildFrame) so wrapped categories count too.
				local obj = object
				if obj.__type == "FilteredESP" and obj.object then
					obj = obj.object
				end
				local bb = obj.billboard
				if obj._show then
					nEnabled = nEnabled + 1
					gEnabled = gEnabled + 1
					local cframe, size = objectBounds(obj)
					if cframe then
						nBounds = nBounds + 1
						if camera then
							local box = projectBox(camera, cframe, size)
							if box and box.w > 0 and box.h > 0 then
								nProjected = nProjected + 1
							end
						end
					end
				end
			end
		end
		-- Only list groups that actually hold objects, to keep it readable.
		if gObjects > 0 then
			perGroup[#perGroup + 1] = string.format("%s:%d/%d", tostring(identifier), gEnabled, gObjects)
		end
	end

	-- Sample the first object of the first non-empty group so we can see whether these pooled objects even carry a billboard and what its Enabled value is.
	local sample = "none"
	for _, group in next, groups do
		local ok, objects = pcall(function()
			return group:data()
		end)
		if ok and type(objects) == "table" then
			local first = objects[1] or (next(objects) and select(2, next(objects)))
			if first then
				sample = string.format(
					"type=%s billboard=%s enabled=%s entity=%s instance=%s",
					tostring(first.__type),
					type(first.billboard),
					tostring(first.billboard and first.billboard.Enabled),
					tostring(first.entity ~= nil),
					tostring(first.instance ~= nil)
				)
				break
			end
		end
	end

	local groupsStr = table.concat(perGroup, "  ")
	local stream = string.format(
		"STREAM: pumpTicks=%d framesSent=%d lastItems=%d sendOk=%s err=%s",
		dbgPumpTicks, dbgFramesSent, dbgLastItems, dbgSendOk, dbgSendErr ~= "" and dbgSendErr or "-"
	)
	return string.format(
		"totals: groups=%d obj=%d enabled=%d proj=%d | %s | sample: %s",
		nGroups, nObjects, nEnabled, nProjected, stream, sample
	)
end)

-- Default the suppression flag so ESP objects have a defined value to read.
if shared.MiraExternalActive == nil then
	shared.MiraExternalActive = false
end

-- Make sure the base folder exists so the user has a place to drop the file.
ensureBaseFolder()

return ExternalESP
end)()
end)
__bundle_register("Features/Visuals/WispVisualizer", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
-- Wisp Visualizer -- a top-of-screen readout of which of YOUR wisps are currently out.

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")

---@module Utility.CoreGuiManager
local CoreGuiManager = require("Utility/CoreGuiManager")
---@module GUI.Library
local Library = require("GUI/Library")

local WispVisualizer = {}

-- Elements, in display order.
local ELEMENTS = {
	{ key = "FireWisp",      label = "FIRE",      match = "fire",      color = Color3.fromRGB(255, 140, 60) },
	{ key = "IceWisp",       label = "ICE",       match = "ice",       color = Color3.fromRGB(150, 220, 255) },
	{ key = "LightningWisp", label = "LIGHTNING", match = "lightning", color = Color3.fromRGB(255, 240, 130) },
	{ key = "WindWisp",      label = "WIND",      match = "wind",      color = Color3.fromRGB(170, 255, 200) },
	{ key = "ShadowWisp",    label = "SHADOW",    match = "shadow",    color = Color3.fromRGB(170, 115, 215) },
	{ key = "MetalWisp",     label = "METAL",     match = "metal",     color = Color3.fromRGB(195, 195, 205) },
	{ key = "BloodWisp",     label = "BLOOD",     match = "blood",     color = Color3.fromRGB(210, 60, 70) },
}

local ACTIVE_COLOR = Color3.fromRGB(80, 230, 120)
local INACTIVE_COLOR = Color3.fromRGB(230, 80, 90)
local MUTED = Color3.fromRGB(168, 156, 182)

local OWNERSHIP_RADIUS = 10 -- studs

-- State
local running = false
local screenGui, mainFrame
local rows = {}            -- element key -> { statusLabel = ... }
local ownedWisps = {}      -- element key -> { [model] = true }
local thrownConns = {}
local thrownWatchConn = nil
local updateConn = nil
local updateAccum = 0

-- Helpers
local function mk(class, props, parent)
	local inst = Instance.new(class)
	for key, value in pairs(props) do
		inst[key] = value
	end
	if parent then
		inst.Parent = parent
	end
	return inst
end

local function safeGet(fn, fallback)
	local ok, value = pcall(fn)
	if ok and value ~= nil then
		return value
	end
	return fallback
end

local function guiParent()
	local ok, hui = pcall(function()
		return gethui and gethui()
	end)
	if ok and hui then
		return hui
	end
	local ok2, cg = pcall(function()
		return game:GetService("CoreGui")
	end)
	if ok2 and cg then
		return cg
	end
	local lp = Players.LocalPlayer
	return lp and lp:FindFirstChildOfClass("PlayerGui")
end

-- -Which element does this model belong to?
---@param instance Instance
---@return boolean
local function isWispModel(instance)
	return tostring(instance.Name):lower():find("wisp", 1, true) ~= nil
end

---Map a WispType attribute value onto one of our element keys.
---@param attribute any
---@return string? elementKey
local function elementFromAttribute(attribute)
	if type(attribute) ~= "string" then
		return nil
	end
	for _, element in ipairs(ELEMENTS) do
		if attribute == element.key then
			return element.key
		end
	end
	-- Unrecognised spelling: still try to place it.
	local lowered = attribute:lower()
	for _, element in ipairs(ELEMENTS) do
		if lowered:find(element.match, 1, true) then
			return element.key
		end
	end
	return nil
end

-- -Resolve a wisp's element from its WispType attribute.
---@param model Instance
---@return string? elementKey
local function resolveElement(model)
	return elementFromAttribute(safeGet(function() return model:GetAttribute("WispType") end))
end

---Distance from us to a model, or nil if either side has no position yet.
---@param model Instance
---@return number?
local function distanceTo(model)
	local character = Players.LocalPlayer and Players.LocalPlayer.Character
	local root = character and character:FindFirstChild("HumanoidRootPart")
	if not root then
		return nil
	end

	local part = model:IsA("Model") and (model.PrimaryPart or model:FindFirstChildWhichIsA("BasePart", true))
		or (model:IsA("BasePart") and model)
	if not part then
		return nil
	end

	return (root.Position - part.Position).Magnitude
end

-- UI
local function buildWindow()
	if screenGui then
		return
	end

	screenGui = Instance.new("ScreenGui")
	screenGui.Name = "MiraWispVis"
	screenGui.ResetOnSpawn = false
	screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
	screenGui.DisplayOrder = 9998
	CoreGuiManager.imark(screenGui)

	local ProtectGui = protectgui or (syn and syn.protect_gui) or function() end
	pcall(ProtectGui, screenGui)
	screenGui.Parent = guiParent()

	-- Top-centre strip, one column per element.
	mainFrame = mk("Frame", {
		Name = "Strip",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0, 6),
		Size = UDim2.fromOffset(#ELEMENTS * 96, 40),
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
	}, screenGui)

	local layout = mk("UIListLayout", {
		FillDirection = Enum.FillDirection.Horizontal,
		SortOrder = Enum.SortOrder.LayoutOrder,
		HorizontalAlignment = Enum.HorizontalAlignment.Center,
		Padding = UDim.new(0, 4),
	}, mainFrame)
	layout.VerticalAlignment = Enum.VerticalAlignment.Top

	rows = {}
	for index, element in ipairs(ELEMENTS) do
		local column = mk("Frame", {
			Name = element.key,
			Size = UDim2.fromOffset(92, 40),
			BackgroundTransparency = 1,
			LayoutOrder = index,
		}, mainFrame)

		mk("TextLabel", {
			Name = "Element",
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, 18),
			Font = Enum.Font.GothamBold,
			Text = element.label,
			TextColor3 = element.color,
			TextSize = 13,
			TextStrokeTransparency = 0.5,
		}, column)

		local status = mk("TextLabel", {
			Name = "Status",
			BackgroundTransparency = 1,
			Position = UDim2.fromOffset(0, 18),
			Size = UDim2.new(1, 0, 0, 16),
			Font = Enum.Font.GothamBold,
			Text = "INACTIVE",
			TextColor3 = INACTIVE_COLOR,
			TextSize = 12,
			TextStrokeTransparency = 0.5,
		}, column)

		rows[element.key] = { status = status }
	end
end

local function setStatus(elementKey, active)
	local row = rows[elementKey]
	if not row then
		return
	end
	row.status.Text = active and "ACTIVE" or "INACTIVE"
	row.status.TextColor3 = active and ACTIVE_COLOR or INACTIVE_COLOR
end

local function refreshStatuses()
	for _, element in ipairs(ELEMENTS) do
		local owned = ownedWisps[element.key]
		local anyAlive = false
		if owned then
			for model in pairs(owned) do
				-- Parent goes nil the moment the wisp is destroyed / expires.
				if safeGet(function() return model.Parent end) then
					anyAlive = true
				else
					owned[model] = nil
				end
			end
		end
		setStatus(element.key, anyAlive)
	end
end

-- Ownership
local function claimIfOurs(model)
	if not isWispModel(model) then
		return
	end

	local elementKey = resolveElement(model)
	if not elementKey then
		return
	end

	-- Spawn distance, read once now (a wisp travels, so re-testing would be wrong).
	local spawnDistance = distanceTo(model)
	if not spawnDistance or spawnDistance > OWNERSHIP_RADIUS then
		return
	end

	ownedWisps[elementKey] = ownedWisps[elementKey] or {}
	ownedWisps[elementKey][model] = true
	setStatus(elementKey, true)
end

local function releaseModel(model)
	for key, owned in pairs(ownedWisps) do
		if owned[model] then
			owned[model] = nil
			local anyAlive = false
			for other in pairs(owned) do
				if safeGet(function() return other.Parent end) then
					anyAlive = true
					break
				end
			end
			setStatus(key, anyAlive)
		end
	end
end

local function bindThrown()
	for _, conn in ipairs(thrownConns) do
		pcall(function() conn:Disconnect() end)
	end
	thrownConns = {}

	local thrown = workspace:FindFirstChild("Thrown")
	if not thrown then
		return false
	end

	thrownConns[#thrownConns + 1] = thrown.ChildAdded:Connect(function(child)
		if running then
			claimIfOurs(child)
		end
	end)
	thrownConns[#thrownConns + 1] = thrown.ChildRemoved:Connect(function(child)
		if running then
			releaseModel(child)
		end
	end)

	-- Anything already out when we started: claim what we can.
	for _, child in ipairs(thrown:GetChildren()) do
		claimIfOurs(child)
	end

	return true
end

-- Public API
function WispVisualizer.start()
	if running then
		return
	end
	running = true

	buildWindow()
	ownedWisps = {}
	refreshStatuses()

	if not bindThrown() then
		-- Thrown doesn't exist yet (or got replaced): watch for it.
		thrownWatchConn = workspace.ChildAdded:Connect(function(child)
			if running and child.Name == "Thrown" then
				bindThrown()
			end
		end)
	end

	updateConn = RunService.RenderStepped:Connect(function(dt)
		if not running then
			return
		end
		updateAccum = updateAccum + dt
		if updateAccum < 0.2 then
			return
		end
		updateAccum = 0
		-- Wisps usually just get destroyed rather than reparented, so poll for expiry instead of relying on ChildRemoved alone.
		refreshStatuses()
	end)
end

function WispVisualizer.stop()
	if not running then
		return
	end
	running = false

	for _, conn in ipairs(thrownConns) do
		pcall(function() conn:Disconnect() end)
	end
	thrownConns = {}

	if thrownWatchConn then
		pcall(function() thrownWatchConn:Disconnect() end)
		thrownWatchConn = nil
	end
	if updateConn then
		pcall(function() updateConn:Disconnect() end)
		updateConn = nil
	end

	ownedWisps = {}
	rows = {}

	if screenGui then
		screenGui:Destroy()
		screenGui = nil
		mainFrame = nil
	end
end

function WispVisualizer.detach()
	WispVisualizer.stop()
end

return WispVisualizer
end)()
end)
__bundle_register("Features/Visuals/Objects/BuilderData", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
---@module Features.Visuals.Objects.DeepwokenData
local DeepwokenData = require("Features/Visuals/Objects/DeepwokenData")

---@module Features.Visuals.Objects.AttributeData
local AttributeData = require("Features/Visuals/Objects/AttributeData")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@class BuilderData
---@field ddata DeepwokenData
---@field talents string[]
---@field mantras string[]
---@field pre AttributeData
---@field post AttributeData
---@field traits table<string, number>
local BuilderData = {}
BuilderData.__index = BuilderData

---Fetch attributes based on data replicated info.
---@param drinfo table
---@return AttributeData
function BuilderData:attributes(drinfo)
	return (self:ipre(drinfo) == 0) and self.pre or self.post
end

--- Calculate whether or not we are in the pre-shrine state.
---@param drinfo table
---@return number
function BuilderData:ipre(drinfo)
	local currentInvestedPoints = 0

	for idx, value in next, drinfo do
		if typeof(idx) ~= "string" or not idx:match("Stat") then
			continue
		end

		if typeof(value) ~= "number" then
			continue
		end

		currentInvestedPoints = currentInvestedPoints + value
	end

	local pointsToGetToShrine = self.pre:points()
	local shrineOverrideState = Configuration.expectOptionValue("ShrineOverrideState")

	if not Configuration.expectToggleValue("ShrineDetectionOverride") then
		shrineOverrideState = nil
	end

	if shrineOverrideState == "Pre-Shrine" then
		return 0
	end

	if shrineOverrideState == "Post-Shrine" then
		return 1
	end

	if shrineOverrideState == "Must Shrine" then
		return 2
	end

	if not self:dshrine() then
		return 1
	end

	if currentInvestedPoints < pointsToGetToShrine then
		return 0
	end

	if currentInvestedPoints == pointsToGetToShrine then
		return 2
	end

	return 1
end

---Did the builder data even shrine of order at all?
---@note: No specific tag, but if they did not shrine of order, then post and pre are the same.
---@return boolean
function BuilderData:dshrine()
	return not self.pre:compare(self.post)
end

---Load from partial values.
---@param values table
function BuilderData:load(values)
	if typeof(values.talents) == "table" then
		self.talents = values.talents
	end

	if typeof(values.mantras) == "table" then
		self.mantras = values.mantras
	end

	-- Replace mapping(s) if they have tags to ones without brackets.
	for idx, talent in next, self.talents do
		local cleaned = talent:gsub("%s*%[.-%]$", "")

		if cleaned ~= talent then
			self.talents[idx] = cleaned
		end
	end

	for idx, mantra in next, self.mantras do
		local cleaned = mantra:gsub("%s*%[.-%]$", "")

		if cleaned ~= mantra then
			self.mantras[idx] = cleaned
		end
	end

	if typeof(values.preShrine) == "table" then
		self.pre:load(values.preShrine)
	end

	if typeof(values.attributes) == "table" then
		self.post:load(values.attributes)
	end

	local stats = values.stats

	if typeof(stats) ~= "table" then
		return
	end

	local traits = stats.traits

	if typeof(traits) ~= "table" then
		return
	end

	self.traits["Vitality"] = traits["Vitality"] or 0
	self.traits["Erudition"] = traits["Erudition"] or 0
	self.traits["Proficiency"] = traits["Proficiency"] or 0
	self.traits["Songchant"] = traits["Songchant"] or 0
end

---Create new BuilderData object.
---@param bvalues table?
---@param dvalues table?
---@return BuilderData
function BuilderData.new(bvalues, dvalues)
	local self = setmetatable({}, BuilderData)

	self.ddata = DeepwokenData.new(dvalues)
	self.talents = {}
	self.mantras = {}
	self.pre = AttributeData.new()
	self.post = AttributeData.new()
	self.traits = {
		["Vitality"] = 0,
		["Erudition"] = 0,
		["Proficiency"] = 0,
		["Songchant"] = 0,
	}

	if bvalues then
		self:load(bvalues)
	end

	return self
end

-- Return BuilderData module.
return BuilderData
end)()
end)
__bundle_register("Features/Visuals/Objects/AttributeData", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
---@class AttributeData
---@field weapon table<string, number>
---@field attunement table<string, number>
---@field base table<string, number>
local AttributeData = {}
AttributeData.__index = AttributeData

---Is it possible to meet the requirements for a specific talent or mantra?
---@note: Expects the data to be formatted correctly from DeepwokenData
---@param reqs table
---@return boolean
function AttributeData:possible(reqs)
	local mind = math.max(self.base["Intelligence"], self.base["Willpower"], self.base["Charisma"])
	local body = math.max(self.base["Strength"], self.base["Fortitude"], self.base["Agility"])

	for idx, value in pairs(reqs) do
		if self.weapon[idx] and self.weapon[idx] < value then
			return false
		end

		if self.attunement[idx] and self.attunement[idx] < value then
			return false
		end

		if self.base[idx] and self.base[idx] < value then
			return false
		end

		if idx == "Mind" and mind < value then
			return false
		end

		if idx == "Body" and body < value then
			return false
		end
	end

	return true
end

---Tally up attribute points.
---@return number
function AttributeData:points()
	local points = 0

	for _, value in pairs(self.weapon) do
		points = points + value
	end

	for _, value in pairs(self.attunement) do
		points = points + value
	end

	for _, value in pairs(self.base) do
		points = points + value
	end

	return points
end

---Compare to another AttributeData object.
---@param other AttributeData
function AttributeData:compare(other)
	for idx, value in pairs(self.weapon) do
		if other.weapon[idx] == value then
			continue
		end

		return false
	end

	for idx, value in pairs(self.attunement) do
		if other.attunement[idx] == value then
			continue
		end

		return false
	end

	for idx, value in pairs(self.base) do
		if other.base[idx] == value then
			continue
		end

		return false
	end

	return true
end

---Load from partial values.
---@param values table
function AttributeData:load(values)
	if typeof(values.weapon) == "table" then
		self.weapon = values.weapon
	end

	if typeof(values.attunement) == "table" then
		self.attunement = values.attunement
	end

	if typeof(values.base) == "table" then
		self.base = values.base
	end
end

---Create new AttributeData object.
---@param values table?
---@return AttributeData
function AttributeData.new(values)
	local self = setmetatable({}, AttributeData)

	self.weapon = {}
	self.attunement = {}
	self.base = {}

	if values then
		self:load(values)
	end

	return self
end

--- Return AttributeData module.
return AttributeData
end)()

end)
__bundle_register("Features/Visuals/Objects/DeepwokenData", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
---@class DeepwokenData
---@field talents table
---@field mantras table
local DeepwokenData = {}
DeepwokenData.__index = DeepwokenData

---Get data for a specific talent or mantra.
---@param name string
function DeepwokenData:get(name)
	return self.talents[string.lower(name)] or self.mantras[string.lower(name)]
end

---Are we able to get a specified talent or mantra with the passed in attribute data?
---@param name string
---@param adata AttributeData
---@return boolean
function DeepwokenData:possible(name, adata)
	local data = self:get(name)
	if not data then
		return false
	end

	local reqs = data.reqs
	if not reqs then
		return false
	end

	---@note: Format this table for clean requirement parsing
	local formatted = {}

	for idx, value in pairs(reqs.base) do
		formatted[idx] = value
	end

	for idx, value in pairs(reqs.weapon) do
		formatted[idx] = value
	end

	for idx, value in pairs(reqs.attunement) do
		formatted[idx] = value
	end

	return adata:possible(formatted)
end

---Load from partial values.
---@param values table
function DeepwokenData:load(values)
	if typeof(values.talents) == "table" then
		self.talents = values.talents
	end

	if typeof(values.mantras) == "table" then
		self.mantras = values.mantras
	end
end

---Create new DeepwokenData object.
---@param values table?
---@return DeepwokenData
function DeepwokenData.new(values)
	local self = setmetatable({}, DeepwokenData)

	self.talents = {}
	self.mantras = {}

	if values then
		self:load(values)
	end

	return self
end

-- Return DeepwokenData module.
return DeepwokenData
end)()

end)
__bundle_register("Menu/AutomationTab", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
-- AutomationTab module.
local AutomationTab = {}

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Features.Automation.EchoFarm
local EchoFarm = require("Features/Automation/EchoFarm")

---@module Features.Automation.JoyFarm
local JoyFarm = require("Features/Automation/JoyFarm")

---@module Features.Automation.TitusFarm
local TitusFarm = require("Features/Automation/TitusFarm")

---@module Features.Automation.AutoBank
local AutoBank = require("Features/Automation/AutoBank")

---@module Game.QueuedBlocking
local QueuedBlocking = require("Game/QueuedBlocking")

---@module Game.KeyHandling
local KeyHandling = require("Game/KeyHandling")

---@module Features.Game.Tweening
local Tweening = require("Features/Game/Tweening")

---Attribute section.
---@param groupbox table
function AutomationTab.initAttributeSection(groupbox)
	groupbox
		:AddToggle("AutoCharisma", {
			Text = "Auto Charisma Farm",
			Default = false,
			Tooltip = "Using the 'How To Make Friends' book, the script will automatically train the 'Charisma' attribute.",
		})
		:AddKeyPicker("AutoCharismaKeybind", {
			Default = "N/A",
			SyncToggleState = true,
			Text = "Auto Charisma Farm",
			HideIfUnbound = true,
		})

	groupbox:AddInput("CharismaCap", {
		Text = "Charisma Cap",
		Tooltip = "When this cap is reached, the farm will stop training the 'Charisma' attribute.",
		Numeric = true,
		MaxLength = 3,
		Default = "75",
	})

	groupbox
		:AddToggle("AutoIntelligence", {
			Text = "Auto Intelligence Farm",
			Tooltip = "Using the 'Math Textbook' book, the script will automatically train the 'Intelligence' attribute.",
			Default = false,
		})
		:AddKeyPicker("AutoIntelligenceKeybind", {
			Default = "N/A",
			SyncToggleState = true,
			Text = "Auto Intelligence",
			HideIfUnbound = true,
		})

	groupbox:AddInput("IntelligenceCap", {
		Text = "Intelligence Cap",
		Tooltip = "When this cap is reached, the farm will stop training the 'Intelligence' attribute.",
		Numeric = true,
		MaxLength = 3,
		Default = "75",
	})

	AutomationTab.initFortitudeFarmSection(groupbox)
end

---Initialize Farming section.
---@param groupbox table
function AutomationTab.initFarmingSection(groupbox)
	AutomationTab.initFishFarmSection(groupbox)
	groupbox:AddDivider()
	AutomationTab.initEffectAutomation(groupbox)
end

---Initialize Fish Farm section.
---@param groupbox table
function AutomationTab.initFishFarmSection(groupbox)
	groupbox
		:AddToggle("AutoFish", {
			Text = "Auto Fish Farm",
			Tooltip = "Automatically farm fish. Non-AFKable yet. Work-in progress.",
			Default = false,
		})
		:AddKeyPicker("AutoFishKeybind", {
			Default = "N/A",
			SyncToggleState = true,
			Text = "Auto Fish Farm",
			HideIfUnbound = true,
		})
end

---Initialize Fortitude Farm section.
---@param groupbox table
function AutomationTab.initFortitudeFarmSection(groupbox)
	groupbox
		:AddToggle("AutoFortitude", {
			Text = "Auto Fortitude Farm",
			Tooltip = "Repeatedly interacts with Brutus's training prompt while you're in range, to passively train the 'Fortitude' attribute.",
			Default = false,
		})
		:AddKeyPicker("AutoFortitudeKeybind", {
			Default = "N/A",
			SyncToggleState = true,
			Text = "Auto Fortitude Farm",
			HideIfUnbound = true,
		})
end

---Initialize Auto Loot section.
---@param groupbox table
function AutomationTab.initAutoLootSection(groupbox)
	groupbox
		:AddToggle("AutoLoot", {
			Text = "Auto Loot",
			Tooltip = "Automatically loot items from choice prompts with filtering options.",
			Default = false,
		})
		:AddKeyPicker("AutoLootKeybind", {
			Default = "N/A",
			SyncToggleState = true,
			Text = "Auto Loot",
			HideIfUnbound = true,
		})

	local autoLootDepBox = groupbox:AddDependencyBox()

	autoLootDepBox:AddToggle("AutoLootAll", {
		Text = "Loot All Items",
		Tooltip = "Loot all items from choice prompts. This will ignore filtering options.",
		Default = false,
	})

	local autoLootAllDepBox = autoLootDepBox:AddDependencyBox()

	autoLootAllDepBox:AddSlider("AutoLootStarsMin", {
		Text = "Minimum Stars",
		Tooltip = "The minimum number of stars an item must have to be looted.",
		Min = 0,
		Max = 3,
		Rounding = 0,
		Suffix = "[*]",
		Default = 0,
	})

	autoLootAllDepBox:AddSlider("AutoLootStarsMax", {
		Text = "Maximum Stars",
		Tooltip = "The maximum number of stars an item can have to be looted.",
		Min = 0,
		Max = 3,
		Rounding = 0,
		Suffix = "[*]",
		Default = 0,
	})

	local itemNameList = autoLootAllDepBox:AddDropdown("ItemNameList", {
		Text = "Item Name List",
		Values = {},
		SaveValues = true,
		Multi = true,
		AllowNull = true,
	})

	local itemNameInput = autoLootAllDepBox:AddInput("ItemNameInput", {
		Text = "Item Name Input",
		Placeholder = "Exact or partial names.",
	})

	autoLootAllDepBox:AddButton("Add Item Name To Filter", function()
		local itemName = itemNameInput.Value
		if #itemName <= 0 then
			return Logger.longNotify("Please enter a valid item name.")
		end

		local values = itemNameList.Values
		if not table.find(values, itemName) then
			table.insert(values, itemName)
		end

		itemNameList:SetValues(values)
		itemNameList:SetValue({})
		itemNameList:Display()
	end)

	autoLootAllDepBox:AddButton("Remove Selected Item Names", function()
		local values = itemNameList.Values
		local value = itemNameList.Value

		for selected, _ in next, value do
			local index = table.find(values, selected)
			if not index then
				continue
			end

			table.remove(values, index)
		end

		itemNameList:SetValues(values)
		itemNameList:SetValue({})
		itemNameList:Display()
	end)

	autoLootAllDepBox:SetupDependencies({
		{ Toggles.AutoLootAll, false },
	})

	autoLootDepBox:SetupDependencies({
		{ Toggles.AutoLoot, true },
	})
end

---Initialize Joy Farm section.
---@param groupbox table
function AutomationTab.initJoyFarmSection(groupbox)
	groupbox:AddButton({
		Text = "Start Joy Farm",
		Tooltip = "Make sure that you are at the start of a cycle.",
		Func = JoyFarm.start,
	})

	groupbox:AddButton("Stop Joy Farm", JoyFarm.stop)
end

---Initialize Titus Farm section.
---@param groupbox table
function AutomationTab.initTitusFarmSection(groupbox)
	groupbox:AddButton({
		Text = "Start Titus Farm",
		Tooltip = "voids titus automatically using pathfinderbreaker",
		Func = TitusFarm.start,
	})

	groupbox:AddButton("Stop Titus Farm", TitusFarm.stop)

	groupbox:AddToggle("AutoTitusServerHop", {
		Text = "Auto Server Hop",
		Tooltip = "On: hop to a fresh server after every Titus and repeat the farm forever. Off: do one run and stop instead of hopping (also stops rather than hopping when a player wanders in or voiding times out).",
		Default = true,
	})

	groupbox:AddToggle("AutoTitusBank", {
		Text = "Auto Bank",
		Tooltip = "Automatically banks your relics when autofarm hits 25",
		Default = false,
	})

	local bankDepBox = groupbox:AddDependencyBox()

	bankDepBox:AddDropdown("AutoTitusBankItems", {
		Text = "Bank Items",
		Tooltip = "Which item types to deposit when auto banking. Tick the ones you want, same as the slide-cast mantras list.",
		Values = { "Armorer's Needle", "Smith's Alloy", "Idol of Yun Shul", "Moonseyes" },
		Default = { "Moonseyes" },
		Multi = true,
		AllowNull = true,
		SaveValues = true,
	})

	bankDepBox:SetupDependencies({
		{ Toggles.AutoTitusBank, true },
	})


end

---Initialize Auto Bank section.
---@param groupbox table
function AutomationTab.initAutoBankSection(groupbox)
	groupbox:AddButton({
		Text = "Start Auto Bank",
		Tooltip = "Tweens to Fort Merit's bank, high in the air then down onto it, talks to the teller, and deposits every 'Moonseye' item in your backpack.",
		Func = AutoBank.start,
	})

	groupbox:AddButton("Stop Auto Bank", AutoBank.stop)
end

---Initialize Effect Automation section.
---@param groupbox table
function AutomationTab.initEffectAutomation(groupbox)
	groupbox:AddToggle("AutoExtinguishFire", {
		Text = "Auto Extinguish Fire",
		Tooltip = "Attempt to remove 'Burning' effects through automatic sliding.",
		Default = false,
	})
end

---Initialize Utility section.
---@param groupbox table
function AutomationTab.initUtilitySection(groupbox)
	AutomationTab.initAutoLootSection(groupbox)

	groupbox:AddDivider()
	AutomationTab.initJoyFarmSection(groupbox)
	groupbox:AddDivider()
	AutomationTab.initTitusFarmSection(groupbox)
	
end

---Initialize tab.
---@param window table
function AutomationTab.init(window)
	-- Create tab.
	local tab = window:AddTab("Auto")

	-- Initialize sections.
	AutomationTab.initFarmingSection(tab:AddLeftGroupbox("Misc"))
	AutomationTab.initAttributeSection(tab:AddLeftGroupbox("Attributes"))
	AutomationTab.initUtilitySection(tab:AddRightGroupbox("Utility"))

	if not LRM_UserNote then
		AutomationTab.initDebuggingSection(tab:AddRightGroupbox("Debugging"))
	end
end

---Initialize Debugging section.
---@param groupbox table
function AutomationTab.initDebuggingSection(groupbox)
	groupbox:AddButton("Start Echo Farm", EchoFarm.invoke)
	groupbox:AddButton("Stop Echo Farm", EchoFarm.stop)

	groupbox:AddButton("Start Titus Farm", TitusFarm.start)
	groupbox:AddButton("Stop Titus Farm", TitusFarm.stop)

	groupbox:AddButton("Start Deflect", function()
		QueuedBlocking.invoke(QueuedBlocking.BLOCK_TYPE_DEFLECT, "StartDeflect", nil)
	end)

	groupbox:AddButton("Start Deflect 0.1s", function()
		QueuedBlocking.invoke(QueuedBlocking.BLOCK_TYPE_DEFLECT, "StartDeflect", 0.1)
	end)

	groupbox:AddButton("Start Block 0.3s", function()
		QueuedBlocking.invoke(QueuedBlocking.BLOCK_TYPE_NORMAL, "StartBlock", 0.3)
	end)

	groupbox:AddButton("Start Block", function()
		QueuedBlocking.invoke(QueuedBlocking.BLOCK_TYPE_NORMAL, "StartBlock", nil)
	end)

	groupbox:AddButton("Stop All Block", function()
		QueuedBlocking.empty()
	end)

	groupbox:AddButton("Raw Start Block", function()
		local blockRemote = KeyHandling.getRemote("Block")
		if not blockRemote then
			return
		end

		blockRemote:FireServer()
	end)

	groupbox:AddButton("Raw Stop Block", function()
		local unblockRemote = KeyHandling.getRemote("Unblock")
		if not unblockRemote then
			return
		end

		unblockRemote:FireServer()
	end)

	groupbox:AddButton("Test Tween", function()
		local positions = {
			CFrame.new(2414.70, 442.28, -5595.58),
			CFrame.new(2424.78, 408.30, -5501.38),
			CFrame.new(2429.86, 408.30, -5495.80),
			CFrame.new(2507.99, 414.60, -5560.85),
			CFrame.new(600.33, 983.29, -7643.66),
			CFrame.new(669.22, 979.31, -7668.61),
			CFrame.new(2960.38, 404.16, -5604.14),
		}

		for idx, position in next, positions do
			Tweening.goal(string.format("TweenToTest_%i", idx), position, true)
		end
	end)

	groupbox:AddButton("Cancel Tween", function()
		for idx = 1, 7 do
			Tweening.stop(string.format("TweenToTest_%i", idx))
		end
	end)
end

-- Return AutomationTab module.
return AutomationTab
end)()
end)
