---Info spoofing section.
---@param groupbox table
function GameTab.initInfoSpoofingSection(groupbox)
	local hasEverBeenEnabled = true

	groupbox:AddToggle("InfoSpoofing", {
		Text = "Enable Info Spoofing",
		Default = false,
		Callback = function(value)
			-- Only refresh if we've ever enabled this feature or we're currently enabling it.
			if value or hasEverBeenEnabled then
				Spoofing.rics()
			end

			-- We don't need to mark if we're disabling it.
			if not value then
				return
			end

			-- Spoof UI.
			Spoofing.sss(Configuration.expectOptionValue("SpoofedSlotString"))
			Spoofing.sds(Configuration.expectOptionValue("SpoofedDateString"))
			Spoofing.sgv(Configuration.expectOptionValue("SpoofedGameVersion"))

			-- Mark that we've enabled this atleast once...
			hasEverBeenEnabled = true
		end,
	})

	local isDepBox = groupbox:AddDependencyBox()

	isDepBox:AddToggle("SpoofOtherPlayers", {
		Text = "Spoof Other Players",
		Default = false,
		Callback = Spoofing.rics,
	})

	isDepBox:AddToggle("HideDeathInformation", {
		Text = "Hide Death Information",
		Default = false,
	})

	isDepBox:AddInput("SpoofedSlotString", {
		Text = "Spoofed Slot String",
		Default = "1234567890:Z|1 [Lv. 1]",
		Finished = true,
		Callback = Spoofing.sss,
	})

	isDepBox:AddInput("SpoofedDateString", {
		Text = "Spoofed Date String",
		Default = "mira, 2025 CE",
		Finished = true,
		Callback = Spoofing.sds,
	})

	isDepBox:AddInput("SpoofedGameVersion", {
		Text = "Spoofed Game Version",
		Default = "pv_JAN_01_00:00z",
		Finished = true,
		Callback = Spoofing.sgv,
	})

	local function refreshHandler()
		if not Configuration.expectToggleValue("InfoSpoofing") then
			return
		end

		Spoofing.rics()
	end

	isDepBox:AddInput("SpoofedFirstName", {
		Text = "Spoofed First Name",
		Default = "Mira",
		Finished = true,
		Callback = refreshHandler,
	})

	isDepBox:AddInput("SpoofedLastName", {
		Text = "Spoofed Last Name",
		Default = "#1",
		Finished = true,
		Callback = refreshHandler,
	})

	isDepBox:AddInput("SpoofedGuildName", {
		Text = "Spoofed Guild Name",
		Default = "discord.gg/miradw",
		Finished = true,
		Callback = refreshHandler,
	})

	isDepBox:AddInput("SpoofedServerName", {
		Text = "Spoofed Server Name",
		Default = "???",
		Finished = true,
		Callback = refreshHandler,
	})

	isDepBox:AddInput("SpoofedServerRegion", {
		Text = "Spoofed Server Region",
		Default = "discord.gg/miradw",
		Finished = true,
		Callback = refreshHandler,
	})

	isDepBox:AddInput("SpoofedServerAge", {
		Text = "Spoofed Server Age",
		Default = "???",
		Finished = true,
		Callback = refreshHandler,
	})

	isDepBox:SetupDependencies({
		{ Toggles.InfoSpoofing, true },
	})
end

---Tweening section.
---@param groupbox table
function GameTab.initTweeningSection(groupbox)
	groupbox:AddSlider("TweenStudsPerSecond", {
		Text = "Tween Speed",
		Default = 120,
		Min = 50,
		Max = 450,
		Suffix = "/s",
		Rounding = 0,
	})
end

---Initialize tab.
function GameTab.init(window)
	-- Create tab.
	local tab = window:AddTab("Game")

	pcall(function()
		GameTab.initLocalCharacterSection(tab:AddLeftGroupbox("Local Character"))
	end)
	pcall(function()
		GameTab.initInstanceRemovalsSection(tab:AddLeftGroupbox("Instance Removals"))
	end)

	pcall(function()
		GameTab.initPlayerMonitoringSection(tab:AddRightGroupbox("Player Monitoring"))
	end)
	pcall(function()
		GameTab.initTweeningSection(tab:AddRightGroupbox("Movement"))
	end)
	pcall(function()
		GameTab.initEffectRemovalsSection(tab:AddRightGroupbox("Effect Removals"))
	end)

	pcall(function()
		local spoofingGroup = tab:AddRightGroupbox("Spoofing")
		GameTab.initInfoSpoofingSection(spoofingGroup)
		GameTab.initDebuggingSection(spoofingGroup)
	end)
end

-- Return GameTab module.
return GameTab
end)()

end)
__bundle_register("Features/Game/FakeVoid", function(require, _LOADED, __bundle_register, __bundle_modules)
-- FakeVoid module.
local FakeVoid = {}

---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Utility.Signal
local Signal = require("Utility/Signal")

---@module Utility.Logger
local Logger = require("Utility/Logger")

-- Services.
local players = game:GetService("Players")
local runService = game:GetService("RunService")
local localPlayer = players.LocalPlayer

-- Constants.
local DEPTHS_PLACE_ID = 5735553160        -- the Depths is its own place
local VOID_Y = -2863                       -- fall past this Y and we've "hit the void"
local ROOF_Y = -831.408935546875           -- teleport back up to the Depths roof

-- State.
local maid = Maid.new()
local enabled = false
-- Whether No Kill Bricks was already on BEFORE Fake Void forced it -- so disabling Fake Void only turns No Kill Bricks off if we were the ones who turned it on.
local killBricksWasOn = false

---Force No Kill Bricks on -- Fake Void requires it, 100% of the time.
local function forceNoKillBricks()
	if Toggles and Toggles.NoKillBricks and Toggles.NoKillBricks.Value ~= true then
		pcall(function()
			Toggles.NoKillBricks:SetValue(true)
		end)
	end
end

---Per-frame: keep No Kill Bricks on, and catch the void.
local function onStep()
	if not enabled then
		return
	end

	forceNoKillBricks()

	-- Only in the Depths.
	if game.PlaceId ~= DEPTHS_PLACE_ID then
		return
	end

	local character = localPlayer.Character
	local root = character and character:FindFirstChild("HumanoidRootPart")
	if not root then
		return
	end

	-- Hit the void -> yank back up to the roof, keeping our facing, and kill the fall so we don't immediately drop back through.
	if root.Position.Y <= VOID_Y then
		local position = root.Position
		pcall(function()
			root.CFrame = CFrame.new(position.X, ROOF_Y, position.Z) * (root.CFrame - root.CFrame.Position)
			root.AssemblyLinearVelocity = Vector3.zero
		end)
	end
end

---Initialize (called when the toggle turns on).
function FakeVoid.init()
	if enabled then
		return
	end
	enabled = true
	-- Snapshot No Kill Bricks BEFORE we force it, so detach knows whether to restore it.
	killBricksWasOn = (Toggles and Toggles.NoKillBricks and Toggles.NoKillBricks.Value == true) or false
	forceNoKillBricks()

	local renderStepped = Signal.new(runService.RenderStepped)
	maid:mark(renderStepped:connect("FakeVoid_OnStep", onStep))

	Logger.warn("Fake Void started.")
end

---Detach (called when the toggle turns off).
function FakeVoid.detach()
	if not enabled then
		return
	end
	enabled = false
	maid:clean()
	-- Turn No Kill Bricks off only if Fake Void was the one that enabled it (it wasn't on beforehand).
	if not killBricksWasOn and Toggles and Toggles.NoKillBricks and Toggles.NoKillBricks.Value == true then
		pcall(function()
			Toggles.NoKillBricks:SetValue(false)
		end)
	end
	Logger.warn("Fake Void stopped.")
end

-- Return FakeVoid module.
return FakeVoid
end)
