	local afDepBox = groupbox:AddDependencyBox()

	afDepBox:AddDropdown("AutoFeintType", {
		Text = "Auto Feint Type",
		Values = {
			"Passive",
			"Aggressive",
		},
		Default = 1,
	})

	afDepBox:AddDropdown("AutoFeintFilter", {
		Text = "Auto Feint Filter",
		Values = {
			"M1s",
			"Mantras",
			"All",
		},
		Default = 1,
	})

	afDepBox:SetupDependencies({
