---Initialize AP Breaker section.
---@param groupbox table
function CombatTab.initAPBreakerSection(groupbox)
	local ExpApBreaker = require("Features/Combat/ExpApBreaker")

	local apBreakerToggle = groupbox:AddToggle("ExpApBreaker", {
		Text = "AP Breaker",
		Default = false,
		Tooltip = "breaks other autoparrys. you need to attack for it to work.",
	})
	apBreakerToggle:OnChanged(function(state)
		if not ExpApBreaker then return end
		if state then ExpApBreaker:Start() else ExpApBreaker:Stop() end
	end)
	apBreakerToggle:AddKeyPicker("APBreakerKeybind", { Default = "N/A", SyncToggleState = true, Text = "AP Breaker" })

	local apbDepBox = groupbox:AddDependencyBox()

	apbDepBox:AddDropdown("ExpApBreakerModes", {
		Text = "Breakers",
		Values = {
			"Priority Mask",
			"Fade Time Spoof",
			"Fade Time Flood",
			"Mutate",
			"Monster Flood",
		},
		Default = {},
		Multi = true,
		AllowNull = true,
		Tooltip = "Which breakers to run. Select more than one to stack them.",
		Callback = function() if ExpApBreaker then ExpApBreaker.refresh() end end,
	})

	apbDepBox:AddDropdown("ExpApBreakerMoveTypes", {
		Text = "Break On",
		Values = { "M1", "Critical", "Mantra" },
		Default = {},
		Multi = true,
		AllowNull = true,
		Tooltip = "Which of your move types to break on. None selected = all.",
	})

	-- NOTE: Replay Delay / Replay Fade (Fade Time Flood) are hard-coded to their old defaults in Features/Combat/ExpApBreaker.lua.
	apbDepBox:AddSlider("ExpApBreakerAggressive2Intensity", {
		Text = "Flood Intensity",
		Default = 200, Min = 1, Max = 200, Rounding = 0,
		Tooltip = "animations played per second for the flood breakers. higher = more aggressive.",
	})
	apbDepBox:AddToggle("ExpApBreakerMaskVisual", {
		Text = "Mask Visual",
		Default = true,
		Tooltip = "covers the flood with copies of your real animations. off = more obvious.",
	})
	apbDepBox:AddToggle("ApBreakerDontHitAnimLimit", {
		Text = "Don't hit animation limit",
		Default = true,
		Tooltip = "stops adding animations once 60+ are playing, so you don't hit the animation limit.",
	})

	apbDepBox:SetupDependencies({ { apBreakerToggle, true } })
end

function CombatTab.initAntiAPBreakerSection(groupbox)
	local antiAPToggle = groupbox:AddToggle("AntiAPBreakerEnabled", {
		Text = "Anti-AP Breaker",
		Default = true,
		Tooltip = "if enabled auto defense will attempt to ignore all ap breaking attemps (this may mess with timings and cause it to miss parrys)",
	})
	antiAPToggle:AddKeyPicker("AntiAPBreakerKeybind", { Default = "N/A", SyncToggleState = true, Text = "Anti-AP Breaker" })

	-- Independent of Anti-AP Breaker: detection for this is a lightweight passive check that runs whether or not Anti-AP Breaker itself is on, so you still get notified even with Anti-AP Breaker off.
	local apBreakNotifyToggle = groupbox:AddToggle("AntiAPBreakerNotify", {
		Text = "AP Break Notifications",
		Default = false,
		Tooltip = "get a notification when someone trys to ap break you. works even if anti-ap breaker is off.",
	})

	-- Reject Reason Notifications only makes sense alongside AP Break Notifications, so it lives in a dependency box gated on that toggle.
	local rejectReasonDepBox = groupbox:AddDependencyBox()

	rejectReasonDepBox:AddToggle("AntiAPBreakerRejectReasonNotify", {
		Text = "Reject Reason Notifications",
		Default = false,
		Tooltip = "tells u what the animations was rejected for",
	})

	rejectReasonDepBox:SetupDependencies({
		{ apBreakNotifyToggle, true },
	})

	local antiAPDepBox = groupbox:AddDependencyBox()

	-- Pick which checks run.
	local apbChecks = antiAPDepBox:AddDropdown("AntiAPBreakerChecks", {
		Text = "Checks",
		Values = {
			"Priority Spoof",

			"Weight Target",
			"Weight Ramp",
			"Speed",
			"Time",
			"Animation Stop",
			"Post-Check Ramp",
			"Churn",
			"Ghost Track",
			"Masked Track",
		},
		-- "Time" ships ON: the judge measures the actual weight ramp across its two samples instead of pattern-matching a magic fade value, so it no longer false-positives on legit slow fades.
		Default = {
			"Priority Spoof",
			"Weight Target",
			"Weight Ramp",
			"Speed",
			"Time",
			"Animation Stop",
			"Post-Check Ramp",
			"Churn",
			"Ghost Track",
			"Masked Track",
		},
		Multi = true,
		AllowNull = true,
		Tooltip = "what checks the anti ap breaker does",
		Callback = function()
			Library:UpdateDependencyBoxes()
		end,
	})

	-- Judge sample timings: affect every weight/speed reading, so they stay visible whenever Anti-AP Breaker is on.
	antiAPDepBox:AddSlider("ApbSample1Delay", {
		Text = "First Sample Delay",
		Tooltip = "how long after a swing starts the judge takes its first reading. higher = more reliable reads but more parry latency.",
		Default = 0.03, Min = 0, Max = 0.2, Suffix = "s", Rounding = 3,
	})
	antiAPDepBox:AddSlider("ApbSample2Delay", {
		Text = "Second Sample Delay",
		Tooltip = "extra wait before the judge's second reading for inconclusive tracks.",
		Default = 0.06, Min = 0, Max = 0.3, Suffix = "s", Rounding = 3,
	})


	antiAPDepBox:SetupDependencies({ { antiAPToggle, true } })

	-- Per-check slider groups.
	local function apbCheckBox(checkName)
		local box = groupbox:AddDependencyBox()
