---Initialize tab.
---@param window table
function CombatTab.init(window)
	-- Create tab.
	local tab = window:AddTab("Combat")

	-- LEFT: Main / Anti Exploit / Settings subtabs 
	local leftTabbox = tab:AddLeftTabbox("")
	local mainTab = leftTabbox:AddTab("Main")
	local antiExploitTab = leftTabbox:AddTab("Anti Exploit")
	local settingsTab = leftTabbox:AddTab("Settings")

	-- MAIN: Auto Defense + Timings/Probabilities
	pcall(function() CombatTab.initAutoDefenseSection(mainTab) end)
	-- Timings (Timing Override List / Timing List / override buttons) now live under the Whitelisting section in the right column — see below.

	-- ANTI EXPLOIT: AP Breaker + Anti-AP Breaker
	pcall(function() CombatTab.initAPBreakerSection(antiExploitTab) end)
	pcall(function() CombatTab.initAntiAPBreakerSection(antiExploitTab) end)

	-- SETTINGS: Notifications, Visualizations, Hitboxes, Failure Settings, Debugging
	pcall(function()
		local settingsGroupbox = settingsTab

		-- Notifications
		settingsGroupbox:AddToggle("EnableNotifications", {
			Text = "Enable Notifications",
			Default = false,
		})

		-- Visualizations
		settingsGroupbox:AddToggle("EnableVisualizations", {
			Text = "View Hitboxes",
			Default = false,
			Callback = Defense.visualizations,
		})


		-- Failure settings
		CombatTab.initBlockInputSection(settingsGroupbox)
	end)
	if not LRM_UserNote then
		pcall(function() CombatTab.initDebuggingSection(settingsTab) end)
	end

	-- RIGHT: Ap Assistance / Generic Buff 
	local rightTabbox = tab:AddRightTabbox("")
	local apAssistTab = rightTabbox:AddTab("Ap Assistance")
	local genericBuffTab = rightTabbox:AddTab("Generic Buff")

	pcall(function() CombatTab.initAttackAssistanceSection(apAssistTab) end)
	pcall(function() CombatTab.initCombatAssistance(genericBuffTab) end)

	-- RIGHT: Whitelisting / Targeting 
	local wlTabbox = tab:AddRightTabbox("")
	local wlTab = wlTabbox:AddTab("Whitelisting")
	local targetingTab = wlTabbox:AddTab("Targeting")
	local silentAimTab = wlTabbox:AddTab("Silent Aim")

	pcall(function() CombatTab.initCombatWhitelistSection(wlTab) end)
	pcall(function()
		wlTab:AddDivider()
		CombatTab:initTimingsSection(wlTab)
	end)
	pcall(function() CombatTab.initCombatTargetingSection(targetingTab) end)
	pcall(function() CombatTab.initSilentAimSection(silentAimTab) end)
end

