__bundle_register("Features/Combat/ExpApBreaker", function(require, _LOADED, __bundle_register, __bundle_modules)
local Require = require

local Maid = Require("Utility/Maid")
local Signal = Require("Utility/Signal")
local Configuration = Require("Utility/Configuration")
local Logger = Require("Utility/Logger")
local OriginalStoreManager = Require("Utility/OriginalStoreManager")
local TimingStore = Require("Game/Timings/SaveManager")

local RunService = game:GetService("RunService")
local Players = game:GetService("Players")
local CollectionService = game:GetService("CollectionService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

-- ============================================================================
-- Hard-coded AP Breaker tuning (was: sliders in the Experimental AP Breaker
-- section). Only "Aggressive 2 Intensity" remains a live, user-facing slider; every
-- other knob below is fixed to what used to be its slider default.
-- ============================================================================
local PASSIVE_REPLAY_DELAY = 0.13      -- was "Replay Delay (Passive)"
local PASSIVE_REPLAY_FADE = 0.05       -- was "Replay Fade (Passive)"

-- Flood-timing jitter (Aggressive 2 / Aggressive 3). The flood used to fire off a
-- FIXED gap (1/Intensity), which forms a periodic emission grid the Anti-AP Breaker's
-- Aggressive-2 sieve fingerprints decoys by. Each gap is now multiplied by a random
-- value in [MIN, MAX]; the mean is 1.0 so the average rate still equals Intensity,
-- but no steady period exists for the grid check to lock onto.
local FLOOD_JITTER_MIN = 0.4
local FLOOD_JITTER_MAX = 1.6

-- ============================================================================
-- Animation priority helper
-- Boosts a priority a fixed number of steps up the priority ladder, clamped
-- to the [Action3, Action4] band, so floods/replays always outrank whatever
-- priority the original animation was using.
-- ============================================================================
local PRIORITY_ORDER = {
	Enum.AnimationPriority.Core,
	Enum.AnimationPriority.Idle,
	Enum.AnimationPriority.Movement,
	Enum.AnimationPriority.Action,
	Enum.AnimationPriority.Action2,
	Enum.AnimationPriority.Action3,
	Enum.AnimationPriority.Action4,
}
local PRIORITY_INDEX = {}
for index, priority in ipairs(PRIORITY_ORDER) do
	PRIORITY_INDEX[priority] = index
end
local ACTION_INDEX = PRIORITY_INDEX[Enum.AnimationPriority.Action]
local BOOST_OFFSET = PRIORITY_INDEX[Enum.AnimationPriority.Action4] - PRIORITY_INDEX[Enum.AnimationPriority.Action]
local ACTION3_INDEX = PRIORITY_INDEX[Enum.AnimationPriority.Action3]
local ACTION4_INDEX = PRIORITY_INDEX[Enum.AnimationPriority.Action4]

local function boostPriority(priority)
	local index = PRIORITY_INDEX[priority] or ACTION4_INDEX
	return PRIORITY_ORDER[math.clamp(index + BOOST_OFFSET, ACTION3_INDEX, ACTION4_INDEX)]
end

-- ============================================================================
-- Module state
-- ============================================================================
local renderSteppedSignal = Signal.new(RunService.RenderStepped)
local maid = Maid.new()
local originalStore = maid:mark(OriginalStoreManager.new())
local loadedTrackRegistry = setmetatable({}, { __mode = "k" })
-- Mutate's mutated-id copies. These stand in for YOUR real swing, so unlike the flood/decoy
-- tracks in loadedTrackRegistry, Priority Mask SHOULD boost them up above its flood (else the
-- copy sits at the swing's native priority and gets buried in the flood, invisible).
local mutateCopies = setmetatable({}, { __mode = "k" })

local ApBreaker = { force = false }

local freestylersBandActive = false
local kongaClutchRingActive = false
local lastUpdateTime = os.clock()

local apBreakerActive = false
-- modeName -> cleanup fn. Multiple breaker modes can run at once (the Modes multi-dropdown
-- picks any subset), so cleanups are held per-mode rather than as a single value.
local apBreakerCleanups = {}
local apBreakerCharacterAddedConn = nil
-- Bumped every time the running mode set changes. Starting/stopping a mode resets the
-- character's animation state (the boosted idle cover is lost), so Priority Mask watches
-- this and re-arms its cover-wait -- it stops flooding until a fresh idle/movement is
-- boosted again, exactly like a fresh start.
local apBreakerModeGeneration = 0

local priorityChangerActive = false
local weightSpoofActive = false
local targetWeightSpoofActive = false
local priorityWeightCharacterAddedConn = nil
local priorityWeightAnimationPlayedConn = nil

local attackDelayActive = false
local attackDelayCharacterAddedConn = nil
local attackDelayCleanup = nil

-- ============================================================================
-- Option helpers
-- ============================================================================
local function getOption(name, fallback)
	local value = Configuration.expectOptionValue(name)
	if value == nil then
		return fallback
	end
	return value
end

-- "Don't hit animation limit" (default on). Roblox silently starts dropping animation
-- tracks once an animator is overloaded -- and the dropped ones can include YOUR real
-- attacks, which defeats the whole point. So when the character already has ANIM_LIMIT+
-- tracks playing, the breaker stops adding more of its own until the count falls back.
local ANIM_LIMIT = 60
local function underAnimationLimit(animator)
	if Configuration.expectToggleValue("ApBreakerDontHitAnimLimit") == false then
		return true
	end
	if not animator then
		return true
	end
	local ok, playing = pcall(function() return animator:GetPlayingAnimationTracks() end)
	if not ok or type(playing) ~= "table" then
		return true
	end
	return #playing < ANIM_LIMIT
end

local cachedEffectReplicator = nil
local function getEffectReplicator()
	if cachedEffectReplicator then
		return cachedEffectReplicator
	end
	local instance = ReplicatedStorage:FindFirstChild("EffectReplicator")
	if instance then
		local ok, module = pcall(Require, instance)
		if ok then
			cachedEffectReplicator = module
		end
	end
	return cachedEffectReplicator
end

local function getCurrentMoveType()
	local effectReplicator = getEffectReplicator()
	if effectReplicator then
		local ok, isCritical = pcall(function()
			return effectReplicator:HasAny("UsingCritical", "Critical")
		end)
		if ok and isCritical then
			return "Critical"
		end
		local ok2, isMantra = pcall(function()
			return effectReplicator:HasAny("CastingSpell", "UsingSpell")
		end)
		if ok2 and isMantra then
			return "Mantra"
		end
	end
	return "M1"
end

-- "None selected = all" per the Break On tooltip. The multi-dropdown defaults to an EMPTY
-- table (not nil), and can also store every entry as false -- both mean "no filter, break
-- on every move type". Only once at least one type is explicitly ticked do we filter to it.
local function anyMoveTypeSelected(selected)
	if type(selected) ~= "table" then
		return false
	end
	for _, on in pairs(selected) do
		if on then
			return true
		end
	end
	return false
end

local function shouldBreakOnMoveType(moveType)
	local selected = Configuration.expectOptionValue("ExpApBreakerMoveTypes")
	if not anyMoveTypeSelected(selected) then
		return true
	end
	return selected[moveType] == true
end

local function shouldAttackDelayMoveType(moveType)
	local selected = Configuration.expectOptionValue("AttackDelayMoveTypes")
	if not anyMoveTypeSelected(selected) then
		return true
	end
	return selected[moveType] == true
end

-- ============================================================================
-- Shared replay handler: used by both Passive AP Breaker mode and the
-- separate Attack Delay feature. Delays a fresh copy of the played track by
-- a fixed amount and replays it faded in.
-- ============================================================================
local function startReplayHandler(character, options)
	if not character then return function() end end
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
	if not animator then return function() end end

	local running = true
	local handledTracks = setmetatable({}, { __mode = "k" })

	local connection = animator.AnimationPlayed:Connect(function(track)
		if not running or handledTracks[track] then return end
		-- Never touch a track another breaker mode is playing (its flood/decoy pool). Those
		-- are known attacks too, so without this a co-running mode's tracks get caught here
		-- and re-played at our short fade -- e.g. Fade Time Flood's 99999-fade baits get
		-- stomped back to full weight, making the whole flood blatant.
		if loadedTrackRegistry[track] then return end
		local animId = tostring(track.Animation.AnimationId)
		if not (TimingStore.as and TimingStore.as:index(animId)) then return end
		if not options.typeSelected(getCurrentMoveType()) then return end

		local length = 0
		pcall(function() length = track.Length end)
		if length <= 0 then length = 0.7 end

		local delay = math.clamp(options.getDelay(), 0, 0.6)
		local fade = math.max(0, options.getFade())

		handledTracks[track] = true
		pcall(function() track:Stop(0) end)
		task.delay(delay, function()
			pcall(function()
				track:Play(fade, 1, 1)
				track.TimePosition = 0
			end)
			task.delay(length + 0.4, function()
				handledTracks[track] = nil
			end)
		end)
	end)

	return function()
		running = false
		if connection then pcall(function() connection:Disconnect() end) end
	end
end

local function startPassiveMode(character)
	-- Hard-coded (was the "Replay Delay (Passive)" / "Replay Fade (Passive)" sliders).
	return startReplayHandler(character, {
		typeSelected = shouldBreakOnMoveType,
		getDelay = function() return PASSIVE_REPLAY_DELAY end,
		getFade = function() return PASSIVE_REPLAY_FADE end,
	})
end

local function startAttackDelayHandler(character)
	-- Separate "Attack Delay" feature -- untouched, still slider-driven.
	return startReplayHandler(character, {
		typeSelected = shouldAttackDelayMoveType,
		getDelay = function() return getOption("AttackDelayTime", 0.13) end,
		getFade = function() return getOption("AttackDelayReplayFade", 0.5) end,
	})
end

-- ============================================================================
-- Aggressive 2 mode: keeps a pool of decoy attack animations cycling at a
-- configurable rate (this is the one slider that stays live), optionally
-- masked behind a disguise loop, and backs off while a real attack track is
-- actually playing so it doesn't stomp your own attacks.
-- ============================================================================
local FALLBACK_AGGRESSIVE2_ANIMATION_IDS = {
	"rbxassetid://9726608174",
	"rbxassetid://111647546998749",
	"rbxassetid://5064195992",
	"rbxassetid://6607519294",
	"rbxassetid://7600160919",
}
local AGGRESSIVE2_MOVE_TYPES = { M1 = true, Mantra = true, Critical = true }
local AGGRESSIVE2_PRIORITY = Enum.AnimationPriority.Action
local PARRY_ACTION_TYPE = "Parry"

-- ============================================================================
-- Module parry probe
--
-- 351 of the 730 animation timings are module-driven (umoa / smod): their Parry
-- action is BUILT AT RUNTIME by a ModuleManager module and never stored, so
-- reading timing.actions finds nothing. The modules don't return a time either --
-- their contract is "given a live AnimatorDefender, call self:action(timing, a)".
--
-- So we impersonate one. A stub with the fields the modules read (entity, track)
-- and a catch-all __index that hands back a no-op for any method we didn't think
-- of, run against a CLONE of the timing because the modules rewrite fields on it
-- in place (ffh, ndfb, pbfb, bfht, htype...) and the real one is shared state.
--
-- Async on purpose: some branches yield until the animation's speed changes
-- (`repeat task.wait() until self.track.Speed ~= ispeed`), which would stall a
-- RenderStepped handler. The probe runs in its own task, the result lands in the
-- cache, and the swing that triggered it falls back to the slider. Every swing
-- after that on the same weapon uses the measurement.
-- ============================================================================
local PROBE_DEADLINE = 0.75
local probeCache = {}
local probeInFlight = {}
local moduleManagerCache = nil
local moduleManagerTried = false

local function getModuleManager()
	if moduleManagerTried then
		return moduleManagerCache
	end
	moduleManagerTried = true
	local ok, manager = pcall(Require, "Game/Timings/ModuleManager")
	if ok then
		moduleManagerCache = manager
	end
	return moduleManagerCache
end

local function moduleNameFor(timing)
	local name = timing and timing.smod
	if type(name) ~= "string" or name == "" or name == "N/A" then
		return nil
	end
	return name
end

-- Speed is an input to the windup maths ((0.171 / self.track.Speed) + 0.120),
-- so it belongs in the key -- rounded, or every micro-variation is a cache miss.
local function probeKey(animationId, moduleName, speed)
	return string.format("%s|%s|%.2f", animationId, moduleName, speed or 1)
end

local function earliestParryFrom(actions)
	local earliest = nil
	for _, action in ipairs(actions) do
		if action._type == PARRY_ACTION_TYPE and type(action.when) == "function" then
			local ok, when = pcall(action.when, action)
			if ok and type(when) == "number" and (earliest == nil or when < earliest) then
				earliest = when
			end
		end
	end
	return earliest
end

local function startModuleProbe(animationId, timing, track, character)
	local moduleName = moduleNameFor(timing)
	if not moduleName then return end

	local manager = getModuleManager()
	local moduleFn = manager and manager.modules and manager.modules[moduleName]
	if type(moduleFn) ~= "function" then return end

	local key = probeKey(animationId, moduleName, track.Speed)
	if probeCache[key] ~= nil or probeInFlight[key] then return end
	probeInFlight[key] = true

	task.spawn(function()
		local captured = {}
		local ok, clone = pcall(function() return timing:clone() end)
		if not ok or not clone then
			clone = timing
		end

		local noop = function() end
		local probe = setmetatable({
			entity = character,
			track = track,
			timing = clone,
			-- The one method whose output we actually want.
			action = function(_, _, actionObject)
				if actionObject then
					captured[#captured + 1] = actionObject
				end
			end,
			pvalidate = function() return true end,
			validate = function() return true end,
			notify = noop,
		}, {
			-- Anything else a module reaches for resolves to a no-op function
			-- rather than erroring the probe out on the first unexpected call.
			__index = function() return noop end,
		})

		-- Deadline: a yielding module parks this task, so record the miss on a
		-- timer instead of waiting on a call that may never return.
		task.delay(PROBE_DEADLINE, function()
			if probeInFlight[key] then
				probeInFlight[key] = nil
				if probeCache[key] == nil then
					probeCache[key] = earliestParryFrom(captured) or false
				end
			end
		end)

		pcall(moduleFn, probe, clone)

		if probeInFlight[key] then
			probeInFlight[key] = nil
			probeCache[key] = earliestParryFrom(captured) or false
		end
	end)
end

-- Parry time for the swing that's playing, in seconds from its start.
-- Returns (seconds, source) or (nil, reason).
local function parryTimeForAnimation(animationId, track, character)
	local timing = TimingStore.as and TimingStore.as:index(animationId)
	if not timing then return nil, "no timing entry" end

	-- Module-driven first -- same precedence AnimatorDefender uses
	-- (`if timing.umoa then return self:module(timing) end` before actions).
	local moduleName = moduleNameFor(timing)
	if timing.umoa or moduleName then
		if moduleName then
			local key = probeKey(animationId, moduleName, track and track.Speed)
			local cached = probeCache[key]
			if type(cached) == "number" then
				return cached, "module probe"
			end
			if track and character then
				startModuleProbe(animationId, timing, track, character)
			end
			return nil, cached == false and "module gave no parry" or "probing module"
		end
		return nil, "module-driven, no module name"
	end

	-- Static Parry action -- earliest wins.
	if timing.actions then
		local earliest = nil
		pcall(function()
			for _, action in ipairs(timing.actions:stack()) do
				if action._type == PARRY_ACTION_TYPE then
					local when = action:when()
					if type(when) == "number" and (earliest == nil or when < earliest) then
						earliest = when
					end
				end
			end
		end)
		if earliest then
			return earliest, "action"
		end
	end

	-- Repeat-parry timings carry their delay on the timing itself.
	if timing.rpue and type(timing._rpd) == "number" and timing._rpd > 0 then
		return timing:rpd(), "repeat delay"
	end

	return nil, "no parry data"
end


local function collectKnownAttackAnimationIds()
	local ids, seen = {}, {}
	pcall(function()
		local list = TimingStore.as:list()
		for _, entry in ipairs(list) do
			if AGGRESSIVE2_MOVE_TYPES[entry.tag] then
				local id = entry:id()
				if type(id) == "string" and id:match("%d") and not seen[id] then
					seen[id] = true
					ids[#ids + 1] = id
				end
			end
		end
	end)
	return ids
end

-- ============================================================================
-- Priority Mask (formerly "Ultimate Breaker") -- mira-old's Aggressive 2, brought over
-- as-is: a decoy pool built from the whole timing store, a generic full-body idle cover at Action2,
-- every real track boosted into the Action3/Action4 band, and the flood gated on
-- detectRealAttack().
--
-- One addition: the idle cover STANDS DOWN while a real locomotion track is
-- playing. Held up permanently it's a full-body pose fighting the walk/run; while
-- you're moving your own locomotion tracks are boosted above the flood and already
-- cover the legs, so the cover isn't needed until you're standing still again.
-- ============================================================================
local ULTIMATE_IDLE_COVER_ID = "rbxassetid://180435571"
-- Fade used when the idle cover stands down for movement, so it eases out instead
-- of popping. Teardown still stops instantly.
local ULTIMATE_IDLE_FADE = 0.2
-- How often the idle cover is hard-restarted (Stop(0) then Play(0), preserving
-- TimePosition). A cover reaches other clients only when it is genuinely PLAYED:
-- priority assignments on a running track don't replicate, and :Play() on a track
-- that's already playing raises no new event -- which is why a permanently-held cover
-- was visible only to the local player. A hard restart is a real play every time, and
-- with fade 0 plus the position restored it's invisible locally.
local ULTIMATE_COVER_REPLAY = 0.3
-- Counter seeds for Mutate's genuine-action-shadow urls, kept at the values seen in
-- the captured breaker so the url shape and numbering still match it.
local ULTIMATE_ATTACK_BASE_GENUINE = 164879734
local ULTIMATE_SLOT_BASE           = 107

---Numeric asset id behind any AnimationId (plain or already-mutated).
local function numericAssetId(animationId)
	local text = tostring(animationId or "")
	local viaQuery = text:match("[?&]id=(%d+)")
	if viaQuery then
		return viaQuery
	end
	return text:match("(%d+)")
end

local function startUltimateMode(character)
	if not character then return function() end end
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	if not humanoid then return function() end end
	local animator = humanoid:FindFirstChildOfClass("Animator")
	if not animator then return function() end end

	local trackPool = {}
	local trackPoolSet = {}
	local poolSize = 0

	local function loadDecoyTracks(idList)
		for _, track in next, trackPool do
			pcall(function() track:Stop(0); track:Destroy() end)
		end
		trackPool = {}
		trackPoolSet = {}
		poolSize = 0
		if type(idList) ~= "table" or #idList == 0 then return end

		local targetPoolSize = math.min(200, math.max(#idList, 20))
		local cursor, attempts, maxAttempts = 0, 0, targetPoolSize + #idList + 8
		while #trackPool < targetPoolSize and attempts < maxAttempts do
			attempts = attempts + 1
			cursor = cursor % #idList + 1
			local id = idList[cursor]
			if not string.find(id, "://", 1, true) then
				id = "rbxassetid://" .. id
			end
			local animation = Instance.new("Animation")
			animation.AnimationId = id
			local ok, track = pcall(function() return animator:LoadAnimation(animation) end)
			if ok and track then
				loadedTrackRegistry[track] = true
				track.Looped = false
				trackPool[#trackPool + 1] = track
				trackPoolSet[track] = true
			end
		end
		poolSize = #trackPool
	end

	local knownIds = collectKnownAttackAnimationIds()
	local usingFallbackIds = false
	if #knownIds == 0 then
		knownIds = FALLBACK_AGGRESSIVE2_ANIMATION_IDS
		usingFallbackIds = true
	end
	loadDecoyTracks(knownIds)

	-- Idle cover.
	--
	-- A cover only reaches OTHER clients when it is genuinely PLAYED: priority changes
	-- on a running track don't replicate, and :Play() on a track that's already playing
	-- doesn't raise a fresh event either. So a permanently-held cover is visible to you
	-- and to nobody else. Playing it only while you're standing still gives it a real
	-- stop/start on every movement transition, which is what actually replicates.
	local maskTrack = nil
	local maskSet = {}
	do
		local animation = Instance.new("Animation")
		animation.AnimationId = ULTIMATE_IDLE_COVER_ID
		local ok, track = pcall(function() return animator:LoadAnimation(animation) end)
		if ok and track then
			loadedTrackRegistry[track] = true
			track.Looped = true
			maskTrack = track
			maskSet[track] = true
		end
	end
	local lastMaskPlay = 0

	-- Always keep a few mutated sharko kicks alive at Action4. sharko_kick_v2 (id
	-- 11710290503) is a MOB move that never plays on a real player, but it IS in the timing
	-- store -- so an enemy autoparry canonicalises the mutated url back to the mob id and
	-- schedules its defense on the MOB's hit window, which no swing of yours will ever land
	-- on. Sitting at Action4 (the top) they also crown the mask. One distinct mutated slot
	-- per track so per-id spam filters can't collapse them.
	local sharkoTracks = {}
	local sharkoSet = {}
	do
		local slot = 104824667
		for _ = 1, 3 do
			local url = string.format(
				"https://www.roblox.com/asset/?attack=%d&slot=%d&id=%s",
				7600160919, slot, "11710290503"
			)
			slot = slot + 1
			local animation = Instance.new("Animation")
			animation.AnimationId = url
			local ok, track = pcall(function() return animator:LoadAnimation(animation) end)
			if ok and track then
				loadedTrackRegistry[track] = true
				track.Looped = false
				sharkoTracks[#sharkoTracks + 1] = track
				sharkoSet[track] = true
			end
		end
	end
	local lastSharkoPlay = 0

	local running = true
	-- The flood is only allowed to start once we've seen a FRESH Deepwoken idle/movement
	-- animation play -- that's a locomotion track we can actually boost up to cover the
	-- decoys. On first turning the breaker on, the idle is already playing (an "old" track):
	-- boosting a track that's already running doesn't take, so the flood would show
	-- uncovered. Waiting for a fresh locomotion track (which fires AnimationPlayed) fixes it.
	local coverEstablished = false
	local coverEstablishedAt = 0
	-- Once our cover has been raised the first time, keep it up through re-arms -- a toggle
	-- re-arms coverEstablished (pausing the flood), but the mask must NOT drop, or the flood
	-- flashes uncovered while it comes back. So the mask stays up until the mode stops / the
	-- visual is disabled; only the flood waits for the cover to re-settle.
	local maskRaisedOnce = false
	-- After the cover (re)establishes, hold the flood a beat so the mask has time to be up
	-- and replicate before the decoys start -- the cover always leads the flood.
	local COVER_SETTLE_TIME = 0.15
	-- Re-arm the cover-wait whenever the running mode set changes (a toggle resets the
	-- animation state and loses the cover) -- see apBreakerModeGeneration.
	local seenGeneration = apBreakerModeGeneration
	local coverConn = animator.AnimationPlayed:Connect(function(track)
		if coverEstablished or loadedTrackRegistry[track] then return end
		local ok, prio = pcall(function() return track.Priority end)
		if ok and (prio == Enum.AnimationPriority.Idle or prio == Enum.AnimationPriority.Movement) then
			coverEstablished = true
			coverEstablishedAt = os.clock()
		end
	end)
	local aggressive2Accumulator = 0
	local poolCursor = 0
	local framesSinceCheck = 0
	local fallbackRefreshTimer = 0
	local lastPlayTime = os.clock()
	local originalPriorities = setmetatable({}, { __mode = "k" })
	local function detectRealAttack(maskVisualEnabled)
		local realAttackPlaying = false
		for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
			if trackPoolSet[track] then
				if track.Priority ~= AGGRESSIVE2_PRIORITY then
					pcall(function() track.Priority = AGGRESSIVE2_PRIORITY end)
				end
			elseif not maskSet[track] and not sharkoSet[track] and (not loadedTrackRegistry[track] or mutateCopies[track]) and track.Animation and track.Animation.AnimationId then
				local savedPriority = originalPriorities[track]
				if savedPriority == nil then
					savedPriority = track.Priority
					originalPriorities[track] = savedPriority
				end
				local boosted = boostPriority(savedPriority)
				pcall(function() track.Priority = boosted end)
				if (PRIORITY_INDEX[boosted] or 0) > ACTION_INDEX and track.WeightCurrent > 0.5 then
					realAttackPlaying = true
				end
			end
		end
		-- Original tied this to the cover being PLAYING. Tie it to the cover being
		-- ENABLED instead, so suppressing the cover for movement doesn't also pause the
		-- flood.
		if maskTrack and maskVisualEnabled then
			realAttackPlaying = true
		end
		return realAttackPlaying
	end

	local function restoreForeignPriorities()
		for track, priority in pairs(originalPriorities) do
			pcall(function() track.Priority = priority end)
		end
		originalPriorities = setmetatable({}, { __mode = "k" })
	end

	local renderSteppedConn
	renderSteppedConn = RunService.RenderStepped:Connect(function(deltaTime)
		if not running then return end
		if not character.Parent then
			running = false
			return
		end

		-- A mode was just toggled on/off -- that resets the animation state and loses the
		-- cover, so re-arm the wait: hold the flood again until a fresh idle/movement is boosted.
		if apBreakerModeGeneration ~= seenGeneration then
			seenGeneration = apBreakerModeGeneration
			coverEstablished = false
		end

		-- Always keep the sharko kicks firing at Action4 (before any of the flood's early
		-- returns, so they run even while the flood is suppressed). Hard restart on a timer
		-- so each play raises a fresh AnimationPlayed that actually replicates.
		if #sharkoTracks > 0 then
			local nowSharko = os.clock()
			if nowSharko - lastSharkoPlay >= ULTIMATE_COVER_REPLAY then
				lastSharkoPlay = nowSharko
				for _, st in next, sharkoTracks do
					pcall(function()
						if st.IsPlaying then st:Stop(0) end
						st.Priority = Enum.AnimationPriority.Action4
						st:Play(0.1, 1, 1)
					end)
				end
			end
		end

		if usingFallbackIds then
			fallbackRefreshTimer = fallbackRefreshTimer + deltaTime
			if fallbackRefreshTimer >= 1.5 then
				fallbackRefreshTimer = 0
				local refreshed = collectKnownAttackAnimationIds()
				if #refreshed > 0 then
					loadDecoyTracks(refreshed)
					usingFallbackIds = false
				end
			end
		end

		if poolSize == 0 then return end

		local maskVisualEnabled = Configuration.expectToggleValue("ExpApBreakerMaskVisual") ~= false

		local shouldRunAggressive2 = true
		if maskVisualEnabled then
			shouldRunAggressive2 = detectRealAttack(maskVisualEnabled)
		elseif next(originalPriorities) ~= nil then
			restoreForeignPriorities()
		end

		if maskTrack then
			-- Don't raise our own idle cover until the flood is first allowed (a boosted fresh
			-- locomotion track). Playing the cover before then just shows a lone idle pose with
			-- nothing under it -- the "old animation" startup tell. But once it HAS been raised,
			-- keep it up through re-arms (maskRaisedOnce): a toggle re-arms the flood wait, and
			-- the mask dropping there is exactly what flashes the decoys.
			if maskVisualEnabled and (coverEstablished or maskRaisedOnce) then
				maskRaisedOnce = true
				-- Held up at ALL times (no movement gating): the instant the game starts
				-- a fresh locomotion track -- strafing is the obvious case -- there has to
				-- already be a cover under it, or that limb is bare for everyone else.
				-- Re-played on a timer so it keeps replicating.
				local now = os.clock()
				if not maskTrack.IsPlaying then
					pcall(function()
						maskTrack.Priority = Enum.AnimationPriority.Action2
						maskTrack:Play(0, 1, 1)
					end)
					lastMaskPlay = now
				elseif now - lastMaskPlay >= ULTIMATE_COVER_REPLAY then
					lastMaskPlay = now
					-- Hard restart: Stop(0) then Play(0). :Play() alone on a running track
					-- raises no event, so it would never reach anyone else. TimePosition is
					-- carried across so the pose doesn't jump locally.
					pcall(function()
						local position = maskTrack.TimePosition
						maskTrack:Stop(0)
						maskTrack.Priority = Enum.AnimationPriority.Action2
						maskTrack:Play(0, 1, 1)
						maskTrack.TimePosition = position
					end)
				end
			elseif maskTrack.IsPlaying then
				pcall(function() maskTrack:Stop(ULTIMATE_IDLE_FADE) end)
			end
		end

		-- Hold the flood until the cover is up (a boosted fresh locomotion track) AND has had
		-- a beat to settle/replicate, so the mask always leads the decoys -- including across
		-- a re-arm, where the flood pauses and resumes under the still-up mask.
		if maskVisualEnabled and (not shouldRunAggressive2 or not coverEstablished or (os.clock() - coverEstablishedAt) < COVER_SETTLE_TIME) then
			for _, track in next, trackPool do
				if track.IsPlaying then
					pcall(function() track:Stop(0) end)
				end
			end
			framesSinceCheck = 0
			aggressive2Accumulator = 0
			return
		end

		framesSinceCheck = framesSinceCheck + 1
		if maskVisualEnabled and framesSinceCheck < 3 then return end

		local intensity = getOption("ExpApBreakerAggressive2Intensity", 200)
		local interval = 1 / math.max(1, intensity)
		aggressive2Accumulator = math.min(aggressive2Accumulator + deltaTime, interval * 2)

		-- Do not push the animator past the animation limit -- skip this frame's flood.
		if not underAnimationLimit(animator) then
			return
		end

		local burstsThisFrame = 0
		while aggressive2Accumulator >= interval and burstsThisFrame < 50 do
			aggressive2Accumulator = aggressive2Accumulator - interval
			burstsThisFrame = burstsThisFrame + 1

			local chosenTrack = nil
			local fallbackZeroLenTrack = nil
			for _ = 1, poolSize do
				poolCursor = poolCursor % poolSize + 1
				local candidate = trackPool[poolCursor]
				if candidate and not candidate.IsPlaying then
					if candidate.Length > 0 then
						chosenTrack = candidate
						break
					elseif not fallbackZeroLenTrack then
						fallbackZeroLenTrack = candidate
					end
				end
			end
			if not chosenTrack and os.clock() - lastPlayTime > 8 then
				chosenTrack = fallbackZeroLenTrack
			end
			if chosenTrack then
				pcall(function()
					chosenTrack.Priority = AGGRESSIVE2_PRIORITY
					chosenTrack:Play(0.1, 1, 1)
				end)
				lastPlayTime = os.clock()
			end
		end
	end)

	return function()
		running = false
		if renderSteppedConn then
			renderSteppedConn:Disconnect()
			renderSteppedConn = nil
		end
		if coverConn then
			pcall(function() coverConn:Disconnect() end)
			coverConn = nil
		end

		-- Stop the flood FIRST, while the mask cover is still up, so the decoys are gone
		-- before the cover drops -- otherwise the flood flashes uncovered on the way out.
		for _, track in next, sharkoTracks do
			pcall(function() track:Stop(0) end)
		end
		for _, track in next, trackPool do
			pcall(function() track:Stop(0) end)
		end

		-- Give those stops a moment to replicate, THEN drop the cover, restore the boosted
		-- locomotion priorities, and destroy everything.
		task.delay(0.15, function()
			restoreForeignPriorities()
			if maskTrack then
				pcall(function() maskTrack:Stop(0); maskTrack:Destroy() end)
				maskTrack = nil
			end
			for _, track in next, sharkoTracks do
				pcall(function() track:Destroy() end)
			end
			for _, track in next, trackPool do
				pcall(function() track:Destroy() end)
			end
		end)
	end
end

-- ============================================================================
-- Mutate -- no flood at all. Every real attack you throw is replaced by a copy
-- of itself playing through a mutated URL, so the id string observers see is
-- unique every swing and never matches a timing-store entry. The original track
-- is stopped so only the mutated copy is live; the hit is server-side, so it
-- still lands.
-- ============================================================================
local function startMutateMode(character)
	if not character then return function() end end
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	if not humanoid then return function() end end
	local animator = humanoid:FindFirstChildOfClass("Animator")
	if not animator then return function() end end

	local running = true
	local attackSeq = ULTIMATE_ATTACK_BASE_GENUINE
	local slotSeq = ULTIMATE_SLOT_BASE
	-- track -> last time we mutated it. Deepwoken REUSES the same AnimationTrack object for
	-- repeat plays of a move, so a permanent "handled" flag would mutate only the FIRST swing
	-- of each move and skip every repeat. Instead dedupe on a short window: re-fires within
	-- the same swing are ignored, but the next swing (a fresh AnimationPlayed) is mutated.
	local lastMutatedAt = setmetatable({}, { __mode = "k" })
	-- realId -> a STABLE mutated copy track for that move. Reusing one url per move lets the
	-- enemy's client cache it after the first swing instead of re-fetching a brand-new url
	-- every swing (which pops/jitters the animation on their screen).
	local copyForMove = {}
	-- The copy currently showing, so a new move can stop the previous one.
	local currentCopy = nil

	local connection = animator.AnimationPlayed:Connect(function(track)
		if not running then return end
		-- Skip tracks another breaker mode owns (its flood/decoy pool) -- don't mutate them.
		if loadedTrackRegistry[track] then return end
		local last = lastMutatedAt[track]
		if last and (os.clock() - last) < 0.1 then return end

		local animId = tostring(track.Animation.AnimationId)
		if not (TimingStore.as and TimingStore.as:index(animId)) then return end
		if not shouldBreakOnMoveType(getCurrentMoveType()) then return end

		lastMutatedAt[track] = os.clock()

		local realId = numericAssetId(animId)
		if not realId then return end

		-- Reuse a stable mutated copy for this move; build one on first sight. Same url every
		-- swing of the same move -> the enemy caches it -> no per-swing re-fetch jitter.
		local copy = copyForMove[realId]
		if not copy then
			local url = string.format(
				"https://www.roblox.com/asset/?attack=%d&genuineactionshadow=1&slot=%d&id=%s",
				attackSeq, slotSeq, realId
			)
			attackSeq = attackSeq + 1
			slotSeq = slotSeq + 1

			local animation = Instance.new("Animation")
			animation.AnimationId = url
			local ok, newCopy = pcall(function() return animator:LoadAnimation(animation) end)
			if not ok or not newCopy then return end
			loadedTrackRegistry[newCopy] = true
			mutateCopies[newCopy] = true
			copy = newCopy
			copyForMove[realId] = copy
		end

		-- Only one of your swings shows at a time -- stop the previous move's copy.
		if currentCopy and currentCopy ~= copy then
			pcall(function() currentCopy:Stop(0) end)
		end
		currentCopy = copy

		local position = track.TimePosition
		local speed = track.Speed
		-- Play the copy at the REAL swing's own priority, not a forced Action4. Action4 made
		-- the mutated copy the single top-priority, full-weight track -- fine alone, but
		-- stacked with a stealth breaker it towers over everything and reads as blatant. At
		-- the swing's native priority it just renders like the attack it's replacing.
		local priority = track.Priority
		pcall(function() track:Stop(0) end)
		pcall(function()
			copy.Priority = priority
			if copy.IsPlaying then copy:Stop(0) end
			copy:Play(0, 1, speed)
			copy.TimePosition = position
		end)
	end)

	return function()
		running = false
		if connection then pcall(function() connection:Disconnect() end) end
		for _, copy in pairs(copyForMove) do
			pcall(function() copy:Stop(0); copy:Destroy() end)
		end
		copyForMove = {}
		currentCopy = nil
	end
end

-- ============================================================================
-- Monster Flood -- floods a MONSTER attack animation on YOUR own rig via per-slot
-- mutated urls. sharko_kick_v2 (id 11710290503) is a mob move that never plays on a
-- player, but it IS in the timing store -- so an enemy autoparry canonicalises the url
-- back to that mob id, finds the timing, and schedules its defense on the MOB's hit
-- window, which no real swing of yours will ever land on. The result breaks their parry
-- without ever looking like a blatant/unknown id. One monster id, many mutated slots:
-- each url is a distinct AnimationId string (so per-id spam filters can't collapse the
-- flood) that still resolves to the same real mob id on the receiving end. This is the
-- captured "sharko kick" breaker, reproduced -- same url shape, same seed/slot numbering.
-- ============================================================================
local MONSTER_FLOOD_ID = "11710290503"            -- sharko_kick_v2 (a Sharko mob move)
local MONSTER_FLOOD_ATTACK_SEED = 7600160919      -- constant attack= param seen in the wild
local MONSTER_FLOOD_SLOT_BASE = 104824667         -- first slot= value seen in the wild
local MONSTER_FLOOD_POOL = 60
local MONSTER_FLOOD_PRIORITY = Enum.AnimationPriority.Action

local function startMonsterFloodMode(character)
	if not character then return function() end end
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	if not humanoid then return function() end end
	local animator = humanoid:FindFirstChildOfClass("Animator")
	if not animator then return function() end end

	local trackPool = {}
	local function destroyPool()
		for _, track in next, trackPool do
			pcall(function() track:Stop(0); track:Destroy() end)
		end
		trackPool = {}
	end

	-- Pre-build the pool: one monster id behind many mutated slot urls.
	local slot = MONSTER_FLOOD_SLOT_BASE
	local attempts = 0
	while #trackPool < MONSTER_FLOOD_POOL and attempts < MONSTER_FLOOD_POOL * 2 do
		attempts = attempts + 1
		local url = string.format(
			"https://www.roblox.com/asset/?attack=%d&slot=%d&id=%s",
			MONSTER_FLOOD_ATTACK_SEED, slot, MONSTER_FLOOD_ID
		)
		slot = slot + 1
		local animation = Instance.new("Animation")
		animation.AnimationId = url
		local ok, track = pcall(function() return animator:LoadAnimation(animation) end)
		if ok and track then
			loadedTrackRegistry[track] = true
			track.Looped = false
			trackPool[#trackPool + 1] = track
		end
	end

	local running = true
	local accumulator = 0
	local poolCursor = 0
	local renderConn
	renderConn = RunService.RenderStepped:Connect(function(deltaTime)
		if not running then return end
		if not character.Parent then
			running = false
			return
		end
		local poolSize = #trackPool
		if poolSize == 0 then return end

		local intensity = getOption("ExpApBreakerAggressive2Intensity", 200)
		local interval = 1 / math.max(1, intensity)
		accumulator = math.min(accumulator + deltaTime, interval * 2)

		-- Do not push the animator past the animation limit -- skip this frame's flood.
		if not underAnimationLimit(animator) then
			return
		end

		local burstsThisFrame = 0
		while accumulator >= interval and burstsThisFrame < 50 do
			accumulator = accumulator - interval
			burstsThisFrame = burstsThisFrame + 1

			-- Prefer an idle track; if all are mid-play, hard-restart the next one so a
			-- fresh AnimationPlayed still fires (a :Play on a running track raises nothing).
			local chosen = nil
			for _ = 1, poolSize do
				poolCursor = poolCursor % poolSize + 1
				local candidate = trackPool[poolCursor]
				if candidate and not candidate.IsPlaying then
					chosen = candidate
					break
				end
			end
			local recycled = false
			if not chosen then
				poolCursor = poolCursor % poolSize + 1
				chosen = trackPool[poolCursor]
				recycled = chosen ~= nil
			end
			if chosen then
				pcall(function()
					if recycled then chosen:Stop(0) end
					chosen.Priority = MONSTER_FLOOD_PRIORITY
					chosen:Play(0.1, 1, 1)
				end)
			end
		end
	end)

	return function()
		running = false
		if renderConn then
			pcall(function() renderConn:Disconnect() end)
			renderConn = nil
		end
		destroyPool()
	end
end

-- ============================================================================
-- Fade Time Flood -- floods known-attack animations played with a 99999s fade time.
-- The giant fade means each track's WeightCurrent ramps in over ~forever, so it renders
-- at ~0 weight the whole time it plays (an invisible fade-time bait) while its
-- AnimationPlayed event STILL replicates and its WeightTarget stays realistic. An enemy
-- autoparry that trusts weight reads a swarm of "real" attacks that never actually ramp.
-- (Distinct from Fade Time Spoof, which replays only YOUR real swings with a long fade.)
-- ============================================================================
local FADE_TIME_FLOOD_FADE = 99999
local FADE_TIME_FLOOD_PRIORITY = Enum.AnimationPriority.Action

local function startFadeTimeFloodMode(character)
	if not character then return function() end end
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	if not humanoid then return function() end end
	local animator = humanoid:FindFirstChildOfClass("Animator")
	if not animator then return function() end end

	local trackPool = {}
	local function destroyPool()
		for _, track in next, trackPool do
			pcall(function() track:Stop(0); track:Destroy() end)
		end
		trackPool = {}
	end

	local function loadPool(idList)
		destroyPool()
		if type(idList) ~= "table" or #idList == 0 then return end
		local targetSize = math.min(200, math.max(#idList, 20))
		local cursor, attempts, maxAttempts = 0, 0, targetSize + #idList + 8
		while #trackPool < targetSize and attempts < maxAttempts do
			attempts = attempts + 1
			cursor = cursor % #idList + 1
			local id = idList[cursor]
			if not string.find(id, "://", 1, true) then
				id = "rbxassetid://" .. id
			end
			local animation = Instance.new("Animation")
			animation.AnimationId = id
			local ok, track = pcall(function() return animator:LoadAnimation(animation) end)
			if ok and track then
				loadedTrackRegistry[track] = true
				track.Looped = false
				trackPool[#trackPool + 1] = track
			end
		end
	end

	local ids = collectKnownAttackAnimationIds()
	local usingFallback = false
	if #ids == 0 then
		ids = FALLBACK_AGGRESSIVE2_ANIMATION_IDS
		usingFallback = true
	end
	loadPool(ids)

	local running = true
	local accumulator = 0
	local poolCursor = 0
	local fallbackRefreshTimer = 0
	local renderConn
	renderConn = RunService.RenderStepped:Connect(function(deltaTime)
		if not running then return end
		if not character.Parent then
			running = false
			return
		end

		if usingFallback then
			fallbackRefreshTimer = fallbackRefreshTimer + deltaTime
			if fallbackRefreshTimer >= 1.5 then
				fallbackRefreshTimer = 0
				local refreshed = collectKnownAttackAnimationIds()
				if #refreshed > 0 then
					loadPool(refreshed)
					usingFallback = false
				end
			end
		end

		local poolSize = #trackPool
		if poolSize == 0 then return end

		local intensity = getOption("ExpApBreakerAggressive2Intensity", 200)
		local interval = 1 / math.max(1, intensity)
		accumulator = math.min(accumulator + deltaTime, interval * 2)

		-- Do not push the animator past the animation limit -- skip this frame's flood.
		if not underAnimationLimit(animator) then
			return
		end

		local burstsThisFrame = 0
		while accumulator >= interval and burstsThisFrame < 50 do
			accumulator = accumulator - interval
			burstsThisFrame = burstsThisFrame + 1

			-- Only ever play a track that is NOT already playing. Re-playing a live track
			-- (Stop+Play) every burst is what made this blatant: the re-Play flashes the
			-- animation's real initial weight for a frame before the 99999 fade takes back
			-- over. Left alone, a fresh play ramps 0 -> 1 over 99999s (so it renders at ~0
			-- weight the whole time), plays out its length, stops, and only then gets played
			-- again -- a steady flood of fade-time baits that never actually show.
			local chosen = nil
			for _ = 1, poolSize do
				poolCursor = poolCursor % poolSize + 1
				local candidate = trackPool[poolCursor]
				if candidate and not candidate.IsPlaying then
					chosen = candidate
					break
				end
			end
			if chosen then
				pcall(function()
					chosen.Priority = FADE_TIME_FLOOD_PRIORITY
					-- 99999 fade: weight stays ~0 for the whole play, WeightTarget realistic.
					chosen:Play(FADE_TIME_FLOOD_FADE, 1, 1)
				end)
			end
		end
	end)

	return function()
		running = false
		if renderConn then
			pcall(function() renderConn:Disconnect() end)
			renderConn = nil
		end
		destroyPool()
	end
end

-- ============================================================================
-- Mode dispatch
-- ============================================================================
-- Each breaker mode is an independent start function returning a cleanup, so any subset
-- (or none) can run at once. Old single-value labels map forward so saved configs load.
local MODE_STARTERS = {
	["Priority Mask"]   = startUltimateMode,
	["Fade Time Spoof"] = startPassiveMode,
	["Fade Time Flood"] = startFadeTimeFloodMode,
	["Mutate"]          = startMutateMode,
	["Monster Flood"]   = startMonsterFloodMode,
}
local APB_LEGACY_MODES = {
	-- "Passive" was the replay mode, now called "Fade Time Spoof".
	["Passive"] = "Fade Time Spoof",
	["Aggressive"] = "Priority Mask",
	["Aggressive 2"] = "Priority Mask",
	["Blatant Flood"] = "Priority Mask",
	["Blatant Flood While Attacking"] = "Priority Mask",
	-- "Ultimate Breaker" was renamed to "Priority Mask".
	["Ultimate Breaker"] = "Priority Mask",
}

-- The set of currently-selected modes (canonical names) from the Modes multi-dropdown. An
-- empty set -- the default -- means no breaker runs even while AP Breaker is toggled on.
local function getSelectedModes()
	local selected = Configuration.expectOptionValue("ExpApBreakerModes")
	local result = {}
	if type(selected) == "table" then
		for key, value in pairs(selected) do
			-- Multi-dropdowns store { [name] = true }; tolerate array form { name } too.
			local name = (value == true) and key or value
			if type(name) == "string" then
				local canonical = APB_LEGACY_MODES[name] or name
				if MODE_STARTERS[canonical] then
					result[canonical] = true
				end
			end
		end
	end
	return result
end

-- Reconcile running modes with the selected set. Diffs rather than tearing everything
-- down: a mode that stays selected keeps running UNTOUCHED, so toggling one breaker never
-- disrupts the others (restarting Priority Mask, say, drops its idle cover for a frame and
-- flashes the decoys). Only newly-deselected modes stop and newly-selected ones start.
-- Called on start, on the dropdown changing, and on respawn (respawn passes a fresh
-- character, so everything is torn down and rebuilt on the new rig -- see the note below).
local function applyApBreakerModes(character, forceRestart)
	local changed = false

	-- On respawn the old character's tracks are gone with it, so every mode must rebind to
	-- the new animator -- tear all down and let the selected set rebuild below.
	if forceRestart then
		if next(apBreakerCleanups) then changed = true end
		for _, cleanup in pairs(apBreakerCleanups) do
			pcall(cleanup)
		end
		apBreakerCleanups = {}
	end

	if not apBreakerActive or not character then
		if next(apBreakerCleanups) then changed = true end
		for _, cleanup in pairs(apBreakerCleanups) do
			pcall(cleanup)
		end
		apBreakerCleanups = {}
		if changed then apBreakerModeGeneration = apBreakerModeGeneration + 1 end
		return
	end

	local selected = getSelectedModes()

	-- Stop modes no longer selected.
	for mode, cleanup in pairs(apBreakerCleanups) do
		if not selected[mode] then
			pcall(cleanup)
			apBreakerCleanups[mode] = nil
			changed = true
		end
	end

	-- Start newly-selected modes; leave already-running ones alone.
	for mode in pairs(selected) do
		if not apBreakerCleanups[mode] then
			local starter = MODE_STARTERS[mode]
			if starter then
				apBreakerCleanups[mode] = starter(character)
				changed = true
			end
		end
	end

	-- Any start/stop resets the character's animation state (the boosted idle cover is
	-- lost), so bump the generation -- running Priority Masks re-arm their cover-wait and
	-- hold the flood until a fresh idle/movement is boosted again.
	if changed then
		apBreakerModeGeneration = apBreakerModeGeneration + 1
	end
end

local function applyAttackDelay(character)
	if attackDelayCleanup then
		attackDelayCleanup()
		attackDelayCleanup = nil
	end
	if not attackDelayActive or not character then return end
	attackDelayCleanup = startAttackDelayHandler(character)
end

-- ============================================================================
-- Passive item spoof (Freestyler's Band / Konga's Clutch Ring)
-- ============================================================================
local function getPassivesTable()
	local effectReplicatorInstance = ReplicatedStorage:FindFirstChild("EffectReplicator")
	local effectReplicatorModule = effectReplicatorInstance and Require(effectReplicatorInstance)
	if not effectReplicatorModule then return nil end
	return effectReplicatorModule.Passives
end

local function addPassive(name)
	local passives = getPassivesTable()
	if type(passives) ~= "table" then return false end
	if passives[name] then return false end
	passives[name] = true
	return true
end

local function removePassive(name)
	local passives = getPassivesTable()
	if type(passives) == "table" then
		passives[name] = nil
	end
end

local function applyFreestylersBandSpoof()
	if addPassive("Freestyler's Band") then
		freestylersBandActive = true
	end
end

local function applyKongaClutchRingSpoof()
	if addPassive("Konga's Clutch Ring") then
		kongaClutchRingActive = true
	end
end

local function revertFreestylersBandSpoof()
	if not freestylersBandActive then return end
	removePassive("Freestyler's Band")
	freestylersBandActive = false
end

local function revertKongaClutchRingSpoof()
	if not kongaClutchRingActive then return end
	removePassive("Konga's Clutch Ring")
	kongaClutchRingActive = false
end

-- ============================================================================
-- Death info hiding
-- ============================================================================
local function spoofDeathInfoLabel(label)
	if label.Name ~= "DeathID" and label.Name ~= "KillerPlayer" and label.Name ~= "KillerCharacter" and label.Name ~= "Timestamp" then
		return
	end
	if not label:IsA("TextLabel") and not label:IsA("TextBox") then return end
	label.Visible = not (Configuration.expectToggleValue("InfoSpoofing") and Configuration.expectToggleValue("HideDeathInformation"))
end

local function hideDeathInfoInKillGuiSplash()
	local player = Players.LocalPlayer
	local playerGui = player:FindFirstChild("PlayerGui")
	if not playerGui then return end
	local killGui = playerGui:FindFirstChild("KillGui")
	if not killGui then return end
	local splash = killGui:FindFirstChild("Splash")
	if not splash then return end
	for _, descendant in next, splash:GetDescendants() do
		spoofDeathInfoLabel(descendant)
	end
end

-- ============================================================================
-- Main update tick (throttled to once per 2s)
-- ============================================================================
local function mainUpdateTick()
	if os.clock() - lastUpdateTime <= 2 then return end
	lastUpdateTime = os.clock()


	if not Configuration.expectToggleValue("InfoSpoofing") then
		originalStore:restore()
	end
	hideDeathInfoInKillGuiSplash()

	local player = Players.LocalPlayer
	if not player then return end
	local character = player.Character
	if not character then return end

	if Configuration.expectToggleValue("FreestylersBandSpoof") then
		applyFreestylersBandSpoof()
	else
		revertFreestylersBandSpoof()
	end
	if Configuration.expectToggleValue("KongaClutchRingSpoof") then
		applyKongaClutchRingSpoof()
	else
		revertKongaClutchRingSpoof()
	end

	if Configuration.expectToggleValue("ExperimentalApBreaker") then
		ApBreaker.startExpApBreaker()
	else
		ApBreaker.stopExpApBreaker()
	end
	if Configuration.expectToggleValue("AttackDelay") then
		ApBreaker.startAttackDelay()
	else
		ApBreaker.stopAttackDelay()
	end
	if Configuration.expectToggleValue("AttackPriorityChanger") then
		ApBreaker.startPriorityChanger()
	else
		ApBreaker.stopPriorityChanger()
	end
	if Configuration.expectToggleValue("SpoofAttackWeight") then
		ApBreaker.startWeightSpoof()
	else
		ApBreaker.stopWeightSpoof()
	end
	if Configuration.expectToggleValue("SpoofTargetWeight") then
		ApBreaker.startTargetWeightSpoof()
	else
		ApBreaker.stopTargetWeightSpoof()
	end
end

-- ============================================================================
-- Info-label spoof setters
-- ============================================================================
function ApBreaker.sgv(text)
	if not Configuration.expectToggleValue("InfoSpoofing") then return end
	local player = Players.LocalPlayer
	if not player then return end
	local playerGui = player:FindFirstChild("PlayerGui")
	if not playerGui then return end
	local topbarGui = playerGui:FindFirstChild("TopbarGui")
	local container = topbarGui and topbarGui:FindFirstChild("Container")
	local infoFrame = container and container:FindFirstChild("InfoFrame")
	local gameInfo = infoFrame and infoFrame:FindFirstChild("GameInfo")
	if not gameInfo then return end
	local gameVersionLabel = gameInfo:FindFirstChild("GameVersion")
	if not gameVersionLabel then return end
	originalStore:add(gameVersionLabel, "Text", text)
end

function ApBreaker.sds(text)
	if not Configuration.expectToggleValue("InfoSpoofing") then return end
	local player = Players.LocalPlayer
	if not player then return end
	local playerGui = player:FindFirstChild("PlayerGui")
	if not playerGui then return end
	local topbarGui = playerGui:FindFirstChild("TopbarGui")
	local container = topbarGui and topbarGui:FindFirstChild("Container")
	local infoFrame = container and container:FindFirstChild("InfoFrame")
	local worldInfo = infoFrame and infoFrame:FindFirstChild("WorldInfo")
	if not worldInfo then return end
	local dateLabel = worldInfo:FindFirstChild("Date")
	if not dateLabel then return end
	originalStore:add(dateLabel, "Text", text)
end

function ApBreaker.sss(text)
	if not Configuration.expectToggleValue("InfoSpoofing") then return end
	local player = Players.LocalPlayer
	if not player then return end
	local playerGui = player:FindFirstChild("PlayerGui")
	if not playerGui then return end
	local topbarGui = playerGui:FindFirstChild("TopbarGui")
	local container = topbarGui and topbarGui:FindFirstChild("Container")
	local infoFrame = container and container:FindFirstChild("InfoFrame")
	local characterInfo = infoFrame and infoFrame:FindFirstChild("CharacterInfo")
	if not characterInfo then return end
	local slotLabel = characterInfo:FindFirstChild("Slot")
	if not slotLabel then return end
	originalStore:add(slotLabel, "Text", text)
end

-- ============================================================================
-- Identity/character-info refresh spoofs (round-trip a value through a
-- sentinel to force listeners to re-read it)
-- ============================================================================
function ApBreaker.facs(instance, attributeName)
	local current = instance:GetAttribute(attributeName)
	instance:SetAttribute(attributeName, "SPOOFING_RICS")
	instance:SetAttribute(attributeName, current)
end

function ApBreaker.fvcs(valueObject)
	local current = valueObject.Value
	valueObject.Value = "SPOOFING_RICS"
	valueObject.Value = current
end

function ApBreaker.rics()
	for _, player in next, Players:GetPlayers() do
		ApBreaker.facs(player, "Guild")
		ApBreaker.facs(player, "FirstName")
		ApBreaker.facs(player, "LastName")
		local character = player.Character
		if not character then continue end
		ApBreaker.facs(character, "GuildRich")
		local humanoid = character:FindFirstChild("Humanoid")
		if not humanoid then continue end
		ApBreaker.facs(humanoid, "CharacterName")
	end

	local serverRegion = ReplicatedStorage:FindFirstChild("SERVER_REGION")
	local serverName = ReplicatedStorage:FindFirstChild("SERVER_NAME")
	local serverAge = ReplicatedStorage:FindFirstChild("SERVER_AGE")
	if not serverRegion or not serverName or not serverAge then return end
	ApBreaker.fvcs(serverRegion)
	ApBreaker.fvcs(serverName)
	local ageValue = serverAge.Value
	serverAge.Value = "L"
	serverAge.Value = ageValue
end

-- ============================================================================
-- AP Breaker public start/stop
-- ============================================================================
function ApBreaker.startExpApBreaker()
	if apBreakerActive then
		-- Already on -- re-apply so a change to the Modes dropdown takes effect live.
		local character = Players.LocalPlayer.Character
		if character then applyApBreakerModes(character) end
		return
	end
	apBreakerActive = true
	local player = Players.LocalPlayer
	if not apBreakerCharacterAddedConn then
		-- Respawn: the old rig's tracks died with it, so force a full rebuild on the new one.
		apBreakerCharacterAddedConn = player.CharacterAdded:Connect(function(char)
			applyApBreakerModes(char, true)
		end)
	end
	local character = player.Character or player.CharacterAdded:Wait()
	applyApBreakerModes(character)
	Logger.warn("Auto Parry Breaker started.")
end

function ApBreaker.stopExpApBreaker()
	if not apBreakerActive then return end
	apBreakerActive = false
	for _, cleanup in pairs(apBreakerCleanups) do
		pcall(cleanup)
	end
	apBreakerCleanups = {}
	if apBreakerCharacterAddedConn then
		apBreakerCharacterAddedConn:Disconnect()
		apBreakerCharacterAddedConn = nil
	end
	Logger.warn("Auto Parry Breaker stopped.")
end

function ApBreaker.startAttackDelay()
	if attackDelayActive then return end
	attackDelayActive = true
	local player = Players.LocalPlayer
	if not attackDelayCharacterAddedConn then
		attackDelayCharacterAddedConn = player.CharacterAdded:Connect(applyAttackDelay)
	end
	local character = player.Character or player.CharacterAdded:Wait()
	applyAttackDelay(character)
	Logger.warn("Attack Delay started.")
end

function ApBreaker.stopAttackDelay()
	if not attackDelayActive then return end
	attackDelayActive = false
	if attackDelayCleanup then
		attackDelayCleanup()
		attackDelayCleanup = nil
	end
	if attackDelayCharacterAddedConn then
		attackDelayCharacterAddedConn:Disconnect()
		attackDelayCharacterAddedConn = nil
	end
	Logger.warn("Attack Delay stopped.")
end

-- ============================================================================
-- Priority changer / weight spoof / target weight spoof
-- ============================================================================
local function getSpoofAttackWeightValue()
	local value = getOption("SpoofAttackWeightValue", 0.9)
	if type(value) ~= "number" then value = 0.9 end
	return value
end

local function getSpoofTargetWeightValue()
	local value = getOption("SpoofTargetWeightValue", 15)
	if type(value) ~= "number" then value = 15 end
	return value
end

local function getAttackPriorityChangerTarget()
	local priorityName = getOption("AttackPriority", "Action2")
	return Enum.AnimationPriority[priorityName] or Enum.AnimationPriority.Action2
end

local function attachPriorityWeightHandler(character)
	if priorityWeightAnimationPlayedConn then
		priorityWeightAnimationPlayedConn:Disconnect()
		priorityWeightAnimationPlayedConn = nil
	end
	if not (priorityChangerActive or weightSpoofActive or targetWeightSpoofActive) or not character then return end

	local humanoid = character:FindFirstChildOfClass("Humanoid")
	local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
	if not animator then return end

	priorityWeightAnimationPlayedConn = animator.AnimationPlayed:Connect(function(track)
		-- Skip tracks a breaker mode owns (its flood/decoy pool) -- only spoof real swings.
		if loadedTrackRegistry[track] then return end
		local animId = tostring(track.Animation.AnimationId)
		if not (TimingStore.as and TimingStore.as:index(animId)) then return end

		local function apply()
			if targetWeightSpoofActive then
				pcall(function() track:AdjustWeight(getSpoofTargetWeightValue(), 0) end)
			elseif weightSpoofActive then
				pcall(function() track:AdjustWeight(getSpoofAttackWeightValue(), 0) end)
			end
			if priorityChangerActive then
				pcall(function() track.Priority = getAttackPriorityChangerTarget() end)
			end
		end

		apply()
		task.spawn(function()
			local length = 0
			pcall(function() length = track.Length end)
			local startTime = os.clock()
			while priorityChangerActive or weightSpoofActive or targetWeightSpoofActive do
				task.wait()
				if not track.IsPlaying then break end
				if os.clock() - startTime > length + 0.25 then break end
				apply()
			end
		end)
	end)
end

local function updatePriorityWeightHandlerBinding()
	local player = Players.LocalPlayer
	if priorityChangerActive or weightSpoofActive or targetWeightSpoofActive then
		if not priorityWeightCharacterAddedConn then
			priorityWeightCharacterAddedConn = player.CharacterAdded:Connect(attachPriorityWeightHandler)
		end
		if player.Character then
			attachPriorityWeightHandler(player.Character)
		end
	else
		if priorityWeightCharacterAddedConn then
			priorityWeightCharacterAddedConn:Disconnect()
			priorityWeightCharacterAddedConn = nil
		end
		if priorityWeightAnimationPlayedConn then
			priorityWeightAnimationPlayedConn:Disconnect()
			priorityWeightAnimationPlayedConn = nil
		end
	end
end

function ApBreaker.startPriorityChanger()
	if priorityChangerActive then return end
	priorityChangerActive = true
	updatePriorityWeightHandlerBinding()
end

function ApBreaker.stopPriorityChanger()
	if not priorityChangerActive then return end
	priorityChangerActive = false
	updatePriorityWeightHandlerBinding()
end

function ApBreaker.startWeightSpoof()
	if weightSpoofActive then return end
	weightSpoofActive = true
	updatePriorityWeightHandlerBinding()
end

function ApBreaker.stopWeightSpoof()
	if not weightSpoofActive then return end
	weightSpoofActive = false
	updatePriorityWeightHandlerBinding()
end

function ApBreaker.startTargetWeightSpoof()
	if targetWeightSpoofActive then return end
	targetWeightSpoofActive = true
	updatePriorityWeightHandlerBinding()
end

function ApBreaker.stopTargetWeightSpoof()
	if not targetWeightSpoofActive then return end
	targetWeightSpoofActive = false
	updatePriorityWeightHandlerBinding()
end

-- ============================================================================
-- Lifecycle
-- ============================================================================
function ApBreaker.init()
	local player = Players.LocalPlayer
	local playerGui = player:WaitForChild("PlayerGui")
	local descendantAddedSignal = Signal.new(playerGui.DescendantAdded)
	maid:add(renderSteppedSignal:connect("Spoofing_OnRenderStepped", mainUpdateTick))
	maid:add(descendantAddedSignal:connect("Spoofing_OnPGDescendantAdded", spoofDeathInfoLabel))
	Logger.warn("Spoofing initialized.")
end

function ApBreaker.detach()
	ApBreaker.force = true
	ApBreaker.stopExpApBreaker()
	ApBreaker.stopAttackDelay()
	ApBreaker.stopPriorityChanger()
	ApBreaker.stopWeightSpoof()
	ApBreaker.stopTargetWeightSpoof()
	maid:clean()
	ApBreaker.rics()
	revertFreestylersBandSpoof()
	revertKongaClutchRingSpoof()
	Logger.warn("Spoofing detached.")
end

-- ==== mira4 compatibility surface ====
function ApBreaker.refresh()
	if apBreakerActive then ApBreaker.startExpApBreaker() end
end
function ApBreaker:Start()
	ApBreaker.startExpApBreaker()
end
function ApBreaker:Stop()
	ApBreaker.stopExpApBreaker()
end
if getgenv then
	getgenv().ExpApBreaker = ApBreaker
end
return ApBreaker

end)
__bundle_register("Features/Combat/AutoSpineCutter", function(require, _LOADED, __bundle_register, __bundle_modules)
-- AutoSpineCutter module (WIP).
local AutoSpineCutter = {}

---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Utility.Signal
local Signal = require("Utility/Signal")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Game.InputClient
local InputClient = require("Game/InputClient")

---@module Game.Objects.DodgeOptions
local DodgeOptions = require("Game/Objects/DodgeOptions")

-- Services.
local players = game:GetService("Players")
local runService = game:GetService("RunService")
local replicatedStorage = game:GetService("ReplicatedStorage")
local localPlayer = players.LocalPlayer

-- Tuning.
local RANGE = 20.0               -- max studs to the target for an attempt to start
local WRAP_TIME = 0.16           -- drive the travel toward their back this long (or until we're behind), THEN cancel + M1
local ROLL_SPEED = 60            -- studs/sec the mover carries us around the arc (plain roll velocity gets damped, so we force it)
local BEHIND_OFFSET = 3.0        -- studs behind their back the travel steers toward
local BEHIND_REACH = 4.0         -- within this many studs of that behind-point = we've made it around (stop steering early)
local SPINE_COOLDOWN = 10.0      -- global cooldown between spine cutter attempts (any trigger)
local PARRY_COOLDOWN = 1.0       -- debounce so a multi-hit parry chain fires once
local BLOCKBREAK_COOLDOWN = 5.0  -- requested: at least 5s between guard-break attempts
local BLOCKBREAK_POLL = 1 / 15   -- how often we sample enemy break meters
local BREAK_RATIO = 0.99         -- BreakMeter.Value/MaxValue counted as "guard broken"

-- Local effect classes that mean "a parry just happened" (manual or auto).
local PARRY_EFFECTS = { Parry = true, Parried = true, ParryCool = true }

-- State.
local maid = Maid.new()
local enabled = false
local busy = false
local lastSpineCutterAt = 0.0
local lastParryAt = 0.0
local lastBlockBreakAt = 0.0
local lastBlockPoll = 0.0

-- Per-target break-meter ratio from the previous poll, so we only fire on the RISING edge into a full meter instead of every frame it stays full.
local breakRatioHistory = setmetatable({}, { __mode = "k" })

--- Read the "Attempt On" multi-dropdown.
---@param name string
---@return boolean
local function modeSelected(name)
	local selected = Configuration.expectOptionValue("AutoSpineCutterModes")
	if type(selected) ~= "table" then
		return false
	end
	return selected[name] == true
end

--- A "humanoid" target: standard player-shaped rig, alive, with a root.
---@param character Instance
---@return boolean
local function isHumanoidCharacter(character)
	if not character or character == localPlayer.Character then
		return false
	end
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	if not humanoid or humanoid.Health <= 0 then
		return false
	end
	if not character:FindFirstChild("HumanoidRootPart") then
		return false
	end
	if players:GetPlayerFromCharacter(character) then
		return true
	end
	return character:FindFirstChild("UpperTorso") ~= nil
		or character:FindFirstChild("Torso") ~= nil
end

---Every valid humanoid character in the combat folders (Live + NPCs).
---@return Instance[]
local function scanCharacters()
	local result = {}
	for _, folderName in next, { "Live", "NPCs" } do
		local folder = workspace:FindFirstChild(folderName)
		if folder then
			for _, character in next, folder:GetChildren() do
				if isHumanoidCharacter(character) then
					result[#result + 1] = character
				end
			end
		end
	end
	return result
end

---Nearest valid humanoid target within RANGE.
---@return Instance?, BasePart?
local function getTarget()
	local character = localPlayer.Character
	local root = character and character:FindFirstChild("HumanoidRootPart")
	if not root then
		return nil
	end

	local best, bestRoot, bestDist = nil, nil, RANGE
	for _, entity in next, scanCharacters() do
		local entityRoot = entity:FindFirstChild("HumanoidRootPart")
		if entityRoot then
			local distance = (entityRoot.Position - root.Position).Magnitude
			if distance <= bestDist then
				best, bestRoot, bestDist = entity, entityRoot, distance
			end
		end
	end
	return best, bestRoot
end

---Can we physically roll right now? (alive local char + a root)
---@return boolean
local function canAct()
	local character = localPlayer.Character
	if not character then
		return false
	end
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	if not humanoid or humanoid.Health <= 0 then
		return false
	end
	return character:FindFirstChild("HumanoidRootPart") ~= nil
end

---The manual spine-cutter motion: roll, wrap around to their back, feint-cancel into an M1.
---@param targetCharacter Instance
---@param targetRoot BasePart
local function doSpineCutter(targetCharacter, targetRoot)
	if busy or not canAct() then
		return
	end
	if os.clock() - lastSpineCutterAt < SPINE_COOLDOWN then
		return
	end
	if not isHumanoidCharacter(targetCharacter) or not (targetRoot and targetRoot.Parent) then
		return
	end

	local character = localPlayer.Character
	local humanoid = character and character:FindFirstChildOfClass("Humanoid")
	local root = character and character:FindFirstChild("HumanoidRootPart")
	if not (humanoid and root) then
		return
	end

	busy = true
	lastSpineCutterAt = os.clock()
	Logger.warn("Auto Spine Cutter firing on %s.", targetCharacter.Name)

	task.spawn(function()
		local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
		local erm = effectReplicator and require(effectReplicator)

		-- Are we currently mid-roll?
		local function isRolling()
			return erm ~= nil and (erm:HasEffect("Dodge") or erm:HasEffect("ClientDodge"))
		end

		-- The point just behind their back.
		local function behindPoint()
			if not (targetRoot and targetRoot.Parent) then
				return nil
			end
			local back = -targetRoot.CFrame.LookVector
			back = Vector3.new(back.X, 0, back.Z)
			if back.Magnitude < 0.01 then
				return nil
			end
			back = back.Unit
			local enemy = Vector3.new(targetRoot.Position.X, root.Position.Y, targetRoot.Position.Z)
			return enemy + back * BEHIND_OFFSET, enemy, back
		end

		-- Steering: circle AROUND them while off to the side, then cut straight in to the behind-point once nearly behind.
		local function steer()
			local behind, enemy, back = behindPoint()
			if not behind then
				return nil, true
			end
			local radial = root.Position - enemy
			radial = Vector3.new(radial.X, 0, radial.Z)
			local dist = radial.Magnitude
			if dist > 0.05 and radial.Unit:Dot(back) > 0.5 and (root.Position - behind).Magnitude <= BEHIND_REACH then
				return nil, true
			end
			if dist < 0.05 then
				return back, false
			end
			local radialUnit = radial.Unit
			local angle = math.acos(math.clamp(radialUnit:Dot(back), -1, 1))
			if angle < 0.7 then
				local delta = behind - root.Position
				delta = Vector3.new(delta.X, 0, delta.Z)
				return (delta.Magnitude > 0.05 and delta.Unit or back), false
			end
			local tangent = radialUnit:Cross(Vector3.new(0, 1, 0))
			if tangent:Dot(back) < 0 then
				tangent = -tangent
			end
			return tangent.Unit, false
		end

		-- Seed MoveDirection once so the roll fires toward the arc.
		local firstDir = select(1, steer())
		if firstDir then
			pcall(function()
				humanoid:Move(firstDir, false)
			end)
		end

		-- Roll animation, looped + top priority, so it's VISIBLE for the whole motion.
		local rollTrack
		do
			local assets = replicatedStorage:FindFirstChild("Assets")
			local anims = assets and assets:FindFirstChild("Anims")
			local movement = anims and anims:FindFirstChild("Movement")
			local rollFolder = movement and movement:FindFirstChild("Roll")
			local rollAnim = rollFolder
				and (rollFolder:FindFirstChild("RightRoll") or rollFolder:FindFirstChild("ForwardRoll"))
			if rollAnim then
				local ok, track = pcall(function()
					return humanoid:LoadAnimation(rollAnim)
				end)
				if ok and track then
					rollTrack = track
					rollTrack.Looped = true
					rollTrack.Priority = Enum.AnimationPriority.Action4
					pcall(function()
						rollTrack:Play(0.05)
					end)
				end
			end
		end

		-- Fire the real roll.
		local options = DodgeOptions.new()
		options.actionRolling = true
		task.spawn(function()
			pcall(InputClient.dodge, options)
		end)

		-- Give the roll one frame to come out.
		runService.RenderStepped:Wait()

		-- Travel around to their back.
		local mover = Instance.new("BodyVelocity")
		mover.Name = "SpineCutterMover"
		mover.MaxForce = Vector3.new(1, 0, 1) * 1e5
		mover.P = 1e4
		mover.Velocity = Vector3.zero
		pcall(function()
			mover:AddTag("AllowedBM")
			mover:AddTag("LocalMover")
		end)
		mover.Parent = root

		local wrapDeadline = os.clock() + WRAP_TIME
		while os.clock() < wrapDeadline do
			local direction, arrived = steer()
			if arrived then
				break
			end
			if direction then
				pcall(function()
					humanoid:Move(direction, false)
					if mover.Parent then
						mover.Velocity = Vector3.new(direction.X * ROLL_SPEED, 0, direction.Z * ROLL_SPEED)
					end
				end)
			end
			runService.RenderStepped:Wait()
		end

		-- Stop the travel.
		pcall(function()
			humanoid:Move(Vector3.zero, false)
		end)
		if mover then
			pcall(function()
				mover:Destroy()
			end)
			mover = nil
		end

		-- Snap the camera onto their back like an aimbot so the M1 can't whiff -- the swing fires along the camera look.
		local camera = workspace.CurrentCamera
		local snapBound = false
		if camera then
			local ok = pcall(function()
				runService:BindToRenderStep("MiraSpineCutterCam", Enum.RenderPriority.Last.Value + 1, function()
					if targetRoot and targetRoot.Parent then
						local cf = camera.CFrame
						camera.CFrame = CFrame.new(cf.Position, targetRoot.Position)
					end
				end)
			end)
			snapBound = ok
			-- Let the forced angle land one frame before the swing.
			task.wait()
		end

		-- Roll-cancel + M1, the proven Easy Roll Cancel way: a feint pops the active dodge, then the M1 lands out of the recovery.
		if isRolling() then
			pcall(InputClient.feint)
		end
		if rollTrack then
			pcall(function()
				rollTrack:Stop(0.05)
			end)
		end
		task.wait()

		local aimTarget = (targetRoot and targetRoot.Parent) and targetRoot.Position
			or (root.Position + root.CFrame.LookVector)
		pcall(InputClient.left, CFrame.new(root.Position, aimTarget), true)

		-- Hold the forced angle a hair so the swing registers on it, then hand the camera back.
		task.wait(0.05)
		if snapBound then
			pcall(function()
				runService:UnbindFromRenderStep("MiraSpineCutterCam")
			end)
		end

		busy = false
	end)
end

---Parry trigger: a parry just landed (Parry / Parried / ParryCool effect).
---@param effect table
local function onEffectAdded(effect)
	if not enabled or not effect or not PARRY_EFFECTS[effect.Class] then
		return
	end
	if not modeSelected("Attempt on Parry") then
		return
	end
	if os.clock() - lastParryAt < PARRY_COOLDOWN then
		return
	end

	local target, targetRoot = getTarget()
	if not target then
		return
	end

	lastParryAt = os.clock()
	doSpineCutter(target, targetRoot)
end

--- Block-break trigger: poll humanoid break meters; fire on the rising edge into a full meter (the moment their guard breaks), gated behind a 5s cooldown.
local function pollBlockBreaks()
	if not enabled or not modeSelected("Attempt on Block Break") then
		return
	end
	if os.clock() - lastBlockPoll < BLOCKBREAK_POLL then
		return
	end
	lastBlockPoll = os.clock()

	local character = localPlayer.Character
	local root = character and character:FindFirstChild("HumanoidRootPart")
	if not root then
		return
	end

	for _, entity in next, scanCharacters() do
		local breakMeter = entity:FindFirstChild("BreakMeter")
		if not breakMeter or breakMeter.MaxValue <= 0 then
			breakRatioHistory[entity] = nil
			continue
		end

		local ratio = breakMeter.Value / breakMeter.MaxValue
		local previous = breakRatioHistory[entity] or 0
		breakRatioHistory[entity] = ratio

		-- Rising edge into a full meter = the guard just broke.
		if previous < BREAK_RATIO and ratio >= BREAK_RATIO then
			if os.clock() - lastBlockBreakAt < BLOCKBREAK_COOLDOWN then
				continue
			end
			local entityRoot = entity:FindFirstChild("HumanoidRootPart")
			if not entityRoot or (entityRoot.Position - root.Position).Magnitude > RANGE then
				continue
			end
			lastBlockBreakAt = os.clock()
			doSpineCutter(entity, entityRoot)
			break
		end
	end
end

---Initialize (called when the toggle turns on).
function AutoSpineCutter.init()
	if enabled then
		return
	end
	enabled = true

	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	local effectReplicatorModule = effectReplicator and require(effectReplicator)
	if effectReplicatorModule then
		local effectAdded = Signal.new(effectReplicatorModule.EffectAdded)
		maid:mark(effectAdded:connect("AutoSpineCutter_EffectAdded", onEffectAdded))
	end

	local postSimulation = Signal.new(runService.PostSimulation)
	maid:mark(postSimulation:connect("AutoSpineCutter_PollBlockBreaks", pollBlockBreaks))

	Logger.warn("Auto Spine Cutter started.")
end

---Detach (called when the toggle turns off).
function AutoSpineCutter.detach()
	if not enabled then
		return
	end
	enabled = false
	busy = false
	pcall(function()
		runService:UnbindFromRenderStep("MiraSpineCutterCam")
	end)
	maid:clean()
	table.clear(breakRatioHistory)
	Logger.warn("Auto Spine Cutter stopped.")
end

-- Return AutoSpineCutter module.
return AutoSpineCutter
end)
__bundle_register("Features/Combat/RhythmSpoofer", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
-- RhythmSpoofer module.
local RhythmSpoofer = {}

---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

local players = game:GetService("Players")
local tweenService = game:GetService("TweenService")
local lighting = game:GetService("Lighting")
local runService = game:GetService("RunService")
local userInputService = game:GetService("UserInputService")
local replicatedStorage = game:GetService("ReplicatedStorage")
local debris = game:GetService("Debris")
local soundService = game:GetService("SoundService")

local localPlayer = players.LocalPlayer

local rhythmMaid = Maid.new()

local CONFIG = {
	FALLBACK_KEY = Enum.KeyCode.G,
	MIN_DURATION = 4.0,
	DETECTION_RANGE = 1000,
	ANIMATION_ID = "rbxassetid://4746910224",
	SOUND_ID = "rbxassetid://4748402358",
	SOUND_VOLUME = 0.8,
	FADE_IN_DURATION = 1.0,
	FADE_OUT_DURATION = 1.0,
	SATURATION_NORMAL = 0,
	SATURATION_ACTIVE = -1.0,
	TINT_NORMAL = Color3.new(1, 1, 1),
	TINT_ACTIVE = Color3.fromRGB(217, 217, 217),
	SONAR_COLOR = Color3.fromRGB(35, 55, 70),
	SONAR_START_SIZE = 80,
	SONAR_END_SIZE = 200,
}

local rhythmActive = false
local rhythmStartTime = nil
local pendingStop = false
local rhythmCC = nil
local currentAnimTrack = nil
local currentSound = nil
local reverbEffect = nil
local volumeEffect = nil
local reverbLoop = nil
local pulseLoop = nil
local debounce = false
local entityTimestamps = {}
local rhythmKeybind = nil
local effectModule = nil

local function getCharacter()
	return localPlayer and localPlayer.Character
end

local function getHRP()
	local character = getCharacter()
	return character and character:FindFirstChild("HumanoidRootPart")
end

local function getHumanoid()
	local character = getCharacter()
	return character and character:FindFirstChildOfClass("Humanoid")
end

local function hasRhythmTalent()
	local passives = localPlayer.Character and localPlayer.Character:GetAttribute("ssv_Passives")
	if passives and passives:find("Murmur: Rhythm") then return true end
	local backpack = localPlayer:FindFirstChild("Backpack")
	return backpack and backpack:FindFirstChild("Talent:Murmur: Rhythm")
end

local function getEffectModule()
	if effectModule then return effectModule end
	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if effectReplicator then
		local success, result = pcall(require, effectReplicator)
		if success then
			effectModule = result
		end
	end
	return effectModule
end

local function isCrouching()
	local em = getEffectModule()
	if not em then return false end
	local clientCrouch = em:FindEffect("ClientCrouch")
	local serverCrouch = em:FindEffect("Crouching")
	return (clientCrouch ~= nil) or (serverCrouch ~= nil)
end

local function canUseRhythm()
	if not isCrouching() then
		return false
	end
	local em = getEffectModule()
	if em and em:FindEffect("Stun") then
		return false
	end
	return true
end

local function getRhythmKeybind()
	if rhythmKeybind then return rhythmKeybind end

	local keybindsModule = replicatedStorage:FindFirstChild("KeyBinds")
	if keybindsModule then
		local success, keybinds = pcall(require, keybindsModule)
		if success and keybinds and keybinds.GetBinding then
			local binding = keybinds.GetBinding("Rhythm")
			if binding and type(binding) == "table" then
				for _, keyName in ipairs(binding) do
					local ok, keyCode = pcall(function()
						return Enum.KeyCode[keyName]
					end)
					if ok and keyCode then
						rhythmKeybind = keyCode
						return rhythmKeybind
					end
				end
			end
		end
	end

	rhythmKeybind = CONFIG.FALLBACK_KEY
	return rhythmKeybind
end

local function getThrown()
	local thrown = workspace:FindFirstChild("Thrown")
	if not thrown then
		thrown = Instance.new("Folder")
		thrown.Name = "Thrown"
		thrown.Parent = workspace
	end
	return thrown
end

local function setupRhythmCC()
	rhythmCC = lighting:FindFirstChild("Rhythm")
	if not rhythmCC then
		rhythmCC = Instance.new("ColorCorrectionEffect")
		rhythmCC.Name = "Rhythm"
		rhythmCC.Brightness = 0
		rhythmCC.Contrast = 0
		rhythmCC.Saturation = 0
		rhythmCC.TintColor = Color3.new(1, 1, 1)
		rhythmCC.Enabled = false
		rhythmCC.Parent = lighting
	end
	return rhythmCC
end

local function activateLighting()
	if not rhythmCC then setupRhythmCC() end

	rhythmCC.Saturation = CONFIG.SATURATION_NORMAL
	rhythmCC.TintColor = CONFIG.TINT_NORMAL
	rhythmCC.Enabled = true

	tweenService:Create(rhythmCC,
		TweenInfo.new(CONFIG.FADE_IN_DURATION, Enum.EasingStyle.Linear),
		{ Saturation = CONFIG.SATURATION_ACTIVE, TintColor = CONFIG.TINT_ACTIVE }
	):Play()
end

local function deactivateLighting()
	if not rhythmCC then return end

	tweenService:Create(rhythmCC,
		TweenInfo.new(CONFIG.FADE_OUT_DURATION, Enum.EasingStyle.Linear),
		{ Saturation = CONFIG.SATURATION_NORMAL, TintColor = CONFIG.TINT_NORMAL }
	):Play()
end

local function startAmbientOverride()
	local em = getEffectModule()
	if not em then return end

	if reverbEffect then
		pcall(function() reverbEffect:Remove() end)
		reverbEffect = nil
	end
	if volumeEffect then
		pcall(function() volumeEffect:Remove() end)
		volumeEffect = nil
	end
	if reverbLoop then
		pcall(function() reverbLoop:Disconnect() end)
		reverbLoop = nil
	end

	task.wait()

	pcall(function()
		reverbEffect = em:CreateEffect("ReverbOverride", {})
	end)

	pcall(function()
		volumeEffect = em:CreateEffect("AmbientVolume", { Value = 1 })
	end)

	reverbLoop = runService.Heartbeat:Connect(function()
		if rhythmActive then
			if soundService.AmbientReverb ~= Enum.ReverbType.Alley then
				soundService.AmbientReverb = Enum.ReverbType.Alley
			end
		end
	end)

	local numberValue = Instance.new("NumberValue")
	numberValue.Value = 1
	local numberValueConn = numberValue.Changed:Connect(function()
		if volumeEffect then
			volumeEffect.Value = numberValue.Value
		end
	end)

	tweenService:Create(numberValue, TweenInfo.new(1), { Value = 0 }):Play()

	task.delay(1.5, function()
		numberValue:Destroy()
	end)
end

local function stopAmbientOverride(immediate)
	if reverbLoop then
		pcall(function() reverbLoop:Disconnect() end)
		reverbLoop = nil
	end

	local currentVolumeEffect = volumeEffect
	local currentReverbEffect = reverbEffect
	volumeEffect = nil
	reverbEffect = nil

	if currentReverbEffect then
		pcall(function() currentReverbEffect:Remove() end)
	end

	soundService.AmbientReverb = Enum.ReverbType.NoReverb

	if not currentVolumeEffect then return end

	if immediate then
		pcall(function() currentVolumeEffect:Remove() end)
		return
	end

	local success, numberValue = pcall(function()
		local nv = Instance.new("NumberValue")
		nv.Value = 0
		return nv
	end)

	if success and numberValue then
		local conn
		conn = numberValue.Changed:Connect(function()
			pcall(function()
				currentVolumeEffect.Value = numberValue.Value
			end)
		end)

		tweenService:Create(numberValue, TweenInfo.new(1), { Value = 1 }):Play()

		task.delay(1.1, function()
			pcall(function() conn:Disconnect() end)
			pcall(function() numberValue:Destroy() end)
			pcall(function() currentVolumeEffect:Remove() end)
		end)
	else
		pcall(function() currentVolumeEffect:Remove() end)
	end
end

local function playAnimation()
	local humanoid = getHumanoid()
	if not humanoid then return end

	local animator = humanoid:FindFirstChildOfClass("Animator")
	if not animator then return end

	local listenAnim = replicatedStorage:FindFirstChild("Assets")
		and replicatedStorage.Assets:FindFirstChild("Anims")
		and replicatedStorage.Assets.Anims:FindFirstChild("Powers")
		and replicatedStorage.Assets.Anims.Powers:FindFirstChild("Listen")

	if listenAnim then
		currentAnimTrack = animator:LoadAnimation(listenAnim)
	else
		local anim = Instance.new("Animation")
		anim.AnimationId = CONFIG.ANIMATION_ID
		currentAnimTrack = animator:LoadAnimation(anim)
	end

	currentAnimTrack.Priority = Enum.AnimationPriority.Action
	currentAnimTrack:Play()
end

local function stopAnimation()
	if currentAnimTrack then
		currentAnimTrack:Stop()
		currentAnimTrack = nil
	end
end

local function playSound()
	local rhythmSound = replicatedStorage:FindFirstChild("Sounds")
		and replicatedStorage.Sounds:FindFirstChild("Rhythm")

	if rhythmSound then
		currentSound = rhythmSound:Clone()
	else
		currentSound = Instance.new("Sound")
		currentSound.SoundId = CONFIG.SOUND_ID
		currentSound.Volume = CONFIG.SOUND_VOLUME
	end

	currentSound.Name = "Rhythm"
	currentSound.Parent = workspace
	currentSound:Play()

	debris:AddItem(currentSound, 3)
end

local function stopSound()
	if currentSound then
		currentSound:Stop()
		currentSound:Destroy()
		currentSound = nil
	end
end

local function createExpandingSonar()
	local hrp = getHRP()
	if not hrp then return end

	local part
	local sonarAsset = replicatedStorage:FindFirstChild("Assets")
		and replicatedStorage.Assets:FindFirstChild("Effects")
		and replicatedStorage.Assets.Effects:FindFirstChild("Sonar")

	if sonarAsset then
		part = sonarAsset:Clone()
	else
		part = Instance.new("Part")
		part.Shape = Enum.PartType.Ball
		part.Color = CONFIG.SONAR_COLOR
		part.Material = Enum.Material.ForceField
		part.Anchored = true
		part.CanCollide = false
		part.CastShadow = false
	end

	part.Name = "Sonar"
	part.Transparency = 1
	part.Size = Vector3.new(CONFIG.SONAR_START_SIZE, CONFIG.SONAR_START_SIZE, CONFIG.SONAR_START_SIZE)
	part.CFrame = hrp.CFrame
	part.Parent = getThrown()

	tweenService:Create(part,
		TweenInfo.new(3, Enum.EasingStyle.Sine, Enum.EasingDirection.Out),
		{ Size = Vector3.new(CONFIG.SONAR_END_SIZE, CONFIG.SONAR_END_SIZE, CONFIG.SONAR_END_SIZE) }
	):Play()

	tweenService:Create(part,
		TweenInfo.new(1, Enum.EasingStyle.Linear, Enum.EasingDirection.Out, 0, true),
		{ Transparency = 0.02 }
	):Play()

	debris:AddItem(part, 4)
end

local function detectEntities()
	local hrp = getHRP()
	if not hrp then return end

	local character = getCharacter()
	local myPos = hrp.Position
	local range = CONFIG.DETECTION_RANGE

	local liveFolder = workspace:FindFirstChild("Live")
	if not liveFolder then return end

	local clientEffectDirect = replicatedStorage:FindFirstChild("Requests")
		and replicatedStorage.Requests:FindFirstChild("ClientEffectDirect")
	if not clientEffectDirect then return end

	for _, entity in ipairs(liveFolder:GetChildren()) do
		local entityHRP = entity:FindFirstChild("HumanoidRootPart")

		if entityHRP and entity ~= character and not entity:HasTag("InTacet") then
			if not entityTimestamps[entity.Name] then
				entityTimestamps[entity.Name] = tick()
			elseif tick() - entityTimestamps[entity.Name] >= 1 then
				entityTimestamps[entity.Name] = tick()
			else
				continue
			end

			local effectiveRange = range
			if entity:HasTag("Disguised") then
				effectiveRange = effectiveRange * 0.1
			end

			local dist = (myPos - entityHRP.Position).Magnitude
			if dist < effectiveRange then
				local color = Color3.new(1, 1, 1)

				local hum = entity:FindFirstChildOfClass("Humanoid")
				if hum and not entity:HasTag("NoVisibleDamage") then
					local healthPercent = hum.Health / hum.MaxHealth
					if healthPercent < 0.33 then
						color = Color3.fromRGB(255, 0, 0)
					elseif healthPercent < 0.66 then
						color = Color3.fromRGB(255, 179, 0)
					end
				end

				clientEffectDirect:Fire("sonarsmall", {
					pos = entityHRP.Position,
					col = color
				})
			end
		end
	end
end

local function canDeactivate()
	if not rhythmStartTime then return true end
	return (tick() - rhythmStartTime) >= CONFIG.MIN_DURATION
end

local function stopRhythm()
	if not rhythmActive then return end

	rhythmActive = false
	rhythmStartTime = nil
	pendingStop = false
	debounce = true

	stopAnimation()
	currentSound = nil
	deactivateLighting()
	stopAmbientOverride()

	if pulseLoop then
		task.cancel(pulseLoop)
		pulseLoop = nil
	end

	task.spawn(function()
		task.wait(0.2)
		debounce = false
	end)

	task.spawn(function()
		task.wait(1)
		if rhythmCC then
			rhythmCC.Enabled = false
		end
	end)
end

local function startRhythm()
	if debounce then return end
	if rhythmActive then return end

	rhythmActive = true
	debounce = true
	rhythmStartTime = tick()
	pendingStop = false

	playAnimation()

	task.wait(0.1)
	playSound()

	task.wait(0.2)

	if not isCrouching() then
		rhythmActive = false
		rhythmStartTime = nil
		pendingStop = false
		stopAnimation()

		if currentSound then
			tweenService:Create(currentSound, TweenInfo.new(0.2), { Volume = 0 }):Play()
			task.wait(0.2)
			stopSound()
		end

		debounce = false
		return
	end

	setupRhythmCC()
	activateLighting()
	startAmbientOverride()

	entityTimestamps = {}
	detectEntities()

	pulseLoop = task.spawn(function()
		while rhythmActive do
			task.wait(0.2)
			detectEntities()
		end
	end)

	for _ = 1, 10 do
		task.spawn(createExpandingSonar)
		task.wait(0.1)
	end

	task.wait(0.5)

	task.spawn(function()
		task.wait(0.2)
		debounce = false
	end)
end

local function onKeyPress(input, gameProcessed)
	if gameProcessed then return end
	if not Configuration.expectToggleValue("RhythmSpoofer") then return end
	if hasRhythmTalent() then return end

	local keybind = getRhythmKeybind()
	if input.KeyCode ~= keybind then return end

	if rhythmActive then
		if canDeactivate() then
			stopRhythm()
		else
			pendingStop = true
		end
	else
		if canUseRhythm() then
			startRhythm()
		end
	end
end

local function monitorRhythmCheck()
	if not rhythmActive then return end
	if not Configuration.expectToggleValue("RhythmSpoofer") then
		stopRhythm()
		return
	end

	if canDeactivate() then
		local canUse = canUseRhythm()
		if pendingStop or not canUse then
			stopRhythm()
		end
	end
end

function RhythmSpoofer.init()
	rhythmMaid:add(userInputService.InputBegan:Connect(onKeyPress))
	rhythmMaid:add(runService.Heartbeat:Connect(monitorRhythmCheck))

	rhythmMaid:add(localPlayer.CharacterAdded:Connect(function()
		currentAnimTrack = nil
		currentSound = nil
		stopAmbientOverride(true)
		if rhythmActive then
			stopRhythm()
		end
	end))

	getRhythmKeybind()
end

function RhythmSpoofer.detach()
	if rhythmActive then
		stopRhythm()
	end
	rhythmMaid:clean()

	if rhythmCC then
		rhythmCC:Destroy()
