local oldUnreliableFireServer = nil
local oldNameCall = nil
local oldNewIndex = nil
local oldTick = nil
local oldToString = nil
local oldIndex = nil
local oldPrint = nil
local oldWarn = nil
local oldGetLogHistory = nil
local oldHasEffect = nil
local oldProtectedCall = nil
local oldGetKey = nil

